[
	{
		"src": "28-j\u00e4hriger Koch in San Francisco Mall tot aufgefunden",
		"tgt": "28-Year-Old Chef Found Dead at San Francisco Mall"
	},
	{
		"src": "Ein 28-j\u00e4hriger Koch, der vor kurzem nach San Francisco gezogen ist, wurde im Treppenhaus eines \u00f6rtlichen Einkaufzentrums tot aufgefunden.",
		"tgt": "A 28-year-old chef who had recently moved to San Francisco was found dead in the stairwell of a local mall this week."
	},
	{
		"src": "Der Bruder des Opfers sagte aus, dass er sich niemanden vorstellen kann, der ihm schaden wollen w\u00fcrde, \"Endlich ging es bei ihm wieder bergauf.\"",
		"tgt": "But the victim's brother says he can't think of anyone who would want to hurt him, saying, \"Things were finally going well for him.\""
	},
	{
		"src": "Der am Mittwoch morgen in der Westfield Mall gefundene Leichnam wurde als der 28 Jahre alte Frank Galicia aus San Francisco identifiziert, teilte die gerichtsmedizinische Abteilung in San Francisco mit.",
		"tgt": "The body found at the Westfield Mall Wednesday morning was identified as 28-year-old San Francisco resident Frank Galicia, the San Francisco Medical Examiner's Office said."
	},
	{
		"src": "Das San Francisco Police Department sagte, dass der Tod als Mord eingestuft wurde und die Ermittlungen am Laufen sind.",
		"tgt": "The San Francisco Police Department said the death was ruled a homicide and an investigation is ongoing."
	},
	{
		"src": "Der Bruder des Opfers, Louis Galicia, teilte dem ABS Sender KGO in San Francisco mit, dass Frank, der fr\u00fcher als Koch in Boston gearbeitet hat, vor sechs Monaten seinen Traumjob als Koch im Sons & Daughters Restaurant in San Francisco ergattert hatte.",
		"tgt": "The victim's brother, Louis Galicia, told ABC station KGO in San Francisco that Frank, previously a line cook in Boston, had landed his dream job as line chef at San Francisco's Sons & Daughters restaurant six months ago."
	},
	{
		"src": "Ein Sprecher des Sons & Daughters sagte, dass sie \u00fcber seinen Tod \"schockiert und am Boden zerst\u00f6rt seien\".",
		"tgt": "A spokesperson for Sons & Daughters said they were \"shocked and devastated\" by his death."
	},
	{
		"src": "\"Wir sind ein kleines Team, das wie eine enge Familie arbeitet und wir werden ihn schmerzlich vermissen,\" sagte der Sprecher weiter.",
		"tgt": "\"We are a small team that operates like a close knit family and he will be dearly missed,\" the spokesperson said."
	},
	{
		"src": "Unsere Gedanken und unser Beileid sind in dieser schweren Zeit bei Franks Familie und Freunden.",
		"tgt": "Our thoughts and condolences are with Frank's family and friends at this difficult time."
	},
	{
		"src": "Louis Galicia gab an, dass Frank zun\u00e4chst in Hostels lebte, aber dass, \"die Dinge f\u00fcr ihn endlich bergauf gingen.\"",
		"tgt": "Louis Galicia said Frank initially stayed in hostels, but recently, \"Things were finally going well for him.\""
	},
	{
		"src": "\"Er fand eine Wohnung, er hatte eine Freundin,\" teilte Louis Garcia KGO mit.",
		"tgt": "\"He found an apartment, he was dating a girl,\" Louis Galicia told KGO."
	},
	{
		"src": "Louis Galicia sagte, dass er sich niemanden vorstellen k\u00f6nne, der seinem j\u00fcngeren Bruder schaden wollen w\u00fcrde.",
		"tgt": "Louis Galicia said he could not think of anyone who would want to hurt his younger brother."
	},
	{
		"src": "Er war ein freundlicher Mensch mit einem gro\u00dfen Herzen.",
		"tgt": "He was a kind spirit with a big heart."
	},
	{
		"src": "Seine Art mit seiner Familie zu verbinden war es, uns immer etwas zu kochen, uns das Abendessen zuzubereiten,\" sagte Louis Galicia.",
		"tgt": "His way of connecting with the family was always making us a dish, making us dinner,\" Louis Galicia said."
	},
	{
		"src": "Er wollte nie an irgendeiner Art von Auseinandersetzung teilnehmen.",
		"tgt": "He never wanted to be in any kind of altercation."
	},
	{
		"src": "Er war der Bruder, der mit dem Strom schwamm.",
		"tgt": "He was the brother that went with the flow."
	},
	{
		"src": "\"Bei allem, was in der Welt schief l\u00e4uft, war er dieser ungeschliffene Diamant, der jeden Tag hell leuchtete,\" sagte er.",
		"tgt": "\"With everything else that's going wrong with the world, he was that diamond in the rough that was shining bright every day,\" he said."
	},
	{
		"src": "Jeder, der Informationen zu dem Fall hat, wird gebeten das Hinweistelefon des SFPD unter der Nummer 415-575-4444 anzurufen.",
		"tgt": "Anyone with information is asked to call the SFPD Tip Line at 415-575-4444."
	},
	{
		"src": "Jennifer Aniston: Ich werde immer in Schubladen gesteckt",
		"tgt": "Jennifer Aniston: I'm always pigeonholed"
	},
	{
		"src": "Jennifer Aniston muss nicht immer perfekt oder erfolgreich sein.",
		"tgt": "Jennifer Aniston need not always be perfect or successful."
	},
	{
		"src": "Das hat der Hollywood-Star in einem Interview jetzt unmissverst\u00e4ndlich klar gemacht.",
		"tgt": "That is what the Hollywood star has made abundantly clear in an interview."
	},
	{
		"src": "\"Ich werde immer in Schubladen gesteckt oder bekomme von au\u00dfen Label aufgeklebt, die mit mir und der Realit\u00e4t meist wenig zu tun haben.\"",
		"tgt": "\"I'm always pigeonholed, or labelled by someone who has little, if anything, to do with me and reality.\""
	},
	{
		"src": "\"Ich selbst habe nicht den Wunsch, immer perfekt und erfolgreich zu sein.\"",
		"tgt": "\"Personally, I have no desire to be perfect and successful all the time.\""
	},
	{
		"src": "\"Ehrlich gesagt, sind mir diese Dinge eher schnuppe.\"",
		"tgt": "\"To be honest, I don't really give a damn about things like that.\""
	},
	{
		"src": "Jennifer Aniston (47) kann nur dar\u00fcber lachen, dass sie als \"Miss Perfect\" gilt, wie sie in der aktuellen \"Cosmopolitan\" erkl\u00e4rt.",
		"tgt": "Jennifer Aniston (47) can only laugh that she has been dubbed \"Miss Perfect\" in the current issue of \"Cosmopolitan\"."
	},
	{
		"src": "Am liebsten verbringt die Schauspielerin n\u00e4mlich ihre Zeit zuhause, vorm Fernseher mit lockerem Dutt und mexikanischem Essen, hei\u00dft es in dem Magazin.",
		"tgt": "The actress prefers to spend her time at home in front of the television with her hair in a relaxed bun, eating Mexican food, the magazine reports."
	},
	{
		"src": "Zur Wei\u00dfglut bringe sie die Frage nach dem Kinderwunsch: \"Wir Frauen m\u00fcssen nicht verheiratet sein oder Kinder haben, um vollkommen zu sein\", so der Hollywood-Star.",
		"tgt": "The question of whether she wants children makes her livid: \"We women do not need to be married or have children to feel fulfilled,\" the Hollywood star says."
	},
	{
		"src": "In ihrem neuen Film \"Mother's Day - Liebe ist kein Kinderspiel\" ist Aniston als eine alleinerziehende Mutter zweier S\u00f6hne zu sehen.",
		"tgt": "In her new film, \"Mother's Day - love isn't child's play\", Aniston stars as a single mother with two sons."
	},
	{
		"src": "Der Film l\u00e4uft bei uns ab dem 25. August.",
		"tgt": "The film is released in Germany on 25 August."
	},
	{
		"src": "Golfer Langer erh\u00e4lt die Sportpyramide",
		"tgt": "Golfer Langer is awarded the Sport Pyramid"
	},
	{
		"src": "Seine Erfahrungen auf dem Pferd sind \u00fcberschaubar.",
		"tgt": "His experience on horseback is negligible."
	},
	{
		"src": "Am Ende eines Golfturniers in S\u00fcdafrika suchte Bernhard Langer mit einigen Kollegen ein bisschen Abwechslung mit einem Ausritt am Strand.",
		"tgt": "At the end of a golfing tournament in South Africa, Bernhard Langer and a colleague went for a ride along the beach for a bit of fun."
	},
	{
		"src": "F\u00fcr den 58-J\u00e4hrigen war es eine Premiere.",
		"tgt": "It was a first for the 58-year-old."
	},
	{
		"src": "CHIO: \"Goldene Sportpyramide\" f\u00fcr Bernhard Langer",
		"tgt": "CHIO: \"Golden Sport Pyramid\" for Bernhard Langer"
	},
	{
		"src": "Nach einigen Minuten erinnerten sich die Pferde an ihren Feierabend, sie jagten im schnellen Galopp nach Hause zu den Futtertr\u00f6gen.",
		"tgt": "After a few minutes, the horse decided it wanted to go home, and raced back to its feeding trough at full tilt."
	},
	{
		"src": "Ein Kilometer bei diesem Tempo, ich habe Angst gehabt.",
		"tgt": "After a kilometre at this speed I was scared."
	},
	{
		"src": "\"Es war kein gutes Erlebnis\", sagt Langer.",
		"tgt": "\"It wasn't a good experience,\" said Langer."
	},
	{
		"src": "Und damit endete die Reitkarriere dann auch schon wieder.",
		"tgt": "And with that, his riding career came to an end again."
	},
	{
		"src": "Am Samstag war Deutschlands bester Golfer aller Zeiten - 101 Turniersiege - wieder in der N\u00e4he von Pferden.",
		"tgt": "On Saturday, Germany's best golfer of all time - with 101 tournament wins under his belt - was once again near horses."
	},
	{
		"src": "Er lie\u00df sich mit seiner Familie \u00fcber die Anlage des ALRV f\u00fchren, auf ein Pferd schwang er sich nicht mal zu Fotozwecken.",
		"tgt": "He and his family toured the ALRV grounds, but he did not jump onto a horse for a photo."
	},
	{
		"src": "Langer war das erste Mal in Aachen und damit auch beim CHIO.",
		"tgt": "It was Langer's first time in Aachen, and at CHIO."
	},
	{
		"src": "Der Grund war durchaus \u00fcberzeugend.",
		"tgt": "He had been thoroughly convinced."
	},
	{
		"src": "Die deutsche Sporthilfe \u00fcberreichte dem Mann aus Anhausen im Rahmen einer kleinen Gala die Goldene Sportpyramide.",
		"tgt": "The German Sport Aid foundation awarded the man from Anhausen with the Golden Sport Pyramid at a small gala event."
	},
	{
		"src": "An Auszeichnungen mangelt es dem sympathischen Sportler nicht.",
		"tgt": "The friendly sportsman is not lacking for awards."
	},
	{
		"src": "Bundesverdienstkreuz, Silbernes Lorbeerblatt, Champions-Tour-Player of the year...",
		"tgt": "The Federal Cross of Merit, the Silver Laurel Leaf, Champions Tour Player of the Year..."
	},
	{
		"src": "Selbst die britische Queen hat ihn schon geadelt.",
		"tgt": "Even the British Queen has bestowed an honour upon him."
	},
	{
		"src": "Langer ist der 18. Preistr\u00e4ger der Sportpyramide.",
		"tgt": "Langer is the 18th person to be awarded the Sport Pyramid."
	},
	{
		"src": "In Aachen traf er am Samstag den ersten Preistr\u00e4ger Hans G\u00fcnter Winkler.",
		"tgt": "On Saturday, he met the first person to receive it, Hans G\u00fcnter Winkler, in Aachen."
	},
	{
		"src": "\"Diese Auszeichnung bedeutet mir sehr viel\", sagt Langer, \"denn sie wird nicht nur f\u00fcr sportliche Erfolge, sondern auch f\u00fcr gesellschaftliches Engagement vergeben\".",
		"tgt": "\"This award means a lot to me,\" said Langer, \"because it's not just given for sporting success, but also for social commitment.\""
	},
	{
		"src": "Seit Jahrzehnten f\u00f6rdert Langer den Nachwuchs.",
		"tgt": "Langer has been encouraging up-and-coming talent for years."
	},
	{
		"src": "Und so gab er auch das Preisgeld von 25.000 Euro gleich weiter.",
		"tgt": "And in this vein, he passed the prize money of 25,000 euros on straight away."
	},
	{
		"src": "Mit 15 weiteren herausragenden Sportlern wurde der zweifache US-Masterssieger am Samstag in die \"Hall of Fame des deutschen Sports\" aufgenommen.",
		"tgt": "The two-time US master's champion was inaugurated into the \"Hall of Fame for German Sport\" on Saturday, along with 15 other outstanding sportspeople."
	},
	{
		"src": "Zu den Ausgezeichneten geh\u00f6ren die Leichtathleten Hartwig Gauder und Harald Schmitt, der Turner Eberhard Gienger, die Fechter Cornelia Hanisch, Alexander Pusch und Arnd Schmitt, der Ruderer Peter-Michael Kolbe, Bob-Fahrer Meinhard Nehmer, der Judoka Frank Wieneke, der Springreiter Alwin Schockem\u00f6hle und posthum der Handballer Erhard Wunderlich.",
		"tgt": "Those given the award include track athletes Hartwig Gauder and Harald Schmitt, gymnast Eberhard Gienger, fencers Cornelia Hanisch, Alexander Putsch and Arnd Schmitt, rower Peter-Michael Kolbe, bob-sleigh rider Meinhard Nehmer, judo player Frank Wieneke, show-jumper Alwin Schockem\u00f6hle, and, posthumously, handball player Erhard Wunderlich."
	},
	{
		"src": "Viele dieser Sportlegenden waren am Samstag nach Aachen gekommen.",
		"tgt": "Many of these sport legends came to Aachen on Saturday."
	},
	{
		"src": "Nach dem offiziellen Teil wanderte die illustre Gesellschaft ins Springstadion, wo der Lavazza-Preis lief.",
		"tgt": "After the official part, the illustrious gathering wandered to the show-jumping stadium, where the Lavazza Prize was underway."
	},
	{
		"src": "Bernhard Langer hielt Abstand zu den gro\u00dfen Tieren.",
		"tgt": "Bernhard Langer kept his distance from the large animals."
	},
	{
		"src": "Clintons und Trumps Wirtschaftspolitik im Vergleich: It's all about the money",
		"tgt": "Comparing Clinton's and Trump's economic policies: It's all about the money"
	},
	{
		"src": "In Infrastruktur investieren und das Handelsabkommen TTP verhindern - das wollen sowohl Clinton als auch Trump.",
		"tgt": "Both Clinton and Trump want to invest in infrastructure and prevent the TTP trade agreement."
	},
	{
		"src": "Uneins sind sich die beiden US-Pr\u00e4sidentschaftsbewerber jedoch bei der Steuer- und Energiepolitik sowie in einer Grundsatzfrage.",
		"tgt": "But the two candidates for the US presidency disagree on taxes and energy policies, as well as on one fundamental issue."
	},
	{
		"src": "Den Unterschieden in der Wirtschaftspolitik zwischen Donald Trump und Hillary Clinton liegt ein grunds\u00e4tzlicher, eher philosophischer Unterschied zugrunde.",
		"tgt": "There is a fundamental philosophical reason for the differences between Donald Trump's and Hillary Clinton's economic policies."
	},
	{
		"src": "Der, \u00fcber die Rolle des Staates.",
		"tgt": "This is the role of the state."
	},
	{
		"src": "Trump will die im Zweifel eher klein halten und warnt davor, wie der Staat der Wirtschaft schaden kann - mit Steuern und Regulierungen.",
		"tgt": "If in doubt, Trump wants the state's role to be minor, and warns of how the state can damage the economy with taxes and regulations."
	},
	{
		"src": "Clinton wolle die Wirtschaft zu Tode besteuern und zu Tode regulieren, sagt er.",
		"tgt": "Clinton wants to lead the economy to its death and regulate it to its death, he says."
	},
	{
		"src": "Er selber dagegen w\u00e4re ganz anders, behauptet Trump.",
		"tgt": "He would do things totally differently, Trump says."
	},
	{
		"src": "Er werde Regulierungen massiv zur\u00fcckfahren, und er macht sich f\u00fcr eine weitreichende Steuerreform mit niedrigeren Steuers\u00e4tzen stark - f\u00fcr Privatleute und f\u00fcr Unternehmen.",
		"tgt": "He would repeal regulations, and lead a wide-reaching tax reform with low rates for private individuals and companies."
	},
	{
		"src": "Clinton dagegen sagt: Der Staat hat bestimmte Aufgaben zu erf\u00fcllen, er hat Benachteiligten Chancen zu er\u00f6ffnen und braucht daf\u00fcr Geld.",
		"tgt": "Conversely, Clinton says that the state has particular tasks to fulfil, giving disadvantaged people opportunities - and it needs money to do so."
	},
	{
		"src": "Deshalb w\u00fcrden die Steuern f\u00fcr die Reichen erh\u00f6ht, sagt sie.",
		"tgt": "This would increase taxes for the rich, she says."
	},
	{
		"src": "Interessanterweise sind sich beide sehr nahe beim Thema Infrastruktur.",
		"tgt": "Interestingly, they have similar views on infrastructure."
	},
	{
		"src": "In die m\u00fcsse investiert werden, sagen Trump und Clinton fast wortgleich.",
		"tgt": "There has to be investment in infrastructure, Trump and Clinton say almost verbatim."
	},
	{
		"src": "Die demokratische Bewerberin k\u00fcndigt gar die gr\u00f6\u00dfte Investition in neue Arbeitspl\u00e4tze seit dem Zweiten Weltkrieg an.",
		"tgt": "The Democratic candidate has even announced the largest investment in jobs since the Second World War."
	},
	{
		"src": "Staatliche Investitionsprogramme in die Infrastruktur sind klassische demokratische Politik und werden etwa vom staatskritischen Teaparty-Fl\u00fcgel der Republikaner strikt abgelehnt.",
		"tgt": "State programs investing in infrastructure are classic Democrat policies, and are rejected by the tea party wing of the Republican party, which is critical of the state."
	},
	{
		"src": "Auf Trump k\u00f6nnten also noch parteiinterne Diskussionen zukommen.",
		"tgt": "Consequently, Trump could lead to discussions within the party."
	},
	{
		"src": "Deutlicher sind die Unterschiede in der Energie- und Klimapolitik.",
		"tgt": "There are clearer differences to be seen in terms of energy and climate policies."
	},
	{
		"src": "Trump will Kohlekraftwerke bauen und die Kohlef\u00f6rderung in den USA wieder hochfahren.",
		"tgt": "Trump wants to build coal-fired power stations and bring coal production in the USA back up."
	},
	{
		"src": "\u00d6lf\u00f6rderung soll auch in bislang gesch\u00fctzten Gebieten m\u00f6glich sein, das Pariser Klimaschutzabkommen will er aufk\u00fcndigen.",
		"tgt": "Drilling for oil should be permitted in protected areas, and he wants to withdraw from the Paris Climate Change Treaty."
	},
	{
		"src": "Clinton dagegen will mit ihrem Investitionsprogramm ausdr\u00fccklich die Erneuerbaren Energien ausbauen und fordert: \"Ein Land wird die Supermacht der sauberen Energien werden und Millionen Jobs schaffen.\"",
		"tgt": "On the other hand, Clinton wants to use her investment program to extend renewable energies, saying: \"One country will become the superpower of renewable energies, and create millions of jobs.\""
	},
	{
		"src": "\"Es wird wohl entweder China, Deutschland oder Amerika sein - ich will, dass wir es sind.\"",
		"tgt": "\"It will either be China, Germany or America - and I want it to be us.\""
	},
	{
		"src": "Doch nicht nur bei der Infrastruktur - auch bei internationalen Handelsabkommen sind die beiden Konkurrenten nicht allzu weit voneinander entfernt.",
		"tgt": "But it's not just infrastructure that sees the two candidates taking a rather similar stance - they agree in terms of international trade agreements as well."
	},
	{
		"src": "TPP, das transpazifische Handelsabkommen, wollen beide nicht unterzeichnen.",
		"tgt": "Neither want to sign TTP, the trans-Pacific trade agreement."
	},
	{
		"src": "Gleichzeitig wollen beide aber die USA nicht vom internationalen Handel isolieren - sondern einfach nur amerikanische Jobs besser sch\u00fctzen.",
		"tgt": "At the same time, neither want to cut the USA off from international trade - they just want to protect American jobs better."
	},
	{
		"src": "Die sollen dann auch besser bezahlt werden, fordert etwa Clinton.",
		"tgt": "They should then also be better paid, Clinton demands."
	},
	{
		"src": "Der derzeitige Mindestlohn von 7,25 US-Dollar sei ein Hungerlohn.",
		"tgt": "The current minimum wage of 7.25 US dollars is a pittance, she says."
	},
	{
		"src": "Ihn will sie auf 15 Dollar pro Stunde erh\u00f6hen.",
		"tgt": "She wants to raise it to 15 dollars an hour."
	},
	{
		"src": "Was Trump in dieser Frage tun will, ist nicht ganz klar: Einmal sagt er: Der Mindestlohn muss rauf, dann sagt er, er d\u00fcrfe nicht ver\u00e4ndert werden.",
		"tgt": "It is not quite clear what Trump wants to do on this score: Once he said that the minimum wage had to be raised, then he said it should stay the same."
	},
	{
		"src": "Doch die gro\u00dfe Diskussion der kommenden Monate d\u00fcrfte sich wohl eher um die Steuerpolitik der beiden Lager entwickeln.",
		"tgt": "But the big discussion of the months to come will likely revolve around both parties' tax policies."
	},
	{
		"src": "Auf der einen Seite steht Trump, der die Wirtschaft und die B\u00fcrger entlasten will, um das Wachstum anzukurbeln.",
		"tgt": "Trump is on one side, wanting to relieve the burden on the economy and citizens to boost growth."
	},
	{
		"src": "Seine Kritiker halten ihm vor, damit w\u00fcrde das Haushaltsdefizit nur noch gr\u00f6\u00dfer.",
		"tgt": "His critics state that this will just increase the budgetary deficit."
	},
	{
		"src": "Auf der anderen Seite steht Clinton, die zumindest von den Reichen verlangen will, dass sie mehr Steuern zahlen, und deren Kritiker sagen: Mehr Steuern sind auch nicht die L\u00f6sung.",
		"tgt": "Clinton is on the opposite side: as a minimum, she wants the rich to pay more taxes, and her critics say that more taxes are not the solution either."
	},
	{
		"src": "Flucht: \"Jede gefl\u00fcchtete Frau hat Erfahrungen mit sexueller Gewalt\"",
		"tgt": "Seeking refuge: \"Every refugee woman has dealt with sexual violence\""
	},
	{
		"src": "Sexuelle Gewalt geh\u00f6rt f\u00fcr Frauen, die alleine fliehen, fast schon zum Alltag.",
		"tgt": "For women fleeing a country on their own, sexual violence is almost part of daily life."
	},
	{
		"src": "Wenn sie in Deutschland ankommen, sind sie oft traumatisiert.",
		"tgt": "When they arrive in Germany, they are often traumatised."
	},
	{
		"src": "Ein Haus bietet Zuflucht.",
		"tgt": "One house offers refuge."
	},
	{
		"src": "In einer gro\u00dfen K\u00fcche sitzen vier Frauen.",
		"tgt": "Four women are sitting in a large kitchen."
	},
	{
		"src": "Jede hat ein Baby dabei, das h\u00f6chstens ein Jahr alt ist.",
		"tgt": "Every one of them has a baby with them, the oldest of which is one year old."
	},
	{
		"src": "Eine hat ihren kleinen Sohn in den Arm gelegt.",
		"tgt": "One woman holds her little son in her arms."
	},
	{
		"src": "Er guckt mit gro\u00dfen Augen neugierig in den Raum.",
		"tgt": "He looks around the room inquisitively, his eyes wide."
	},
	{
		"src": "Seine Mutter starrt auf die Tischplatte.",
		"tgt": "His mother stares at the tabletop."
	},
	{
		"src": "Bis sie merkt, dass sie beobachtet wird.",
		"tgt": "Until she realises she's being watched."
	},
	{
		"src": "Sie l\u00e4chelt kurz und k\u00fcsst den Kleinen.",
		"tgt": "She smiles briefly and kisses the child."
	},
	{
		"src": "Die Szene wirkt normal.",
		"tgt": "The scene looks normal."
	},
	{
		"src": "Bis man mit Katrin Bahr spricht.",
		"tgt": "Until you start talking to Katrin Bahr."
	},
	{
		"src": "Sie ist Bereichs-Gesch\u00e4ftsf\u00fchrerin von Condrobs, einem Tr\u00e4ger f\u00fcr soziale Hilfsangebote in Bayern, und besch\u00e4ftigt sich unter anderem mit dem Thema Frauen auf der Flucht.",
		"tgt": "She is the field manager for Condrobs, a provider of social assistance within Bavaria. One of the issues she deals with is refugee women."
	},
	{
		"src": "Die vier Frauen in der K\u00fcche sind Gefl\u00fcchtete.",
		"tgt": "The four women in the kitchen are refugees."
	},
	{
		"src": "Sie leben im M\u00fcnchner Norden in einer der wenigen dezentralen Unterk\u00fcnfte f\u00fcr alleingefl\u00fcchtete Frauen und ihre Kinder in Bayern.",
		"tgt": "They live in the north of Munich, in one of the few decentralised accommodation centres in Bavaria for refugee women and their children who have made the journey alone."
	},
	{
		"src": "Im Januar hat Condrobs die Einrichtung zusammen mit Pro Familia und der M\u00fcnchner Frauenhilfe aufgemacht.",
		"tgt": "Condrobs opened the centre in January, in collaboration with Pro Familia and the Munich Women's Help organisation."
	},
	{
		"src": "Unl\u00e4ngst wurde sie offiziell er\u00f6ffnet.",
		"tgt": "It recently had its official opening."
	},
	{
		"src": "60 Personen leben dort - etwa 40 Frauen und 20 Kinder.",
		"tgt": "60 people live there - around 40 women and 20 children."
	},
	{
		"src": "M\u00e4nner gibt es keine - auch nicht als Besucher.",
		"tgt": "There are no men - not even male visitors."
	},
	{
		"src": "Die Ausnahme ist ein Wachmann vor der T\u00fcr.",
		"tgt": "The exception is a bodyguard on the door."
	},
	{
		"src": "\"Es ist nicht \u00fcbertrieben zu sagen: Jede Frau, die hier ankommt, hat auf ihrer Flucht Erfahrungen mit sexueller Gewalt gemacht\", sagt Bahr.",
		"tgt": "\"I'm not exaggerating when I say that every woman who arrives here has dealt with sexual violence on her way to find refuge,\" said Bahr."
	},
	{
		"src": "\"M\u00e4nner fliehen wegen Kriegen, weil sie politisch verfolgt werden, weil ihnen Folter oder der Tod drohen oder weil ihre Familien sie als Hoffnungstr\u00e4ger nach Europa schicken\", erz\u00e4hlt sie.",
		"tgt": "\"Men flee because of war, because they are politically persecuted, because they are threatened with torture or death, or because their families pin their hopes on them and send them to Europe,\" she explains."
	},
	{
		"src": "Bei Frauen \u00fcberwiegen andere Gr\u00fcnde f\u00fcr die Flucht: \"Viele stehlen sich heimlich davon, weil sie keinen anderen Ausweg sehen\".",
		"tgt": "When women flee, other reasons are in the foreground: \"Many women sneak away secretly, because they see no other way out\"."
	},
	{
		"src": "In ihrer Heimat haben sie Erfahrung mit sexueller Gewalt, Zwangsehen, Ehrenmorden, Sklaverei oder Zwangsprostitution gemacht.",
		"tgt": "In their home countries, they experienced sexual violence, forced marriage, honour killings, slavery or forced prostitution."
	},
	{
		"src": "Das treibt sie fort.",
		"tgt": "That propels them forward."
	},
	{
		"src": "Auf der Flucht geht das weiter.",
		"tgt": "And it continues even while they're on the run."
	},
	{
		"src": "\"Dass Schlepper zum Beispiel f\u00fcr eine Flasche Wasser eine sexuelle Handlung fordern, ist keine Seltenheit\", sagt Bahr.",
		"tgt": "\"It is not a rare occurrence that traffickers request a sexual act in exchange for a bottle of water, for example,\" says Bahr."
	},
	{
		"src": "Und die Frauen sind alleine, sie werden nicht von ihren Familien gesch\u00fctzt.",
		"tgt": "And the woman are alone, unprotected by their families."
	},
	{
		"src": "Wer glaube, dass das ende, sobald sie in Deutschland ank\u00e4men, irre, erz\u00e4hlt Bahr.",
		"tgt": "If you think that this stops as soon as they arrive in Germany, you'd be wrong, says Bahr."
	},
	{
		"src": "Auch hier w\u00fcrden alleinstehende Frauen in Fl\u00fcchtlingsunterk\u00fcnften oft als minderwertig betrachtet und schlimmstenfalls missbraucht.",
		"tgt": "Even in Germany, lone women are often seen as inferior in refugee accommodation, and, in the worst cases, they are abused."
	},
	{
		"src": "Das f\u00fchrt dazu, dass etwa 90 Prozent der Frauen, die in der Unterkunft im M\u00fcnchner Norden wohnen, traumatisiert sind, sch\u00e4tzt sie.",
		"tgt": "As a result, around 90 percent of the women living in accommodation in the north of Munich are traumatised, she estimates."
	},
	{
		"src": "\"Einige der Kinder sind sicher nicht freiwillig entstanden\".",
		"tgt": "\"Some of the children were certainly not conceived with the woman's consent\"."
	},
	{
		"src": "Viele Frauen seien es so gewohnt, dass sie nichts sagen.",
		"tgt": "Many women are so used to it that they do not say anything, she says."
	},
	{
		"src": "\"Oder sie trauen sich nicht, offen \u00fcber das Erlebte zu sprechen, weil die Scham zu gro\u00df ist\".",
		"tgt": "\"Or they can't bring themselves to talk about what they experienced because they are too ashamed\"."
	},
	{
		"src": "Da sie sich oft nicht zu helfen w\u00fcssten, brauche es mehr Unterk\u00fcnfte nur f\u00fcr sie, fordert Bahr.",
		"tgt": "Because they often don't know how to get help, there needs to be more accommodation just for them, says Bahr."
	},
	{
		"src": "In Bayern sind die sieben Bezirksregierungen f\u00fcr die Unterbringung von Fl\u00fcchtlingen zust\u00e4ndig.",
		"tgt": "In Bavaria, the seven district governments are responsible for providing accommodation for refugees."
	},
	{
		"src": "Auf die Frage, ob sie von einem \u00e4hnlichen Projekt wie in M\u00fcnchen in ihrem Zust\u00e4ndigkeitsbereich w\u00fcssten, antworten einige mit Nein.",
		"tgt": "When asked if they knew of projects like the one in Munich operating within the areas they covered, some answered with \"no\"."
	},
	{
		"src": "In der Oberpfalz und Oberfranken etwa gibt es so etwas in Unterk\u00fcnften der Regierungen nicht.",
		"tgt": "In Upper Palatinate and Upper Franconia regions, for example, there is no similar accommodation offered by the government."
	},
	{
		"src": "Auch in Schwaben werden allein gefl\u00fcchtete Frauen nicht getrennt untergebracht, sagt Karl-Heinz Meyer, Pressesprecher der Regierung.",
		"tgt": "Even in Swabia, women who come as lone refugees are not given separate accommodation, says Karl-Heinz Meyer, press spokesperson for the region."
	},
	{
		"src": "In Oberbayern, Unter- und Mittelfranken gibt es in manchen Gemeinschaftsunterk\u00fcnften Stockwerke oder eigene H\u00e4user nur f\u00fcr alleinstehende Frauen und deren Kinder.",
		"tgt": "In Upper Bavaria, Lower Franconia and Middle Franconia, floors, or individual houses, are set aside in some shared accommodation for lone women and their children."
	},
	{
		"src": "Die Ausnahme ist Niederbayern, dort gibt es zwei zentrale Unterk\u00fcnfte ausschlie\u00dflich f\u00fcr Frauen.",
		"tgt": "The exception is Lower Bavaria: there, there are two central accommodation centres exclusively for women."
	},
	{
		"src": "Auch der Ausschuss \"Rechte der Frau und Gleichstellung der Geschlechter\" im Europaparlament fordert, dass Frauen getrennt von M\u00e4nnern untergebracht werden m\u00fcssen.",
		"tgt": "Even the European Parliament's Committee on \"Women's Rights and Gender Equality\" stresses that women must be provided with accommodation separate from that of the men."
	},
	{
		"src": "In einer Studie, die f\u00fcr den Ausschuss ver\u00f6ffentlicht wurde, hei\u00dft es: \"Es ist sehr wichtig, dass M\u00e4nner und Frauen getrennt beherbergt werden.\"",
		"tgt": "In a study published on behalf of the Committee, it was stated that \"it is very important that men and women are given separate accommodation.\""
	},
	{
		"src": "\"Fehlt die Privatsph\u00e4re oder werden M\u00e4nner und Frauen zusammen untergebracht, kann es zu - fortw\u00e4hrender - Gewalt gegen Frauen kommen\".",
		"tgt": "\"If there is a lack of private space, or if men and women are provided with accommodation together, this can result in (perpetual) violence against women\"."
	},
	{
		"src": "Vor allem die Waschr\u00e4ume sollten getrennt und f\u00fcr Frauen leicht zug\u00e4nglich sein, steht in der Studie.",
		"tgt": "Washing facilities, above all, should be separate, and easily accessible for women, according to the study."
	},
	{
		"src": "Wie sehr die Frauen dieses Schutzbed\u00fcrfnis versp\u00fcren, kann man am Andrang ablesen, den es auf das Haus in M\u00fcnchen gibt.",
		"tgt": "The extent to which women need this protection can be seen in the sheer number of people interested in the house in Munich."
	},
	{
		"src": "\"Seit sich herumgesprochen hat, dass es uns gibt, haben wir eine lange Warteliste\", sagt Bahr.",
		"tgt": "\"Since word has got around that we exist, we have developed a long waiting list,\" says Bahr."
	},
	{
		"src": "Man k\u00f6nnte leicht ein zweites Haus aufmachen.",
		"tgt": "It would be easy to open a second house."
	},
	{
		"src": "Assistenz\u00e4rzte streiken: Forderungen nach neuen Arbeitskampfma\u00dfnahmen",
		"tgt": "Junior doctors strike: Calls for fresh industrial action"
	},
	{
		"src": "Stellvertreter der Assistenz\u00e4rzte haben ihre Gewerkschaft dazu aufgerufen, neue Arbeitskampfma\u00dfnahmen bei ihren Streitigkeiten bez\u00fcglich eines neuen Vertrages zu genehmigen.",
		"tgt": "Representatives of junior doctors have called on their union to authorise fresh industrial action in their dispute about a new contract."
	},
	{
		"src": "Das Junior Doctors Committee (JDC) der British Medical Association (BMA) hat seinen gesamten Rat gefordert, ab Anfang September mehr Arbeitskampfma\u00dfnahmen zu genehmigen.",
		"tgt": "The Junior Doctors Committee (JDC) of the British Medical Association (BMA) is to ask its full council to back more industrial action from early September."
	},
	{
		"src": "Der JDC sagte aus, dass es Minister verabs\u00e4umt h\u00e4tten, auf die Sorgen bez\u00fcglich des Vertrages einzugehen.",
		"tgt": "The JDC says ministers have failed to address concerns about the contract."
	},
	{
		"src": "Assistenz\u00e4rzte und Medizinstudenten haben im Juli \u00fcber die Ablehnung eines Vertrages abgestimmt, der mit der BMA vereinbart wurde.",
		"tgt": "Junior doctors and medical students voted in July to reject a contract deal agreed with the BMA."
	},
	{
		"src": "Er wurde von 58 % seiner Mitglieder abgelehnt, die bei den Wahlen abgestimmt haben.",
		"tgt": "It was rejected by 58% of its members who voted in the ballot."
	},
	{
		"src": "In einem Brief an die Mitglieder, der am Donnerstag abend auf Twitter ver\u00f6ffentlicht wurde, sagte die Vorsitzende des JDC Ellen McCourt, dass die Regierung \"beharrlich ruhig\" zu Problemen geblieben w\u00e4re, was dazu f\u00fchrte, dass der Vertrag abgelehnt wurde.",
		"tgt": "In a letter to members released on Twitter on Thursday night, the JDC's chair Ellen McCourt said the government had remained \"persistently silent\" on issues which, she said, had resulted in the contract being rejected."
	},
	{
		"src": "Sie sagte:\"In Anbetracht dessen hat der JDC Vorstand abgestimmt, den vorgeschlagenen neuen Vertrag vollst\u00e4ndig abzulehnen und offizielle Neuverhandlungen zu all Euren Sorgen angefordert.\"",
		"tgt": "She said: \"In light of this, the JDC Executive has voted to reject the proposed new contract in full and to call for formal re-negotiations on all of your concerns.\""
	},
	{
		"src": "Als Antwort auf das Schweigen der Regierung hat der JDC Vorstand heute einen formalen Antrag auf ein spezielles Treffen des BMA Rates gestellt, um ein laufendes Programm eskalierender Arbeitskampfma\u00dfnahmen, das Anfang September beginnt, zu genehmigen.",
		"tgt": "In response to the government's silence, JDC exec has today made a formal request for a special meeting of BMA Council to authorise a rolling programme of escalated industrial action beginning in early September."
	},
	{
		"src": "Die Streitigkeiten f\u00fchrten dazu, dass Assistenz\u00e4rzte dieses Jahr sechsmal streikten, die ersten Gesamtausf\u00e4lle in der Geschichte des NHS.",
		"tgt": "The dispute has led to junior doctors taking part in six strikes this year, including the first all-out stoppages in the history of the NHS."
	},
	{
		"src": "Der Leiter der BMA Assistenz\u00e4rzte Dr. Johann Malawana trat nach der Wahl zur Ablehnung der vereinbarten Vertragsbedingungen, die von der BMA empfohlen worden waren, zur\u00fcck.",
		"tgt": "The BMA's junior doctor leader, Dr Johann Malawana, resigned following the vote to reject the negotiated terms of the contract, which the BMA had recommended."
	},
	{
		"src": "Er teilte BMA Mitgliedern w\u00e4hrend der Sitzungen, die noch vor der Abstimmung durch 54.000 Assistenz\u00e4rzte und Medizinstudenten stattfanden, mit, dass der Vertrag vorteilhaft sei und angenommen werden sollte.",
		"tgt": "He had told BMA members the deal was a good one that should be accepted, during meetings ahead of the poll of 54,000 junior doctors and medical students."
	},
	{
		"src": "Nach der Abstimmung sagte der Gesundheitsminister Jeremy Hunt, dass der Vertrag f\u00fcr \u00c4rzte in England zwangsweise eingef\u00fchrt werden w\u00fcrde.",
		"tgt": "Following the vote, Health Secretary Jeremy Hunt said the contract would be imposed on medics in England."
	},
	{
		"src": "Russland und T\u00fcrkei: Eine \"Allianz von Au\u00dfenseitern\"?",
		"tgt": "Russia and Turkey: An 'alliance of misfits'?"
	},
	{
		"src": "Es war eine Geste, die eine Krise beendete.",
		"tgt": "It was a gesture that ended a crisis."
	},
	{
		"src": "Die Anf\u00fchrer Russlands und der T\u00fcrkei trafen sich am Dienstag, um sich die H\u00e4nde zu geben und ein offizielles Ende des acht Monate lang andauernden Krieges der Worte und wirtschaftlichen Sanktionen zu verk\u00fcnden.",
		"tgt": "The leaders of Russia and Turkey met on Tuesday to shake hands and declare a formal end to an eight-month long war of words and economic sanctions."
	},
	{
		"src": "Aber als Vladimir Putin seinen t\u00fcrkischen Gegenspieler im vergoldeten Saal des St. Petersburger Palastes in Empfang nimmt, kann ich mich nicht des Eindrucks verwehren, dass Ankara diese Vers\u00f6hnung am meisten will.",
		"tgt": "But, as Vladimir Putin greeted his Turkish counterpart in the gilded hall of a St. Petersburg palace, I got the distinct impression that Ankara wants this reconciliation the most."
	},
	{
		"src": "Es gab den Handschlag, ja.",
		"tgt": "There was the handshake, yes."
	},
	{
		"src": "Aber Putins L\u00e4cheln wirkte schmallippig und er strahlte kaum W\u00e4rme aus, selbst f\u00fcr seine zur\u00fcckhaltenden Verh\u00e4ltnisse.",
		"tgt": "But Mr Putin's smile looked thin and he was hardly oozing warmth even by his own restrained standards."
	},
	{
		"src": "Recep Tayyip Erdogan hingegen sprach wiederholt von seinem \"lieben Freund\" Putin - laut einem Bericht ganze f\u00fcnf Male.",
		"tgt": "Recep Tayyip Erdogan by contrast talked repeatedly of his \"dear friend\" Mr Putin - five times, according to one report."
	},
	{
		"src": "Ich konnte es nicht mehr z\u00e4hlen.",
		"tgt": "I lost count."
	},
	{
		"src": "Er versprach auch, dass die Beziehungen zu Russland nicht nur zu ihrem alten Niveau vor der Krise zur\u00fcckkehren w\u00fcrden, sondern sich sogar noch verbessern werden.",
		"tgt": "He also pledged that relations with Russia would return not just to their pre-crisis level, but even higher."
	},
	{
		"src": "Am n\u00e4chsten Tag beschrieb eine Zeitung, dass sich Erdogan so benommen h\u00e4tte, als w\u00e4re nie etwas Schlimmes geschehen.",
		"tgt": "The next day one newspaper here described Mr Erdogan as acting as if nothing bad had ever happened."
	},
	{
		"src": "Mir schien sein Enthusiasmus eher das Gegenteil anzudeuten.",
		"tgt": "To me, his enthusiasm implied the opposite."
	},
	{
		"src": "Aber eine von Putin ausstrahlende, nachhaltige K\u00fchle zeigte, dass der Staatschef Russlands nichts vergessen hatte.",
		"tgt": "But a lingering coolness emanating from Mr Putin showed that Russia's leader has forgotten nothing."
	},
	{
		"src": "Vielmehr war die Ursache der Krise das Erste, was er in seinen Einf\u00fchrungsworten erw\u00e4hnte: der Abschuss eines russischen Kampfflugzeugs an der syrischen Grenze durch die T\u00fcrkei.",
		"tgt": "In fact, the cause of the crisis was the first thing he mentioned in his opening comments: Turkey's shooting down of a Russian fighter plane on the Syrian border."
	},
	{
		"src": "Moskaus Reaktion zu der Zeit war wutentbrannt.",
		"tgt": "Moscow's reaction at the time was furious."
	},
	{
		"src": "Putin teilte aus und beschuldigte Ankara, Russland in den R\u00fccken gefallen zu sein.",
		"tgt": "Mr Putin lashed out, accusing Ankara of stabbing Moscow in the back."
	},
	{
		"src": "Das Vergehen war sogar noch gr\u00f6\u00dfer, da es von einem vermeintlichen Freund begangen wurde.",
		"tgt": "The offence was even greater, coming from a supposed friend."
	},
	{
		"src": "Das Vetrauen wieder aufzubauen wird schwierig, wenn nicht sogar unm\u00f6glich werden.",
		"tgt": "Rebuilding real trust will be hard, perhaps impossible."
	},
	{
		"src": "Die \u00f6ffentliche Meinung in Russland hat sich seit November gewandelt.",
		"tgt": "Russian public opinion has also turned since November."
	},
	{
		"src": "Monate lang f\u00fchrten die staatlich kontrollierten Medien einen heftigen, uneingeschr\u00e4nkten Angriff auf Ankara aus.",
		"tgt": "For months, state-controlled media conducted a staggering, all-out offensive against Ankara."
	},
	{
		"src": "Auf einmal schien es, als w\u00fcrden die T\u00fcrken f\u00fcr alles die Schuld tragen.",
		"tgt": "All of a sudden, it seemed like Turks were to blame for everything."
	},
	{
		"src": "Am ernsthaftesten waren die Anschuldigungen von leitenden Beamten, dass Erdogans eigene Familie vom illegalen \u00d6lhandel in Gebieten Syriens profitiert h\u00e4tte, die vom sogenannten Islamischen Staat kontrolliert werden.",
		"tgt": "Most serious were accusations from top officials that Mr Erdogan's own family has profited from an illegal trade in oil from areas of Syria controlled by the so-called Islamic State."
	},
	{
		"src": "Er hat dies vehement bestritten.",
		"tgt": "He's denied that emphatically."
	},
	{
		"src": "Aber in St.Petersburg lautete die offizielle Botschaft, dass es Zeit sei, nach vorne zu blicken.",
		"tgt": "But in St. Petersburg came the official message that it's time to move on."
	},
	{
		"src": "Schlie\u00dflich fand dieses Treffen nur deshalb statt, weil Putin vom Pr\u00e4sidenten Erdogan die Entschuldigung erhielt, die er h\u00f6ren wollte.",
		"tgt": "After all, this meeting only happened because Mr Putin got the apology he demanded from President Erdogan."
	},
	{
		"src": "Russland konnte eine Art Sieg verbuchen.",
		"tgt": "Russia could claim a victory of sorts."
	},
	{
		"src": "F\u00fcr Ankara liegen die Vorteile eines Waffenstillstands klar auf der Hand.",
		"tgt": "For Ankara the benefits of calling a truce are clear."
	},
	{
		"src": "Erdogan ben\u00f6tigt in erster Linie alle Freunde, die er bekommen kann, nachdem er letzten Monat bei einem gescheiterten Staatsstreich fast seines Amtes enthoben wurde.",
		"tgt": "First and foremost, Erdogan needs all the friends he can get after he was nearly ousted from power last month in a failed coup."
	},
	{
		"src": "Wiederholte Terrorangriffe auf die T\u00fcrkei haben ihn ebenfalls ersch\u00fcttert.",
		"tgt": "Repeat terror attacks on Turkey have clearly shaken him too."
	},
	{
		"src": "Aber es gibt auch wirtschaftliche Motive.",
		"tgt": "There is also an economic motive."
	},
	{
		"src": "Russische Sanktionen haben die T\u00fcrkei hart getroffen - insbesondere das Verbot von Charterfl\u00fcgen, die jedes Jahr \u00fcblicherweise mehrere Millionen russische Touristen an die t\u00fcrkische K\u00fcste bringen.",
		"tgt": "Russian sanctions have hit hard - particularly the ban on charter flights, which usually carry several million Russian tourists to the Turkish coast each year."
	},
	{
		"src": "Die Anzahl ist um fast 90 % zur\u00fcckgegangen.",
		"tgt": "The number has slumped by almost 90%."
	},
	{
		"src": "In Russland werden Reiseveranstalter und Chartergesellschaften erleichtert sein, wenn die Fl\u00fcge wieder aufgenommen werden.",
		"tgt": "As for Russia, tour operators and charter companies here will certainly be relieved when flights eventually resume."
	},
	{
		"src": "Sie z\u00e4hlen auf einen sp\u00e4tsaisonalen Ansturm ans Mittelmeer.",
		"tgt": "They're banking on a late-season rush to the Mediterranean."
	},
	{
		"src": "Diese Woche prognostizierte das Staatsfernsehen billigeres Obst und Gem\u00fcse, sobald die t\u00fcrkischen Agrarimporte wieder erlaubt werden.",
		"tgt": "And even this week, state TV has been predicting cheaper fruit and vegetables once Turkish agricultural imports are permitted again."
	},
	{
		"src": "Ein Bericht in Vedemosti formulierte es folgenderma\u00dfen: \"Touristen dort lang, Tomaten hier lang.\"",
		"tgt": "\"Tourists that way, tomatoes back here,\" as a report in Vedemosti newspaper phrased it."
	},
	{
		"src": "Aber der Besuch hatte einen zus\u00e4tzlichen politischen Wert f\u00fcr Moskau.",
		"tgt": "But the visit also had additional political value for Moscow."
	},
	{
		"src": "Ankara ist auf den Westen w\u00fctend, da es dessen Reaktion auf die versuchte Macht\u00fcbernahme als schwache Antwort betrachtet.",
		"tgt": "Ankara is angry with the West for what it considers a weak response to the attempted takeover."
	},
	{
		"src": "Dazu kommen der anhaltende Groll \u00fcber das Schneckentempo der EU-Beitrittsverhandlungen und Putin - der erpicht darauf ist, aus der k\u00fchlen Stimmung Nutzen zu ziehen und die Beziehung der T\u00fcrkei zum Westen zu verringern.",
		"tgt": "Add to that its long-standing grudge at the snail's pace of talks to join the EU and step in Mr Putin - who is keen to capitalise on the chill and chip away at Turkey's ties with the West."
	},
	{
		"src": "Der russische Staatschef gewann in Ankara mit Sicherheit einen Bonus daf\u00fcr, dass er nach dem versuchten Staatsstreich Unterst\u00fctzung f\u00fcr die gew\u00e4hlten Staatsorgane forderte.",
		"tgt": "The Russian leader certainly won bonus points with Ankara for calling in support of the elected authorities after the attempted coup."
	},
	{
		"src": "Das ist f\u00fcr Moskau wohlgemerkt eine Selbstverst\u00e4ndlichkeit, das selbst eine tiefsitzende Angst vor Regimewechseln hat.",
		"tgt": "Mind you, that's a given for Moscow which has its own deep-seated fear of regime change."
	},
	{
		"src": "Das Gipfeltreffen in diesem glanzvollen Palast am Meer erm\u00f6glichte es Russland und der T\u00fcrkei, eine, wie es mir ein Analytiker einst beschrieb, \"Allianz von Au\u00dfenseitern\" darzustellen: zwei L\u00e4nder, die sich vom Westen versto\u00dfen und schlecht behandelt f\u00fchlen und sich nun verb\u00fcnden.",
		"tgt": "So the summit at this glitzy, seaside palace allowed Russia and Turkey to present what one analyst described to me as an \"alliance of misfits\": two countries that feel rejected and mistreated by the West, joining forces."
	},
	{
		"src": "Dennoch, trotz der \u00f6ffentlichen Vers\u00f6hnung, bestehen zwischen den beiden noch immer gro\u00dfe Differenzen.",
		"tgt": "Still, despite the public display of reconciliation, the two still have major differences."
	},
	{
		"src": "Die gr\u00f6\u00dfte Differenz ist Syrien, wo sich Moskau vor kurzem die Rolle als Friedensstifter gab, aber wo Russland und die T\u00fcrkei gegens\u00e4tzliche Seiten unterst\u00fctzen.",
		"tgt": "The key one is Syria, where Moscow has recently been casting itself as peacemaker but where Russia and Turkey back opposite sides."
	},
	{
		"src": "Es k\u00f6nnte bezeichnend sein, dass nach fast drei Stunden an Erstgespr\u00e4chen beide Pr\u00e4sidenten auf der Pressekonferenz aussagten, dass sie das Thema nicht einmal gestreift h\u00e4tten.",
		"tgt": "It could be telling that after almost three hours of initial talks, the two presidents told a press conference that they hadn't even touched on the topic."
	},
	{
		"src": "Der Pr\u00e4sident der T\u00fcrkei vermied es absichtlich auf eine Frage \u00fcber ihre Differenzen zu antworten, w\u00e4hrend Putin sich dazu entschied diese zu betonen.",
		"tgt": "Turkey's president deliberately avoided answering a question on their differences, while Mr Putin chose to underline them."
	},
	{
		"src": "Es liegt kein eindeutiger Konsens dar\u00fcber vor, wo ein gemeinsamer Nenner zu Syrien gefunden werden kann.",
		"tgt": "There is no clear consensus on where they can seek common ground on Syria."
	},
	{
		"src": "Aber nach Monaten offener Feindseligkeiten - und angesichts des Potenzials f\u00fcr ein vollkommenes Disaster, als das NATO-Mitglied T\u00fcrkei den russischen Kampfjet abschoss - ist es sicherlich besser, dass die zwei Staatschefs zumindest wieder miteinander reden.",
		"tgt": "But after months of open hostility - and given the potential for utter disaster when Nato member Turkey shot down that Russian fighter jet - it is surely better that the two leaders are at least talking again."
	},
	{
		"src": "Royal Bank of Scotland f\u00fcr Kunden au\u00dferhalb Schottlands nicht mehr verf\u00fcgbar",
		"tgt": "Royal Bank of Scotland to disappear for customers outside Scotland"
	},
	{
		"src": "Die Marke RBS soll laut dem Vorstandschef der Bank nurmehr auf eine Backoffice-Rolle reduziert werden.",
		"tgt": "The brand RBS is to be reduced to a back office role, according to the bank's chief executive."
	},
	{
		"src": "Die Royal Bank of Scotland wird f\u00fcr Kunden au\u00dferhalb Schottlands nicht mehr verf\u00fcgbar sein.",
		"tgt": "Royal Bank of Scotland will disappear for customers outside Scotland."
	},
	{
		"src": "Ross McEwan teilte der BBC Scotland mit, dass die Marke RBS mit den globalen Ambitionen der Bank verbunden waren.",
		"tgt": "Ross McEwan told BBC Scotland that the RBS brand was associated with the bank's global ambitions."
	},
	{
		"src": "Die Bank hat sich seitdem distanziert, als sie vor acht Jahren fast kollabierte und gerettet werden musste.",
		"tgt": "It has retreated from them since it nearly collapsed eight years ago and had to be bailed out."
	},
	{
		"src": "In dieser Zeit haben Markenstrategen \"RBS\" dazu verwendet, andere Endverbraucherfinanzmarken zu sch\u00fctzen.",
		"tgt": "During that time, brand strategists have used 'RBS' to protect other consumer finance brands."
	},
	{
		"src": "Sie unterst\u00fctzte den internationalen Sport mit Millionen Pfund an Sponsoring, vom Six Nations Rugby bis hin zum Wimbledon Sieger Andy Murray.",
		"tgt": "It was backed with millions of pounds in sponsorship of international sport, from Six Nations rugby to Wimbledon champion Andy Murray."
	},
	{
		"src": "Aber jetzt hat sie sich dazu entschieden, mehr nationale Marken in den Fokus zu r\u00fccken.",
		"tgt": "But now, it has been judged right to let more national brands come to the fore."
	},
	{
		"src": "Die Royal Bank of Scotland wird nur f\u00fcr Kunden in Schottland verf\u00fcgbar sein, aber wird nicht initialisiert werden.",
		"tgt": "Royal Bank of Scotland will be used with Scottish customers, but will not be initialised."
	},
	{
		"src": "In England und Wales werden alle RSB Referenzen, der dezentrale Hauptsitz und die B\u00f6rsennotierung zu NatWest wechseln.",
		"tgt": "In England and Wales, all RBS references, outside head office and the stock exchange listing, will be changed to NatWest."
	},
	{
		"src": "Die Marke Ulster Bank wird bereits f\u00fcr Kunden in der Republik Irland und Nordirland verwendet.",
		"tgt": "The Ulster Bank brand is already used for customers in the Republic of Ireland and Northern Ireland."
	},
	{
		"src": "Es gibt andere, kleinere Marken f\u00fcr das Privatkundengesch\u00e4ft, die mehr Bedeutung erhalten werden - Coutts, Adam & Co, Drummond und Holt's Military Bank.",
		"tgt": "There are other, smaller brands for private banking, which will get more prominence - Coutts, Adam & Co, Drummond, and Holt's Military Bank."
	},
	{
		"src": "McEwan wurde w\u00e4hrend einer Besichtigungstour von Kunden und Mitarbeitern in Inverness-shire interviewt.",
		"tgt": "Mr McEwan was interviewed during a tour of customers and staff in Inverness-shire."
	},
	{
		"src": "Er teilte der BBC Scotland mit: \"Die Marke RSB wird zu unserer Investorenmarke sowie zu der Marke, unter der unsere Mitarbeiter besch\u00e4ftigt sein werden, da wir jetzt mehr zu einer Bank von Marken werden.\"",
		"tgt": "He told BBC Scotland: \"The RBS brand will end up becoming our investor brand and the one that our staff are employed with, because we are now becoming much more a bank of brands.\""
	},
	{
		"src": "Als die Bank selber zu einer globalen Marke wurde, wurde RBS zur globalen Marke.",
		"tgt": "As the bank itself became a global brand, RBS became the global brand."
	},
	{
		"src": "Ich sage jetzt, dass wir keine globalen Ziele, sondern lokale Ziele verfolgen.",
		"tgt": "I'm now saying we no longer have global aspirations, we have local aspirations."
	},
	{
		"src": "Jede dieser Marken wird in ihren eigenen Gemeinden f\u00fcr etwas vollkommen anderes stehen und unsere Mitarbeiter werden unter diesen Marken mit den Kunden arbeiten.",
		"tgt": "Each one of those brands will stand for something quite different in their own communities, and our staff will work with customers under those brands."
	},
	{
		"src": "RBS hat bereits ausgesagt, dass es sein Six Nations Sponsoring nicht mehr fortf\u00fchren wird und, dass es die Wahrnehmbarkeit der verschiedenen Marken in seinem Sport-Sponsoring erh\u00f6hen wird.",
		"tgt": "RBS had already stated that it would not to continue its Six Nations sponsorship, and it has been raising the profile of different brands in its sports sponsorship."
	},
	{
		"src": "\"Es ist Zeit f\u00fcr uns, sich zur Bank der Marken zu entwickeln, denn wie konzentrieren wir uns im Inneren (wir haben gefragt) darauf, dies zu einer besseren Bank f\u00fcr Kunden zu machen?\" sagte der Vorstandschef.",
		"tgt": "\"The time is right for us to move to the bank of brands, because underneath (we've been asking) how do we focus on making this a better bank for customers?\" said the chief executive."
	},
	{
		"src": "Es w\u00e4re vor drei Jahren sehr zynisch gewesen, wenn wir gesagt h\u00e4tten, dass wir f\u00fcr unsere Kunden eine tolle Bank sein werden und diese Marken lanciert h\u00e4tten.",
		"tgt": "It would have been very cynical three years ago if we'd said we're going to be a great bank for customers and put those brands out there."
	},
	{
		"src": "Aber mit unserer Arbeit, dem Fokus auf Kundenbed\u00fcrfnisse und nicht unsere eigenen, denke ich, wird man viele Ver\u00e4nderungen sehen.",
		"tgt": "But with the work we've been doing, focussing on the customers needs, not our own, I think you're seeing a lot of change."
	},
	{
		"src": "Wir k\u00f6nnen diese Marken wieder lancieren, daher denke ich, dass die Zeit gekommen ist.",
		"tgt": "We can bring those brands back up again, so I think the time is right."
	},
	{
		"src": "Frankie Dettori erreicht auf Predilection seinen 3.000ten Gewinn bei Newmarket",
		"tgt": "Frankie Dettori reaches 3,000 winners with victory at Newmarket on Predilection"
	},
	{
		"src": "Dettori spr\u00fcht Champagner nach einem Double bei Newmarket, der ihm 3.000ten Gewinn bringt",
		"tgt": "Dettori sprays champagne after a double at Newmarket takes him to 3,000 wins"
	},
	{
		"src": "Der Jockey Frankie Dettori sicherte am Freitag seinen 3.000ten britischen Gewinn bei Newmarket.",
		"tgt": "Jockey Frankie Dettori secured his 3,000th British winner at Newmarket on Friday."
	},
	{
		"src": "Er setzte auf Predilection, die von John Gosden trainiert wird, auf seiner lokalen Rennstrecke mit seinem zweiten Gewinn der Nacht einen Meilenstein.",
		"tgt": "He brought up the landmark with his second winner of the night at his local track - on Predilection, trained by John Gosden."
	},
	{
		"src": "Der 45-j\u00e4hrige Italiener ist der sechste Jockey, der den Meilenstein im Flachrennen erreicht.",
		"tgt": "The 45-year-old Italian is the sixth jockey to reach the landmark in Flat racing."
	},
	{
		"src": "Er folgt Sir Gordon Richards, Doug Smith, Lester Piggott, Pat Eddry und Willie Carson.",
		"tgt": "He follows Sir Gordon Richards, Doug Smith, Lester Piggott, Pat Eddery and Willie Carson."
	},
	{
		"src": "Der dreimalige Sieger Dettori, der davor auf Ghayyar gewann, sagte: \"Es ist etwas Besonderes.\"",
		"tgt": "Three-time champion jockey Dettori, who earlier won on Ghayyar, said: \"It's special.\""
	},
	{
		"src": "Ich bin sehr emotional, weil meine Familie auch hier ist",
		"tgt": "I'm very emotional because my family are here as well"
	},
	{
		"src": "Ich bin sehr gl\u00fccklich dar\u00fcber, dass es bei Newmarket geschehen ist, weil ich hier vor 30 Jahren gelandet bin.",
		"tgt": "I'm very pleased for it to have happened at Newmarket because this is where I landed 30 years ago."
	},
	{
		"src": "Es ist kein gro\u00dfes Treffen, es ist nicht Royal Ascot - es ist ein banaler Freitag abend mit 20.000 Leuten.",
		"tgt": "It's not a big meeting, it's not a Royal Ascot - it's a mundane Friday night with 20,000 people."
	},
	{
		"src": "Ich bin erleichtert und sehr bescheiden.",
		"tgt": "I'm relieved and very humble."
	},
	{
		"src": "Dettori nimmt den Jubel auf, als er auf Predilection den Sieg holt",
		"tgt": "Dettori soaks up the cheers as he brings in Predilection after victory"
	},
	{
		"src": "Zwei Jockeys haben den Meilenstein im Hindernisrennen erreicht - Jockey Richard Johnson und der pensionierte 20-malige Sieger Sir Anthony McCoy, der mehr als 4.300 Siege in einer rekordbrechenden Karriere erreichte.",
		"tgt": "Two jockeys have reached the milestone in jump racing - champion jockey Richard Johnson and retired 20-time champion Sir Anthony McCoy, who had more than 4,300 victories in a record-breaking career."
	},
	{
		"src": "Lester Piggott, der neunmalige Derbysieger hatte 4.493 Karrieresiege",
		"tgt": "Lester Piggott, nine-time Derby winner, 4,493 career wins"
	},
	{
		"src": "Frankie ist einer der besten Jockey der Moderne und es ist keine \u00dcberraschung, dass er diesen Meilenstein erreicht hat, den nur wenige vor ihm erreicht haben.",
		"tgt": "Frankie is one of the best jockeys of the modern era and it is no surprise he has reached this landmark so few have achieved before him."
	},
	{
		"src": "Er hat Stil und ist stark, aber es ist sein taktischer Intellekt, der ihn von den anderen im Gewichtskontrollraum unterscheidet.",
		"tgt": "He is stylish and strong, but it is his tactical nous that sets him apart from others in the weighing room."
	},
	{
		"src": "Er ist ein fantastischer Botschafter f\u00fcr Rennen, sein Enthusiasmus und Charisma begeistert Fans schon seit Jahren f\u00fcr diese Sportart.",
		"tgt": "He is a fantastic ambassador for racing, his enthusiasm and charisma have been drawing fans to the sport for years."
	},
	{
		"src": "Ich sagte Frankie vor einigen Wochen bei Epsom, dass er bereits 6.000 Gewinne geholt h\u00e4tte, wenn er nicht nur ein Wochenend- und Gro\u00dfturnierjockey w\u00e4re!",
		"tgt": "I said to Frankie a few weeks ago at Epsom he'd have ridden 6,000 winners if he wasn't just a weekend and big-race jockey!"
	},
	{
		"src": "Frankie hat in GB bereits fast 30 Jahre Gewinner geritten, was toll ist.",
		"tgt": "Seriously though, Frankie's been riding winners in the UK for the best part of 30 years which is great to see."
	},
	{
		"src": "Er hat eine lebendige Pers\u00f6nlichkeit, was f\u00fcr ein britisches Rennen gut ist, aber dar\u00fcber hinaus ist er ein unglaublicher Jockey.",
		"tgt": "He's a lively character which is good for British racing but more than that, he's an incredible jockey."
	},
	{
		"src": "Frankie Dettori feierte den Meilenstein mit einem typischen Flying Dismount",
		"tgt": "Frankie Dettori celebrated the milestone with a trademark flying dismount"
	},
	{
		"src": "Von Flying Finishes zu Flying Dismounts, Frankie Dettori ist seit zwei Jahrzehnten das Aush\u00e4ngeschild des britischen Flachrennens.",
		"tgt": "From flying finishes to flying dismounts, Frankie Dettori has been the poster boy of British Flat racing for two decades."
	},
	{
		"src": "Es war nervenaufreibend.",
		"tgt": "It has been a rollercoaster ride."
	},
	{
		"src": "Eine ganze Reihe an Gro\u00dfturniergewinnen, einschlie\u00dflich seiner ber\u00fchmten \"Glorreichen Sieben\" 1996 in Ascot, aber er \u00fcberlebte auch einen Flugzeugabsturz und erhielt ein Drogenverbot.",
		"tgt": "Stacks of big-race winners, including his famous 1996 'Magnificent Seven' at Ascot, but he also survived a plane crash and served a drugs ban."
	},
	{
		"src": "Vor drei Jahren hatte er anfangs Schwierigkeiten, als er von seiner sechsmonatigen Sperre zur\u00fcckkehrte, aber er zeigte eine beeindruckende charakterliche St\u00e4rke, um seinen Zweiflern zu trotzen und zu seiner Bestform zur\u00fcckzukehren.",
		"tgt": "Three years ago he initially struggled when returning from that six-month suspension, but he showed formidable strength of character to defy the doubters and return to his best."
	},
	{
		"src": "Und er ist noch lange nicht am Ende - Dettori hat fr\u00fcher einmal gesagt, dass er bei Wettbewerben bis zu seinem mindestens 50.ten Lebensjahr weitermachen will.",
		"tgt": "And he may not be done for some time - Dettori has previously said he would like to carry on competing until the age of 50, at least."
	},
	{
		"src": "Russlands Putin feuert Stabschef Sergei Ivanov",
		"tgt": "Russia's Putin sacks chief of staff Sergei Ivanov"
	},
	{
		"src": "Der russische Pr\u00e4sident Vladimir Putin hat unerwarteterweise seinen Stabschef Sergei Ivanov entlassen.",
		"tgt": "Russian President Vladimir Putin has unexpectedly dismissed his chief of staff Sergei Ivanov."
	},
	{
		"src": "Ivanov war viele Jahre Teil des engsten Vertrauenskreises von Putin.",
		"tgt": "Mr Ivanov has been part of Mr Putin's trusted inner circle for many years."
	},
	{
		"src": "Der 63-J\u00e4hrige wurde zum Sonderbeauftragten f\u00fcr Umwelt- und Transportangelegenheiten ernannt.",
		"tgt": "The 63-year-old has now been made a special representative for environmental and transport issues."
	},
	{
		"src": "In einer Stellungnahme des Kreml lautet es, dass Putin ohne Angabe von Gr\u00fcnden \"die Entlassung Ivanovs von seinen Pflichten als Vorsitzender der russischen Pr\u00e4sidialverwaltung angeordnet habe\".",
		"tgt": "A statement from the Kremlin said that Mr Putin had \"decreed to relieve Ivanov of his duties as head of the Russian presidential administration,\" but gave no reason."
	},
	{
		"src": "Anton Vaino, der seit 2012 Ivanovs Stellvertreter war, wurde zu seinem Nachfolger ernannt.",
		"tgt": "Mr Ivanov's deputy since 2012, Anton Vaino, has been appointed as his successor."
	},
	{
		"src": "Vaino, 44, ist ehemaliger Diplomat.",
		"tgt": "Mr Vaino, 44, is a former diplomat."
	},
	{
		"src": "1972 in der estnischen Hauptstadt Tallinn geboren, machte er seinen Abschluss am renommierten Staatlichen Moskauer Institut f\u00fcr Internationale Beziehungen (MGIMO) und arbeitete in der Botschaft in Tokyo.",
		"tgt": "Born in the Estonian capital Tallinn in 1972, he graduated from the prestigious Moscow State Institute of International Relations (MGIMO) and served in the Tokyo embassy."
	},
	{
		"src": "Auf der Website des Kreml hei\u00dft es (auf Russisch), dass er sp\u00e4ter Protokollchef und Stabsleiter des Regierungspersonals war.",
		"tgt": "Later he managed presidential protocol and government staff, the Kremlin website says (in Russian)."
	},
	{
		"src": "\u00dcber seine Ernennung sagte er zu Putin:\"Danke f\u00fcr Ihr Vertrauen.\"",
		"tgt": "On being appointed, he told Mr Putin: \"Thank you for your trust.\""
	},
	{
		"src": "Ich denke, dass es die wichtigste Aufgabe der Regierung ist, Ihre T\u00e4tigkeit als Staatschef bez\u00fcglich Gesetzesentw\u00fcrfen und Kontrollen zur Umsetzung Ihrer Anweisungen zu unterst\u00fctzen.",
		"tgt": "I think the administration's most important task is to support your activity as head of state in terms of drafting laws and control over how your instructions are implemented."
	},
	{
		"src": "Putin teilte dem russischen TV Sender am Freitag mit, dass Ivanov darum gebeten habe, seinen Posten zu verlassen und Vaino als seinen Nachfolger empfohlen habe.",
		"tgt": "Mr Putin told a Russian TV station on Friday that Mr Ivanov had asked to leave the post, and recommended that Mr Vaino should replace him."
	},
	{
		"src": "\u00dcberzeugen die l\u00e4chelnden Gesichter?",
		"tgt": "Do the smiles convince?"
	},
	{
		"src": "Dieser Schritt hat Moskau geheimnisumwoben gemacht.",
		"tgt": "This is a move that has mystified Moscow."
	},
	{
		"src": "Sergei Ivanov war lange Zeit einer der engsten Vertrauten Vladimir Putins und arbeitet wie er f\u00fcr den sowjetischen Geheimdienst, dem KGB.",
		"tgt": "Sergei Ivanov has long been one of Vladimir Putin's closest allies and, like him, served in the Soviet security service, the KGB."
	},
	{
		"src": "Als Stabschef war er einer der m\u00e4chtigsten M\u00e4nner der Landes.",
		"tgt": "As chief of staff he was one of the most powerful men in the country."
	},
	{
		"src": "Bei einem Treffen mit Pr\u00e4sident Putin, das im Fernsehen ausgestrahlt wurde, behaupteten beide M\u00e4nner, dass der Stabschef auf eigenen Wunsch zur\u00fccktritt.",
		"tgt": "In a meeting with President Putin shown on state television both men claimed that the chief of staff was stepping down at his own request."
	},
	{
		"src": "Aber trotz des L\u00e4chelns f\u00fcr die Kameras, sind hier nur wenige davon \u00fcberzeugt - vor allem jetzt, kurz vor den Parlamentswahlen.",
		"tgt": "But despite the smiles for the cameras, few here are convinced - especially now, just before parliamentary elections."
	},
	{
		"src": "Liegt hier also die Folge einer Art Machtkampf vor?",
		"tgt": "So is this the fall-out from some kind of power struggle?"
	},
	{
		"src": "Das wei\u00df derzeit niemand.",
		"tgt": "No-one knows yet."
	},
	{
		"src": "Aber die offizielle Behauptung - dass ein Mann, der einst als potenzieller Pr\u00e4sident angepriesen wurde, auf einmal die russische Umweltpolitik leiten m\u00f6chte - stie\u00df auf gro\u00dfe Skepsis.",
		"tgt": "But the official claim - that a man once touted as a potential president, suddenly wanted to run Russia's environmental policy - has been met with great scepticism."
	},
	{
		"src": "In seinen Bemerkungen an Putin, die auf der Website des Kreml zitiert werden, sagte Ivanov \"es ist wahr, dass ich Sie Anfang 2012 in einem Gespr\u00e4ch gebeten habe, mir diesen sehr komplizierten Posten - man k\u00f6nnte beinahe sagen - beschwerlichen Posten vier Jahre lang anzuvertrauen.",
		"tgt": "In remarks to Mr Putin, quoted on the Kremlin website, Mr Ivanov said \"it's true that in early 2012 I asked you, in a conversation, to entrust me with this very complicated post, even - you could say - troublesome post, for four years."
	},
	{
		"src": "Wie es sich herausstellt, bin ich seit vier Jahren und acht Monaten Vorsitzender der russischen Pr\u00e4sidialverwaltung.",
		"tgt": "Well, it turns out that I've been presidential chief of staff for four years and eight months."
	},
	{
		"src": "Ivanov nahm den Posten im Dezember 2011 an.",
		"tgt": "Mr Ivanov took up the post in December 2011."
	},
	{
		"src": "Zuvor war er stellvertretender Ministerpr\u00e4sident und Verteidigungsminister.",
		"tgt": "He served previously as a deputy prime minister and defence minister."
	},
	{
		"src": "Er ist Mitglied des russischen Sicherheitsrates und wie Putin ehemaliges Mitglied des Staatssicherheitsdienstes KGB.",
		"tgt": "He is a member of the Russian Security Council and a former member of the KGB state security service, like Mr Putin."
	},
	{
		"src": "In den sp\u00e4ten 1990er Jahren, als Putin Vorsitzender des Bundessicherheitsdienstes (FSB) war, der den KGB ersetzte, wurde Ivanov zu seinem Stellvertreter ernannt.",
		"tgt": "In the late 1990s, when Mr Putin was head of the Federal Security Service (FSB), which replaced the KGB, Mr Ivanov was appointed as his deputy."
	},
	{
		"src": "Als Putin an die Macht gelangte nannte er Ivanov als einen von f\u00fcnf Leuten, denen er am meisten vertraute.",
		"tgt": "When Mr Putin came to power, he named Mr Ivanov as one of the five people he trusted most."
	},
	{
		"src": "Einst wurde angenommen, dass Ivanov nach Putins zweiter Amtszeit Pr\u00e4sident von Russland werden k\u00f6nnte, da eine dritte Amtszeit Putins gegen die Verfassung versto\u00dfen h\u00e4tte.",
		"tgt": "It was once thought that Mr Ivanov might become president of Russia after Mr Putin's second term, as a third term for Mr Putin would have been unconstitutional."
	},
	{
		"src": "Aber dieser Posten wurde von einem weiteren, nahestehenden Verb\u00fcndeten Putins eingenommen, Dmitry Medvedev.",
		"tgt": "But that post was taken by another close Putin ally, Dmitry Medvedev."
	},
	{
		"src": "Putin wurde Ministerpr\u00e4sident, bevor er dreieinhalb Jahre sp\u00e4ter wieder zum Pr\u00e4sidenten wurde.",
		"tgt": "Mr Putin became prime minister, before returning to the presidency just three-and-a-half years later."
	},
	{
		"src": "Criminal Minds Star Thomas Gibson gefeuert, nachdem er Produzenten schlug",
		"tgt": "Criminal Minds star Thomas Gibson sacked after hitting producer"
	},
	{
		"src": "Gibson war letzten Monat an einer k\u00f6rperliche Auseinandersetzung am Set der Serie in Los Angeles beteiligt.",
		"tgt": "Gibson was involved in a physical altercation on the set of the show in Los Angeles last month."
	},
	{
		"src": "ABC Studios und CBS Television Studios, die die Serie produzieren, verk\u00fcndeten in einer gemeinsamen Stellungnahme seine K\u00fcndigung.",
		"tgt": "ABC Studios and CBS Television Studios, which produce the series, announced his dismissal in a joint statement."
	},
	{
		"src": "Gibson, der den Special Agent Aaron Hotchner spielte, entschuldigte sich am Donnerstag vor der Bekanntmachung seiner K\u00fcndigung \u00f6ffentlich.",
		"tgt": "Gibson, who played Special Agent Aaron Hotchner, issued an apology on Thursday before his termination was announced."
	},
	{
		"src": "Am Set kam es zu k\u00fcnstlerischen Differenzen und einer Meinungsverschiedenheit.",
		"tgt": "There were creative differences on the set and a disagreement."
	},
	{
		"src": "Ich bereue den Vorfall,\" sagte er in einer Mitteilung.",
		"tgt": "I regret that it occurred,\" he said in a statement."
	},
	{
		"src": "Einzelheiten dazu, wie der Charakter Gibsons aus der Serie, die einem Team von FBI Agenten folgt, herausgeschrieben wird, werden laut der Stellungnahme der ABC Studios und CBS Television Studios voraussichtlich zu einem sp\u00e4teren Zeitpunkt ver\u00f6ffentlicht.",
		"tgt": "Details on how Gibson's character will be written out of the show, which follows a team of FBI agents, is expected to come at a later date, according to the ABC Studios and CBS Television Studios statement."
	},
	{
		"src": "Der 54-J\u00e4hrige, der zuvor in der Sitcom Dharma & Greg spielte, war seit der ersten Staffel der Serie im Jahr 2005 mit dabei.",
		"tgt": "The 54-year-old, who previously starred on the sitcom Dharma & Greg, had been on the show since its first season in 2005."
	},
	{
		"src": "\"Ich liebe Criminal Minds und habe die letzten zw\u00f6lf Jahre mein ganzes Herzblut hineingesteckt,\" sagte Gibson in einer am Freitag ver\u00f6ffentlichten Mitteilung.",
		"tgt": "\"I love Criminal Minds and have put my heart and soul into it for the last twelve years,\" Gibson said in a statement released on Friday."
	},
	{
		"src": "Ich hatte gehofft bis zum Ende dabei zu sein, aber das wird jetzt nicht mehr m\u00f6glich sein.",
		"tgt": "I had hoped to see it through to the end, but that won't be possible now."
	},
	{
		"src": "Ich w\u00fcrde mich einfach gerne bei den Autoren, Produzenten, Schauspielern, unserer wundervollen Crew und vor allem den besten Fans, die man sich f\u00fcr eine Serie nur w\u00fcnschen kann, bedanken.",
		"tgt": "I would just like to say thank you to the writers, producers, actors, our amazing crew, and, most importantly, the best fans that a show could ever hope to have."
	},
	{
		"src": "Die geplante Ausstrahlung der zw\u00f6lften Staffel ist auf den 28. September angesetzt.",
		"tgt": "The show is slated to return for its twelfth season on 28 September."
	},
	{
		"src": "R\u00e4tsel um Fische, die in Garten in Banff landeten",
		"tgt": "Mystery as fish land in Banff garden"
	},
	{
		"src": "Ein Einwohner von Banff forderte bei der Identifizierung der Fische Hilfe an, der in seinem Garten in Banff auftauchte.",
		"tgt": "A Banff man has appealed for help in identifying fish that have appeared in his garden in Banff."
	},
	{
		"src": "Kevin Bain denkt, dass es sich bei den 75 Fischen um Sandaale handeln k\u00f6nnte, die von einem Springbrunnen ausgespien wurden.",
		"tgt": "Kevin Bain thinks the 75 fish could be sand eels deposited by a waterspout."
	},
	{
		"src": "Herr Bain, der ca. 500 Meter vom Meer lebt, ver\u00f6ffentlichte auf Periscope ein Video des Spektakels in der Hoffnung, dass jemand etwas Licht auf das Erscheinen der zwei Zoll langen Fische werfen k\u00f6nnte.",
		"tgt": "Mr Bain, who lives about 500m from the sea, posted footage of the spectacle on Periscope in the hope someone could shed light on the appearance of the two-inch fish."
	},
	{
		"src": "Queensferry Crossing: Br\u00fccke nun mit Fife verbunden",
		"tgt": "Queensferry Crossing: Bridge now connected to Fife"
	},
	{
		"src": "Das \u00a3 1,35 Mrd. teure Projekt soll bis Mai 2017 fertiggestellt werden",
		"tgt": "The \u00a31.35bn project is now due to be complete by May 2017"
	},
	{
		"src": "Ingenieure haben das Norddeck des Queensferry Crossings mit dem Viadukt verbunden - was bedeutet, dass die Br\u00fccke jetzt mit Fife verbunden ist.",
		"tgt": "Engineers have joined the Queensferry Crossing's north deck and viaduct - meaning the bridge is now connected to Fife."
	},
	{
		"src": "Es ist das erste von vier Verschlie\u00dfungen der \"Deckgebl\u00e4se\", die sich der Fertigstellung um jeden der drei T\u00fcrme der Br\u00fccke n\u00e4hern.",
		"tgt": "It is the first of four closures between the \"deck fans,\" which are now nearing completion around each of the bridge's three towers."
	},
	{
		"src": "Der Br\u00fcckenabschnitt von Fife ist jetzt 600 Meter lang und wiegt 30.000 Tonnen.",
		"tgt": "The bridge section from Fife is now 600 metres long and weighs 30,000 tonnes."
	},
	{
		"src": "Er verf\u00fcgt \u00fcber 10.000 Tonnen Stahl und 20.000 Tonnen Beton sowie 46 Schr\u00e4gseile.",
		"tgt": "It has 10,000 tonnes of steel and 20,000 tonnes of concrete and 46 stay-cables."
	},
	{
		"src": "Das \u00a3 1,35 Mrd. teure Projekt soll bis Mai 2017 fertiggestellt werden.",
		"tgt": "The \u00a31.35bn project is now due to be complete by May 2017."
	},
	{
		"src": "Wirtschaftsminister Keith Brown stattete der Baustelle heute einen Besuch ab und war einer der Ersten, die vom Land auf die Br\u00fccke gingen.",
		"tgt": "Economy Secretary Keith Brown visited the site today and was among the first to walk from the land on to the bridge."
	},
	{
		"src": "Er sagte: \"Das ist ein historischer und symbolischer Moment beim Bau des Queensferry Crossings.",
		"tgt": "He said: \"This is a historic and symbolic moment in the building of the Queensferry Crossing."
	},
	{
		"src": "Wir sind alle Zeugen einer Ingenieurskunst von einem wahrlich epischen Ma\u00dfe bei diesem Projekt mit \u00fcber 30.000 Tonnen Beton und Stahl, die alleine f\u00fcr diesen Teil der Br\u00fccke verwendet wurden.",
		"tgt": "We're all witnessing engineering on a truly epic scale on this project, with over 30,000 tonnes of concrete and steel used just to build this part of the bridge."
	},
	{
		"src": "Trotz der massiven Gr\u00f6\u00dfe und Gewichts des Br\u00fccke, ist die Fertigstellung des Verschlusses zwischen dem Viadukt und dem Br\u00fcckendeck eine heikle T\u00e4tigkeit, die extrem pr\u00e4zise Toleranzen f\u00fcr die Passung erfordern.",
		"tgt": "Despite the massive size and weight of the bridge completing the closure between the viaduct and bridge deck is a delicate operation involving extremely precise tolerances for fit up."
	},
	{
		"src": "Insgesamt sind fast 79 % der gesamten Br\u00fcckendecks an ihrem Platz und der letzte Abschnitt des Decks bekommt heute in Rosyth einen Betonguss f\u00fcr das Deck, was bedeutet, dass das gesamte Deck bereit ist, auf der Br\u00fccke an seinen Platz gehoben zu werden.",
		"tgt": "Overall, nearly 79% of the total bridge deck is now in place, the final section of deck is having its concrete deck cast in Rosyth today, meaning all the deck is ready to be lifted into place on the bridge."
	},
	{
		"src": "Michael Martin, Projektleiter von Forth Crossing Bridge Constructors sagte: \"Der erste Verschluss stellt bei jedem Br\u00fcckenprojekt einen erheblichen Meilenstein dar.",
		"tgt": "Michael Martin, Forth Crossing Bridge Constructors project director said: \"The first closure on any bridge project is always a significant milestone."
	},
	{
		"src": "Bei diesem fantastischen Projekt stellt der Verschluss zukunftsweisenden Hoch- und Tiefbau dar.",
		"tgt": "On this fantastic project, this closure represents leading edge civil engineering."
	},
	{
		"src": "Nach der Installation des letzten Stra\u00dfendeckabschnitts und dessen Verbindung mit dem im Ausbau befindlichen Nordturmdeck, mussten wir sodann die noch bestehende L\u00fccke auf der Nord- oder Landseite schlie\u00dfen.",
		"tgt": "After installing the last road deck section and connecting it to the expanding North Tower road deck, we then had to close the remaining gap on the north - or landward - side."
	},
	{
		"src": "Dies wurde durch Ziehen der n\u00f6rdlichen Zubringerbr\u00fccke 700 Millimeter s\u00fcdlich erreicht.",
		"tgt": "This was done by pulling the northern approach viaduct 700 millimetres southwards."
	},
	{
		"src": "Dies war eine massive und gleichzeitig sehr heikle T\u00e4tigkeit.",
		"tgt": "This was a massive and, at the same time, very delicate operation."
	},
	{
		"src": "Massiv, da das Viadukt 222 Meter lang ist, ca. 6.000 Tonnen wiegt und bei einer Steigung von ca. 3 % nach oben gezogen werden musste.",
		"tgt": "Massive because the viaduct is 222 metres long, weighs approximately 6,000 tonnes and had to be pulled up a gradient of about 3%."
	},
	{
		"src": "Heikel, da die Toleranzen, auf die das Team hinarbeitet, winzig waren - auf jeder Seite betrugen sie nur einige Millimeter.",
		"tgt": "Delicate because the tolerances the team were working to were tiny - just a few millimetres either way."
	},
	{
		"src": "Gl\u00fccklicherweise verlief alles sehr gut.",
		"tgt": "Happily, it all went very well."
	},
	{
		"src": "Rettung in der Moelfre Bay: Drei M\u00e4nner haben \"Gl\u00fcck noch am Leben zu sein\"",
		"tgt": "Moelfre Bay rescue: Three men are 'lucky to be alive'"
	},
	{
		"src": "Drei M\u00e4nner haben \"Gl\u00fcck noch am Leben zu sein\", nachdem sie von ihrem Fischerboot vor Anglesey geworfen wurden.",
		"tgt": "Three men are \"lucky to be alive\" after they were thrown from their fishing boat off Anglesey."
	},
	{
		"src": "Die Moelfre RNLI Rettungsstation schlug am Freitag um 13:20 BST Alarm, nachdem eine Crew das Ereignis in Moelfre Bay beobachtete.",
		"tgt": "Moelfre RNLI lifeboat station raised the alarm at 13:20 BST on Friday after a crew saw the incident unfold in Moelfre Bay."
	},
	{
		"src": "Die drei M\u00e4nner hatten Schwierigkeiten sich in Sicherheit zu schwimmen, w\u00e4hrend sich ihr Boot aus eigener Kraft weiterbewegte.",
		"tgt": "The three men struggled to swim to safety while their boat continued under its own power."
	},
	{
		"src": "\"Wir sahen, wie sich das Boot in ihrer N\u00e4he um sich drehte und stellten uns das Schlimmste vor,\" sagte der Leiter der Rettungsstation von Moelfre Vince Jones.",
		"tgt": "\"We saw their boat circling close to them and imagined the worst,\" said Moelfre lifeboat helm Vince Jones."
	},
	{
		"src": "\"Gl\u00fccklicherweise haben die starken Winde das Boot bereits au\u00dfer ihrer Reichweite geweht, bis wir zu Wasser lie\u00dfen,\" f\u00fcgte er hinzu.",
		"tgt": "\"Fortunately, by the time we had launched, the strong winds had blown it clear of them,\" he added."
	},
	{
		"src": "Zwei der M\u00e4nner wurden von einem \u00f6rtlichen Fischerboot gerettet, w\u00e4hrend der dritte Mann im Alter von 60 ersch\u00f6pft und an einer Boje h\u00e4ngend ohne Rettungsweste aufgefunden wurde.",
		"tgt": "Two of the men were rescued by a local fishing boat, while the third man, aged 60, was found exhausted and clinging to a buoy without a lifejacket."
	},
	{
		"src": "Sie kamen alle an Bord des K\u00fcstenrettungsboots und wurden zur\u00fcck zur Rettungsstation gebracht",
		"tgt": "They were all taken on board the inshore lifeboat and brought back to the lifeboat station"
	},
	{
		"src": "Herr Jones sagte: \"Die drei M\u00e4nner, die ins Wasser geworfen wurden, haben Gl\u00fcck unverletzt und noch am Leben zu sein.",
		"tgt": "Mr Jones said: \"The three men thrown in the water are lucky to be alive and completely uninjured."
	},
	{
		"src": "Der Bootmotor verf\u00fcgte zwar \u00fcber eine Notstoppleine, diese l\u00f6ste sich allerdings beim Kentern des Boots von der Person los, die das Boot steuerte.",
		"tgt": "The boat's engine had an emergency kill cord but it had somehow come detached from the person driving the boat when it capsized."
	},
	{
		"src": "Jemand hat heute \u00fcber diese M\u00e4nner gewacht.",
		"tgt": "Someone was watching over these guys today."
	},
	{
		"src": "Schwer verletzt - Mann sticht auf seine Ex-Freundin ein",
		"tgt": "Seriously injured - man stabs his ex-girlfriend"
	},
	{
		"src": "Ein Mann hat seine Ex-Freundin in Hamburg-Harburg mit einem Messer angegriffen und schwer verletzt.",
		"tgt": "A man has attacked his ex-girlfriend with a knife in Hamburg's Harburg district, and seriously injured her."
	},
	{
		"src": "Wie die Polizei gestern mitteilte, hatte der 50-J\u00e4hrige den Schl\u00fcssel zur Wohnung bekommen, um seine pers\u00f6nlichen Dinge zu holen.",
		"tgt": "As the police reported yesterday, the 50-year-old had got the key to the apartment so he could collect his personal belongings."
	},
	{
		"src": "Stattdessen zerschnitt der alkoholisierte T\u00e4ter die Kleidung seiner Ex-Freundin.",
		"tgt": "Instead, the drunk attacker sliced up his ex-girlfriend's clothes."
	},
	{
		"src": "Als diese in die Wohnung kam, stach er zweimal auf sie ein.",
		"tgt": "When she came home, he stabbed her twice."
	},
	{
		"src": "Die 44-J\u00e4hrige wurde an der Hand und am K\u00f6rper verletzt.",
		"tgt": "The 44-year-old suffered injuries to her hand and body."
	},
	{
		"src": "Die Polizei konnte den T\u00e4ter festnehmen.",
		"tgt": "The police managed to arrest the perpetrator."
	},
	{
		"src": "W\u00e4hrend der 50-J\u00e4hrige die Kleidung seiner Ex-Freundin zerst\u00f6rte, rief er seine Mutter an.",
		"tgt": "While the 50-year-old man was destroying his ex-girlfriend's clothing, he called his mother."
	},
	{
		"src": "Diese alarmierte daraufhin dessen Schwester.",
		"tgt": "She then called his sister."
	},
	{
		"src": "Gemeinsam mit ihrem Lebensgef\u00e4hrten wollte die 45-J\u00e4hrige ihren Bruder beruhigen.",
		"tgt": "The 45-year-old and her partner wanted to calm down her brother."
	},
	{
		"src": "Sie konnte ihn aber nicht dazu bewegen, die Wohnung zu verlassen.",
		"tgt": "However, she couldn't get him to leave the apartment."
	},
	{
		"src": "Darum ging sie mit ihrem Lebensgef\u00e4hrten aus dem Haus.",
		"tgt": "Consequently, she set off from home with her partner."
	},
	{
		"src": "Auf der Stra\u00dfe trafen sie die Ex-Lebensgef\u00e4hrtin des Mannes an.",
		"tgt": "They met the man's ex-partner in the street."
	},
	{
		"src": "Als die beiden Frauen die Wohnung erneut betraten, schubste der 50-J\u00e4hrige seine Schwester zur Seite und griff seine Ex-Freundin an.",
		"tgt": "As the two women entered the apartment, the 50-year-old pushed his sister to one side, and attacked his ex-girlfriend."
	},
	{
		"src": "Wer baut Braunschweigs g\u00fcnstige Wohnungen?",
		"tgt": "Who is going to build Braunschweig's low-cost housing?"
	},
	{
		"src": "Die SPD und Gr\u00fcne meinen: Investoren sollen k\u00fcnftig viel st\u00e4rker in die Pflicht genommen werden.",
		"tgt": "The SPD and the Greens think that investors should step up to the plate much more in the future."
	},
	{
		"src": "Wie reagiert man auf die schlechte Nachricht, dass Braunschweig in den n\u00e4chsten Jahren fast 1300 g\u00fcnstige Wohnungen verlieren wird?",
		"tgt": "How to react to the bad news that Braunschweig will lose almost 1300 low-cost homes over the next few years?"
	},
	{
		"src": "Die SPD schl\u00e4gt zur n\u00e4chsten Ratssitzung ein \"Handlungskonzept Wohnen\" vor.",
		"tgt": "At the next council meeting, the SPD is going to put forward an \"action plan for homes\"."
	},
	{
		"src": "Doch Streit ist programmiert.",
		"tgt": "But it won't be smooth sailing."
	},
	{
		"src": "In erster Linie geht es um die Frage: Wer soll die g\u00fcnstigen Wohnungen eigentlich bauen?",
		"tgt": "Firstly, there is the question of who is actually going to build the low-cost homes?"
	},
	{
		"src": "Eine Regelung fehlt bislang.",
		"tgt": "So far, no settlement has been reached on this point."
	},
	{
		"src": "SPD-Fraktionsvorsitzender Christoph Bratmann meint: \"Wir sind uns mit den Gr\u00fcnen einig: Wer auf st\u00e4dtischen Fl\u00e4chen bauen will, muss k\u00fcnftig 20 Prozent aller Wohnungen als Sozialwohnungen ausweisen.\"",
		"tgt": "SPD group chairman, Christoph Bratmann, says: \"We agree with the Greens: if you want to build on municipal land, you will have to designate 20 percent of all homes as social housing in the future.\""
	},
	{
		"src": "Die g\u00fcnstigen Wohnungen k\u00f6nnen allerdings auch im Bestand entstehen.",
		"tgt": "The low-cost homes could also be older homes that are renovated."
	},
	{
		"src": "Der gro\u00dfe Streitpunkt im Rathaus sei jedoch, so Bratmann: \"Wie geht man mit Investoren um, die auf privaten Fl\u00e4chen bauen wollen?\"",
		"tgt": "However, the main issue for the council, according to Bratmann: \"How do we handle investors who want to build on private ground?\""
	},
	{
		"src": "\"Wir wollen, dass Investoren auf solchen Fl\u00e4chen mindestens 10 Prozent, aber m\u00f6glichst 20 Prozent der Wohnungen als Sozialwohnungen bauen.\"",
		"tgt": "We want investors building on those spaces to keep at least 10 percent, but if possible, 20 percent, of homes as social housing.\""
	},
	{
		"src": "Ein neues st\u00e4dtisches Wohnungsbau-F\u00f6rderprogramm, das Millionen kosten wird und noch finanziert werden muss, soll f\u00fcr Anreize sorgen.",
		"tgt": "A new municipal programme to promote the construction of homes, which will cost millions, and which still needs to be financed, will trigger concerns."
	},
	{
		"src": "Das Problem, so Bratmann: \"Es gibt momentan noch keine Einigung zwischen den Fraktionen.\"",
		"tgt": "The problem, according to Bratmann: \"At the moment, there is no agreement between groups.\""
	},
	{
		"src": "Die CDU m\u00f6chte Investoren m\u00f6glichst wenige Vorschriften machen.",
		"tgt": "The CDU wants to put as few rules on investors as possible."
	},
	{
		"src": "Die Linke will noch h\u00e4rte Auflagen f\u00fcr Investoren.",
		"tgt": "The Left wants more stringent requirements to be imposed on investors."
	},
	{
		"src": "Ungeachtet dessen, so Bratmann, bahne sich eine Versch\u00e4rfung der Situation auf dem Wohnungsmarkt an.",
		"tgt": "Despite that, according to Bratman, the situation in terms of the housing market is also hotting up."
	},
	{
		"src": "Wird das Handlungskonzept umgesetzt, wird das f\u00fcr zus\u00e4tzliche Aufgaben in der Bauverwaltung sorgen.",
		"tgt": "If the action plan is implemented, the building authorities will be faced with additional tasks."
	},
	{
		"src": "Mehr Personal wird ben\u00f6tigt.",
		"tgt": "More staff will be needed."
	},
	{
		"src": "Es ist unklar, ob wir die Fachkr\u00e4fte bekommen werden.",
		"tgt": "It is not clear if we will get the specialist staff."
	},
	{
		"src": "Doch noch steht das Programm nicht g\u00e4nzlich: Denn die rund 1260 neuen Wohnungen, die sollten ohnehin gebaut werden.",
		"tgt": "But the program is not quite complete: because the approximately 1260 new homes are to be built anyway."
	},
	{
		"src": "Wie aber gleicht man den Verlust von weiteren rund 1300 g\u00fcnstigen Wohnungen aus, deren F\u00f6rderung in den n\u00e4chsten Jahren auslaufen wird?",
		"tgt": "But how do you balance out the loss of an additional 1300 low-cost homes (approximately), the grants for which will run out over the next few years?"
	},
	{
		"src": "Allein bis zum Jahr 2020 werden es 500 Wohnungen sein.",
		"tgt": "This will come to 500 homes even by 2020."
	},
	{
		"src": "Um das zu verhindern, so die planungspolitische Sprecherin Nicole Palm, sollten jetzt auslaufende Bindungen von der Stadt angekauft werden.",
		"tgt": "To prevent this, according to Nicole Palm, spokeswoman for planning policy, bonds that are about to mature should be purchased by the municipality."
	},
	{
		"src": "Au\u00dferdem m\u00fcsste dar\u00fcber nachgedacht werden, Wohnungen wieder zur\u00fcck in die Preisbindung zu holen.",
		"tgt": "In addition, thought must be given to putting homes back into a price maintenance scenario."
	},
	{
		"src": "Das ist in der Weststadt m\u00f6glich.",
		"tgt": "This is possible in the west of the city."
	},
	{
		"src": "Auf einen Schlag lie\u00dfe sich das Problem l\u00f6sen.",
		"tgt": "The problem could be solved in one fell swoop."
	},
	{
		"src": "Denn in der Weststadt laufen zum Jahresende Fristen aus.",
		"tgt": "This is because deadlines expire at the end of the year in the west of the city."
	},
	{
		"src": "Rund 1800 Wohnungen k\u00f6nnte man dort zur\u00fcck in die Preisbindung f\u00fcr g\u00fcnstige Wohnungen holen.",
		"tgt": "Around 1800 homes could then be moved into the managed price scheme for affordable housing."
	},
	{
		"src": "Nur: Das wollen die Eigent\u00fcmer, die Wohnungsbaugesellschaften nicht.",
		"tgt": "The only problem is that their owners, housing companies, are against it."
	},
	{
		"src": "Denn wird die Zahl der Sozialwohnungen in der Weststadt wieder drastisch erh\u00f6ht, entfernt man sich vom Ziel der sogenannten Durchmischung.",
		"tgt": "This would dramatically increase the amount of affordable housing in the west of the city, taking a step back from the target of \"blending\"."
	},
	{
		"src": "Eine Konzentration von Sozialschwachen in nur wenigen Stadtteilen soll es nicht mehr geben.",
		"tgt": "No longer are socially disadvantaged people to be concentrated in a small number of districts."
	},
	{
		"src": "Die Gr\u00fcnen rechnen damit, dass es noch Bewegung in der Diskussion geben wird.",
		"tgt": "The Greens think there's still room for manoeuvre in the discussions."
	},
	{
		"src": "Fraktionsvorsitzender Holger Herlitschke meint: \"F\u00fcr eine breite Mehrheit muss die CDU mit ins Boot.\"",
		"tgt": "Group chairman Holger Herlitschke thinks that \"the CDU will have to get into bed with us to reach a decent majority.\""
	},
	{
		"src": "Die habe sich zwar auf mehr Baupl\u00e4tze f\u00fcr Einfamilienh\u00e4user konzentriert.",
		"tgt": "However, they have focused on providing more building sites for detached homes."
	},
	{
		"src": "Was aber nicht hei\u00dft, dass nicht doch noch ein Kompromiss gefunden werden kann.",
		"tgt": "But that does not mean that it will be impossible to reach a compromise."
	},
	{
		"src": "Pok\u00e9mon Go, eine Jagd nach Gesundheit und Gl\u00fcck, die sich lohnt",
		"tgt": "Pok\u00e9mon Go a worthy hunt for health and happiness"
	},
	{
		"src": "Es ist faszinierend zuzusehen, wie sich die Welt ver\u00e4ndert.",
		"tgt": "It is fascinating to see how the world turns."
	},
	{
		"src": "Dass Teenager und Kind zum Spielen nicht mehr nach drau\u00dfen gehen, sondern es vielmehr bevorzugen, ihre Freizeit damit zu verbringen, auf Bildschirme zu starren, wurde im letzten Jahrzehnt von vielen beklagt.",
		"tgt": "That teenagers and children do not get outside to play any more, preferring to spend their free time looking at screens, has been the lament of many for the the past decade."
	},
	{
		"src": "Bei Pokemon Go geht es darum, Leute vom Sofa zu holen und aktiver werden zu lassen.",
		"tgt": "Pokemon Go is getting people off the couch and into some activity."
	},
	{
		"src": "Die Zeit am Bildschirm war anfangs auf den Fernseher, dann auf Videospiele und zuletzt auf Smartphones beschr\u00e4nkt.",
		"tgt": "Screen time was initially limited to the television then video games and more recently smartphones."
	},
	{
		"src": "Daher ist es toll zu sehen, dass sich Technologie und Aktivit\u00e4ten im Freien nicht gegenseitig ausschlie\u00dfen.",
		"tgt": "So it is great to see that technology and being active outdoors are not mutually exclusive."
	},
	{
		"src": "Ich beziehe mich dabei selbstverst\u00e4ndlich auf den Pok\u00e9mon Go-Wahn, eine App, die auf den Charakteren beruht, die zun\u00e4chst f\u00fcr die Videospiele in den 1990ern erschaffen wurden (sp\u00e4ter entstanden daraus eine Zeichentrickserie, Spielkarten und andere Spin-Offs).",
		"tgt": "I am of course referring to the craze that is Pok\u00e9mon Go, an app based on the characters first created for video games in the 1990s (it later spawned a cartoon series, playing cards and other spin offs)."
	},
	{
		"src": "Wie viele Ph\u00e4nomene der Popkultur sank das Interesse vor der Ver\u00f6ffentlichung des Spiels in den USA, Australien und Neuseeland Anfang Juli etwas.",
		"tgt": "Like many pop cultural phenomena it had gone off the boil somewhat before this new game was made available in the US, Australia and New Zealand in early July."
	},
	{
		"src": "Die Markteinf\u00fchrung in anderen L\u00e4ndern wurde durch die massive Nachfrage verschoben, die die Server \u00fcberlastete.",
		"tgt": "The launch in other countries was then delayed by the massive response, which overloaded servers."
	},
	{
		"src": "Innerhalb weniger Tage hatte Pok\u00e9mon Go mehr Benutzer als Tinder und fast so viele wie Twitter.",
		"tgt": "Within days, Pok\u00e9mon Go had more users than Tinder and nearly as many as Twitter."
	},
	{
		"src": "Wie funktioniert es?",
		"tgt": "So how does it work?"
	},
	{
		"src": "Kurz gesagt gehen die Spieler mit ihren Smartphones nach drau\u00dfen und suchen nach Pok\u00e9mons, die mit einem GPS nachverfolgt werden und, sobald sie einmal gefunden wurden, \"fotografiert\" (\u00fcber einen Screenshot auf dem Handy) oder \"gefangen genommen\" werden k\u00f6nnen.",
		"tgt": "In a nutshell, players on smartphones go out looking for Pok\u00e9mons, which are tracked with a GPS and, once found, can be 'photographed' (via a screenshot on your phone) or 'captured'."
	},
	{
		"src": "Eine Generation, die das Spiel spielte, als sie noch j\u00fcnger war, schloss sich dem Wahn an und sprang f\u00fcr die Suche vom Sofa.",
		"tgt": "A generation who played the game when younger have joined the craze, jumping off the couch for the search."
	},
	{
		"src": "In den USA f\u00fchrte das Spiel zu einem betr\u00e4chtlichen Anstieg an Schritten, die die \"durchschnittliche\" Person jeden Tag zur\u00fccklegt.",
		"tgt": "In the US, the game has led to a significant increase in the number of steps taken by the \"average\" person each day."
	},
	{
		"src": "Cardiogram, eine App f\u00fcr Apple Watch, die 35.000 Benutzer nachverfolgt, teilte der Washington Post vor kurzem mit, dass innerhalb von zwei Tagen nach Markteinf\u00fchrung des Spiels, die Anzahl der nachverfolgten Leute, die jeden Tag 30 Minuten trainieren, von 45 Prozent auf 53 Prozent ansprang.",
		"tgt": "Cardiogram, an app for the Apple Watch that tracks 35,000 users, told the Washington Post recently that within two days of the game launching, the number of people it tracked who did 30 minutes of exercise each day jumped from 45 per cent to 53 per cent."
	},
	{
		"src": "Das Unternehmen wei\u00df nicht, wer davon Pok\u00e9mon Go spielt - es sieht lediglich die Rohdaten zur Leistungssteigerung.",
		"tgt": "The company does not know who is playing Pok\u00e9mon Go - it just sees raw data on exercise levels."
	},
	{
		"src": "Viele \u00f6ffentliche Aufkl\u00e4rungskampagnen zur Gesundheit, die Leute dazu bringen wollen \"sich 30 Minuten Zeit zu nehmen,\" \"vom Sofa zu kommen\" und \"jeden Tag aktiv zu sein\" stie\u00dfen auf taube Ohren, weil viele \u00f6ffentliche Botschaften zur Gesundheit langweilig sind und von Leuten kommen, die elend aussehen.",
		"tgt": "Many public health campaigns to get people to \"find 30,\" \"get off the couch\" and \"be active everyday\" have fallen on deaf ears because most public health messages are boring and delivered by people who look miserable."
	},
	{
		"src": "Dennoch kann die Bedeutung von Sport nicht \u00fcberbewertet werden.",
		"tgt": "Yet the importance of exercise cannot be understated."
	},
	{
		"src": "Wer regelm\u00e4\u00dfig Sport treibt, reduziert seine Chancen, an Krebs oder Depressionen zu erkranken.",
		"tgt": "Those who exercise regularly reduce their chances of getting cancer or depression."
	},
	{
		"src": "K\u00f6rperliche Bet\u00e4tigung hilft bei der Gewichtskontrolle, hohem Blutdruck, Diabetes und einer langen Liste an Vorteilen, die zu lange ist, um sie hier anzuf\u00fchren.",
		"tgt": "Activity helps with weight management, high blood pressure, diabetes and a long list of benefits too long to list here."
	},
	{
		"src": "Aber das Wundervolle an Pok\u00e9mon Go ist, dass es die Leute dazu bringt, etwas im Freien zu tun, dass ihnen Spa\u00df macht.",
		"tgt": "But the beauty of Pok\u00e9mon Go is it gets people outside doing something they enjoy."
	},
	{
		"src": "Somit werden drei S\u00e4ulen der Gesundheit abgedeckt - Bewegung, frische Luft und Sonnenschein sowie Spa\u00df.",
		"tgt": "Thus you are covering three pillars of health - movement, fresh air and sunshine, and fun."
	},
	{
		"src": "Manche Leute schlie\u00dfen auf der Jagd sogar neue Freundschaften.",
		"tgt": "Some people are even making new friends on the hunt."
	},
	{
		"src": "Wie immer gibt es auch m\u00fcrrische Spielverderber, die sich immer \u00fcber etwas beschweren m\u00fcssen.",
		"tgt": "As usual there are po-faced killjoys looking for something to complain about."
	},
	{
		"src": "Und ja, jemand k\u00f6nnte gegen eine T\u00fcr laufen.",
		"tgt": "And yes somebody might walk into a door."
	},
	{
		"src": "Was soll's?",
		"tgt": "So what?"
	},
	{
		"src": "Es hat sich ein Durchbruch ereignet.",
		"tgt": "A breakthrough has occurred."
	},
	{
		"src": "Auch wenn Smartphone-Apps wie Fitbit bereits fr\u00fcher unsere Aktivit\u00e4t nachverfolgen konnten, gaben sie uns keinen Grund, Sport zu treiben, wie es dieses Spiel tut.",
		"tgt": "For while smartphone apps like Fitbit could previously track our activity, they didn't give us a reason to exercise like this game does."
	},
	{
		"src": "Das Neue wird seinen Reiz verlieren und die Verwendung wird mit der Zeit nachlassen.",
		"tgt": "The novelty will wear off and use will subside in due course."
	},
	{
		"src": "Aufgrund von Pokemons Erfolg wird es jedoch mehr Spiele geben, die Apps und virtuelle Realit\u00e4t mit dem Aktivwerden in der realen Welt vereinen werden und dabei vielen Leuten auf der Jagd helfen werden, aktiver, fitter und ges\u00fcnder zu sein.",
		"tgt": "However because of Pokmeon's success there will be more games that combine apps and virtual reality with being active in the real world, helping many people on the hunt to be more active, fitter and healthier."
	},
	{
		"src": "Lesen Sie Dr. Joes Blog auf www.drjoetoday.com",
		"tgt": "Read Dr Joe's blogs at www.drjoetoday.com"
	},
	{
		"src": "Simone Biles schafft Gold im Damenturnen",
		"tgt": "Simone Biles nails all-around gold in women's gymnastics"
	},
	{
		"src": "Vergessen Sie den Druck.",
		"tgt": "Forget the pressure."
	},
	{
		"src": "Vergessen Sie den Hype.",
		"tgt": "Forget the hype."
	},
	{
		"src": "Simone Biles ist auf all das immun.",
		"tgt": "Simone Biles is immune to all of it."
	},
	{
		"src": "Dynamisch auf dem Sprungpferd.",
		"tgt": "Dynamic on vault."
	},
	{
		"src": "M\u00fchelos auf dem Balken.",
		"tgt": "Effortless on beam."
	},
	{
		"src": "Atemberaubend auf dem Boden.",
		"tgt": "Jaw-dropping on floor."
	},
	{
		"src": "Auf ganzer Linie brilliant.",
		"tgt": "Brilliant all over."
	},
	{
		"src": "Und jetzt endlich auch Olympiasiegerin.",
		"tgt": "And now, finally, an Olympic champion."
	},
	{
		"src": "Die 19-j\u00e4hrige amerikanische Turnerin erklomm am Donnerstag zum Mehrkampftitel und vergr\u00f6\u00dferte die L\u00fccke zwischen sich und dem Rest der Welt vor aller Augen unter dem Scheinwerferlicht der Olympischen Spiele.",
		"tgt": "The 19-year-old American gymnast soared to the all-around title on Thursday, putting the gap between herself and the rest of the world on full display under the Olympic spotlight."
	},
	{
		"src": "Ihr Gesamtergebnis von 62,198 lag eindeutig vor der Silbermedaillengewinner und \"Final Five\"-Mannschaftskameradin Aly Raisman und der russischen Bronzemedaillengewinnerin Aliya Mustafina.",
		"tgt": "Her total of 62.198 was well clear of silver medalist and \"Final Five\" teammate Aly Raisman and Russian bronze medalist Aliya Mustafina."
	},
	{
		"src": "Die Amerikanerinnen Simone Biles turnt auf dem Schwebebalken w\u00e4hrend des Einzelmehrkampffinales der Frauen im Kunstturnen bei den Olympischen Sommerspielen in Rio de Janeiro 2016, Brasilien, Donnerstag.",
		"tgt": "United States' Simone Biles performs on the balance beam during the artistic gymnastics women's individual all-around final at the 2016 Summer Olympics in Rio de Janeiro, Brazil, Thursday."
	},
	{
		"src": "Biles ist die vierte heterosexuelle Amerikanerin, die einen Mehrkampftitel gewinnt und insgesamt die f\u00fcnfte, w\u00e4hrend sie ihren Ruf festigt, die Beste ihrer Generation oder sogar \u00fcberhaupt zu sein.",
		"tgt": "Biles became the fourth straight American woman to win the all-around title and fifth overall while cementing her reputation as the best of her generation and perhaps ever."
	},
	{
		"src": "Sie brach in Tr\u00e4nen aus, als ihr Endergebnis gezeigt wurde und ihre lange Reise in diesem Moment ein Ende fand.",
		"tgt": "She burst into tears when her final total was posted and her long journey to this moment ended."
	},
	{
		"src": "Dieser Erfolg stellt sie in dieselbe Liga wie einzigartige Athleten wie Michael Phelps, die ihre Sportarten zu neuen H\u00f6hen gebracht habe:",
		"tgt": "The achievement puts her in the same league as once-in-a-generation athletes like Michael Phelps who have taken their sports to new heights:"
	},
	{
		"src": "Biles hat die letzten drei Jahre ihre Sportart dominiert, 15 Weltmeistermedaillen - einschlie\u00dflich 10 Goldmedaillen - mit so erstaunlichen \u00dcbungen gewonnen, die eine Mischung aus Ehrgeiz und Pr\u00e4zision beinhalten, dass die Olympiasiegerin von 1984 Mary Lou Retton von ihr sagte, dass sie \"die beste Turnerin ist, die ich jemals gesehen habe.\"",
		"tgt": "Biles has spent the last three years dominating her sport, winning 15 world championship medals - including 10 gold - with routines so astonishing in their mix of ambition and precision that 1984 Olympic champion Mary Lou Retton called her \"the greatest gymnast I've ever seen.\""
	},
	{
		"src": "Es erwartete sie eine letzte Pr\u00fcfung in Brasilien, ein Wettbewerb, der nicht so sehr zwischen Biles und dem Rest der Athleten ging, sondern vielmehr zwischen ihr und einer Last \u00fcberdimensionierter Erwartungen.",
		"tgt": "One last test awaited in Brazil, a contest not so much between Biles and the rest of the field but between herself and the burden of oversized expectations."
	},
	{
		"src": "Nicht mit einer Handvoll Gold zur\u00fcck zur Familie in Spring, Texas zur\u00fcckkehren, w\u00e4re als Entt\u00e4uschung angesehen werden.",
		"tgt": "Anything less than heading back to her family's home in Spring, Texas, with a fistful of golds would be seen as a disappointment."
	},
	{
		"src": "Die Amerikanerinnen Simone Biles, links, und Aly Raisman umarmen sich, nachdem sie jeweils Gold und Silber im Einzelmehrkampffinale der Frauen im Kunstturnen bei den Olympischen Sommerspielen 2016 in Rio de Janeiro, Brasilien, Donnerstag, gewonnen haben",
		"tgt": "United States' Simone Biles, left, and Aly Raisman embrace after winning gold and silver respectively for the artistic gymnastics women's individual all-around final at the 2016 Summer Olympics in Rio de Janeiro, Brazil, Thursday, Aug."
	},
	{
		"src": "Biles holte die erste Medaille am Dienstag, w\u00e4hrend sie auf der Abschiedsfeier der sich in Ruhestand begehenden Mannschaftskoordinatorin Martha Karolyi als Ausrufezeichen diente.",
		"tgt": "Biles earned the first one on Tuesday while serving as the exclamation point to retiring national team coordinator Martha Karolyi's going away party."
	},
	{
		"src": "Obwohl Biles darauf bestand, w\u00e4hrend ihres langen Wegs auf die Spitze, nie die Zukunft geplant zu haben, ist das nicht wirklich wahr.",
		"tgt": "While Biles insisted she's never looked ahead during her long run at the top, that's not exactly true."
	},
	{
		"src": "Ein Teil ihrer Boden\u00fcbungen - die ihren typischen Tumbling Pass enthalten - ist auf lateinamerikanische Musik abgestimmt, das zuhause auf der Stra\u00dfe au\u00dferhalb der Olympiaarena in Rio passen w\u00fcrde.",
		"tgt": "A portion of her floor exercise routine - the one that includes her signature tumbling pass - is set to Latin music that would fit right at home in the street right outside the Rio Olympic Arena."
	},
	{
		"src": "Das ist kein Zufall.",
		"tgt": "It's not a coincidence."
	},
	{
		"src": "Dieses M\u00e4dchen, das von ihren Gro\u00dfeltern als kleines Kind adoptiert und von Trainerin Aimee Boormans Mutter w\u00e4hrend eines Schulausflugs in die Turnhalle entdeckt wurde, in der Boorman trainierte, wurde zur Kraft.",
		"tgt": "The girl adopted by her grandparents as a toddler and discovered by coach Aimee Boorman's mother during a field trip to the gym where Boorman was coaching has become a force."
	},
	{
		"src": "Sie hat seit dem Sommer 2013 keinen Mehrkampfwettbewerb mehr verloren, eine Siegesserie, die so lange anhalten wird, wie es Biles w\u00fcnscht.",
		"tgt": "She hasn't lost an all-around competition since the summer of 2013, a winning streak that should go for as long as Biles wants it to."
	},
	{
		"src": "Auch wenn Mustafina durch zwei Drehungen leicht f\u00fchrte, tr\u00fcgte das Bild.",
		"tgt": "Though Mustafina took a small lead through two rotations, it was a mirage."
	},
	{
		"src": "Schwebebalken und Bodenturnen - in denen Biles den Weltmeistertitel h\u00e4lt - lauerten.",
		"tgt": "Balance beam and floor exercise - where Biles is the defending world champion - lay in wait."
	},
	{
		"src": "Sie holte wieder mit 15,433 auf dem Schwebebalken wieder auf - und setzte mit einem 15,933 auf dem Boden noch einen darauf.",
		"tgt": "She went back in front with a 15.433 on beam - and capped it with a 15.933 on floor."
	},
	{
		"src": "Raisman umarmte sie sanft als sie ihr Endergbnis erwarteten - eine reine Formalit\u00e4t - und Tr\u00e4nen str\u00f6mten auf Biles gl\u00e4nzend roten, wei\u00dfen und blauen Eyeliner, als die Vision, die sie einst in ihrem Sammelbuch beschrieb, zur Wirklichkeit wurde.",
		"tgt": "Raisman hugged her gently as they awaited the final score - a mere formality - and tears appeared around Biles' glittery red, white and blue eyeliner when the vision she once wrote in a scrapbook became a reality."
	},
	{
		"src": "Die Leistung Raismans war eine Rache f\u00fcr das letzte Mal vor vier Jahren, als sie um den dritten Platz k\u00e4mpfte, aber die Bronzemedaille in einem Tiebrake an Mustafina ging.",
		"tgt": "Raisman's performance was a bit of revenge from four years ago, when she tied for third but lost the bronze to Mustafina on a tiebreaker."
	},
	{
		"src": "Dieses Mal hatte die 22-j\u00e4hrige Mannschaftskapit\u00e4nin, die von den Amerikanern \"Oma\" genannt wird, einen Vorsprung.",
		"tgt": "This time, the 22-year-old team captain the Americans call \"grandma\" was well ahead."
	},
	{
		"src": "Nach ihrer Boden\u00fcbung warf sie dem Publikum Kussh\u00e4nde zu, \u00fcberw\u00e4ltigt von einem Comeback, das manchmal zweifelhaft erschien.",
		"tgt": "She blew kisses to the crowd after her floor exercise, overcome by a comeback that at times seemed in doubt."
	},
	{
		"src": "Was Biles betrifft, so hat der sich schnell ausbreitende Tweet der 19-J\u00e4hrigen von Anfang dieser Woche eine ganz neue Bedeutung:",
		"tgt": "As for Biles, the 19-year-old's viral tweet from earlier this week now carries a whole new meaning:"
	},
	{
		"src": "Polizei: 3 Opfer in Serienm\u00f6rderfall beim Musikh\u00f6ren im Auto erschossen",
		"tgt": "Police: 3 victims in serial killer case shot while listening to music in car"
	},
	{
		"src": "Laut Polizeiberichten, die am Donnerstag ver\u00f6ffentlicht wurden, wurden zwei Frauen und ein 12-Jahre altes M\u00e4dchen erschossen, die in einem der t\u00f6dlichsten Angriffe seit einem Jahrzehnt im ersten Serienm\u00f6rderfall von Phoenix umgekommen sind, w\u00e4hrend sie sich im Auto unterhielten und Musik h\u00f6rten.",
		"tgt": "Two women and a 12-year-old girl who died in the deadliest attack in Phoenix's first serial killer case in a decade were sitting in a car talking and listening to music when they were shot, according to police reports released Thursday."
	},
	{
		"src": "Angela Rochelle Liner, Stefanie R. Ellis and Ellis Tochter Maleah wurden am 12. Juni erschossen, w\u00e4hrend das Auto in einer Einfahrt geparkt war, sagten die Beh\u00f6rden.",
		"tgt": "Angela Rochelle Liner, Stefanie R. Ellis and Ellis' daughter Maleah were shot on June 12 while the car was parked in a driveway, authorities said."
	},
	{
		"src": "Der T\u00e4ter feuerte acht Sch\u00fcsse aus einer Handfeuerwaffe, w\u00e4hrend er auf der Beifahrerseite des Autos stand und floh anschlie\u00dfend mit einem anderen Fahrzeug, ist im Bericht zu lesen.",
		"tgt": "The gunman fired as many as eight shots from a handgun while standing on the passenger side of the car then fled in another vehicle, the report states."
	},
	{
		"src": "Die Polizei teilte mit, dass der dreifache Mord nicht das Ergebnis eines Raub\u00fcberfalles gewesen zu sein scheint, da der Angreifer nicht die Handtaschen oder die $ 2.900 mitnahm, die sich im Besitz einer der erwachsenen Opfer befanden.",
		"tgt": "Police say the triple killing doesn't appear to have been the result of a robbery because the attacker didn't take purses or $2,900 in the possession of one of the adult victims."
	},
	{
		"src": "Der Polizeisprecher von Phoenix Sgt. Jonathan Howard sagte, dass die Schie\u00dferei die Ermittler dazu verleitete, einen n\u00e4heren Blick darauf zu werden, ob sie mit vier vorherigen Angriffen verbunden ist.",
		"tgt": "Phoenix police spokesman Sgt. Jonathan Howard said the shooting prompted investigators to look at whether it was tied to four earlier attacks."
	},
	{
		"src": "Insgesamt wurden vorwiegend in hispanischen Wohngegenden innerhalb von vier Monaten in neun Angriffen sieben Personen get\u00f6tet und zwei weitere verletzt.",
		"tgt": "In all, seven people have been killed and two others wounded in nine attacks in two predominantly Hispanic neighborhoods over a four-month period."
	},
	{
		"src": "\"Es geschieht in einer Wohngegend vor einem Haus,\" teilte Howard der KHPO, einer Tochtergesellschaft von CBS, Anfang des Monats mit.",
		"tgt": "\"It's occurring within a residential area in front of a home,\" Howard said to CBS affiliate KPHO earlier this month."
	},
	{
		"src": "Es wird angenommen, dass der Verd\u00e4chtige mehrere Fahrzeuge benutzt hat, einschlie\u00dflich eines braunen Nissans aus den sp\u00e4ten 1990ern, einem schwarzen BMW aus den sp\u00e4ten 1990ern und einem wei\u00dfen Cadillac oder Lincoln.",
		"tgt": "The suspect is believed to have used several vehicles, including as a late-1990s brown Nissan, a late-1990s black BMW and a white Cadillac or Lincoln."
	},
	{
		"src": "Die Ermittler weigerten sich, die Beweise offenzulegen, die sie zu der Schlu\u00dffolgerung gef\u00fchrt haben, dass die Angriffe verkn\u00fcpft sind und von dem selben M\u00f6rder begangen wurden.",
		"tgt": "Investigators have declined to reveal the evidence that led them to conclude the attacks are related and committed by the same killer."
	},
	{
		"src": "Ellis, 33, wurde aufgrund ihrer Verletzungen hospitalisiert und verstarb sp\u00e4ter.",
		"tgt": "Ellis, 33, was hospitalized for her injuries and later died."
	},
	{
		"src": "Liner, 31, und Ellis Tochter Maleah verstarben noch vor Ort.",
		"tgt": "Liner, 31, and Ellis' daughter Maleah died at the scene."
	},
	{
		"src": "Ein Zeuge teilte der Polizei mit, dass es f\u00fcr sie nicht ungew\u00f6hnlich war, in einem geparkten Auto zu sitzen und Musik zu h\u00f6ren.",
		"tgt": "A witness told police that it wasn't unusual for them to sit in a parked car listening to music."
	},
	{
		"src": "Die Beh\u00f6rden ver\u00f6ffentlichten auch einen Polizeibericht \u00fcber die Schie\u00dferei, die auf einen leeren Pickup-Truck eine halbe Stunde vor dem dreifachen Mord abzielte und von dem ausgegangen wird, dass es das Werk des Serienm\u00f6rders war.",
		"tgt": "Authorities also released a police report on a shooting that targeted an unoccupied pickup truck just a half-hour before the triple killing and is believed to have been the work of the serial killer."
	},
	{
		"src": "Ermittler fanden Patronenh\u00fclsen und sicherten eine Kugel aus dem Sitz sowie Kugelfragmente aus dem Motorraum.",
		"tgt": "Investigators found bullet casings and recovered a bullet from a seat and bullet fragments from the engine compartment."
	},
	{
		"src": "Mutter eines 6-J\u00e4hrigen mit Mikrozephalie: \"Es wird besser\"",
		"tgt": "Mother of 6-year-old with microcephaly: \"It gets better\""
	},
	{
		"src": "Wie die meisten 6-J\u00e4hrigen liebt Edmund Picciuto das Singen, Spielzeuge und nat\u00fcrlich seine Mutter.",
		"tgt": "Like most six-year-olds, Edmund Picciuto loves singing, toys and, of course, his mother."
	},
	{
		"src": "Aber wie die wenigsten seiner Altergenossen hat Edmund Mikrozephalie, das Ergebnis einer genetischen St\u00f6rung, \u00fcber die seine Mutter Elizabeth Picciuto w\u00e4hrend ihrer Schwangerschaft nichts wusste.",
		"tgt": "But unlike most of his peers, Edmund has microcephaly, the result of a genetic disorder his mom Elizabeth Picciuto didn't know about while pregnant."
	},
	{
		"src": "Als er das erste Mal nach Hause kam, war mein erster Gedanke, Ich schaffe das nicht.",
		"tgt": "When he first came home my initial thought was, I can't do this."
	},
	{
		"src": "Ich schaffe das nicht.",
		"tgt": "I can't do this."
	},
	{
		"src": "Darauf habe ich mich nicht eingelassen.",
		"tgt": "I didn't sign up for this."
	},
	{
		"src": "Was \u00fcberhaupt nicht stimmt -- nat\u00fcrlich hat man sich darauf eingelassen,\" sagte sie.",
		"tgt": "Which is not true at all -- of course you sign up for it,\" she said."
	},
	{
		"src": "Ihrem Ehemann Vincent und ihr wurde mitgeteilt, dass Edmund sie unter Umst\u00e4nden nie erkennen wird k\u00f6nnen und, dass er m\u00f6glicherweise nicht einmal \u00fcberleben wird.",
		"tgt": "She and her husband, Vincent, were told Edmund might never recognize them, and that he might not even survive."
	},
	{
		"src": "Manche \u00c4rzte gingen sogar so weit, dass sie vorschlugen, ihn zu institutionalisieren.",
		"tgt": "Some doctors went as far as suggesting he be institutionalized."
	},
	{
		"src": "\"Meine erste Antwort darauf war 'Ich wusste nicht, dass das Leute noch immer machen,'\" erkl\u00e4rte Picciuto.",
		"tgt": "\"My first response was 'I didn't think people did that anymore,'\" Picciuto explained."
	},
	{
		"src": "Edmund kann mit Hilfe einer Gehhilfe laufen.",
		"tgt": "Edmund walks with the help of a walker."
	},
	{
		"src": "Edmund konnte bis zu seinem dritten Lebensjahr weder sitzen noch krabbeln und er kann noch immer nicht sprechen.",
		"tgt": "Edmund didn't sit up or crawl until he was three, and he still doesn't talk."
	},
	{
		"src": "Aber er macht langsam Fortschritte.",
		"tgt": "But he's slowly meeting some milestones."
	},
	{
		"src": "Er kann mit Unterst\u00fctzung laufen und Fahrradfahren.",
		"tgt": "He's walking with help, and riding a bike."
	},
	{
		"src": "Er liebt es auch, mit seinen zwei Br\u00fcdern zu spielen und zu singen.",
		"tgt": "He also loves playing with his two brothers, and singing."
	},
	{
		"src": "Elizabeth zeigt die Zeichensprache, die sich Edmund f\u00fcr \"Bitte sing mir etwas vor\" ausgedacht hat.\"",
		"tgt": "Elizabeth demonstrates the sign language Edmund made up for \"please sing to me.\""
	},
	{
		"src": "\"Wir bringen ihm Zeichensprache bei,\" erz\u00e4hlte Picciuto CBS News.",
		"tgt": "\"We're teaching him sign language,\" Picciuto told CBS News."
	},
	{
		"src": "Aber es ist keine typische Zeichensprache -- sagt sie. Edmund hat einige Zeichen alleine erfunden.",
		"tgt": "But it's not just typical sign language -- she says Edmund has invented some of his own signs."
	},
	{
		"src": "Mikrozephalie hat eine Vielzahl an Ursachen: genetische wie bei Edmund sowie Infektionen mit Viren wie Masern oder dem Zikavirus w\u00e4hrend der Schwangerschaft.",
		"tgt": "Microcephaly can arise from a number of different conditions: genetic ones like Edmund's, and infections during pregnancy from viruses like measles and Zika."
	},
	{
		"src": "Die Symptome und Prognosen k\u00f6nnen stark variieren.",
		"tgt": "Symptoms and prognosis can vary widely."
	},
	{
		"src": "Es ist noch zu fr\u00fch zu sagen, wie es das Leben der mit dem Zikavirus Infizierten beeinflussen wird.",
		"tgt": "It's too early to tell how it will affect the lives of those infected with Zika."
	},
	{
		"src": "Picciuto erinnert sich an den emotionalen Preis einer ungewissen Zukunft.",
		"tgt": "Picciuto remembers the emotional toll of an uncertain future."
	},
	{
		"src": "Ich fragte st\u00e4ndig, was wird geschehen?",
		"tgt": "I kept saying, what's going to happen?"
	},
	{
		"src": "Was wird geschehen?",
		"tgt": "What's going to happen?"
	},
	{
		"src": "Und sie wei\u00df es noch immer nicht wirklich.",
		"tgt": "And she still doesn't really know."
	},
	{
		"src": "Ich habe schon seit langer Zeit nicht mehr nach der Prognose gefragt, weil ich nicht erwarte, dass sie mir jemand wirklich sagen kann.",
		"tgt": "I actually haven't asked for a prognosis in forever, because I don't expect anyone to really be able to tell me."
	},
	{
		"src": "Aber Picciuto hat einen hoffnungsvollen Ratschlag f\u00fcr M\u00fctter von S\u00e4uglingen mit Geburtssch\u00e4den, die durch den Zikavirus verursacht wurden.",
		"tgt": "But Picciuto has hopeful advice for the mothers of babies with birth defects from Zika."
	},
	{
		"src": "Es wird besser.",
		"tgt": "It gets better."
	},
	{
		"src": "Sie wissen, dass es f\u00fcr Sie besser werden wird.",
		"tgt": "You know it will get better for you."
	},
	{
		"src": "Sie werden Ihr Kind lieben und Ihr Kind wird Sie lieben.",
		"tgt": "You will love your child, and your child will love you."
	},
	{
		"src": "Heftige Regenf\u00e4lle, \u00dcberschwemmung gibt Anlass zu Rettungen in Louisiana, Mississippi",
		"tgt": "Heavy rain, flooding prompts rescues in Louisiana, Mississippi"
	},
	{
		"src": "Heftige Regenf\u00e4lle und gro\u00dffl\u00e4chige \u00dcberschwemmungen in Louisiana zwangen den Gouverneur dazu, am Freitag den Notstand auszurufen. Es wird den ganzen Samstag \u00fcber mit mehr Regenf\u00e4llen gerechnet.",
		"tgt": "Heavy rain and widespread flooding in Louisiana lead the governor to declare a state of emergency on Friday, with more rain expected over the state through Saturday."
	},
	{
		"src": "Zahlreiche Fl\u00fcsse im S\u00fcdosten Louisianas und dem S\u00fcden des Mississippis \u00fcberfluteten ihre Ufer und drohten mit gro\u00dffl\u00e4chigen \u00dcberschwemmungen nach extremen Regenf\u00e4llen, berichtete der Nationale Wetterdienst.",
		"tgt": "Numerous rivers in southeast Louisiana and southern Mississippi were overflowing their banks and threatening widespread flooding after extreme rainfall, the National Weather Service reported."
	},
	{
		"src": "Der Gouverneur von Louisiana John Bel Edwards teilte mit, dass Staatsbeamte im st\u00e4ndigen Kontakt mit den \u00f6rtlichen Beh\u00f6rden stehen und Hilfe zu den betroffenen Gemeinden bereits unterwegs sei.",
		"tgt": "Louisiana Gov. John Bel Edwards said state officials are in constant contact with local officials, and assistance is already on the move to affected parishes."
	},
	{
		"src": "Mike Steele, ein Sprecher f\u00fcr das Office of Homeland Security and Emergency Preparedness des Gouverneurs, teilte mit, dass sich die Anfragen f\u00fcr Hochwasserfahrzeuge, Boote und Sands\u00e4cke mehrten.",
		"tgt": "Mike Steele, a spokesman for the Governor's Office of Homeland Security and Emergency Preparedness, said requests were coming in for high-water vehicles, boats and sandbags."
	},
	{
		"src": "Steele sagte, dass allein die Gemeinde Tangipahoa zehntausend Sands\u00e4cke angefordert h\u00e4tte.",
		"tgt": "Steele said Tangipahoa Parish alone requested tens of thousands of sandbags."
	},
	{
		"src": "Ein \u00dcberschwemmungswarnsystem wird \u00fcber weite Teile im S\u00fcden Louisianas bis Samstag eingesetzt.",
		"tgt": "A flood watch remains in effect until Saturday across most of south Louisiana."
	},
	{
		"src": "Der Wetterdienst lie\u00df verlautbaren, dass in diesem Gebiet zus\u00e4tzliche 3 bis 5 Zoll an Regen fallen k\u00f6nnten.",
		"tgt": "The weather service said in a statement that an additional 3 to 5 inches could fall over the area."
	},
	{
		"src": "Im S\u00fcden Alabamas wurde am Freitag ein Flutfr\u00fchwarnsystem eingesetzt, w\u00e4hrend es im Gebiet Mobile weiterhin regnete.",
		"tgt": "In south Alabama, a flood watch was in effect Friday as rain continued in the Mobile area."
	},
	{
		"src": "Der Fluss Comite in der N\u00e4he Baton Rouges und der Fluss Amite in der N\u00e4he Denham Springs, die sich beide in Louisiana befinden, werden aller Wahrscheinlichkeit nach \u00fcber das Wochenende Rekordpegel erreichen.",
		"tgt": "The Comite River near Baton Rouge and Amite River near Denham Springs, both in Louisiana, were predicted to set record crests over the weekend."
	},
	{
		"src": "Der Metereologe Alek Krautmann sagt, dass beide Fl\u00fcsse viele H\u00e4user in den Vorortgegenden nahe Baton Rouge \u00fcberschwemmen k\u00f6nnten.",
		"tgt": "Forecaster Alek Krautmann said both rivers could flood many houses in suburban areas near Baton Rouge."
	},
	{
		"src": "Er sagte auch, dass eine stromabw\u00e4rts gerichtete \u00dcberschwemmung in Ascension Parish eine Gefahr darstellt, da diese \u00fcber die getretenen Fl\u00fcsse nur langsam in den Lake Maurepas flie\u00dfen werden.",
		"tgt": "He also said that flooding downstream in Ascension Parish is a threat, as those swollen rivers will be slow to drain into Lake Maurepas."
	},
	{
		"src": "Der Fluss Tickfaw, s\u00fcdlich der Mississippi Staatsgrenze in Liverpool, Louisiana, erreichte am Freitag bereits um 09.00 den h\u00f6chsten Stand, der jemals aufgezeichnet wurde.",
		"tgt": "The Tickfaw River, just south of the Mississippi state line in Liverpool, Louisiana, was already at the highest level ever recorded at 9 a.m. Friday."
	},
	{
		"src": "Rettungsteams zupften noch immer Leute aus dem Flutwasser in den Bezirken Amite und Wilkinson im S\u00fcdwesten von Mississippi.",
		"tgt": "Rescuers were still plucking people from floodwaters in Amite and Wilkinson counties in southwest Mississippi."
	},
	{
		"src": "Leroy Hansford, seine Frau und sein Stiefsohn befanden sich unter denjenigen, die am Freitag in der N\u00e4he von Gloster gerettet wurden.",
		"tgt": "Leroy Hansford, his wife and stepson were among those rescued earlier Friday near Gloster."
	},
	{
		"src": "Hansford, 62, sagt, dass Wasser von Beaver Creek, das normalerweise mehr als 400 Fu\u00df von seinem Haus entfernt liegt, \u00fcber Nacht stark anstieg.",
		"tgt": "Hansford, 62, says waters from Beaver Creek, which is normally more than 400 feet away from his house, rose quickly overnight."
	},
	{
		"src": "Er sagte, dass ihn ein weiterer Stiefsohn, der in der N\u00e4he wohnt, gewarnt h\u00e4tte.",
		"tgt": "He said another stepson who lives nearby alerted him."
	},
	{
		"src": "\"Wir sind aufgewacht und das Wasser str\u00f6mte und str\u00f6mte herein,\" sagte Hansford.",
		"tgt": "\"We woke up and the water kept on coming,\" Hansford said."
	},
	{
		"src": "Es erreichte meine Taille.",
		"tgt": "It came up to my waist."
	},
	{
		"src": "Seine Frau sagte Hansford, dass sie in den 48 Jahren, in denen sie dort lebte, noch nie einen solchen Hochstand des Flusses gesehen h\u00e4tte.",
		"tgt": "His wife told Hansford that it's the highest she's seen the creek in the 48 years she's lived there."
	},
	{
		"src": "Hansford sagte, dass er und seine Familienmitglieder alle Behinderungen h\u00e4tten und er der Einzige w\u00e4re, der schwimmen kann.",
		"tgt": "Hansford said he and his family members all have disabilities, and he's the only one who can swim."
	},
	{
		"src": "Hansford sagte, dass Nothelfer alle drei in einem gro\u00dfen Milit\u00e4r-LKW gerettet h\u00e4tten und sie zu der n\u00e4chsten Feuerwache in Gloster gebracht h\u00e4tten, wo sie bis zum Freitag untergebracht waren.",
		"tgt": "Hansford said emergency workers rescued all three in a large military-style truck and took them to the fire station in Gloster, where they were sheltering Friday."
	},
	{
		"src": "Krautmann sagte, dass die \u00dcberschwemmung \"sich schnell ausgebreitet\" hatte, da es weiterhin schwere Regenf\u00e4lle gab und, dass die Beh\u00f6rden Evakuierungsanweisungen in Betracht z\u00f6gen.",
		"tgt": "Krautmann says flooding is \"quickly becoming widespread\" as heavy rains continue, saying officials are considering evacuation orders."
	},
	{
		"src": "Laut Krautmann meldete ein Beobachter in der N\u00e4he von Livingstone von Mitternacht bis Freitag morgen von 13,75 Zoll Regen.",
		"tgt": "Krautmann says one observer near Livingston reported 13.75 inches of rain from midnight to Friday morning."
	},
	{
		"src": "Krautmann sagte, dass der Boden durch die Regenf\u00e4lle seit Mittwoch erheblich vollgesogen sei.",
		"tgt": "Krautmann said the ground was heavily saturated by rainfall since Wednesday."
	},
	{
		"src": "Die Beh\u00f6rden gaben an, dass schwere Regenf\u00e4lle und Stra\u00dfen\u00fcberschwemmungen die Rettung von Einwohnern aus ihren H\u00e4usern in Tangipahoa Parish und Unterrichtsausfall in f\u00fcnf Schulbezirken verursachten.",
		"tgt": "Heavy rain and street flooding prompted the rescue of residents from their homes in Tangipahoa Parish and the cancellation of classes in five school districts, authorities said."
	},
	{
		"src": "Der CBS-Tochtersender WWL berichtete, dass eine Beigeordnete in Tangipahoa 200 \u00fcberschwemmte H\u00e4user angab.",
		"tgt": "CBS affiliate WWL reports that an alderwoman in Tangipahoa said 200 homes flooded."
	},
	{
		"src": "Die Einwohner wurden in zwei Kirchen evakuiert, die jetzt beide \u00fcberschwemmt wurden.",
		"tgt": "Residents had been evacuated to two churches but both are now flooding."
	},
	{
		"src": "Der Vorsteher der Gemeinde Robby Miller sagte, dass die Beh\u00f6rden 72 Leute und sieben Haustiere gerettet h\u00e4tten, die vom Hochwasser angesp\u00fclt wurden.",
		"tgt": "Parish President Robby Miller said authorities rescued 72 people and seven pets stranded by high water."
	},
	{
		"src": "In den St\u00e4dten Amite und Hammond wurden Notunterk\u00fcnfte eingerichtet, um die Evakuierten zu beherbergen.",
		"tgt": "Shelters have been opened in the town of Amite and the city of Hammond to house those who were evacuated."
	},
	{
		"src": "\"Sobald das Wasser anf\u00e4ngt zur\u00fcckzugehen, werden sie wieder in ihre H\u00e4user zur\u00fcckgehen k\u00f6nnen,\" sagte er.",
		"tgt": "\"They will be allowed to return home once the water starts to recede,\" he said."
	},
	{
		"src": "In der Stadt Hammond der Gemeinde Tangipahoa wurden fast zwei dutzend Stra\u00dfen aufgrund des Hochwassers geschlossen und Sands\u00e4cke f\u00fcr die Bewohner zur Mitnahme bereitgestellt, die hoffen, das Wasser aus ihren H\u00e4usern und Gesch\u00e4ften halten zu k\u00f6nnen.",
		"tgt": "In the Tangipahoa Parish city of Hammond, close to two dozen streets were closed because of high water, and sandbags were made available for pickup by residents hoping to keep water out of homes and businesses."
	},
	{
		"src": "\"Die letzte gro\u00dfe \u00dcberschwemmung, die wir hatten, war im M\u00e4rz,\" sagte Lacy Landrum von der Stadtverwaltung.",
		"tgt": "\"The last major flood we had was in March,\" said city administrator Lacy Landrum."
	},
	{
		"src": "Dies scheint ein \u00e4hnlicher Vorfall zu werden.",
		"tgt": "This one is on track to be a similar event."
	},
	{
		"src": "In Mississipp sagte der Notfallmanager Rupert Lacy des Harrison Countys, dass es an der Golfk\u00fcste weiterhin regnete.",
		"tgt": "In Mississippi, Harrison County Emergency Manager Rupert Lacy said steady rain continued on the Gulf Coast."
	},
	{
		"src": "Laut seinen Angaben sollen eine Handvoll H\u00e4user am Donnerstag als \u00fcberschwemmt gemeldet worden sein, aber am Freitag wurden bis jetzt keine gemeldet.",
		"tgt": "He said a handful of houses were reported as flooded Thursday, but none have been reported so far Friday."
	},
	{
		"src": "Keith Townson, Manager bei Shopper Value Foods in Amite, lebt bereits seit 40 Jahren in der Gegend.",
		"tgt": "Keith Townson, manager of Shopper Value Foods in Amite, has lived in the area for 40 years."
	},
	{
		"src": "\"Ich habe Wasser an Orten gesehen, an denen ich es nie zuvor gesehen habe,\" sagte Townson, \"und es kommt noch immer.\"",
		"tgt": "\"I've seen water in some places I have never seen before,\" Townson said, \"and it's still coming down.\""
	},
	{
		"src": "Mahaj Brown, 6, \"von Kugeln durchl\u00f6chert\", \u00fcberlebt Schie\u00dferei in Philadelphia",
		"tgt": "Mahaj Brown, 6, \"riddled with bullets,\" survives Philadelphia shooting"
	},
	{
		"src": "Die Polizei teilt mit, dass der 6-j\u00e4hrige Junge in Philadelphia angeschossen wurde, diese Woche bereits das zweite Mal, dass ein 6-j\u00e4hriges Kind angeschossen wird.",
		"tgt": "Police say a 6-year-old boy has been shot in Philadelphia, marking the second shooting of a 6-year-old in the city this week."
	},
	{
		"src": "Die Gro\u00dfeltern des Jungen identifizierten ihn f\u00fcr CBS Philadelphia als Mahaj Brown.",
		"tgt": "The child's grandparents identified him to CBS Philadelphia as Mahaj Brown."
	},
	{
		"src": "Die Gro\u00dfeltern gaben an, dass Brown mehrere Schussverletzungen erlitt, einschlie\u00dflich in der Lende, Bein, Arm und Bauch, aber dass er bei seinem Transport ins Krankenhaus bei Bewusstsein war.",
		"tgt": "The grandparents say Brown suffered multiple gunshot wounds, including in his groin, leg, arm and abdomen, but was awake when he was transported to the hospital."
	},
	{
		"src": "\"Er hat viel durchgemacht, sein kleiner K\u00f6rper war von Kugeln durchl\u00f6chert,\" teilte seine Gro\u00dfmutter Delores Melendez dem Sender mit.",
		"tgt": "\"He just took a lot, his little body was riddled with bullets,\" his grandmother Delores Melendez tells the station."
	},
	{
		"src": "Ich kann das einfach nicht glauben.",
		"tgt": "I just can't believe it."
	},
	{
		"src": "Der Zustand des Jungen wurde in einem Krankenhaus als kritisch eingestuft und er musste sich mehreren Operationen unterziehen.",
		"tgt": "The boy is listed in critical condition at a hospital and has undergone several surgeries."
	},
	{
		"src": "Die Familie des Jungen teilte dem Sender mit, dass er voraussichtlich wieder genesen wird.",
		"tgt": "Family tells the station he is expected to recover."
	},
	{
		"src": "Er h\u00e4tte die erste Klasse in einer \u00f6rtlichen Grundschule beginnen sollen.",
		"tgt": "He was set to start first grade at a local elementary school."
	},
	{
		"src": "Brown war einer von vier Personen die in Germantown angeschossen wurden.",
		"tgt": "Brown was among four people shot in the Germantown section."
	},
	{
		"src": "Ebenfalls angeschossen wurden drei M\u00e4nner: zwei im Alter von 29 Jahren und ein 32-J\u00e4hriger.",
		"tgt": "Also shot were three men: two 29-year-olds and one 32-year old."
	},
	{
		"src": "Einer der 29-j\u00e4hrigen M\u00e4nner ist im kritischen Zustand; die anderen zwei Opfer sind laut CBS Philadelphia im stabilen Zustand.",
		"tgt": "One of the 29-year-old men was reported in critical condition; the other two victims were listed in stable condition, according to CBS Philadelphia."
	},
	{
		"src": "Der Junge wurde auf dem Vordersitz eines Autos zusammen mit dem 29-J\u00e4hrigen, der sich in einem kritischen Zustand befindet, angeschossen aufgefunden, berichtet der Sender.",
		"tgt": "The child was found shot in the front seat of a car along with the 29-year-old in critical condition, the station reports."
	},
	{
		"src": "Die anderen zwei Opfer befanden sich nicht im Auto und die Polizei ermittelt gerade, ob sich unter einem der verletzten M\u00e4nner der T\u00e4ter befinden k\u00f6nnte.",
		"tgt": "The other two victims were not in the car and police are investigating whether any of the wounded men could be a shooter."
	},
	{
		"src": "Ermittler teilten CBS Philadelphia mit, dass es anscheinend zu einem Kreuzfeuer zwischen mehreren Sch\u00fctzen gekommen sei.",
		"tgt": "Investigators tells CBS Philadelphia it appears there was crossfire between multiple gunmen."
	},
	{
		"src": "Patronenh\u00fclsen f\u00fcr Sturmgewehre, die zu verschiedenen Sturmgewehren zur\u00fcckverfolgt wurden, \u00fcbers\u00e4hten den Tatort.",
		"tgt": "Assault weapon-style shell casings, traced to different assault style weapons, littered the scene."
	},
	{
		"src": "Es scheint, dass es sich hierbei eindeutig um einen andauernden Kampf gehandelt habe.",
		"tgt": "It appears that this was definitely an ongoing battle."
	},
	{
		"src": "Auf der Stra\u00dfe, auf beiden Seiten des Gehwegs, befanden sich H\u00fclsen.",
		"tgt": "There were casings in the street, on both sides of the sidewalk."
	},
	{
		"src": "So scheint es hier mehrere bewaffnete K\u00e4mpfer gegeben zu haben, die sehr aktiv beteiligt waren,\" teilte Polizeihautpmann Anthony Ginaldi der Polizei in Philadelphia dem Sender mit.",
		"tgt": "So it appears that there were multiple armed combatants out here and that they were actively engaged,\" Philadelphia police Captain Anthony Ginaldi told the station."
	},
	{
		"src": "Es wurden auch mehrere H\u00e4user und Fahrzeuge in dem Gebiet getroffen.",
		"tgt": "Multiple houses and vehicles in the area were also struck."
	},
	{
		"src": "Es kam zu keinen Festnahmen und die Polizei \u00fcberpr\u00fcft derzeit Berichten zufolge das \u00dcberwachungsvideo.",
		"tgt": "No arrests have been made and police are reportedly reviewing surveillance video."
	},
	{
		"src": "Am Dienstag wurde ein weiteres 6-j\u00e4hriges M\u00e4dchen durch einen Querschl\u00e4ger am Arm getroffen, als sie vor ihrem Haus in der Wohngegend der West Oak Lane spielte.",
		"tgt": "Another 6-year-old, a girl, was hit in her arm by a stray bullet Tuesday while playing in front of her home in the West Oak Lane neighborhood."
	},
	{
		"src": "Sie erholt sich und die Polizei sucht noch nach einem Verd\u00e4chtigen.",
		"tgt": "She is recovering, and police are still searching for a suspect."
	},
	{
		"src": "Weshalb wir Simone, Gabby und Laurie brauchen",
		"tgt": "Why we need Simone, Gabby and Laurie"
	},
	{
		"src": "Das ist, was ich mir unter der Frauenolympiamannschaft im Turnen vorstelle und das aus mehr als einem Grund.",
		"tgt": "That's what I call this year's Women's Olympic Gymnastics Team and for more reasons than one."
	},
	{
		"src": "Erstens bin ich seit 1984 bei jeder Sommerolympiade dabei und die USA waren noch nie so dominant.",
		"tgt": "First, I have been to every Summer Olympics since 1984 and the USA has never been so dominant."
	},
	{
		"src": "Und zweitens: Diese Mannschaft hat drei Turnerinnen, Simone Biles, Gabby Douglas und Lauren \"Laurie\" Hernandez, die f\u00fcr viele junge M\u00e4dchen anderer Hautfarbe inspirierend wirkten.",
		"tgt": "And second: This team features three gymnasts, Simone Biles, Gabby Douglas and Lauren \"Laurie\" Hernandez, who have been inspiring so many young girls of color."
	},
	{
		"src": "Die Struktur dieser Mannschaft, die Aly Raisman, die J\u00fcdin ist und Madison Kocian, die Katholikin ist, abrunden, macht jeden stolz.",
		"tgt": "The make-up of this team, rounded out by Aly Raisman, who is Jewish, and Madison Kocian, who is Catholic, is making everyone proud."
	},
	{
		"src": "Diese Mannschaft spiegelt endlich die USA wider.",
		"tgt": "This team looks, finally, like America."
	},
	{
		"src": "Es hat die schwarze und hispanische weibliche Anwesenheit an der Spitze dieser Sportart verfestigt.",
		"tgt": "It also has solidified the black and Latina female presence at the top of this sport."
	},
	{
		"src": "In den letzten vier Jahren war die Nummer eins unter der weiblichen Turnerinnen eine Afro-Amerikanerin.",
		"tgt": "For the past four years, the number one female gymnast has been African-American."
	},
	{
		"src": "Letztes Jahr waren Simone und Gabby #1 und #2.",
		"tgt": "Last year, Simone and Gabby were #1 and #2."
	},
	{
		"src": "Das zeigt St\u00e4rke.",
		"tgt": "This is powerful."
	},
	{
		"src": "Bei den letzten Olympischen Spielen war Gabby Douglas eine \u00fcberraschende Olympiagewinnerin und Amerika jubelte.",
		"tgt": "Last Olympics, Gabby Douglas was a surprise Olympic champion, and America cheered."
	},
	{
		"src": "Jetzt war die Welt in der Lage, Zeuge der unglaublichen Leistung der dreifachen Weltmeisterin Simone Biles, Douglas und Laurie Hernandez zu sein, wie sie unerwartete, doch meisterhafte Gymastikroutinen lieferten.",
		"tgt": "Now the world has been able to witness the incredible performances of three-time World Champion Simone Biles, Douglas and Laurie Hernandez delivering the unexpected, yet masterful gymnastics routines."
	},
	{
		"src": "Am Donnerstag wurde Simone die vierte, heterosexuelle Amerikanerin, die bei einer individuellen Mehrkampfveranstaltung f\u00fcr Frauen Gold gewann.",
		"tgt": "On Thursday, Simone became the fourth straight American to win gold in the women's individual all-around event."
	},
	{
		"src": "Mannschaftmitglied Aly Raisman gewann Silber.",
		"tgt": "And teammate Aly Raisman earned silver."
	},
	{
		"src": "Wir erleben die Spitze dieser Sportart, aber so sehen Turnklassen im ganzen Land nicht aus.",
		"tgt": "We are witnessing the top of the sport, but it does not look like this at gymnastics classes across the country."
	},
	{
		"src": "Simone, Gabby und Laurie schlugen alle den gleichen Weg wie Aly und Madison ein, um es ins olympische Team zu schaffen.",
		"tgt": "Simone, Gabby and Laurie all took the same path as Aly and Madison to make the Olympic team."
	},
	{
		"src": "Sie sind die \"Letzten F\u00fcnf\", weil die n\u00e4chste Olympiamannschaft nur vier Turnerinnen in der Mannschaft haben wird. Au\u00dferdem ist das das letzte Jahr mit Marta Karolyi als Trainerin.",
		"tgt": "They are the \"Final Five\" because the next Olympic gymnastics team will only have four gymnasts on the team, and this is Marta Karolyi's last year coaching."
	},
	{
		"src": "Aber die Realit\u00e4t sieht so aus, dass Turnen ein teurer Sport ist und Turner in erster Linie in privaten Turnvereinen, die von Eltern aufrechterhalten werden, die f\u00fcr die Trainings-, Einrichtungs-, Reise- Bekleidungs-, Wettbewerbs- und Hotelkosten (f\u00fcr die Trainer und deren Turner und Familien) aufkommen. Die Liste l\u00e4sst sich beliebig fortsetzen.",
		"tgt": "But the reality is that gymnastics is an expensive sport, and gymnasts primarily train in private gymnastics clubs that are maintained by parents paying the cost of the training, facility, travel, uniforms, competition fees, hotel fees (for the coaches and their gymnasts and families) and the list goes on."
	},
	{
		"src": "Die Mehrheit dieser Turnvereine liegen in wohlhabenden Vororten, die das Gesch\u00e4ft unterst\u00fctzen k\u00f6nnen.",
		"tgt": "Most of these gymnastics clubs are located in affluent suburban neighborhoods that can support the business."
	},
	{
		"src": "In diesen Vereinen erhalten die Turner ihr gesamtes Training und das ist f\u00fcr die Familien ein teures und langfristiges Engagement.",
		"tgt": "These clubs are where the gymnasts get all of their training, and it's a costly and long-term commitment for the gymnasts' families."
	},
	{
		"src": "Aimee Boorman, Trainerin von Simone Biles, und Maggie Haney, Trainerin von Laurie Hernandez, haben beide ihre Athleten trainiert, seitdem sie mit dem Turnen angefangen haben.",
		"tgt": "Aimee Boorman, coach of Simone Biles, and Maggie Haney, coach of Laurie Hernandez, have both coached their athletes since they started in gymnastics."
	},
	{
		"src": "Wir m\u00fcssen den Gemeinden aun unz\u00e4hligen, jungen M\u00e4dchen, die von Simone, Gabby und Laurie inspiriert werden, ein leistbareres und leichter zug\u00e4ngliches Turntrainung erm\u00f6glichen.",
		"tgt": "We must bring more affordable and accessible gymnastics training to the communities of countless young girls who are inspired by Simone, Gabby and Laurie."
	},
	{
		"src": "Ich habe meine Turnstiftung von 20 Jahren gegr\u00fcndet.",
		"tgt": "I founded my gymnastics foundation 20 years ago."
	},
	{
		"src": "Bei meinen Veranstaltungen haben wir kostenloses und erschwingliches Turnen in Harlem f\u00fcr \u00fcber 15.000 urbane Jugendliche (vor allem schwarze und hispanische) geboten und nationale und internationale Sieger trainiert.",
		"tgt": "At my organizations, we have provided free and low-cost gymnastics, based in Harlem, for over 15,000 urban youth (primarily black and Hispanic) and have trained national and international champions."
	},
	{
		"src": "Im September werden wir nach Detroit (meine Heimatstadt) expandieren, um der Jugend hochqualitatives Turnen zu bieten, die die M\u00f6glichkeit verdienen, von dieser tollen olympischen Sportart zu lernen und zu profitieren.",
		"tgt": "In September, we will be expanding to Detroit (my hometown) to provide high quality gymnastics to the youth that deserve the opportunity to learn and benefit from this great Olympic sport."
	},
	{
		"src": "Turnen entwickelt St\u00e4rke, Flexibilit\u00e4t und Koordination f\u00fcr den K\u00f6rper sowie harte Arbeit, Disziplin und Bestimmtheit f\u00fcr den Geist.",
		"tgt": "Gymnastics develops strength, flexibility and coordination for the body and hard work, discipline and determination for the mind."
	},
	{
		"src": "Diese Kombination bietet lebenslange Vorteile f\u00fcr die Gesundheit sowie f\u00fcr den schulischen und beruflichen Erfolg.",
		"tgt": "This combination provides life-long benefits for good health, success in school and work."
	},
	{
		"src": "Es ist die Inspiration dieser Mannschaft, die tausende junge M\u00e4dchen dazu bringen, sich f\u00fcr das Turnen zu interessieren und das ist toll.",
		"tgt": "It is the inspiration of this team that will send thousands of young girls to take gymnastics and that is great."
	},
	{
		"src": "Es ist so wichtig, am Sport teilzunehmen, vor allem f\u00fcr M\u00e4dchen.",
		"tgt": "To participate in sport is so important, especially for girls."
	},
	{
		"src": "Das ist eine so spannende Zeit.",
		"tgt": "This is such an exciting time."
	},
	{
		"src": "Danke Simone, Aly, Laurie, Gabby und Madison f\u00fcr diese echte Darstellung von \"Girl Power\" durch das Holen des olympischen Mannschaftsgolds und danke, fass ihr so viele junge M\u00e4dchen mit unterschiedlichem Hintergrund motiviert, um ihren Weg zu beginnen, gesunde, starke und erfolgreiche junge Frauen zu werden.",
		"tgt": "Thank you Simone, Aly, Laurie, Gabby and Madison for that serious showcase of \"Girl Power\" in winning the Olympic team gold and for motivating so many young girls of all backgrounds to begin their path to be healthy, strong and successful young women."
	},
	{
		"src": "Assistenz\u00e4rzte m\u00f6chten weitere Streiks organisieren, nachdem sie Jeremy Hunts Vorschlag abgelehnt haben",
		"tgt": "Junior doctors set to mount further strikes after rejecting Jeremy Hunt's proposal"
	},
	{
		"src": "Die Minister hatten gehofft, den Streit \u00fcber die \u00c4nderungen durch Annahme eines reformierten Vertrages mit den Funktion\u00e4ren der British Medical Association beenden zu k\u00f6nnen, aber 58 Prozent der 37.000 Assistenz\u00e4rzte, die bei einer Wahl abstimmten, lehnten ihn ab.",
		"tgt": "Ministers had hoped to end the dispute over the changes by agreeing to a reformed contract with British Medical Association officials, but 58 per cent of the 37,000 junior doctors who took part in a ballot had rejected it."
	},
	{
		"src": "Im Juli hatte Hunt Pl\u00e4ne enth\u00fcllt, den Vertrag zwangsweise einzuf\u00fchren und sagte, dass die NHS sich in einem \"Niemandsland\" bef\u00e4nde und jede weitere Verz\u00f6gerung f\u00fcr die Mitarbeiter und Patienten sch\u00e4dlich w\u00e4re.",
		"tgt": "In July, Mr Hunt revealed plans to impose the contract saying the NHS was in \"no man's land\" and any further delay would be damaging for staff and patients."
	},
	{
		"src": "Die ersten Assistenz\u00e4rzte sollen einen neuen Vertrag erhalten, der \u00c4nderungen zu Nacht- und Wochenendarbeiten enth\u00e4lt, um die Pflege zu ungastlichen Uhrzeiten zu verbessern.",
		"tgt": "The first junior doctors are moved onto the new contract, which includes changes to overnight and weekend working practices to improve care at unsociable hours."
	},
	{
		"src": "Dr Ellen McCourt, die Vorsitzende des BMA Kommittees f\u00fcr Assistenz\u00e4rzte teilte letzte Nacht in einer Mitteilung mit: \"Assistenz\u00e4rzte haben zu dem vorgeschlagenen Vertrag nach wie vor ernsthafte Bedenken, insbesondere, dass es die derzeitige Belegschaftskrise anheizen und es verabs\u00e4umen wird, alle \u00c4rzte gerecht zu behandeln.\"",
		"tgt": "Dr Ellen McCourt, the BMA's junior doctors\" committee chair, said in a statement last night: \"Junior doctors still have serious concerns about the proposed contract, particularly that it will fuel the current workforce crisis, and that it fails to treat all doctors fairly.\""
	},
	{
		"src": "Bei nur acht Wochen, die noch verbleiben, bis die erste Gruppe von \u00c4rzten unter den neuen Vertrag fallen, m\u00fcssen Fortschritte gemacht werden und die Zeit l\u00e4uft aus.",
		"tgt": "With just eight weeks before the first group of doctors are moved onto the new contract, progress needs to be made and time is running out."
	},
	{
		"src": "Bem\u00fchungen seitens des BMA zur L\u00f6sung der Streitigkeiten durch Gespr\u00e4che stie\u00dfen bei der Regierung auf Widerwillen sich zu beteiligen und manchmal auf ohrenbet\u00e4ubendes Schweigen.",
		"tgt": "Efforts by the BMA to resolve the dispute through talks have been met with an unwillingness to engage and, at times, deafening silence from the government."
	},
	{
		"src": "Das geschah des eines Versprechens, das Jeremy Hunt erst letzten Monat dar\u00fcber gemacht hatte, dass seine T\u00fcr immer offenstehen w\u00fcrde.",
		"tgt": "This is despite a promise from Jeremy Hunt just last month that his door is always open."
	},
	{
		"src": "\"Jeremy Hunt muss jetzt handeln, die Aufzwingung aufheben und die Sorgen der Assistenz\u00e4rzte ansprechen\".",
		"tgt": "\"Jeremy Hunt needs to act now, lift the imposition and address junior doctors\" concerns."
	},
	{
		"src": "Sollte er dies nicht tun, so haben es die Assistenz\u00e4rzte deutlich gemacht, dass sie bereit sind, weitere Arbeitskampfma\u00dfnahmen durchzuf\u00fchren.",
		"tgt": "If he does not then junior doctors are clear that they are prepared to take further industrial action."
	},
	{
		"src": "Der letzte Streik Ende April sah einen Aufschub von beinahe 13.000 Routineoperationen und 100.000 Terminen vor, da Krankenschwestern und Fach\u00e4rzte einbezogen wurden, um \u00c4rzten auf der Streikpostenkette Deckung zu gew\u00e4hren.",
		"tgt": "The last strike at the end of April saw the postponement of nearly 13,000 routine operations and 100,000 appointments as nurses and consultants were drafted in to provide cover for doctors on the picket line."
	},
	{
		"src": "Die Minister hatten gehofft, den Streit \u00fcber die \u00c4nderungen durch eine Annahme des reformierten Vertrages mit den Funktion\u00e4ren der British Medical Association beenden zu k\u00f6nnen.",
		"tgt": "Ministers had hoped to end the dispute over the changes by agreeing to a reformed contract with British Medical Association officials."
	},
	{
		"src": "Die BMA m\u00f6chte eine bessere Wochendentlohnung f\u00fcr die 54.000 Assistenz\u00e4rzte, die dem Vertrag unterliegen werden.",
		"tgt": "The BMA wants better weekend pay for the 54,000 junior doctors who would be subject of the contract."
	},
	{
		"src": "Daniel Mortimer, Generaldirektor der NHS Mitarbeiter, forderte die Assistenz\u00e4rzte dazu auf, den Streik zu beenden.",
		"tgt": "Daniel Mortimer, chief executive of NHS Employers, called on junior doctors not to go ahead with any strikes."
	},
	{
		"src": "Mortimer sagte: \"Arbeitskampfma\u00dfnahmen erreichen nichts der nur wenig, belasten aber bereits \u00fcberbelastete Teams und Dienstleister und bereiten den Patienten, Pflegern und ihren Familien nur Sorgen, Not und Unterbrechung.\"",
		"tgt": "Mr Mortimer said: \"Industrial action achieves little or nothing, but places pressure on already stretched teams and services and causes worry, distress and disruption for patients, carers and their families.\""
	},
	{
		"src": "In den letzten zwei Monaten haben wir mir dem Kommittee der Assistenz\u00e4rzte gesprochen und mit dem Gesundheitsministerium sowie anderen Ministerien positiv auf die Bedenken hinsichtlich der Vormundschaft und des Whistleblowings geantwortet.",
		"tgt": "Over the last two months we have been talking with the Junior Doctors Committee and have, along with the Department of Health and others, responded positively to their concerns regarding the Guardian Role and Whistleblowing."
	},
	{
		"src": "Die Arbeitgeber hofften, dass das fortgef\u00fchrte positive Engagement zu anderen wichtigen Themen - wie Entsendung, Flexibilit\u00e4t bei Schulungen, zus\u00e4tzliche Schulungen f\u00fcr diejenigen, die von einer beruflichen Auszeit zur\u00fcckkehren, Schulungsksten, gegenseitige Anerkennung des Lehrplans, Fortbildungsurlaub und das geschlechtsspezifische Lohngef\u00e4lle in der Medizin - ein Zeichen daf\u00fcr waren, wie ernst es die Arbeitgeber, das Health Education England und das Gesundheitsministerium bez\u00fcglich der Einhaltung der Vereinbarungen mit der BMA im November, Februar und Mai waren.",
		"tgt": "Employers were hopeful that the continued positive engagement on other important topics - such as deployment, flexibility in training, additional training for those returning from career breaks, costs of training, mutual recognition of syllabus, study leave and the gender pay gap in medicine - were a sign of how serious employers, Health Education England and the Department of Health were about honouring the agreements reached with the BMA in November, February and May."
	},
	{
		"src": "Das \u00a32-pro Tag- Medikament, das Herzinfarktrisiko senken kann",
		"tgt": "The \u00a32-a-day drug that can cut heart attack threat"
	},
	{
		"src": "Tausende von Herzinfarktpatienten werden von einem \u00a32-pro Tag-Medikament profitieren, nachdem von den Beh\u00f6rden empfohlen wurde, dieses mehr Leuten f\u00fcr einen l\u00e4ngeren Zeitraum zu verabreichen.",
		"tgt": "Thousands of heart attack patients are to benefit from a \u00a32-a-day drug, after officials recommended it be given to more people for longer."
	},
	{
		"src": "Das gerinnungshemmende Medikament Ticagrelor reduziert das Risiko wiederholter Herzinfarkte f\u00fcr Personen mit einer Herzerkrankung.",
		"tgt": "Anti-clotting drug ticagrelor slashes the risk of repeat attacks for people with heart disease."
	},
	{
		"src": "Das Medikament wird bereits 12 Monate lang nach einem Herzinfarkt verabreicht, wodurch das Risiko eines Schlaganfalls oder eines weiteren Herzinfarkts reduziert wird.",
		"tgt": "The drug is already given for 12 months after a heart attack, reducing the risk of a stroke or another attack."
	},
	{
		"src": "Die Regulierungsbeh\u00f6rde NICE des NHS hat eine vier Jahre lange Einnahme empfohlen, um das Risiko kardiovaskul\u00e4rer Probleme weiter zu reduzieren.",
		"tgt": "NHS watchdog NICE has advised that it should be given to people for four years, to further reduce the risk of cardiovascular problems."
	},
	{
		"src": "Die Regulierungsbeh\u00f6rde NICE des NHS hat eine vier Jahre lange Einnahme empfohlen, um das Risiko kardiovaskul\u00e4rer Probleme weiter zu reduzieren.",
		"tgt": "But now NHS watchdog NICE has advised that it should be given to people for four years, to further reduce the risk of cardiovascular problems."
	},
	{
		"src": "Rund 140.000 Leute erleiden jedes Jahr einen Herzinfarkt und ein Viertel davon erleiden einen weiteren Herzinfarkt oder einen Schlaganfall.",
		"tgt": "Some 140,000 people have a heart attack in England every year, and a quarter of these go on to have another attack or a stroke."
	},
	{
		"src": "Herzinfarkte und Schlaganf\u00e4lle werden durch Ansammlungen fetthaltigen Materials in den Arterienw\u00e4nden verursacht, die Bel\u00e4ge bilden.",
		"tgt": "Heart attacks and strokes are caused by the build-up of fatty material in artery walls to form a plaque."
	},
	{
		"src": "Wenn der Belag auseinanderbricht, kann es ein Blutgerinnsel verursachen, das den Blutfluss bis zum Herzen verstopft und dadurch einen Herzinfarkt verursacht.",
		"tgt": "If the plaque breaks apart it can cause a blood clot, blocking blood to the heart causing a heart attack."
	},
	{
		"src": "Wenn sich das Blutgerinnsel l\u00f6st, kann es durch den Blutstrom flie\u00dfen und den Blutfluss zum Gehirn verstopfen, was einen Schlaganfall verursacht.",
		"tgt": "And if the clot dislodges it can travel in the blood stream and block blood flow to the brain, causing a stroke."
	},
	{
		"src": "Personen, die bereits einen Herzinfarkt hatten, unterliegen einem h\u00f6heren Risiko einen weiteren zu haben.",
		"tgt": "People who have already have one attack are at a higher risk of having another."
	},
	{
		"src": "Ticagrelor, das von dem britischen Unternehmen AstraZeneca hergestellt wird und unter dem Handelsnamen Brilique vertrieben wird, reduziert dieses Risiko, indem es die Bildung von Blutgerinnseln unwahrscheinlicher macht.",
		"tgt": "Ticagrelor, which is made by UK firm AstraZeneca and sold under the trade name Brilique, reduces this risk by making clots less likely."
	},
	{
		"src": "Der Anleitungsentwurf von NICE, der heute ver\u00f6ffentlicht wurde, empfiehlt eine 12-monatige Einnahme von 90mg Ticagrelor, gefolgt von 60mg mit einer zweimal t\u00e4glichen Einnahme von Aspirin f\u00fcr die n\u00e4chsten drei Jahre.",
		"tgt": "The draft NICE guidance, published today, recommends that people be given 90 mg of ticagrelor for 12 months, followed by 60mg along with aspirin twice a day for another three years."
	},
	{
		"src": "Professor Carole Longson, Direktorin des NICE Gesundheitstechnologieevaluierungszentrums sagte: \"Trotz der Verf\u00fcgbarkeit von Sekund\u00e4rpr\u00e4vention haben ein Viertel aller Personen, die einen Herzinfarkt erlitten haben, einen weiteren Herzinfarkt oder einen Schlaganfall - oft mit desastr\u00f6sen Folgen.\"",
		"tgt": "Professor Carole Longson, director at the NICE health technology evaluation centre, said: \"Despite the availability of effective secondary prevention treatments, as many as a quarter of people who have had a heart attack go on to have another heart attack or stroke - often with devastating consequences.\""
	},
	{
		"src": "Die Angst vor einem erneuten Herzinfarkt kann erhebliche negative Auswirkungen auf die Lebensqualit\u00e4t einer Person haben.",
		"tgt": "Fear of a recurrence can have a significant negative impact on a person's quality of life."
	},
	{
		"src": "Die Erfahrung zeigt, dass Ticagrelor in Kombination mit Aspirin effektiv bei der Reduzierung weiterer Herzinfarkte und Schlaganf\u00e4lle bei Leuten ist, die bereits einen Herzinfarkt hatten.",
		"tgt": "The evidence shows that ticagrelor, in combination with aspirin, is effective at reducing the risk of further heart attacks and strokes in people who have already had a heart attack."
	},
	{
		"src": "Durch eine vorl\u00e4ufige Empfehlung von Ticagrelor freuen wir uns, dass wir in der Lage sind, verf\u00fcgbare Behandlungsoptionen an tausende von Menschen zu erweitern, die davon profitieren k\u00f6nnen.",
		"tgt": "In provisionally recommending ticagrelor we are pleased to be able to increase the treatment options available to the many thousands of people who stand to benefit from it."
	},
	{
		"src": "Die Information \u00fcber die Wirksamkeit und Sicherheit von Ticagrelor - vor allem das Blutungsrisiko - ist auf einen Zeitraum von bis zu drei Jahren beschr\u00e4nkt. Der Anleitungsentwurf empfiehlt keine Behandlung, die \u00fcber diesen Zeitraum hinausgeht.",
		"tgt": "Because information on the efficacy and safety of ticagrelor - particularly the risk of bleeding - beyond three years is limited, the draft guidance does not recommend treatment with it beyond that period."
	},
	{
		"src": "Kultur der Political Correctness l\u00e4sst Wahlbetrug in muslimischen Gegenden aufbl\u00fchen",
		"tgt": "PC culture let vote fraud in Muslim areas flourish"
	},
	{
		"src": "Der ehemalige B\u00fcrgermeister von Tower Hamlets Lutfur Rahman wurde letztes Jahr auf Veranlassung eines Regierungsberichts wegen Korruption aus dem Amt entfernt",
		"tgt": "Ex-Tower Hamlets mayor Lutfur Rahman was removed from office last year for corruption, prompting the government report"
	},
	{
		"src": "Eine Kultur der Political Correctness hat dazu gef\u00fchrt, dass weitverbreiteter Wahlbetrug in muslimischen Gemeinden wissentlich ignoriert wird wie ein vernichtender Regierungsbericht heute offenlegte.",
		"tgt": "A culture of political correctness has led to a blind eye being turned to widespread voting fraud in Muslim communities, a devastating government report reveals today."
	},
	{
		"src": "Das ehemalige Kabinettsmitglied Sir Eric Pickles greift verbal die Polizei, Wahlbeobachter und Rath\u00e4user daf\u00fcr an, Beweise von Wahlmissbrauch aufgrund von \"\u00dcberempfindlichkeiten bez\u00fcglich Ethnie und Religion\" ignoriert zu haben.",
		"tgt": "Ex-Cabinet minister Sir Eric Pickles lambasts the police, election watchdogs and town halls for ignoring evidence of electoral abuse because of \"over-sensitivities about ethnicity and religion.\""
	},
	{
		"src": "Der ehemalige Minister f\u00fcr Integration und Kommunalregierung, der jetzt ein Antkorruptionsk\u00f6nig ist, sagte, dass die Einsch\u00fcchterung von W\u00e4hlern aus religi\u00f6sen Motiven so schlimm w\u00e4re, dass es der Polizei gestattet sein sollte, Absperrb\u00e4nder au\u00dferhalb von Wahlkabinen einzurichten, um eingesch\u00fcchterte W\u00e4hler zu sch\u00fctzen.",
		"tgt": "The former communities secretary, now the anti-corruption tsar, said the intimidation of voters on religious grounds was so bad that police should be allowed to put cordons outside polling stations to protect frightened voters."
	},
	{
		"src": "Er empfiehlt, dass W\u00e4hler einen Ausweis mit sich f\u00fchren sollten, um bei Wahlen ihre Identit\u00e4t zu beweisen.",
		"tgt": "He recommends that voters should have to take ID to prove who they are when they vote."
	},
	{
		"src": "Zur Zeit muss ein W\u00e4hler lediglich seinen Namen und Anschrift nennen.",
		"tgt": "Currently, a voter merely has to state their name and address."
	},
	{
		"src": "Der Bericht schl\u00e4gt vor, nicht entfernbare Tinte auf den Finger einer Person aufzutragen, wenn sie ihre Wahlstimme abgeben, um zu verhindern, dass jemand zweimal w\u00e4hlt.",
		"tgt": "The report even suggests putting indelible ink on a person's fingers as they cast their ballot to prevent anyone being able to vote twice."
	},
	{
		"src": "Whistleblower sollten mehr Schutz erhalten, sagt Sir Eric.",
		"tgt": "Greater protection should be given to whistleblowers, Sir Eric says."
	},
	{
		"src": "Er fordert, dass die Presse mehr Zugang zu Gemeindeunterlagen und Entscheidungen von nicht offiziellen Kommittees oder Arbeitsgruppen haben sollte.",
		"tgt": "He calls for the Press to be given greater access to council papers and decisions taken by unofficial committees or working groups."
	},
	{
		"src": "\"Das dient nicht nur gegen Wahlbetrug, sondern soll auch die kommunale Regierung vor der breiteren Korruptions- und Finanzbetrugskultur, die damit einhergeht, sch\u00fctzen,\" sagte er.",
		"tgt": "\"This is not solely to protect against electoral fraud, but to protect local government from the broader culture of corruption and financial fraud that goes hand in hand with it,\" he said."
	},
	{
		"src": "Der Bericht wurde von der Downing Street als Folge des Tower Hamlets Wahlskandals im Osten Londons angeordnet.",
		"tgt": "The report was ordered by Downing Street in the wake of the Tower Hamlets voting scandal in East London."
	},
	{
		"src": "Letztes Jahr entschied ein Sonderwahlgericht, dass der amtierende B\u00fcrgermeister Lutfur Rahman nach einer Litanei an korrupten und illegalen Praktiken seines Amtes enthoben werden sollte.",
		"tgt": "Last year a special election court ruled the sitting mayor, Lutfur Rahman, should be removed from office following a litany of corrupt and illegal practices."
	},
	{
		"src": "Das Gericht befand, dass Rahman die religi\u00f6sen Gef\u00fchle seiner muslimischen Gemeinschaft\"auf zynische Art und Weise pervertiert h\u00e4tte\" und, dass er seine Kritiker mit Rassissmus- und Islamophobienanschuldigungen zum Schweigen gebracht h\u00e4tte.",
		"tgt": "The court found Rahman \"cynically perverted\" the religious feeling of his Muslim community and silenced his critics with accusations of racism and Islamophobia."
	},
	{
		"src": "Rahman soll \"seine Kampagne auf der Grundlage gef\u00fchrt haben, dass es die relig\u00f6se Pflicht von Muslimen sei, ihn zu w\u00e4hlen.\"",
		"tgt": "Rahman, it was said, \"ran his campaign on the basis that it was the religious duty of faithful Muslims to vote for him.\""
	},
	{
		"src": "Bis zu 300 Stimmen waren entweder zweifelhaft oder die Folge einer Nachahmung, bei der eine Person als jemand anderer w\u00e4hlt.",
		"tgt": "Up to 300 votes were dubious or the result of personation, where a person votes while posing as someone else."
	},
	{
		"src": "Sir Eric sagte, dass es im ganzen Land Beweise f\u00fcr Betrug g\u00e4be.",
		"tgt": "Sir Eric said there was evidence of fraud across the country."
	},
	{
		"src": "Er \u00e4u\u00dferte sich insbesondere alarmierend zur betr\u00fcgerischen Briefwahl - bei der \u00e4ltere Mitglieder der muslimischen Gemeinschaft Druck auf Leute gemacht h\u00e4tten, einen Kandidaten ihrer Wahl zu w\u00e4hlen.",
		"tgt": "He voiced particular alarm about postal voting fraud - in which senior members of the Muslim community were said to have exerted pressure on people to vote for a candidate of their choosing."
	},
	{
		"src": "Sir Eric, abgebildet, machte mehrere Empfehlungen, um das Wahlsystem zu s\u00e4ubern, einschlie\u00dflich dem F\u00fchren von Ausweisen, um die Identit\u00e4t zu beweisen",
		"tgt": "Sir Eric, pictured, made several recommendations to clean up the voting system including bringing your ID to prove who you are"
	},
	{
		"src": "In seinem Bericht hei\u00dft es: \"Als Beweis wurde angebracht, dass Druck auf schutzbed\u00fcrftige Mitglieder einiger ethnischer Minderheiten ausge\u00fcbt wurde, insbesondere Frauen und junge Menschen, um gem\u00e4\u00df des Willens der \u00c4lteren, insbesondere Gemeinschaften mit pakistanischem oder bangladeschischem Hintergrund, zu w\u00e4hlen.",
		"tgt": "His report says: \"Evidence was presented of pressure being put on vulnerable members of some ethnic minority communities, particularly women and young people, to vote according to the will of the elders, especially in communities of Pakistani and Bangladeshi background."
	},
	{
		"src": "\"Es gab Bedenken, dass... staatliche Institutionen ein solches Verhalten aufgrund von \"politisch korrekten\" \u00dcberempfindlichkeiten bez\u00fcglich der Ethnie und Religion wissentlich ignoriert h\u00e4tten.\"",
		"tgt": "\"There were concerns that... state institutions had turned a blind eye to such behaviour because of \"politically correct\" over-sensitivities about ethnicity and religion.\""
	},
	{
		"src": "Sir Eric sprach 50 Empfehlungen aus, um das System zu s\u00e4ubern, einschlie\u00dflich dem Verbot, dass politische Aktivisten Briefwahlunterlagen bearbeiten, um \"Wahlernten\" zu stoppen.",
		"tgt": "Sir Eric made 50 recommendations to clean up the system, including banning political activists from handling postal ballot papers to stop \"vote harvesting.\""
	},
	{
		"src": "Der Bericht, der von Theresa May in Erw\u00e4gung gezogen wird, verlangt auch h\u00e4rtere Registrierungs\u00fcberpr\u00fcfungen, um zu verhindern, dass das Wahlverzeichnis zu Immigrations- und Sozialbetrugszwecken verwendet wird.",
		"tgt": "The report, being considered by Theresa May, also calls for tougher checks on registration to prevent the electoral register being used for immigration and benefit fraud."
	},
	{
		"src": "Optionen in Betracht ziehen, W\u00e4hler vor der Wahl nach Ihrem Ausweis zu fragen.",
		"tgt": "Consider the options for requiring voters to produce ID before voting."
	},
	{
		"src": "Nicht entfernbare Tinte auf dem Finger einer Person verwenden, sobald sie ihre Stimme abgegeben hat, um zu verhindern, dass jemand zweimal w\u00e4hlt.",
		"tgt": "Use indelible ink on a person's fingers once they cast their ballot to prevent anyone voting twice."
	},
	{
		"src": "Systematische \u00dcberpr\u00fcfungen \u00fcber die Nationalit\u00e4t einer Person durchzuf\u00fchren, um sicherzustellen, dass sie wahlberechtigt sind.",
		"tgt": "Carry out systematic checks on a person's nationality to ensure they are eligible to vote."
	},
	{
		"src": "Eine dreij\u00e4hrige Begrenzung auf Antr\u00e4ge auf eine automatische Briefwahl.",
		"tgt": "Put a three-year limit on requests for an automatic postal vote."
	},
	{
		"src": "Verbot, dass politische Aktivisten vollst\u00e4ndige Briefwahlen und Umschl\u00e4ge von Briefwahlen bearbeiten.",
		"tgt": "Ban political campaigners and activists from handling completed postal votes and postal vote envelopes."
	},
	{
		"src": "Der Polizei die Befugnis geben, Absperrungen um Wahlstationen einzurichten.",
		"tgt": "Give police powers to set up cordons around polling stations."
	},
	{
		"src": "Eine Gesetzes\u00e4nderung, die eine Anklage wegen Einsch\u00fcchterung gem\u00e4\u00df des Representation of the People Act 1983 (Volksvertretungsgesetz 1983) erleichtert.",
		"tgt": "Change the law to make it easier to charge people with intimidation under the Representation of the People Act 1983."
	},
	{
		"src": "Fotografierverbot in Wahlstationen.",
		"tgt": "Make it illegal to take pictures in polling stations."
	},
	{
		"src": "Anforderung, dass nur Englisch in den Wahlstationen verwendet werden darf (mit Ausnahme von Wales).",
		"tgt": "Make it a requirement that only English is to be used in polling stations (except in Wales)."
	},
	{
		"src": "Intensivierung des Trainings, um sicherzustellen, dass die Mitarbeiter die Regel durchsetzen, dass W\u00e4hler alleine in die Wahlkabine gehen.",
		"tgt": "Strengthen training to ensure staff enforce the rule that voters go to the booth alone."
	},
	{
		"src": "Sir Eric f\u00e4llt \u00fcber die Metropolitan Police und findet es \"erstaunlich\", dass nach dem Tower Hamlets Fall keine Strafanzeige gestellt wurde.",
		"tgt": "Sir Eric savages the Metropolitan Police, saying it is \"astonishing\" that no criminal charges were brought after the Tower Hamlets case."
	},
	{
		"src": "\"Das Wahlgericht hat Lutfur Rahman und seinen Stellvertreter f\u00fcr aufgrund einer Litanei an korrupten und illegalen Praktiken als untauglich erkl\u00e4rt,\" sagte er.",
		"tgt": "\"The election court disqualified Lutfur Rahman and his agent for a litany of corrupt and illegal practices,\" he said."
	},
	{
		"src": "Er wurde aufgrund einer Reihe von Gr\u00fcnden f\u00fcr hinreichend - gem\u00e4\u00df der hohen Anforderungen im strafrechtlichen Verfahren - schuldig bekannt.",
		"tgt": "He was found guilty beyond reasonable doubt - to a criminal standard of proof - on a series of grounds."
	},
	{
		"src": "Er kritisiert auch die wirkungslosen \"Abhakkontrollen\" der Wahlregistrierungsabteilungen der Rath\u00e4user.",
		"tgt": "He also criticises the ineffectual \"tick-box inspections\" of town hall electoral registration departments."
	},
	{
		"src": "Sir Eric sagte: \"Das Gerichtsurteil in Tower Hamlets vom letzten Jahr war ein Warnsignal.",
		"tgt": "Sir Eric said: \"Last year's court ruling in Tower Hamlets was a wake-up call."
	},
	{
		"src": "Unser Land tr\u00e4gt als die Mutter der Parlamente ein stolzes Erbe, doch die besorgniserregende und verdeckte Ausbreitung von Wahlbetrug und Leugnung einiger Beh\u00f6rden bedrohen diesen guten Ruf.",
		"tgt": "Our nation has a proud heritage as the mother of parliaments, yet the worrying and covert spread of electoral fraud and state of denial by some bodies threatens that good reputation."
	},
	{
		"src": "Verr\u00fcckt nach Kates Radler-Doppelg\u00e4ngerin und andere ber\u00fchmte Doppelg\u00e4nger von Olympiasportlern in Rio",
		"tgt": "Crazy for Kate's cyclist lookalike and other celeb doppelgangers of Rio Olympians"
	},
	{
		"src": "Fans der Olympiade 2016 in Rio sind diese Woche \u00fcber die franz\u00f6sische Radsportlerin Pauline Ferrand-Prevot au\u00dfer Rand und Band geraten, die sich als beeindruckende Doppelg\u00e4ngerin der Herzogin von Cambridge erwiesen hat.",
		"tgt": "Fans of the Rio 2016 Olympics this week have gone wild for French cyclist Pauline Ferrand-Prevot, who has proven an impressive lookalike for the Duchess of Cambridge."
	},
	{
		"src": "Aber die 24-j\u00e4hrige Olympionikin ist diesen Sommer bei weitem nicht der einzige, um Gold k\u00e4mpfende Athlet, der seinen eigenen ber\u00fchmten Doppelg\u00e4nger aufweist - zumindest nicht, wenn man den sozialen Medien Glauben schenken darf.",
		"tgt": "But the 24-year-old Olympian is far from the only athlete out fighting for gold this summer that boasts their own celebrity doppelganger - at least not according to social media."
	},
	{
		"src": "Zu Ehren der Olympischen Spiele in Rio und all die ber\u00fchmten Gesichter, die zur Zeit auf unseren Bildschirmen flimmern, hat FEMAIL eine Listen an Olympioniken erstellt, die mehr als nur eine gewisse \u00c4hnlichkeit mit Hollywoodber\u00fchmtheiten aufweisen.",
		"tgt": "So, in honor of the Rio Games and all the famous faces crossing our screens at the moment, FEMAIL have compiled a list of Olympians who bear more than a passing resemblance with Hollywood celebs."
	},
	{
		"src": "Der J\u00e4ger und der Wolf: Mannschaftsmitglied der US-Mannschaft im Bogenschie\u00dfen Brady Ellison, links, wird seit seiner Kindheit mit Leonardo DiCaprio verglichen",
		"tgt": "The hunter and the wolf: U.S. Men's Archery Team member Brady Ellison, left, has been compared to Leonardo DiCaprio since he was a kid"
	},
	{
		"src": "Au\u00dfer Kates Doppelg\u00e4ngerin auf der Radrennbahn wiesen viele Leute im Internet darauf hin, wie ein gewisser Bogensch\u00fctze der Zwilling von A-Promi Leonardo DiCaprio sein k\u00f6nnte.",
		"tgt": "Aside from Kate's doppelganger on the cycling track, many people online have been quick to point out how a certain archer could be the twin of A-lister Leonardo DiCaprio."
	},
	{
		"src": "Das Mannschaftsmitglied der US-Mannschaft im Bogenschie\u00dfen Brady Ellison hat einen Ansturm auf Twitter verursacht, nachdem Bilder, auf denen er dem Wolf of Wall Street Star unheimlich \u00e4hnlich sieht, auftauchten.",
		"tgt": "U.S. Men's Archery Team member Brady Ellison has caused a storm on Twitter after images of him looking eerily similar to the Wolf of Wall Street star surfaced."
	},
	{
		"src": "Tats\u00e4chlich bekam der Bogensch\u00fctze den Wahnsinn in den sozialen Medien mit und gab zu, dass er bereits seit seiner Kindheit zu h\u00f6ren bekommt, dass er wie Leo aussieht.",
		"tgt": "And in fact, the archer became aware of the social media frenzy and admitted that he has been hearing that he looks like Leo since he was a kid."
	},
	{
		"src": "\"Ich selbst sehe keine gro\u00dfe \u00c4hnlichkeit, mit Ausnahme der Gesichtsbehaarung,\" teilte Brady der Huffington Post mit.",
		"tgt": "'I personally don't see a huge resemblance, maybe besides the facial hair,' Brady told Huffington Post."
	},
	{
		"src": "\"Er ist ein gutaussehender Kerl, also fasse ich das wohl als Kompliment auf.\"",
		"tgt": "'He is a good-looking dude so I guess it's a compliment.'"
	},
	{
		"src": "Einer der beliebtesten Vergleiche seit London 2012 wird dieses Jahr zweifellos noch mehr in den Mittelpunkt treten: die aufallende \u00c4hnlichkeit zwischen dem britischen Weitspringer Greg Rutherford und dem beliebten Schauspieler Neil Patrick Harris.",
		"tgt": "One of the most popular comparisons from London 2012 is undoubtedly going to be pointed out even more this year: the striking likeness between British long jumper Greg Rutherford and popular actor Neil Patrick Harris."
	},
	{
		"src": "Die russische Turnerin Aliya Mustafina mit ihren gro\u00dfen, ausdrucksstarken Augen soll als Doppelg\u00e4ngerin f\u00fcr die kubanisch-amerikanische S\u00e4ngerin Gloria Estefan durchgehen k\u00f6nnen.",
		"tgt": "Russian gymnast Aliya Mustafina, with her large, expressive eyes, has been said to be a dead ringer for Cuban-American singer Gloria Estefan."
	},
	{
		"src": "Und im Schwimmbecken wird der s\u00fcdafrikanische Schwimmer Cameron van der Burgh seit Jahren mit dem Glee Star Matthew Morrison verglichen.",
		"tgt": "And over in the pool, South African swimmer Cameron van der Burgh has been getting compared to Glee star Matthew Morrison for years now."
	},
	{
		"src": "Einen Gang h\u00f6her: Dieser User ist der Ansicht, dass Nathan die \"athletische Version\" des Inception Schauspielers ist",
		"tgt": "Changing it up: This user reckons that Nathan is an 'athletic version' of the Inception actor"
	},
	{
		"src": "Ein weiterer anhaltender Vergleich wurde zwischen dem Tennisstar Rafael Nadal und Schauspieler Josh Hartnett gezogen, der \u00e4hnlich schwere Augenbrauen und Lippen aufweist.",
		"tgt": "Another long-running comparison has been between tennis star Rafael Nadal and actor Josh Hartnett who boast a similar heavy brow and lips."
	},
	{
		"src": "Die russische Silbermedaillenschwimmerin Yulia Efimova weist mehr als nur die sonnengebr\u00e4unte Haut und blonden Haare wie die Schauspielerin Annalynne McCord auf, w\u00e4hrend dem Amerikaner Nathan Adrian von Fans attestiert wurde, einer \"athletischen Version von Joseph Gordon Levitt\" zu gleichen.",
		"tgt": "Silver medal swimmer Russia's Yulia Efimova boasts more than just the same sunkissed skin and blonde hair as actress Annalynne McCord, while Team USA's Nathan Adrian has been said by fans to resemble an 'athletic version of Joseph Gorgon Levitt.'"
	},
	{
		"src": "Starke Frauen: Fu\u00dfballstar Hope Solo, links, und Dexter Schauspielerin Jennifer Carpenter, rechts, haben eine \u00e4hnliche Gesichtsform und Augen",
		"tgt": "Tough women: Soccer star Hope Solo, left, and Dexter actress Jennifer Carpenter, right, have similar face shapes and eyes"
	},
	{
		"src": "Nicht die Einzige: Ein Twitter-User war sehr gl\u00fccklich dar\u00fcber, dass anderen die \u00c4hnlichkeiten auch aufgefallen sind",
		"tgt": "Not the only one: One Twitter user was very pleased that others also saw the similaritiest"
	},
	{
		"src": "Theorie in den Raum gestellt: Laut diesem User gibt es f\u00fcr die \u00c4hnlichkeit des Paares vielleicht einen Grund",
		"tgt": "Floating a theory: According to this user, perhaps there is a reason behind the pair's similar looks"
	},
	{
		"src": "Eine Twitter-Userin erkl\u00e4rte ihre Zufriedenheit, dass \"der Rest des Internets denkt, dass Hope Solo und Jennifer Carpenter nahezu identisch sind.\"",
		"tgt": "One Twitter user took to the site recently to declare her happiness that 'the rest of the internet thinks that Hope Solo and Jennifer Carpenter are actually identical.'"
	},
	{
		"src": "Tats\u00e4chlich haben der US-Fu\u00dfballstar Hope Solo und die Dexter Schauspielerin Jennifer Carpenter eine unglaublich \u00e4hnliche Gesichtsform und Augen.",
		"tgt": "Indeed, the USA soccer star and the Dexter actress share incredibly similar face shapes and eyes."
	},
	{
		"src": "Weitere beliebte Vergleiche umfassten Kerri Walsh-Jennings und ihr L\u00e4cheln, die nahezu identisch mit dem von Schauspielerin Laura Linney ist sowie die Goldmedaillengewinnerin im Turnen Gabby Douglas, die ihr eigenes wundersch\u00f6nes, breites L\u00e4cheln aufweist, das dem von Bring It On Star Gabrielle Union \u00e4hnelt.",
		"tgt": "Other popular comparisons have included Kerri Walsh-Jennings and her smile that is near-identical to that of actress Laura Linney, as well as gold medal-winning gymnast Gabby Douglas, who boasts her own beautifully broad smile that matches that of Bring It On star Gabrielle Union."
	},
	{
		"src": "CBC-Kommentator f\u00fcr die Olympischen Spiele entschuldigt sich f\u00fcr seine Aussage, dass chinesische Schwimmerin \"wie ein Schwein gestorben ist\"",
		"tgt": "CBC Olympics commentator apologizes for saying Chinese swimmer 'died like a pig'"
	},
	{
		"src": "Byron MacDonalds Analyse \u00fcber den vierten Platz der 14-j\u00e4hrigen Ai Yanhan bei dr 4x200m Freistilschwimmstaffel emp\u00f6rte Zuschauer der CBC-Live\u00fcbertragung der Olmypischen Spiele am Mittwoch",
		"tgt": "Byron MacDonald's analysis of 14-year-old Ai Yanhan's fourth place finish at the women's 4x200m freestyle relay outraged viewers of CBC's live Olympic coverage on Wednesday"
	},
	{
		"src": "Der kanadische Sender CBC musste sich entschuldigen, nachdem einer seiner Kommentatoren sagte, dass die 14-j\u00e4hrige chinesische Schwimmerin \"wie Mief abging\" und w\u00e4hrend des Rennens wie \"ein Schwein starb\".",
		"tgt": "Canadian broadcaster CBC has been forced to apologize after one of its commentators said a 14-year-old female Chinese swimmer 'went out like stink' and 'died like a pig' during a race."
	},
	{
		"src": "Der Kommentator Byron MacDonalds dachte, dass sein Mikrofon ausgeschaltet sei, als er am Ende der 4x200m Freistilschwimmstaffel seine eigenen Meinungen abzugeben.",
		"tgt": "Commentator Byron MacDonald thought his mic was turned off when he started to dispense some of his own opinions at the end of the women's 4x200m freestyle relay final."
	},
	{
		"src": "MacDonald, der ins Kommentatorenteam des CBS an Bord geholt worden war, um mehr \"Farbe\" zu verleihen, konnte man h\u00f6ren sagen: \"Diese kleine 14-j\u00e4hrige Chinesin hat den Anschlu\u00df verloren, Baby\".",
		"tgt": "MacDonald, who was brought on board CBC's commentary team to provide 'color' could be heard saying: 'That little 14-year-old from China dropped the ball, baby'."
	},
	{
		"src": "Zu aufgeregt, ging ab wie Mief, starb wie ein Schwein.",
		"tgt": "Too excited, went out like stink, died like a pig."
	},
	{
		"src": "Danke daf\u00fcr.",
		"tgt": "Thanks for that."
	},
	{
		"src": "Die chinesische Schwimmerin Ai Yanhan, 14, schwamm die zweite Etappe der Schwimmstaffel 1:57,79 - 1,61 Sekunden langsamer als Kanadas Taylor Ruck, was es den Kanadiern erm\u00f6glichte, die L\u00fccke zu China aufzuschlie\u00dfen.",
		"tgt": "Chinese swimmer Ai Yanhan, 14, swam the second leg of the relay in 1:57.79 - 1.61 seconds slower than Canada's Taylor Ruck, allowing the Canadians to close the gap on China."
	},
	{
		"src": "Zuschauer in ganz Kanada reagierten schnell online, nachdem sie von dem Ton und der Sprache geschockt waren",
		"tgt": "Viewers across Canada were quick to react online after being shocked by the tone and the language used"
	},
	{
		"src": "Emmett Macfarlane tweete, \" Hat der CBC-Kommentator gerade gesagt, dass die 14-j\u00e4hrige Schwimmerin aus China \"wie ein Schwein gestorben ist\"????",
		"tgt": "Emmett Macfarlane tweeted, \"Did the CBC announcer just say the 14-year-old swimmer from China 'died like a pig'\"????"
	},
	{
		"src": "Der Idiot hat nicht kapiert, dass sie noch immer auf Sendung waren.\"",
		"tgt": "The idiot didn't realize they were still on the air.'"
	},
	{
		"src": "Ai Yanhan aus China wurde bei der finalen 4 x 200m Freistilschwimmstaffel f\u00fcr Frauen folgendema\u00dfen beschrieben: \" Diese kleine 14-j\u00e4hrige Chinesin hat den Anschlu\u00df verloren, Baby.\"",
		"tgt": "Ai Yanhan of China in the Women's 4 x 200m Freestyle Relay Final was described as: 'That little 14-year-old from China dropped the ball, baby.'"
	},
	{
		"src": "Die Kritik gegen Byron MacDonald auf Twitter kam schnell und hart, bei der ihn viele zur Rede stellten",
		"tgt": "Criticism on Twitter came thick and fast against Byron MacDonald with many calling him out"
	},
	{
		"src": "Twitter-User hielten sich nicht zur\u00fcck, als sie h\u00f6rten, wie unsensibel Byron MacDonald war",
		"tgt": "Twitter users did not hold back when the heard how insensitive Byron Macdonlad was being"
	},
	{
		"src": "Ein andere Twitter-Userin Sarah Paradis schrieb: \"Wow, #ByronMacDonald.",
		"tgt": "Another twitter user, Sarah Paradis, wrote: 'Wow #ByronMacDonald."
	},
	{
		"src": "Du repr\u00e4sentierst die CBC und Kanada und l\u00e4sst uns alle wie Rassisten aussehen. #angeekelt.",
		"tgt": "You represent the CBC and Canada and make us all sound like a bunch of racists. #disgusted."
	},
	{
		"src": "Kurze Zeit sp\u00e4ter entschuldigte sich Scott Russel, der die CBC Sendung moderierte, live f\u00fcr den Kommentar von MacDonald und sagte: \"Wir entschuldigen uns, dass der Kommentar \u00fcber eine Schwimmleistung ausgestrahlt wurde.\"",
		"tgt": "Soon after, Scott Russel who was hosting CBC's broadcast apologized on-air for MacDonald's comment, saying: 'We apologize the comment on a swim performance made it to air.'"
	},
	{
		"src": "Es war eine ungl\u00fccklich gew\u00e4hlte Formulierung, es tut uns leid, dass es passiert ist.\"",
		"tgt": "It was an unfortunate choice of words, we're sorry it happened.'"
	},
	{
		"src": "CBC entschuldigte sich am Ende \u00fcber 90 Mal bei den Leuten, die auf die Bemerkt \u00fcber Twitter geantwortet haben",
		"tgt": "CBC ended up apologizing more than 90 times to people who had tweeted in response to the remark"
	},
	{
		"src": "Der Kommentatorenkollege Scott Russel musste sich im Namen von MacDonald entschuldigen",
		"tgt": "Fellow commentator, Scott Russel, had to make an apology on MacDonald's behalf"
	},
	{
		"src": "CBC kopierte und f\u00fcgte seine Entschuldigung bei mehr als 90 anderen Twitter-Usern ein, die sich \u00fcber die Kommentare von MacDonald beschwert hatten",
		"tgt": "CBC then copied and pasted their apology to more than 90 other twitter users who complained about MacDonald's comments"
	},
	{
		"src": "Das Netzwerk entschuldigte sich ebenfalls schnell und gab eine Mitteilung heraus.",
		"tgt": "The network was also quick to apologize and released a statement."
	},
	{
		"src": "Wir bedauern es aufrichtig, dass diese Aussagen gemacht wurden und, dass es erm\u00f6glicht wurde, dass sie ausgestrahlt werden.",
		"tgt": "We sincerely regret that these statements were made, and that they were allowed to go to air."
	},
	{
		"src": "Wir haben uns gestern Nacht schnell bei unseren Zuschauern auf Sendung und unseren Followern in den sozialen Medien entschuldigt.",
		"tgt": "We moved quickly last night to apologize to our viewers on-air and to our followers on Social media."
	},
	{
		"src": "Um eins klarzustellen, Byrons Kommentare bezogen sich auf die Leistung der Schwimmerin und nicht auf sie als Person.",
		"tgt": "To be clear, Byron's comments were related to the swimmer's performance, not to her as an individual."
	},
	{
		"src": "Dennoch waren sie unangemessen und eine ungl\u00fccklich gew\u00e4hlte Formulierung. Byron tut das, was er gesagt hat, sehr leid.",
		"tgt": "That said, they were inappropriate and an unfortunate choice of words and Byron is very sorry for what he said."
	},
	{
		"src": "Am Donnerstag nachmittag entschuldigte sich MacDonald in der Sendung und versuchte seine Bemerkung zu rechtfertigen, indem er aussagte, dass es nicht seine Absicht war, dass sie als pers\u00f6nlicher Angriff ausgelegt wird.",
		"tgt": "On Thursday afternoon, MacDonald apologized on-air and attempted to qualify his remark by stating he didn't mean for it to be construed as a personal attack."
	},
	{
		"src": "\"Ich w\u00fcrde mir gerne einen Moment Zeit nehmen, um mich f\u00fcr den Kommentar, den ich nach der Frauenschwimmstaffel in der CBC Olympisendung gemacht habe, zu entschuldigen, sagte er.",
		"tgt": "'I would like to take a moment to apologize for a comment that I made last night after the women's relay,' he said on CBC's Olympic broadcast.'"
	},
	{
		"src": "\"Ich habe mich auf die Leistung der Schwimmerin und nicht auf sie als Person bezogen.\"",
		"tgt": "'I was referring to a swimmer's performance, and not to them as a person.'"
	},
	{
		"src": "Nat\u00fcrlich war keine Missachtung beabsichtigt und es tut mir sehr leid.\"",
		"tgt": "'Needless to say, there was no disrespect intended and I'm very sorry.'"
	},
	{
		"src": "K\u00e4ufer in Primark emp\u00f6rt \u00fcber Frau, die mitten im Gesch\u00e4ft schamlos Unterw\u00e4sche anprobiert",
		"tgt": "Primark shopper outraged at woman who brazenly tried on underwear in the middle of the shop"
	},
	{
		"src": "Die K\u00e4ufer wussten nicht, wohin sie hinsehen sollten, als eine Frau ihre Kleidung inmitten eines Primark auszog, um Unterhosen anzuprobieren.",
		"tgt": "Shoppers didn't know where to look when a woman stripped off to try on knickers on the shop floor in the middle of a Primark."
	},
	{
		"src": "Um die Situation zu verschlimmern, musterte sie, wie sie darin aussah, zog sie aus und legte sie wieder zur\u00fcck ins Regal.",
		"tgt": "To make it even worse, she sized up how she looked in them, peeled them off and put them back on the shelf."
	},
	{
		"src": "Sie st\u00f6berte weiter und probierte vier Paar Unterhosen in einem Gesch\u00e4ft im Bouverie Place Einkaufszentrum in Folkestone, an.",
		"tgt": "She carried on browsing and eventually tried on four pairs of underwear at the store in Bouverie Place shopping centre, Folkestone."
	},
	{
		"src": "Das Primark Gesch\u00e4ft im Bouverie Place Einkaufszentrum in Folkestone, in dem die Frau die Unterhosen anprobierte, bevor sie sie zur\u00fcck in das Regal legte",
		"tgt": "The Primark store in Bouverie Place shopping centre, Folkestone, where the woman tried on knickers before putting them back on the shelf"
	},
	{
		"src": "Eine Mutter von zwei Kindern, Jenny Davidson, die sich zur selben Zeit im Gesch\u00e4ft befand, sagte, dass nachdem die mysteri\u00f6se Frau die Unterw\u00e4sche anprobiert hatte, \"sie sich wieder anzog und das Gesch\u00e4ft verlie\u00df, ohne etwas zu kaufen.\"",
		"tgt": "A mother-of-two, Jenny Davidson, who was in the shop at the time, said after trying on the underwear the mystery woman 'got dressed again and walked out of the store without buying anything.'"
	},
	{
		"src": "Sie sagte: \" Die Leute konnten nicht glauben, was sie sahen.\"",
		"tgt": "She said: 'People couldn't believe what they were seeing.'"
	},
	{
		"src": "Mitten auf der Verkaufsfl\u00e4che stehend nahm sie ein Paar Unterhosen aus der Auslage, zog ihre eigenen Strumpfhosen und Hosen aus und probierte sie an.",
		"tgt": "Standing in the middle of the shop floor, she took a pair of knickers from the display, stripped off her own tights and pants and put them on."
	},
	{
		"src": "\"Sie versuchte nicht einmal einen etwas diskreteren Ort zu finden, um es zu tun - sie stand einfach da, frech wie Oskar.\"",
		"tgt": "'She didn't try to find anywhere discreet to do it - she just stood there, bold as brass.'"
	},
	{
		"src": "\"Jeder starrte, als sie die Unterhosen wieder auszog, die ihr offensichtlich nicht gefallen haben, da sie sie wieder ins Regal legte.\"",
		"tgt": "'Everyone was staring as she took the knickers off again and obviously didn't like them because she put them back on the shelf.'"
	},
	{
		"src": "Sie wiederholte dasselbe mit drei weiteren Unterhosen, bevor sie endlich entschied, dass ihr nichts gefiel, sich wieder anzog und rausging.",
		"tgt": "She did the same with three more pairs before finally deciding there was nothing she liked and she got dressed again and walked out."
	},
	{
		"src": "\"Sie schien es nicht zu st\u00f6ren, dass sie jemand beobachtete - oder \u00fcber die Person zu denken, die unter Umst\u00e4nden die Unterhosen kaufen w\u00fcrde, die sie anprobiert hatte.\"",
		"tgt": "'She didn't seem to care who was watching - or think about the person who would eventually buy the knickers she'd been trying on.'"
	},
	{
		"src": "Frau Davidson, 33, die in Kent lebt, sagte:\"Wie widerlich zu denken, dass jemand Unterhosen mit nach Hause nehmen w\u00fcrde, die eine andere Person anhatte und die nicht gewaschen wurden.\"",
		"tgt": "Ms Davidson, 33, who lives in the Kent town, said: 'How disgusting to think someone is going to take home knickers that another person has been wearing and they haven't been cleaned.'"
	},
	{
		"src": "Der Vorfall ereignete sich am Dienstag nachmittag.",
		"tgt": "The incident happened on Tuesday afternoon."
	},
	{
		"src": "Frau Davidson f\u00fcgte hinzu:\"Wie ich mitbekommen habe, haben die Mitarbeiter versucht die Kleidungsst\u00fccke aus dem Verkauf zu ziehen, nachdem sie ging - was genauso gut ist.\"",
		"tgt": "Ms Davidson added: 'I gather the staff apparently tried to remove the garments from sale after she had left - which is just as well.'"
	},
	{
		"src": "\"Ich w\u00fcrde es hassen, mit einem neuen Paar Unterhosen nach Hause zu gehen und herauszufinden, dass eine andere Frau sie anhatte und wieder auszog und sie nicht gewaschen wurden.\"",
		"tgt": "'I'd hate to get home with a new pair of knickers and find another woman had put them on and taken them off again, and they hadn't been washed.'"
	},
	{
		"src": "Ein Sprecher von Primark sagte:\"Primark ist sich des Vorfalls, der sich am Dienstag, dem 9. August in unserer Filiale in Folkstone ereignete, bewusst.\"",
		"tgt": "A Primark spokesman said: 'Primark is aware of an incident which took place in our Folkestone store on Tuesday August 9.'"
	},
	{
		"src": "Alle in Frage kommenden Produkte wurden aus dem Verkauf gezogen.",
		"tgt": "All the product in question has been removed from sale."
	},
	{
		"src": "Wie man sich mit Krav Maga vor Waffenangriffen sch\u00fctzt",
		"tgt": "How to defend yourself from gun attacks using Krav Maga"
	},
	{
		"src": "Die Welt drau\u00dfen ist ein gef\u00e4hrlicher Ort, aber dieses Video von Dailymail.com k\u00f6nnte ihn f\u00fcr Sie etwas sicherer machen.",
		"tgt": "It's a dangerous world out there, but this video from Dailymail.com might help make it a little safer for you."
	},
	{
		"src": "Wir sprachen mit Rhon Mizrachi, einem Gro\u00dfmeister des Krav Maga Verbandes in New York, um herauszufinden, wie man mit bewaffneten R\u00e4ubern auf nahe Entfernung umgeht.",
		"tgt": "We spoke to Rhon Mizrachi, New York-based grandmaster of the Krav Maga Federation, to find out how to deal with gun-toting muggers at close range."
	},
	{
		"src": "Unabh\u00e4ngig davon, ob man sich Ihnen von vorne oder von hinten n\u00e4hert wird Ihnen dieses Video zeigen, wie Sie f\u00fcr Ihren R\u00e4uber den Spie\u00df umdrehen.",
		"tgt": "Whether you're approached from in front or behind, this video will show you how to turn the tables on your mugger."
	},
	{
		"src": "Wenn man sich Ihnen von hinten ann\u00e4hert, dann sollten Sie sich als Erstes umdrehen, sodass Sie Ihren Angreifer sehen k\u00f6nnen und \"sich aus der Schusslinie begeben\", sagt Mizrachi.",
		"tgt": "If approached from behind, Mizrachi says, the first thing to do is turn around, so that you can see your attacker and 'clear the line of fire'."
	},
	{
		"src": "Ergreifen Sie die Waffe dann zwischen Ihrem Vorderarm und Ihrer Schulter bevor Sie ihm mit Ihrem freien Ellbogen ins Gesicht schlagen.",
		"tgt": "You then grasp the gun between your forearm and shoulder before hitting them in the face with your free elbow."
	},
	{
		"src": "Schlagen Sie ihm sodann mit dem Knie in die Leiste und verdrehen Sie, w\u00e4hrend sich der Angreifer vor Schmerzen zusammenkr\u00fcmmt, die Waffe aus seinen H\u00e4nden. Schlagen Sie ihm mit dem Lauf ins Gesicht und bewegen Sie sich r\u00fcckw\u00e4rts, w\u00e4hrend sie die Waffe auf ihn richten.",
		"tgt": "A knee to the groin follows, and while the attacker doubles up in pain, you twist the gun from his hands, smack him in the face with the barrel and back up, keeping the weapon trained on him."
	},
	{
		"src": "Bei Angreifern, die sich von vorne n\u00e4hern, ist die Technik \u00e4hnlich - bewegen Sie Ihren K\u00f6rper aus der Schusslinie, ergreifen Sie die Waffe und verdrehen Sie sie, sodass der Angreifer nicht schie\u00dfen kann.",
		"tgt": "For gunmen approaching from the front, it's a similar technique - get your body out of the line of fire, grab the gun and twist it around so the villain can't fire."
	},
	{
		"src": "Verlagern Sie gleichzeitig das Gewicht auf die Waffe und schlagen Sie dem Angreifer auf die Brust, dann verdrehen Sie die Waffe aus seinem Griff, bevor sie sich r\u00fcckw\u00e4rts bewegen und die Waffe auf ihn richten.",
		"tgt": "At the same time, put weight on the gun and punch the attacker in the chest, then twist the gun from his grip before backing up and pointing it at him."
	},
	{
		"src": "Klingt schwierig?",
		"tgt": "Sounds tricky?"
	},
	{
		"src": "Sehen Sie sich das Video an, um genau zu sehen, wie es Mizrachi vormacht.",
		"tgt": "Check the video to see exactly how Mizrachi does it."
	},
	{
		"src": "Aber denken Sie daran, dass es bei einem Raub am sichersten ist, Ihr Geld zu \u00fcberreichen - sofern Sie kein Krav Maga Gro\u00dfmeister sind.",
		"tgt": "But remember that the safest way out of any mugging - if you're not a Krav Maga grandmaster - is to hand over your cash."
	},
	{
		"src": "Reisender Ian Wright schabt f\u00fcr einen Reisef\u00fchrer seine Zunge an den schmutzigsten Orten Europas",
		"tgt": "Traveller Ian Wright scrapes his tongue along Europe's dirtiest places for travel guide"
	},
	{
		"src": "Ein britischer Reisender unterzog sein Immunsystem und W\u00fcrgereflex einer ernsthaften Pr\u00fcfung - indem er einige der schmutzigsten und ekelhaftesten Orte Europas ableckte.",
		"tgt": "A British traveller has put his immune system and gag reflex to a serious test - by licking some of the dirtiest and disgusting places in Europe."
	},
	{
		"src": "Der Moderator und Reiseautor Ian Wright, 51, aus Suffolk schabte seine Zuge auf einem Euro-Schein, einem Gel\u00e4nder am Piccadilly Circus, einem Sp\u00fclknopf einer Zugtoilette sowie einem \u00f6ffentlichen Telefon in Russland, um die Widerstandsf\u00e4higkeit seines Immunsystems unter Beweis zu stellen.",
		"tgt": "Presenter and travel writer Ian Wright, 51, from Suffolk, scraped his tongue along a Euro note, a Piccadilly Circus hand rail, a train toilet's flush button and a Russian public telephone to prove the strength of his immune system."
	},
	{
		"src": "Vor dem Ablecken jedes Objekts verwendete er einen Luminometer, um sich und uns zu zeigen, auf was er sich einlassen wird.",
		"tgt": "Before licking each object, he used a luminometer to show himself, and us, just what he was getting in to."
	},
	{
		"src": "Aber das Experiment, das unter dem Titel \"The Lickhiker's Guide to Inner Strength\" verfilmt wurde, brachte einige \u00fcberraschende Ergebnisse ans Tageslicht.",
		"tgt": "But the experiment, which has be made into a film called The Lickhiker's Guide to Inner Strength, threw up some surprising results."
	},
	{
		"src": "Der Gedanke, den Sp\u00fclknopf einer Zugtoilette abzulecken, der bereits von Tausenden anderen benutzt wurde, mag v\u00f6llig absto\u00dfend sein, doch tats\u00e4chlich befinden sich in einer K\u00fcchensp\u00fcle mehr schlechte Bakterien.",
		"tgt": "The thought of licking a train's flush button used by thousands of other may be utterly repellent, but in fact there are more bad bacteria in a kitchen sink."
	},
	{
		"src": "Auf seiner Reise durch Europa sprach Herr Wright mit \u00c4rzten und medizinischen Fachkr\u00e4ften \u00fcber die F\u00f6rderung von Darmbakterien sowie \u00fcber seine eigene Gesundheit.",
		"tgt": "All the way along his trip through Europe, Mr Wright spoke to doctors and medical professionals about boosting gut bacteria and about his own health."
	},
	{
		"src": "Gl\u00fccklicherweise hinterlie\u00df nichts, was er ableckte, mehr als einen schlechten Nachgeschmack im Mund.",
		"tgt": "Fortunately, nothing he licked left him with anything more than a bad taste in his mouth."
	},
	{
		"src": "Herr Wright wurde bekannt daf\u00fcr, die Widerstandsf\u00e4higkeit seines Darms zu testen, indem er durch die Welt reiste und eigenartige sowie wundervolle Dinge a\u00df.",
		"tgt": "Mr Wright became known for testing the durability of his gut by travelling around the world and eating weird and wonderful things."
	},
	{
		"src": "Von \u00f6ffentlichen Gel\u00e4ndern an Bahnh\u00f6fen bis hin zu Sp\u00fclkn\u00f6pfen von Toiletten, die Aufgabe stellte sein Immunsystem definitiv unter eine Probe",
		"tgt": "From public handrails in train stations to a toilet flush button the task definitely tested his immune system"
	},
	{
		"src": "Im Film erz\u00e4hlte er: \"Bereits als Kind war ich relativ unbesorgt, was meine Gesundheit betrifft und ich habe alle m\u00f6glichen Dinge in meinen Mund gesteckt, Erde, W\u00fcrmer und Schlammwasser.\"",
		"tgt": "In the movie made about it he said: 'Ever since I was a kid I have been fairly carefree with my health and I've put all sorts of things in my mouth from soil, eating worms and muddy water.'"
	},
	{
		"src": "Im Film wurde er seinem Ruf auf jeden Fall gerecht.",
		"tgt": "He certainly proved his reputation during the film."
	},
	{
		"src": "Das Einzige was er ablehnte, war eine schmutzige \u00f6ffentliche Toilette in Russland.",
		"tgt": "The only thing he turned down was a filthy Russian public toilet."
	},
	{
		"src": "Sein Probeabstrich zeigte eine Luminometerzahl von \u00fcber 4000 Einheiten.",
		"tgt": "His sample swab showed a luminometer count of over 4000 units."
	},
	{
		"src": "Im Vergleich dazu betr\u00e4gt die Luminometerzahl frisch gewaschener H\u00e4nde weniger als 60.",
		"tgt": "By comparison, freshly washed hands should come in under 60."
	},
	{
		"src": "Aber es gab eine russische Toilette, die er sich weigerte abzulecken, nachdem ihre Luminometerzahl \u00fcber 4000 Einheiten betrug, w\u00e4hrend frisch gewaschene H\u00e4nde eine von weniger als 60 aufweisen",
		"tgt": "But there was one Russian public toilet he refused to lick after his luminometer count was over 4000 units, when freshly washed hands are less than 60"
	},
	{
		"src": "Herr Wright und der finnische Hersteller von Milchprodukten Valio produzierten den Reisefilm \"The Lickhiker's Guide to Inner Strength\", der die Bakterienzahl an verschiedenen Orten wie dem Badezimmer zeigt",
		"tgt": "Mr Wright and Finnish dairy producer Valio have produced the traveller's film called The Lickhiker's Guide to Inner Strength which shows the bacteria count in different place like in the bathroom"
	},
	{
		"src": "In dem Film sagt er: \"Das kommt dem Schlimmsten, was ich in einer Toilette gerochen habe, nahe.\"",
		"tgt": "He said in the film: 'That is close to one of the worst things I have smelled in a toilet.'"
	},
	{
		"src": "Es gibt nichts Schmutzigeres als das!",
		"tgt": "There's nothing more dirty than that!"
	},
	{
		"src": "Ich werde hier nichts anlecken, weil es hier drinnen ekelhaft ist.",
		"tgt": "I'm not going to lick anything because it's disgusting in there."
	},
	{
		"src": "\"The Lickhiker's Guide to Inner Strength\" wurde in Zusammenarbeit mit dem finnischen Hersteller von Milchprodukten Valio produziert.",
		"tgt": "The Lickhiker's Guide to Inner Strength was produced in conjunction with Finnish dairy producer Valio."
	},
	{
		"src": "Das Unternehmen stattet Herrn Wright mit Valio Gefilus aus, das sowohl Milchs\u00e4urebakterien als auch Vitamin C und D enth\u00e4lt, um die F\u00f6rderung von Darmbakterien und des Immunsystems zu unterst\u00fctzen.",
		"tgt": "The company provided Mr Wright with Valio Gefilus, which contain lactic acid bacteria as well as vitamins C and D to help boost people's gut bacteria and immune systems."
	},
	{
		"src": "Valios Senior Venice President f\u00fcr Snacks, S\u00e4fte und Neue Kategorien Niko Vuorenmaa sagt: \"Wir wollten den Konsumenten wirklich etwas Neues bieten.",
		"tgt": "Valio's Senior Vice President of Snacks, Juice and New Categories Niko Vuorenmaa said: 'We really wanted to offer consumers something new."
	},
	{
		"src": "Etwas, das faszinierend zum Anschauen ist und gleichzeitig die Vorteile von Probiotika erkl\u00e4rt.",
		"tgt": "Something that would be fascinating to watch and at the same time explain the benefits of probiotics."
	},
	{
		"src": "Wir f\u00fchrten verr\u00fcckte Brainstormings durch, die damit endeten, dass wir sagten \"Lass uns Ian anrufen.\"",
		"tgt": "We did a lot of crazy brainstorming that ended in the idea \"let's call Ian.\""
	},
	{
		"src": "Sie behaupten, dass das Interesse an Darmgesundheit zu einem globalen Ph\u00e4nomen wird",
		"tgt": "They claim the interest in gut health is becoming a global phenomenon"
	},
	{
		"src": "Anstelle nur \u00fcber die Produkte zu reden, wollten wir sie in einen gr\u00f6\u00dferen Kontext stellen - die guten und schlechten Bakterien in unserer allt\u00e4glichen Umgebung, die Bedeutung der Darmgesundheit und wie sie mit dem Immunsystem verkn\u00fcpft ist.",
		"tgt": "Instead of just talking about the products, we wanted to put them into a bigger context - the good and bad bacteria in our everyday environment, the importance of gut health and how it's linked to the immune system."
	},
	{
		"src": "Das wachsende Interesse an der Darmgesundheit ist ein globales Ph\u00e4nomen und mit dem Dokumentarfilm konnten wir den Konsumenten dar\u00fcber mehr Informationen auf eine interessante Art und Weise bereitstellen.",
		"tgt": "Growing interest in gut health is a global phenomenon and with the documentary we could provide consumers with more information about it in an interesting way."
	},
	{
		"src": "Ich denke auch, dass der Film zeigt, dass wir einen tollen Sinn f\u00fcr Humor haben!",
		"tgt": "I also think the film shows we have a great sense of humour!"
	},
	{
		"src": "Tom Hakala, der die Regie des Films f\u00fchrte, f\u00fcgte hinzu: \"Lassen Sie es mich so sagen - Ich h\u00e4tte meinen Respekt f\u00fcr Ian verloren, wenn er einige der Dinge geleckt h\u00e4tte, die ich ihm angewiesen habe zu lecken, so wie die ekelhafte russische Toilette, die in dem Film gezeigt wird.\"",
		"tgt": "Tom Hakala, who directed the film, added: 'Let's put it this way - I would have lost my respect for Ian if he had licked some of the things I asked him to, like the disgusting Russian toilet that's shown in the film.'"
	},
	{
		"src": "Nat\u00fcrlich gab es Dinge, bei denen es einfacher war, Ian dazu zu bringen, sie anzulecken und andere, bei denen dies ziemlich schwierig war.",
		"tgt": "Naturally some things were easier to get Ian to lick, some were pretty tough."
	},
	{
		"src": "Ich bin froh, dass wir einige dieser schmutzigen Leckereien auf Film aufgenommen haben.\"",
		"tgt": "I'm glad we got some of those dirty licks caught on tape.'"
	},
	{
		"src": "In einer von Valio durchgef\u00fchrten Umfrage aus dem Jahr 2015 assoziierten 84 Prozent aller Befragten Milchs\u00e4urebakterien insbesondere mit dem Wohlbefinden von Magen und Darm und 58 Prozent sagten aus, dass sie zumindest gelegentlich Produkte verwenden, die beigef\u00fcgte Milchs\u00e4urebakterien enthalten.",
		"tgt": "In a survey conducted in 2015 by Valio, 84 per cent of the respondents associated lactic acid bacteria specifically with the well-being of the stomach and gut and 58 per cent said they use at least occasionally products containing added lactic acid bacteria."
	},
	{
		"src": "Asoziale Familie zerst\u00f6rt vor Delogierung Sozialwohnung in Saltash, Cornwall",
		"tgt": "Family of yobs destroyed Saltash, Cornwall council house ahead of eviction"
	},
	{
		"src": "Eine asoziale Familie verlie\u00df ihre Sozialwohnung nach einer Delogierung mit einem Schaden in H\u00f6he von \u00a350.000, weil sie ihre Nachbarn terrorisiert hatte.",
		"tgt": "A family of yobs left their council house with \u00a350,000 worth of damage after they were evicted for terrorising their neighbours."
	},
	{
		"src": "Tanya Skeldon und ihr Partner Shaun Trebilcock wurden nach einer langen Liste an Beschwerden von ihrem Anwesen in Saltash, Cornwall geworfen.",
		"tgt": "Tanya Skeldon and her partner Shaun Trebilcock have been kicked out of the property in Saltash, Cornwall, after a long list of complaints against them."
	},
	{
		"src": "Nachdem sie gewaltsam aus ihrem Anwesen entfernt wurden, fanden schockierte Angestellte der Wohnungsgenossenschaft das Eigentum in einem irreparablen Zustand vor.",
		"tgt": "After they were forcibly removed from the property, shocked housing associations officers found the property in a state of disrepair."
	},
	{
		"src": "Die W\u00e4nde wiesen klaffende L\u00f6cher auf, Holzdielen wurden aufgerissen, M\u00fcll wurde auf dem Fu\u00dfboden verstreut und Graffiti wurde an die W\u00e4nde geschmiert.",
		"tgt": "The walls were left with gaping holes, floorboards were ripped up, rubbish was strewn over the floor and graffiti was daubed on the walls."
	},
	{
		"src": "Die Familie wurden umgesiedelt und es wird angenommen, dass sie jetzt in einer privaten Unterkunft lebt",
		"tgt": "The family have now been moved on and are believed to be living in a private accomodation"
	},
	{
		"src": "Donna McEvoy, die f\u00fcr die Hausverwaltung bei Cornwall Housing arbeitet, sagte, dass sie bef\u00fcrchtet, dass die Wohnung nicht mehr zu reparieren sei.",
		"tgt": "Donna McEvoy, housing manager at Cornwall Housing, said she feared it might be beyond saving."
	},
	{
		"src": "Sie sagte: \"Es war f\u00fcr die Leute hier ein absoluter Albtraum und ich bin der Ansicht, dass Leute nicht auf diese Weise leben m\u00fcssen.",
		"tgt": "She said: 'It's been an absolute nightmare for people down here and I don't think people should have to live like that."
	},
	{
		"src": "Es gibt viele Dinge zu ber\u00fccksichtigen, da dieses Anwesen vermutlich als nicht so sch\u00f6ner Teil Cornwalls angesehen werden wird.",
		"tgt": "There are a lot of things to weigh up because this property will probably be known by the not-so-nice element of Cornwall."
	},
	{
		"src": "Die Familie ist ber\u00fcchtigt und ihr Ruf ist es ebenfalls.",
		"tgt": "This family are notorious and their name is notorious."
	},
	{
		"src": "Das Paar hatte drei S\u00f6hne, die zwischenzeitlich in der Wohnung lebten und die Polizei sagte, dass der Terror, die die Familie zugef\u00fcgt hatte, Stra\u00dfenk\u00e4mpfe mit Baseballschl\u00e4gern, Einsch\u00fcchtern von Anwohnern, Drogenmissbrauch, Drogenhandel und \u00fcberm\u00e4\u00dfiges Schreien, Streiten und Fluchen umfasste.",
		"tgt": "The couple had three sons who lived at the property intermittently and police say the reign of terror the family inflicted included fighting in the street with baseball bats, intimidating nearby residents, drug use, drug dealing and excessive shouting, arguing and swearing."
	},
	{
		"src": "Skeldon, 47, dessen Name auf dem Mietvertrag stand, bekam im Juni eine Anordnung f\u00fcr antisoziales Verhalten.",
		"tgt": "Skeldon, 47, whose name was on the tenancy, was given an antisocial behaviour order in June."
	},
	{
		"src": "In einigen R\u00e4umen des Hauses, das unter Umst\u00e4nden abgerissen werden wird, wurde alter M\u00fcll gefunden",
		"tgt": "Old rubbish was found in a number of the rooms of the house, which may be demolished"
	},
	{
		"src": "Es wurden in dem Anwesen, in dem in der Vergangenheit Drogen gehandelt wurden, die Holzdielen aufgerissen",
		"tgt": "Floor boards had been pulled up in the property, from which drugs had been dealt in the past"
	},
	{
		"src": "Nachbarn sagten aus, dass sie sie auf der Stra\u00dfe k\u00e4mpfen sahen und regelm\u00e4\u00dfig die Polizei angerufen werden musste",
		"tgt": "Neighbours say they were seen fighting in the street and police were regularly called"
	},
	{
		"src": "Cornwall Housing delogierte sie und ihren Partner diese Woche gewaltsam von dem Anwesen, nachdem sie ihnen eine verl\u00e4ngerte Frist von 11 Wochen gab, um freiwillig auszuziehen.",
		"tgt": "Cornwall Housing evicted her and her partner forcefully from the property this week after giving them an extended period of 11 weeks to move on voluntarily."
	},
	{
		"src": "Die Delogierung wurden von erleichterten Nachbarn bejubelt, die sagten, dass ihr Leben zur H\u00f6lle gemacht wurde.",
		"tgt": "The eviction was hailed by relieved neighbours who said their lives had been made a living hell."
	},
	{
		"src": "Einer sagte aus: \"Sie scherten sich um niemanden.\"",
		"tgt": "One said: 'They didn't care about anybody.'"
	},
	{
		"src": "Wir lebten 20 Jahre neben ihnen und es war immer schlimm.",
		"tgt": "We lived next to them for 20 years and it's always been bad."
	},
	{
		"src": "Die unz\u00e4hligen Male, die wir die Polizei hier sagen, sind unglaublich.",
		"tgt": "The amount of times we've seen the police down here is unbelievable."
	},
	{
		"src": "\"Heute morgen konnten wir nicht schlafen.\"",
		"tgt": "'This morning, we couldn't sleep.'"
	},
	{
		"src": "Wir standen auf, weil es hier so ruhig war - das sind wir nicht gewohnt!",
		"tgt": "We got up because it was so quiet here - we're not used to that!"
	},
	{
		"src": "Jetzt, wo sie endlich weg sind, wird es sch\u00f6n werden.",
		"tgt": "It's going to be lovely now that they're finally gone."
	},
	{
		"src": "Adam Fitzpatrick, Neighbourhood Enforcement Manager von Cornwall Housing, sagte aus, dass es die Familie verabs\u00e4umt h\u00e4tte mit den lokalen Beh\u00f6rden zu kooperieren.",
		"tgt": "Adam Fitzpatrick, Cornwall Housing's neighbourhood enforcement manager, said the family failed to cooperate with the local authority."
	},
	{
		"src": "Die Familie lebte in dem Haus, zu dem die Polizei in regelm\u00e4\u00dfigen Abst\u00e4nden gerufen wurde, 20 Jahre lang",
		"tgt": "The family have lived in the house for 20 years, with police regularly called to the property"
	},
	{
		"src": "Auf der \u00fcberwucherten Seite des Gemeindehauses wurden M\u00fcll und alte Spielzeuge hinuntergeworfen",
		"tgt": "Rubbish and old toys have been thrown down the overgrown side of the council house"
	},
	{
		"src": "Er f\u00fcgte hinzu:\"Es ist eine Schande, dass es der Mieter verabs\u00e4umte, jegliche Verantwortung f\u00fcr ihr Verhalten und das ihrer Familie anzunehmen, da eine Delogierung immer der letzte Schritt ist, der Cornwall Housing in Betracht zieht.",
		"tgt": "He added: 'It is a shame that the tenant failed to accept any responsibility for the behaviour of her and her family as eviction is always the last course of action that Cornwall Housing considers."
	},
	{
		"src": "Das war ein sehr schwieriger Fall, da das Verhalten extrem war und ihre Taten f\u00fcr ihre Nachbarn schrecklich mitanzusehen sein mussten.",
		"tgt": "This was a very difficult case as the behaviour was extreme and their actions must have been terrifying for her neighbours to witness."
	},
	{
		"src": "Ich sch\u00e4tze all die Arbeit, die mein Team, die Polizei von Devon und Cornwall sowie Mitglieder der Gemeinde, die mutig auf uns zugegangen sind und uns die Informationen haben zukommen lassen haben, geleistet haben.",
		"tgt": "I appreciate all the work that has been put in by my team, Devon and Cornwall Police and members of the community who bravely came forward to give us information."
	},
	{
		"src": "Ich hoffe, dass diese Entwicklung einigen Nachbarn Trost spenden wird und die Botschaft vermittelt, dass antisoziales Verhalten nicht toleriert wird.",
		"tgt": "I hope that this development will give some comfort to the neighbours and sends out a message that antisocial behaviour will not be tolerated."
	},
	{
		"src": "Fitzpatrick sagte, dass alle drei S\u00f6hne zu unterschiedlichen Zeiten in dem Haus gelebt h\u00e4tten, aber dass sie alle \u00fcber 20 seien.",
		"tgt": "Mr Fitzpatrick said that the three sons had all lived at the property at different times but said they were all in their 20s."
	},
	{
		"src": "Eine schmutzige Matratze, die in einem der Schlafzimmer des Hauses nach der Delogierung auf dem Boden zur\u00fcckgelassen wirde",
		"tgt": "A dirty mattress left on the floor of one of the bedrooms in the house after the eviction"
	},
	{
		"src": "Arbeiter der Hausverwaltung werden nun M\u00fcllberge wegr\u00e4umen m\u00fcssen, die das Haus umgeben",
		"tgt": "Housing workers will now have to clear away the piles of rubbish which surround the house"
	},
	{
		"src": "2014 f\u00fchrte die Polizei eine Razzia in dem Haus durch und fand \u00fcber 70g Cannabis sowie Waagen, Paraphernalien und Bargeld in H\u00f6he von \u00a31.700.",
		"tgt": "In 2014, police raided the property and found more than 70g in cannabis as well as scales, paraphernalia and \u00a31,700 in cash."
	},
	{
		"src": "Skeldon erhielt eine Geldstrafe, nachdem sie sich des Besitzes einer Droge der Klasse B in Handelsabsicht schuldig bekannt hatte.",
		"tgt": "Skeldon was fined after pleading guilty to possession of a Class B drug with intent to supply."
	},
	{
		"src": "Sie behauptete, dass das Geld f\u00fcr ein Grabstein ihres Sohnes Lee Skeldon sei, der 2013 bei einem Autounfall ums Leben kam.",
		"tgt": "She claimed the money was going towards a headstone for her son, Lee Skeldon, who died in a car crash in 2013."
	},
	{
		"src": "Nachdem sie ohne Obdach waren, wird davon ausgegangen, dass Tanya und ihr Partner jetzt in einer privaten Unterkunft in Plymouth leben.",
		"tgt": "After being made homeless, it is understood that Tanya and her partner are now living in private housing in Plymouth."
	},
	{
		"src": "Viele Zimmerw\u00e4nde des Hauses waren mit Graffiti beschmiert.",
		"tgt": "The walls of many of the house's rooms had graffiti scrawled across them."
	},
	{
		"src": "Die Polizei sagt, dass sie Mieter delogieren wird, die sich nicht an die Hausordnung halten",
		"tgt": "Police say they will seek to evict tenants who flout the rules of their tenancies"
	},
	{
		"src": "Angela Crow von der Polizei von Devon und Cornwall teilte mit, dass die Delogierung eine klare Warnung an die anderen Mieter sei, die sich nicht an die Hausordnung halten.",
		"tgt": "Angela Crow, of Devon and Cornwall Police, said the eviction sent a clear warning to other tenants who continue to flout the rules."
	},
	{
		"src": "\"Dies geht an diejenigen, die sich denken, dass sie sich ohne Selbstvorw\u00fcrfe benehmen k\u00f6nnen sowie an diejenigen, die von so einem Verhalten gesch\u00e4digt wurden,\" sagte sie.",
		"tgt": "'This sends out to those who feel that they can behave without recrimination, as well as those blighted by such behaviour,' she said."
	},
	{
		"src": "Die Polizei von Devon und Cornwall wird nie kriminelles und antisoziales Verhalten tolerieren, die weiterhin mit Partnern zusammenarbeiten werden, um unsere Gemeinden zu sch\u00fctzen.",
		"tgt": "Criminal and antisocial behaviour will never be tolerated by Devon and Cornwall Police, who will continue to work with partners to protect our communities."
	},
	{
		"src": "Touristen in Portugal in Panik versetzt, nachdem ein tieffliegender Milit\u00e4rjet Strand \u00fcberfliegt",
		"tgt": "Tourists in Portugal are left terrified as a low-flying military jet flies skims beach"
	},
	{
		"src": "Sonnenanbeter in Aveiro, Portugal erlebten den Schock ihres Lebens",
		"tgt": "Tourists sun worshipping in Aveiro, Portugal, had the shock of their lives"
	},
	{
		"src": "Ein portugisiesches P-3C Orion Flugzeug der Luftstreitkr\u00e4fte legte einen unglaublichen Sturzflug hin",
		"tgt": "A Portuguese air force P-3C Orion plane swooped in incredibly low"
	},
	{
		"src": "Die Luftstreitkr\u00e4fte gaben an, dass es sich auf einem Trainingsflug befand, aber beharrten darauf, dass kein Sicherheitsrisiko vorlag",
		"tgt": "The air force said it was on a training flight but insisted no risk to safety"
	},
	{
		"src": "Dies war der Moment, in dem ver\u00e4ngstigte Touristen anfangen in Panik zu geraten, nachdem ein tieffliegender Jet \u00fcber einen vollen Strand hinabst\u00fcrzt.",
		"tgt": "This is the moment terrified tourists start to panic as a low-flying jet swooped down over a packed beach."
	},
	{
		"src": "Dramatische Videoaufnahmen zeigten, wie das Milit\u00e4rflugzeug fast in greifbarer N\u00e4he \u00fcber den Sonnenanbetern auf dem Strandabschnitt in Aveiro im Norden Portugals flog.",
		"tgt": "Dramatic footage showed the military plane almost coming within touching distance of sunseekers on the stretch of sand in Aveiro, northern Portugal."
	},
	{
		"src": "Die Urlauber sprangen auf, als sie sich verst\u00e4ndlicherweise anfingen, Sorgen \u00fcber den L\u00e4rm der D\u00fcsentriebwerke zu machen, ohne zun\u00e4chst zu sehen, was durch die Wolken auf sie zukam.",
		"tgt": "Holidaymakers rose to their feet as they became understandably concerned about the noise from the jet engines without being able to see at first what was coming their way through the clouds."
	},
	{
		"src": "Der Vorfall ereignete sich gestern Nachmittag in Costa Nova, in der N\u00e4he von Aveiro.",
		"tgt": "The incident happened in Costa Nova near Aveiro yesterday afternoon."
	},
	{
		"src": "Daniel Fernandes, einer der vielen Urlauber, die Videos \u00fcber den dramatischen Fly-By in den sozialen Medien posteten, sagte: \"Es flog zweimal wirklich sehr tief vorbei und es gab einen Moment, als es so aussah, als w\u00fcrde es abst\u00fcrzen.\"",
		"tgt": "Daniel Fernandes, one of several holidaymakers who posted videos of the dramatic fly-by onto social media, said: 'It passed really low twice and there was a point when it looked like it was going to crash.'"
	},
	{
		"src": "Nuno Arroja f\u00fcgte hinzu: \"Ich war gerade am Surfen und es f\u00fchlte sich so an, als w\u00fcrde das Flugzeug auf mich herabfallen.\"",
		"tgt": "Nuno Arroja added: 'I was surfing and swear it felt like the plane was going to fall on top of me.'"
	},
	{
		"src": "Touristen am Strand von Aveiro waren in Panik versetzt, als das Flugzeug aus der Dunkelheit kam und unglaublich tief flog",
		"tgt": "Tourists on the beach at Aveiro were terrified when the plane appeared out of the murk and flew at an incredibly low altitude"
	},
	{
		"src": "Die portugiesischen Luftstreitkr\u00e4fte gaben heute an, dass sich der Pilot des P-3C Orion Flugzeugs auf einem Trainingsflug befand, um Fischerboote vor der K\u00fcste zu identifizieren und dabei so tief fliegen musste, dass dies die einzige M\u00f6glichkeit darstellte, sie zu erkennen.",
		"tgt": "The Portuguese Air Force said today the pilot of the P-3C Orion plane was on a training flight to identify fishing boats off the coast and had to drop so low because it was the only way of checking them."
	},
	{
		"src": "Der Sprecher sagte, dass der Jet aufgrund der schlechten Sichtverh\u00e4ltnisse durch sich in der N\u00e4he befindliche Fl\u00e4chenbr\u00e4nde etwas tiefer als \u00fcblich flog, allerdings beharrten die Luftstreitkr\u00e4fte darauf, dass die Sicherheit zu keiner Zeit gef\u00e4hrdet war.",
		"tgt": "He said the jet had flown slightly lower than normal because of poor visibility caused by the smoke from nearby wildfires, but the air force insisted no-one's safety had been compromised."
	},
	{
		"src": "Fl\u00e4chenbr\u00e4nde haben diesen Sommer Teile des portugiesischen Festlandes zerst\u00f6rt, bei denen auch vier Menschen auf der Insel Madeira zu Tode kamen.",
		"tgt": "Wildfires have devastated parts of mainland Portugal this summer as well as killing four people on the island of Madeira."
	},
	{
		"src": "Die portugiesischen Luftstreitkr\u00e4fte gaben heute an, dass der Pilot aufgrund der Verh\u00e4ltnisse - starker Nebel und Brandrauch - so tief fliegen musste, was seine Sicht einschr\u00e4nkte",
		"tgt": "The Portuguese air force said today the pilot had to fly low because of the conditions - thick fog and smoke from wildfires - which obscured his visibility"
	},
	{
		"src": "Das Flugzeug befand sich auf einem Trainingsflug, bei dem der Pilot Fischerboote als Teil der \u00dcbung identifizieren musste",
		"tgt": "The plane was on a training flight and the pilot was being asked to identify fishing boats as part of the exercise"
	},
	{
		"src": "Supercup: Barca mit Sorgen gegen Sevilla",
		"tgt": "Supercup: Barca is worried about facing Sevilla"
	},
	{
		"src": "Sevilla - Der FC Barcelona k\u00e4mpft am Sonntag um den ersten Schritt zum ersten Titelgewinn in der neuen Fu\u00dfball-Saison.",
		"tgt": "Seville - On Sunday, FC Barcelona will fight to take their first step towards their first title of the new football season."
	},
	{
		"src": "Die Katalanen treten im Duell um den spanischen Supercup ausw\u00e4rts gegen den FC Sevilla an, das R\u00fcckspiel steigt drei Tage sp\u00e4ter im Camp Nou.",
		"tgt": "The Catalan team will face off against FC Sevilla in an away game in Spain's Supercup; the second leg will take place three days later in Camp Nou."
	},
	{
		"src": "Der Doublegewinner muss im Kr\u00e4ftemessen mit dem unterlegenen Cupfinalisten und regierenden Europa-League-Champion unter anderen auf Neymar verzichten, der mit Brasilien das olympische Fu\u00dfball-Turnier bestreitet.",
		"tgt": "The two-time champions will have to face up to the defeated Cup finalists and reigning Europa League champions without Neymar, who is playing in the Olympic football tournament for Brazil."
	},
	{
		"src": "Au\u00dferdem fehlt auch Goalie Marc-Andre ter Stegen.",
		"tgt": "In addition, goalkeeper Marc-Andre ter Stegen is also missing."
	},
	{
		"src": "Der Deutsche erlitt im Training eine B\u00e4nderstauchung im Knie, womit die Einserfrage bei Barca zumindest vorerst zugunsten von Claudio Bravo gekl\u00e4rt ist.",
		"tgt": "During training the German pulled a ligament in his knee. At least it's clear who'll be wearing the number one jersey for Barca: Claudio Bravo."
	},
	{
		"src": "Der chilenische Internationale und Ter Stegen wetteifern in Barcelona schon seit zwei Jahren um den Status als Nummer eins.",
		"tgt": "The Chilean international and Ter Steigen have been competing for number one status for two years now."
	},
	{
		"src": "Coach Luis Enrique verzichtete diesbez\u00fcglich bisher auf eine klare Entscheidung und lie\u00df Bravo in der Liga, daf\u00fcr aber Ter Stegen in den meisten \u00fcbrigen Bewerben den Vortritt.",
		"tgt": "Coach Luis Enrique has so far refused to make a clear decision either way, allowing Bravo to wear the jersey in league games, but giving it to Ter Stegen in most of their other matches."
	},
	{
		"src": "Vor dem ersten Pflichtspiel der neuen Spielzeit gibt es beim spanischen Meister Zweifel \u00fcber den Fitnesszustand der Mannschaft, die am Samstag in einem Testspiel von Liverpool mit 0:4 gedem\u00fctigt wurde.",
		"tgt": "Ahead of the first compulsory game of the new season there were doubts as to the Spanish champions' fitness: they lost 0-4 to Liverpool in a friendly game on Saturday."
	},
	{
		"src": "Auch beim 3:2 im Probegalopp gegen Sampdoria am Mittwoch wussten Lionel Messi und Co. noch nicht wirklich zu \u00fcberzeugen.",
		"tgt": "Even with 3-2 in a friendly against Sampdoria on Wednesday, Lionel Messi and co. were not really all that convincing."
	},
	{
		"src": "Sevilla wiederum hat die 2:3-Niederlage nach Verl\u00e4ngerung im europ\u00e4ischen Supercup gegen Real Madrid zu verdauen und strebt den zweiten Triumph bei der \"Supercopa de Espana\" an.",
		"tgt": "On the other hand, Sevilla have to swallow their 2-3 extra-time defeat against Real Madrid in the Supercup, and are aiming for a second victory in the \"Supercopa de Espana\"."
	},
	{
		"src": "Barcelona ist mit bisher elf Erfolgen der Rekordsieger in diesem Bewerb.",
		"tgt": "With eleven victories, Barcelona are the current record-holders for this competition."
	},
	{
		"src": "Ma Long in einer eigenen Liga zu Tischtennis-Gold",
		"tgt": "Ma Long is in a league of his own, taking Gold in the table tennis"
	},
	{
		"src": "Rio de Janeiro - Der Chinese Ma Long ist der neue Tischtennis-Olympiasieger.",
		"tgt": "Rio de Janeiro - Ma Long, from China, is the new table tennis Olympic champion."
	},
	{
		"src": "Der 27-J\u00e4hrige besiegte am Donnerstag in Rio de Janeiro in einem einseitigen Finale seinen Landsmann und \"Titelverteidiger\" Zhang Jike 4:0 (12,5,4,4).",
		"tgt": "On Thursday, the 27-year-old beat his fellow countryman and \"defending champion\" Zhang Jike in Rio de Janeiro 4-0 in a one-sided final (12,5,4,4)."
	},
	{
		"src": "Damit holte der Weltranglisten-Erste den \"Golden Grand Slam\" mit Erfolgen bei WM, Weltcup, World-Tour-Finalturnier und eben Olympia.",
		"tgt": "This gave the world number one the \"golden grand slam\", winning the World Championship, the World Cup, the final tournament of the World Tour, and the Olympics."
	},
	{
		"src": "Bronze ging an den Japaner Jun Mizutani.",
		"tgt": "The bronze medal went to Jun Mizutani from Japan."
	},
	{
		"src": "Die beiden Chinesen haben es wie erwartet in das Endspiel geschafft und machten sich den Titel untereinander aus.",
		"tgt": "The two Chinese men made it to the final, as expected, and fought each other for the title."
	},
	{
		"src": "Damit war klar, dass zum dritten Mal in Folge ein Chinese den Einzel-Titel im Zeichen der F\u00fcnf Ringe holen w\u00fcrde.",
		"tgt": "It was clear that, for the third time in a row, a Chinese athlete would take the singles title at the Olympics."
	},
	{
		"src": "Letzter Nicht-Chinese auf dem obersten Olympia-Treppchen war der ehemalige SVS-N\u00d6-Legion\u00e4r Ryu Seung-min aus S\u00fcdkorea.",
		"tgt": "The last non-Chinese athlete on the top step of the Olympic podium was former SVS Lower Austria legionary Ryu Seung-min from South Korea."
	},
	{
		"src": "Ma und Zhang waren sich an der Platte allein \u00fcberlassen, zwischen den S\u00e4tzen und bei Time-outs hatten sie keine Coaches bei sich.",
		"tgt": "Ma and Zhang were alone at the table: they had no coaches with them between sets and during time-outs."
	},
	{
		"src": "Die hatten sich auf die Trib\u00fcne zur\u00fcckgezogen und lie\u00dfen ihre Sch\u00fctzlinge im fairen Wettkampf alleine aufeinander los.",
		"tgt": "They had returned to the stands, leaving their charges alone to fight a fair battle against each other."
	},
	{
		"src": "\"Die Matches bis hierher habe ich f\u00fcr mein Land gespielt.\"",
		"tgt": "\"Up until now, I have played for my country.\""
	},
	{
		"src": "\"Im Finale spiele ich f\u00fcr mich\", hatte Zhang folgerichtig gesagt.",
		"tgt": "\"In the final, I'm playing for myself,\" Zhang summarised."
	},
	{
		"src": "Nach der Partie posierten Gold- und Silbermedaillengewinner mit der China-Fahne.",
		"tgt": "After the game, the gold and silver medallists posed with the Chinese flag."
	},
	{
		"src": "Das Match selbst war unerwartet einseitig.",
		"tgt": "The match itself was unexpectedly one-sided."
	},
	{
		"src": "Ma hatte mit seinem 28-j\u00e4hrigen Gegner nur im ersten Satz wirklich zu k\u00e4mpfen.",
		"tgt": "Ma only had to fight off his 28-year-old opponent in the first set."
	},
	{
		"src": "Danach bestimmte er das Tempo an der Platte und lie\u00df Zhang ab da nur noch insgesamt 13 Punkte.",
		"tgt": "Afterwards, he set the pace on the table, and only let Zhang score a total of 13 points."
	},
	{
		"src": "Durch die \u00dcberlegenheit von Ma entwickelte sich nicht das erwartete mitrei\u00dfende Match.",
		"tgt": "Ma's dominance meant that the match was not as exciting as expected."
	},
	{
		"src": "Doch waren nichtsdestotrotz ausreichend atemberaubende Ballwechsel zu sehen.",
		"tgt": "But nevertheless, there were some breathtaking volleys to be seen."
	},
	{
		"src": "Mizutani gewann das Spiel um Bronze gegen den 40-j\u00e4hrigen Wladimir Samsonow 4:1.",
		"tgt": "Mizutani won the bronze medal match against 40-year-old Wladimir Samsonow 4-1."
	},
	{
		"src": "Der Wei\u00dfrusse hatte sich in seinem Viertelfinale gegen den deutschen Europameister Dimitrij Ovtcharov eine Rippenverletzung zugezogen, war danach in \u00e4rztlicher Behandlung, musste sich \"letztlich\" mit Blech begn\u00fcgen.",
		"tgt": "The Belarussian had injured his rib in his quarter-final against German European Champion Dimitrij Ovtcharov, and was given medical treatment, and ultimately had to content himself with fourth place."
	},
	{
		"src": "Die Schweden Jan-Ove Waldner (38/2004) und J\u00f6rgen Persson (42/2008) waren \u00fcbrigens in \u00e4hnlich hohem Tischtennisalter Olympia-Vierte geworden.",
		"tgt": "Jan-Ove Waldner from Sweden (38/2004) and J\u00f6rgen Persson (42/2008) also reached fourth place at the Olympics at a similarly old age for table tennis."
	},
	{
		"src": "Donald Trump r\u00e4umt \u2033gewaltige Probleme\u2033 im Wahlkampf ein",
		"tgt": "Donald Trump admits there are \"huge problems\" with his election campaign"
	},
	{
		"src": "Die F\u00fchrung der US-Republikaner wird von massiven Sorgen geplagt, auch in traditionell konservativen Bundesstaaten ihre Mehrheit einzub\u00fc\u00dfen.",
		"tgt": "The US Republicans' lead is plagued by significant fears that they might lose their majority, even in states that are traditionally conservative."
	},
	{
		"src": "Pr\u00e4sidentschaftskandidat Donald Trump gab jetzt Schw\u00e4chen seiner Wahlkampagne in der bisherigen republikanischen Hochburg Utah zu.",
		"tgt": "Presidential candidate Donald Trump has now admitted to the weaknesses of his election campaign in Utah, formerly a Republican stronghold."
	},
	{
		"src": "Ein seltener Moment, in dem der normalerweise gro\u00dfspurig und selbstsicher auftretende Multimillion\u00e4r so etwas wie Bedenken \u00e4u\u00dferte, wie Korrespondenten berichteten.",
		"tgt": "It was a strange moment - the multi-millionaire normally puts on a pompous, self-assured performance, but this time he expressed something analogous to doubt, as correspondents report."
	},
	{
		"src": "Nachdem er 16 Rivalen innerhalb des eigenen republikanischen Lagers aus dem Rennen geworfen hat, wachsen nun die Zweifel an seinem Erfolg im Kampf um das Wei\u00dfe Haus.",
		"tgt": "After he had beaten 16 rivals from within the Republican camp, doubt is now growing as to whether he will be successful in the race for the White House."
	},
	{
		"src": "\"Wir haben gewaltige Probleme in Utah\", sagte Trump vor evangelikalen Christen, die er um Unterst\u00fctzung in wichtigen Bundesstaaten wie Ohio, Florida oder Virginia bat.",
		"tgt": "\"We have huge problems in Utah,\" Trump said to an audience of evangelical Christians whom he asked for assistance in key states such as Ohio, Florida or Virginia."
	},
	{
		"src": "Schuld seien falsche Berichte \u00fcber seine Kandidatur, nahm er wieder seine bekannte Medienschelte auf.",
		"tgt": "He blamed false reports on his candidacy, once again giving the media a dressing-down, as he is known to do."
	},
	{
		"src": "Republikanische Hochburgen wackeln",
		"tgt": "Republican strongholds are wavering"
	},
	{
		"src": "Utah ist normalerweise eine sichere Bank f\u00fcr die Republikaner.",
		"tgt": "Utah is normally a safe seat for the Republicans."
	},
	{
		"src": "Einer Umfrage von SurveyUSA aus dem Juni zufolge lagen Trump und seine Konkurrentin von den Demokraten, Hillary Clinton, gleichauf.",
		"tgt": "A poll carried out by SurveyUSA in June puts Trump and his competitor on an equal footing with Democrat Hillary Clinton."
	},
	{
		"src": "Andere Institute sehen Trump zwar vorn, allerdings nicht mit dem Abstand, der f\u00fcr republikanische Kandidaten in dem Bundesstaat \u00fcblich sind.",
		"tgt": "Other bodies do put Trump ahead, but not by the margin usual for Republican candidates in the state."
	},
	{
		"src": "Als gef\u00e4hrdet gelten auch Arizona und Georgia.",
		"tgt": "Arizona and Georgia are also at risk."
	},
	{
		"src": "In einem Interview des Senders CNBC antwortete Trump auf die Frage, wie er denn den Vormarsch Clintons wieder stoppen wolle: \"Genauso, wie ich es bisher gemacht habe\".",
		"tgt": "In an interview with broadcaster CNBC, Trump was asked how he would stop Clinton's rise, replying: \"In the same way I have done before\"."
	},
	{
		"src": "Und schob hinterher: Dies werde \"entweder erfolgreich sein, oder ich werde einen sehr sehr sch\u00f6nen, langen Urlaub machen\".",
		"tgt": "And he added: \"Either it'll work out, or I'll go on a long, long holiday\"."
	},
	{
		"src": "Er mache nichts Anderes, als \"die Wahrheit zu erz\u00e4hlen\".",
		"tgt": "He said he was just \"telling the truth\"."
	},
	{
		"src": "Falls es f\u00fcr ihn am Ende aus Gr\u00fcnden der politischen Korrektheit nicht reiche, sei das in Ordnung, sagte Trump weiter.",
		"tgt": "If he doesn't make it because of political correctness, that's ok, Trump added."
	},
	{
		"src": "Dann kehre ich zu einer sehr guten Lebensweise zur\u00fcck.",
		"tgt": "Then, he said, I'd return to a very nice way of life."
	},
	{
		"src": "Laut Presseberichten soll die Partei Trump gedroht haben, Gelder zur Unterst\u00fctzung seines Wahlkampfs zu streichen, sollte er keine besseren Umfragewerte pr\u00e4sentieren k\u00f6nnen.",
		"tgt": "According to press reports, the party have threatened Trump with removing financial support for his election campaign if he is unable to do any better in the polls."
	},
	{
		"src": "Anstatt dessen wolle man die Kandidaten der Republikaner f\u00fcr den Kongress st\u00e4rker unter die Arme greifen.",
		"tgt": "Instead, the Republican congressional candidates would be offered more support."
	},
	{
		"src": "Olympia: Dreister Betrug bei Doping-Test",
		"tgt": "Olympics: Brazen cheating in doping tests"
	},
	{
		"src": "Das IOC will eine Disziplinarkommission zu dem Fall einrichten.",
		"tgt": "The IOC intends to set up a disciplinary committee to handle the case."
	},
	{
		"src": "Kenias Leichtathleten droht nach der zweiten Doping-Aff\u00e4re bei den Olympischen Spielen in Rio de Janeiro Ungemach.",
		"tgt": "Following the second doping scandal at the Rio Olympics, trouble is looming for Kenya's track and field athletes."
	},
	{
		"src": "Nach einem Betrugsversuch bei einer Doping-Kontrolle im Olympischen Dorf hat Kenia einen Trainer nach Hause geschickt.",
		"tgt": "After an attempt to deceive a doping check in the Olympic village, Kenya has sent one coach home."
	},
	{
		"src": "Das Internationale Olympische Komitee teilte mit, umgehend eine Disziplinarkommission einzurichten, um den Fall zu untersuchen.",
		"tgt": "The International Olympic Committee announced that it would set up a disciplinary committee immediately to investigate the case."
	},
	{
		"src": "Ein kenianischer Funktion\u00e4r hatte mitgeteilt, dass der fr\u00fchere Sprinter und heutige Coach, John Anzrah, im Olympischen Dorf eine Urin-Probe unter dem Namen des 800-Meter-L\u00e4ufers Ferguson Rotich abgegeben habe.",
		"tgt": "A Kenyan official announced that former sprinter and current coach John Anzrah had given a urine sample in the Olympic village in the name of 800-metre runner Ferguson Rotich."
	},
	{
		"src": "Dies sei der Teamleitung Kenias von den Doping-Kontrolleuren berichtet worden.",
		"tgt": "Kenya's team managers were allegedly informed of this by the doping officials."
	},
	{
		"src": "Der Weltverband IAAF hat das IOC um Informationen \u00fcber den Fall ersucht, um eigene Untersuchungen anzustrengen, teilte ein IAAF-Sprecher mit.",
		"tgt": "The global IAAF federation has requested information about the matter from the IOC so it can carry out its own investigations, stated an IAAF spokesperson."
	},
	{
		"src": "\"Abh\u00e4ngig von den Ergebnissen der Untersuchung und die darauf folgenden Ma\u00dfnahmen des IOC wird die IAAF eine Bewertung vornehmen\", hie\u00df es in einer IAAF-Erkl\u00e4rung.",
		"tgt": "\"The IAAF will perform an evaluation, depending on the findings of the investigation and the steps taken by the IOC as a result,\" said an IAAF statement."
	},
	{
		"src": "\"Er (Anzrah) ist zur Doping-Kontrollstation gegangen und hat sich als Ferguson Rotich ausgegeben, die Probe abgegeben und unterschrieben\", erkl\u00e4rte Kenias Chef de Mission Stephan Arap Soi.",
		"tgt": "\"He (Anzrah) went to the doping check and alleged that he was Ferguson Rotich, handed in the sample, and signed for it,\" explained Stephan Arap Soi, Kenya's Chef de Mission."
	},
	{
		"src": "Er war im Besitz der Akkreditierung des Athleten, der auf der Liste f\u00fcr die Trainingskontrollen der Welt-Anti-Doping-Agentur stand.",
		"tgt": "He had the athlete's accreditation as given in the list of training checks for the World Anti-Doping Agency."
	},
	{
		"src": "Ferguson Rotich war 2015 in Peking WM-Vierter \u00fcber 800 Meter geworden.",
		"tgt": "Ferguson Rotich came fourth in the 800-metre race at the 2015 World Championships in Beijing."
	},
	{
		"src": "Vier Tage zuvor war der kenianische Leichtathletik-Delegationschef Michael Rotich von den Rio-Spielen abgezogen worden.",
		"tgt": "Four days previously, the Head of the Kenyan track & field delegation, Michael Rotich, had been sent away from the Rio games."
	},
	{
		"src": "Er soll gegen Geldzahlungen Sportler seines Landes \u00fcber anstehende Doping-Tests informiert haben.",
		"tgt": "He was alleged to have told sportspeople from his country about upcoming doping tests in exchange for money."
	},
	{
		"src": "Medienberichten zufolge soll er bei seiner R\u00fcckkehr am Flughafen von Nairobi festgenommen worden sein.",
		"tgt": "According to media reports, he was arrested on his return at Nairobi Airport."
	},
	{
		"src": "Kenia steht beim IOC nach zahlreichen Doping-Vergehen bereits seit l\u00e4ngerer Zeit unter besonderer Beobachtung.",
		"tgt": "After numerous instances of doping, the IOC has been keeping a particularly close eye on Kenya for a while."
	},
	{
		"src": "Bei der Ank\u00fcndigung der vom IOC aufgelegten mehr als 2000 Doping-Zielkontrollen vor den Rio-Spielen wurde ungew\u00f6hnlicherweise vorher darauf hingewiesen, dass besonders Athleten aus Kenia und Russland ins Visier genommen werden.",
		"tgt": "When the IOC announced that it would hold more than 2000 targeted doping checks in advance of the Rio games, it also announced, unusually, that athletes from Kenya and Russia would be examined particularly closely."
	},
	{
		"src": "Die Welt-Anti-Doping-Agentur hatte vor den Sommerspielen in Brasilien viel Druck auf das afrikanische Land ausge\u00fcbt, ein Anti-Doping-Gesetz und ein funktionierendes Kontrollsystem zu schaffen.",
		"tgt": "Ahead of the summer games in Brazil, the World Anti-Doping Agency had put a lot of pressure on the African country to introduce an anti-doping law and a functioning system of checks."
	},
	{
		"src": "Das Gesetz wurde wenige Wochen vor Olympia-Beginn verabschiedet.",
		"tgt": "The law was passed a few weeks before the start of the Olympics."
	},
	{
		"src": "In der Folge nahm die WADA Kenia von der Liste der L\u00e4ndern, deren Doping-Bek\u00e4mpfung konform mit den Regeln der WADA sind.",
		"tgt": "Following this, WADA removed Kenya from the list of countries whose anti-doping measures comply with WADA rules."
	},
	{
		"src": "Kenia gilt als gro\u00dfe L\u00e4ufer-Nation.",
		"tgt": "Running is a national sport in Kenya."
	},
	{
		"src": "Die Leichtathleten des Landes gewannen bei der WM 2015 in Peking die meisten Medaillen.",
		"tgt": "The country's track and field athletes won the most medals at the 2015 world championships in Beijing."
	},
	{
		"src": "In einer Reihe von Fernsehberichten der ARD wurden immer wieder Vorw\u00fcrfe erhoben, dass in Kenia Doping-Mittel leicht zug\u00e4nglich sind und es einen erhebliche Mentalit\u00e4t des Sportbetrugs geben soll.",
		"tgt": "In a series of televised reports by ARD, the claim was made time and again that doping drugs are easily accessible in Kenya and that there is a mentality of cheating at sport."
	},
	{
		"src": "IOC-Mitglied Richard Pound forderte zuletzt eine \u00e4hnliche Untersuchung in Kenia, wie er sie in der russischen Leichtathletik angestellt hatte.",
		"tgt": "IOC member Richard Pound has recently called for an investigation in Kenya to mirror that which took place into Russian athletics."
	},
	{
		"src": "Dabei konnte nachgewiesen werden, dass in dieser Sportart fl\u00e4chendeckend und systematisch gedopt wurde.",
		"tgt": "This investigation proved that doping was undertaken extensively and systematically across the sport."
	},
	{
		"src": "Russlands Leichtathleten wurden daraufhin von den Sommerspielen ausgeschlossen.",
		"tgt": "As a result, Russia's track and field athletes were banned from the summer games."
	},
	{
		"src": "Salzburger \"West Side Story\" mit Cecilia Bartoli",
		"tgt": "Salzburg's \"West Side Story\" with Cecilia Bartoli"
	},
	{
		"src": "Im Shakespeare-Jahr pr\u00e4sentieren die Salzburger Festspiele die \"West Side Story\" mit Tony und Maria als tragischem Liebespaar, \u00e4hnlich wie Romeo und Julia.",
		"tgt": "In the Shakespeare anniversary year, the Salzburger Festspiele is putting on \"West Side Story\" with Tony and Maria as tragic couple just like Romeo and Juliet."
	},
	{
		"src": "Mit dabei eine \u00fcberraschende Cecilia Bartoli.",
		"tgt": "Featuring a surprise: Cecilia Bartoli."
	},
	{
		"src": "Ein Musical erobert Salzburg: die \"West Side Story\", Leornard Bernsteins Meisterwerk.",
		"tgt": "A musical has gripped Salzburg: Leornard Bernstein's masterpiece, \"West Side Story\"."
	},
	{
		"src": "Die k\u00fcnstlerische Leiterin Cecilia Bartoli wollte das Musical in den Tempel der Klassik bringen und erf\u00fcllte sich mit der Rolle der Maria einen Jugendtraum.",
		"tgt": "Artistic Director Cecilia Bartoli wanted to bring the musical into the temple of classical music, and has made a childhood dream come true by taking on the role of Maria."
	},
	{
		"src": "Im Orchestergraben das Sim\u00f3n Bol\u00edvar Orchester unter Leitung des venezonalischen Dirigenten Gustavo Dudamel: \"Diese Musik ist voller Rhythmus\", schw\u00e4rmt er.",
		"tgt": "In the orchestra pit, the Sim\u00f3n Bol\u00edvar Orchestra will be conducted by Venezuelan director Gustavo Dudamel: \"This music is full of rhythm,\" he enthuses."
	},
	{
		"src": "Wir sagen immer, dass sie sehr lateinamerikanisch gepr\u00e4gt ist.",
		"tgt": "We always say that it has a lot of Latin American influences."
	},
	{
		"src": "Es gibt viele lateinamerikanische Zutaten in ihrem Tempo und ihrer Melodie.",
		"tgt": "There are many Latin American elements in its tempo and melodies."
	},
	{
		"src": "Es ist eine wunderbare Mischung, das perfekte Rezept f\u00fcr unser Orchester.",
		"tgt": "It is a wonderful mixture, the perfect formula for our orchestra."
	},
	{
		"src": "Ich w\u00fcrde sagen, dass wir Bernsteins Musik wirklich in unserem Blut haben!",
		"tgt": "I would say that we really have Bernstein's music in our blood!"
	},
	{
		"src": "In dieser Inszenierung spielt Bartoli eine \u00e4lter gewordene Maria.",
		"tgt": "In this production, Bartoli plays an older Maria."
	},
	{
		"src": "Sie erinnert sich mit Wehmut an ihre Liebschaft mit Tony, w\u00e4hrend die j\u00fcngere Maria spielt und tanzt.",
		"tgt": "She remembers her love affair with Tony with wistfulness, while the younger Maria plays and dances."
	},
	{
		"src": "Die Rolle der Maria hat mich immer fasziniert.",
		"tgt": "The role of Maria has always fascinated me."
	},
	{
		"src": "Erstens weil sie musikalisch au\u00dfergew\u00f6hnlich ist!",
		"tgt": "Firstly because it's musically unusual!"
	},
	{
		"src": "Und dann w\u00e4re da noch Marias Pers\u00f6nlichkeit.",
		"tgt": "And then there's Maria's personality."
	},
	{
		"src": "Sie sagt es in ihrem Lied: \"I feel pretty, oh so pretty, I feel pretty and witty and bright\".",
		"tgt": "As she says in her song: \"I feel pretty, oh so pretty, I feel pretty and witty and bright\"."
	},
	{
		"src": "Sie ist also klug, nat\u00fcrlich auch naiv, und sehr leidenschaftlich.",
		"tgt": "So she's clever, and naive of course, and full of passion."
	},
	{
		"src": "\"Sie \u00e4hnelt mir sehr, meinem italienischen Charakter, den ich als R\u00f6merin habe\", lacht Bartoli.",
		"tgt": "\"She's very like me, like my Italian personality as a girl from Rome,\" laughs Bartoli."
	},
	{
		"src": "Dudamel ist voll des Lobes f\u00fcr die Operns\u00e4ngerin: \"Cecilia ist eine wunderbare K\u00fcnstlerin.\"",
		"tgt": "Dudamel is full of praise for the opera singer: \"Cecilia is a wonderful artist.\""
	},
	{
		"src": "Es ist so eine Ehre f\u00fcr uns mit ihr zu arbeiten.",
		"tgt": "We are so honoured to work with her."
	},
	{
		"src": "Sie ist ein ungeheuer gro\u00dfz\u00fcgiger Mensch.",
		"tgt": "She is an incredibly generous person."
	},
	{
		"src": "Und Bartoli gibt das Kompliment zur\u00fcck: \"Dudamel ist so ein au\u00dfergew\u00f6hnlicher K\u00fcnstler und sehr leidenschaftlich!\"",
		"tgt": "And Bartoli returns the compliment: \"Dudamel is such an exceptional artist and so passionate!\""
	},
	{
		"src": "Dirigieren ist f\u00fcr ihn eine Notwendigkeit.",
		"tgt": "For him, conducting is a need."
	},
	{
		"src": "Man sieht es in jeder seiner Bewegungen, in seinen Blicken, es ist sein Leben!",
		"tgt": "You see it in all his movements, his glances - it is his life!"
	},
	{
		"src": "Es ist so eine riesige Chance diese musikalische Erfahrung mit ihm teilen zu k\u00f6nnen.",
		"tgt": "It is such a great chance to be able to share this musical experience with him."
	},
	{
		"src": "Wir haben beide ein eher s\u00fcdliches Temperament, ein Feuer, eine Leidenschaft und auch eine fr\u00f6hliche Herangehensweise an das Leben, das ist \u00fcberhaupt sehr wichtig!",
		"tgt": "We both have a rather southern temperament, fire, passion, and we both approach life with joy, which is the most important of all!"
	},
	{
		"src": "F\u00fcr den amerikanischen Regisseur Philip Wm. McKinley ist die \"West Side Story\" hochaktuell: \"In diesem St\u00fcck geht es um Vorurteile und Fanatismus.\"",
		"tgt": "For the American director Philip Wm. McKinley, \"West Side Story\" is bang up-to-date: \"This work is all about prejudice and fanaticism.\""
	},
	{
		"src": "Heute haben wir die Fl\u00fcchtlinge, damals sind die Puertorikaner nach New York gegangen, und die New Yorker Einwohner wollten sie nicht.",
		"tgt": "Today we're dealing with the refugees, back then Puerto Ricans had gone to New York, and the residents of New York didn't want them there."
	},
	{
		"src": "Es sind die gleichen Themen, und sie sind heute genauso aussagekr\u00e4ftig wie damals.",
		"tgt": "It's the same issues, and they were as significant then as they are today."
	},
	{
		"src": "59 Jahre sp\u00e4ter ist das St\u00fcck immer noch relevant.",
		"tgt": "Fifty-nine years on, the work is still relevant."
	},
	{
		"src": "Londoner Schulm\u00e4dchen, das sich dem IS anschloss, wurde in Syrien get\u00f6tet",
		"tgt": "London schoolgirl who joined ISIL killed in Syria"
	},
	{
		"src": "Kadiza Sultana, eines von drei britischen Schulm\u00e4dchen, die letztes Jahr London verlie\u00dfen, um sich dem IS anzuschlie\u00dfen, starb Berichten zufolge in Syrien.",
		"tgt": "Kadiza Sultana, one of three British schoolgirls who left London last year to join ISIL, has reportedly died in Syria."
	},
	{
		"src": "Der Anwalt Tasnime Akunjee sagte, dass ihre Familie vor einigen Wochen von ihrem Tod in Raqqa, Syrien erfuhr.",
		"tgt": "Attorney Tasnime Akunjee said her family learned of her death in Raqqa, Syria, a few weeks ago."
	},
	{
		"src": "Es wurde vermutet, dass sie durch einen russischen Luftangriff in Raqqa get\u00f6tet wurde, dem Bollwerk der Gruppe im Land, berichtete ITV News am Donnerstag.",
		"tgt": "She was believed to have been killed by a Russian air strike in Raqqa, the group's stronghold in the country, ITV News reported on Thursday."
	},
	{
		"src": "Sultana war 17 Jahre alt und starb nach Angaben ihrer Familie kurz nachdem sie vorhatte, das kriegsgebeutelte Land zu verlassen und nach England zur\u00fcckzukehren.",
		"tgt": "Sultana was 17 years old and, according to her family, died just as she was making plans to flee the war-torn country and return to Britain."
	},
	{
		"src": "\"Man kann nur hoffen, dass das einzige Gute darin liegt - als Mahnung und Warnung an andere, dass dies die Risiken sind, die damit verbunden sind, in ein Kriegsgebiet zu gehen - Leute davon abzuhalten, jemals diese Entscheidung zu treffen,\" sagte Akunjee.",
		"tgt": "\"One would hope that the only benefit out of this is - as a tombstone and testament to others, that these are the risks actually involved in going to a war zone - to dissuade people from ever making that choice really,\" Akunjee said."
	},
	{
		"src": "Im Februar 2015 stiegen Sultana und zwei andere Schulm\u00e4dchen aus dem Osten Londons in ein Flugzeug Richtung T\u00fcrkei und anschlie\u00dfend in einen Bus an die syrische Grenze ein.",
		"tgt": "In February 2015, Sultana and two other schoolgirls from east London boarded a flight to Turkey and then a bus to the Syrian border."
	},
	{
		"src": "Sultanas Familie wurde mitgeteilt, dass sie einen ISIS-K\u00e4mpfer in Syrien geheiratet hat - und innerhalb weniger Monate zur Witwe wurde.",
		"tgt": "Sultana's family was told she married an ISIL fighter in Syria - and became a widow within months."
	},
	{
		"src": "Reid sagt, Clinton werde im Fall eines Wahlsiegs bei Garland als Kandidaten f\u00fcr das Oberste Gericht bleiben",
		"tgt": "Reid says Clinton will stick with Garland as Supreme Court nominee if elected"
	},
	{
		"src": "Harry Reid, Anf\u00fchrer der Demokraten im Senat, ist \u00fcberzeugt, dass die Pr\u00e4sidentschaftskandidatin der Demokraten, Hillary Clinton den Richter Merrick Garland f\u00fcr das Oberste Gericht nominieren wird.",
		"tgt": "Senate Democratic Leader Harry Reid says he is convinced that Democratic presidential candidate Hillary Clinton will nominate Judge Merrick Garland to the Supreme Court if she is elected president."
	},
	{
		"src": "Die Republikaner im Senat haben Garlands Best\u00e4tigung seit seiner Nominierung durch Barack Obama im M\u00e4rz blockiert.",
		"tgt": "Senate Republicans have blocked Garland's confirmation since President Barack Obama nominated him in March."
	},
	{
		"src": "Der Mehrheitsf\u00fchrer im Senat Mitch McConnell ist der Meinung, dass der n\u00e4chste Pr\u00e4sident den Nachfolger des verstorbenen Richter am Obersten Gericht Antonin Scalia ernennen wird.",
		"tgt": "Senate Majority Leader Mitch McConnell says the next president will choose the person to replace late Supreme Court Justice Antonin Scalia."
	},
	{
		"src": "Reid sagte am Donnerstag w\u00e4hrend einer Telefonkonferenz, dass er von Clinton erwartet Garland \"mit einer gewissen Ma\u00df an Gewissheit\" auszuw\u00e4hlen.",
		"tgt": "Reid said on a conference call Thursday that he is predicting Clinton will pick Garland \"with some degree of credibility.\""
	},
	{
		"src": "Eine Sprecherin von Reid sagte sp\u00e4ter, dass er noch nicht mit Clinton gesprochen h\u00e4tte ob sie Garland nominieren w\u00fcrde und er spekuliere.",
		"tgt": "A spokeswoman for Reid later said he had not spoken to Clinton directly about whether she would nominate Garland and was speculating."
	},
	{
		"src": "Er lobte Garland und sagte, Clintons Team w\u00fcrde nicht f\u00fcr Unruhe mit einem neuen Kandidaten sorgen.",
		"tgt": "He praised Garland and said Clinton's team would not want to \"rock the boat\" with a new pick."
	},
	{
		"src": "Garland ist der oberste Richter f\u00fcr das US Appellationsgericht f\u00fcr den District of Columbia.",
		"tgt": "Garland is the chief judge for the U.S. Court of Appeals for the District of Columbia Circuit."
	},
	{
		"src": "Raid sagte, Republikaner die Garlands Nominierung blockierten, seien Lakaien und Helfershelfer des republikanischen Pr\u00e4sidentschaftskandidaten Donald Trump.",
		"tgt": "Reid said Republicans who are blocking Garland's nomination are \"minions\" and \"enablers\" of Republican presidential candidate Donald Trump."
	},
	{
		"src": "Er stellte auch fest, Donald Trump sei ungeeignet f\u00fcr das Pr\u00e4sidentenamt.",
		"tgt": "He said Trump is unfit for office."
	},
	{
		"src": "Treats will Nacktkalendar f\u00fcr \"Frauen und f\u00fcr M\u00e4nner\"",
		"tgt": "Treats says nude calendar for 'women, as well as men'"
	},
	{
		"src": "Das Treats Magazin arbeitet mit dem Fotografen David Bellemere zusammen, um einen 1970er Jahre Pirelli-inspirierten Kalendar f\u00fcr 2017 herauszubringen.",
		"tgt": "Treats magazine is partnering with photographer David Bellemere to launch a 1970s' Pirelli-inspired calendar for 2017."
	},
	{
		"src": "Aber anstelle ber\u00fchmter nackter Menschen m\u00f6chten sie f\u00fcr ihren NU Muses Kalendar f\u00fcr 2017 die n\u00e4chste Generation von Topmodels finden.",
		"tgt": "But instead of famous naked people, they're setting out to find the next generation of top models for their 2017 NU Muses calendar."
	},
	{
		"src": "Der Chefredakteur von Treats Steve Shaw erz\u00e4hlte uns Anfang diesen Jahres, dass sich sein Nacktmagazin von Oldschool-Playboys unterscheide, da \"Playboy f\u00fcr M\u00e4nner sei\".",
		"tgt": "Treats president Steve Shaw told us earlier this year that his nude-heavy magazine differs from old-school Playboys because \"Playboy is for men.\""
	},
	{
		"src": "Ich mache das f\u00fcr Frauen.",
		"tgt": "I do this for women."
	},
	{
		"src": "Anscheinend ist er der Ansicht, dass es der Kalendar auch tut.",
		"tgt": "Apparently he thinks the calendar is, too."
	},
	{
		"src": "\"Wir m\u00fcssen wieder zur Darstellung zeitloser und klassischer Nackheit zur\u00fcckkehren, bei der sich sowohl Frauen als auch M\u00e4nner wohl f\u00fchlen und sich von diesen Bildern eines weiblichen K\u00f6rpers inspiriert f\u00fchlen,\" sagte Shaw in einer Pressemitteilung zur Ver\u00f6ffentlichung des Kalendars.",
		"tgt": "\"We need to get back to showcasing timeless and classic nudity where women, as well as men, feel comfortable and inspired by these images of the female body,\" Shaw said in a press release announcing the calendar."
	},
	{
		"src": "Frauen werden an diesem Projekt teilnehmen wollen, weil es ein wundersch\u00f6nes Kunstwerk ist.",
		"tgt": "Women will want to be a part of this project because it's a beautiful piece of art."
	},
	{
		"src": "Models k\u00f6nnen ihre Bilder online oder pers\u00f6nlich bei offenen Casting-Aufruf in Los Angeles und New York einreichen.",
		"tgt": "Models can submit pics online or in person at open casting calls in Los Angeles and New York."
	},
	{
		"src": "T\u00fcrkei: Kurdische Gemeinde rechnet mit Massenflucht",
		"tgt": "Turkey: Kurdish community faces mass exodus"
	},
	{
		"src": "\"Wer sich nicht anpasst und Erdogan lobt, sitzt auf gepackten Koffern\", sagt der Vorsitzend der G\u00fclen-nahen Stiftung Dialog und Welt, Ercan Karakoyun.",
		"tgt": "\"If you don't change your tune and praise Erdogan, your suitcase is basically packed,\" says the President of the G\u00fclen-supporting Dialogue and World foundation, Ercan Karakoyun."
	},
	{
		"src": "Die Kurdische Gemeinde Deutschland rechnet kurzfristig mit zehntausenden Schutzsuchenden, die aus der T\u00fcrkei nach Deutschland fl\u00fcchten.",
		"tgt": "The Kurdish community in Germany is expecting tens of thousands of people to arrive at short notice in search of protection, fleeing from Turkey to Germany."
	},
	{
		"src": "Mittelfristig k\u00f6nnten es sogar \"einige hunderttausend\" werden, glaubt der Verbandsvorsitzende Ali Toprak.",
		"tgt": "In the medium term, this could even grow to \"a few hundred thousand\", believes Ali Toprak, President of the association."
	},
	{
		"src": "Wegen des harten Vorgehens des t\u00fcrkischen Pr\u00e4sidenten Recep Tayyip Erdogan nach dem Putschversuch erwartet die Kurdische Gemeinde Deutschland eine Massenflucht nach Deutschland.",
		"tgt": "The crackdown instigated by Turkish President Recep Tayyip Erdogan after the attempted coup has led the Germany Kurdish Association to expect a mass exodus to Germany."
	},
	{
		"src": "\"Kurzfristig rechne ich mit zehntausenden, mittelfristig mit einigen hunderttausend Schutzsuchenden aus der T\u00fcrkei in Deutschland, wenn das Erdogan-Regime die Minderheiten und die demokratische Opposition weiter bek\u00e4mpft\", sagt der Verbandsvorsitzende Ali Toprak der \"Welt\" vom Freitag.",
		"tgt": "\"In the short term I'm expecting ten thousand, in the medium term a few hundred thousand people coming from Turkey looking for protection in Germany, if the Erdogan regime continues to antagonise minorities and democratic opposition,\" said the President of the Association, Ali Toprak, to \"Die Welt\" newspaper on Friday."
	},
	{
		"src": "Weil die Regierung bereits vor Monaten kurdische Hochburgen mit Strafaktionen \u00fcberzogen habe, seien 500.000 Kurden innerhalb der T\u00fcrkei auf der Flucht.",
		"tgt": "A few months ago the government initiated punitive action against Kurdish strongholds - and as a result, 500,000 Kurds are already on the run within Turkey."
	},
	{
		"src": "Nach dem vereitelten Putsch k\u00e4men noch s\u00e4kulare und oppositionelle ethnische T\u00fcrken hinzu.",
		"tgt": "After the unsuccessful coup, secular and oppositional ethnic Turks have been added to the list."
	},
	{
		"src": "Viele werden in Europa neu anfangen wollen, wenn sie in der T\u00fcrkei weiter unterdr\u00fcckt werden.",
		"tgt": "Many will want to seek a new start in Europe if they continue to suffer oppression in Turkey."
	},
	{
		"src": "\"Es kann nicht sein, dass ein Staat, der selbst Fl\u00fcchtlinge aufnimmt, im eigenen Land Fl\u00fcchtlinge produziert\", sagte Toprak.",
		"tgt": "\"It is unacceptable that a country that takes in refugees is also producing them,\" said Toprak."
	},
	{
		"src": "Der Verbandschef beklagte die gezielte Ansiedlung syrischer Araber in kurdischen, aber auch in alevitischen St\u00e4dten.",
		"tgt": "The head of the Association complained about the deliberate relocating of Syrian Arabs in Kurdish and Alevi towns."
	},
	{
		"src": "Damit wolle Erdogan den Ausreisedruck auf die verbliebenen Kurden erh\u00f6hen.",
		"tgt": "He thinks that Erdogan did this to encourage the remaining Kurds to leave."
	},
	{
		"src": "\"Sie sind die letzte gro\u00dfe Minderheit in der T\u00fcrkei, die christlichen Armenier und Griechen wurden ja schon in den vergangenen hundert Jahren ausgerottet oder vertrieben\", sagte Toprak, der auch CDU-Mitglied ist.",
		"tgt": "\"They are the last big minority in Turkey: the Christian Armenians and the Greeks have already been exterminated or driven out over the past hundred years,\" said Toprak, who is also a member of the CDU."
	},
	{
		"src": "Der Verbandschef forderte, dass die Bundesregierung sich \"so scharf wie \u00d6sterreich gegen Erdogan und seine Anh\u00e4nger positioniert\".",
		"tgt": "The head of the Association requested that the Federal Government acted \"as harshly as Austria against Erdogan and his supporters\"."
	},
	{
		"src": "Auch in Deutschland finde eine \"Hexenjagd\" gegen Erdogan-Kritiker statt.",
		"tgt": "A \"witch-hunt\" is also underway in Germany against those critical of Erdogan."
	},
	{
		"src": "Ich f\u00fchle mich in den letzten Monaten zum ersten Mal nicht mehr sicher in Deutschland.",
		"tgt": "Over the past few months, I have no longer felt safe in Germany for the first time."
	},
	{
		"src": "Der deutsche Zweig der G\u00fclen-Bewegung bef\u00fcrchtet ebenfalls die Flucht vieler T\u00fcrken ins Ausland.",
		"tgt": "The German branch of the G\u00fclen movement also fears that many Turks will flee abroad."
	},
	{
		"src": "Mehr T\u00fcrken werden Asyl in Deutschland suchen, vor allem Kurden und Oppositionelle.",
		"tgt": "More Turks will seek asylum in Germany, especially Kurds and members of the opposition."
	},
	{
		"src": "Die Brandmarkung als G\u00fclen-Anh\u00e4nger vernichtet Lehrern und anderen Akademikern die berufliche Existenz.",
		"tgt": "Being singled out as a G\u00fclen-supporter is career-destroying for teachers and other academics."
	},
	{
		"src": "\"Wer sich nicht anpasst und Erdogan lobt, sitzt auf gepackten Koffern, \u00fcbrigens auch die Kemalisten und S\u00e4kularen\", sagte Ercan Karakoyun, Vorsitzender der G\u00fclen-nahen Stiftung Dialog und Bildung, der \"Welt\".",
		"tgt": "\"If you don't change your tune and praise Erdogan, your suitcase is basically packed,\" said the President of the G\u00fclen-supporting Dialogue and World Foundation, Ercan Karakoyun, to \"Die Welt\" newspaper."
	},
	{
		"src": "Wie die Zeitung unter Berufung auf Zahlen des Bundesinnenministeriums berichtet, stellten die T\u00fcrken schon vor dem Putsch die gr\u00f6\u00dfte Gruppe der wegen politischer Verfolgung anerkannten Asylberechtigten in Deutschland.",
		"tgt": "As the newspaper reports, using figures from the Federal Ministry of the Interior, even before the coup Turks were the largest group granted asylum in Germany on the grounds of political persecution."
	},
	{
		"src": "Zum Stichtag 30. Juni seien dies 11.386 Menschen und damit knapp 29 Prozent aller als asylberechtigt Anerkannten (39.625) gewesen.",
		"tgt": "On the reference date of June 30, this amounted to 11,386 people, almost 29 percent of all people entitled to asylum (39,625)."
	},
	{
		"src": "In dieser Erhebung finden sich nicht die vor Krieg, Armut oder Perspektivlosigkeit Geflohenen.",
		"tgt": "These figures do not include people who have fled war, poverty or a lack of prospects."
	},
	{
		"src": "Asylberechtigt nach dem Grundgesetz sind ausschlie\u00dflich politisch, also von staatlicher Seite, individuell Verfolgte.",
		"tgt": "Under the constitution, only individuals suffering political persecution, i.e., on the part of the state, are entitled to asylum."
	},
	{
		"src": "Mecklenburg-Vorpommern: \"Dahin gehen, wo es wehtut\"",
		"tgt": "Mecklenburg-Vorpommern: \"Go where it hurts\""
	},
	{
		"src": "Seltsames Mecklenburg-Vorpommern: Die Einheimischen bekommen nichts vom Sommer-Wahlkampf mit - und die Urlauber aus Nordrhein-Westfalen d\u00fcrfen nicht den Landtag w\u00e4hlen.",
		"tgt": "Strange Mecklenburg-Vorpommern: Locals hear nothing about the summer elections - and holidaymakers from North Rhine-Westphalia are not allowed to vote for the state parliament."
	},
	{
		"src": "In Mecklenburg-Vorpommern haben sie verstanden.",
		"tgt": "In Mecklenburg-Vorpommern, they understood this."
	},
	{
		"src": "2021 wird die Landtagswahl nicht wieder direkt am Ende der Sommerferien stattfinden, hat das Schweriner Parlament bereits Anfang des Jahres beschlossen.",
		"tgt": "In 2021 the state parliament elections will not take place at the end of the summer holidays, the Schwerin parliament decided at the start of the year."
	},
	{
		"src": "Denn bl\u00f6der als bislang geht es nicht: Sommerferien, Hitze und Landtagswahlkampf - das bei\u00dft sich.",
		"tgt": "The way things had been going was simply ridiculous: summer holidays, heat and state parliament elections - they clash with one another."
	},
	{
		"src": "Die Einheimischen, die von den Wahlk\u00e4mpfern \u00fcberzeugt werden sollen, sind im Urlaub.",
		"tgt": "The locals who need to be won over by the candidates are on holiday."
	},
	{
		"src": "Die allermeisten Urlauber, die im Land sind, auf Usedom, R\u00fcgen oder Hiddensee unterwegs, sind keine Einheimischen, d\u00fcrfen also nicht den Landtag w\u00e4hlen.",
		"tgt": "Most holidaymakers in the state, in Usedom, R\u00fcgen or Hiddensee, are not locals - and are not allowed to vote for the state parliament."
	},
	{
		"src": "Dazu kommen praktische Probleme: In den Ferien sind Helfer, die Plakate aufh\u00e4ngen, Luftballons aufblasen, Flyer verteilen und am Ende Stimmen ausz\u00e4hlen, nur m\u00fchevoll aufzutreiben.",
		"tgt": "There are also practical problems to consider: during the holidays, volunteers who put up signs, blow up balloons, distribute flyers and count the votes at the end, are hard to find."
	},
	{
		"src": "Bis zum 4. September 2016, dem Wahl- und letzten Ferientag, muss Mecklenburg-Vorpommern einmal noch Wahlkampf knapp am Volk vorbei \u00fcber sich ergehen lassen.",
		"tgt": "Until 4 September 2016, election day and the last day of the holidays, people in Mecklenburg-Vorpommern must put up with one more election without the people being consulted."
	},
	{
		"src": "Die hei\u00dfe Phase, wenn man das \u00fcberhaupt sagen kann, hat gerade begonnen.",
		"tgt": "The heated phase, if that can be said at all, has already begun."
	},
	{
		"src": "Und es geht auch um etwas: Ministerpr\u00e4sident Erwin Sellering, Anf\u00fchrer einer SPD/CDU-Koalition, muss um sein Amt f\u00fcrchten.",
		"tgt": "And there's something at stake: Prime Minister Erwin Sellering, leader of an SPD/CDU coalition, is fearing for his seat."
	},
	{
		"src": "Die SPD, seit 1998 st\u00e4rkste Partei, liegt nun in Umfragen klar hinter der CDU.",
		"tgt": "The SPD, the strongest party since 1998, is now clearly behind the CDU, according to polls."
	},
	{
		"src": "Spannend wird, wie stark Neuling AfD abschneidet und was am Ende Koalitionstaugliches \u00fcbrig bleibt.",
		"tgt": "It will be exciting to see how Neuling AfD carves things up, and whether a coalition can be formed with what's left at the end."
	},
	{
		"src": "Sellering, 66 Jahre alt und seit 2008 Regierungschef, macht einen fast unauff\u00e4llig wirkenden Wahlkampf, sieht man von seinen Gro\u00dfplakaten ab.",
		"tgt": "Sellering, 66 years old and head of the parliament since 2008, pursued a rather inconspicuous election campaign, as can be seen from his posters."
	},
	{
		"src": "Er reist durchs Land, verteilt Rosen und plauscht ein wenig mit den Leuten, so wie es auch schon sein legend\u00e4r wortkarger Vorg\u00e4nger Harald Ringstorff tat.",
		"tgt": "He is travelling around the region, distributing roses and chatting a bit with people, just as his legendarily taciturn predecessor Harald Ringstorff did."
	},
	{
		"src": "Ansonsten hat Seelering kalte F\u00fc\u00dfe bekommen und gibt Kanzlerin Merkel die Schuld am Erbl\u00fchen der AfD.",
		"tgt": "Apart from that, Seelering has got cold feet, blaming Chancellor Merkel for the rise of the AfD."
	},
	{
		"src": "Ihre Fl\u00fcchtlingspolitik, ihr \"Wir schaffen das\" habe den Aufstieg der Rechtspopulisten beschleunigt, was ihn jetzt vermutlich das sch\u00f6ne Amt kosten wird.",
		"tgt": "Her refugee policies, her \"we can manage it\" have accelerated the rise of the far-right, he believes - which will probably cost him his job."
	},
	{
		"src": "Die CDU mit ihrem Spitzenkandidaten, dem Innenminister Lorenz Caffier, hat schon erlebt, wie es ist, wenn man zur falschen Zeit am richtigen Ort Wahlkampf macht.",
		"tgt": "The CDU and its top-level candidate, Minister of the Interior Lorenz Caffier, has already experienced what happens when you fight an election in the right place at the wrong time."
	},
	{
		"src": "Sie hat zweimal Kanzlerin Angela Merkel zu Gro\u00dfkundgebungen eingeladen; Merkel Bundestagswahlkreis liegt im Nordosten.",
		"tgt": "The CDU have invited Chancellor Angela Merkel to two mass rallies; Merkel's parliamentary constituency is in the north-east."
	},
	{
		"src": "Aber die Zielgruppe stimmte nicht, es waren mehr Nordrhein-Westfalen, Berliner und Sachsen da als Mecklenburger und Vorpommern.",
		"tgt": "But the target group wasn't right: there were more people from North Rhine-Westphalia, Berlin and Saxony there than people from Mecklenburg-Vorpommern."
	},
	{
		"src": "\"Da war wahrscheinlich die Mehrheit aus anderen Bundesl\u00e4ndern\", klagte Vincent Kokert, Generalsekret\u00e4r der CDU in Mecklenburg-Vorpommern, k\u00fcrzlich im NDR.",
		"tgt": "\"The majority probably came from other federal states,\" Vincent Kokert, general secretary of the CDU in Mecklenburg-Vorpommern, complained to the NDR recently."
	},
	{
		"src": "Aber es schade auch niemandem aus anderen Ecken Deutschlands, einmal Angela Merkel zuzuh\u00f6ren.",
		"tgt": "But it won't do any harm to anyone from other parts of Germany to listen to Angela Merkal for once."
	},
	{
		"src": "Ansonsten verzichtet die Nordost-CDU weitgehend auf die \u00fcblichen Wahlkampfst\u00e4nde auf Marktpl\u00e4tzen und vor Einkaufszentren mit Sonnenschirmen und Luftballons.",
		"tgt": "Apart from that, the north-east CDU is generally dispensing with the normal election events with parasols and balloons in market squares and outside shopping centres."
	},
	{
		"src": "Das, so meint Kokert, spiele nur noch eine \"untergeordnete Rolle\".",
		"tgt": "According to Kokert, that will only play a \"minor role\"."
	},
	{
		"src": "Auch die Union hat gemerkt, dass ihr auf dem Land die Basis wegbr\u00f6selt, dass sie sich sehr anstrengen muss, wieder einen Draht zu den Leuten zu finden.",
		"tgt": "The Union also noticed that they are losing their footing in the region, and will have to work hard to connect with the people."
	},
	{
		"src": "Ihr geht es wie der Linken, der SPD, den Gr\u00fcnen: in den Weiten des Landes kaum vorhanden.",
		"tgt": "They are suffering like the Left, the SPD, the Greens: hardly present across large swathes of the region."
	},
	{
		"src": "Der Rat des CDU-Wahlk\u00e4mpfers Kokert an seine Mitstreiter ist allerdings auch selbstentlarvend: \"Sie m\u00fcssen dahin gehen, wo es wehtut, n\u00e4mlich wo die Menschen sind: Dorffeste, Goldene Hochzeiten, jede Geburtstagsfeier muss genutzt werden\".",
		"tgt": "The advice that CDU candidate Kokert gave to his competitors is revealing: \"You have got to go where it hurts, or where the people are: village fetes, Golden Wedding anniversaries, you have to make use of every birthday party.\""
	},
	{
		"src": "Weil viel auf dem Spiel steht, hat Sellering seine SPD nun zu einem besonders engagierten Wahlkampf aufgerufen.",
		"tgt": "Sellering has already called his SPD to fight a particularly committed election campaign because there is so much at stake."
	},
	{
		"src": "In Umfragen lagen die Sozialdemokraten zuletzt mit 22 Prozent hinter Partner CDU (25) und nur knapp vor der AfD (19).",
		"tgt": "According to polls, the social democrats have 22 percent, behind their partners the CDU (25), and only fractionally ahead of the AfD (19)."
	},
	{
		"src": "Bei der Wahl 2011 hatte die SPD noch klar mit 35,6 Prozent vor der CDU (22) gewonnen.",
		"tgt": "In the 2011 elections, the SPD had a clear victory over the CDU (35.6 percent versus 22 percent)."
	},
	{
		"src": "Die Gr\u00fcnen, Kleinpartei mit sieben Prozent in den Umfragen, d\u00fcrften den Sprung in den Landtag schaffen.",
		"tgt": "The Greens, a small party with seven percent in the polls, should make the leap into the regional parliament."
	},
	{
		"src": "Sie machen aus der Ferien-Not eine moderne Tugend und verlegen ihren Wahlkampf gro\u00dfenteils ins Internet.",
		"tgt": "They are making a modern virtue out of the holiday issue, and are waging their election war predominantly online."
	},
	{
		"src": "\"Online-Wahlkampf\", nennt es die Landesvorsitzende Claudia M\u00fcller.",
		"tgt": "\"Online election campaign\" is what the regional chairperson Claudia M\u00fcller has dubbed it."
	},
	{
		"src": "Ansonsten begeben sich gr\u00fcne Wahlk\u00e4mpfer auf Spurensuche nach einheimischen Stimmb\u00fcrgern unter den Urlaubern.",
		"tgt": "Apart from that, the Greens are searching out local voters among the holidaymakers."
	},
	{
		"src": "Silke Gajek, die Spitzenkandidatin, kurvt gerade mit einem Hausboot durch die mecklenburgischen Seen und findet es auch noch sch\u00f6n.",
		"tgt": "Silke Gajek, their top candidate, is currently crossing Mecklenburg's lakes on a houseboat - and is having a nice time."
	},
	{
		"src": "Ihr Eindruck: \"Wahlurlaub in Mecklenburg-Vorpommern ist keine Strafe\".",
		"tgt": "Her view? \"Having an election holiday in Mecklenburg-Vorpommern isn't all that bad\"."
	},
	{
		"src": "B27-Sanierung: Gastst\u00e4tten leiden unter Sperrung",
		"tgt": "B27 redevelopment: restaurants are suffering from the closure"
	},
	{
		"src": "An der Schnelligkeit, mit der die B 27 saniert wird, gibt es nichts zu meckern.",
		"tgt": "There are hardly any problems with the speed at which the B27 is being redeveloped."
	},
	{
		"src": "F\u00fcr die Verantwortlichen der Bauarbeiten, die um 5.30 Uhr morgens beginnen und erst gegen 20 Uhr enden, gibt es allenthalben Lob.",
		"tgt": "There is praise from all quarters for the people responsible for the construction works, which start at 5.30 a.m. and end at 8 p.m."
	},
	{
		"src": "\"Die haben alles ziemlich zackig gemacht\", erz\u00e4hlt Elvira Tetzlaff von der Jet-Tankstelle.",
		"tgt": "\"They have done everything so speedily,\" Elvira Texlaff at the Jet petrol station explains."
	},
	{
		"src": "Das ist ein Superteam.",
		"tgt": "That is a super team."
	},
	{
		"src": "Es gibt auch keinen Verzug.",
		"tgt": "There are also no delays."
	},
	{
		"src": "Die Baustelle konnte am Wochenanfang zur Halbzeit planm\u00e4\u00dfig nach S\u00fcden verlegt werden, bis Ende Oktober soll alles fertig sein.",
		"tgt": "At the start of the week, the construction site could be moved southwards in line with plans, marking the half-way point, and everything is expected to be completed by October."
	},
	{
		"src": "Gelobt wird auch das Entgegenkommen der f\u00fcr die Bauarbeiten Verantwortlichen, etwa wenn es um die Einrichtung von Behelfseinfahrten geht.",
		"tgt": "The obligingness of the people responsible for the construction works in terms of setting up substitute driveways."
	},
	{
		"src": "Seit die Baustelle am Montag nach S\u00fcden gewandert ist und auch die Sperrung der Aspergstra\u00dfe in Ofterdingen aufgehoben wurde und damit auch die Verbindung nach Rottenburg wieder besteht, hat sich die Verkehrslage innerhalb des Ortes entspannt.",
		"tgt": "Since the construction site was moved southwards on Monday, and the Aspegstra\u00dfe in Ofterdingen was reopened, and the link to Rottenburg was re-established, the traffic situation within the town has improved."
	},
	{
		"src": "Die B\u00fcrger k\u00f6nnen nun von Ofterdingen aus die B 27 wieder beidseitig befahren.",
		"tgt": "Residents can now drive on both sides of the B 27 out of Ofterdingen."
	},
	{
		"src": "Der Ausweichverkehr durch den Ort scheint zur\u00fcckzugehen.",
		"tgt": "There seem to be fewer drivers taking alternative routes through the town."
	},
	{
		"src": "\"Da gab es teilweise erhebliche Beschwerden\", sagt der f\u00fcr das verkehrstechnische Management der Sanierung verantwortliche stellvertretende Hauptamtsleiter Florian King.",
		"tgt": "\"There were some serious complaints made,\" said Florian King, deputy chief officer responsible for traffic management during the redevelopment."
	},
	{
		"src": "Die Anwohner von Bachsatzstra\u00dfe, Steinlachstra\u00dfe, Hafnerstra\u00dfe und Weiherrain hatten mit mehr Verkehrsl\u00e4rm zu k\u00e4mpfen, weil sich viele Schleichwege suchten und eher ihrem Navi vertrauten als der Beschilderung.",
		"tgt": "Residents in Bachsatzstra\u00dfe, Steinlachstra\u00dfe, Hafnerstra\u00dfe and Weiherrain had to put up with more traffic noise because people were looking for ways to cut through, trusting their satnav more than the signage."
	},
	{
		"src": "Was dazu f\u00fchrte, dass sich mancher Lkw in Wohngebieten verfranste.",
		"tgt": "This led to some lorries hurtling through residential areas."
	},
	{
		"src": "Da auch die Geschwindigkeitsbegrenzungen nicht eingehalten wurden, forderte die Gemeinde verst\u00e4rkt das Messfahrzeug aus M\u00f6ssingen an.",
		"tgt": "The commune has increased calls for the measuring vehicle from M\u00f6ssingen because speed limits were not always adhered to either."
	},
	{
		"src": "\"Es gab erhebliche \u00dcberschreitungen\", sagt King, der sich selbst mal vor Ort \u00fcber die Lage kundig machte.",
		"tgt": "\"There were considerable infringements,\" said King, who had taken a look on-site to see what was going on."
	},
	{
		"src": "Da sind schon zwei bis drei pro Minute geblitzt worden.",
		"tgt": "Two to three vehicles were snapped by a speed camera every minute."
	},
	{
		"src": "Der Schnellste war mit 77 Stundenkilometern in der Tempo-30-Zone unterwegs.",
		"tgt": "The fastest was travelling at 77 kilometres per hour in a 30 zone."
	},
	{
		"src": "Seit die Baustelle weitergezogen ist, sei es aber ruhiger geworden.",
		"tgt": "Since the construction site has moved on, things have quietened down."
	},
	{
		"src": "F\u00fcr die Gesch\u00e4ftsleute an der B 27 ist es nur ein kleiner Trost, dass f\u00fcr Kunden aus Rottenburg nun die Stra\u00dfe wieder offen ist.",
		"tgt": "This is only a small consolation for businesses located along the B 27 that the road has reopened for customers from Rottenburg."
	},
	{
		"src": "In die Karten schauen lassen sich Gesch\u00e4ftsleute nicht gern.",
		"tgt": "Business people don't like to show their hand."
	},
	{
		"src": "Aber dass die B 27-Sanierung bei ihnen zu Umsatzeinbr\u00fcchen gef\u00fchrt hat, l\u00e4sst jeder, den man fragt, durchblicken.",
		"tgt": "But nobody we questioned hid the fact that the B 27 redevelopment had led to a drop in profits."
	},
	{
		"src": "Allerdings sind manche mehr und manche weniger betroffen.",
		"tgt": "However, some have been affected more than others."
	},
	{
		"src": "Wer mit dem \"Endkunden\" weniger zu tun hat, also f\u00fcr andere Firmen produziert, f\u00fcr den hat die Sanierung kaum Folgen.",
		"tgt": "People who have little to do with \"end customers\", i.e. if they make products for other companies, have hardly been affected by the redevelopment."
	},
	{
		"src": "Auch beim Autohaus Maier spricht Thomas Sulz von einem \"h\u00f6chstens leichten R\u00fcckgang\", r\u00e4umt aber auch ein, dass nat\u00fcrlich \"die Laufkundschaft fehlt\".",
		"tgt": "Even at the Maier car dealership, Thomas Sulz talked of \"a slight loss, at the most\", but also admitted that \"there had been a lack of passing trade\"."
	},
	{
		"src": "Am st\u00e4rksten gebeutelt sind die Lokale entlang der Stra\u00dfe.",
		"tgt": "Bars and restaurants along the road had been the hardest hit."
	},
	{
		"src": "J. Albert G\u00f6hner, Inhaber des Steakhouse, vormals Krone, findet deutliche Worte.",
		"tgt": "J. Albert G\u00f6hner, owner of the Steakhouse (previously Krone), expressed himself clearly."
	},
	{
		"src": "Das ist schon existenzbedrohend.",
		"tgt": "It has threatened our very existence."
	},
	{
		"src": "Nicht nur ihn, sondern alle Gastst\u00e4tten habe es \"hart getroffen\".",
		"tgt": "It's not just him: all restaurants have been \"hit hard\"."
	},
	{
		"src": "Es fehlten die Kunden aus Hechingen, Balingen und Rottweil.",
		"tgt": "Customers from Hechingen, Balingen and Rottweil stayed away."
	},
	{
		"src": "Wir m\u00fcssen froh sein \u00fcber jeden Euro Umsatz.",
		"tgt": "We have to be happy about every euro of profit we make."
	},
	{
		"src": "Die Umsatzeinbu\u00dfen beziffert er auf \"weit \u00fcber 50 Prozent\".",
		"tgt": "He reckons that profits slumped by \"far more than 50 percent\"."
	},
	{
		"src": "Die Stra\u00dfensanierung habe seinen Betrieb \"um zwei Jahre zur\u00fcckgeworfen\".",
		"tgt": "The road redevelopment \"set back\" his businesses \"by two years\"."
	},
	{
		"src": "Die H\u00e4lfte seiner Mitarbeiter habe er entlassen m\u00fcssen.",
		"tgt": "He had to let half of his staff go."
	},
	{
		"src": "Wenn ich eine Firma mit 4000 Mitarbeitern h\u00e4tte und die H\u00e4lfte w\u00e4re entlassen worden, h\u00e4tte die Politik anders reagiert.",
		"tgt": "If I had a company with 4000 employees and had to let half of them go, politicians would have reacted differently."
	},
	{
		"src": "Stattdessen hat Regierungspr\u00e4sident J\u00f6rg Schmidt auf eine Anfrage von G\u00f6hner, ob es einen finanziellen Ausgleich geben k\u00f6nnte, mit dem Hinweis geantwortet, die Gastst\u00e4tte profitiere sonst von den Vorteilen der Lage an der B 27. Jetzt m\u00fcsse sie eben auch die Nachteile, die sich durch die Sanierung ergeben, tragen.",
		"tgt": "Instead, when G\u00f6hner asked the government's president, J\u00f6rg Schmidt, if there would be financial compensation, the president replied that the restaurant benefited already from its location on the B 27. And now it just had to deal with the disadvantages thrown up by the redevelopment."
	},
	{
		"src": "G\u00f6hner wei\u00df von anderen Landkreisen, wo so etwas gro\u00dfz\u00fcgiger gehandhabt wurde.",
		"tgt": "G\u00f6hner knows of other districts where people have acted more generously."
	},
	{
		"src": "Bei allen Klagen ist G\u00f6hner sich sicher, dass seine Gastst\u00e4tte weiterbestehen wird.",
		"tgt": "Despite all the complains, G\u00f6hner is convinced that his restaurant will survive."
	},
	{
		"src": "Schlie\u00dflich ist der Familienbetrieb schon seit 1715 hier angesiedelt, verweist er auf die lange Historie.",
		"tgt": "After all, the family business moved there back in 1715, he said, referring to its long history."
	},
	{
		"src": "Dass sonstige Stammg\u00e4ste jetzt wegen der komplizierten Verkehrsf\u00fchrung weniger h\u00e4ufig vorbeischauen, kann er verstehen.",
		"tgt": "He can understand that his regular customers visit less as a result of the complicated traffic system."
	},
	{
		"src": "Wenn man nicht herfahren kann, ist es auch woanders sch\u00f6n.",
		"tgt": "If you can't drive past, other places are also nice."
	},
	{
		"src": "Dass seine Stammklientel nach Ende der Sanierungsarbeiten wieder zur\u00fcckkommt, daran hat G\u00f6hner keine Zweifel.",
		"tgt": "G\u00f6hner has no doubt that his regulars will return once the redevelopment works have been completed."
	},
	{
		"src": "Trotz der Krisen mit BSE und Vogelgrippe h\u00e4lt G\u00f6hner die Auswirkungen der B 27-Bauarbeiten auf seine Kundschaft f\u00fcr die gr\u00f6\u00dfte Krise, die seine Gastst\u00e4tte in ihrer langj\u00e4hrigen Geschichte erlebt hat.",
		"tgt": "Despite the crises with BSE and bird flu, G\u00f6hner believes that the effects of the B 27 works on his clientele mark the biggest crisis his restaurant has suffered in its long history."
	},
	{
		"src": "Sechs Monate Bauarbeiten, das ist schon brutal.",
		"tgt": "Six months of construction works, that's brutal."
	},
	{
		"src": "St\u00e4ndig wird im Namen der Terrorbek\u00e4mpfung an Gesetzen geschraubt.",
		"tgt": "Law are constantly being passed in the name of anti-terrorism."
	},
	{
		"src": "Nach den j\u00fcngsten Anschl\u00e4gen legt Innenminister de Maizi\u00e8re nun ein dickes Sicherheitspaket vor.",
		"tgt": "After the most recent attacks, Minister of the Interior de Maizi\u00e8re is now putting forward a host of security measures."
	},
	{
		"src": "Aber was hat ein Duldungsstatus mit Terror zu tun?",
		"tgt": "But what does residential status have to do with terrorism?"
	},
	{
		"src": "Und was sagt der Koalitionspartner zu all dem?",
		"tgt": "And what does the coalition partner have to say about it all?"
	},
	{
		"src": "Thomas de Maizi\u00e8re gibt den Vers\u00f6hner.",
		"tgt": "Thomas de Maizi\u00e8re is playing the conciliator."
	},
	{
		"src": "Alle seine Vorschl\u00e4ge seien dem Koalitionspartner \"politisch zumutbar\", sagt der Bundesinnenminister bei der Vorstellung seines neuen Sicherheitspakets.",
		"tgt": "All his proposals are \"politically reasonable\" for the coalition partner, the Federal Minister of the Interior said when revealing his new security package."
	},
	{
		"src": "Sie \u00fcberfordern niemanden.",
		"tgt": "They are not asking too much of anyone."
	},
	{
		"src": "Andere, weitergehende Punkte w\u00fcrden zun\u00e4chst innerhalb der Parteien diskutiert.",
		"tgt": "Other, more wide-reaching issues will first be discussed within the parties."
	},
	{
		"src": "Auch daran beteilige ich mich.",
		"tgt": "I will also be involved in that."
	},
	{
		"src": "Als Innenminister sei ihm aber an Ergebnissen gelegen und an einem \"erzielbaren Konsens\" innerhalb der Koalition.",
		"tgt": "As Minister of the Interior, however, he is responsible for results, and for reaching an \"achievable agreement\" within the coalition, he says."
	},
	{
		"src": "De Maizi\u00e8re hat nach den j\u00fcngsten Anschl\u00e4gen in W\u00fcrzburg und Ansbach ein wenig Zeit verstreichen lassen, bevor er seine Schlussfolgerungen f\u00fcr die Sicherheit in der Republik pr\u00e4sentiert.",
		"tgt": "After the most recent attacks in W\u00fcrzburg and Ansbach, de Maizi\u00e8re let a little time pass before announcing his conclusions for security within Germany."
	},
	{
		"src": "Die fallen daf\u00fcr nun aber umso umfangreicher aus.",
		"tgt": "However, they are more comprehensive as a result."
	},
	{
		"src": "Einiges ist schon bekannt, verk\u00fcndet, angepeilt: Dass sich eine neue Sicherheitsbeh\u00f6rde um das Knacken verschl\u00fcsselter Kommunikation k\u00fcmmern soll, ist nicht neu.",
		"tgt": "One thing was already known, announced, heralded: The fact that a new security agency is going to work on cracking encrypted communications is not new."
	},
	{
		"src": "Auch nicht die Tatsache, dass Deutschland mehrere EU-Vorgaben zu Fluggastdaten und Waffenrecht umsetzen muss.",
		"tgt": "Neither is the fact that Germany will have to implement several EU directives on air passenger data and gun laws."
	},
	{
		"src": "Der Ruf nach mehr Video\u00fcberwachung und Personal f\u00fcr die Sicherheitsbeh\u00f6rden kommt ebenso nicht \u00fcberraschend.",
		"tgt": "The call for more video surveillance and staff for security agencies also does not come as a surprise."
	},
	{
		"src": "Zum Teil startet de Maizi\u00e8re einen zweiten Anlauf f\u00fcr Vorschl\u00e4ge, die mit der SPD bislang nicht zu machen waren: Er will Sympathiewerbung f\u00fcr Terrorgruppen unter Strafe stellen und Dschihadisten mit doppelter Staatsb\u00fcrgerschaft den deutschen Pass abkn\u00f6pfen.",
		"tgt": "To some extent, de Maizi\u00e8re is launching a second attempt at proposals that the SPD long wanted nothing to do with: He wants to penalise advertising for terrorist groups, and remove German passports from jihadis with dual citizenship."
	},
	{
		"src": "\"Das werden schwierige Punkte sein f\u00fcr die SPD\", r\u00e4umt der CDU-Mann ein.",
		"tgt": "\"They will be difficult issues for the SPD,\" admitted the CDU politician."
	},
	{
		"src": "Er halte dies trotzdem f\u00fcr zumutbar und fordere auch nichts, was beim Koalitionspartner ohnehin keine Chancen habe.",
		"tgt": "Despite this, he believes they are achievable, and is not demanding anything that has no chance with the coalition partner."
	},
	{
		"src": "Ein paar neue Ideen pr\u00e4sentiert de Maizi\u00e8re auch.",
		"tgt": "De Maizi\u00e8re also presented a few new ideas."
	},
	{
		"src": "Die haben es teilweise in sich: Er plant Schnellverfahren f\u00fcr Abschiebungen und mehr M\u00f6glichkeiten zur Inhaftierung von Menschen vor der Abschiebung.",
		"tgt": "Some of them have a lot to offer: He is planning accelerated processes for deportation and more opportunities to arrest individuals prior to their deportation."
	},
	{
		"src": "Fl\u00fcchtlinge, die gezielt ins Land geholt werden, sollen vorher ihre Smartphones checken lassen und Social-Media-Accounts f\u00fcr eine Sicherheits\u00fcberpr\u00fcfung offenlegen.",
		"tgt": "Refugees who are specifically brought to the country should allow their smartphones to be checked, and present their social media accounts for security checks."
	},
	{
		"src": "Bei Duldungen f\u00fcr abgelehnte Asylbewerber will er manche noch schlechter stellen als bislang - etwa solche, die Straftaten begehen oder ihre Papiere bewusst wegwerfen, um ihre Identit\u00e4t zu verschleiern.",
		"tgt": "He wants to reduce tolerance for people who have been refused asylum - such as those who commit crimes, or deliberately throw away their papers to conceal their identity."
	},
	{
		"src": "Einiges davon ist politisch und rechtlich heikel.",
		"tgt": "Some of it is politically and legally tricky."
	},
	{
		"src": "Manches wirkt auch noch unausgegoren und l\u00e4sst Fragen offen.",
		"tgt": "Some of it also seems half-baked, and leaves questions to be answered."
	},
	{
		"src": "Und bei einigen Punkten - bei der Ungleichbehandlung von Geduldeten zum Beispiel - stellt sich die Frage: Was hat das eigentlich mit Sicherheit und Terror zu tun?",
		"tgt": "And for some points - such as the unequal treatment of tolerated persons - the following question is raised: What does that actually have to do with security and terrorism?"
	},
	{
		"src": "Ja, sagt de Maizi\u00e8re, es sei wichtig zu differenzieren zwischen den Themen Fl\u00fcchtlinge und Terror.",
		"tgt": "Yes, de Maizi\u00e8re says, it is important to differentiate between the issues posed by refugees, and the issue of terrorism."
	},
	{
		"src": "Aber es l\u00e4sst sich ja nicht in Abrede stellen, dass die Attent\u00e4ter von Ansbach und W\u00fcrzburg Fl\u00fcchtlinge waren.",
		"tgt": "But it cannot be denied that the perpetrators of the attacks in Ansbach and W\u00fcrzburg were refugees."
	},
	{
		"src": "Au\u00dferdem machten sich viele Menschen angesichts der hohen Fl\u00fcchtlingszahlen Sorgen um die Sicherheit.",
		"tgt": "In addition, many people are worried about security because of the large numbers of refugees."
	},
	{
		"src": "Und Dinge, die die Menschen zutiefst besch\u00e4ftigten, lie\u00dfen sich nun mal auch in Wahlkampfzeiten nicht ausklammern.",
		"tgt": "And things that deeply worry people cannot be ignored - even during election season."
	},
	{
		"src": "Die innere Sicherheit ist enorm in den Fokus ger\u00fcckt.",
		"tgt": "Domestic security has come to the fore to a huge extent."
	},
	{
		"src": "Erst die Anschl\u00e4ge in der Nachbarschaft: Paris, Kopenhagen, Br\u00fcssel, Nizza.",
		"tgt": "First the attacks in neighbouring countries: Paris, Copenhagen, Brussels, Nice."
	},
	{
		"src": "Dann die Attacken in W\u00fcrzburg und Ansbach.",
		"tgt": "Then the attacks in W\u00fcrzburg and Ansbach."
	},
	{
		"src": "Die Verunsicherung ist gro\u00df.",
		"tgt": "There is a large amount of uncertainty."
	},
	{
		"src": "Und ja, es stehen Wahlk\u00e4mpfe an.",
		"tgt": "And yes, elections are looming."
	},
	{
		"src": "Union und SPD bringen sich beim Thema innere Sicherheit daher zunehmend in Stellung.",
		"tgt": "The Union and the SPD are consequently focusing more and more on the issue of security."
	},
	{
		"src": "In den vergangenen Tagen ging es zwischen den beiden Parteien hoch her.",
		"tgt": "Over the past few days things have been quite heated between the two parties."
	},
	{
		"src": "Erst ein garstiger Streit \u00fcber die Ausstattung der Bundespolizei, dann \u00fcber eine sicherheitspolitische Ideen-Sammlung einiger Unions-Innenminister, in der die Ressortchefs auch ein Burka-Verbot und eine Abkehr von der doppelten Staatsb\u00fcrgerschaft fordern.",
		"tgt": "First a nasty argument about the Federal Police Force's equipment, then about an ideas-gathering event for security and politics-related discussions between some Ministers of the Interior in the Union, at which a burka ban and the renunciation of dual citizenship were demanded by department heads."
	},
	{
		"src": "De Maizi\u00e8re m\u00fcht sich auch hier um vers\u00f6hnliche T\u00f6ne.",
		"tgt": "De Maizi\u00e8re is also trying to strike a conciliatory note here."
	},
	{
		"src": "Von einer Abkehr vom Doppelpass halte er nichts.",
		"tgt": "He does not think that dual citizenship will be removed."
	},
	{
		"src": "Wir haben die Diskussion in Deutschland befriedet.",
		"tgt": "We have dealt with the discussions in Germany."
	},
	{
		"src": "Sie neu aufzumachen, sei nicht sinnvoll.",
		"tgt": "It would not make sense to reopen discussions on this topic."
	},
	{
		"src": "Und bei einem Burka-Verbot habe er verfassungsrechtliche Bedenken.",
		"tgt": "And he thinks that a burka ban would come up against constitutional issues."
	},
	{
		"src": "Ob sein eigenes Paket an allen Ecken verfassungsfest ist und ob es tats\u00e4chlich \"zumutbar\" ist f\u00fcr den Koalitionspartner, muss sich erst noch zeigen.",
		"tgt": "However, it remains to be seen whether his own package is in line with the constitution throughout, and whether it really is \"achievable\" for his coalition partner."
	},
	{
		"src": "Es steckt einiges drin, was f\u00fcr Streit sorgen k\u00f6nnte.",
		"tgt": "There are few things inside it that could cause problems."
	},
	{
		"src": "Doch auch die SPD versucht derzeit, sich beim Thema innere Sicherheit zu profilieren.",
		"tgt": "But the SPD is also currently attempting to use the issue of domestic security to shape itself."
	},
	{
		"src": "Parteichef Sigmar Gabriel signalisiert erst mal vorsichtig Gespr\u00e4chsbereitschaft und sagt: \"Die SPD ist bereit, \u00fcber alles zu reden, was dazu beitr\u00e4gt, die Sicherheit weiter zu erh\u00f6hen\".",
		"tgt": "SPD Head Sigmar Gabriel showed that the party was happy to discuss the issue, albeit sensitively at first, saying that \"the SPD is prepared to discuss anything that will increase security further.\""
	},
	{
		"src": "Noch kommt Volkswagen glimpflich durch.",
		"tgt": "Volkswagen gets off lightly."
	},
	{
		"src": "Trotz Dieselskandals steigen die Auslieferungszahlen weltweit.",
		"tgt": "Despite the diesel scandal, global delivery figures are increasing."
	},
	{
		"src": "Doch nicht in allen M\u00e4rkten l\u00e4uft es rund.",
		"tgt": "But things aren't quite as rosy in all markets."
	},
	{
		"src": "Bei der R\u00fcckrufaktion gibt es Wirbel um einen Begriff.",
		"tgt": "The recall has led to fuss about one term."
	},
	{
		"src": "Volkswagen startet bei den Auslieferungen verhaltener in das zweite Halbjahr.",
		"tgt": "Volkswagen's deliveries were more restrained in the second half of the year."
	},
	{
		"src": "Europas gr\u00f6\u00dfter Autobauer kann im bisherigen Jahresverlauf zwar trotz der Dieselaff\u00e4re dank seiner vielen Marken und einiger gut laufender M\u00e4rkte weiter ein Plus vorweisen.",
		"tgt": "Thanks to its number of brands and some well-functioning markets, Europe's largest car manufacturer can boast another plus for the previous year, despite the diesel scandal."
	},
	{
		"src": "Doch im Juli schw\u00e4chelte die Kernmarke VW vor allem in Westeuropa und belastete damit wieder den Gesamtverkauf, wie das im Dax notierte Unternehmen mitteilte.",
		"tgt": "However, in July, the VW core brand suffered, particularly in Western Europe, thereby affecting overall sales, as the Dax-listed company announced."
	},
	{
		"src": "Weltweit verkaufte die Marke VW im Juli mit 449100 Autos 1,8 Prozent weniger Fahrzeuge als im Vorjahresmonat.",
		"tgt": "Globally, the VW brand sold 449,100 cars in July - 1.8 percent fewer vehicles than in the same month in the previous year."
	},
	{
		"src": "Allein in Westeuropa, nach China der zweitwichtigste Markt, lagen die Verk\u00e4ufe 14 Prozent unter dem Vorjahresmonat.",
		"tgt": "In Western Europe alone, the second most important market after China, sales were 14 percent lower than in the same month the year before."
	},
	{
		"src": "Im Heimatmarkt Deutschland sackten die Auslieferungen um fast ein Sechstel ab.",
		"tgt": "In its home market of Germany, deliveries plummeted by almost a sixth."
	},
	{
		"src": "Markenvertriebschef J\u00fcrgen Stackmann f\u00fchrte die schw\u00e4cheren Zahlen aus dem Juli vor allem auf zwei Verkaufstage weniger in Europa zur\u00fcck.",
		"tgt": "Head of brand sales, J\u00fcrge Stackmann, blamed July's poor figures on the loss of two sales days in Europe."
	},
	{
		"src": "Zudem habe es in einigen Kernm\u00e4rkten durch \"ver\u00e4nderte wirtschaftliche Rahmenbedingungen\" eine Kaufzur\u00fcckhaltung gegeben.",
		"tgt": "In addition, some key markets saw \"changed economic climates\", which led to fewer purchases."
	},
	{
		"src": "Neben der Situation rund um den Putschversuch in der T\u00fcrkei habe auch das britische Votum zum Austritt aus der EU belastet, erl\u00e4uterte eine Sprecherin.",
		"tgt": "In addition to the situation regarding the attempted coup in Turkey, the British vote to leave the EU had also had an impact, a spokeswoman said."
	},
	{
		"src": "In den USA, wo die Abgasaff\u00e4re zuerst eskalierte, steht ebenfalls weiter ein Minus zu Buche.",
		"tgt": "In the USA, where the emissions scandal first began, the books are once again in the red."
	},
	{
		"src": "Gro\u00dfe St\u00fctze f\u00fcr VW ist der chinesische Markt.",
		"tgt": "The Chinese market is a source of great support for VW."
	},
	{
		"src": "Insgesamt kommt die haupts\u00e4chlich betroffene Hausmarke der Niedersachsen ohnehin weiter glimpflich durch den Dieselskandal: Nach den ersten sieben Monaten steht lediglich ein Auslieferungsminus von 0,9 Prozent auf 3,37 Millionen Fahrzeuge zu Buche.",
		"tgt": "In total, Lower Saxony's own brand, which was most affected, has got off lightly from the diesel scandal: After the first seven months, there is a minus in the books for deliveries amounting to 0.9 percent of 3.37 million vehicles."
	},
	{
		"src": "Konzernvertriebschef Fred Kappler konnte von Januar bis Juli weiter ein Verkaufsplus vorweisen.",
		"tgt": "Head of sales at the company, Fred Kappler, was once again able to bring out an increase in sales from January to July."
	},
	{
		"src": "1,3 Prozent mehr Fahrzeuge lieferte Volkswagen in dieser Zeit aus, weltweit 5,904 Millionen.",
		"tgt": "Volkswagen delivered 1.3 percent more vehicles in this time period, coming to a global total of 5.904 million."
	},
	{
		"src": "Volkswagen hatte mit einer Software Abgastests manipuliert.",
		"tgt": "Volkswagen had used software to manipulate emissions tests."
	},
	{
		"src": "Alleine in Deutschland ruft VW rund 2,5 Millionen Wagen zur Umr\u00fcstung in die Werkst\u00e4tten.",
		"tgt": "In Germany alone, VW has called 2.5 million vehicles back to workshops to be refitted."
	},
	{
		"src": "Im Zuge der Umr\u00fcstung bekr\u00e4ftigte VW, dass der Umbau der Autos keine negativen Auswirkungen hat.",
		"tgt": "In the course of modifying the vehicles VW emphasised that refitting them would have no negative effects."
	},
	{
		"src": "Nach der Umr\u00fcstung der Fahrzeuge gebe es bei Kraftstoffverbrauch, CO2-Emissionen oder Motorleistung keinerlei Verschlechterung.",
		"tgt": "After the vehicles have been modified, fuel consumption, CO2 emissions or motor performance would not get worse."
	},
	{
		"src": "Der Autobauer stelle den Kunden nach der Umr\u00fcstung eine \"garantiegleiche\" Bescheinigung aus, spreche aber nicht von einer \"Garantie\", wie es am Freitag in Unternehmenskreisen hie\u00df.",
		"tgt": "After modification, the car manufacturer will provide its customers with a certificate that is \"as good as a guarantee\" but would not talk of an actual \"guarantee\", as was mentioned on Friday in corporate circles."
	},
	{
		"src": "Grund seien juristische Feinheiten.",
		"tgt": "Legal intricacies are the reason for this."
	},
	{
		"src": "Der \"Focus\" hatte berichtet, Volkswagen gew\u00e4hre seinen deutschen Kunden jetzt doch eine Garantie f\u00fcr umger\u00fcstete Dieselmodelle.",
		"tgt": "\"Focus\" reported that Volkswagen would provide its German customers with a guarantee for modified diesel cars nonetheless."
	},
	{
		"src": "Dies h\u00e4tten am vergangenen Montag VW-Vertreter im Bundesverkehrsministerium best\u00e4tigt.",
		"tgt": "This was confirmed by VW representatives at the Federal Ministry of Transport on the Monday previous."
	},
	{
		"src": "Aus dem Verkehrsministerium wurde best\u00e4tigt, dass es dieses Treffen gab.",
		"tgt": "The Ministry of Transport confirmed that this meeting had taken place."
	},
	{
		"src": "\"VW hat die Auflagen meiner Untersuchungskommission und des KBA vollumf\u00e4nglich zu erf\u00fcllen.\"",
		"tgt": "\"VW must fully meet the requirements of my investigative committee and the KBA.\""
	},
	{
		"src": "\"Abweichungen davon werden nicht akzeptiert\", erkl\u00e4rte Bundesverkehrsminister Alexander Dobrindt (CSU) laut Ministerium.",
		"tgt": "\"Deviations will not be accepted,\" explained Alexander Dobrindt (CDU), the Federal Minister for Transport, according to the Ministry."
	},
	{
		"src": "VW hat die Garantie \u00fcbernommen, dass bei Kraftstoffverbrauch, CO2-Emissionen oder Motorleistung nach der Umr\u00fcstung keine Verschlechterungen stattfinden und alle typgenehmigungsrelevanten Fahrzeugwerte unver\u00e4ndert Bestand haben.",
		"tgt": "VW took on the guarantee that fuel consumption, CO2 emissions or motor performance would not get worse as a result of the modification, and all vehicle values relevant to type approval would remain unchanged."
	},
	{
		"src": "Volkswagen selbst verwendet den Begriff \"Garantie\" aber nicht, wie es in Unternehmenskreisen hie\u00df.",
		"tgt": "Volkswagen itself does not use the term \"guarantee\", as has been mentioned in corporate circles."
	},
	{
		"src": "Bei dem weiten Begriff \"Garantie\" sieht Volkswagen die M\u00f6glichkeit, dass Kunden zum Beispiel ein halbes Jahr nach der Umr\u00fcstung etwa mit einem Motorschaden in eine Werkstatt kommen - und dies auf die neue Software zur\u00fcckf\u00fchren k\u00f6nnten, auch wenn der Schaden damit nichts zu tun hat.",
		"tgt": "Volkswagen believes that the broad term \"guarantee\" could see customers returning to the workshop with motor damage six months after the modification - and being able to blame this on the new software, even if the damage had nothing at all to do with it."
	},
	{
		"src": "Auch im Kundeninteresse sei es wichtig zu vermeiden, dass es bei etwaigen anderen Sch\u00e4den, die gar nichts mit dem Abgasskandal zu tun haben, zu einer Verunsicherung hinsichtlich m\u00f6glicher Gew\u00e4hrleistungsregelungen kommt, wie es hie\u00df.",
		"tgt": "It is also in the customers' interest to prevent confusion with guarantee clauses for any other faults that have nothing at all to do with the emissions scandal."
	},
	{
		"src": "Deswegen verwende VW den Begriff \"Garantie\" nicht.",
		"tgt": "This is why VW will not be using the term \"guarantee\"."
	},
	{
		"src": "Die Raiffeisenbank Gmund am Tegernsee verlangt von reichen Sparern k\u00fcnftig Strafzinsen - als zweites Institut in Deutschland.",
		"tgt": "The Raffeisen Bank in Gmund am Tegernsee will demand penalty interest from wealthy savers in the future - and it will be the second bank in Germany to do so."
	},
	{
		"src": "Bankchef Josef Paul sagte am Donnerstag: \"Es geht nur um 139 Kunden, die 40 Millionen Euro auf Giro- oder Tagesgeldkonten parken\".",
		"tgt": "Managing Director of the bank, Josef Paul, said on Thursday that \"this only applies to 139 customers with 40 million euros in their current accounts or day-to-day accounts\"."
	},
	{
		"src": "Der Bundesverband Deutscher Banken spricht von einem Einzelfall und sieht darin kein Signal: Normale Sparer m\u00fcssten \"nicht bef\u00fcrchten, f\u00fcr ihre Spargroschen Strafzins zu zahlen\".",
		"tgt": "The Federal Association of German Banks believes this is an isolated case, and does not see it as a sign: normal savers \"need not worry about being hit with penalty interest on the pennies they've put aside\"."
	},
	{
		"src": "Lagern Banken Geld \u00fcber Nacht bei der Europ\u00e4ischen Zentralbank (EZB), m\u00fcssen sie ihr 0,4 Prozent Strafzins zahlen.",
		"tgt": "If banks invest money overnight with the European Central Bank (ECB), they have to pay penalty interest of 0.4 percent."
	},
	{
		"src": "Diese Geb\u00fchr verlangt die Raiffeisenbank Gmund ab September von Privat- und Firmenkunden f\u00fcr Einlagen \u00fcber 100.000 Euro auf Giro- oder Tagesgeldkonten zur\u00fcck.",
		"tgt": "From September, the Raffeisen Bank in Gmund will be asking private and business customers with more than 100,000 euros in their current account or day-to-day account to pay this fee."
	},
	{
		"src": "\"Die ersten 100.000 Euro sind frei.\"",
		"tgt": "\"The first 100,000 euros are free.\""
	},
	{
		"src": "\"Die n\u00e4chsten 100.000 kosten k\u00fcnftig 400 Euro im Jahr\", sagte Paul.",
		"tgt": "\"In the future, any subsequent 100,000 euros will cost 400 euros a year,\" Paul said."
	},
	{
		"src": "Er h\u00fcte seit geraumer Zeit 40 Millionen Euro, die von einem Tag auf den anderen abgehoben werden k\u00f6nnten und die er nicht verwerten k\u00f6nne.",
		"tgt": "For some time, he has been managing 40 million euros that could be withdrawn any day, and that he is unable to make use of."
	},
	{
		"src": "\"Die liegen bei mir auf dem Zentralbankkonto und verursachen 0,4 Prozent Kosten\", sagte der Bankchef.",
		"tgt": "\"The money has been sitting in my account at the Central Bank, and costing 0.4 percent,\" the bank CEO said."
	},
	{
		"src": "\"Ich kann nicht f\u00fcr jede Million 4000 Euro hinlegen.\"",
		"tgt": "\"I cannot put 4000 euros aside for every million.\""
	},
	{
		"src": "Die Kosten gebe er nach dem Verursacherprinzip nun weiter.",
		"tgt": "He is passing on the costs under the \"polluter pays\" principle."
	},
	{
		"src": "Das Bargeld einfach in den Tresoren der Raiffeisenbank liegen zu lassen, w\u00e4re viel zu gef\u00e4hrlich: \"Ich hab' schon vier \u00dcberf\u00e4lle erlebt, ich m\u00f6cht nicht noch den f\u00fcnften!\", sagte der Bankvorstand.",
		"tgt": "It would be far too dangerous just to leave the cash in the Raffeisen Bank's safe: \"I have already been through four raids, I don't want a fifth!\" the bank's managing director said."
	},
	{
		"src": "Die meisten Kunden h\u00e4tten Verst\u00e4ndnis und wechselten auf andere Anlageformen.",
		"tgt": "Most customers have been understanding, and have switched to other forms of investment."
	},
	{
		"src": "Nur wenige wanderten zu anderen Banken ab.",
		"tgt": "Only a small number moved to other banks."
	},
	{
		"src": "Der Genossenschaftsverband Bayern erkl\u00e4rte: \"Der extreme geldpolitische Kurs der EZB verursacht bei allen Banken erhebliche Kosten\".",
		"tgt": "The Federation of Cooperatives of Bavaria explained that \"the extreme monetary policy pursued by the ECG leads to all banks incurring significant costs\"."
	},
	{
		"src": "Sie allein zu tragen, sei \"betriebswirtschaftlich dauerhaft nicht m\u00f6glich\".",
		"tgt": "It would be \"impossible\" for them to bear these costs \"on a permanent basis, from a business perspective\"."
	},
	{
		"src": "Einige deutsche Banken haben deshalb ihre Geb\u00fchren f\u00fcr Kontof\u00fchrung, Kreditkarten oder \u00dcberweisungen erh\u00f6ht.",
		"tgt": "As a result, some German banks have increased the fees they charge for account management, credit cards or transfers."
	},
	{
		"src": "Mit Strafzinsen f\u00fcr Einlagen ab drei Millionen Euro hatte die Th\u00fcringer Volks- und Raiffeisenbank Altenburger Land mit ihrer Skatbank-Filiale 2014 Schlagzeilen gemacht.",
		"tgt": "Thuringia's \"Volks- und Raffeisen Bank\" in Altenburger Land hit the headlines in 2014 when their Skatbank branch imposed penalty interest on investments of more than three million euros."
	},
	{
		"src": "Michael Kemmer, Hauptgesch\u00e4ftsf\u00fchrer des Bankenverbandes, sagte: \"Wir erwarten nicht, dass Privatkunden fl\u00e4chendeckend Entgelte f\u00fcr Einlagen bezahlen m\u00fcssen, dazu ist der Wettbewerb in Deutschland unter Banken und Sparkassen viel zu stark\".",
		"tgt": "Michael Kemmer, managing director of the banking association, said: \"We are not expecting that private customers will all have to pay fees for investments - the competition between banks in Germany is much too strong for that\"."
	},
	{
		"src": "Ein Banker sagte, am Tegernsee gebe es \"eine Klientel, die vom Verm\u00f6gen etwas \u00fcppiger ausgestattet ist\".",
		"tgt": "A banker said that, in Tegernsee, there was \"clientele who were rather better off in terms of assets.\""
	},
	{
		"src": "\"Das kann f\u00fcr eine kleine Bank zum Problem werden\", wenn sie kostenlos Geld h\u00fcte.",
		"tgt": "\"That can be a problem for a small bank,\" if the bank is looking after their money for free."
	},
	{
		"src": "Die 1911 gegr\u00fcndete Genossenschaftsbank Gmund hat Zweigstellen in Bad Wiessee, Rottach-Egern, Kreuth und Tegernsee.",
		"tgt": "The Cooperative Bank of Gmund was founded in 1911, and has branches in Bad Wiessee, Rottach-Egern, Kreuth and Tegernsee."
	},
	{
		"src": "In der Region wohnen bekannte Schauspieler, Sportler und Unternehmer.",
		"tgt": "Famous actors, sportspeople and enterpreneurs live in the region."
	},
	{
		"src": "Dem Genossenschaftsverband Bayern \"sind derzeit keine weiteren Banken bekannt, die einen Auslagenersatz f\u00fcr Einlagen von Privatkunden berechnen\", sagte Sprecher Ernst.",
		"tgt": "Spokesperson Ernst said that the Cooperative Association of Bavaria \"was not currently aware of any other banks that ask private customers to reimburse their expenses\"."
	},
	{
		"src": "Der Pr\u00e4sident des Bundesverbandes der deutschen Volksbanken und Raiffeisenbanken (BVR), Uwe Fr\u00f6hlich, hatte Ende Juni erkl\u00e4rt: \"Die Schwelle, ins Negative zu gehen gegen\u00fcber dem Privatkunden, ist sehr, sehr hoch\".",
		"tgt": "The President of the Bundesverband der deutschen Volksbanken und Raiffeisenbanken (BVR), Uwe Fr\u00f6hlich, said at the end of June that \"the threshold for tipping into the red in terms of private customers is very, very high\"."
	},
	{
		"src": "Die Konkurrenz sei hart, und es drohe die Abwanderung von Anlegern zur Konkurrenz.",
		"tgt": "Competition is fierce, and there is the risk that investors will move to competitors."
	},
	{
		"src": "Die Kunden in Deutschland werden sich das in der Breite nicht gefallen lassen.",
		"tgt": "Customers in Germany will not put up with that, broadly speaking."
	},
	{
		"src": "Destination Platten: wer kauft eigentlich Schallplatten?",
		"tgt": "Vinyl destination: who is actually buying records?"
	},
	{
		"src": "Einsame M\u00e4nner mittleren Alters lieben Platten.",
		"tgt": "Lonely, middle-aged men love vinyl."
	},
	{
		"src": "Bevor Sie zum Kommentarteil eilen, um ihn unter dem Pseudonym NichtAlleEinsamenM\u00e4nnerMittlerenAlters mit rauen Beleidigungen zu \u00fcbers\u00e4en, diese Aussage leitet sich von aktuellen Daten ab.",
		"tgt": "Before you rush to litter the comments section with gnarly insults under the pseudonym NotAllLonelyMiddleAgedMen, this statement derives from actual data."
	},
	{
		"src": "Laut YouGov ist die vielbesprochene Wiederaufstehung von Schallplatten nicht auf einen Boom in Millennials, die die Neuigkeit von physischen Gegenst\u00e4nden begr\u00fc\u00dfen wollen, sondern auf Midlife-Nostalgie zur\u00fcckzuf\u00fchren.",
		"tgt": "According to YouGov, the much talked-about record resurgence is driven not by a boom in millennials who want to embrace the novelty of a physical item, but by midlife nostalgia."
	},
	{
		"src": "Diejenigen, die vor kurzem eine Platte gekauft haben, sind aller Voraussicht nach im Alter zwischen 45 und 54.",
		"tgt": "Those who have recently purchased a vinyl album are most likely to be aged between 45 and 54, apparently."
	},
	{
		"src": "In der Tat ist die Altersgruppe von 18-24 die unwahrscheinlichste K\u00e4ufergruppe.",
		"tgt": "In fact, those in the 18-24 age group are the least likely."
	},
	{
		"src": "Es ist auch kein Horden durch Hobbysammlern - es hat eine emotionale Bedeutung: \u00e4ltere Plattenk\u00e4ufer behalten ihre Gef\u00fchle eher f\u00fcr sich (56 % vs. 53 %) und genie\u00dfen es, alleine Zeit zu verbringen (69 % vs. 66 %).",
		"tgt": "It is not just an act of hoarding by hobbyists, either - it has emotional significance: older vinyl buyers are slightly more likely to keep their feelings to themselves (56% versus 53%) and enjoy being alone (69% versus 66%)."
	},
	{
		"src": "Aber stimmen die Ergebnisse von YouGov?",
		"tgt": "But are YouGov's results true?"
	},
	{
		"src": "Wenn dieser Blog ein Nachrichtenbericht im Fernsehen w\u00e4re, w\u00fcrde mir die Kamera folgen, w\u00e4hrend ich inmitten einer gesch\u00e4ftigen Stra\u00dfe in Soho laufe, einen bescheidenen grauen Anzug trage und wild gestuliere, bevor ich stehenbleibe, meine H\u00e4nde halte und etwas Bestimmendes sage wie: \"Also, lassen Sie uns einen n\u00e4heren Blick darauf werfen.\"",
		"tgt": "If this blog was a televised news report, the camera would follow me as I walked down the middle of a busy Soho street, wearing a modest grey suit and gesturing wildly before stopping, cupping my hands and saying something authoritative like: \"So, let's take a look.\""
	},
	{
		"src": "Also, lassen Sie uns einen Blick darauf werfen.",
		"tgt": "So, let's take a look."
	},
	{
		"src": "Auch wenn das Herz Sohos langsam an seinem Charme einb\u00fc\u00dft - Hotels, Restaurants und B\u00fcros f\u00fcllen jetzt die Geb\u00e4ude, in denen einst unabh\u00e4ngige Verk\u00e4ufer ans\u00e4ssig waren - gibt es nach wie vor eine Handvoll fantastischer Plattenspezialgesch\u00e4fte.",
		"tgt": "While the heart of Soho is slowly being drained of its charm and grot - hotels, Eats, Prets and Paperchases now fill the buildings once occupied by independent sellers - a handful of fantastic specialist record shops still remain."
	},
	{
		"src": "Ich w\u00fcrde den Kameramann vermutlich bitten, die Kamera f\u00fcr den n\u00e4chsten Teil auszuschalten, in dem ich in unmittelbarer N\u00e4he zu verschiedenen M\u00e4nnern in solchen Gesch\u00e4ften stehe und versuche, ihr Alter und Gem\u00fct durch Beobachtung einzusch\u00e4tzen.",
		"tgt": "I'd probably ask the camera to stop rolling for the next bit, in which I stand very close to various men in some of these stores and attempt to gauge their age and emotional disposition via observation."
	},
	{
		"src": "Stuart aus Glasgow, 55, dem ich von Sister Ray (Datenanzahl: zwei junge Frauen, drei M\u00e4nner mittleren Alters) ins Reckless Records (Datenanzahl: acht M\u00e4nner mittleren Alters, eine Frau, vermutlich um die 20) folge, ist einen Tag lang wegen eines Treffens in London und geht durch die Gesch\u00e4fte, um die paar Stunden zu f\u00fcllen.",
		"tgt": "Glaswegian Stuart, 55, whom I follow from Sister Ray (data count: two young women, three middle-aged men) into Reckless Records (data count: eight middle-aged men, one woman, probably in her 20s) is in London for the afternoon for a meeting and is perusing the shops to fill a few hours."
	},
	{
		"src": "Ist er ein Sammler, frage ich?",
		"tgt": "Is he a collector, I ask?"
	},
	{
		"src": "\"Ich sch\u00e4tze schon,\" sagt er.",
		"tgt": "\"I suppose I am,\" he says."
	},
	{
		"src": "Ich habe ca. 3.000 oder 4.000 Platten.",
		"tgt": "I have about 3,000 or 4,000 records."
	},
	{
		"src": "Diese Schallplatten, oben abgebildet (er hat mir den Schnappschuss per E-Mail geschickt, ich bin ihm nicht nach Hause gefolgt), kleiden die W\u00e4nde seines Wohnzimmers aus.",
		"tgt": "These records, pictured above (he emailed me the snap, I didn't follow him home), line his living room walls."
	},
	{
		"src": "Der Grund, warum er eine solch betr\u00e4chtliche Anzahl an Alben und Singles besitzt, ist das Ergebnis seines verf\u00fcgbaren Einkommens: er ist jetzt in der Lage, Platten zu kaufen, die er sich nicht leisten konnte, als sie erschienen und erneut Gegenst\u00e4nde zu kaufen, die er verkaufte, als er jung und pleite war.",
		"tgt": "His reason for acquiring such a vast number of albums and singles is partly a result of his disposable income: he is now able to buy records he couldn't afford when they originally came out, and to repurchase items he sold when he was young and skint."
	},
	{
		"src": "\"Viele Dinge, die ich kaufe, sind aus den sp\u00e4ten 60ern, fr\u00fchen 70ern, die erschienen, als ich 11 oder 12 war. Dinge, bei denen ich vermutlich etwas zu jung war, um sie mir zu kaufen,\" sagt er.",
		"tgt": "\"A lot of the stuff I get is late 60s, early 70s, things that came out when I was 11 or 12, things I was probably a bit too young to get,\" he says."
	},
	{
		"src": "Er stimmt zu, dass diejenigen, die Platten kaufen, eher introvertiert sind und gerne alleine Zeit verbringen, und f\u00fcgt hinzu: \"Ich rauche nicht und ich trinke nicht sehr viel.",
		"tgt": "He agrees that those who purchase records are more likely to be introverts who like their own company, adding: \"I don't smoke, I don't drink very much."
	},
	{
		"src": "Das ist mein Laster.",
		"tgt": "It's my vice."
	},
	{
		"src": "Wez, 25, der bei Sister Ray arbeitet, glaubt auch, dass viele Kunden, die er trifft, auf das YouGov-Profil zutreffen.",
		"tgt": "Wez, 25, who works at Sister Ray, also believes that many of the customers he encounters fit the YouGov profile."
	},
	{
		"src": "Er hat allerdings auch eine neue Welle an Leuten bemerkt, die von dem Medienhpe beeinflusst werden, Leute, die \u00fcber das Comeback geh\u00f6rt haben und sich veranlasst sehen, wieder ihre alten Platten zu kaufen.",
		"tgt": "He has, however, noticed a new wave of people influenced by the media hype, people who heard about the comeback and felt compelled to buy back their old records."
	},
	{
		"src": "Von den Gespr\u00e4chen, die ich gef\u00fchrt habe, haben sich Leute in der Regel so um 1998 oder 1999 ihrer Sammlung entledigt.",
		"tgt": "From conversations I've had, people have got rid of their collection, normally around 1998 or 1999."
	},
	{
		"src": "Kunden, die einst ihre Platten verkauften, um sich CDs zu kaufen, verkaufen jetzt ihre CDs, um sich wieder ihre Platten zu kaufen,\" sagt er.",
		"tgt": "Customers who once sold their vinyl to buy CDs are now selling their CDs to buy their records back,\" he says."
	},
	{
		"src": "Das w\u00fcrde den Boom an Anh\u00e4ngern des Plattenrevivals eines bestimmten Alters erkl\u00e4ren.",
		"tgt": "That may explain a boom in vinyl revivalists of a certain age."
	},
	{
		"src": "Aber was ist mit der angeblichen emotionalen Bedeutung von Platten?",
		"tgt": "But what about the alleged emotional importance of records?"
	},
	{
		"src": "Es dauert nur einige Sekunden in einem Gesch\u00e4ft wie Phonica, um zu erkennen, dass Plattengesch\u00e4fte eine beruhigende Gemeinschaft von Gleichgesinnten bietet.",
		"tgt": "It takes a few seconds in a shop such as Phonica to realise that record stores offer a comforting community of likeminded types."
	},
	{
		"src": "Laut Wez nahmen einige der \u00e4lteren Kunden Ansto\u00df an dem kontaktlosen Zahlungssystem.",
		"tgt": "According to Wez, some older customers have taken umbrage with the contactless payment system in particular."
	},
	{
		"src": "Manche Plattenfans f\u00fchlen sich von der digitalen Welt \u00fcberw\u00e4ltigt und m\u00f6chten sich zur Stabilit\u00e4t von vertrauten Schallplattenh\u00fcllen zur\u00fcckziehen, von Gegenst\u00e4nden, die gl\u00fcckliche Jugenderinnerungen wachrufen.",
		"tgt": "Some vinyl fans may feel overwhelmed by the digital world and choose to retreat to the stability of the familiar record sleeve, of items that recall halcyon teenage memories."
	},
	{
		"src": "\"Ich denke, manchmal kann es das F\u00fcllen einer Leere oder der Besitz materieller Besitzt\u00fcmer als eine Art Trost sein,\" sagt Wez.",
		"tgt": "\"I think sometimes it can be filling a void or having material possessions as some kind of comfort,\" Wez says."
	},
	{
		"src": "Das ist bei mir als Sammler so und ich denke, dass es bei vielen Leuten so ist.",
		"tgt": "As a collector myself, I have that, and I think a lot of people do."
	},
	{
		"src": "Es ist ein einfacher Weg, sich geistig zu besch\u00e4ftigen.",
		"tgt": "It's an easy way to occupy your headspace."
	},
	{
		"src": "\"Wir sind wie ihre Sozialarbeiter!\" fl\u00f6tet ein Mitarbeiter von einem Plattenstapel aus.",
		"tgt": "\"We're like their social workers!\" pipes up a co-worker from a stack of records."
	},
	{
		"src": "Eine Umfrage des ICM im April enth\u00fcllte, dass fast 50 % der Leute, die letzten Monat eine Platte gekauft haben, sie noch nicht angeh\u00f6rt haben.",
		"tgt": "An ICM poll in April revealed that almost 50% of people who bought a vinyl album the previous month had yet to listen to it."
	},
	{
		"src": "Die Umfrage fand auch heraus, dass 41 % einen Plattenspieler besitzen, den sie nie benutzen, w\u00e4hrend 7 % derjenigen, die eine Platte kaufen, keinen Plattenspieler besitzen.",
		"tgt": "The poll also found that 41% have a turntable they never use, while 7% of those who purchase vinyl don't own a record player."
	},
	{
		"src": "Zu diesem Zeitpunkt des Nachrichtenberichts w\u00fcrde ich vermutlich sehr besorgt aussehen, w\u00e4hrend ich durch einen Stapel an Bossa Nova Kompilationen bl\u00e4ttere.",
		"tgt": "At this stage of the news report, I would probably be looking gravely concerned while flicking through a stack of bossa nova compilations."
	},
	{
		"src": "Jonny, 42, der bei Sounds of the Universe (Datenanzahl: drei M\u00e4nner mittleren Alters) arbeitet, hat eine \"Troph\u00e4enaspekt\" des Revivals bemerkt.",
		"tgt": "The \"trophy\" aspect of the revival is something that Jonny, 42, who works in Sounds of the Universe (data count: three midde-aged men) has noticed."
	},
	{
		"src": "\"Jemand kam erst vor kurzem hier rein und sagte: \"Ich besitze keinen Plattenspieler, aber ich w\u00fcrde gerne eine Radiohead Schallplatte kaufen, damit ich sie ins Regal stellen kann,\" sagt er.",
		"tgt": "\"Someone came in recently and said: \"I don't have a record player, but I want to buy a Radiohead record so we can put it on our shelf,\"\" he says."
	},
	{
		"src": "Dies ist kein gro\u00dfer Prozentsatz, aber es passiert definitiv.",
		"tgt": "That's not a large percentage, but it's definitely happening."
	},
	{
		"src": "Mehr produktlastig, weniger musiklastig.",
		"tgt": "More of the product side, less of the music."
	},
	{
		"src": "Wir haben Leute, die sagen: \"Ich habe keinen Plattenspieler.\"",
		"tgt": "We have people saying: \"I don't have a record player.\""
	},
	{
		"src": "Das sind j\u00fcngere Leute, nicht \u00e4ltere, die erst langsam reinkommen.",
		"tgt": "That's younger people, not older ones, late teens who are just getting into it."
	},
	{
		"src": "Fopp, das den Schallplatten fast eine ganze Etage gewidmet hat, hat ein bunteres Publikum, als ich reingehe.",
		"tgt": "Fopp, which now dedicates almost an entire floor to vinyl, has a far more varied audience when I arrive."
	},
	{
		"src": "Es gibt Paare um die 70, Touristen, die Fotos machen, Teenagejungs und Frauen mittleren Alters.",
		"tgt": "There are couples in their 70s, tourists taking photos, teenage boys and middle-aged women."
	},
	{
		"src": "Auch wenn die Atmosph\u00e4re etwas weniger entspannt als in den vorstehend genannten Gesch\u00e4ften ist - Wild Beasts neuester Synthesizer- und sexbepackter Pop anstelle von experimentellem Jazz dr\u00f6hnt aus den Lautsprechern - ist es gut, eine solche Diversit\u00e4t bei den Kunden zu sehen.",
		"tgt": "While the atmosphere is less at ease than the aforementioned stores - Wild Beast's latest synth- and sex-fuelled pop, rather than noodling jazz, is blasting from the speakers - it is good to see diversity in its customers."
	},
	{
		"src": "Keiner von ihnen sieht sonderlich einsam aus, aber nagende psychische Traumata sind schwer feststellbar, wenn man neben jemanden 30 Sekunden lang steht.",
		"tgt": "None of them look particularly lonely, but nagging psychological trauma is hard to ascertain by standing next to someone for 30 seconds."
	},
	{
		"src": "Elanora, 27, l\u00e4uft seit einigen Minuten im Gesch\u00e4ft herum und betrachtet die Variet\u00e4t der zum Verkauf stehenden Platten.",
		"tgt": "Elanora, 27, has been walking around Fopp for a few minutes, looking at the variety of records on sale."
	},
	{
		"src": "Sie macht eher einen Schaufensterbummel als einen Gro\u00dfeinkauf.",
		"tgt": "She is window-shopping, rather than on a spending spree."
	},
	{
		"src": "Sie verdient nicht viel, daher ist das Sammeln von Platten keine wirkliche Option, sagt sie.",
		"tgt": "She doesn't earn a lot, she says, so collecting records isn't really an option."
	},
	{
		"src": "Es kostet viel.",
		"tgt": "It costs a lot."
	},
	{
		"src": "Es ist leicht Musik von einem Computer oder auf andere Art und Weise zu h\u00f6ren, aber die Sch\u00f6nheit von Platten ist...\" sie treibt mit einem verliebten Seufzer ab.",
		"tgt": "It's easy to listen to music by a computer or another way, but the beauty of vinyl is ...\" she drifts off into a lovestruck sigh."
	},
	{
		"src": "Ich wei\u00df nicht, wie ich es erkl\u00e4ren soll - es ist wirklich einzigartig.",
		"tgt": "I don't know how to explain - it's really unique."
	},
	{
		"src": "Mein letzter Halt ist ein Gesch\u00e4ft, von dem gesagt wird, dass eine neue Generation von Plattenliebhabern inspiriert haben soll: Urban Outfitters.",
		"tgt": "My last stop is a shop said to have inspired a fresh generation of vinyl lovers: Urban Outfitters."
	},
	{
		"src": "W\u00e4hrend ich den Anschein gebe, die Jeans-Hotpants zu mustern, beobachte ich eine Gruppe junger Teenagem\u00e4dchen, die sich f\u00fcr einen Moment um Polaroid Kameras gruppieren, bevor eine Vater und seine Tochter sich \u00fcberlegen, einen Crosley Plattenspieler zu kaufen.",
		"tgt": "While giving the illusion of perusing the denim hot pants, I observe a group of teenage girls, who cluster around the Polaroid cameras momentarily, before a dad and his daughter deliberate purchasing a Crosley record player."
	},
	{
		"src": "Zur Linken befindet sich ein Treppenhaus, eine Wand voller Platten von Adele, Jeff Buckley, Amy Winehouse und Fleetwood Mac: eine Mischung von zeitgen\u00f6ssischer Musik und Klassikern, die essentiellen Platten f\u00fcr eine durchschnittliche Sammlung.",
		"tgt": "To the left is a stairwell, a wall of which is stacked with records by Adele, Jeff Buckley, Amy Winehouse and Fleetwood Mac: a mix of contemporary and classics, the essential records for any average collection."
	},
	{
		"src": "Niemand sieht sie sich an - vielleicht, weil sie nur rein dekorativ sind, manche so weit oben, dass es unm\u00f6glich ist, sie anzufassen.",
		"tgt": "Nobody is looking - perhaps because they are merely decoration, some so high up the wall that it would be impossible to touch them."
	},
	{
		"src": "Es ist reine \"Plattenkunst\".",
		"tgt": "It is pure \"art vinyl.\""
	},
	{
		"src": "Aber in Anbetracht dessen, dass jede Attraktion f\u00fcr diese Gegenst\u00e4nde mehr Geld f\u00fcr die Branche bedeuten und einige Kunden in die Tiefen Sohos f\u00fcr mehr schicken k\u00f6nnte, gibt es nichts, um sich zu beschweren.",
		"tgt": "But, given that any attraction to these items could mean more money for the industry and send a few customers into the depths of Soho for more, there is little to complain about."
	},
	{
		"src": "Es ist keine \u00dcberraschung, dass eine Bev\u00f6lkerungsgruppe, die mehr Zeit und Geld als andere hat, auch diejenige ist, die am meisten f\u00fcr Luxusgegenst\u00e4nde wie Platten ausgibt.",
		"tgt": "It is no surprise that a demographic more likely than most to have more time and money than most is also the one that spends the most on luxury items such as vinyl."
	},
	{
		"src": "Auch wenn meine Nachforschungen ergaben, dass die Ergebnisse von YouGov stimmen, lassen sie, zumindest in Plattengesch\u00e4ften in Soho, die gro\u00dfe Anzahl an weiblichen Sammlerinnen und Plattenliebhaberinnen, die in der Realit\u00e4t, Plattengesch\u00e4ften und in Onlineforen existieren, unber\u00fccksichtigt.",
		"tgt": "But while my findings suggest YouGov's results are accurate, in Soho record stores at least, they do not discount the huge number of female collectors and vinyl lovers that exist in reality, in record shops and on online forums."
	},
	{
		"src": "Diese Menschen arbeiten vermutlich hart in der Schule oder in B\u00fcros.",
		"tgt": "These people are probably working hard at school or in offices."
	},
	{
		"src": "Sie verbringen ihren Donnerstag morgen mit Sicherheit nicht mit dem Bummeln durch Plattengesch\u00e4fte der Berwick Street und dem Bl\u00e4ttern durch Platten, w\u00e4hrend sie dem starrenden Blick eines unheimlichen, 30-j\u00e4hrigen falschen Moderator meiden, der \u00fcber die Schultern nichts ahnender M\u00e4nner mittleren Alters aufragt.",
		"tgt": "They are certainly not spending their Thursday mornings loitering around the record shops of Berwick Street, flicking through records and avoiding the gaze of a creepy, 30-year-old fake television presenter who is looming over the shoulders of unsuspecting middle-aged men."
	},
	{
		"src": "Der Gr\u00f6nlandhai ist das am l\u00e4ngsten lebende Wirbeltier - Videobericht",
		"tgt": "Greenland shark is longest-living vertebrate animal - video report"
	},
	{
		"src": "Wissenschaftlicher sagen, dass der Gr\u00f6nlandhai die l\u00e4ngste Lebensspanne von allen Wirbeltieren auf dem Planeten hat.",
		"tgt": "Scientists say the Greenland shark has the longest lifespan of any vertebrate on the planet."
	},
	{
		"src": "Julius Nielsen, der Haie untersucht, sagt, dass der Rekord bei einem Weibchen lag, von dem ausgegangen wird, dass es zwischen 272 und 512 Jahre alt und f\u00fcnf Meter lang ist",
		"tgt": "Julius Nielsen, who has been studying the sharks, says record goes to a female thought to be between 272 and 512 years old and is five metres in length"
	},
	{
		"src": "Franz\u00f6sisches Gericht lehnt Angebot \u00fcber Abriss von Gesch\u00e4ften im Dschungel Fl\u00fcchtlingslager ab",
		"tgt": "French court rejects bid to demolish shops at Jungle refugee camp"
	},
	{
		"src": "Ein franz\u00f6sisches Gericht hat ein Angebot der Beh\u00f6rden in Calais abgelehnt, Dutzende von provisorischen Gesch\u00e4ften und Restaurants im Dschungel von Calais, in dem Tausende von Fl\u00fcchtlingen leben, niederzureissen.",
		"tgt": "A French court has rejected a bid by Calais authorities to demolish dozens of makeshift shops and restaurants in the Jungle camp where thousands of refugees are living."
	},
	{
		"src": "Bei einer Gerichtsverhandlung diese Woche argumentierten die Beh\u00f6rden in Calais, dass der Staat befugt sein sollte, 72 provisorische Gesch\u00e4fte niederzurei\u00dfen, in denen Personen innerhalb des Lagers Waren, von Zigaretten bis Energydrinks, verkaufen, Friseurdienstleistungen anbieten oder Tee f\u00fcr 50 Cent (40 Pence) oder einfache Mahlzeiten f\u00fcr ein paar Euro in provisorischen Restaurants verkaufen.",
		"tgt": "At a court hearing this week, Calais authorities had argued the state should be able to knock down a total of 72 makeshift shops where people inside the camp sell goods, from cigarettes to energy drinks, offer haircuts, or sell tea for 50 cents (40p) or basic meals for a few euros in makeshift restaurants."
	},
	{
		"src": "Die Pr\u00e4fektur Calais argumentierte, dass diese Orte niedergerissen werden sollten, weil sie eine parallele Wirtschaft darstellen w\u00fcrden, aus der keine Steuern gezahlt werden w\u00fcrden und die ein Feuer- und Sanit\u00e4tsrisiko bergen.",
		"tgt": "The Calais prefect's office argued the places should be demolished because they represented a parallel economy that did not pay tax, and because they carried fire and sanitation risks."
	},
	{
		"src": "Humanit\u00e4re Gruppen teilten dem Gericht mit, dass die Gesch\u00e4fte und Restaurants wichtig seien, da die kostenlosen Mahlzeiten, die von der staatlich unterst\u00fctzten Vereinigung und anderen Gruppen angeboten werden, nicht gen\u00fcgend Lebensmittel f\u00fcr die wachsenden Zahlen im Lager bieten w\u00fcrden.",
		"tgt": "Humanitarian groups had told the court the shops and restaurants were vital, saying the free meals offered by a state-backed association and other groups did not provide enough food for the growing numbers at the camp."
	},
	{
		"src": "Sie f\u00fchrten dar\u00fcber hinaus aus, dass die provisorischen Gesch\u00e4fte und Restaurants oft Unterkunft und kostenlose Mahlzeiten f\u00fcr Leute in Not bieten w\u00fcrden.",
		"tgt": "They argued the makeshift shops and restaurants often provided shelter and free meals to those in need."
	},
	{
		"src": "Ein Gericht in Lille entschied, dass es keine rechtliche Grundlage f\u00fcr die Ausweisung von Leuten g\u00e4be, die die 72 provisorischen Gesch\u00e4fte betreiben, aber r\u00e4umte ein, dass die Bedenken der Pr\u00e4fektur von Calais \"absolut nachvollziehbar seien.\"",
		"tgt": "A Lille court ruled there was no legal basis for expelling the people running the 72 makeshift shops, but said the Calais prefect's concerns \"were totally understandable.\""
	},
	{
		"src": "Der Richter Jean-Fran\u00e7ois Molla sagte, dass die Lebensmittelgesch\u00e4fte, Caf\u00e9s und Restaurants eine viel gr\u00f6\u00dfere Rolle spielen w\u00fcrden, als lediglich Leute zu ern\u00e4hren, die \"in extrem prek\u00e4ren Bedingungen leben.\"",
		"tgt": "The judge, Jean-Fran\u00e7ois Molla, said the groceries, cafes and restaurants played a much bigger role than simply feeding people that \"live in extremely precarious conditions.\""
	},
	{
		"src": "Er sagte, dass die Bereiche ruhige Treffpunkte zwischen Fl\u00fcchtlingen und Freiwilligen bieten.",
		"tgt": "He said the spaces provided calm meeting points between refugees and volunteers."
	},
	{
		"src": "Eine der Orte, der von dem Niederreissen bedroht war, war das Jungle Book Kids' Caf\u00e9 des Lagers, das gemeinnn\u00fctzig betrieben wird und 200 Mahlzeiten am Tag, Englisch- und Franz\u00f6sischklassen sowie eine Beratung zu Asylsachen f\u00fcr die Hunderte von schutzbed\u00fcrftigen, unbegleiteten Minderj\u00e4hrigen im Lager bietet.",
		"tgt": "One of the places that had been under threat from demolition was the camp's Jungle Book Kids\" Cafe which is run not-for-profit and provides 200 meals a day, English and French classes, and asylum advice for the hundreds of vulnerable unaccompanied minors in the camp."
	},
	{
		"src": "Mehr als 170.000 Menschen haben die Petition unterzeichnet, um das Kids' Caf\u00e9 zu wahren.",
		"tgt": "More than 170,000 people have signed a petition to protect the kids\" cafe."
	},
	{
		"src": "In einem Brief an den Guardian hie\u00df es, dass die Schlie\u00dfung \"f\u00fcr diese Kinder einer Katastrophe w\u00e4re, von denen die j\u00fcngsten acht Jahre alt sind.\"",
		"tgt": "A letter sent to the Guardian said its closure \"would be a catastrophe for these children, some of whom are as young as eight.\""
	},
	{
		"src": "Die zwei Hilfsorganisationen Help Refugees und L'Auberge des Migrants sch\u00e4tzten am Freitag, dass die Zahl der im Dschungellager Lebenden auf \u00fcber 9.000 Leute angestiegen sei - der h\u00f6chsten Zahl bis jetzt - nach einer steilen Zunahme von Neuank\u00f6mmlingen im Laufe des Sommers.",
		"tgt": "Two charities, Help Refugees and L'Auberge des Migrants, on Friday estimated that numbers in the Jungle camp have risen to over 9,000 people - the highest ever - after a steep increase in arrivals during the summer."
	},
	{
		"src": "Trotz Olympia-Entt\u00e4uschung: Martin bleibt k\u00e4mpferisch",
		"tgt": "Despite Olympic disappointment, Martin keeps his fighting spirit"
	},
	{
		"src": "Trotz seines entt\u00e4uschenden Auftritts im olympischen Zeitfahren will sich Radprofi Tony Martin nicht unterkriegen lassen.",
		"tgt": "Despite his disappointing performance in the Olympic time trial, cycling professional Tony Martin will keep his chin up."
	},
	{
		"src": "\"Ich behalte weiter die WM im Blick, bleibe zuversichtlich und k\u00e4mpfe weiter\", schrieb der 31-J\u00e4hrige am Donnerstag vor seiner Abreise aus Rio de Janeiro bei Facebook.",
		"tgt": "\"I'm going to keep the World Championship in my sights, stay optimistic, and keep fighting,\" wrote the 31-year-old on Facebook on Thursday ahead of his journey home from Rio."
	},
	{
		"src": "Eine Erkl\u00e4rung f\u00fcr seinen miserablen zw\u00f6lften Platz am Zuckerhut hat er nicht.",
		"tgt": "He was unable to provide an explanation for his poor finish in 12th place on Sugar Loaf Mountain."
	},
	{
		"src": "\"Mir f\u00e4llt es ehrlich gesagt schwer, das Zeitfahren von gestern zu kommentieren\", meinte Martin.",
		"tgt": "\"It's honestly hard for me to comment on my time from yesterday,\" said Martin."
	},
	{
		"src": "Er m\u00fcsse in Ruhe analysieren, welche Gr\u00fcnde zum Debakel gef\u00fchrt h\u00e4tten.",
		"tgt": "He said he needed to reflect and analyse the reasons behind the debacle."
	},
	{
		"src": "Bei der Zeitfahr-WM im Oktober in Katar wollte Martin eigentlich um den Titel mitk\u00e4mpfen.",
		"tgt": "Martin had wanted to compete for the title at the time trial World Championship in Qatar in October."
	},
	{
		"src": "\"Ich werde mir alles genau anschauen, was wir in der letzten Zeit ver\u00e4ndert haben.\"",
		"tgt": "\"I'm going to take a real look at everything we've changed recently.\""
	},
	{
		"src": "\"Dazu z\u00e4hlt auch meine Position\", schrieb der dreimalige Zeitfahr-Weltmeister, der am Mittwoch auf den 54,5 km mehr als drei Minuten auf Olympiasieger Fabian Cancellara (Schweiz) verloren hatte.",
		"tgt": "\"This also includes my position,\" wrote the three-time time trial World Champion, who had lost to Olympic gold medallist Fabian Cancellara (Switzerland) by more than three minutes over the course of the 54.5km race on Wednesday."
	},
	{
		"src": "Olympia: Tennisprofi Siegemund verpasst Halbfinale",
		"tgt": "Olympics: Tennis pro Siegemund misses out on the semi-final"
	},
	{
		"src": "Der Siegeszug von Laura Siegemund endete im Viertelfinale von Rio: Die Weltranglisten-32. aus Metzingen verpasste durch ein 1:6, 1:6 gegen Monica Puig (Puerto Rico/WTA-Nr.",
		"tgt": "Laura Siegemund's reign of success comes to an end in the Rio quarter-final: Ranked 32 in the world, the player from Metzingen will definitely miss out on the semi-final of the Olympic tennis tournament after losing 1:6, 1:6 against Monic Puig (Puerto Rico/WTA no."
	},
	{
		"src": "34) das Halbfinale des olympischen Tennisturniers deutlich.",
		"tgt": "34)."
	},
	{
		"src": "Siegemund, die von R\u00fcckenproblemen geplagt wurde, konnte ihren Aufschlag nur einmal durchbringen und wirkte im Vergleich zu den vorherigen Runden kraftlos.",
		"tgt": "Sigemund, who has been struggling with back problems, was only able to hold her serve once, and seemed powerless in comparison to earlier rounds."
	},
	{
		"src": "Am Donnerstag hatte noch Medaillenhoffnung Angelique Kerber (Kiel/Nr. 2) die Chance auf den Sprung in die Vorschlussrunde.",
		"tgt": "On Thursday, potential medallist Angelique Kerber (Kiel/no. 2) had the chance of making the semi-final."
	},
	{
		"src": "Die Australian-Open-Gewinnerin traf auf die Britin Johanna Konta (Nr. 10).",
		"tgt": "The winner of the Australian Open faced off against Brit Johanna Konta (no. 10)."
	},
	{
		"src": "Als letzter deutscher Tennisprofi hatte Tommy Haas 2000 in Sydney eine Medaille (Silber) geholt.",
		"tgt": "The last German tennis player to win was Tommy Haas, who took the silver medal in Sydney in 2000."
	},
	{
		"src": "Zwei deutsche DTB-Starter im Viertelfinale von Sommerspielen hatte es zuletzt 1992 gegeben.",
		"tgt": "The last time there were two German tennis players in the quarter-finals of the summer games was in 1992."
	},
	{
		"src": "Noch nie stand ein deutsches Duo in einem olympischen Einzel-Halbfinale.",
		"tgt": "There has never been a German-German Olympic semi-final."
	},
	{
		"src": "Konzern steigt bei Start-up f\u00fcr Live-Videospiel\u00fcbertragungen ein",
		"tgt": "Company gets involved in start-up for live video game streaming"
	},
	{
		"src": "Anderen Leute beim Spielen von Videospielen zuzuschauen, ist ein Riesentrend - davon will auch Microsoft profitieren.",
		"tgt": "Watching other people play video games is a huge trend - and Microsoft wants to profit from this too."
	},
	{
		"src": "Der Technologiekonzern kauft das Start-up Beam, das sich auf dieses Hobby spezialisiert hat.",
		"tgt": "The technology company has purchased start-up Beam, which has specialised in this hobby."
	},
	{
		"src": "Wie viel Geld f\u00fcr die \u00dcbernahme flie\u00dft, teilte Microsoft am Donnerstag nicht mit.",
		"tgt": "On Thursday Microsoft did not announce how much many had been spent on the takeover."
	},
	{
		"src": "Beam ging mit seinem Angebot erst im Januar an den Start und hat bereits mehr als 100.000 Nutzer.",
		"tgt": "Beam launched its programme in January, and already has more than 100,000 users."
	},
	{
		"src": "Sie k\u00f6nnen anderen beim Spielen zuschauen, aber auch selbst eingreifen.",
		"tgt": "They can watch other people play, and also get involved themselves."
	},
	{
		"src": "Zum Beispiel k\u00f6nnen sie den Spielern Missionen aufgeben und Feinde gegen\u00fcberstellen sowie Ausr\u00fcstungsgegenst\u00e4nde bereitstellen.",
		"tgt": "For example, they can give players missions to complete and confront enemies, and provide equipment."
	},
	{
		"src": "Der Spieleriese Activision Blizzard startet einen neuen HD-Videodienst f\u00fcr die boomende Welt des E-Sports.",
		"tgt": "Games giant Activision Blizzard is launching a new HD video service for the booming world of e-sports."
	},
	{
		"src": "Auf dem Weg zum globalen Medienereignis soll Facebook helfen.",
		"tgt": "Facebook is to help on the path to making them global media events."
	},
	{
		"src": "Die Werbeindustrie horcht bereits auf.",
		"tgt": "The advertising industry has already pricked up its ears."
	},
	{
		"src": "Die Mitarbeiter des Start-ups, das seinen Sitz bisher in Seattle im US-Bundesstaat Washington hat, ziehen zum Microsoft Hauptsitz im kalifornischen Redmond um, wie Beam-Mitgr\u00fcnder und -Chef Matt Salsamendi mitteilte.",
		"tgt": "The start-up's employees, who were previously based in Seattle in the US state of Washington, will now move to Microsoft's headquarters in California's Redmond, Beam's co-founder and CEO Matt Salsamendi reported."
	},
	{
		"src": "F\u00fcr die Kunden soll sich demnach durch die \u00dcbernahme nichts \u00e4ndern.",
		"tgt": "The takeover will not change anything for customers."
	},
	{
		"src": "Beam wird laut Microsoft in die Videospielabteilung rund um die Xbox-Konsole integriert.",
		"tgt": "According to Microsoft, Beam will be integrated into the video games department that is linked to the Xbox console."
	},
	{
		"src": "Der Markt des Live-Streamings von Videospielaktivit\u00e4ten w\u00e4chst derzeit rasant.",
		"tgt": "The market for live-streaming video games is currently growing rapidly."
	},
	{
		"src": "Bekannte Plattformen sind Twitch und YouTube Gaming.",
		"tgt": "Well-known platforms include Twitch and YouTube Gaming."
	},
	{
		"src": "Twitch war im Jahr 2014 vom Onlineh\u00e4ndler Amazon gekauft wurden - f\u00fcr fast eine Milliarde Dollar.",
		"tgt": "In 2014 Twitch was purchased by online retailer Amazon - for almost one billion dollars."
	},
	{
		"src": "YouTube Gaming geh\u00f6rt zur Google-Mutter Alphabet.",
		"tgt": "YouTube Gaming is owned by Google's parent company Alphabet."
	},
	{
		"src": "Hier kommt der Enforcement Trailer",
		"tgt": "Here comes the enforcement trailer"
	},
	{
		"src": "Deutschlands Raser m\u00fcssen sich auf die n\u00e4chste Generation Geschwindigkeitsmesser einstellen: In verschiedenen Bundesl\u00e4ndern, unter anderem in Hessen und Brandenburg, werden neue Blitzger\u00e4te getestet, die Tempos\u00fcnder besonders effektiv \u00fcberf\u00fchren sollen.",
		"tgt": "Germany's speeders will have to get used to the new generation of speedometers: In various federal states, including Hesse and Brandenburg, new speed cameras are being trialled, which are supposed to be particularly effective at catching those who drive too fast."
	},
	{
		"src": "Die futuristisch wirkenden Enforcement Trailer der Firma Vitronic aus Wiesbaden k\u00f6nnen zum Beispiel an Unfallschwerpunkten eingesetzt werden, wo es f\u00fcr eine mobile Messung durch die Polizei zu gef\u00e4hrlich w\u00e4re.",
		"tgt": "The futuristic-looking enforcement trailer made by Vitronic, a company form Wiesbaden, could be used at accident blackspots, for example, where it is too dangerous for the police to go."
	},
	{
		"src": "Beispielsweise an Autobahn-Baustellen oder zu sanierenden Br\u00fccken mit vor\u00fcbergehendem Tempolimit gibt es oft keine n\u00f6tige Infrastruktur, um dort mit einem station\u00e4ren Blitzer f\u00fcr die Einhaltung der Geschwindigkeitsbegrenzung zu sorgen.",
		"tgt": "For example, roadworks on a motorway, or a bridge that is due to be repaired, and therefore has a temporary speed limit often lack the infrastructure to support a fixed speed camera to ensure that speed limits are being adhered to."
	},
	{
		"src": "Ein dauerhafter mobiler Aufbau kann aber zu gef\u00e4hrlich oder aufwendig sein.",
		"tgt": "It can also be too dangerous or expensive to keep assembling and unassembling the speed camera at these points."
	},
	{
		"src": "Der Enforcement Trailer ist autark: Sein Akku h\u00e4lt bei ununterbrochenem Messbetrieb f\u00fcnf Tage, die Falldaten werden verschl\u00fcsselt \u00fcber ein Modem \u00fcbertragen.",
		"tgt": "The enforcement trailer is autonomous: its battery lasts for five days of continuous measurement, and data is transferred in encrypted form via a modem."
	},
	{
		"src": "Mit Laser-Messtechnik k\u00f6nnen zudem alle Fahrzeuge \u00fcber mehrere Spuren hinweg gleichzeitig erfasst werden.",
		"tgt": "Thanks to laser measuring technology, all vehicles across several lanes can be tracked at the same time."
	},
	{
		"src": "Variable Geschwindigkeitsbegrenzungen sowie Durchfahrtsverbote nach Uhrzeit, Fahrstreifen und Fahrzeugklasse lassen sich ebenfalls \u00fcberwachen.",
		"tgt": "Variable speed limits and driving bans based on time, lane or vehicle type can also be monitored."
	},
	{
		"src": "Im hochgefahrenen Zustand bewegen kann man den Anh\u00e4nger laut Hersteller mit jedem Auto mit Anh\u00e4ngerkupplung.",
		"tgt": "When powered up, the manufacturer says that any car with a trailer coupling can move the trailer."
	},
	{
		"src": "Damit er nicht einfach geklaut wird, ist er im Messbetrieb abgesenkt, so dass die R\u00e4der in der gepanzerten und \u00fcbrigens auch schusssicheren Au\u00dfenh\u00fclle verschwinden.",
		"tgt": "To prevent it from simply being stolen, it sinks down when measuring, making its wheels disappear into the armoured, bullet-proof exterior."
	},
	{
		"src": "Au\u00dferdem soll eine eingebaute Alarmanlage den Blitzer vor Vandalismus sch\u00fctzen.",
		"tgt": "In addition, the speed camera's in-built alarm system is designed to protect it from vandalism."
	},
	{
		"src": "Seit 2015 wird der Trailer nach Angaben von Vitronic in verschiedenen Bundesl\u00e4ndern getestet und mittlerweile auch eingesetzt.",
		"tgt": "Since 2015, according to Vitronic, the trailer has been tested in various federal states and is now also used in them."
	},
	{
		"src": "Auch ausl\u00e4ndische Beh\u00f6rden blitzen mit der neuen Technik: J\u00fcngst hat Frankreich 100 St\u00fcck nachgeordert, nach einer Bestellung von 150 St\u00fcck im vergangenen Jahr.",
		"tgt": "Foreign authorities are also using the new technology for speed cameras: recently France ordered 100 of them, after ordering 150 the year before."
	},
	{
		"src": "Gro\u00dfbritannien holt Silber im 7-er Rugby, nachdem Fiji Masterclass Gold holt",
		"tgt": "Britain settle for silver in rugby sevens after Fiji masterclass sees them take gold"
	},
	{
		"src": "Die beeindruckende Leistung Gro\u00dfbritanniens beim 7-er Rugby kam im Finale am Donnerstag abend zu einem abrupten Halt bei der letzten H\u00fcrde in Form der Fijis, als sie mit einem Ergebnis von 43-7 im Deodoro Stadium hier in Rio geschlagen wurden.",
		"tgt": "Great Britain's impressive run in the Rugby 7s was brought to a crashing halt at the final hurdle by Fiji in the final on Thursday night when they were comprehensively beaten 43-7 at the Deodoro Stadium here in Rio."
	},
	{
		"src": "Fiji erteilte eine Meisterklasse im Handling, Side-Stepping, Nachr\u00fccken, Linienlauf und roher Kraft, um Gold zu gewinnen - ihre erste Olympiamedaille jeglicher Farbe.",
		"tgt": "Fiji gave a masterclass in handling, off-loading, side-stepping, support play, running lines and brute strength to win gold - their first Olympic medal of any colour."
	},
	{
		"src": "Die Niederlage wurde durch den nicht allzu schlechten Trostpreis der Silbermedaille vers\u00fc\u00dft - Gro\u00dfbritanniens vierte an diesem Tag - und sie konnten auf ihre Bem\u00fchungen in diesem Turnier durchaus stolz sein, in dem sie Neuseeland, Argentinien und S\u00fcdafrika schlugen.",
		"tgt": "Defeat came with the non-too shabby consolation of silver - Britain's third of the day - and they could be proud of their efforts in the inaugural Olympic 7s tournament in which they beat New Zealand, Argentina and South Africa along the way."
	},
	{
		"src": "Die deutliche Niederlage der Boks, 7-5 im Halbfinale am selben Tag k\u00f6nnte auf sie im Finale zur\u00fcckfallen.",
		"tgt": "The bruising beating of the Boks, 7-5 in the semi-final earlier in the day, may have come back to bite them in the final."
	},
	{
		"src": "Aber unabh\u00e4ngig davon h\u00e4tte Fiji bei dieser Form ein 15-Mann-Team in Bestform geschlagen.",
		"tgt": "But, regardless, Fiji on this form would have beaten a fit as a fiddle 15-man team."
	},
	{
		"src": "Es k\u00f6nnte f\u00fcr GB ein Trost sein - aber wird es wahrscheinlich nicht - dass zumindest ein Brite morgen eine Goldmedaille um seinen Hals h\u00e4ngen haben wird: Fijis Cheftrainer Ben Ryan, der ehemalige Chef f\u00fcr England aus Wimbledon.",
		"tgt": "It may be some consolation to GB - but probably not - that at least one Briton will have a gold medal around his neck tomorrow: Fiji's head coach is Ben Ryan, the former England boss from Wimbledon."
	},
	{
		"src": "GB hatte einen schwierigen Weg hinter sich.",
		"tgt": "It has been some journey for GB."
	},
	{
		"src": "Vor acht Jahren verloren sie unter Ryan jedes Spiel bei den Adelaide Sevens.",
		"tgt": "Eight years ago, under Ryan, they lost every game at the Adelaide Sevens."
	},
	{
		"src": "Hier verloren sie nur eins.",
		"tgt": "Here, they lost just one."
	},
	{
		"src": "Diese Schlappe wird wehtun, aber der Fortschritt ist erstaunlich.",
		"tgt": "This hammering will hurt but the progress is startling."
	},
	{
		"src": "Fiji begann wundervoll und lie\u00df die Angriffe GBs aus Spass abprallen.",
		"tgt": "Fiji started magnificently, bouncing off GB tackles for fun."
	},
	{
		"src": "Es f\u00fchlte sich f\u00fcr den Kapit\u00e4n Tom Mitchell an und Co. an, als w\u00fcrde man in fahrende Busse laufen. Die World Series-Gewinner gingen 5-0 nach oben, als Osea Kolinisau in der Ecke r\u00fcberhechtete.",
		"tgt": "It was like running into a series of moving buses for captain Tom Mitchell and co and the World Series champions went 5-0 up when Osea Kolinisau dived over in the corner."
	},
	{
		"src": "Mit noch vier Minuten Spielzeit f\u00fcgte Jerry Tuwai noch einen weiteren Angriff aus der rechten Ecke aus, den er umwandelte.",
		"tgt": "With four minutes on the clock Jerry Tuwai added another down the right wing, which was converted."
	},
	{
		"src": "12-0 und GB hat kaum den Ball angefasst.",
		"tgt": "12-0 and GB had hardly touched the ball."
	},
	{
		"src": "Ein hevorragender Tackle von Mitchell stoppte den Berg von Mann Leone Nakarawa ein drittes Tor zu erzielen, aber es hat Fiji nur aufgehalten.",
		"tgt": "A superb Mitchell tackle stopped the man-mountain Leone Nakarawa from scoring a third but it was only delaying Fiji."
	},
	{
		"src": "In der siebten Minute lete Jasa Veremalua in der rechten Ecke einen Touchdown hin und es stand 0-17 f\u00fcr GB.",
		"tgt": "On seven minutes Jasa Veremalua touched down in the right corner and GB were 17-0 to the bad."
	},
	{
		"src": "Nakarawa f\u00fcgte einen neuen seit dem Wiederanpfiff hinzu und es gab noch immer \u00fcber eine Minute Spielzeit ... in der ersten H\u00e4lfte.",
		"tgt": "Nakarawa added another from the restart and there was still over a minute on the clock ... in the first half."
	},
	{
		"src": "Vatemo Ravouvou preschte durch weitere schwache Tacklings des GB Teams und st\u00fcrmte bis zur Linie, um ein Tor zu machen.",
		"tgt": "Vatemo Ravouvou then burst through some more limp GB tackling and stormed to the line to score."
	},
	{
		"src": "Die Umwandlung brachte ein 29-0 bis zur Pause.",
		"tgt": "The conversion made it 29-0 at the break."
	},
	{
		"src": "Es ist so, als w\u00e4re Fiji dazu geboren wurde, die 7 zu spielen, w\u00e4hrend GB noch immer dazulernt.",
		"tgt": "It was as if Fiji had been born to play 7s, while GB are still learning the trade."
	},
	{
		"src": "So ist es auch.",
		"tgt": "Which is pretty much how it is."
	},
	{
		"src": "GB f\u00fchrte grundlegende \u00c4nderungen zur Halbzeit durch und schloss die fijianische L\u00fccke...f\u00fcr ganze vier Minuten, was f\u00fcr die Verh\u00e4ltnisse der ersten Halbzeit gut war, bis Josua Tuisova nach einem brillianten Zwischenplay von Fiji durchlief.",
		"tgt": "GB made wholesale changes at half-time and they plugged the Fijian dam...for all of four minutes, which by first-half standards was good, until Josua Tuisova went over after some brilliant Fijian interplay."
	},
	{
		"src": "Dan Norton startete einen Versuch f\u00fcr GB, machte einen Touchdown in der linken Ecke f\u00fcr ein 36-7, aber das Spiel verlief schon lange zugunsten der S\u00fcdseeinsulaner, dessen Fans sangen, Fahnen schwenkten und tanzten auf der Trib\u00fcne.",
		"tgt": "Dan Norton grabbed a try for GB, touching down in the left corner to make it 36-7 but the game was long gone the way of the South Sea Islanders whose fans sang, waved flags and danced in the stands."
	},
	{
		"src": "Es war nicht schwer den spielerischen Ansatz Fijis zu bewundern.",
		"tgt": "It was hard not to admire Fiji's whole joyful approach."
	},
	{
		"src": "Mata Viliame setzte das i-T\u00fcpfelchen mit einem weiteren Versuch in den letzten Sekunden.",
		"tgt": "Mata Viliame iced the Fijian cake that didn't need icing with another try in the dying moments."
	},
	{
		"src": "Der Pfiff ert\u00f6nte, die Fijis umarmten sich und GB kickte vernichtend geschlagen in den Rasen.",
		"tgt": "The whistle went, the Fijians embraced and GB hit the turf, thoroughly beaten."
	},
	{
		"src": "Fr\u00fcher an dem Tage hatte Fiji Japan im Halbfinale mit 20-5 besiegt und Gro\u00dfbritannien dr\u00e4ngte S\u00fcdafrika in einem knappen Halbfinalmatch aus dem Rennen - Gro\u00dfbritanniens Umwandlung der Differenz.",
		"tgt": "Earlier in the day, Fiji had beaten Japan 20-5 in their semi-final and GB edged South Africa in a tight semi-final of one try each - Britain's conversion the difference."
	},
	{
		"src": "Kyle Brown brachte die Boks in der ersten H\u00e4lfte nach vorne, aber Dan Norton durchbrach die Linie mit einer beeindruckenden Fu\u00dfarbeit und erzielte ein Tor unter den Posten in der zweiten H\u00e4lfte.",
		"tgt": "Kyle Brown put the Boks ahead in the first half but Dan Norton with some dazzling footwork broke the line and scored under the posts in the second half."
	},
	{
		"src": "Ein brilliantes sp\u00e4tes Tackling von Marcus Watson, dem Bruder von Anthony des englischen 15-Aside Teams, sicherte den Gewinn - und damit die Silbermedaille.",
		"tgt": "A brilliant late tackle from Marcus Watson, brother of England's 15-aside team, Anthony, secured the win - and ultimately the silver medal."
	},
	{
		"src": "Helen Glover und Heather Stanning durch Kampf mit dem Krebs des Trainers zum Rudersieg inspiriert",
		"tgt": "Helen Glover and Heather Stanning inspired to rowing victory by coach's cancer battle"
	},
	{
		"src": "Es wird kein emotinaleres Gold als bei diesen Spielen geben und das will was hei\u00dfen.",
		"tgt": "There will not be a more emotive gold at these games, and that is saying something."
	},
	{
		"src": "Vom ersten Ruderschlag bis zum letzten, 220 harte Hieve, die in die Geschichte eingehen, Helen Glover und Heather Stanning fanden eine zus\u00e4tzliche Bedeutung in ihrem goldenem Moment am Estacio da Lagoa.",
		"tgt": "From the first stroke to the last, 220 punishing heaves into history, Helen Glover and Heather Stanning found added meaning in their golden moment at the Estacio da Lagoa."
	},
	{
		"src": "Auch wenn es nur die Beiden waren, die am Ruder sa\u00dfen, gab es drei Stimmen im Boot. Das Echo des Trainers Robin Williams, war allanwesend als sie zum zweiten Olympiagold im Zweier ohne Steuerfrau in Folge ruderten, die ersten Frauen in der Geschichte des britischen Sports, die einen solchen Ma\u00dfstab legten.",
		"tgt": "Though they were the two pulling on the oars, there were three voices in that boat, the echo of coach Robin Williams ever present as they powered to a second successive Olympic gold in the women's pairs, the first females in the annals of British sport to scale such a height."
	},
	{
		"src": "Ihre Dominanz war absolut, immerhin ihr 39.ter ungeschlagener Einsatz, der ebenfalls beispiellos ist.",
		"tgt": "Their dominance was absolute, after all this was their 39th outing unbeaten, again unprecedented."
	},
	{
		"src": "Was wir sehen sind zwei brilliante Athletinnen, die \u00fcber die Oberfl\u00e4che mit der Eleganz von Schw\u00e4nen gleiten, was nicht die Art des Triumphes zu G\u00e4nze widerspiegelt.",
		"tgt": "What we see, two brilliant athletes skating over the surface with the elegance of swans, does not wholly reflect the nature of the triumph."
	},
	{
		"src": "Hinter jedem Gold im Rudern steckt ein Bataillon an willigen Helfern, die zu den inkrementellen Fortschritten beitragen, die den Unterschied ausmachen und es war niemand behilflicher als der Trainer, der vor 30 Monaten nicht wusste, ob er diesen Tag \u00fcberhaupt \u00fcberleben w\u00fcrde, als bei ihm Krebs diagnostiziert wurde.",
		"tgt": "Behind every rowing gold is a battalion of willing hands contributing the incremental gains that make the difference, and no hands were more instrumental than those of a coach who 30 months ago did not know whether he would live to see this day when diagnosed with cancer."
	},
	{
		"src": "Wie er sagte, er was riskant.",
		"tgt": "As he said, it was touch and go."
	},
	{
		"src": "Ich hatte Blasenkrebs, der operierbar ist und das taten sie.",
		"tgt": "I had bladder cancer which is one of the things they can operate on and they did."
	},
	{
		"src": "Wenn Sie das nicht tun, breitet er sich \u00fcberall aus.",
		"tgt": "If they don't it goes everywhere."
	},
	{
		"src": "Es w\u00e4re ein ziemlich schlimme Situation gewesen.",
		"tgt": "It would have been a pretty bad situation."
	},
	{
		"src": "Es ver\u00e4ndert ein wenig den Ausblick.",
		"tgt": "It alters your outlook a bit."
	},
	{
		"src": "Williams wurde im Dezember 2013 diagnostiziert.",
		"tgt": "Williams was diagnosed in December 2013."
	},
	{
		"src": "Das Trio hatte Gl\u00fcck, dass er seien Behandlung Anfang 2014, au\u00dferhalb der Saison, beginnen konnte, was die Unterbrechung auf ein Minimum hielt, falls das unter solchen Umst\u00e4nden \u00fcberhaupt der richtige Begriff ist.",
		"tgt": "The trio were fortunate that he was able to begin his treatment at the start of 2014 out of season, keeping the disruption to a minimum, if that is ever the right expression in circumstances such as these."
	},
	{
		"src": "Ich ben\u00f6tigte Geld, daher musste es mir bald wieder besser gehen.",
		"tgt": "I needed to get paid so I had to get better quickly."
	},
	{
		"src": "Es war ein Anreiz.",
		"tgt": "It was an incentive."
	},
	{
		"src": "Ich war im Krankenhaus und lief auf der Station herum - 20 Fu\u00df, 30 Fu\u00df, 50 Fu\u00df zu einer Zeit, als sie sagten, dass einige Schritte gen\u00fcgen w\u00fcrden.",
		"tgt": "I was in hospital and I was walking around the ward - 20ft, 30ft 50ft at a time when they were saying a few steps is enough."
	},
	{
		"src": "So beginnt es.",
		"tgt": "That's how it starts off."
	},
	{
		"src": "Das Rudern an sich ist schon eine Herausforderung, aber das macht es zu einer noch gr\u00f6\u00dferen.",
		"tgt": "Rowing in itself is a journey but that makes it a bit bigger."
	},
	{
		"src": "In der Unmittelbarkeit des Sieges gingen ihre ersten Gedanken an Williams, der einen nervenaufreibenden Morgen damit verbrachte etwas mehr als sonst zu reden und damit versuchte, seine eigenen \u00c4ngste zu verarbeiten.",
		"tgt": "In the immediacy of victory their first thoughts were for Williams, who had spent a nervy morning talking a little more than usual in an attempt to process his own anxieties."
	},
	{
		"src": "Stanning, die als Hauptmann im Royal Artillery Regiment in einem Einsatz in Afghanistan war, sagte \"Ich war diese Woche ein emotionales Wrack. Das ist vielleicht etwas extrem, aber es bedeutet so viel.\"",
		"tgt": "Stanning, a captain in the Royal Artillery regiment with a tour of Afghanistan behind her, said \"I've been an emotional wreck this week, maybe that's a bit extreme, but it means such a lot.\""
	},
	{
		"src": "Es wiederholt nur, wieviel mir das bedeutet, wieviel ich und Helen und auch Robin gearbeitet haben.",
		"tgt": "It just reiterates how much this means to me, how much me and Helen have worked and Robin as well."
	},
	{
		"src": "Es waren drei fantastische Jahre mit Helen und Robin.",
		"tgt": "It's been a fantastic three years back with Helen and Robin."
	},
	{
		"src": "Ohne Robin w\u00e4ren wir niemand, daher geht ein massives Danke an ihn. Er ist der beste Trainer der Welt.",
		"tgt": "Without Robin we would be nobody, so a massive thanks to him he's the best coach in the world."
	},
	{
		"src": "Ich h\u00e4tte mir keine bessere Person zum Trainieren oder einen besseren Trainer w\u00fcnschen k\u00f6nnen.",
		"tgt": "I couldn't have asked for a better person to train with, or a better coach."
	},
	{
		"src": "Helena Glover und Heather Stanning haben in den letzten f\u00fcnf Jahren kein Rennen verloren.",
		"tgt": "Helen Glover and Heather Stanning haven't lost a race in five years."
	},
	{
		"src": "Das Paar hatte einen harten Rhythmus, mit denen ihre Gegner nicht mithalten konnten.",
		"tgt": "The pair set a punishing rhythm that their rivals could never match."
	},
	{
		"src": "Selbst in den letzten 500 Metern, als die Teams aus Neuseeland und D\u00e4nemark anfingen aufzuschlie\u00dfen, hatten Stanning und Glover zuviel in Reserve.",
		"tgt": "Even in the final 500 metres when the crews from New Zealand and Denmark began to close, Stanning and Glover had too much in reserve."
	},
	{
		"src": "Wir waren sehr im Moment gefangen.",
		"tgt": "We were very much in the moment."
	},
	{
		"src": "Helen rief \"bleib im Prozess, bleib im Prozess\".",
		"tgt": "Helen was calling 'stay in the process, stay in the process'."
	},
	{
		"src": "Es ist wirklich wichtig, sich nicht mitrei\u00dfen zu lassen.",
		"tgt": "It's really important not to get carried away."
	},
	{
		"src": "Wir hatten einen guten Start und zur gleichen Zeit waren wir nicht darauf aus, etwas Tolles zu machen.",
		"tgt": "We had a good start and at the same time we weren't looking to do anything amazing."
	},
	{
		"src": "Wir wollten heute kein Feuerwerk, wir wollten einfach ein gutes Ergebnis erzielen, hinausgehen und das Rennen gewinnen, was wir auch taten.",
		"tgt": "We weren't looking for fireworks today, we were just looking to do a good row and to go out and win that race, which we did."
	},
	{
		"src": "Das Paar wird sich f\u00fcr ein Jahr eine Auszeit nehmen, bevor es Entscheidungen \u00fcber seine Zukunft treffen wird.",
		"tgt": "The pair will take a year before deciding their futures."
	},
	{
		"src": "Glover muss n\u00e4chste Woche auf einer Hochzeit erscheinen, ihrer eigenen mit dem TV-Abenteurer Steve Backshall.",
		"tgt": "Glover has a wedding to attend next month, her own to television adventurer Steve Backshall."
	},
	{
		"src": "Jetzt will sie einfach den Moment genie\u00dfen.",
		"tgt": "For now she just wants to enjoy the moment."
	},
	{
		"src": "Ich wollte nicht sagen, dass das mein letztes Rennen war.",
		"tgt": "I didn't want to say this was my last race."
	},
	{
		"src": "Das h\u00e4tte zuviel Druck bedeutet.",
		"tgt": "That would have meant too much pressure."
	},
	{
		"src": "In London dauerte es rund sechs Monate, um zu begreifen, dass ich eine Olympiasiegerin bin.",
		"tgt": "In London it took about six months to realise that I was an Olympic champion."
	},
	{
		"src": "Es war alles so neu f\u00fcr mich und ich war so gestresst.",
		"tgt": "It was all so new and I was so stressed."
	},
	{
		"src": "Hier dauerte es ca. vier Minuten.",
		"tgt": "Here it took about four minutes."
	},
	{
		"src": "Das f\u00fchlt sich so viel besser an,\" sagte sie.",
		"tgt": "This feels so much better,\" she said."
	},
	{
		"src": "31 Jahre lang vorbildlich f\u00fcr Klarheit gesorgt",
		"tgt": "Setting a clear example for 31 years"
	},
	{
		"src": "Der Gesch\u00e4ftsf\u00fchrer des Wasserzweckverbands \"Veitensteingruppe\", Ruppert G\u00f6ller, geht in den Ruhestand.",
		"tgt": "The Managing Director of the \"Veitensteingruppe\" Water Supply Association, Rupert G\u00f6ller, is retiring."
	},
	{
		"src": "Der Verband gilt als \"bayernweit vorbildlich\".",
		"tgt": "The Assocation \"sets an example for the entirety of Bavaria\"."
	},
	{
		"src": "Ein kleiner fr\u00e4nkischer Trinkwasserzweckverband als Vorbild f\u00fcr die gro\u00dfen Wasserproduzenten.",
		"tgt": "A small Franconian drinking water supply association as a role-model for the large water producers."
	},
	{
		"src": "So hie\u00df es vor einiger Zeit im Originalton in einem Beitrag des Bayerischen Rundfunks.",
		"tgt": "That was how the association was described in a segment on Bavarian radio."
	},
	{
		"src": "Wenig sp\u00e4ter w\u00fcrdigte das Wasserforum der Regierung von Unterfranken den Zweckverband.",
		"tgt": "A little later, the Water Forum of the government of Lower Franconia praised the Association."
	},
	{
		"src": "Die Arbeit der Veitensteingruppe gelte \"bayernweit als vorbildlich\".",
		"tgt": "The Veitensteingruppe's work was described as \"setting an example for the entirety of Bavaria\"."
	},
	{
		"src": "Hinter all dem steht Rupert G\u00f6ller, der 31 Jahre im Zweckverband Mitarbeiter war, davon 28 Jahre als Gesch\u00e4ftsf\u00fchrer.",
		"tgt": "Rupert G\u00f6ller is behind it all: he worked as an employee of the Association for 31 years, and has been its Managing Director for 28."
	},
	{
		"src": "Nun wurde er im Alter von 65 Jahren in den Ruhestand verabschiedet.",
		"tgt": "He has now gone into retirement at the age of 65."
	},
	{
		"src": "Der Trinkwasserzweckverband der Veitensteingruppe mit Sitz in Kottendorf, Gemeinde Breitbrunn, f\u00f6rdert j\u00e4hrlich etwa 150000 Kubikmeter Wasser und versorgt 32 Orte und Weiler mit etwa 5500 Einwohnern.",
		"tgt": "The Veitensteingruppe Drinking Water Supply Association has its headquarters in Kottendorf in the commune of Breitbrunn, and provides 150,000 cubic metres of water annually, supplying 32 villages and hamlets with around 5,500 inhabitants."
	},
	{
		"src": "Mitgliedsgemeinden sind die Gemeinden Kirchlauter, Breitbrunn, Lauter, Ebelsbach und die Stadt Baunach.",
		"tgt": "The communes of Kirchlauter, Breitbrunn, Lauter, Ebelsbach and the municipality of Baunach are also members."
	},
	{
		"src": "F\u00fcr weitere St\u00e4dte und Gemeinden gibt es Wasserlieferungsvertr\u00e4ge.",
		"tgt": "Water supply contracts are in place for additional municipalities and communes."
	},
	{
		"src": "Die aktuelle Vorsitzende, Breitbrunns B\u00fcrgermeisterin Gertrud B\u00fchl (FW), erinnerte daran, dass Rupert G\u00f6ller 1985 als Wasserwart eingestellt und schon 1988 zum Gesch\u00e4ftsf\u00fchrer des Zweckverbandes ernannt wurde.",
		"tgt": "Current chairman, Breitbrunn's mayoress Gertrud B\u00fchl (FW), looks back to when Ruper G\u00f6ller was brought on as a water officer in 1985, and was promoted to Managing Director of the Association as soon as 1988."
	},
	{
		"src": "\"Seine Aufgaben sind sehr vielf\u00e4ltig gewesen und sie erstreckten sich vom Wasserleitungsbau und Instandhaltungsarbeiten \u00fcber B\u00fcro- und Organisationst\u00e4tigkeiten, die Haushaltsplanerstellung, Kalkulation von Geb\u00fchren und Beitr\u00e4gen bis hin zu Notfalleins\u00e4tzen an Wochenenden\", sagte die Vorsitzende.",
		"tgt": "\"His tasks were very varied, ranging from constructing water pipes and performing maintenance work through to office and organisational tasks, budget planning, calculating fees and contributions, through to getting involved in emergencies at weekends,\" the chairman said."
	},
	{
		"src": "Als herausragende Ereignisse nannte sie die Inbetriebnahme und Einweihung der neuen Brunnen (1994), Grundst\u00fccksk\u00e4ufe im Bereich der neuen Brunnen (1998) und Entsch\u00e4digung der Landwirte, die Sanierung der Hochbeh\u00e4lter (1999), die Neuanschaffung einer zentralen Computer-Steuerung (2004) und die Teilerneuerungen von Wasserleitungen.",
		"tgt": "She pointed out some exceptional successes, including commissioning and opening the new spring (1994), purchasing land near the new spring (1998), compensating farmers, renovating the elevated tanks (1999), creating a new computer management system (2004), and renewing some of the water pipes."
	},
	{
		"src": "Es habe keinerlei Stillstand gegeben und man habe immer wieder Neuerungen aufgenommen, weil Wasser Leben bedeute und Trinkwasser das wichtigste Lebensmittel sei.",
		"tgt": "Things never stopped, and renovations were always underway: water means life, and drinking water is the most important foodstuff of all."
	},
	{
		"src": "In ihrer Laudatio lobte sie G\u00f6llers treuen, zuverl\u00e4ssigen und korrekten Dienst \u00fcber 31 Jahre hinweg.",
		"tgt": "In her laudatory speech, she praised G\u00f6ller's loyal, reliable, and upstanding service over 31 years."
	},
	{
		"src": "Er hat sich mit viel Herzblut f\u00fcr seinen Wasserzweckverband eingesetzt und er hat den Wasserzweckverband regelrecht gelebt, als w\u00e4re es sein eigenes Unternehmen.",
		"tgt": "He put his heart and soul into the Water Supply Association, and lived for it as if it were his own company."
	},
	{
		"src": "Vor wenigen Wochen habe er als echter Praktiker das Erfolgskonzept der Veitensteingruppe zur Nitratsenkung vor dem Wasserforum des Bezirks Unterfranken pr\u00e4sentieren d\u00fcrfen.",
		"tgt": "A few weeks ago he gave a presentation at the Water Forum for the District of Lower Franconia as a true practitioner of the Veitensteingruppe's successful nitrate reduction concept."
	},
	{
		"src": "Daf\u00fcr habe er sehr viel Anerkennung und Lob erhalten.",
		"tgt": "He received considerable appreciation and praise for this."
	},
	{
		"src": "Rupert G\u00f6ller seinerseits lobte Wasserwart Alfons Griebel, der 28 Jahre mit ihm zusammengearbeitet habe.",
		"tgt": "For his part, Rupert G\u00f6ller praised water officer Alfons Griebel, who had worked alongside him for 28 years."
	},
	{
		"src": "Er ist der beste Wasserwart und er war ein treuer Knappe.",
		"tgt": "He is the best water officer, and he was a loyal lad."
	},
	{
		"src": "Zusammen waren wir ein unschlagbares Team.",
		"tgt": "Together, we were an unbeatable team."
	},
	{
		"src": "Als H\u00f6hepunkte aus seiner Sicht bezeichnete er den Brunnenbau und die Neustrukturierung des Zweckverbandes.",
		"tgt": "From his perspective, the high point was the construction of the spring and the restructuring of the Association."
	},
	{
		"src": "Die gr\u00f6\u00dfte Herausforderung und der schwierigste Einsatz waren aber der Rohrbruch am Hochbeh\u00e4lter bei Kirchlauter an einem 3. Januar.",
		"tgt": "However, the largest challenge and most difficult shift was when the pipe broke on the Kirchlauter elevated tank on 3 January one year."
	},
	{
		"src": "Hier mussten wird bei minus 17 Grad die ganze Nacht hindurch arbeiten, damit die Ortschaften mit Wasser versorgt werden konnten.",
		"tgt": "We had to work through the night at minus 17 degrees to ensure the locality would be supplied with water."
	},
	{
		"src": "Auch die Versorgung von Neubrunn habe man einmal nur aufrechterhalten k\u00f6nnen, weil man den Hochbeh\u00e4lter von Pettstadt her mit Schl\u00e4uchen bef\u00fcllte.",
		"tgt": "Even the supply from the new spring was sometimes only maintained because the elevated tank at Pettstadt was filled by hosepipe."
	},
	{
		"src": "Die Gesch\u00e4ftsf\u00fchrung des Trinkwasserzweckverbandes wurde an Daniel St\u00fcrmer aus Lauter \u00fcbergeben, der die Nachfolge von Rupert G\u00f6ller antritt.",
		"tgt": "The management of the Drinking Water Supply Association was passed to Daniel St\u00fcrmer from Lauter, who will be Rupert G\u00f6ller's successor."
	},
	{
		"src": "Die Sopranistin Anna Netrebko geht offen mit der Autismus ihres Sohnes Tiago um - und wendet sich an andere betroffene Eltern: \"Sie m\u00fcssen den Mut haben, dar\u00fcber zu sprechen.\"",
		"tgt": "Soprano Anna Netrebko is open about her son Tiago's autism - and addresses other parents affected by the disease: \"You must be brave enough to talk about it.\""
	},
	{
		"src": "\"Die Medizin hat gro\u00dfe Fortschritte gemacht\", sagte die 44-J\u00e4hrige der italienischen Zeitung \"Corriere della Sera\".",
		"tgt": "\"Medicine has come a long way,\" the 44-year-old said to Italian newspaper \"Corriere della Sera\"."
	},
	{
		"src": "Als die Krankheit bei ihrem Sohn erkannt worden sei, habe sie geglaubt, sie m\u00fcsse sterben.",
		"tgt": "When her son was diagnosed with the disease, she thought she would die."
	},
	{
		"src": "Der inzwischen achtj\u00e4hrige Tiago sei aber gut vorw\u00e4rtsgekommen und lerne nun privat in New York, wo es die besten Therapeuten gebe.",
		"tgt": "Tiago is now eight years old and has made great strides, being schooled privately in New York, where the best therapists are located."
	},
	{
		"src": "\"Um ein Beispiel zu geben: Wenn ich ihn etwas frage, was zwei Jahre zur\u00fcckliegt, als ich an der Mail\u00e4nder Scala sang, erinnert er sich an nichts\", sagte Netrebko.",
		"tgt": "\"To give an example: If I ask him what happened two years ago when I sang at Milan's La Scala, he can't remember anything,\" Netrebko said."
	},
	{
		"src": "Aber er ist der gl\u00fccklichste Mensch auf Erden.",
		"tgt": "But he is the happiest person on earth."
	},
	{
		"src": "Tiago stammt aus Netrebkos Verbindung mit dem Bassbariton Erwin Schrott.",
		"tgt": "Tiago is the offspring of Netrebko's liaison with bass-baritone Erwin Schrott."
	},
	{
		"src": "Sie ist nun mit dem Tenor Yusif Eyvazov verheiratet.",
		"tgt": "She is now married to tenor Yusif Eyvazov."
	},
	{
		"src": "Beziehungstat in Bargteheide - Mann schie\u00dft auf Lebensgef\u00e4hrtin",
		"tgt": "Crime passionelle in Bargteheide - man shoots his partner"
	},
	{
		"src": "Ein 35-j\u00e4hriger Mann hat am Freitag gegen 10.45 Uhr in einem Mehrfamilienhaus in Bargteheide (Kreis Stormarn) auf seine Partnerin geschossen und sie t\u00f6dlich verletzt.",
		"tgt": "A 35-year-old man shot and fatally wounded his partner on Friday around 10.45 a.m. in an apartment building in Bargeteheide (in the district of Stormarn)."
	},
	{
		"src": "\"Der Mann hat selbst bei uns angerufen und angegeben, seine Lebensgef\u00e4hrtin erschossen zu haben\", sagte eine Polizeisprecherin.",
		"tgt": "\"The man himself called up and admitted to having shot his partner,\" a police spokeswoman said."
	},
	{
		"src": "Der T\u00e4ter sei auf der Flucht, nach ihm werde \u00f6ffentlich gefahndet.",
		"tgt": "The perpetrator is on the run, she said, and he is officially being sought."
	},
	{
		"src": "Mittlerweile bundesweit, denn Sven S. k\u00f6nnte mit dem Auto unterwegs sein.",
		"tgt": "This search is now happening across Germany, because Sven S. might be travelling by car."
	},
	{
		"src": "Der Mann ist etwa 1,80 Meter gro\u00df, muskul\u00f6s, braungebrannt und hat eine Glatze.",
		"tgt": "The man is around 1.8 m tall, muscular, sun-tanned, and has a bald patch."
	},
	{
		"src": "Mittlerweile hat die Polizei ein Foto von ihm ver\u00f6ffentlicht.",
		"tgt": "The police have now issued a photo of him."
	},
	{
		"src": "Es ist allerdings ein paar Jahre alt.",
		"tgt": "But it is a couple of years old."
	},
	{
		"src": "Inzwischen tr\u00e4gt der Mann eine Glatze.",
		"tgt": "The man now has a bald patch."
	},
	{
		"src": "Der Mann soll nicht direkt angesprochen werden.",
		"tgt": "The man should not be approached."
	},
	{
		"src": "Er k\u00f6nne noch die Waffe bei sich tragen, so die Polizei.",
		"tgt": "The police believe he may still be carrying a weapon."
	},
	{
		"src": "Wer Sven S. sieht, soll die 110 rufen.",
		"tgt": "Anyone who sees Sven S. should call 110."
	},
	{
		"src": "Die Polizei spricht von einer \"Beziehungstat\".",
		"tgt": "The police are talking of a \"crime passionelle\"."
	},
	{
		"src": "Das Opfer sei Jahrgang 1988, der T\u00e4ter 1981.",
		"tgt": "The victim was apparently born in 1988, the perpetrator in 1981."
	},
	{
		"src": "Die zust\u00e4ndige Polizei in L\u00fcbeck wollte zun\u00e4chst keine Angaben zum Tathergang oder der Beziehung zwischen T\u00e4ter und Opfer machen; sie best\u00e4tigte aber, dass ein Mensch get\u00f6tet worden sei.",
		"tgt": "The police force in L\u00fcbeck dealing with the crime initially did not want to disclose any information on the crime or the relationship between the perpetrator and the victim, but it confirmed that a person had been killed."
	},
	{
		"src": "\"Es handelt sich um einen T\u00f6tungsdelikt.\"",
		"tgt": "\"It is a homicide.\""
	},
	{
		"src": "\"Mehr sagen wir derzeit nicht\", sagte eine Polizeisprecherin in L\u00fcbeck.",
		"tgt": "\"We are not saying any more at this time,\" a police spokeswoman in L\u00fcbeck said."
	},
	{
		"src": "Augenzeugen zufolge war ein Spezialeinsatzkommando (SEK) am Tatort.",
		"tgt": "According to eyewitnesses, a SWAT team was at the scene."
	},
	{
		"src": "Stahl - Lichtblick f\u00fcr Deutsche Stahlindustrie",
		"tgt": "Steel - There's a ray of hope for the German steel industry"
	},
	{
		"src": "Die krisengebeutelte und energieintensive deutsche Stahlindustrie bleibt von zus\u00e4tzlichen Kosten in Millionenh\u00f6he verschont.",
		"tgt": "The German steel industry has been riddled with crises and uses a lot of energy - but it has been spared additional costs that could have run into the millions."
	},
	{
		"src": "Finanzielle Belastungen, die der Branche aus der \u00d6kostrom-F\u00f6rderung drohten, sind vom Tisch.",
		"tgt": "The sector had been threatened by financial burdens for the promotion of green energy, but these are now off the table."
	},
	{
		"src": "Es bleibe bei der Befreiung von der Erneuerbare-Energien-Umlage bei den Bestandsanlagen zur sogenannten Eigenstromproduktion in der deutschen Stahlindustrie, sagte Bundeswirtschaftsminister Sigmar Gabriel (SPD) der \"Westdeutschen Allgemeinen Zeitung\" (WAZ, Freitagausgabe).",
		"tgt": "Federal Minister of the Economy Sigmar Gabriel (SPD) told the \"Westdeutsche Allgemeine Zeitung\" (WAZ) newspaper on Friday that the exemption from the renewable energies levy would remain in place for electricity self-supply for pre-existing plants within the German steel industry."
	},
	{
		"src": "\"Ich bin wirklich froh dar\u00fcber, dass wir das nach zwei Jahren z\u00e4her Verhandlungen endlich erreichen konnten.\"",
		"tgt": "\"I am truly delighted by the fact that we have finally reached an agreement after two years of intense negotiations.\""
	},
	{
		"src": "Die Europ\u00e4ische Kommission hatte demnach zun\u00e4chst geplant, die Stahlhersteller, die Gase aus dem Hochofen zur Stromerzeugung f\u00fcr den eigenen Verbrauch einsetzen, zur Kasse zu bitten.",
		"tgt": "The European Commission had originally planned to make steel manufacturers, who use the gases from their blast furnaces to generate electricity for their own use, pay a levy."
	},
	{
		"src": "Der Stahlindustrie drohten nach Angaben des deutschen Branchenverbands zus\u00e4tzliche Kosten von 120 bis 240 Millionen Euro pro Jahr.",
		"tgt": "According to the German association for the sector, the steel industry was threatened with additional costs ranging from 120 to 240 million euros a year."
	},
	{
		"src": "Gabriel sagte der WAZ, es gebe nun eine Grundsatzeinigung mit der EU-Kommission nach Gespr\u00e4chen mit Wettbewerbskommissarin Margrethe Vestager.",
		"tgt": "Gabriel told WAZ that a basic agreement had now been reached with the EU Commission, following discussions with Margrethe Vestager, the Commissioner for Competition."
	},
	{
		"src": "Erst wenn die Generatoren in den Stahlwerken ersetzt werden, falle eine EEG-Umlage von 20 Prozent an.",
		"tgt": "The EEG levy of 20 percent is now only due when the generators in the steelworks are replaced."
	},
	{
		"src": "Aber auch diese werde in der Stahlindustrie nicht erhoben.",
		"tgt": "This too will not be levied against the steel industry."
	},
	{
		"src": "Die IG Metall begr\u00fc\u00dfte die Einigung Deutschlands mit der EU-Kommission zur Eigenstromerzeugung.",
		"tgt": "IG Metall welcomed the agreement Germany had reached with the EU Commission on electricity self-generation."
	},
	{
		"src": "Damit werde der Status Quo der bisherigen Regelung weitgehend festgeschrieben.",
		"tgt": "The agreement sees the status quo of the previous ruling largely formalised."
	},
	{
		"src": "Besondere Bedeutung habe das erfolgreiche Bem\u00fchen von Gabriel f\u00fcr die Stahlindustrie.",
		"tgt": "Gabriel's positive efforts are particularly important for the steel industry."
	},
	{
		"src": "\"Im Hinblick auf unsere Kampagne 'Stahl ist Zukunft' ist das ein erster Schritt.\"",
		"tgt": "\"It is the first step within our \"steel is the future\" campaign.\""
	},
	{
		"src": "\"Weitere m\u00fcssen folgen.\"",
		"tgt": "\"This needs to be followed by other steps.\""
	},
	{
		"src": "\"Auch bei der Reform des Emissionsrechtehandels sind Klima- und Besch\u00e4ftigungsziele abzuw\u00e4gen\", erkl\u00e4rte IG Metall-Chef J\u00f6rg Hofmann in Frankfurt.",
		"tgt": "\"Climate targets and employment objectives also need to be taken into account during negotiations to reform emissions allowances,\" explained IG Metall's CEO, J\u00f6rg Hofmann, in Frankfurt."
	},
	{
		"src": "Die Stahlbranche in Europa leidet seit der Finanzkrise 2008 unter \u00dcberkapazit\u00e4ten und einem erheblichen Preisdruck.",
		"tgt": "Since the financial crisis of 2008, Europe's steel sector has suffered from overcapacities and considerable pressure in terms of pricing."
	},
	{
		"src": "Im vergangenen Jahr versch\u00e4rfte sich die Lage weiter, als das weltgr\u00f6\u00dfte Erzeugerland China angesichts der schw\u00e4chelnden heimischen Nachfrage massenhaft Stahl auf den Weltmarkt warf.",
		"tgt": "The situation only worsened over the past year when the world' biggest producer, China, dumped steel into the global market en masse as a result of weakening domestic demand."
	},
	{
		"src": "Europ\u00e4ische Hersteller werfen chinesischen Stahlkonzernen Preisdumping vor.",
		"tgt": "European manufacturers accuse Chinese steel firms of price dumping."
	},
	{
		"src": "Im Laufe dieses Fr\u00fchjahrs hat sich die Situation etwas entspannt.",
		"tgt": "The situation improved slightly during spring of this year."
	},
	{
		"src": "Zum einen zeigen verh\u00e4ngte Einfuhrz\u00f6lle auf Importstahl Wirkung, zum anderen haben sich die Wirtschaftsaussichten in China aufgehellt.",
		"tgt": "On the one hand, import taxes started to have an impact on imported steel, on the other, economic prospects in China brightened up."
	},
	{
		"src": "Unklar ist, wie nachhaltig die Preiserholung ist.",
		"tgt": "It is not clear how long prices will remain perked up for."
	},
	{
		"src": "Der deutschen Branchenprimus Thyssenkrupp blieb am Donnerstag vorsichtig.",
		"tgt": "The German sector leader, Thyssenkrupp, was cautious on Thursday."
	},
	{
		"src": "Zuletzt h\u00e4tten die Preise wieder eher stagniert.",
		"tgt": "Prices had plateaued recently, he said."
	},
	{
		"src": "Die Branche reagiert auf die schwierige Lage mit weiteren Kostensenkungen.",
		"tgt": "The sector is reacting to the tricky situation by reducing prices further."
	},
	{
		"src": "Thyssenkrupp wollte dabei zuletzt auch Schlie\u00dfungen einzelner Werke nicht ausschlie\u00dfen.",
		"tgt": "Thyssenkrupp also did not want to rule out closing individual plants."
	},
	{
		"src": "In der deutschen Stahlindustrie waren Ende 2015 rund 86000 Menschen besch\u00e4ftigt.",
		"tgt": "At the end of 2015, around 86,000 people were employed in Germany's steel industry."
	},
	{
		"src": "Im Juli bleiben die deutschen Stahlhersteller trotz steigender Preise und zunehmenden Bestellungen vorsichtig.",
		"tgt": "Despite rising prices and increasing orders, German steel manufacturers remained cautious in July."
	},
	{
		"src": "Sie produzierten mit 3,4 Millionen Tonnen gut sechs Prozent weniger Rohstahl als im Vorjahresmonat, wie die Wirtschaftsvereinigung Stahl am Freitag mitteilte.",
		"tgt": "At 3.4 million tons, they produced a good six percent less raw steel than in the corresponding month in the previous year, as the steel association reported on Friday."
	},
	{
		"src": "Nach einer kurzen Erh\u00f6hung im Mai ging die hergestellte Menge nun den zweiten Monat hintereinander zur\u00fcck.",
		"tgt": "After a brief spike in May, the amounts produced shrunk for a second consecutive month."
	},
	{
		"src": "Seit Jahresbeginn liegt die Produktion um zwei Prozent unter dem Vorjahreswert.",
		"tgt": "Since the start of the year, production has been two percent less than the value for the equivalent period in the previous year."
	},
	{
		"src": "Der Verband rechnet in den kommenden Monaten dank einer verbesserten Auftragslage mit einem steigenden Aussto\u00df.",
		"tgt": "The association is expecting output to increase over the next few months thanks to an improved situation in terms of orders."
	},
	{
		"src": "Gemeinschaft, Geist, Gesundheit: Singen tut Senioren gut",
		"tgt": "Community, mind, health: singing is good for the elderly"
	},
	{
		"src": "Das Singen hat Ursel Kipp schon ihr ganzes Leben begleitet: Als junges M\u00e4dchen war sie im Schulchor, im Lehramt-Studium belegte sie das Fach Musik, und heute singt die 78-J\u00e4hrige in einem Senioren-Chor.",
		"tgt": "Singing has been a constant throughout Ursel Kipp's entire life: as a young girl she sang in her school choir, when she was studying to be a teacher she took music classes, and today, the 78-year-old sings in a choir for the elderly."
	},
	{
		"src": "\"Singen bewegt mich - emotional und k\u00f6rperlich\", beschreibt sie.",
		"tgt": "\"Singing moves me - emotionally and physically,\" she describes."
	},
	{
		"src": "Nach einer Probe f\u00fchlt sie sich ausgeglichen, fr\u00f6hlich und insgesamt lebendiger, sagt sie.",
		"tgt": "After a rehearsal, she feels balanced, happy, and generally more alive, she says."
	},
	{
		"src": "Ganz nebenbei tut sie dabei ihrer Gesundheit und ihrem Geist etwas Gutes.",
		"tgt": "And additionally, she's doing something good for her health and her mind."
	},
	{
		"src": "Denn Singen ist gleich aus mehreren Perspektiven ein tolles Hobby f\u00fcr Senioren, sagt Erhard Hackler von der Deutschen Seniorenliga.",
		"tgt": "Singing is a great hobby for the elderly for a host of reasons, says Erhard Hackler from the German Association for the Elderly."
	},
	{
		"src": "Die meisten Senioren singen im Chor und teilen mit Gleichgesinnten die Freude an der Musik, beschreibt Hackler.",
		"tgt": "Most elderly people sing in a choir and share the enjoyment they get from music with like-minded people, says Hackler."
	},
	{
		"src": "Durch das regelm\u00e4\u00dfige Zusammensein k\u00f6nnen Senioren soziale Kontakte kn\u00fcpfen und pflegen.",
		"tgt": "By regularly spending time with others, the elderly can build and maintain social contacts."
	},
	{
		"src": "Denn h\u00e4ufig l\u00f6sen sich soziale und famili\u00e4re Strukturen im Alter auf, ein Chor ist dann eine ideale Gelegenheit, um Zeit mit anderen Menschen zu verbringen.",
		"tgt": "Social and familial structures often weaken as people grow older - so choir is a perfect way to spend time with other people."
	},
	{
		"src": "Diese Erfahrung hat auch Ursel Kipp in ihrem Chor gemacht: \"Sich abzusprechen und zu organisieren, sich auf die anderen verlassen zu k\u00f6nnen und voneinander zu lernen - ein Chor ist eine ganz besondere Form des Zusammenseins\".",
		"tgt": "Ursel Kipp has also experienced this in her choir: \"Arranging and organising things with people, being able to rely on others and learn from them - a choir is a really unique way of being together with other people\"."
	},
	{
		"src": "Singen kann im positiven Sinne anstrengend sein, meint Hackler.",
		"tgt": "Singing can be demanding in the positive sense, Hackler thinks."
	},
	{
		"src": "Denn dabei trainieren Senioren eine tiefe und kontrollierte Atmung.",
		"tgt": "This is because it teaches the elderly to breathe deeply and in a controlled manner."
	},
	{
		"src": "Wer seine Lunge regelm\u00e4\u00dfig fordert, ger\u00e4t auch im Alltag nicht so schnell aus der Puste.",
		"tgt": "If you push your lungs to their limits regularly, you will not run out of breath as quickly in day-to-day life."
	},
	{
		"src": "Auch wenn es darum geht, den Klang der Stimme im Alter zu erhalten, ist Singen ein optimales Hobby.",
		"tgt": "And if you are interested in keeping the sound of your voice as you age, too, singing is the perfect hobby."
	},
	{
		"src": "Auf \u00e4ltere Menschen hat Singen oft eine ganz besondere Wirkung, sagt Ursula Lenz von der Bundesarbeitsgemeinschaft der Senioren-Organisationen.",
		"tgt": "Singing often has a really special effect on older people, says Ursula LEnz from the German Association of Senior Citizens' Associations."
	},
	{
		"src": "In den \u00e4lteren Generationen hatte das gemeinsame Singen einen viel h\u00f6heren Stellenwert, es geh\u00f6rte zum Alltag, sowohl in der Schule als auch in der Freizeit, erkl\u00e4rt sie.",
		"tgt": "For older generations, singing together is seen as more important, it was part of their daily life both at school and in their leisure time, she explains."
	},
	{
		"src": "Lenz beobachtet h\u00e4ufig, dass das Singen oder H\u00f6ren von Liedern bei \u00e4lteren Menschen viele Erinnerungen weckt, oft verbunden mit positiven Gef\u00fchlen ihrer Jugendzeit.",
		"tgt": "Lenz often sees that singing or listening to songs often triggers memories in older people that are often connected to positive emotions from their youth."
	},
	{
		"src": "Durch Liedtexte und besonders Melodien entsinnen sich selbst demenzerkrankte Menschen an lange zur\u00fcckliegende Ereignisse.",
		"tgt": "Song texts, and melodies in particular, can even be used to help patients with dementia to remember things from far back in their past."
	},
	{
		"src": "Beim Singen wird dem Kopf zudem eine besondere Leistung abverlangt, erkl\u00e4rt Lenz.",
		"tgt": "Singing also demands particular mental exertion, explains Lenz."
	},
	{
		"src": "Sich gleichzeitig auf die eigene Stimme und auf einen vorgegebenen Rhythmus zu konzentrieren und sich dabei den anderen S\u00e4ngern anzupassen - das ist eine gro\u00dfe kognitive Herausforderung.",
		"tgt": "Concentrating on one's own voice and a set rhythm, while adapting to the other singers - that is a huge cognitive challenge."
	},
	{
		"src": "Gerade \u00e4ltere Menschen, die allein leben, \u00fcben so, sich nicht nur auf sich selbst zu konzentrieren.",
		"tgt": "In particular, older people who live alone can practice how to focus on people other than themselves."
	},
	{
		"src": "Ein anderer positiver Aspekt ist die Anerkennung, die man durch das Singen im Chor erf\u00e4hrt, meint Hackler.",
		"tgt": "Another positive aspect is the recognition gained by singing in a choir, Hackler thinks."
	},
	{
		"src": "Ein begeistertes Publikum ist ein tolles Lob.",
		"tgt": "A happy audience is great praise."
	},
	{
		"src": "Auch das Selbstwertgef\u00fchl w\u00e4chst durch das Singen im Chor.",
		"tgt": "Even one's self-esteem is boosted by singing in a choir."
	},
	{
		"src": "Sich selbst zu zeigen: Wenn ich lange f\u00fcr etwas \u00fcbe, werde ich besser und wachse \u00fcber mich hinaus - diese Erfahrung st\u00e4rkt.",
		"tgt": "Being able to show yourself that by practising for a long time, you can improve and grow - this experience gives you strength."
	},
	{
		"src": "Gute Gr\u00fcnde, um mit dem Singen zu beginnen, gibt es also genug.",
		"tgt": "So there are enough good reasons to start singing."
	},
	{
		"src": "Wer ein neues Hobby ausprobieren will, sollte nicht z\u00f6gern - auch wenn er meint, wenig Talent zu haben, r\u00e4t Lenz.",
		"tgt": "If you want to try a new hobby, don't delay - even if you think you've not got much talent, Lenz suggests."
	},
	{
		"src": "Man singt ja nicht allein - bei 50 singenden Menschen, wer h\u00f6rt da schon, wenn mal ein Ton daneben geht?",
		"tgt": "You're not singing by yourself - and in a group of 50 people singing, who'll hear if a note's out here or there?"
	},
	{
		"src": "Auf der Suche nach dem passenden Angebot haben Senioren verschiedene M\u00f6glichkeiten, sagt Hackler.",
		"tgt": "The elderly have many options when looking for the right fit, says Hackler."
	},
	{
		"src": "Singt jemand aus dem Bekanntenkreis in einem Seniorenchor, kann man sich einfach anschlie\u00dfen.",
		"tgt": "If someone you know already sings in a choir for the elderly, you can just go along with them."
	},
	{
		"src": "Viele St\u00e4dte bieten au\u00dferdem \u00dcbersichten \u00fcber die Ch\u00f6re in der Umgebung.",
		"tgt": "In addition, many towns offer an overview of the choirs in their region."
	},
	{
		"src": "Wer in einem kirchlichen Chor singen m\u00f6chte, kann sich direkt an die Gemeinde oder den Kirchenvorsteher wenden.",
		"tgt": "If you want to sing in a church choir, you can approach the parish or churchwarden directly."
	},
	{
		"src": "Viele Seniorench\u00f6re findet man auch \u00fcber das Internet.",
		"tgt": "Many choirs for the elderly can also be found online."
	},
	{
		"src": "Wer keinen Zugang zum Internet hat, kann die Familie, Freunde oder Nachbarn um Hilfe bei der Internetrecherche bitten.",
		"tgt": "If you don't have access to the internet, you can ask your family, friends or neighbours to help you look things up online."
	},
	{
		"src": "Wer Lust hat zu singen, sollte sich unbedingt einem Chor anschlie\u00dfen, r\u00e4t Hackler.",
		"tgt": "If you're interested in singing, you should absolutely join a choir, Hackler thinks."
	},
	{
		"src": "Singen tut der Seele gut und hat etwas Befreiendes - das gilt f\u00fcr jedes Alter.",
		"tgt": "Singing is good for the soul and is a kind of release - no matter how old you are."
	},
	{
		"src": "Katzen reagieren sensibler als Kater auf Schreie der Jungtiere",
		"tgt": "Female cats react more sensitively than male cats to the mewls of their kittens"
	},
	{
		"src": "Biologen haben in Hannover untersucht, welchen Effekt das Rufen von Katzenbabys auf erwachsene Tiere hat.",
		"tgt": "Biologists in Hanover have researched the effect kittens' cries have on adult animals."
	},
	{
		"src": "Zu ihrer \u00dcberraschung lie\u00df das Miauen auch die M\u00e4nnchen nicht kalt - allerdings verhielten sie sich im Unterschied zu den Weibchen immer gleich.",
		"tgt": "To their surprise, the miaowing didn't leave the male cats unaffected - but, compared to their female counterparts, they always acted the same way."
	},
	{
		"src": "Weibliche Katzen k\u00f6nnen den Erregungsgrad von Katzenbabys am Miauen der Kleinen erkennen.",
		"tgt": "Female cats can tell how agitated kittens are by their miaowing."
	},
	{
		"src": "Sie reagieren um zehn Prozent schneller auf Laute von K\u00e4tzchen, die sich in gro\u00dfer Not w\u00e4hnen, wie Wissenschaftler von der Tier\u00e4rztlichen Hochschule und der Medizinischen Hochschule Hannover (MHH) herausgefunden haben.",
		"tgt": "They react ten percent quicker to kittens who sound to be in great distress, the scientists from the Veterinary University and Medical University of Hanover discovered."
	},
	{
		"src": "Kater reagieren zwar auch auf die Rufe von K\u00e4tzchen - allerdings immer gleich.",
		"tgt": "Male cats do respond to kittens' cries - but always to the same extent."
	},
	{
		"src": "\"Offenbar sind die akustischen Unterschiede zwischen dem Miauen von weniger und stark erregten Jungtieren f\u00fcr die M\u00e4nnchen entweder nicht wahrnehmbar oder nicht von Bedeutung\", sagte die Biologin Wiebke Konerding von der MHH.",
		"tgt": "\"It is clear that the acoustic differences between the miaows of kittens that are more or less agitaged are either imperceptible or unimportant for male cats,\" the biologists Wiebke Konerding, from MHH, said."
	},
	{
		"src": "Sie ist Erstautorin der Studie, die an diesem Freitag im Fachmagazin \"BMC Evolutionary Biology\" ver\u00f6ffentlicht wurde.",
		"tgt": "She is the first author of the study published in the \"BMC Evolutionary Biology\" specialist journal this Friday."
	},
	{
		"src": "In einer vorherigen Untersuchung hatte das Forscherteam bereits herausgefunden, dass sich die Dauer und Tonh\u00f6he der K\u00e4tzchen-Schreie mit der Dringlichkeit ihrer Hilfebed\u00fcrftigkeit unterscheidet.",
		"tgt": "In a previous experiment the research team had already discovered that the duration and pitch of a kitten's miaow changes depending on how urgently they need help."
	},
	{
		"src": "Beobachtet wurden insgesamt neun erwachsene Kater und acht K\u00e4tzinnen aus der Tierhaltung der MHH.",
		"tgt": "Nine adult male cats and eight female cats from the MHH's animal husbandry programme were examined."
	},
	{
		"src": "Ihnen wurden zum einen Rufe von Kleinen vorgespielt, die f\u00fcr drei Minuten aus der Wurfbox genommen und von Mutter und Geschwistern getrennt wurden.",
		"tgt": "Firstly, they were played the sound of a kitten who had been taken from the birthing box and separated from its mother and siblings for three minutes."
	},
	{
		"src": "Zum anderen wurden sie mit Schreien von st\u00e4rker erregten K\u00e4tzchen konfrontiert, die zus\u00e4tzlich hochgehoben wurden.",
		"tgt": "Then they were played the sound of a more agitated cat, which had also been lifted up."
	},
	{
		"src": "Die Forscher halten ihre Ergebnisse trotz der geringen Stichprobe f\u00fcr aussagekr\u00e4ftig.",
		"tgt": "Despite the low sample size, the researchers believe the results to be significant."
	},
	{
		"src": "\"Alle Weibchen, sogar die, die noch keinen eigenen Nachwuchs hatten, reagierten differenziert auf die Schreie\", sagte Konerding.",
		"tgt": "\"All females, even those who did not have their offspring, were able to differentiate between miaows,\" said Konerding."
	},
	{
		"src": "Sie drehten sich schneller zum Lautsprecher um, wenn dieser Rufe der sehr erregteren K\u00e4tzchen abspielte.",
		"tgt": "They turned towards the speaker quicker if it was playing the sound of a highly agitated kitten."
	},
	{
		"src": "Diese F\u00e4higkeit sei m\u00f6glicherweise angeboren oder entwickele sich mit der Geschlechtsreife.",
		"tgt": "This ability may be innate, or may develop as the animal reaches sexual maturity."
	},
	{
		"src": "\"Eine \u00dcberraschung war, dass die M\u00e4nnchen \u00fcberhaupt reagiert haben\", sagte die Biologin.",
		"tgt": "\"One surprise was that the male cats reacted at all,\" the biologist said."
	},
	{
		"src": "In der Vergangenheit haben Wissenschaftler bereits mehrfach beim Menschen die Reaktionen von Frauen und M\u00e4nner auf Babyger\u00e4usche untersucht.",
		"tgt": "In the past, scientists have researched women's and men's reactions to babies' cries on multiple occasions."
	},
	{
		"src": "Auch dabei zeigten einige Studien, dass Frauen sensitiver auf S\u00e4uglinge reagierten, ganz gleich ob sie bereits M\u00fctter waren oder nicht, berichtete die Biologin Marina Scheumann.",
		"tgt": "Even in this field a few studies showed that woman reacted more sensitively to infants, regardless of whether they had their own children or not, the biologist Marina Scheumann reported."
	},
	{
		"src": "Podolski greift mit \"Gala\" nach Supercup",
		"tgt": "Podolski and \"Gala\" are shooting for the Supercup"
	},
	{
		"src": "Hakan S\u00fck\u00fcr ist in der T\u00fcrkei eine Fu\u00dfball-Legende.",
		"tgt": "Hakan S\u00fck\u00fcr is a football legend in Turkey."
	},
	{
		"src": "In der T\u00fcrkei ist gegen den einstigen Fu\u00dfballstar Hakan S\u00fck\u00fcr ein Haftbefehl erlassen worden.",
		"tgt": "An arrest warrant has been issued in Turkey for the former football star Hakan S\u00fck\u00fcr."
	},
	{
		"src": "Ihm wird vorgeworfen, Mitglied einer terroristischen Gruppe zu sein.",
		"tgt": "He is accused of being a member of a terrorist organisation."
	},
	{
		"src": "Erstmals nach dem Putschversuch findet in der T\u00fcrkei wieder ein wichtiges Fu\u00dfballspiel statt.",
		"tgt": "An important football match is taking place in Turkey for the first time following the attempted coup."
	},
	{
		"src": "Vor dem Duell der Erzrivalen zwischen Besiktas Istanbul und Lukas Podolskis Galatasaray Istanbul um den Supercup in Konya ist die offizielle Linie eindeutig: \"Business as usual\" ist angesagt.",
		"tgt": "Ahead of the duel between arch-rivals Besiktas Istanbul and Lukas Podolski's Galatasaray Istanbul for the Supercup in Konya, the official line is clear: \"business as usual\"."
	},
	{
		"src": "Schon bei der Verh\u00e4ngung des Ausnahmezustands nach dem Umsturzversuch im Juli beteuerte die Regierung, der Alltag von Normalb\u00fcrgern solle nicht beeintr\u00e4chtigt werden.",
		"tgt": "Even when announcing the state of emergency after the attempted coup in July, the government emphasised that this would not affect citizens' daily life."
	},
	{
		"src": "Das gilt aber nicht f\u00fcr die, die verd\u00e4chtigt werden, der Bewegung des Predigers Fethullah G\u00fclen anzugeh\u00f6ren, den man f\u00fcr den Putschversuch verantwortlich macht.",
		"tgt": "This does not apply to those people suspected of being followers of the imam Fethulla G\u00fclen, who is believed to be responsible for the attempted coup."
	},
	{
		"src": "Dabei wird auch vor dem Fu\u00dfball nicht halt gemacht.",
		"tgt": "And this doesn't stop for football."
	},
	{
		"src": "Gegen den fr\u00fcheren Starkicker Hakan S\u00fck\u00fcr stellte die Staatsanwaltschaft einen Haftbefehl aus.",
		"tgt": "The state prosecutor has issued a warrant for the arrest of former star striker Hakan S\u00fck\u00fcr."
	},
	{
		"src": "Demnach wird dem mittlerweile in Amerika lebenden S\u00fck\u00fcr vorgeworfen, Mitglied einer terroristischen Gruppe zu sein.",
		"tgt": "S\u00fck\u00fcr, who now lives in America, is accused of being a member of a terrorist organisation."
	},
	{
		"src": "S\u00fck\u00fcr soll Anh\u00e4nger des Predigers Fethullah G\u00fclen sein, der vom Staatspr\u00e4sidenten Recep Tayyip Erdogan f\u00fcr den Putschversuch verantwortlich gemacht wird.",
		"tgt": "S\u00fck\u00fcr is accused of being a follower of the imam Fethullah G\u00fclen, whom President Recep Tayyip Erdogan holds responsible for the attempted coup."
	},
	{
		"src": "Zwar gilt der zun\u00e4chst f\u00fcr 90 Tage verh\u00e4ngte Ausnahmezustand noch bis Oktober, tats\u00e4chlich hat das auf das Leben der meisten T\u00fcrken aber so gut wie keine Auswirkungen.",
		"tgt": "While the state of emergency, declared for ninety days, will continue until October, it is having practically no effect on the lives of most Turks."
	},
	{
		"src": "Die n\u00e4chtlichen \"Demokratie-Wachen\" auf \u00f6ffentlichen Pl\u00e4tzen im ganzen Land hat Erdogan am Mittwoch f\u00fcr beendet erkl\u00e4rt.",
		"tgt": "On Wednesday, Erdogan announced that the night-time \"democracy vigils\" in public places across the country have come to an end."
	},
	{
		"src": "Der Sport ist - wie das ganze Land - gespalten in Anh\u00e4nger und Gegner Erdogans.",
		"tgt": "The sport - like the entire country - is divided into those who support Erdogan, and those who do not."
	},
	{
		"src": "Besonders Fans des Arbeiterclubs Besiktas z\u00e4hlen traditionell nicht zu den Freunden des Pr\u00e4sidenten.",
		"tgt": "Fans of the workers' club Besiktas, in particular, are not traditionally counted among the President's friends."
	},
	{
		"src": "Was das Gros der T\u00fcrken aber angesichts dramatischer Erfahrungen in der Geschichte eint, ist die strikte Ablehnung von Milit\u00e4rputschen.",
		"tgt": "However, the strict rejection of military coups is what brings most Turks together, in the light of dramatic historical events."
	},
	{
		"src": "Da sind sich sogar selbst die Fans einig - egal, ob ihr Herz f\u00fcr Galatasaray oder Besiktas schl\u00e4gt.",
		"tgt": "And even the fans can agree on that - whether their hearts beat for Galatasaray or Besiktas."
	},
	{
		"src": "Bei Pokalsieger \"Gala\" wird es besonders wieder auf Lukas Podolski ankommen.",
		"tgt": "For cup winners Gala, it will once again depend on Lukas Podolski."
	},
	{
		"src": "Seinen sportlichen Wert stellte der K\u00f6lner in der abgelaufenen Saison unter Beweis: Mit 17 Toren und neun Vorlagen in allen Wettbewerben beendete der 31-J\u00e4hrige seine erste Spielzeit als Topscorer seines Vereins.",
		"tgt": "The Cologne native has proved his sporting value over the last season: with 17 goals and nine assists across all competitions, the 31-year-old closed his first season as his club's top scorer."
	},
	{
		"src": "Im Endspiel gegen Fenerbahce erzielte er den 1:0-Siegtreffer.",
		"tgt": "In the final game against Fenerbahce, he scored the goal that led to a 1-0 victory."
	},
	{
		"src": "Die Zeitung \"Fanatik\" bejubelte ihn: \"Er war der Beste auf dem Platz.\"",
		"tgt": "The \"Fanatik\" newspaper praised him, saying \"he was the best player on the pitch.\""
	},
	{
		"src": "Er hat die Saison auf hervorragende Weise abgeschlossen und seiner Mannschaft den Pokal gesichert.",
		"tgt": "He finished the season in style, and secured the cup for his team."
	},
	{
		"src": "Dank \"Poldi\" fand die entt\u00e4uschende Saison f\u00fcr den Rekordmeister einen vers\u00f6hnlichen Abschluss.",
		"tgt": "Thanks to \"Poldi\", the disappointing season for the record-holders came to a happy end."
	},
	{
		"src": "Nach dem Vorrunden-K.o in der Champions League schieden die \"L\u00f6wen\" auch in der Europa League fr\u00fch aus.",
		"tgt": "After their knockout in the heats for the Champions League, the \"Lions\" also left the Europa League early on."
	},
	{
		"src": "In der S\u00fcper Lig reichte es nur zu Rang sechs.",
		"tgt": "They only reached sixth place in the S\u00fcper Lig."
	},
	{
		"src": "Die Saison war nicht gut.",
		"tgt": "The season was not good."
	},
	{
		"src": "Der Pokal war die einzige M\u00f6glichkeit, etwas zu gewinnen.",
		"tgt": "The cup was the only chance to win something."
	},
	{
		"src": "\"Das haben wir geschafft und das ist das Wichtigste\", sagte Podolski.",
		"tgt": "\"We did it - and that's the most important thing,\" said Podolski."
	},
	{
		"src": "F\u00fcr Meister Besiktas lief das Spieljahr besser.",
		"tgt": "Winners Besiktas saw a better year of play."
	},
	{
		"src": "Vor allem dank Mario Gomez, der mit 26 Saisontreffern als S\u00fcper-Lig-Torsch\u00fctzenk\u00f6nig die Basis zum 14. Titel legte.",
		"tgt": "This is mainly thanks to Mario Gomez, who laid the groundwork for their fourteenth title with 26 matches in the season as the S\u00fcper Lig's star goalkeeper."
	},
	{
		"src": "Das ist auch der Grund, dass die Fans weiter auf die R\u00fcckkehr des 31-J\u00e4hrigen hoffen.",
		"tgt": "This is also why fans are hoping that the 31-year-old returns."
	},
	{
		"src": "Dabei hatte der beim AC Florenz unter Vertrag stehende und an Besiktas nur ausgeliehene Gomez nach dem Putschversuch bekanntgegeben, wegen der politischen Situation im Land nach seinem EM-Urlaub nicht zur\u00fcckzukehren.",
		"tgt": "Gomez, under contract at AC Florenz and only on loan to Besktas, announced after the attempted coup that he would not return to the country after his European Championship holiday due to the political situation."
	},
	{
		"src": "\"Wenn Mario doch zu uns kommen will, muss er es nur sagen\", zitierte das Fachmagazin \"Kicker\" Clubchef Fikret Orman.",
		"tgt": "\"But if Mario wants to come here, all he has to do is say,\" \"Kicker\" specialist magazine quoted club chairman Fikret Orman as saying."
	},
	{
		"src": "Dazu m\u00fcsste der St\u00fcrmer aber bereit sein, auf rund ein Drittel seines auf 7,5 Millionen Euro gesch\u00e4tzten Jahressal\u00e4rs zu verzichten, stellte Orman klar: \"Sein Gehalt bei Florenz k\u00f6nnen wir nicht zahlen\".",
		"tgt": "However, the star would have to be prepared to give up around a third of his annual salary, estimated at 7.5 million euros, as Orman made clear: \"We cannot pay the salary that Florenz do\"."
	},
	{
		"src": "Trotz Doping: Diese Athleten haben noch Medaillen-Chancen bei Olympia in Rio",
		"tgt": "Despite doping: These athletes are still in with a chance of winning medals in Rio"
	},
	{
		"src": "Der 34-j\u00e4hrige Justin Gatlin war bereits zweimal wegen Dopings (2001 und 2006) gesperrt.",
		"tgt": "Justin Gatlin, aged 34, has already been banned twice for doping (in 2001 and 2006)."
	},
	{
		"src": "Rio de Janeiro - Whistleblowerin Julia Stepanowa darf in Rio nicht starten.",
		"tgt": "Rio de Janeiro - Whistleblower Julia Stepanowa is banned from taking her place on the start line."
	},
	{
		"src": "Andere \u00fcberf\u00fchrte Leichtathletik-S\u00fcnder k\u00f6nnen dar\u00fcber nur lachen - sie k\u00e4mpfen in Rio um Medaillen.",
		"tgt": "Other track athletes who have been found guilty can only laugh - they are in Rio competing for medals."
	},
	{
		"src": "Das Thema Doping bestimmt nach wie vor die Schlagzeilen bei den Olympischen Spielen in Rio.",
		"tgt": "The issue of doping continues to hit the headlines during the Olympic Games in Rio."
	},
	{
		"src": "Die russische Schwimmerin Julija Jefimowa, die sich nach einer Doping-Sperre ihr Startrecht kurz vor den Spielen eingeklagt hatte, wurde bei ihrem Start (100 Meter Brust) gnadenlos ausgepfiffen und ausgebuht.",
		"tgt": "The Russian swimmer Julija Jefimowa, who appealed against her doping conviction shortly before the games to enable herself to compete, was booed and shouted at as she started her 100-metre breaststroke race."
	},
	{
		"src": "Es bot sich eine skurrile Szenerie: Mit einem aufgesetzten L\u00e4cheln war sie noch in die Halle stolziert und hatte mit ihrem Auftritt provoziert.",
		"tgt": "It was a bizarre scene: She waltzed into the pool with a smile plastered on her face, a deliberately provocative entrance."
	},
	{
		"src": "Als feststand, dass sie nicht Gold holen werde, brach das Publikum in einen Jubelsturm aus.",
		"tgt": "As it became clear that she would not take the gold medal, the audience cheered enthusiastically."
	},
	{
		"src": "Doch es gibt noch zahlreiche weitere Sportler, die trotz Doping-Vergangenheit bei den Olympischen Spielen in Rio an den Start gehen.",
		"tgt": "But there are many other athletes preparing to line up on the start line at the Olympic Games in Rio despite having been involved in doping in the past."
	},
	{
		"src": "Hier eine \u00dcbersicht:",
		"tgt": "Here is an overview:"
	},
	{
		"src": "Justin Gatlin (100, 200, 4x100-m-Staffel/USA): Der 34-J\u00e4hrige geh\u00f6rt zu den umstrittensten Figuren in der Leichtathletik.",
		"tgt": "Justin Gatlin (100, 200, 4x100m relay/USA): The 34-year-old is one of the most controversial track athletes."
	},
	{
		"src": "Er war bereits zwei Mal wegen Dopings gesperrt (2001 und 2006 bis 2010).",
		"tgt": "He has already been banned twice for doping (in 2001 and from 2006 to 2010)."
	},
	{
		"src": "Seit seinem Bann l\u00e4uft der Olympiasieger von 2004 und Ex-Weltmeister sogar noch schneller als zuvor, er ist \u00fcber 100 m in 9,80 Sekunden die Nummer eins der Welt und gilt als gr\u00f6\u00dfter Herausforderer von Usain Bolt.",
		"tgt": "Since being banned, the 2004 Olympic champion and former World Champion is running faster than ever before: covering 100m in 9.80 seconds, he is the world number one, and is Usain Bolt's major challenger."
	},
	{
		"src": "Shelly-Ann Fraser-Pryce (100, 4x100-m-Staffel/Jamaika): Die zweimalige Olympiasiegerin und siebenfache Weltmeisterin musste 2010 eine sechsmonatige Sperre absitzen, nachdem ihr die Einnahme des Schmerzmittels Oxycodon nachgewiesen wurde.",
		"tgt": "Shelly-Ann Fraser-Pryce (100, 4x100m relay/Jamaica): The two-time Olympic champion and seven-time World Champion was handed a six-month ban in 2010 after she was proved to have taken Oxycodone."
	},
	{
		"src": "Sie habe nach einer Operation starke Zahnschmerzen gehabt, verteidigte sich die 29-J\u00e4hrige.",
		"tgt": "The 29-year-old defended herself by saying she had suffered with bad toothache after an operation."
	},
	{
		"src": "Sandra Perkovic (Diskus/Kroatien): 2011 wurde die Olympiasiegerin von 2012, Weltmeisterin von 2013 und Europameisterin von 2010 bis 2016 positiv auf das verbotene Stimulans-Mittel Methylhexanamin getestet.",
		"tgt": "Sandra Perkovic (discus/Croatia): in 2011, the 2012 Olympic Chamption, 2013 World Champion and 2010-2016 European Champion tested positive for the banned stimulant methyhexaminine."
	},
	{
		"src": "Perkovic bestritt die wissentliche Einnahme und wurde sechs Monate gesperrt.",
		"tgt": "Perkovic said that she had not knowingly taken the drug, and was banned for six months."
	},
	{
		"src": "Die vier weitesten W\u00fcrfe in diesem Jahr gehen auf das Konto der gro\u00dfen Goldfavoritin.",
		"tgt": "This year's four longest throws were by the woman tipped for gold."
	},
	{
		"src": "LaShawn Merritt (200, 400, 4x400-m-Staffel/USA): Der Peking-Olympiasieger und zweimalige Weltmeister \u00fcber 400 m, war 2010 positiv getestet und 21 Monate gesperrt worden.",
		"tgt": "LaShawn Merrit (200, 400 4x400m relay/USA): Champion at the Beijing Olympics and two-time 400m World Champion, Merrit tested positive in 2010 and was banned for 21 months."
	},
	{
		"src": "Ein Mittel zur Penisvergr\u00f6\u00dferung sei verantwortlich gewesen, beteuerte Merritt.",
		"tgt": "Merritt claimed that a penis enlargement drug was to blame."
	},
	{
		"src": "In diesem Jahr ist der 30-J\u00e4hrige \u00fcber 200 und 400 m der bisher schnellste Mann der Welt.",
		"tgt": "This year, the 30-year-old is the fastest man in the world in the 200m and the 400m."
	},
	{
		"src": "Iwan Tichon (Hammerwurf, Wei\u00dfrussland): Wohl kaum einem Athleten wurden so viele Medaillen nachtr\u00e4glich aberkannt.",
		"tgt": "Ivan Tichon (hammer, Belarus): There is hardly another athlete who has been retrospectively stripped of so many medals."
	},
	{
		"src": "So verlor Tichon seinen WM-Titel von 2005 neun Jahre sp\u00e4ter, nachdem bei ihm Testosteron-Doping festgestellt wurde.",
		"tgt": "Tichon lost his 2005 World Championship title nine years later after he was proved to have been involved in testosterone doping."
	},
	{
		"src": "Der mittlerweile 40-J\u00e4hrige musste zudem Olympia-Silber 2004 wegen Steroid-Dopings und den EM-Titel 2006 wegen Testosteron-Missbrauchs abgeben.",
		"tgt": "Now 40 years old, he was also stripped of his 2004 Olympic silver medal for doping with steroids, and his 2006 European Champion title for testosterone misuse."
	},
	{
		"src": "Die ebenfalls aberkannte Bronzemedaille der Olympischen Spiele 2008 erhielt er aufgrund eines Urteils des Internationalen Sportgerichtshofs CAS zur\u00fcck.",
		"tgt": "His bronze medal from the 2008 Olympics was also taken away, but it was returned to him following a decision by the International Court of Arbitration for Sport, CAS."
	},
	{
		"src": "Mit 80,04 m liegt er auf Rang zwei der Weltrangliste.",
		"tgt": "With 80.04m he is at second place in the global rankings."
	},
	{
		"src": "Liu Hong (20 km Gehen, China): Die Weltrekordlerin und Goldfavoritin wurde erst im Mai positiv getestet, darf aber trotzdem in Rio starten.",
		"tgt": "Liu Hong (20km walking, China): The world record holder and favourite to win gold tested positive as far back as May, but will still be on the start line in Rio."
	},
	{
		"src": "Bei der 29 Jahre alten Weltmeisterin wurden Hinweise auf die Einnahme eines verbotenen Nahrungserg\u00e4nzungsmittels gefunden, die Sperre der Welt-Anti-Doping-Agentur WADA fiel milde aus und lief schon am 13. Juli ab.",
		"tgt": "The 29-year-old world champion revealed traces of a banned dietary supplement, but the World Anti-Doping Agency (WADA)'s ban was lenient, and ended as early as July 13."
	},
	{
		"src": "Bombenterror in Thailand - \u00d6sterreicherin verletzt - Mehrere Tote",
		"tgt": "Bomb terror in Thailand - One Austrian woman injured - Several dead"
	},
	{
		"src": "Die \u00f6sterreichische Botschaft in Thailand stehe mit der Frau in Kontakt, sagte der Sprecher des Au\u00dfenministeriums, Thomas Schn\u00f6ll, Freitagfr\u00fch.",
		"tgt": "The Austrian Embassy in Thailand is in contact with the woman, Thomas Schn\u00f6ll, the spokesperson for the Foreign Ministry, said early on Friday morning."
	},
	{
		"src": "Sie habe Schnittwunden erlitten und sei im Krankenhaus behandelt worden, habe dieses aber bereits wieder verlassen k\u00f6nnen.",
		"tgt": "She has some cuts, he says, and was treated in hospital, but has already been able to leave hospital."
	},
	{
		"src": "Ihre Heimreise habe sie f\u00fcr Anfang September geplant.",
		"tgt": "She plans to return home at the start of September."
	},
	{
		"src": "Ob von den weiteren Explosionen auf der Urlauberinsel Phuket sowie in den s\u00fcdlichen St\u00e4dten Surat Thani, Phang Nga, Trang und Chumphon ebenfalls \u00f6sterreichische Staatsb\u00fcrger betroffen sind, sei vorerst noch unklar.",
		"tgt": "It is currently unclear whether other Austrian citizens have been affected by the other explosions on the holiday island of Phuket or in the southern cities of Surat Thani, Phang Nga, Trang and Chumpon."
	},
	{
		"src": "Das Au\u00dfenministerium stehe diesbez\u00fcglich in st\u00e4ndigem Kontakt mit den lokalen Beh\u00f6rden, so Schn\u00f6ll.",
		"tgt": "According to Schn\u00f6ll, the Foreign Ministry is in constant contact with local authorities as a result."
	},
	{
		"src": "Im rund 200 Kilometer s\u00fcdlich der Hauptstadt Bangkok gelegenen Hua Hin waren zun\u00e4chst am Donnerstagabend in einem Ausgehviertel zwei Bomben explodiert.",
		"tgt": "Hua Hin, located around 200 kilometres south of the capital city, Bangkok, two bombs went off in the nightlife district on Thursday evening."
	},
	{
		"src": "Dabei seien laut Polizei eine Thail\u00e4nderin get\u00f6tet und etwa 20 Menschen verletzt worden, darunter die \u00d6sterreicherin, drei Deutsche, drei Niederl\u00e4nder und drei Italiener.",
		"tgt": "According to police reports, a Thai woman was killed and around 20 people injured, including the Austrian woman, three Germans, three people from Holland and three Italians."
	},
	{
		"src": "Freitagfr\u00fch gingen dann erneut zwei Sprengs\u00e4tze hoch, dabei wurde laut den Beh\u00f6rden ein weiterer Mensch get\u00f6tet.",
		"tgt": "There were another two explosions early on Friday morning, with another person killed, according to the authorities."
	},
	{
		"src": "Auch von Phuket wurde in der Fr\u00fch eine Bombenexplosion gemeldet.",
		"tgt": "A bomb explosion was also reported in Phuket early in the morning."
	},
	{
		"src": "Bei der Detonation in der N\u00e4he des bei Urlaubern beliebten Badestrands Patong wurde nach Polizeiangaben ein Taxifahrer verletzt.",
		"tgt": "Police reports state that a taxi driver was injured in the explosion, which occurred near Patong beach, popular with holidaymakers."
	},
	{
		"src": "In Surat Thani an der S\u00fcdostk\u00fcste des Landes explodierte dann eine weitere Bombe, die eine st\u00e4dtische Angestellte t\u00f6tete.",
		"tgt": "Another bomb exploded in Surat Thani on the country's south-east coast, which led to the death of a civil servant."
	},
	{
		"src": "Der Sprengsatz sei laut den Beh\u00f6rden in einem Blumenbeet vor dem Revier der K\u00fcstenpolizei in die Luft gegangen.",
		"tgt": "According to the authorities, the explosive device was launched from a flower bed on the edge of the coastal police's territory."
	},
	{
		"src": "Schlie\u00dflich forderten noch Detonationen in Phang Nga und Trang an der S\u00fcdwestk\u00fcste sowie in Chumphon an der S\u00fcdostk\u00fcste mehrere Verletzte.",
		"tgt": "Finally, explosions in Phang Nga and Trang on the south-west coast and in Chumphon on the south-east coast caused several casualties."
	},
	{
		"src": "Man gehe von einem Zusammenhang mit den Explosionen in Hua Hin aus, hie\u00df es.",
		"tgt": "There is apparently a connection with the explosions in Hua Hin."
	},
	{
		"src": "\"Die Bombenattentate tragen dieselbe Handschrift\", sagte Armeegeneral Danai Kritmethavee Freitagfr\u00fch vor Journalisten.",
		"tgt": "\"The bomb attacks bear the same signature,\" said Army General Danai Kritmethavee to journalists early on Friday morning."
	},
	{
		"src": "\"Wir gehen davon aus, dass es sich um eine koordinierte Attacke handelt.\"",
		"tgt": "\"We are assuming that the attacks were coordinated\"."
	},
	{
		"src": "Es sei zu fr\u00fch, um sich zu m\u00f6glichen Motiven zu \u00e4u\u00dfern - wahrscheinlich handle es sich jedoch um die Taten von muslimischen Rebellen.",
		"tgt": "It is too early to speculate on possible motives, he says - however, it is probably the actions of Muslim rebels."
	},
	{
		"src": "Auch thail\u00e4ndische Medien wollten bei den Anschl\u00e4gen ein Muster erkennen, das f\u00fcr die Bombenattentate muslimischer Separatisten im S\u00fcden des Landes typisch ist.",
		"tgt": "The Thai media also wanted to see a pattern in the attacks that was typical of Islamic separatists in the south of the country."
	},
	{
		"src": "Die thail\u00e4ndische Polizei hingegen erkl\u00e4rte, die Attentate st\u00fcnden nicht in Zusammenhang mit der islamistischen Aufstandsbewegung oder mit dem internationalen Terrorismus.",
		"tgt": "However, the Thai police issued a statement that the attacks were not connected with the Islamist resistance movement or with global terrorism."
	},
	{
		"src": "\"Das ist nur \u00f6rtliche Sabotage, die sich auf begrenzte Gebiete und Provinzen beschr\u00e4nkt\", sagte ein Sprecher in Bangkok.",
		"tgt": "\"It is just local sabotage, limited to particular areas and provinces,\" said a spokesperson in Bangkok."
	},
	{
		"src": "Man gehe vielmehr davon aus, dass die Bomben von Gegnern der herrschenden Milit\u00e4rjunta gelegt wurden.",
		"tgt": "It is more reasonable to assume that the bombs were set off by opponents of the military junta currently ruling the country."
	},
	{
		"src": "Die Beh\u00f6rden h\u00e4tten in den vergangenen Tagen geheimdienstliche Hinweise auf bevorstehende Anschl\u00e4ge im S\u00fcden des Landes erhalten - allerdings seien sie nicht \u00fcber den genauen Zeitpunkt und die Orte informiert gewesen.",
		"tgt": "Over the past few days, the authorities have received notification from the security services about attacks planned in the south of the country - but they do not know when and where exactly the attacks are planned for."
	},
	{
		"src": "Noch sei unklar, welche Gruppe hinter den Anschl\u00e4gen stecke.",
		"tgt": "It is still apparently unclear who is behind the attacks."
	},
	{
		"src": "Die Polizei wies ihre Beamten im ganzen Land an, die Sicherheit rund um wichtige Regierungsgeb\u00e4ude sowie Flugh\u00e4fen, Bahnh\u00f6fe, Touristenattraktionen, Restaurants und Vergn\u00fcgungsviertel zu verst\u00e4rken.",
		"tgt": "The police told civil servants across the entire country to increase security around important governmental buildings, along with airports, railway stations, tourist attractions, restaurants and nightlife districts."
	},
	{
		"src": "In Thailand gibt es immer wieder kleinere Bombenanschl\u00e4ge, doch richten sie sich meist nicht gegen Touristen.",
		"tgt": "Small-scale bombings are a frequent occurrence in Thailand, but they are rarely directed at tourists."
	},
	{
		"src": "In Hua Hin liegt ein Palast, der \u00fcber Jahre von Thailands K\u00f6nig Bhumibol Adulyadej benutzt wurde.",
		"tgt": "There is a palace in Hua Hin that was used by Thailand's King Bhumibol Adulyadej for years."
	},
	{
		"src": "Nach den nunmehrigen Bombenexplosionen empfiehlt das \u00f6sterreichische Au\u00dfenministerium auf seiner Homepage, den Anweisungen der thail\u00e4ndischen Sicherheitsbeh\u00f6rden unbedingt Folge zu leisten.",
		"tgt": "After the recent bomb explosions, the Austrian Foreign Ministry has issued a recommendation on its homepage that Austrians follow the instructions from the Thai security agencies at all times."
	},
	{
		"src": "Hohes Sicherheitsrisiko (Sicherheitsstufe 3) gelte f\u00fcr die Provinzen Narathiwat, Yala, Pattani und Songhkla sowie Preah Vihear und Umgebung.",
		"tgt": "The provinces of Narathiwat, Yala, Pattani and Songhkla, along with Preah Vihear and its surroundings, have been issued with a high security alert (security level 3)."
	},
	{
		"src": "Nach Auseinandersetzungen zwischen Sicherheitskr\u00e4ften und muslimischen Bev\u00f6lkerungsteilen wird vor nicht notwendigen Reisen in diese Provinzen abgeraten.",
		"tgt": "After skirmishes between security forces and Muslim sectors of the population, people are advised against all but essential travel to these districts."
	},
	{
		"src": "Erh\u00f6htes Sicherheitsrisiko (Sicherheitsstufe 2) gelte f\u00fcr den Rest des Landes.",
		"tgt": "The rest of the country is on an increased security alert (security level 2)."
	},
	{
		"src": "Die Anschl\u00e4ge am Donnerstag und Freitag erfolgten wenige Tage nach einem umstrittenen Referendum \u00fcber eine von der Milit\u00e4rjunta ausgearbeitete Verfassung.",
		"tgt": "The attacks on Thursday and Friday came just a few days after a controversial referendum on a constitution drawn up by the military junta."
	},
	{
		"src": "Diese r\u00e4umt dem Milit\u00e4r gro\u00dfen Einfluss auch in den kommenden Jahren ein.",
		"tgt": "This will give the military large-scale influence even in the years to come."
	},
	{
		"src": "Junta-Chef und Ministerpr\u00e4sident Prayut Chan-o-cha sagte, die Bomben seien ein Versuch gewesen, Chaos zu stiften, w\u00e4hrend sich das Land in Richtung Stabilit\u00e4t, einer Verbesserung der Wirtschaftslage und des Tourismus bewege.",
		"tgt": "The Head of the junta, and Prime Minister, Prayut Chan-o-cha said that the bombs were an attempt to create chaos when the country was heading towards stability, an improved economic climate and tourism."
	},
	{
		"src": "Die Milit\u00e4runta, die 2014 nach einer Phase blutiger Unruhen die Macht ergriffen hatte, h\u00e4lt sich selbst zugute, das K\u00f6nigreich wieder zu Stabilit\u00e4t und Ordnung gef\u00fchrt zu haben.",
		"tgt": "The military junta took power in 2014 after a period of bloody unrest, and believes that it has led the kingdom back to stability and order."
	},
	{
		"src": "Allerdings ist es auch dem Milit\u00e4r nicht gelungen, den seit Jahren im \u00e4u\u00dfersten S\u00fcden des Landes schwelenden Aufstand muslimischer Rebellen in den Griff zu bekommen.",
		"tgt": "However, the military has not managed to quell the latent resistance brewing with Muslim rebels in the southern edges of the country."
	},
	{
		"src": "In dem Konflikt wurden bereits mehr als 6500 Menschen get\u00f6tet.",
		"tgt": "More than 6,500 people have been killed in the conflict so far."
	},
	{
		"src": "Vor knapp einem Jahr waren zudem in Bangkok bei einem Anschlag an einem beliebten Hindu-Schrein 20 Menschen get\u00f6tet worden - die meisten von ihnen ausl\u00e4ndische Touristen.",
		"tgt": "A little under a year ago, 20 people were killed in an attack on a popular Hindu shrine in Bankok - the majority of whom were foreign tourists."
	},
	{
		"src": "Es war der blutigste Anschlag der j\u00fcngeren Geschichte des Landes.",
		"tgt": "It was the most bloody attack in the country's recent history."
	},
	{
		"src": "Die rechte \"Identit\u00e4re Bewegung\" ist ins Visier des Bundesamtes f\u00fcr Verfassungsschutz geraten.",
		"tgt": "The Federal Office for the Protection of the Constitution has the right-wing \"Identit\u00e4re Bewegung\" movement in its sights."
	},
	{
		"src": "Nach mehreren Landes\u00e4mtern haben auch die Verfassungssch\u00fctzer im Bund die Gruppe unter Beobachtung gestellt.",
		"tgt": "After several regional authorities had done so, the body charged with protecting the constitution across Germany has also put the group on a watchlist."
	},
	{
		"src": "\"Wir sehen bei der 'Identit\u00e4ren Bewegung' Anhaltspunkte f\u00fcr Bestrebungen gegen die freiheitliche demokratische Grundordnung\", sagte Verfassungsschutzchef Hans-Georg Maa\u00dfen der Deutschen Presse-Agentur in Berlin.",
		"tgt": "\"In terms of the \"Identit\u00e4re Bewegung\" movement, we can see clear indicators of efforts against the free, democratic order,\" said Hans-Georg Maa\u00dfen, head of constitutional protection, to the German press agency in Berlin."
	},
	{
		"src": "So werden Zuwanderer islamischen Glaubens oder aus dem Nahen Osten in extremistischer Weise diffamiert.",
		"tgt": "Muslim migrants or migrants from the Middle East were vilified in an extremist manner."
	},
	{
		"src": "Deshalb beobachten wir die Bewegung nun auch.",
		"tgt": "That is why we will also be monitoring the movement from henceforth."
	},
	{
		"src": "Die \"Identit\u00e4re Bewegung\" ist eine Gruppierung mit franz\u00f6sischen Wurzeln, die seit 2012 auch in Deutschland aktiv ist.",
		"tgt": "The \"Identit\u00e4re Bewegung\" is a group with French roots that has been active in Germany since 2012."
	},
	{
		"src": "Sie wendet sich gegen \"Multikulti-Wahn\", \"unkontrollierte Massenzuwanderung\" und den \"Verlust der eigenen Identit\u00e4t durch \u00dcberfremdung\".",
		"tgt": "It fights against \"multicultural madness\", \"uncontrolled mass immigration\" and \"the loss of national identity through foreigners\"."
	},
	{
		"src": "Verfassungssch\u00fctzer in neun Bundesl\u00e4ndern - Bremen, Bayern, Hessen, Berlin, Baden-W\u00fcrttemberg, NRW, Niedersachsen, Sachsen und Th\u00fcringen - beobachten die \"Identit\u00e4ren\" bereits.",
		"tgt": "Bodies protecting the constitution across nine federal states - Bremen, Bavarian, Hesse, Berlin, Baden-W\u00fcrttemberg, North Rhine-Westphalia, Lower Saxony, Saxony and Thuringia - already have the \"Identit\u00e4re\" under observation."
	},
	{
		"src": "Maa\u00dfen sagte, seine Beh\u00f6rde habe sich bei der Entscheidung eng mit den Landes\u00e4mtern abgestimmt.",
		"tgt": "Maa\u00dfen said that his authority had worked closely with regional authorities to come to its decision."
	},
	{
		"src": "\"Gruppen wie die 'Identit\u00e4re Bewegung' versuchen, ihre Zielgruppe da abzuholen, wo sie steht\", sagte der Verfassungsschutzchef.",
		"tgt": "\"Groups such as the \"Identit\u00e4re Bewegung\" are trying to approach their target group on their level,\" said the head of constitutional protection."
	},
	{
		"src": "Generell versuchen Extremisten, sie mit jugendgerechter Sprache anzusprechen, oftmals mit poppiger Musik.",
		"tgt": "In general, extremists attempt to speak to them in young people's own language, often with pop music."
	},
	{
		"src": "Das t\u00e4ten Islamisten ebenso wie Rechtsextremisten.",
		"tgt": "Radical Islamists and right-wing extremists both do this."
	},
	{
		"src": "Das ist keine betuliche Werbung f\u00fcr die eigene Sache.",
		"tgt": "It's not calm advertisement for the actual matter at hand."
	},
	{
		"src": "Die Propaganda soll die Leute emotional ansprechen.",
		"tgt": "This propaganda is designed to provoke an emotional response in people."
	},
	{
		"src": "Junge Leute sind da in besonderer Weise anf\u00e4llig.",
		"tgt": "Young people are particularly vulnerable to this."
	},
	{
		"src": "Das ist gef\u00e4hrlich.",
		"tgt": "This is dangerous."
	},
	{
		"src": "Zuletzt hatte es aus mehreren Bundesl\u00e4ndern Berichte \u00fcber Kontakte der \"Identit\u00e4ren\" zu AfD-Politikern gegeben.",
		"tgt": "Recently, there have been reports from several federal states pointing out contact between members of the \"Identit\u00e4re\" movement and AfD politicians."
	},
	{
		"src": "Maa\u00dfen sagte, dazu habe er keine Erkenntnisse.",
		"tgt": "Maa\u00dfen said he had no information on this."
	},
	{
		"src": "F\u00fcr den Verfassungsschutz seien m\u00f6gliche Kontakte dieser Art erst ab einem gewissen Punkt relevant.",
		"tgt": "In terms of constitutional protection, potential contact of this kind only becomes relevant from a certain point, he says."
	},
	{
		"src": "Es kommt darauf an, ob die jeweilige Partei - in diesem Fall die AfD - durch bestimmte Personen, die extremistisch sind, ihre Zielrichtung \u00e4ndert und so extremistisch wird.",
		"tgt": "It depends on whether the party in question - in this case, the AfD - changes its focus and becomes extremist as a result of particular people who are extremists."
	},
	{
		"src": "Ausschlaggebend ist also, ob solche Personen steuernden Einfluss auf die Partei haben.",
		"tgt": "Therefore, the decisive factor is whether these people exert a controlling influence over the party."
	},
	{
		"src": "Dies sei nicht erkennbar.",
		"tgt": "This has not been noted."
	},
	{
		"src": "Mit Blick auf die deutliche Zunahme von rechtsmotivierten Straftaten und Angriffen auf Asylbewerber und Fl\u00fcchtlingsunterk\u00fcnfte sagte Maa\u00dfen, er w\u00fcrde in diesem Zusammenhang noch nicht von neuem rechten Terrorismus sprechen.",
		"tgt": "With regard to the clear increase in right-wing crimes and attacks on asylum seekers and refugee shelters, Maa\u00dfen said that he would not yet speak of a new right-wing terrorism."
	},
	{
		"src": "Aber wir haben in den vergangenen Jahren festgestellt, dass es rechtsterroristische Strukturen geben kann.",
		"tgt": "But, over the past few years, we have determined that right-wing terrorist structures can exist."
	},
	{
		"src": "Es gab die Gruppe 'Old School Society' oder die Freitaler Gruppe.",
		"tgt": "There was the \"Old School Society\" group or the \"Freitaler Group\"."
	},
	{
		"src": "Es kann durchaus sein, dass sich weitere rechtsterroristische Gruppierungen oder Kleinstgruppen bilden, die Anschl\u00e4ge gegen Asylsuchende, gegen Fl\u00fcchtlingsheime oder Attacken aus anderen rechtsextremistischen Motiven planen.",
		"tgt": "It can absolutely be the case that additional right-wing terrorist groups or small gatherings come to exist, and plan attacks on asylum seekers, refugee shelters, or for other far-right motives."
	},
	{
		"src": "Eine deutschlandweite oder europaweite Steuerung von Rechtsterrorismus sei aber nicht erkennbar.",
		"tgt": "However, there is no Germany-wide or Europe-wide control of far-right terrorism that we can discern."
	},
	{
		"src": "Die bisherigen Gruppen seien auf der regionalen Ebene oder in sozialen Netzen entstanden.",
		"tgt": "The groups that have existed to date have arisen on a regional level or via social networks."
	},
	{
		"src": "Besorgt \u00e4u\u00dferte sich Maa\u00dfen dar\u00fcber, dass viele \u00dcbergriffe auf das Konto von Menschen gingen, die vorher nicht in der rechten Szene in Erscheinung getreten seien.",
		"tgt": "Maa\u00dfen expressed concern that many attacks were perpetrated by people who had previously not been involved in the far-right scene."
	},
	{
		"src": "Das ist das Besorgniserregende.",
		"tgt": "That is frightening."
	},
	{
		"src": "Viele der Tatverd\u00e4chtigen bei Attacken auf Asylunterk\u00fcnfte seien vorher nicht als Kriminelle, politisch motivierte Straft\u00e4ter oder Anh\u00e4nger der rechten Szene bekannt gewesen.",
		"tgt": "Many of those suspected of carrying out the attacks on asylum centers were not viewed as criminals, politically motivated perpetrators or members of the far-right scene."
	},
	{
		"src": "\"Viele Personen haben also Straftaten begangen, die vorher mit Rechtsextremisten gar nichts am Hut hatten, die vielleicht politisch indifferent waren oder zum Beispiel CDU, SPD oder Linke gew\u00e4hlt haben, die sich dann allerdings durch rechtsextremistische Stimmungsmache radikalisiert haben\".",
		"tgt": "\"This means that many people have committed crimes who previously paid the far-right no heed, who might have been politically indifferent or voted for the CDU, SPD or the Left, who were then radicalised by far-right sensationalism\"."
	},
	{
		"src": "Rio 2016: Robel Kiros Habte wird zum Internethit",
		"tgt": "Rio 2016: Robel Kiros Habte becomes an Internet sensation"
	},
	{
		"src": "Nicht immer bestimmen die Olympioniken oder Weltrekorde die Schlagzeilen bei den Olympischen Spielen.",
		"tgt": "Olympic athletes or world records aren't always the only things to hit the headlines at the Olympic Games."
	},
	{
		"src": "Das zeigt der mutige Auftritt von Robel Kiros Habte bei den Sommerspielen in Rio de Janeiro.",
		"tgt": "This is shown by Robel Kiros Habte's brave performance at the summer games in Rio de Janeiro."
	},
	{
		"src": "Im Aquatics Center schwamm der leicht \u00fcbergewichtige Schwimmer aus \u00c4thiopien so langsam, dass er zeitweise nicht mehr in den TV-Bildern zu sehen war.",
		"tgt": "In the Aquatics Centre, the slightly overweight swimmer from Ethiopia swam so slowly that, sometimes, it was impossible to see him in the televised images."
	},
	{
		"src": "Er verschwand einfach - egal wie weit der Ausschnitt ausgew\u00e4hlt war.",
		"tgt": "He just disappeared - no matter how wide a perspective was used."
	},
	{
		"src": "In den sozialen Netzwerken wurde Habte anschlie\u00dfend zum viralen Internethit.",
		"tgt": "Habte finally become a viral internet sensation on social networks."
	},
	{
		"src": "Tats\u00e4chlich beendet der 24-J\u00e4hrige mit einem R\u00fcckstand von 48 Sekunden seinen Vorlauf und belegte den 59. Platz von 59 Startern.",
		"tgt": "The 24-year-old completed his heat 48 seconds slower than the next-fastest competitor, taking place 59 out of 59."
	},
	{
		"src": "Es war aber eher seine nicht gerade sportliche Figur, die die Aufmerksamkeit der internationalen Medien auf sich zog.",
		"tgt": "However, it was his not-quite sporty figure that caught the eye of the international media."
	},
	{
		"src": "Warum der 24-J\u00e4hrige dennoch an den Olympischen Spielen teilnimmt?",
		"tgt": "Why was the 24-year-old taking part in the Olympic games?"
	},
	{
		"src": "Der \u00c4thiopier bekam vom internationalen Schwimmverband ein Sonderstartrecht.",
		"tgt": "The Ethiopian was given special permission to take part by the international swimming federation."
	},
	{
		"src": "Dies wird verteilt, um Schwimmen in unterrepr\u00e4sentierten L\u00e4ndern bekannter zu machen.",
		"tgt": "This is given out to popularise swimming in underrepresented countries."
	},
	{
		"src": "Da in \u00c4thopien die meisten Sportler laufen, wollte Habte einfach mal etwas anderes machen.",
		"tgt": "Because most athletes from Ethiopia run, Habte wanted to do something different."
	},
	{
		"src": "Vorbereitung ist alles: Robel Kiros Habte macht sich fertig f\u00fcr das gro\u00dfe Rennen.",
		"tgt": "Preparation is everything: Robel Kiros Habte prepared himself for the big race."
	},
	{
		"src": "Schnell machten die ersten Spitznamen die Runde.",
		"tgt": "The first nicknames were soon doing the rounds."
	},
	{
		"src": "Einige Medien bezeichneten ihn als \"Robel der Wal\".",
		"tgt": "Some media outlets dubbed him \"Robel the whale\"."
	},
	{
		"src": "In Anlehnung an einen \"Wohlstandsbauch\" machte sich das englische Boulevardblatt \"The Sun\" mit \"Dad Bod\" \u00fcber ihn lustig.",
		"tgt": "With reference to his \"flabby stomach\", the British tabloid \"The Sun\" mocked his \"Dad Bod\"."
	},
	{
		"src": "Seine Zeit, er schlug erst mit einer Minute und fast f\u00fcnf Sekunden \u00fcber die 100 Meter Freistil an, spielte da keine Rolle.",
		"tgt": "His time, almost one minute and five seconds for the 100 metre freestyle, played no part in this."
	},
	{
		"src": "Vergleiche mit \"Eric the Eel\" wurden ebenfalls gezogen.",
		"tgt": "Comparisons were also made with \"Eric the Eel\"."
	},
	{
		"src": "Bei den Olympischen Spielen 2000 in Sydney sorgte der Lauf von Eric Moussambani f\u00fcr mediale Aufmerksamkeit.",
		"tgt": "At the 2000 Olympic Games in Sydney, Eric Moussambani's race also drew media attention."
	},
	{
		"src": "Unvergesslich war der Auftritt des Schwimmers aus \u00c4quatorial-Guinea, als er in einem Vorlauf \u00fcber 100 Meter Freistil alleine antreten musste.",
		"tgt": "The performance of the swimmer from Equatorial Guinea was unforgettable: he had to swim his 100 metre freestyle heat all on his own."
	},
	{
		"src": "Frenetisch wurde Moussambani damals angefeuert.",
		"tgt": "Moussambani was then greeted by wild cheering."
	},
	{
		"src": "Der damals 22-J\u00e4hrige lernte erst acht Monate vor Olympia schwimmen und hatte vor dem Wettkampf noch nie eine so lange Distanz absolviert.",
		"tgt": "He was 22 years old at the time, and had learnt to swim eight months before the Olympics - and had never managed such a long distance before the competition began."
	},
	{
		"src": "Ein Sitz in der vordersten Reihe zur atemberaubenden Architektur der Zentralbibliothek von Los Angeles",
		"tgt": "A front-row seat to the stunning architecture of the Los Angeles Central Library"
	},
	{
		"src": "Erfahren Sie mehr \u00fcber die Geschichte der Zentralbibliothek in der Innenstadt, da die Society of Architectural Historians/Southern California Chapter einen Salon mit Arnold Schwartzman und Stephen Gee h\u00e4lt, den Autoren des neuen Buchs \"Los Angeles Central Library: A History of its Art and Architecture\".",
		"tgt": "Learn more about the history of downtown's Central Library as the Society of Architectural Historians/Southern California Chapter hosts a salon with Arnold Schwartzman and Stephen Gee, authors of the new book \"Los Angeles Central Library: A History of its Art and Architecture\" ."
	},
	{
		"src": "Es ist vorgesehen, dass Gee und Schwartmann Bilder des 1926 Bertram Goodhue Designs sowie die 1993 Restoration und Erg\u00e4nzung von Hardy Holzman Pfeiffer Associates diskutieren und teilen werden.",
		"tgt": "Gee and Schwartzman are scheduled to discuss and share images of the 1926 Bertram Goodhue design as well as the 1993 restoration and addition by Hardy Holzman Pfeiffer Associates."
	},
	{
		"src": "Der Salon ist f\u00fcr den 21. August von 14.00 bis 16.00 im Salle Moderne in der Art Deco Southwestern School of Law, (ehemals Bullocks Wilshire), 3050 Wilshire Blvd. angesetzt.",
		"tgt": "The salon is set for 2 p.m. to 4 p.m. on Aug. 21 in the Salle Moderne at the Art Deco Southwestern School of Law, (formerly Bullocks Wilshire), 3050 Wilshire Blvd."
	},
	{
		"src": "Besucher k\u00f6nnen den Mittelsaal, die Stilzimmer, Kaktuslounge und den Teesalon besichtigen.",
		"tgt": "Attendees can tour the Central Hall, Period Rooms, Cactus Lounge and Tea Room."
	},
	{
		"src": "Nur Vorverkaufstickets; SAH/SCC Mitglieder, $ 15; Nichtmitglieder, $ 25.",
		"tgt": "Advance tickets are required; SAH/SCC members, $15; non-members, $25."
	},
	{
		"src": "Eine offene Industrieloft in DTLA erh\u00e4lt eine gem\u00fctliches Makeover",
		"tgt": "An open, industrial loft in DTLA gets a cozy makeover"
	},
	{
		"src": "Wir feiern den 90.ten Geburtstag der Zentralbibliothek von L.A. mit - was sonst? - einem neuen Buch",
		"tgt": "Celebrating L.A.'s Central Library's 90th birthday with - what else? - a new book"
	},
	{
		"src": "Geretsried - Die Inhaberin eines Ladens am Neuen Platz ist bestohlen worden.",
		"tgt": "Geretsried - Theft from the owner of a shop on the Neuen Platz."
	},
	{
		"src": "Nach Angaben der Polizei hatte die 67-j\u00e4hrige Geretsriederin am Montag gegen 17.30 Uhr ihr Gesch\u00e4ft verlassen und dabei vergessen, ein Fenster im Erdgeschoss zu schlie\u00dfen.",
		"tgt": "According to the police, the 67-year-old woman from Geretsried left her shop around 5.30 p.m. on Monday, and forgot to close a ground-floor window."
	},
	{
		"src": "Als sie am n\u00e4chsten Morgen gegen 8.15 Uhr zur\u00fcckkam, waren aus der Kasse zirka 250 Euro verschwunden.",
		"tgt": "When she returned the next morning at around 8.15 a.m. around 250 euros was missing from the till."
	},
	{
		"src": "Spuren des T\u00e4ters konnten nicht gefunden werden.",
		"tgt": "There was no trace of the perpetrator."
	},
	{
		"src": "Auch eine Video\u00fcberwachung ist nicht vorhanden.",
		"tgt": "The shop did not have CCTV."
	},
	{
		"src": "Trump sieht die drohende Wahlniederlage nicht so eng",
		"tgt": "Trump is not taking the threat of election defeat too seriously"
	},
	{
		"src": "Der republikanische Pr\u00e4sidentschaftskandidat Donald Trump spricht auf einer Wahlkampfveranstaltung in Florida.",
		"tgt": "The Republican candidate for the presidency, Donald Trump, spoke out at an election event in Florida."
	},
	{
		"src": "Sollte es mit der Wahl zum US-Pr\u00e4sidenten nichts werden, hat Donald Trump schon eine Alternatividee.",
		"tgt": "If things don't work out with the presidential election, Donald Trump already has a plan B in place."
	},
	{
		"src": "Er fahre dann eben in den Urlaub.",
		"tgt": "He would go on holiday."
	},
	{
		"src": "Verliert Donald Trump die US-Pr\u00e4sidentschaftswahlen im November, w\u00e4re ihm das relativ egal: \"Letztlich wird es entweder klappen, oder ich habe einen sehr, sehr sch\u00f6nen, langen Urlaub\", sagte der Kandidat der Republikaner in einem Telefon-Interview mit dem US-Fernsehsenders CNBC.",
		"tgt": "Donald Trump wouldn't really mind if he lost the US presidential election in November: \"Either it'll work out, or I'll go on a long, long holiday,\" the Republican candidate said in an telephone interview with US television channel CNBC."
	},
	{
		"src": "Falls es f\u00fcr ihn am Ende aus Gr\u00fcnden der politischen Korrektheit nicht reiche, sei das in Ordnung, sagte Trump.",
		"tgt": "If he doesn't make it because of political correctness, that's ok, Trump said."
	},
	{
		"src": "So bezeichnete er den US-Pr\u00e4sidenten Barack Obama und die Kandidatin der Demokraten, Hillary Clinton, als Gr\u00fcnder der Terrormiliz Islamischer Staat (IS).",
		"tgt": "For example, he called US President Barack Obama, and the Democratic candidate, Hillary Clinton, the founders of terrorist militia Islamic State (IS)."
	},
	{
		"src": "Innerhalb seiner Partei formierte sich zuletzt immer mehr Widerstand.",
		"tgt": "Within his party, resistance continues to grow."
	},
	{
		"src": "Post steigt in den Handel mit Elektro-Transportern ein",
		"tgt": "The postal service gets on board with electric vehicles"
	},
	{
		"src": "Ein Elektro-Zustellfahrzeug der Deutschen Post in Aktion.",
		"tgt": "Detusche Post's electric truck in action."
	},
	{
		"src": "Das Interesse anderer Firmen an dem Gef\u00e4hrt ist offenbar gro\u00df.",
		"tgt": "Other companies are clearly interested in the vehicle."
	},
	{
		"src": "Die Post plant, ihr Elektrofahrzeug StreetScooter auch zu verkaufen.",
		"tgt": "The postal service is also planning to sell its StreetScooter electric vehicle."
	},
	{
		"src": "In K\u00fcrze will der Konzern den Handel mit dem Transporter starten.",
		"tgt": "Soon the company will start retailing the vehicle."
	},
	{
		"src": "Die Post will ihre Elektro-Transporter ab dem kommenden Jahr auch auf dem freien Automarkt anbieten.",
		"tgt": "The postal service wants to bring its electric vehicle to the free automotive market from next year."
	},
	{
		"src": "\"Wir wollen in den Verkauf an Dritte einsteigen\", sagte ein Post-Sprecher am Freitag.",
		"tgt": "\"We want to start selling it to third parties,\" a postal service spokesman said on Friday."
	},
	{
		"src": "Das Unternehmen pr\u00fcft seit Monaten, ob sie ihren selbst entwickelten StreetScooter, mit dem Briefe und P\u00e4ckchen ausgeliefert werden, auch an andere Betriebe verkaufen soll.",
		"tgt": "For months the company has been examining whether the StreetScooter it developed, which is used to deliver letters and parcels, could be sold to other sectors as well."
	},
	{
		"src": "Post-Vorstand J\u00fcrgen Gerdes hatte gesagt, es gebe immer wieder Nachfragen, etwa von Handwerkern.",
		"tgt": "Managing Director of the postal service J\u00fcrgen Gerdes said that there was always demand from tradesmen."
	},
	{
		"src": "Nach Informationen des Nachrichtenmagazins \"Der Spiegel\" will der Bonner Konzern in K\u00fcrze in die Massenproduktion der Fahrzeuge einsteigen.",
		"tgt": "According to information in \"Der Spiegel\", a news magazine, the Bonn-based company will soon start mass production of the vehicle."
	},
	{
		"src": "In der posteigenen Fabrikation plane das Unternehmen den Bau von bis zu 10.000 Autos pro Jahr und Schicht.",
		"tgt": "The company is planning to use its own factories to build up to 10,000 vehicles per year, per level."
	},
	{
		"src": "Gerdes hatte angek\u00fcndigt, der Konzern wolle seine Flotte von Elektroautos deutlich vergr\u00f6\u00dfern und peile langfristig eine komplette Umstellung auf die umweltfreundlichen Fahrzeuge an.",
		"tgt": "Gerdes announced that the company wanted to increase the size of its fleet of electric cars considerably, and that its long-term aim was to switch over completely to these environmentally friendly vehicles."
	},
	{
		"src": "\"Wir werden einen sehr, sehr robusten Schritt Richtung 2020 machen\", hatte er Ende Juli gesagt.",
		"tgt": "\"We will take a very, very strong step towards 2020,\" he said at the end of July."
	},
	{
		"src": "Ich kann mir vorstellen, dass wir die komplette Flotte umstellen.",
		"tgt": "I can imagine that we will switch over the entire fleet."
	},
	{
		"src": "Der StreetScooter ist seit 2014 auf Deutschlands Stra\u00dfen aktiv.",
		"tgt": "The StreetScooter has been out and about on Germany's roads since 2014."
	},
	{
		"src": "GfK-F\u00fchrung tritt nach entt\u00e4uschenden Gesch\u00e4ftszahlen ab",
		"tgt": "GfK managing director steps down after disappointing figures"
	},
	{
		"src": "Das Konsumforschungsunternehmen GfK tauscht seinen Chef Matthias Hartmann aus.",
		"tgt": "Consumer research firm GfK is replacing its managing director Matthias Hartmann."
	},
	{
		"src": "Die R\u00fccktritte kamen zwar pl\u00f6tzlich - aber nicht ganz \u00fcberraschend.",
		"tgt": "His resignation came swiftly - but it was not a complete surprise."
	},
	{
		"src": "Die schwierige Lage des Marktforschungsunternehmens GfK lie\u00df erahnen, dass der Stuhl von Vorstandschef Matthias Hartmann umso unsicherer wird, je l\u00e4nger die von ihm versprochenen Erfolge ausbleiben.",
		"tgt": "The tricky situation in which market research firm GfK finds itself made it self-evident that Managing Director Matthias Harmann's seat became more and more unstable the longer the success he promised failed to materialise."
	},
	{
		"src": "Turbulenzen an der Spitze des N\u00fcrnberger Marktforschungsunternehmens GfK: Nach erneut entt\u00e4uschenden Gesch\u00e4ftszahlen und dem R\u00fccktritt der Unternehmensf\u00fchrung steht die weltweite Nummer F\u00fcnf der Branche vor einem personellen Neuanfang.",
		"tgt": "Turbulence at the top of Nuremberg's market research firm GfK: After another round of disappointing figures and the resignation of the managing director, the firm, fifth in its sector globally, is on the brink of a personal new start."
	},
	{
		"src": "GfK-Vorstands-Chef will zum Jahresende das Unternehmen verlassen.",
		"tgt": "GfK's managing director wants to leave the company at the end of the year."
	},
	{
		"src": "Der Vorsitzende des GfK-Aufsichtsrats Arno Mahlert scheidet bereits mit Wirkung zum 12. September aus dem Aufsichtsgremium aus.",
		"tgt": "The managing director of GfK's supervisory board, Arno Mahlert, has already announced that he will be leaving the supervisory committee with effect from 12 September."
	},
	{
		"src": "Die F\u00fchrung im Vorstand \u00fcbernehme bereits zum 1. September das bisherige Vorstandsmitglied Gerhard Hausruckinger, teilte das Unternehmen mit.",
		"tgt": "The company announced that Gerhard Hausruckinger, who is currently a member of the board of directors, will take over the management of the board on 1 September."
	},
	{
		"src": "Er soll offiziell die Funktion eines \"Vorstandssprechers\" \u00fcbernehmen, bis ein Nachfolger f\u00fcr Hartmann gefunden sei.",
		"tgt": "Officially, he will take on the role of \"board spokesman\" until Hartmann's successor has been found."
	},
	{
		"src": "Als Grund f\u00fcr die R\u00fccktritte nannte das Unternehmen \"unterschiedliche Ansichten\" zur langfristigen gesch\u00e4ftspolitischen Ausrichtung.",
		"tgt": "The company cited \"different viewpoints\" on long-term business direction as the reason behind the resignation."
	},
	{
		"src": "Details wollte ein Unternehmenssprecher am Freitag nicht nennen.",
		"tgt": "A company spokesman did not give further details on Friday."
	},
	{
		"src": "Wer k\u00fcnftig das Marktforschungsunternehmen leite werde, sei derzeit noch unklar.",
		"tgt": "It is currently not clear who will head up the market research firm in the future."
	},
	{
		"src": "In Anlegerkreisen hie\u00df es am Freitag, bei den Aktion\u00e4ren sei zuletzt die Entt\u00e4uschung \u00fcber die weiter ausbleibenden Erfolge der vor Jahren eingeleiteten Umstrukturierung gro\u00df gewesen.",
		"tgt": "In investment circles, on Friday it was said that shareholders were greatly disappointed by the lack of success following the restructuring programme implemented years ago."
	},
	{
		"src": "Herr Hartmann ist seit 2011 an der GfK-Spitze.",
		"tgt": "Mr Hartman has headed up GfK since 2011."
	},
	{
		"src": "\"Die Fr\u00fcchte der Umstrukturierung sind aber auch nach 5 Jahren noch nicht zu sehen\", hie\u00df es.",
		"tgt": "\"The benefits of the restructuring programme will only become visible after 5 years,\" he said."
	},
	{
		"src": "Angesichts der zuletzt schlechten GfK-Gesch\u00e4ftszahlen werde jeder Anteilseigner irgendwann unruhig.",
		"tgt": "As a result of GfK's recent poor figures, every shareholder would be a little unsettled, he said."
	},
	{
		"src": "\"Wenn das bei BMW der Fall w\u00e4re, w\u00fcrden das auch die Quandts so machen\", hie\u00df es.",
		"tgt": "\"If that were the case at BMW, the quants would be too,\" he said."
	},
	{
		"src": "Das Unternehmen hatten nach R\u00fcckschl\u00e4gen in den Vorquartalen auch im zweiten Quartal 2016 seine Verlustfahrt nicht stoppen k\u00f6nnen.",
		"tgt": "After suffering losses in the previous quarters, the company was unable to stop losing money in the second quarter of 2016."
	},
	{
		"src": "Mit 361,2 Millionen Euro lag der Umsatz um 6,1 Prozent unter dem Niveau des vergleichbaren Vorjahresquartals.",
		"tgt": "At 361.2 million euros, turnover was 6.1 lower than it had been in the same quarter of the previous year."
	},
	{
		"src": "Bezogen auf das erste Halbjahr schrumpfte der Umsatz mit 721,2 Millionen Euro um 3,4 Prozent.",
		"tgt": "Compared to the first six months of the year, turnover (721.2 million euros) had shrunk by 3.4 percent."
	},
	{
		"src": "Den Gewinn im zweiten Quartal hat vor allem der gesunkene Wert des Unternehmens angesichts seiner schwierigen wirtschaftlichen Lage belastet.",
		"tgt": "The company's reduced value because of the difficult economic climate had impacted second-quarter profits, in particular."
	},
	{
		"src": "Die im Gesch\u00e4ftsbereich Consumer Experience notwendig gewordenen Firmenwertabschreibungen von 139 Millionen Euro bescherten dem Konzern unter dem Strich einen Verlust von 148,2 Millionen Euro.",
		"tgt": "The goodwill amortisation of 139 million euros required for the consumer experience sector was provided by the company, leading to a final loss of 148.2 million euros."
	},
	{
		"src": "Im zweiten Quartal 2015 hatte die GfK noch einen Konzerngewinn von 19,7 Millionen erwirtschaftet.",
		"tgt": "In the second quarter of 2015, GfK had made a profit of 19.7 million."
	},
	{
		"src": "Unf\u00e4lle - Bus rutscht in Krummh\u00f6rn in Graben: Acht Verletzte",
		"tgt": "Incident - Bus slips into a ditch in Krummh\u00f6rn: eight people injured"
	},
	{
		"src": "Bei einem Unfall eines Reisebusses mit 43 Senioren als Fahrg\u00e4sten sind am Donnerstag in Krummh\u00f6rn (Landkreis Aurich) acht Menschen verletzt worden.",
		"tgt": "On Thursday, an accident involving a coach carrying 43 elderly people in Krummh\u00f6rn (district of Aurich) led to eight people being injured."
	},
	{
		"src": "Zwei der Insassen erlitten schwere Verletzungen, teilte die Polizei mit.",
		"tgt": "Two of the passengers suffered serious injuries, the police reported."
	},
	{
		"src": "Die 66 Jahre alte Fahrerin des Busses eines Reiseunternehmens aus Eisenach musste ihren Angaben zufolge einem entgegenkommen Laster ausweichen, der teils auf der Gegenfahrbahn fuhr.",
		"tgt": "The 66-year-old bus driver, employed by a coach company based in Eisenach, said that she had to swerve to avoid an oncoming lorry that was partly on the wrong side of the road."
	},
	{
		"src": "Der Bus kam nach rechts von der Stra\u00dfe ab und rutschte in einen Graben, wie eine Sprecherin der Polizei Aurich/Wittmund berichtete.",
		"tgt": "The bus came off the right-hand side of the road, and skidded into a ditch, a spokeswoman for the police force of Aurich/Wittmund reported."
	},
	{
		"src": "\"Aufgrund der Lage des Busses konnten die Personen den Bus nicht selbstst\u00e4ndig verlassen\", sagte sie.",
		"tgt": "\"As a result of the way the bus was positioned, people were not able to leave the bus on their own,\" she said."
	},
	{
		"src": "Die Feuerwehr befreite die Insassen.",
		"tgt": "The fire brigade freed the passengers."
	},
	{
		"src": "Sechs Rettungswagen und ein Notarztwagen kamen zum Unfallort auf der Landesstra\u00dfe 2.",
		"tgt": "Six rescue vehicles and an ambulance were in attendance at the scene of the accident on the no.2 road."
	},
	{
		"src": "Die unverletzten Reisenden wurden von einem Linienbus zur\u00fcck zum Krummh\u00f6rner Stadtteil Pewsum gebracht.",
		"tgt": "Uninjured passengers were transported back to Krummh\u00f6rn's Pewsum district by regular bus."
	},
	{
		"src": "Dort sollten sie auf einen Ersatzbus des Reiseunternehmens warten.",
		"tgt": "They waited there until a replacement bus was sent by the coach company."
	},
	{
		"src": "Die Ermittler forderten den Lasterfahrer und m\u00f6gliche Zeugen auf, sich bei der Polizei zu melden.",
		"tgt": "Investigators are asking the lorry driver and any witnesses to make themselves known to the police."
	},
	{
		"src": "Die Geb\u00fchren pro Kubikmeter Abwasser betragen ab 1. Oktober 2016 f\u00fcr den Bereich der Abwasseranlage Neudorf/Reuth/Welschenkahl 3,44 statt bisher 2,10 Euro; f\u00fcr Zultenberg/Lindenberg/Lopp 3,36 Euro (bisher 2,26 Euro) und f\u00fcr Azendorf 3,64 Euro (bisher 2,18 Euro).",
		"tgt": "From 1 October 2016, fees per cubic metre of sewage for the area covered by the sewage plant at Neudorf/Reuth/Welschenkahl will be 3.44 euros instead of 2.10 euros as previously, 3.36 euros (previously 2.26 euros) for Zultenberg/Lindenberg/Lopp, and 3.64 euros (previously 2.18 euros) for Azendorf."
	},
	{
		"src": "Bei der Anlage in Azendorf wird sich die Abwassergeb\u00fchr sp\u00e4testens dann nochmals erh\u00f6hen, wenn entsprechende Verbesserungsma\u00dfnahmen notwendig werden.",
		"tgt": "The sewage fee for the sewage works in Azendorf will be raised again if it is necessary to carry out improvement works."
	},
	{
		"src": "Nach einer \u00fcberschl\u00e4gigen Kalkulation wird der Abwasserpreis in Azendorf dann bei 4,37 Euro pro Kubikmeter liegen.",
		"tgt": "According to an estimated calculation, sewage fees in Azendorf will then come to 4.37 euros per cubic metre."
	},
	{
		"src": "Wie B\u00fcrgermeister Bernd Steinh\u00e4user (CSU) berichtete, wurde bei der Genehmigung des Haushalts durch das Landratsamt Kulmbach festgestellt, dass f\u00fcr diese Abwasseranlagen Unterdeckungen auflaufen.",
		"tgt": "As mayor Bernd Steinh\u00e4user (CSU) reported, when the district administration of Kulmbach approved the budget, it was determined that these sewage plants were underfunded."
	},
	{
		"src": "Der Markt Kasendorf sei aufgrund rechtlicher Grundlagen verpflichtet, die Anlagen kostendeckend zu betreiben.",
		"tgt": "The market town of Kasendorf is legally obliged to run the sewage works so that they break even."
	},
	{
		"src": "Ab 1. Oktober 2016 werden die B\u00fcrger sowie die Gewerbe- und Industriebetriebe aus Welschenkahl, Neudorf, Reuth, Azendorf, Lopp, Lindenberg und Zultenberg tiefer in den Geldbeutel greifen m\u00fcssen.",
		"tgt": "From 1 October 2016, individuals and commercial and industrial enterprises from Welschenkahl, Neudorf, Reuth, Azendorf, Lopp, Lindenberg and Zultenberg will have to dig a little deeper."
	},
	{
		"src": "Die Geb\u00fchrenerh\u00f6hungen liegen zwischen 48 und 67 Prozent.",
		"tgt": "The fee increases range from 48 to 67 percent."
	},
	{
		"src": "Wie Verwaltungsleiter Herbert Schmidt dem Gremium aufzeigte, war eine Neukalkulation der Geb\u00fchren f\u00fcr die Abwasseranlagen der Marktgemeinde notwendig.",
		"tgt": "As administrative director Herbert Schmidt showed the committee, it was necessary to recalculate the fees for the sewage plants serving the market town."
	},
	{
		"src": "Im Zeitraum von Oktober 2016 bis September 2020 seien auch \u00dcber- beziehungsweise Unterdeckungen aus dem vorhergehenden Kalkulationszeitraum auszugleichen.",
		"tgt": "Between October 2016 and September 2020, overfunding and underfunding from the previous calculation period will be balanced out."
	},
	{
		"src": "Die gravierenden Geb\u00fchrenerh\u00f6hungen begr\u00fcndete Schmidt damit, dass es sich bei allen drei Abwasseranlagen um relativ kleine Einrichtungen mit einem sehr geringen Abwasseranfall handele, der zwischen 6800 und 12000 Kubikmeter pro Jahr liege.",
		"tgt": "Schmidt justifies the major fee increases by saying that all three sewage plants are relatively small and deal with a very small amount of waste, namely between 6800 and 12000 cubic metres a pear."
	},
	{
		"src": "So w\u00fcrden sich aufgrund der geringen Verteilungsgrundlage zum Beispiel Aufwendungen f\u00fcr notwendige Reparaturen von mehreren Tausend Euro gravierend auswirken.",
		"tgt": "As a result of the low distribution, expenses for critical repairs amounting to several thousand euros, for example, seem major."
	},
	{
		"src": "Zudem sei das Abwasseraufkommen in allen drei Anlagen leicht r\u00fcckl\u00e4ufig.",
		"tgt": "In addition, the amount of sewage arriving at all three plants is gradually decreasing."
	},
	{
		"src": "Weiterhin seien im zur\u00fcckliegenden Kalkulationszeitraum bei allen drei Anlagen nicht zuletzt aufgrund ihres Alters Sanierungs- und Reparaturaufwendungen in einem erheblichen Umfang angefallen.",
		"tgt": "Furthermore, the previous calculation period did not include renovation and repair works to a great extent for all three treatment plants, not least because of their age."
	},
	{
		"src": "Die Anlage in Azendorf sei nahezu 30 Jahre alt, die Anlagen f\u00fcr Welschenkahl, Neudorf und Reuth sowie Zultenberg, Lindenberg und Lopp fast 20 Jahre.",
		"tgt": "The plant in Azendorf is nearly 30 years old, the plants in Welschenkahl, Neudorf and Reuth, as well as Zultenberg, Lindenberg and Lopp are almost 20 years old."
	},
	{
		"src": "Schmidt verwies darauf, dass in der Abwasseranlage Azendorf die mechanische Bel\u00fcftungsanlage aufgrund eines Schadens ausgetauscht werden musste.",
		"tgt": "Schmidt pointed out that the waste treatment plant at Azendorf needed to have its mechanical ventilation system replaced because of damage."
	},
	{
		"src": "Im Pumpwerk Welschenkahl mussten die nahezu 20 Jahre alten F\u00f6rderanlagen von Grund auf \u00fcberholt werden und bei der Teichkl\u00e4ranlage Lopp musste nach nahezu 20 Jahren Betrieb der erste Kl\u00e4rteich ausgebaggert, der Kl\u00e4rschlamm entsorgt und eine zus\u00e4tzliche Bel\u00fcftungsm\u00f6glichkeit eingebaut werden, um die wasserrechtlichen Vorgaben auch k\u00fcnftig einhalten zu k\u00f6nnen.",
		"tgt": "The conveyor system in the pumping station at Welschenkahl is almost 20 years old, and needs to be completely overhauled; the first clarification pond in the pond treatment plant at Lopp has been operational for almost 20 years and now needs to be dredged, its sewage sludge removed, and an additional ventilation system incorporated to ensure that it will be in line with water law regulations in the future."
	},
	{
		"src": "Schmidt: \"Zu diesen au\u00dferordentlichen Aufwendungen kamen die fortgeschriebenen Betreuungs- und Wartungskosten, die entsprechend im neuen Kalkulationszeitraum zu ber\u00fccksichtigen sind.\"",
		"tgt": "Schmidt: \"These extraordinary expenses were also coupled with perpetual support and maintenance costs that are to be taken into account in the new calculation period.\""
	},
	{
		"src": "Das Gleiche gilt f\u00fcr Stromkosten, welche bei der vorherigen Kalkulation in den Jahren 2011/2012 noch deutlich unter dem jetzigen Niveau lagen.",
		"tgt": "The same is true for electricity costs: in the previous calculations for 2011/2012, they are far below their current levels."
	},
	{
		"src": "Steinh\u00e4user machte deutlich, dass bei dem geringen Abwasseranfall in den drei Anlagen die Aufwendungen f\u00fcr den Betrieb und Unterhalt \"voll durchschlagen\".",
		"tgt": "Steinh\u00e4user pointed out that, even with a low amount of sewage coming to the three plants, the expenses for running and maintaining them \"were significantly impacted\"."
	},
	{
		"src": "Dabei sei, erg\u00e4nzte Schmidt, die Marktgemeinde von gro\u00dfen Unterhaltungskosten bei den Abwasseranlagen in den vergangenen 20 Jahren verschont geblieben.",
		"tgt": "As a result, Schmidt expanded, the market town had been saved from large maintenance costs for the sewage treatment plants over the past 20 years."
	},
	{
		"src": "Die Situation f\u00fcr die genannten Anlagen werde nach Ansicht von Steinh\u00e4user auf Dauer weiterhin prek\u00e4r bleiben, zumal man das Versorgungsgebiet des Abwasserzweckverbandes Friesenbachtal um diese Anlagen nicht erweitern werden k\u00f6nne, weil es sich um defizit\u00e4re Einrichtungen handelt.",
		"tgt": "From Steinh\u00e4user's perspective, the plants mentioned will remain in a precarious situation in the long run, especially as the area covered by Friesenbachtal wastewater association cannot be expanded to include these plants because they are running at a deficit."
	},
	{
		"src": "Bulgarien verbucht zum ersten Mal in 8 Monaten Inflation",
		"tgt": "Bulgaria Posts Inflation for 1st Time in 8 Months"
	},
	{
		"src": "Nationale Statistiken zeigen, dass die Inflation in Bulgarien im Juli 1 % auf einer monatlichen Basis betrug.",
		"tgt": "Inflation in Bulgaria was 1% on a monthly basis in July, national statistics show."
	},
	{
		"src": "Dies ist der h\u00f6chste Wert (seit Juni 2012) und der erste \u00fcber Null seit Oktober letzten Jahres, als positive 0,2 % verbucht wurden.",
		"tgt": "This is the highest value in years (since June 2012) and the first one above zero since October of last year when a positive 0.2% was posted."
	},
	{
		"src": "Die j\u00e4hrliche Durchschnittsinflation der letzten 12 Monate (August 2015 - Juli 2016) im Vergleich zu den vorherigen 12 Monaten (August 2014 - Juli 2015) betrug gemessen nach dem CPI -0,8 %.",
		"tgt": "The annual average inflation, measured by CPI, in the last 12 months (August 2015 - July 2016) compared to the previous 12 months (August 2014 - July 2015) was -0.8%."
	},
	{
		"src": "Der Verbraucherpreisindex im Juli 2016 verglichen zu Juni 2016 betrug 101,0 %, d.h. die monatliche Inflation betrug 1,0 %.",
		"tgt": "The consumer price index in July 2016 compared to June 2016 was 101.0%, i.e. the monthly inflation was 1.0%."
	},
	{
		"src": "Die Inflationsrate seit Anfang des Jahres (Juli 2016 verglichen zu Dezember 2015) betrug -0,2 % und die j\u00e4hrliche Inflation im Juli 2016 verglichen zu Juli 2015 betrug -0,2 %.",
		"tgt": "The inflation rate since the beginning of the year (July 2016 compared to December 2015) has been -0.2% and the annual inflation in July 2016 compared to July 2015 was -0.2%."
	},
	{
		"src": "Im Juli 2016 wurde im Vergleich zum Vormonat ein Preisanstieg der folgenden Gruppen von Konsumg\u00fctern beobachtet: Lebensmittel und nichtalkoholische Getr\u00e4nke (1,7 %); Transport (1,8 %); Freizeit und Kultur (6,3 %); Restaurants und Hotels (1,2 %); verschiedene G\u00fcter und Dienstleistungen (0,3 %).",
		"tgt": "In July 2016, compared to the previous month, an increase was observed in the price of the following groups of consumer goods: food and non-alcoholic beverages (1.7%); transport (1.8%); recreation and culture (6.3%); restaurants and hotels (1.2%); miscellaneous goods and services (0.3%)."
	},
	{
		"src": "Die Preise fielen bei Kleidung und Schuhen (2,2 %); Mobiliar, Haushaltsger\u00e4ten und Routinewartungen (0,5 %); Gesundheit (0,1 %).",
		"tgt": "Prices decreased in clothing and footwear (2.2%); furnishings, household equipment and routine maintenance (0.5%); health (0.1%)."
	},
	{
		"src": "Die Preise blieben wie im Vormonat bei alkoholischen Getr\u00e4nken und Tabak; Wohnungen, Wasser, Strom, Gas und sonstigen Kraftstoffen; Kommunikation; sowie Bildung unver\u00e4ndert.",
		"tgt": "Prices remained at the same level as in the previous month in alcoholic beverages and tobacco; housing, water, electricity, gas and other fuels; communications; and education."
	},
	{
		"src": "Snapchat \"Anime\"-Effekt als asiatische Karikatur kritisiert",
		"tgt": "Snapchat \"Anime\" Effect Is Criticized as Asian Caricature"
	},
	{
		"src": "Snapchat sagt, dass dieser Filter Anime-inspiriert ist, aber manche Beobachter sagen, dass es unsensibel gegen\u00fcber Rassen ist.",
		"tgt": "Snapchat says this filter is inspired by anime, but some observers say it's racially insensitive."
	},
	{
		"src": "Mit seinem Filtertool erm\u00f6glicht es Snapchat rund 150 Millionen t\u00e4glichen Usern, die Realit\u00e4t zu ver\u00e4ndern und mit Identit\u00e4ten auf so eine Art und Weise zu spielen, die schon ans Absurde grenzt.",
		"tgt": "With its lens tool, Snapchat allows some 150 million daily users to alter reality and play with identity in ways that border on the absurd."
	},
	{
		"src": "Sie k\u00f6nnen sich in eine Ananas, einen Hund oder eine Figur verwandeln, die aus einem Roy Lichtenstein Gem\u00e4lde sein k\u00f6nnte.",
		"tgt": "You can turn yourself into a pineapple, a dog or a character befitting a Roy Lichtenstein painting."
	},
	{
		"src": "Die Filter sind unverbl\u00fcmte, eigenschaftsverdrehende Tools, die mehr als 30 Millionen verbesserte Selfies pro Tag erzeugen.",
		"tgt": "The lenses are blunt, feature-warping tools that generate more than 30 million enhanced selfies a day."
	},
	{
		"src": "S\u00e4mtliche Fehltritte gelangen an die \u00d6ffentlichkeit.",
		"tgt": "Any missteps quickly enter the public record."
	},
	{
		"src": "Snapchat-Filter haben in der Vergangenheit Kritik auf sich gezogen, in der sie beschuldigt wurden, dass die App Blackface f\u00f6rdere oder wei\u00dfe Haut als Sch\u00f6nheitsideal propagieren w\u00fcrde.",
		"tgt": "Snapchat lenses have drawn criticism in the past with accusations that the app was promoting blackface or encouraging whitened skin tones as an ideal of beauty."
	},
	{
		"src": "Als es diese Woche einigen Usern einen Filter vorschlug, der ihnen Schlitzaugen, falsche Z\u00e4hne und aufgedunsene Wangen gab, nannten es einige Kritiker eine rassistische Karikatur von Asiaten - \"Gelbgesicht\".",
		"tgt": "So when it pushed a lens to some users this week that gave them slanted eyes, distorted teeth and puffy cheeks, some critics called it a racist caricature of Asian people - \"yellowface.\""
	},
	{
		"src": "Sie fragten sich, ob diese wiederholten Kontroversen auf ein gr\u00f6\u00dferes Problem hinwiesen, dass das Unternehmen mit Diversit\u00e4t hat.",
		"tgt": "And they wondered if these repeated controversies pointed to a larger problem that the company has with diversity."
	},
	{
		"src": "Die Nachrichten und die Emp\u00f6rung wurden am Mittwoch weit verbreitet, mit Berichten von The Verge und Motherboard, einen Tag nachdem Snapchat mitteilte, dass es das Feature deaktiviert h\u00e4tte.",
		"tgt": "The news and the outrage went wide on Wednesday, with reports by The Verge and Motherboard, a day after Snapchat said it had dismantled the feature."
	},
	{
		"src": "Das Unternehmen bot eine Entschuldigung: Der Filter war als Hommage an Anime-Charaktere und nicht als Karikatur von Asiaten gedacht.",
		"tgt": "The company offered an explanation: The lens was meant as homage to anime characters, not as a caricature of Asian people."
	},
	{
		"src": "Aber Au\u00dfenstehende, die Rassissmus erlebt haben, erinnerte der Filter an verletzende Klischees.",
		"tgt": "But for observers who have experienced racism, the lens reminded them of hurtful stereotypes in action."
	},
	{
		"src": "Andere lehnten den Anime-Vergleich entschieden ab.",
		"tgt": "Others roundly rejected the anime comparison."
	},
	{
		"src": "In einer E-Mail schrieb Grace Sparapani, eine koreanisch-amerikanische Kunststudentin, deren Tweet \u00fcber die Fotos weit verbreitet wurden, dass der Filter \"verletzend und gelinde gesagt unangenehm war.\"",
		"tgt": "In an email, Grace Sparapani, a Korean American art student whose tweet about the photos was widely shared, said that the lens was \"hurtful and uncomfortable to say the least.\""
	},
	{
		"src": "Sie f\u00fcgte hinzu, dass \"es schwierig sei mit der Gegen\u00fcberstellung einer sehr widerlichen asiatischen Karikatur und den Filtereffekten zu argumentieren.",
		"tgt": "She added that \"it's hard to argue with the side by side comparison of the very gross Asian caricature and the filter's effects."
	},
	{
		"src": "Es zeigt, dass der Filter nicht gelbgesichtig ist, sondern dass das Gelbgesicht ins abwertende Extrem gezogen wurde.",
		"tgt": "It shows that the filter isn't just yellowface, but yellowface taken to its derogatory extreme."
	},
	{
		"src": "Snapchat ist nicht das einzige Unternehmen, das diese kulturellen Stolperdrahte \u00fcberquert.",
		"tgt": "Snapchat is not the only company to cross these cultural tripwires."
	},
	{
		"src": "Die amerikanische Kultur scheint in einen endlosen Diversit\u00e4ts- und Integrationskampf verwickelt zu sein, von Konferenzr\u00e4umen bis zu Hollywood und den Ger\u00e4ten, die wir alle in der Hand halten.",
		"tgt": "American culture seems involved in an endless struggle over diversity and inclusion, from corporate boardrooms to Hollywood and the devices we all carry in our hands."
	},
	{
		"src": "Und Snapchats gro\u00dfes Publikum junger Leute - die in Sachen Rasse diverser als ihre \u00e4lteren Gegenspieler sind - k\u00f6nnten eher davon ausgehen, Sensibilit\u00e4t zu erwarten.",
		"tgt": "And Snapchat's huge audience of younger people - who are more racially diverse than their older counterparts - might mean that they are even more likely to expect sensitivity."
	},
	{
		"src": "Wenn einer von Snapchats Filtern ein Bild erzeugt, dass f\u00fcr einen User beleidigend ist, \"so ist es viel schwieriger, dass solche Sachen unbemerkt bleiben, als es fr\u00fcher der Fall war,\" sagte die 25-j\u00e4hrige Katie Zhu in einem Interview am Donnerstag.",
		"tgt": "When one of Snapchat's lenses creates an image that is insulting to a user, 25-year-old Katie Zhu said in an interview on Thursday, \"it's much harder for these types of things to go unnoticed like they did before.\""
	},
	{
		"src": "Am Donnerstag entschied sich Zhu, die als Produktmanagerin und Ingenieurin f\u00fcr Medium arbeitet, ihr Snapchat-Konto zu l\u00f6schen forderte andere auf, dasselbe zu tun.",
		"tgt": "On Thursday, Ms. Zhu, a product manager and engineer who works for Medium, decided to delete her Snapchat account and encouraged others to do the same."
	},
	{
		"src": "In einem Aufsatz f\u00fcr Medium und in einem Telefoninterview sagte sie, dass sie glaube, dass rassenbezogene Kontroversen einen Mangel an Diversit\u00e4t bei den Einstellungspraktiken bei Snapchat widerspiegeln.",
		"tgt": "In an essay for Medium and in a telephone interview, she said she believed that the race-related controversies reflected a lack of diversity in hiring practices at Snapchat."
	},
	{
		"src": "Zhu kritisierte die zum gro\u00dfen Teil wei\u00dfe, nur m\u00e4nnliche F\u00fchrerschaft und beendete ihren Aufsatz mit einem Hashtag: #DeleteSnapchat.",
		"tgt": "Ms. Zhu criticized the company's mostly white, all-male leadership and ended her essay with a hashtag: #DeleteSnapchat."
	},
	{
		"src": "\"Entweder habe sie keine diverse Repr\u00e4sentation von Menschen mit anderen Hautfarben in ihrer Belegschaft, sodass sie solche Entscheidungen treffen k\u00f6nnen,\" sagte die chinesich-amerikanische Zhu, \"oder sie haben Menschen mit anderen Hautfarben, die dort arbeiten, aber nicht in Positionen sind, in denen sie sich sicher oder wohlf\u00fchlen, um was dagegen zu sagen.\"",
		"tgt": "\"It's either that they had no diverse representation of people of color on their staff to the point where they're able to make decisions like this,\" Ms. Zhu, who is Chinese-American, said, \"or they do have some people of color who are working there, but they're not on positions where they feel safe or comfortable to speak up.\""
	},
	{
		"src": "Andere teilen ihre Meinung, eine Beschwerde, die Snapchat gr\u00f6\u00dftenteils unbeantwortet gelassen hat.",
		"tgt": "Other observers share her view, a complaint that Snapchat has left largely unanswered."
	},
	{
		"src": "Das Unternehmen ver\u00f6ffentlicht keine Zahlen zur Diversit\u00e4t seiner Belegschaft und weist auf seinen Status als privates Unternehmen hin.",
		"tgt": "The company does not release figures about diversity on its staff, noting its status as a private company."
	},
	{
		"src": "Am Donnerstag lehnte es Snapchat ab, die kulturellen Hintergr\u00fcnde seiner Mitarbeiter zu diskutieren, aber laut eines Sprechers hat das Unternehmen k\u00fcrzlich einen Personalverantwortlichen eingestellt, der sich auf unterrepr\u00e4sentierte Bev\u00f6lkerungsgruppen und auf interne Integrationsbem\u00fchungen konzentriert.",
		"tgt": "On Thursday, Snapchat declined to discuss the racial backgrounds of its staff, but according to a spokesman, the company recently hired a recruiter to focus on underrepresented populations and on driving inclusion efforts internally."
	},
	{
		"src": "Zhu sagte ihrerseits, dass sie ihr Snapchat-Konto geschlossen lassen wird und f\u00fcgte hinzu, \"ich frage mich, ob sie mehr User wie uns brauchen, um sagen zu k\u00f6nnen, dass das nicht O.K. ist.\"",
		"tgt": "For her part, Ms. Zhu said she would keep her Snapchat account closed, adding, \"I wonder if they actually need more users like us to be able to say that this is not O.K.\""
	},
	{
		"src": "Milit\u00e4rf\u00fchrung verf\u00e4lsche ISIS Geheimdienstinformationen, stellt Ausschuss des Kongresses fest",
		"tgt": "Military Officials Distorted ISIS Intelligence, Congressional Panel Says"
	},
	{
		"src": "Milit\u00e4rangeh\u00f6rige des United States Central Command ver\u00e4nderten nachrichtendienstliche Informationen, um ein optimistischeres Bild des Krieges gegen den sog. Islamischen Staat im Irak und in Syrien zu zeichnen als es die tats\u00e4chlichen Zust\u00e4nde vor Ort erlaubt h\u00e4tten, meldete ein Untersuchungsausschuss des Kongresses in einem Bericht am Donnerstag.",
		"tgt": "Officials from the United States Central Command altered intelligence reports to portray a more optimistic picture of the war against the Islamic State in Iraq and Syria than events on the ground warranted, a congressional panel said in a report issued Thursday."
	},
	{
		"src": "Der vorl\u00e4ufige Report, erstellt durch eine Task Force der republikanischen Mitglieder des Streitkr\u00e4ftekommitees, Geheimdienstkommitees und des Wehrbudgetkommites, berichtet von gro\u00dfer Unzufriedenheit unter Central Command Geheimdienstanalysten, die berichteten, wie Vorgesetzte ihre Einsch\u00e4tzungen zu den amerikanischen Anstrengungen im Kampf gegen den Islamischen Staat ver\u00e4nderten.",
		"tgt": "The interim report, from a task force established by the Republican chairmen of the House Armed Services Committee, Intelligence Committee and Defense Appropriations Subcommittee, found \"widespread dissatisfaction\" among Central Command intelligence analysts, who said superiors were doctoring their assessments of American efforts to defeat the Islamic State."
	},
	{
		"src": "Das Central Command, kurz Cencom, ist das milit\u00e4rische Hauptquartier in Tampa, Florida, das die amerikanischen Milit\u00e4roperationen im Nahen Osten und Zentralasien steuert.",
		"tgt": "Central Command, known as Centcom, is the military headquarters in Tampa, Fla., that oversees American military operations across the Middle East and Central Asia."
	},
	{
		"src": "\"Nachrichtendienstliche Informationen, die von hochrangigen Centcom Kommandeuren typischerweise abgenickt wurden, zeichneten regelm\u00e4\u00dfig ein positiveres Bild von den amerikanischen Anstrengungen gegen den Terrorismus als es die tats\u00e4chlichen Zust\u00e4nde vor Ort erlaubt h\u00e4tten und waren durchg\u00e4ngig positiver als Analysen anderer Nachrichtendienste\", zitierte ein Zeitungsartikel den Bericht.",
		"tgt": "\"Intelligence products approved by senior Centcom leaders typically provided a more positive depiction of U.S. antiterrorism efforts than was warranted by facts on the ground and were consistently more positive than analysis produced by other elements of the intelligence community,\" a news release about the report said."
	},
	{
		"src": "\"Was beim Centcom geschehen ist, ist inakzeptabel - unsere Soldaten leiden, wenn schlechte Analysen unseren politischen F\u00fchrern pr\u00e4sentiert werden\", stellte Ken Calvert, republikanisches Mitglied des Repr\u00e4sentantenhauses, fest.",
		"tgt": "\"What happened at Centcom is unacceptable - our war fighters suffer when bad analysis is presented to senior policy makers,\" said Representative Ken Calvert, Republican of California."
	},
	{
		"src": "Die F\u00fchrungsfehler im Centcom reichen bis zur obersten Spitze der Organisation.",
		"tgt": "The leadership failures at Centcom reach to the very top of the organization."
	},
	{
		"src": "Der zehnseitige Bericht zeigt detailliert best\u00e4ndige Probleme in den Jahren 2014 und 2015 in den Beschreibungen und Analysen der amerikanischen Anstrengungen in der Ausbildung der irakischen Streitkr\u00e4fte.",
		"tgt": "The 10-page report detailed persistent problems in 2014 and 2015 in Central Command's description and analysis of American efforts to train Iraqi forces."
	},
	{
		"src": "Obwohl es keine direkten Hinweise darauf liefert, dass Regierungsspitzen unter Obama Anweisungen gegeben haben, die Berichte zu ver\u00e4ndern, zeigt es, wie Analysten sich dem Druck von ihren Vorgesetzen ausgesetzt sahen, ein optimistischeres Bild von der Bedrohung des Islamischen Staates, auch bekannt als ISIS oder ISIL, zu zeichnen.",
		"tgt": "Although it offers no definitive evidence that senior Obama administration officials ordered the reports to be doctored, it describes analysts as feeling as though they were under pressure from Centcom leaders to present a more optimistic view of the threat posed by the Islamic State, also known as ISIS or ISIL."
	},
	{
		"src": "\"W\u00e4hrend des ersten Halbjahres 2015 waren viele Central Command Pressemitteilungen, Stellungnahmen und Aussagen vor dem Kongress deutlich positiver als es den Tatsachen entspricht\" stellte der Bericht fest.",
		"tgt": "\"Throughout the first half of 2015, many Central Command press releases, statements and congressional testimonies were significantly more positive than actual events,\" the report said."
	},
	{
		"src": "Zum Beispiel gab ein Centcom Angeh\u00f6riger \u00f6ffentlich bekannt, dass eine milit\u00e4rische R\u00fcckeroberung Mossuls bereits im April oder Mai 2015 beginnen k\u00f6nne.",
		"tgt": "For example, a Centcom official stated publicly that a major military assault to take back Mosul could begin as early as April or May 2015."
	},
	{
		"src": "Mossul, zweitgr\u00f6\u00dfte Stadt des Irak, bleibt weiterhin unter der Kontrolle des Islamischen Staates.",
		"tgt": "Mosul, Iraq's second-largest city, remains under the control of the Islamic State."
	},
	{
		"src": "\"Nach Monaten von Ermittlungen, ist soviel klar.\" sagte Mike Pompeo, republikanischer Kongressabgeordneter aus Kansas, in einer Stellungnahme.",
		"tgt": "\"After months of investigation, this much is very clear,\" Representative Mike Pompeo, Republican of Kansas, said in a statement."
	},
	{
		"src": "Von der Mitte des Jahres 2014 bis zur Mitte des Jahres 2015 ver\u00e4nderten die Spitzen des Central Command die nachrichtendienstlichen Berichte, um die Gefahr durch ISIS im Irak herunterzuspielen.",
		"tgt": "From the middle of 2014 to the middle of 2015, the United States Central Command's most senior intelligence leaders manipulated the command's intelligence products to downplay the threat from ISIS in Iraq."
	},
	{
		"src": "Die Republikaner riefen die Task Force ins Leben, nachdem ihnen zugespielt wurde, dass Analysten sich Sorgen hinsichtlich der Manipulation von Berichten zum Islamischen Staat machten.",
		"tgt": "Republicans created the task force after learning that analysts had raised concerns that intelligence about the Islamic State was being manipulated."
	},
	{
		"src": "Der am Donnerstag ver\u00f6ffentlichte Bericht wird noch durch detailliertere Erkenntnisse vervollst\u00e4ndigt werden w\u00e4hrend die Ermittlungen fortgesetzt werden.",
		"tgt": "The report released Thursday is to be followed up by more extensive findings as the investigation continues."
	},
	{
		"src": "Zus\u00e4tzlich sind weitere Ermittlungen der Centcom Berichte durch den Generalinspekteur des Verteidigungsministeriums im Gange.",
		"tgt": "There is an additional, ongoing investigation of Centcom intelligence by the Department of Defense inspector general."
	},
	{
		"src": "Demokratische Mitglieder des Nachrichtendienstekomittees ver\u00f6ffentlichten am Donnerstag ihre eigenen Erkenntnisse, die mit manchen der Schlussfolgerungen der republikanischen Task Force \u00fcbereinstimmten.",
		"tgt": "Democratic members of the House Intelligence Committee released their own findings on Thursday that agreed with some of the conclusions of the Republican task force."
	},
	{
		"src": "\"In den Jahren 2014 und 2015 kreierte das Centcom einen \u00fcberm\u00e4\u00dfig eingeschr\u00e4nkten Prozess f\u00fcr die Erstellung von nachrichtendienstlichen Einsch\u00e4tzungen zu ISIL und den irakischen Sicherheitsdiensten\", gab der h\u00f6chstrangige Demokrat im Kommittee, Mitglied im Repr\u00e4sentantenhaus Adam B. Schiff, in einer Stellungnahme bekannt.",
		"tgt": "\"Between 2014 and 2015, Centcom created an overly insular process for producing intelligence assessments on ISIL and Iraqi Security Forces,\" Representative Adam B. Schiff, the committee's top Democrat, said in a statement."
	},
	{
		"src": "Dieser Prozess, so Mr. Schiff, \"verz\u00f6gerte die Ver\u00f6ffentlichung von nachrichtendienstlichen Berichten\", sch\u00e4digte die Moral unter Analysten und \"gab \u00fcberm\u00e4\u00dfig wenig Raum f\u00fcr abweichende Meinungen.\"",
		"tgt": "This process, Mr. Schiff said, \"stalled the release of intelligence products,\" hurt morale among analysts and \"insufficiently accommodated dissenting views.\""
	},
	{
		"src": "Aber Mr. Schiff und die Demokraten gaben an, keine Hinweise auf ein Eingreifen des Wei\u00dfen Hauses bei den Centcom Analysten hinsichtlich einer \"bestimmten politischen Meinung\" gefunden zu haben.",
		"tgt": "But Mr. Schiff and the Democrats said they found no evidence that the White House tried to pressure Centcom analysts to fit their conclusions to a \"preset or political narrative.\""
	},
	{
		"src": "Die vorl\u00e4ufigen Ergebnisse der Ermittlungen des Kongresses wurden am Dienstag durch \"The Daily Beast\" ver\u00f6ffentlicht.",
		"tgt": "The preliminary results of the congressional investigation were reported Tuesday by The Daily Beast."
	},
	{
		"src": "Im vergangenen August berichtete die New York Times von Ermittlungen durch den Generalinspekteur des Pentagon, die nach Beschwerden von Centcom Analysten aufgenommen wurden.",
		"tgt": "Last August, The New York Times reported the existence of the Pentagon inspector general investigation, opened after complaints by Centcom analysts."
	},
	{
		"src": "Lt. Cmdr. Patrick Evans, ein Pressesprecher des Pentagon, gab in einer Stellungnahme an, dass das Verteidigungsministerium keine Berichte des Kongresses kommentieren w\u00fcrde, w\u00e4hrend die Ermittlungen des Generalinspekteurs noch im Gange seien.",
		"tgt": "Lt. Cmdr. Patrick Evans, a Pentagon spokesman, said in a statement that the Defense Department would not comment on the congressional report while the inspector general's investigation continued."
	},
	{
		"src": "Aber er gab auch an, dass \"Experten manchmal durchaus divergierende Meinungen hinsichtlich der Interpretation komplexer Daten haben, und dass die Nachrichtendienste und das Verteidigungsministerium eine kontroverse Diskussion dieser wichtigen Themen der nationalen Verteidigung begr\u00fc\u00dfen.\"",
		"tgt": "But he said that \"experts sometimes disagree on the interpretation of complex data, and the intelligence community and Department of Defense welcome healthy dialogue on these vital national security topics.\""
	},
	{
		"src": "Die Ermittlungen haben R\u00fcckwirkungen \u00fcber die Frage einer erfolgreichen Luftkampagne unter amerikanischer F\u00fchrung im Irak und Syrien hinaus (eine Behauptung, die inzwischen von einer wachsenden Zahl von Angeh\u00f6rigen des Verteidigungsministeriums gemacht wird).",
		"tgt": "The investigation has repercussions beyond the question of whether the American-led bombing campaign in Iraq and Syria is succeeding (an assertion now made by a growing number of Defense officials)."
	},
	{
		"src": "Die Anschuldigungen des vergangenen Jahres haben jedoch die Frage aufgeworfen, inwiefern Pr\u00e4sident Obama sich auf das Central Command f\u00fcr ehrliche Einsch\u00e4tzungen der milit\u00e4rischen Operationen im Irak, Afghanistan, Libyen und anderen Krisenregionen verlassen kann.",
		"tgt": "But last year's allegations called into question how much President Obama could rely on Central Command for honest assessments of military operations in Iraq, Afghanistan, Libya and other crisis spots."
	},
	{
		"src": "Die Kritik hinsichtlich der Geheiminformationen \u00fcber den Islamischen Staat erinnern an Zwistigkeiten von vor mehr als zehn Jahren, als ein Centcom Analyst, Gregory Hooker, ein Schriftst\u00fcck dar\u00fcber verfasste, wie die damalige Regierung unter George W. Bush entgegen der Empfehlungen vieler Analysten nur eine kleine Besatzungstruppe im Irak vorsah und wenig Zeit darauf verwand, sich \u00fcber die Folgen der Invasion von 2003 Gedanken zu machen.",
		"tgt": "The critiques on the Islamic State intelligence mirror disputes of more than a decade ago, when a Centcom intelligence analyst, Gregory Hooker, wrote a research paper saying that the administration of President George W. Bush, over many analysts\" objections, advocated a small force in Iraq and spent little time thinking about what would follow the 2003 invasion."
	},
	{
		"src": "Mr. Hooker spielte auch eine Schl\u00fcsselrolle beim Aufstand gegen die derzeitige Berichterstattung \u00fcber den Islamischen Staat.",
		"tgt": "Mr. Hooker also played a key part in the insurrection over the Islamic State intelligence."
	},
	{
		"src": "Im vergangenen Jahr stellt das Team um Mr. Hooker nach Angabe von Regierungsstellen fest, dass entgegen der Aussagen der Regierung Luftschl\u00e4ge gegen die vom Islamischen Staat gehaltenen Raffinerien keine signifikanten Auswirkungen auf die Finanzlage der Terrorgruppe h\u00e4tten, da diese provisorische Raffinerien in Betrieb genommen h\u00e4tten, um \u00d6l auf dem Schwarzmarkt zu verkaufen.",
		"tgt": "Last year, officials said, Mr. Hooker's team concluded that despite public statements to the contrary, airstrikes against Islamic State-held refineries had not significantly weakened the terrorist group's finances because it had built makeshift refineries to sell oil on the black market."
	},
	{
		"src": "Diese Erkenntnis wurde jedoch nicht ver\u00f6ffentlicht, berichtete die Times im September.",
		"tgt": "But the finding was not distributed outside Central Command, The Times reported in September."
	},
	{
		"src": "Centcoms damaliger Befehlshaber, Gen. Lloyd J. Austin III, wurde von Mitgliedern der Legislative wegen seiner \u00fcberm\u00e4\u00dfig positiven Einsch\u00e4tzung der Kriegslage bei einer Anh\u00f6rung vor dem Senat kritisiert.",
		"tgt": "Centcom's commander then, Gen. Lloyd J. Austin III, came under criticism last year after Senate testimony viewed by many lawmakers as being an overly positive assessment of the war."
	},
	{
		"src": "General Austin ging im April in den Ruhestand und wurde beim Central Command durch Gen. Joseph L. Votel ersetzt.",
		"tgt": "General Austin retired in April and was replaced at Central Command by Gen. Joseph L. Votel."
	},
	{
		"src": "Die USA gewinnen viertes Match im Feldhockey der Frauen, ein Showdown mit Gro\u00dfbritannien steht bevor",
		"tgt": "U.S. Wins 4th Straight in Women's Field Hockey, Setting Up Showdown With Britain"
	},
	{
		"src": "Einen Tag, nachdem sie drei Tore w\u00e4hrend eines 6-1 Siegs \u00fcber Japan geschossen hatte, machte Katie Bam auch die ersten zwei Tore f\u00fcr das amerikanische Feldhockeyteam der Frauen in einem Match am Donnerstag gegen Indien, dass die Amerikanerinnen mit 3-0 gewannen.",
		"tgt": "One day after scoring three goals in a 6-1 victory over Japan, Katie Bam scored the first two goals for the United States women's field hockey team on Thursday as the Americans defeated India, 3-0."
	},
	{
		"src": "F\u00fcnf Tore in zwei Spielen sollten eigentlich eine denkw\u00fcrdige Leistung darstellen, aber Bam (27) sagte, sie k\u00f6nne sich nicht daran erinnern, das jemals getan zu haben.",
		"tgt": "Five goals in two games should be a memorable feat, but Bam, 27, said she was not sure if she had ever done the same thing."
	},
	{
		"src": "\"Ich habe keine Ahnung.\" sagte sie.",
		"tgt": "\"I have no clue,\" she said."
	},
	{
		"src": "Ich geh\u00f6re nicht zu den Leuten, die ihre Tore im Ged\u00e4chtnis behalten.",
		"tgt": "I'm not really one of those people who keeps track of their goals."
	},
	{
		"src": "Das wei\u00df sie allerdings: Die Amerikanerinnen liegen bei 4-0 im olympischen Wettkampf und sind gleichauf in ihrer Gruppe mit den Britinnen auf dem ersten Platz, die nach ihrem 2-0 Sieg gegen Japan ungeschlagen bleiben.",
		"tgt": "Here is what she does know: The Americans are 4-0 in the Olympic tournament and are tied for first place in their group with Britain, which remained unbeaten after defeating Japan, 2-0, on Thursday."
	},
	{
		"src": "Gro\u00dfbritannien und die Vereinigten Staaten werden am Samstag im letzten Spiel der ersten Runde aufeinandertreffen.",
		"tgt": "Britain and the United States will meet on Saturday in the last game of the first round."
	},
	{
		"src": "Beide Mannschaften haben sich bereits f\u00fcr das Viertelfinale qualifiziert, das Spiel wird entscheiden, welche der beiden innerhalb ihrer Gruppe aus sechs Teams jeweils den ersten und den zweiten Platz erlangen wird.",
		"tgt": "Both teams have qualified for the quarter finals, and the game will decide who finishes first in their six-team bracket and who finishes second."
	},
	{
		"src": "Der Erstplatzierte wird den starken Holl\u00e4nderinnen etwas l\u00e4nger aus dem Weg gehen, die die andere Gruppe anf\u00fchren.",
		"tgt": "The first-place finisher will avoid the powerful Dutch, the leaders of the other bracket, for a bit longer when the quarter finals begin."
	},
	{
		"src": "Wie auch immer das Spiel am Samstag ausgehen mag, die Amerikanerinnen haben durch ihre Erfolgsgeschichte einen \u00fcberraschenden Wirbel ausgel\u00f6st, vier Jahre nachdem sie bei den vergangenen London Games auf dem letzten von 12 Pl\u00e4tzen landeten.",
		"tgt": "However Saturday's game turns out, the Americans have created a stir with their surprising run here, four years after finishing last among 12 teams at the London Games."
	},
	{
		"src": "Bam war Teil dieses Teams.",
		"tgt": "Bam was on that team."
	},
	{
		"src": "Sie wuchs in Blue Bell, Pennsylvania auf, und hatte das erste Mal mit drei Jahren einen Hockeyschl\u00e4ger in H\u00e4nden (ihre beiden \u00e4lteren Schwestern spielten den Sport an der Drexel Universit\u00e4t), mit 16 Jahren wurde sie Nationalspielerin der USA, die j\u00fcngste in der Geschichte des Teams.",
		"tgt": "She grew up in Blue Bell, Pa., first picked up a field hockey stick when she was 3 (her twin older sisters played the sport at Drexel) and joined the national team when she was 16, becoming its youngest player ever."
	},
	{
		"src": "Sie verpasste die Olympiade im Jahr 2008, da sie sich nicht f\u00fcr den Kader qualifizieren konnte.",
		"tgt": "She missed out on the 2008 Olympics when she did not make the cut for the final roster."
	},
	{
		"src": "Dann kam das Jahr 2012, in dem f\u00fcr sie und ihr Team alles schiefging.",
		"tgt": "Then came 2012, when nothing much went right for her and her teammates."
	},
	{
		"src": "Im darauffolgenden Jahr wurde Craig Parnham, ein Engl\u00e4nder, Trainer des Nationalteams und damit begannen sich die Dinge zum besseren zu wenden.",
		"tgt": "The next year, Craig Parnham, an Englishman, was named the coach, and things began to change."
	},
	{
		"src": "\"Ein Kulturwechsel, ein mentaler Wechsel und ein k\u00f6rperlicher Wechsel\", sagte Bam.",
		"tgt": "\"A cultural change, a mental change, a physical change,\" Bam said."
	},
	{
		"src": "Wir hatten nicht das Arbeitspensum in London, das wir jetzt haben.",
		"tgt": "We didn't have the work rate in London that we have now."
	},
	{
		"src": "Wir haben das Ruder komplett herumrei\u00dfen k\u00f6nnen.",
		"tgt": "We've made a complete turnaround."
	},
	{
		"src": "Am Donnerstagabend er\u00f6ffnete Bam den Torreigen in der ersten H\u00e4lfte des Spiels mit einem R\u00fcckhandschlag aus dem Nahbereich.",
		"tgt": "On Thursday night, Bam opened the scoring in the first half with a backhand shot from close in."
	},
	{
		"src": "Indien war ohne Sieg im Turnier in das Spiel gegangen, aber das Team zeigte sich \u00fcberraschend z\u00e4h und hielt den Spielstand von 1-0 bis in das dritte Viertel, bis Bam das Spiel in ihre H\u00e4nde nahm.",
		"tgt": "India had come into the game without a victory in the tournament, but the team proved surprisingly tough and kept the score 1-0 until late in the third period, when Bam took charge."
	},
	{
		"src": "Sie vollf\u00fchrte einen Sprint mit dem flachen Ball \u00fcber die linke Flanke, zog dann in die Mitte und lupfte den Ball in das Tor um den Amerikanerinnen eine 2-0 F\u00fchrung zu verschaffen.",
		"tgt": "She made a long run with the ball down the left side of the field, then curled into the middle and whipped the ball into the goal to give the Americans a 2-0 lead."
	},
	{
		"src": "Melissa Gonzalez machte das finale Tor in der Mitte des letzten Viertels.",
		"tgt": "Melissa Gonzalez added the final goal midway through the fourth period."
	},
	{
		"src": "Der Shutout war der erste des ganzen Turniers f\u00fcr die Torh\u00fcterin der USA, Jackie Briggs, die bisher jeweils ein Tor in jedem der vorherigen Spiele verbuchen musste.",
		"tgt": "The shutout was the first of the tournament for the United States goalie, Jackie Briggs, who had allowed one goal in each of the first three victories."
	},
	{
		"src": "Sie hat einen Lauf.",
		"tgt": "She is on a roll."
	},
	{
		"src": "Genauso wie Bam.",
		"tgt": "So is Bam."
	},
	{
		"src": "\"Wir sind in einer guten Position\" sagte Parnham, aber wie gut wird vom Ergebnis des n\u00e4chsten Spiels am Samstag abh\u00e4ngen.",
		"tgt": "\"We're in a good place right now,\" Parnham said, but just how good it is will depend on the result of Saturday's game."
	},
	{
		"src": "Inmitten der Rage der Olympischen Spiele, das Zen des Trampolins",
		"tgt": "Amid the Fury of the Olympics, the Zen of the Trampoline"
	},
	{
		"src": "Wo immer Sie auch sind, wie sp\u00e4t es auch ist, es sind die Olympischen Spiele.",
		"tgt": "Wherever you are, whatever time it is, it is the Olympics."
	},
	{
		"src": "Die Veranstaltungen in Rio de Janeiro f\u00fchlen sich best\u00e4ndig und unausweichlich an, ein rasender Staffellauf zwischen Wettbewerb und Streben.",
		"tgt": "The events in Rio de Janeiro feel constant and inescapable, a furious relay of competition and striving."
	},
	{
		"src": "Es ist, als w\u00e4re die olympische Fackel selbst ein brennender Stab, der vom Armbrustsch\u00fctzen zum Schwimmer zum Turner zum Triathleten gereicht wird.",
		"tgt": "It is as if the Olympic torch itself were a flaming baton, passed from archer to swimmer to gymnast to triathlete."
	},
	{
		"src": "Sie k\u00f6nnen nicht den Fernseher einschalten, eine Zeitung lesen oder beim Gespr\u00e4ch Ihres Nachbarn in der Warteschlange im Coffeshop zuh\u00f6ren, ohne \u00fcber Simone Biles, Katie Ledecky oder dem Streit zwischen Michael Phelps und Chad le Clos zu h\u00f6ren.",
		"tgt": "You can't turn on a television, read a newspaper or listen in on your neighbor's conversation in a coffee-shop line without hearing about Simone Biles, Katie Ledecky or the feud between Michael Phelps and Chad le Clos."
	},
	{
		"src": "Und dann gibt es noch Logan Dooley.",
		"tgt": "And then there is Logan Dooley."
	},
	{
		"src": "Dooley, der zum ersten Mal bei den Olympischen Spielen dabei und ein Frauenschwarm mit Gr\u00fcbchen ist, h\u00e4tte durchaus unter diesen bekannten Namen sein k\u00f6nnen, die zur Prime Time gesendet werden, aufgebaut durch Sponsoren und Wohlf\u00fchl-TV-Werbung, wenn er ein Schwimmer, Turner oder sogar Fechter w\u00e4re.",
		"tgt": "Mr. Dooley, a first-time Olympian and a dimpled heartthrob in the making, may well be among those household names being showcased in prime time, buoyed by sponsorships and feel-good TV commercials, if he were a swimmer, a gymnast or even a fencer."
	},
	{
		"src": "Aber Dooley, 28, aus Lake Forest, Kalifornien, k\u00e4mpft im olympischen Trampolinturnen um Gold.",
		"tgt": "But Mr. Dooley, 28, of Lake Forest, Calif., is competing for the gold in Olympic trampoline."
	},
	{
		"src": "Die olympische Flamme beleuchtet nicht jedes Ereignis gleich.",
		"tgt": "The Olympic flame does not illuminate each event equally."
	},
	{
		"src": "Weiter vom Zentrum, teilweise im Schatten befinden sich die Sportarten, die nicht allgemein anerkannt sind: Luftpistolenschie\u00dfen, Bogenschie\u00dfen, Badminton, Taekwondo.",
		"tgt": "Further from the center, partly in shadow, are those sports not universally acknowledged: air-pistol shooting, archery, badminton, taekwondo."
	},
	{
		"src": "Wir werden immer das Brustschwimmen haben und m\u00f6ge es lange herrschen.",
		"tgt": "We will always have the breaststroke, and long may it reign."
	},
	{
		"src": "Aber wenn ich bescheidenerweise Argumente f\u00fcr meinen bestimmten Liebling machen d\u00fcrfte, dann lassen Sie mich die Aufmerksamkeit auf den diskreten Charme des Trampolins lenken.",
		"tgt": "But if I may make a modest case for my particular favorite, let me call attention to the discreet charm of the trampoline."
	},
	{
		"src": "Obwohl das Trampolinspringen bereits seit 2000 ein olympisches Ereignis ist, als es in Sydney sein Deb\u00fct hatte, wurde es die letzten 16 Jahre so sp\u00e4rlich wahrgenommen, dass viele die, ich befragt hatte, nicht wussten, dass es \u00fcberhaupt eine Olympiasportart ist.",
		"tgt": "Though trampoline has been an Olympic event since 2000, when it debuted at the Sydney Games, it has spent the intervening 16 years so barely acknowledged that many I surveyed did not realize it was an Olympic sport at all."
	},
	{
		"src": "Das k\u00f6nnte auch regionale Ignoranz sein.",
		"tgt": "This may be a regional ignorance."
	},
	{
		"src": "Obwohl die USA Athleten zum Wettkampf schickte, hat es noch nie eine Medaille im Trampolinspringen gewonnen und bis 2012 einen Athleten gehabt, der es bis zur Endrunde geschafft hat.",
		"tgt": "Despite sending athletes to compete, the United States has never won a medal in trampoline and did not have an athlete advance to the finals until 2012."
	},
	{
		"src": "Die Chinesen und die Russen neigen dazu, sich die Preise f\u00fcr die M\u00e4nner und die Chinesen und die Kanadier die f\u00fcr die Frauen zu teilen.",
		"tgt": "The Chinese and the Russians tend to split the prizes for the men, and the Chinese and the Canadians for the women."
	},
	{
		"src": "Dong Dong aus China und Rosie MacLennan aus Kanada werden dieses Jahr ihre Goldmedaille aus London verteidigen.",
		"tgt": "Dong Dong of China and Rosie MacLennan of Canada will be defending their London gold medals this year."
	},
	{
		"src": "Das Trampolinspringen hat einen gewissen Au\u00dfenseitercharme, teilweise weil es f\u00fcr das unaufgekl\u00e4rte Ohr passender f\u00fcr eine Clownsschule als die f\u00fcr die Olympischen Spiele klingt.",
		"tgt": "But there is an underdog charm to trampoline, in part because it sounds, to the unenlightened ear, fitter for clown college than the Olympics."
	},
	{
		"src": "An dieser Stelle sollte ich zugeben, dass ich kein Experte, sondern nur ein erdgebundener Enthusiast bin.",
		"tgt": "Here I should confess that I am no expert, just an earthbound enthusiast."
	},
	{
		"src": "Es hat humoristisches Potenzial - das kartoonhafte Zittern seines nie zu enden wollendem Aufpralls - aber auch die Grazie des Turnens und Tauchens, die zwei Sportarten, die es im Wesentlichen vereint.",
		"tgt": "It does have comic potential - the cartoon quaver of its never-ending bounce - but also the grace of gymnastics and diving, the two sports it essentially combines."
	},
	{
		"src": "Das Wort \"Trampolin\" stammt von dem spanischen El Trampolin, was so viel bedeutet wie \"Sprungbrett.\"",
		"tgt": "The word \"trampoline\" derives from the Spanish el trampol\u00edn, meaning \"diving board.\""
	},
	{
		"src": "Aufstrebende Sieger springen auf einem gigantischen Trampolin, schie\u00dfen fast bis zu 30 Fu\u00df in die Luft und m\u00fcssen eine Reihe an fallenden Bewegungen (Drehen, Hechten und Saltos), bevor sie auf den F\u00fc\u00dfen landen.",
		"tgt": "Aspiring champions jump on a giant trampoline, shooting up to nearly 30 feet in the air, and are called upon to perform a series of tumbling moves (twists, pikes and somersaults) before eventually landing on their feet."
	},
	{
		"src": "Sie werden laut offiziellem Olympiaprogramm nach Ausf\u00fchrung, Schwierigkeitsgrad und \"Flugzeit\" bewertet.",
		"tgt": "They are judged on execution, difficulty and \"flight time,\" according to the official Olympic program."
	},
	{
		"src": "Zweiundrei\u00dfig Athleten aus 17 L\u00e4ndern, 16 M\u00e4nner und 16 Frauen, werden in Rio gegeneinander antreten.",
		"tgt": "Thirty-two athletes from 17 countries, 16 men and 16 women, will compete in Rio."
	},
	{
		"src": "Der gemeinsamste olympische Vektor ist geradeaus.",
		"tgt": "The most common Olympic vector is straight ahead."
	},
	{
		"src": "Medaillenhoffende m\u00fcssen in ihrem Streben nach Gold weiter, schneller, nach oben und dr\u00fcber gehen, manchmal bis zum Ziel, manchmal hin und zur\u00fcck, nach oben und nach unten auf dem Spielplatz.",
		"tgt": "Medal hopefuls must go farther, faster, up and over, in their quest for gold, sometimes to the finish, other times back and forth up and down the court."
	},
	{
		"src": "Sie jagen nicht nur die Ziellinie oder die Ausgangswand, sondern in der Fernseh\u00fcbertragung auch ein weiteres h\u00f6hnisches Ziel: die der Welt oder des Olympiarekords.",
		"tgt": "They are chasing not only the finish line or the starting wall but also, in the televised coverage, another taunting line: that of the world, or Olympic, record."
	},
	{
		"src": "Das zielgerichtete Streben ist nobel, bewundernswert, sogar fanatisch - und es ist genug, um sogar einen Zuschauer zu Tr\u00e4nen zu r\u00fchren.",
		"tgt": "This single-minded pursuit is noble, admirable, even fanatic - and it is enough to bring even a spectator to tears."
	},
	{
		"src": "Aber es ist auch das, was ich selbst beim Zuschauen dieser Spiele als etwas erm\u00fcdend empfinde.",
		"tgt": "But it is also what I find slightly exhausting about even watching the Games."
	},
	{
		"src": "Davon bietet das Trampolin eine Atempause.",
		"tgt": "From this, trampoline offers a respite."
	},
	{
		"src": "Der Vektor des Trampolinspringers ist oben.",
		"tgt": "The trampoliner's vector is up."
	},
	{
		"src": "Eine Vorw\u00e4rtsbewegung ist nicht das Ziel.",
		"tgt": "Forward motion is not the goal."
	},
	{
		"src": "Er oder sie prallt ab, scheinbar schwerelos wie ein Astronaut, geht nach oben, dann nach unten, dann m\u00fchelos wieder nach oben.",
		"tgt": "He or she rebounds, seeming weightless as an astronaut, going up, then down, then effortlessly up again."
	},
	{
		"src": "Auch hier herrscht ein Wettbewerb, selbstverst\u00e4ndlich nicht ohne Schwierigkeit, aber w\u00e4hrend der \u00dcbung gibt es keinen hektischen Angriff auf das Ziel, kein W\u00f6lben in die Ferne, nur die tr\u00e4umerische, elegante Aufhebung von Zeit und Schwerkraft.",
		"tgt": "It is not without competition, of course, nor without difficulty, but for the duration of a routine, there is no frantic charge toward the end, no vaulting into the distance, just the dreamy, graceful suspension of time and gravity."
	},
	{
		"src": "Es ist so Zen wie der Wettbewerb bei den Olympischen Spielen nur sein kann.",
		"tgt": "It is as close to Zen as Olympic competition gets."
	},
	{
		"src": "Die Qualifikations- und Endrunden der Frauen werden am Freitag nachmittag stattfinden, im Streaming um 13.00 Eastern Time; die der M\u00e4nner am Samstag, ebenfalls um 13.00.",
		"tgt": "The women's qualifiers and then finals will take place on Friday afternoon, streaming at 1 p.m. Eastern time; the men's on Saturday, also at 1."
	},
	{
		"src": "NBC wird die Endrunden als Teil eines Nachmittagblocks an beiden Tagen ab 14.00 ausstrahlen.",
		"tgt": "NBC will air the finals as part of an afternoon block beginning at 2 p.m. on both days."
	},
	{
		"src": "Inmitten der Olympia-Manie versprechen sie einen ruhigen, netten Moment, einen, der im allgemeinen Tumult wahrscheinlich \u00fcbersehen wird.",
		"tgt": "In the midst of Olympic mania, they promise a quiet, lovely moment, one likely to be overlooked in the general melee."
	},
	{
		"src": "Wenn die Bewusstseinssteigerung nur durch das Angaffen und die Objektifizierung m\u00e4nnlicher Athleten erreicht werden kann - wie es die m\u00e4nnlichen US-Turner laut dem The Wall Street Journal vor kurzem vorschlugen - dann erwartet Herrn Dooley seine nach Luft ringende, neue Fangemeinde.",
		"tgt": "And if consciousness raising is to be achieved only by offering up male athletes for ogling and objectification - as the United States men's gymnasts recently proposed, according to The Wall Street Journal - Mr. Dooley only awaits his gasping new fan base."
	},
	{
		"src": "\"Eine Generation protestiert\" in \u00c4thiopien, Long ein Verb\u00fcndeter der USA",
		"tgt": "\"A Generation Is Protesting\" in Ethiopia, Long a U.S. Ally"
	},
	{
		"src": "Gewaltt\u00e4tige Proteste in \u00c4thiopien",
		"tgt": "Violent Protests in Ethiopia"
	},
	{
		"src": "Demonstranten, die politische Ver\u00e4nderungen in \u00c4thiopien fordern, stie\u00dfen auf gewaltt\u00e4tigen Widerstand der Regierung.",
		"tgt": "Demonstrators demanding political change in Ethiopia have been met with violent resistance by the government."
	},
	{
		"src": "Zeugen sagen aus, dass zig Protestierende w\u00e4hrend der Zusammenst\u00f6\u00dfe mit der Polizei bei Schusswechseln get\u00f6tet wurden.",
		"tgt": "Witnesses say that scores of protesters have been fatally shot during clashes with police."
	},
	{
		"src": "Ist \u00c4thiopien gerade dabei zusammenzubrechen?",
		"tgt": "Is Ethiopia about to crack?"
	},
	{
		"src": "In den letzten zehn Jahren war es eines der stabilsten L\u00e4nder Afrikas, ein solider Verb\u00fcndeter des Westens mit einer schnell wachsenden Wirtschaft.",
		"tgt": "For the last decade, it has been one Africa's most stable nations, a solid Western ally with a fast-growing economy."
	},
	{
		"src": "Aber in den letzten Monaten ersch\u00fctterten Proteste gegen die Regierung das Land und weiteten sich in immer mehr Gebiete aus.",
		"tgt": "But in recent months, anti-government protests have convulsed the country, spreading into more and more areas."
	},
	{
		"src": "Letzte Woche st\u00fcrmten Tausende von Leuten auf die Stra\u00dfen und verlangten fundamentale politische Ver\u00e4nderungen.",
		"tgt": "In the last week alone, thousands of people stormed into the streets, demanding fundamental political change."
	},
	{
		"src": "Die Antwort des Regierung war laut Menschenrechtsorganisationen unbarmherzig.",
		"tgt": "The government response, according to human rights groups, was ruthless."
	},
	{
		"src": "Zeugen gaben an, dass Polizisten auf zig unbewaffnete Demonstranten schossen und t\u00f6teten.",
		"tgt": "Witnesses said that police officers shot and killed scores of unarmed demonstrators."
	},
	{
		"src": "Sich im Umlauf befindliche Videos \u00fcber die Proteste, die vermutlich vom letzten oder Anfang dieses Jahres sind, zeigen wie Sicherheitsleute junge Leute mit St\u00f6cken schlagen, w\u00e4hrend diese dazu gezwungen wurden, einen Handstand gegen eine Wand zu machen.",
		"tgt": "Videos circulating from protests thought to be from late last year or earlier this year show security officers whipping young people with sticks as they were forced to perform handstands against a wall."
	},
	{
		"src": "Der Chef der UN-Beh\u00f6rde f\u00fcr Menschenrechte verlangt jetzt eine eingehende Untersuchung.",
		"tgt": "The top United Nations human rights official is now calling for a thorough investigation."
	},
	{
		"src": "\"Es war schon immer schwierig, dieses Land zusammenzuhalten und zuk\u00fcnftig wird es sogar noch schwieriger werden,\" sagte Rashid Abdi, der Projektleiter des Horn von Afrika der International Crisis Group, einer Forschungsgruppe.",
		"tgt": "\"It was always difficult holding this country together, and moving forward, it will be even harder,\" said Rashid Abdi, the Horn of Africa project director for the International Crisis Group, a research group."
	},
	{
		"src": "\u00c4thiopien ist nach Nigeria das bev\u00f6lkerungsreichste Land Afrikas und seine Stabilit\u00e4t wird vom Westen gesch\u00e4tzt.",
		"tgt": "Ethiopia is the second most populous nation in Africa, after Nigeria, and its stability is cherished by the West."
	},
	{
		"src": "Amerikanische Milit\u00e4r-und Geheimdienste arbeiten eng mit den \u00c4thiopiern zusammen, um Terrorgefahren \u00fcber die Region hinaus zu bek\u00e4mpfen, insbesondere in Somalia. Nur wenige L\u00e4nder in Afrika, wenn \u00fcberhaupt, erhalten so viel westliche Hilfe.",
		"tgt": "American military and intelligence services work closely with the Ethiopians to combat terrorist threats across the region, especially in Somalia, and few if any countries in Africa receive as much Western aid."
	},
	{
		"src": "\u00c4thiopiens Wirtschaft expandierte im beachtlichen Tempo.",
		"tgt": "Ethiopia's economy has been expanding at an impressive clip."
	},
	{
		"src": "Seine Infrastruktur hat sich drastisch verbessert - es gibt einen neuen Pendlerzug in der Hauptstadt Addis Abeba.",
		"tgt": "Its infrastructure has improved drastically - there is even a new commuter train in the capital, Addis Ababa."
	},
	{
		"src": "Die Strassen sind in der Regel ruhig, sicher und sauber.",
		"tgt": "And its streets are typically quiet, safe and clean."
	},
	{
		"src": "Auch wenn \u00c4thiopien alles andere als ein Vorbild f\u00fcr Demokratie war - Menschenrechtsorganisationen haben fortlaufend die Unterdr\u00fcckung durch die Regierung angef\u00fchrt - die Opposition im Land wurde eingeschr\u00e4nkt, wobei Dissidenten wirksam zum Schweigen gebracht wurden.",
		"tgt": "Though Ethiopia has hardly been a paragon of democracy - human rights groups have constantly cited the government's repressiveness - opposition within the country had been limited, with dissidents effectively silenced."
	},
	{
		"src": "Viele wurden ins Exil oder ins Gef\u00e4ngnis geschickt, get\u00f6tet oder in die Weiten der W\u00fcste getrieben.",
		"tgt": "Many have been exiled, jailed, killed or driven to the far reaches of the desert."
	},
	{
		"src": "Doch das k\u00f6nnte sich \u00e4ndern.",
		"tgt": "But that may be changing."
	},
	{
		"src": "\"Wenn Sie Leute unterdr\u00fccken und diese keine anderen Optionen haben au\u00dfer zu protestieren, bricht es aus,\" sagte Seyoum Teshome, ein Dozent in Zentral\u00e4thiopien.",
		"tgt": "\"If you suffocate people and they don't have any other options but to protest, it breaks out,\" said Seyoum Teshome, a university lecturer in central Ethiopia."
	},
	{
		"src": "Die gesamte Jugend protestiert.",
		"tgt": "The whole youth is protesting."
	},
	{
		"src": "Eine Generation protestiert.",
		"tgt": "A generation is protesting."
	},
	{
		"src": "Es gibt zahlreiche Beschwerden, die alles von der Bodennutzung bis hin zum W\u00fcrgegriff in Bezug auf Macht der regierenden Koalition abdecken.",
		"tgt": "The complaints are many, covering everything from land use to the governing coalition's stranglehold on power."
	},
	{
		"src": "Nach einer weitl\u00e4ufig kritisierten Wahl letztes Jahr erhielten die regierende Partei und ihre Verb\u00fcndeten den letzten Sitz der Opposition und kontrollieren nun 100 Prozent des Parlaments.",
		"tgt": "After a widely criticized election last year, the governing party and its allies got the last seat the opposition had held and now control 100 percent of the Parliament."
	},
	{
		"src": "Gleichzeitig steigen die Spannungen entlang der Grenze zu Eritrea; ein Kampf um diese zackige, umstrittene Linie forderte im Juni Hunderte von Leben.",
		"tgt": "At the same time, tensions are rising along the border with Eritrea; a battle along that jagged, disputed line claimed hundreds of lives in June."
	},
	{
		"src": "Analytiker bef\u00fcrchten, dass Separatisten wie die Oromo-Befreiungsfront oder die Nationale Befreiungsfront des Ogaden, die in den letzten Jahren mehr oder weniger bezwungen wurden, die Turbulenzen ausn\u00fctzen und sich wieder bewaffnen k\u00f6nnten.",
		"tgt": "Analysts fear that separatist groups that had been more or less vanquished in recent years, like the Oromo Liberation Front or the Ogaden National Liberation Front, may try to exploit the turbulence and rearm."
	},
	{
		"src": "Mehrere Faktoren erkl\u00e4ren, warum Gef\u00fchle der Verbitterung nach Jahren des vor sich Hink\u00f6chelns unter der Oberfl\u00e4che nun explodieren.",
		"tgt": "Several factors explain why bitter feelings, after years of simmering beneath the surface, are exploding now."
	},
	{
		"src": "Der erste scheint harmlos: Smartphones.",
		"tgt": "The first is seemingly innocuous: smartphones."
	},
	{
		"src": "Erst in den letzten Jahren waren sehr viele \u00c4thiopier in der Lage, mittels den sozialen Medien zu kommunizieren, da billigere Smartphones immer h\u00e4ufiger wurden und sich die Internetdienste verbesserten.",
		"tgt": "Only in the last couple of years have large numbers of Ethiopians been able to communicate using social media as cheaper smartphones became common and internet service improved."
	},
	{
		"src": "Selbst wenn die Regierung den Zugang zu Facebook und Twitter sperrt, was sie in regelm\u00e4\u00dfigen Abst\u00e4nden, vor allem bei Protesten, tut, k\u00f6nnen viele Leute noch immer \u00fcber Internet-Proxies kommunizieren, die verbergen, wo sie sich aufhalten.",
		"tgt": "Even when the government shuts down access to Facebook and Twitter, as it frequently does, especially during protests, many people are still able to communicate via internet proxies that mask where they are."
	},
	{
		"src": "Mehrere junge \u00c4thiopier gaben an, dass sie sich so zu Protesten versammelten.",
		"tgt": "Several young Ethiopians said this was how they gathered for protests."
	},
	{
		"src": "Der zweite Faktor ist, dass es mehr Solidarit\u00e4t zwischen den Oromos und Amharas, den zwei gr\u00f6\u00dften Ethnien in \u00c4thiopien, gibt.",
		"tgt": "Second, there is more solidarity between Oromos and Amharas, Ethiopia's two largest ethnic groups."
	},
	{
		"src": "Die Oromos und Amharas sind keine nat\u00fcrlichen Feinde.",
		"tgt": "Oromos and Amharas are not natural allies."
	},
	{
		"src": "Seit \u00c4onen prosperierten die Amharas, die aus \u00c4thopiens \u00fcberwiegend christlichen Hochl\u00e4ndern kommen, in der Politik und Wirtschaft, w\u00e4hrend sie die Oromos ausbeuteten, von denen viele Muslime sind und in Flachlandgebieten leben.",
		"tgt": "For eons, Amharas from Ethiopia's predominantly Christian highlands flourished in politics and business, exploiting the Oromos, many of whom are Muslim and live in lowland areas."
	},
	{
		"src": "Aber auch das \u00e4ndert sich gerade.",
		"tgt": "But that is changing as well."
	},
	{
		"src": "\"Wir sind dabei, unter einem Schirm zu koordinieren,\" sagte Mulatu Gemechu, ein F\u00fchrer der Oromos.",
		"tgt": "\"We are on the way to coordinate under one umbrella,\" said Mulatu Gemechu, an Oromo leader."
	},
	{
		"src": "Die gr\u00f6\u00dften Proteste fanden in Gebieten der Amhara und Oromos statt.",
		"tgt": "The biggest protests have been in Amhara and Oromo areas."
	},
	{
		"src": "Viele Amharas und Oromos haben das Gef\u00fchl, dass \u00c4thiopien unfairerweise von Mitgliedern der ethnischen Gruppe der Tigray dominiert wird, die rund 6 Prozent der Bev\u00f6lkerung ausmachen und die im Milit\u00e4r, in den Geheimdiensten, im Handel und der Politik dominant sind.",
		"tgt": "Many Amharas and Oromos feel Ethiopia is unfairly dominated by members of the Tigrayan ethnic group, which makes up about 6 percent of the population and dominates the military, the intelligence services, commerce and politics."
	},
	{
		"src": "Der dritte Grund f\u00fcr die Unruhen ist der Tod von Meles Zenawi.",
		"tgt": "The third reason behind the unrest is the loss of Meles Zenawi."
	},
	{
		"src": "Herr Meles, ein ehemaliger Rebellenanf\u00fchrer, war bis zu seinem Tod an einer nicht publik gemachten Krankheit im Jahre 2012 17 Jahre lang \u00c4thiopiens Premierminister.",
		"tgt": "Mr. Meles, a former rebel leader, was Ethiopia's prime minister for 17 years, until his death from an undisclosed illness in 2012."
	},
	{
		"src": "Er wurde als taktisches Genie angesehen, ein Mann, der um Ecken denken konnte.",
		"tgt": "He was considered a tactical genius, a man who could see around corners."
	},
	{
		"src": "Analysten sagen, dass er besonders versiert darin war, fr\u00fche Anzeichen von Unzufriedenheit wahrzunehmen und Sonderbeauftragte zu benutzen, um Gegner zu bearbeiten und sie unsch\u00e4dlich zu machen.",
		"tgt": "Analysts say he was especially adept at detecting early signals of discontent and using emissaries to massage and defang opponents."
	},
	{
		"src": "\"Dem derzeitigen Regime fehlt es an diesem grundlegendem Geschick,\" sagte Herr Abdi, ein Konfliktanalytiker.",
		"tgt": "\"The current regime lacks that ground savvy,\" Mr. Abdi, the conflict analyst, said."
	},
	{
		"src": "\u00c4thiopiens neuer Premierminister, Hailemariam Desalegn, wurde aus relativ undurchsichtigen Gr\u00fcnden ausgew\u00e4hlt, um die Stellung von Herrn Meles einzunehmen.",
		"tgt": "Ethiopia's new prime minister, Hailemariam Desalegn, was plucked from relative obscurity to fill Mr. Meles's shoes."
	},
	{
		"src": "Anders als Herr Meles, der aus der Tigray Region Nord\u00e4thiopiens kam, kommt Herr Hailemariam aus dem S\u00fcden.",
		"tgt": "Unlike Mr. Meles, who came from the Tigray region of northern Ethiopia, Mr. Hailemariam is a southerner."
	},
	{
		"src": "Analytiker sagen, dass er nicht das Vertrauen der von den Tigray kontrollierten Sicherheitsdiensten genie\u00dft.",
		"tgt": "Analysts say he does not have the trust of the Tigrayan-controlled security services."
	},
	{
		"src": "Viele bef\u00fcrchten, dass das Ergebnis mehr Blutvergie\u00dfen sein wird.",
		"tgt": "The result, many fear, is more bloodshed."
	},
	{
		"src": "Das letzte Mal, dass \u00c4thiopien einen solchen Aufruhr erlebte war 2005, nachdem Tausende gegen Wahlen protestierten, die laut Angaben von Analytikern scheinbar von der Regierung verpfuscht und anschlie\u00dfend gestohlen wurden.",
		"tgt": "The last time Ethiopia experienced such turmoil was in 2005, after thousands protested over what analysts have said appeared to be an election the government bungled and then stole."
	},
	{
		"src": "W\u00e4hrend der darauf folgenden Razzien wurden viele Protestierende get\u00f6tet, auch wenn es weniger als in den letzten Monaten waren und diese Zeit der Unruhen ging relativ schnell vorbei.",
		"tgt": "In the ensuing crackdown, many protesters were killed, though fewer than in recent months, and that period of unrest passed relatively quickly."
	},
	{
		"src": "Entwicklungsexperten lobten \u00c4thiopiens F\u00fchrer f\u00fcr ihre vision\u00e4re Infrastrukturplanung, wie der neue Pendlerzug, sowie f\u00fcr ihre messbaren Fortschritte bei der Armutsbek\u00e4mpfung.",
		"tgt": "Development experts have praised Ethiopia's leaders for visionary infrastructure planning, such as the new commuter train, and measurable strides in fighting poverty."
	},
	{
		"src": "Aber offensichtlich hat dies nicht die Intensivierung der internen Missgunst der \u00e4thiopischen Regierung verhindert.",
		"tgt": "But clearly that has not stopped the internal resentment of Ethiopia's government from intensifying."
	},
	{
		"src": "Und sie nimmt eine gef\u00e4hrliche ethnische Form an.",
		"tgt": "And it is taking a dangerous ethnic shape."
	},
	{
		"src": "Letzten Monat griffen Protestierende in Gondar, einer amharischen Stadt, von Tigray gef\u00fchrte Gesch\u00e4fte an und der Hass gegen\u00fcber den Tigray wird in den sozialen Medien immer \u00fcblicher.",
		"tgt": "Last month, protesters in Gondar, an Amhara town, attacked businesses owned by Tigrayans, and anti-Tigrayan hatred is becoming more common in social media."
	},
	{
		"src": "Analytiker sagen, dass die Proteste die USA und andere westliche Verb\u00fcndete in eine eigenartige Position bringen.",
		"tgt": "Analysts say the protests are putting the United States and other Western allies in an awkward position."
	},
	{
		"src": "Die amerikanische Regierung benutzte \u00c4thiopien als Basis f\u00fcr Dronenfl\u00fcge \u00fcber das benachbarte Somalia, auch wenn sie k\u00fcrzlich mitteilte, dass sie dieses Basis geschlossen hat.",
		"tgt": "The American government has used Ethiopia as a base for drone flights over neighboring Somalia, though it recently said it closed that base."
	},
	{
		"src": "W\u00e4hrend der Westen eindeutig die Demokratie unterst\u00fctzen will, will er nicht, dass sein Verb\u00fcndeter in einer bereits volatilen Gegend zusammenbricht.",
		"tgt": "While the West clearly wants to support democracy, it also does not want its ally in an already volatile region to crumble."
	},
	{
		"src": "\"Dies,\" sagte Herr Abdi, \"ist eine sehr d\u00fcnne Gratwanderung.\"",
		"tgt": "\"That,\" Mr. Abdi said, \"is a very tight rope to walk.\""
	},
	{
		"src": "Donald Trump erkl\u00e4rt seine Behauptung Obama habe ISIS gegr\u00fcndet sei \"Sarkasmus\" gewesen",
		"tgt": "Donald Trump Explains His Obama-Founded-ISIS Claim as \"Sarcasm\""
	},
	{
		"src": "Donald J. Trump versuchte am Freitag die letzte Kontroverse zu zerstreuen, die seine Kampagne umgibt, indem er angab, dass seine mehrfach wiederholte Behauptung, Pr\u00e4sident Obama und Hillary Clinton w\u00e4ren die \"Gr\u00fcnder\" der Terrorgruppe Islamischer Staat, nicht ernst gemeint gewesen sei.",
		"tgt": "Donald J. Trump tried to quash the latest controversy engulfing his campaign on Friday by claiming that he was not serious when he insisted several times this week that President Obama and Hillary Clinton were the \"founders\" of the Islamic State terrorist group."
	},
	{
		"src": "Diese Klarstellung warf neue Fragen zu den Kommunikationsf\u00e4higkeiten des Pr\u00e4sidentschaftskandidaten der Republikaner auf, ob er in der Lage sei klar und verst\u00e4ndlich mit der amerikanischen \u00d6ffentlichkeit zu kommunizieren.",
		"tgt": "The clarification raised new questions about the Republican presidential nominee's ability to communicate clearly to the American public."
	},
	{
		"src": "Es bringt auch seine Mitstreiter, die sich bem\u00fchen ihn w\u00e4hrend einer ereignisreichen Phase in Schutz zu nehmen, in die eigent\u00fcmliche Position, Aussagen erkl\u00e4ren zu m\u00fcssen, die er gar nicht gemeint haben k\u00f6nnte.",
		"tgt": "It also put his surrogates, who have strained to defend him during a tumultuous stretch, in the awkward position of having to explain remarks that he might not mean."
	},
	{
		"src": "Nachdem er die Andeutung bei einer Wahlkampfveranstaltung am Mittwochabend gemacht hatte, ruderte Mr. Trump in Bezug auf die Behauptung am Donnerstag zur\u00fcck und bestand in Interviews darauf, dass er wirklich nicht beabsichtigte anzudeuten, der Pr\u00e4sident und Mrs. Clinton h\u00e4tten ISIS geschaffen.",
		"tgt": "After making the suggestion at a rally on Wednesday night, Mr. Trump doubled down on the assertion on Thursday, insisting in interviews that he really did intend to say that the president and Mrs. Clinton had created ISIS."
	},
	{
		"src": "Aber in einem fr\u00fchmorgendlichen Tweet am Freitag sagte Mr. Trump, er sei einfach sarkastisch.",
		"tgt": "But in an early-morning Twitter post on Friday, Mr. Trump said that he was just being sarcastic."
	},
	{
		"src": "Der Tweet war der Gegensatz zu dem vorherigen Tag, an denen Mr. Trump in einer Reihe von Interviews sagte, er meinte die Anschuldigung vollkommen ernst.",
		"tgt": "The post was a reversal from just a day ago, when Mr. Trump said in a number of interviews that he was indeed serious about the charge."
	},
	{
		"src": "Als der konservative Radiomoderator Hugh Hewitt Mr. Trump helfen wollte, die Aussage etwas abzuschw\u00e4chen indem er ihn daran erinnerte, dass Mr. Obama ISIS zerst\u00f6ren will, wollte der republikanische Pr\u00e4sidentschaftskandidat nichts davon wissen.",
		"tgt": "When the conservative radio host Hugh Hewitt tried to help Mr. Trump soften the remark by reminding him that Mr. Obama wants to destroy ISIS, the Republican presidential nominee would not have it."
	},
	{
		"src": "Der letzte Sturm der Kritik prasselt auf Mr. Trump herab, w\u00e4hrend er versucht hat den Fokus seiner Kampagne wegen fallender Umfragewerte auf die Wirtschaftslage zu lenken.",
		"tgt": "The latest firestorm comes as Mr. Trump has been trying to refocus his campaign on the economy amid declining poll numbers."
	},
	{
		"src": "Mr. Trump und Mrs. Clinton hielten Reden zur Wirtschaftslage in Michigan in dieser Woche.",
		"tgt": "Mr. Trump and Mrs. Clinton gave dueling economic speeches in Michigan this week."
	},
	{
		"src": "Am Freitag versuchte Mr. Trump nochmals zu diesem Thema zur\u00fcck zu kehren.",
		"tgt": "On Friday, Mr. Trump tried again to return to that subject."
	},
	{
		"src": "Sich \u00fcber Twitter meldend warnte er, dass Mrs. Clintons Vorschl\u00e4ge zu h\u00f6heren Steuern f\u00fchren w\u00fcrden und dass er ihre Rede langweilig gefunden habe.",
		"tgt": "Taking again to Twitter, he warned that Mrs. Clinton's proposals would come with higher taxes and he said that he found her speech boring."
	},
	{
		"src": "Mr. Trump hat Sarkasmus bereits zu seiner Verteidigung vorgebracht.",
		"tgt": "Mr. Trump has used the sarcasm defense before."
	},
	{
		"src": "Ende Juli zog er starke Kritik auf sich, als er meinte, die Russen sollten Mrs. Clintons Emails hacken, jedoch erkl\u00e4rte er sp\u00e4ter \"Nat\u00fcrlich meinte ich das sarkastisch\".",
		"tgt": "In late July, after he drew widespread criticism by appearing to suggest that the Russians should hack Mrs. Clinton's emails, he later explained his remarks by saying, \"Of course I'm being sarcastic.\""
	},
	{
		"src": "Diese Methode erlaubt es Mr. Trump die sprachlichen Grenzen in der Politik zu verschieben und dann nach Bedarf zur\u00fcck zu rudern.",
		"tgt": "The approach allows Mr. Trump to push the limits of political speech and dial it back as needed."
	},
	{
		"src": "\"Ich denke, es ist eine seiner Methoden zu testen, wie bestimmte Botschaften von seinen Fans aufgenommen werden, wie sie ankommen, und dann gegebenenfalls \"klarzustellen\" je nach dem, wie die Reaktion ausf\u00e4llt. \" sagte Ruth Sherman, eine Kommunikationsexpertin, die die Sprache beider Kandidaten beobachtet.",
		"tgt": "\"I think it's a pattern of him testing certain messages that resonate with his fans, seeing how they play, and then \"clarifying\" one way or another depending on the reaction,\" said Ruth Sherman, a communications expert who has been monitoring the language used by both candidates."
	},
	{
		"src": "Ich glaube aber auch, er ist clever genug um seine Aussagen vage genug zu halten, so dass sie auf verschiedene Art und Weise interpretiert werden k\u00f6nnen.",
		"tgt": "But I also think he's clever about his statements and knows they are vague enough to be filtered through various lenses."
	},
	{
		"src": "Anstatt den Ton f\u00fcr die Pr\u00e4sidentschaftswahlen zu entsch\u00e4rfen, hat Mr. Trump einen noch \u00e4tzenderen Ton angenommen, da seine Umfragewerte weiter zur\u00fcckgegangen sind.",
		"tgt": "Instead of toning things down for a general election audience, Mr. Trump has taken an even more caustic tone in recent days as his poll numbers have continued to tumble."
	},
	{
		"src": "Eine neue Umfrage von NBC/Wall Street Journal/Marist, der am Freitag ver\u00f6ffentlicht wurde, zeigte eine F\u00fchrung mit gro\u00dfem Vorsprung in den Bundesstaaten North Carolina, Virginia, Colorado und ein Kopf-an-Kopf-Rennen in Florida.",
		"tgt": "A new NBC/Wall Street Journal/Marist poll released on Friday showed Mr. Trump trailing Mrs. Clinton by large margins in North Carolina, Virginia and Colorado and locked in a tight race in Florida."
	},
	{
		"src": "W\u00e4hrend Mr. Trump generell versucht, sich f\u00fcr seine provokanten \u00c4u\u00dferungen nicht entschuldigen zu m\u00fcssen, beschuldigt er seine Kritiker h\u00e4ufig, seine Aussagen zu verzerren oder seinen Humor falsch zu verstehen.",
		"tgt": "While Mr. Trump generally tries to avoid apologizing for provocative things that he says, he often accuses his critics of misconstruing his words or misunderstanding his sense of humor."
	},
	{
		"src": "Aber w\u00e4hrend er verst\u00e4rkt im Fokus der Aufmerksamkeit in den letzten Monaten seiner Pr\u00e4sidentschaftskampagne steht, haben Mr. Trumps Scherze seine loyalen Mitstreiter in die unkomfortable Situation gebracht, zu ihm stehen zu m\u00fcssen, unabh\u00e4ngig davon, wie provokant seine Aussagen auch sein m\u00f6gen.",
		"tgt": "But as he faces heightened scrutiny during the final months of the presidential campaign, Mr. Trump's jokes have put his loyal allies in the uncomfortable position of having to publicly stand up for him no matter how provocative his remarks."
	},
	{
		"src": "Rudolph W. Giuliani, ehemaliger B\u00fcrgermeister von New York und einer von Trumps prominentesten F\u00fcrsprechern, gab sich gro\u00dfe M\u00fche den Kandidaten heute in einem CNN-Interview vom Donnerstag zu verteidigen.",
		"tgt": "Rudolph W. Giuliani, the former New York City mayor who is one of Mr. Trump's most prominent surrogates, went to great lengths to defend the candidate in an interview with CNN on Thursday."
	},
	{
		"src": "\"Ich glaube, was er sagt sind legitime, politische Kommentare\" sagte Mr. Giuliani also er zu der Richtigkeit von Mr. Trumps Aussagen befragt wurde, ob Mr. Obama und Mrs. Clinton den Islamischen Staat gegr\u00fcndet h\u00e4tten.",
		"tgt": "\"I think what he's saying there is legitimate, political commentary,\" Mr. Giuliani said when questioned about the veracity of Mr. Trump's assertion about Mr. Obama and Mrs. Clinton having founded the Islamic State."
	},
	{
		"src": "Es ist in diesem Sinne wahr, dass vor Obama ISIS eine fast unbekannte, kleine Organisation war, er nannte sie Hinterb\u00e4nkler, vollkommen falsch und deswegen geschah es, weil er die Truppen aus dem Irak abzog.",
		"tgt": "It is true in a sense that before Obama, ISIS was an almost unknown, small little organization, he who called it the jayvee, totally wrong, and here's why it happened, because he withdrew the troops from Iraq."
	},
	{
		"src": "Die meisten Mainstream-Republikaner versuchen zu argumentieren, dass die Regierung unter Obama, in der Mrs. Clinton als Au\u00dfenministerin diente, es ISIS erlaubte, sich auszubreiten indem sie es unterlie\u00dfen, die Situation im Nahen Osten aggressiv unter Kontrolle zu bringen.",
		"tgt": "Most mainstream Republicans try to argue that the Obama administration, in which Mrs. Clinton served as secretary of state, allowed ISIS to fester by failing to aggressively manage the situation in the Middle East."
	},
	{
		"src": "Vor den Wahlkampfveranstaltungen in Pennsylvania am Freitag setzte Mr. Trump seine Angriffe auf die Medien fort und warf ihnen vor, auf jedem seiner Worte herumzureiten und gegen ihn voreingenommen zu sein.",
		"tgt": "Ahead of rallies in Pennsylvania on Friday, Mr. Trump continued to lash out on Twitter at the news media for harping on his every word and for being biased against him."
	},
	{
		"src": "Er verh\u00f6hnte die \"armen, j\u00e4mmerlichen\" Fernsehexperten, die versuchen ihn zu verstehen und sagte, \"Sie k\u00f6nnen es nicht!\".",
		"tgt": "He mocked the \"poor, pathetic\" television pundits who try to figure him out and said, \"They can't!\""
	},
	{
		"src": "Manche der Demokraten spotteten \u00fcber Mr. Trumps Entschuldigung als nur einen weiteren Beweis, dass er f\u00fcr das Pr\u00e4sidentenamt ungeeignet sei.",
		"tgt": "Some Democrats scoffed at Mr. Trump's excuse as more evidence that he is unfit to be president."
	},
	{
		"src": "Einst \u00fcber den Preis vom Markt verdr\u00e4ngt, kommt Caf\u00e9 in Greenpoint zur\u00fcck",
		"tgt": "Once Priced Out, a Cafe Returns in Greenpoint"
	},
	{
		"src": "Verb Cafe war ein sch\u00e4biges Caf\u00e9 in Williamsburg, in dem man nur bar bezahlen konnte, das kein Wi-Fi hatte, daf\u00fcr aber 15 Jahre lang guten Kaffee servierte.",
		"tgt": "Verb Cafe was a shabby, cash-only space in Williamsburg that had no Wi-Fi but served good coffee for 15 years."
	},
	{
		"src": "Nat\u00fcrlich wurde durch die Preise aus seiner Bedford Avenue Ladenfront verdr\u00e4ngt.",
		"tgt": "Naturally, it got priced out of its Bedford Avenue storefront."
	},
	{
		"src": "Das Gesch\u00e4ft Soap Cherie, das Verb im Sommer 2014 ersetzte, verkauft Seife in Form von Cupcakes.",
		"tgt": "The store that replaced the Verb in the summer of 2014, Soap Cherie, sells soaps in the shape of cupcakes."
	},
	{
		"src": "Einheimische betrauerten es als letzten Verlust in einer sich gentrifizierenden Stadt.",
		"tgt": "Locals bemoaned it as the latest loss in a gentrifying city."
	},
	{
		"src": "Die K\u00fcnstlerin Molly Crabapple schrieb auf Twitter, \"Ich wei\u00df, New York ist Ver\u00e4nderung, aber ich kann noch immer nicht glauben, dass CBGB tot, das Chelsea Hotel ausgenommen und Verb jetzt ein Seifengesch\u00e4ft ist.\"",
		"tgt": "The artist Molly Crabapple wrote on Twitter, \"New York is change, I know, but still, can't believe CBGB's is dead and the Chelsea Hotel is gutted and Verb is now a soap shop.\""
	},
	{
		"src": "Aber wenn New York Ver\u00e4nderung ist, dann ist es auch Neuerfindung.",
		"tgt": "But if New York is change, it is also reinvention."
	},
	{
		"src": "Ein wiederbelebtes Verb Cafe \u00f6ffnete letzten November in Greenpoint, weniger als eine Meile n\u00f6rdlich von seinem urspr\u00fcnglichen Standort.",
		"tgt": "A revived Verb Cafe opened last November in Greenpoint, less than a mile north of the original location."
	},
	{
		"src": "Das neue Verb hat Wi-Fi und akzeptiert Kreditkarten, aber hat noch immer einige der selben Mitarbeiter und eine \u00e4hnlich schlichte Atmosph\u00e4re.",
		"tgt": "The new Verb has Wi-Fi and accepts credit cards but has some of the same employees and a similar unpretentious vibe."
	},
	{
		"src": "Der Kaffee ist auch noch immer gut.",
		"tgt": "The coffee is still good, too."
	},
	{
		"src": "Der neue Besitzer des Verb ist Cisco Rodriguez, ein langj\u00e4hriger Mitarbeiter des alten Caf\u00e9s, der Eigent\u00fcmer und Gesch\u00e4ftsf\u00fchrer des neuen Caf\u00e9s ist.",
		"tgt": "Leading the new Verb is Cisco Rodriguez, a longtime employee at the old cafe who is an owner and the general manager at the new place."
	},
	{
		"src": "Er begann 2001 bei Verb zu arbeiten und blieb dort bis zum Ende.",
		"tgt": "He started at Verb in 2001 and was there until the end."
	},
	{
		"src": "Als ihm ein Kunde anbot, Geldmittel f\u00fcr eine neue Au\u00dfenstelle bereitzustellen, war er aufgeregt, es zu tun, sagte er.",
		"tgt": "When a customer offered to bankroll him in a new outpost, he said he was excited to do it."
	},
	{
		"src": "Rodriguez, 36, behielt vieles bei.",
		"tgt": "Mr. Rodriguez, 36, kept a lot of things the same."
	},
	{
		"src": "Verb verwendet denselben Distributor f\u00fcr die Bagels kaufte dasselbe Espressomaschinenmodell.",
		"tgt": "Verb uses the same distributor for the bagels and bought the same model of espresso machine."
	},
	{
		"src": "Es verwendet sogar dieselben Lampen aus dem alten Verb.",
		"tgt": "It even reused the lights from the old Verb."
	},
	{
		"src": "Aber Rodriguez sagte, dass er auch experimentieren wollte.",
		"tgt": "But Mr. Rodriguez said he also wanted to experiment."
	},
	{
		"src": "Er f\u00fchrte neue Zutaten ein.",
		"tgt": "He introduced new ingredients."
	},
	{
		"src": "Auf der Speisekarte stehen Sandwiches mit Speck und K\u00e4se und es gibt Garnierungen wie Kapern und sautierte Zwiebeln.",
		"tgt": "Bacon-egg-and-cheese sandwiches are on the menu, and toppings like capers and saut\u00e9ed onions are available."
	},
	{
		"src": "Es gibt Naturreisssch\u00fcsseln.",
		"tgt": "There are brown-rice bowls."
	},
	{
		"src": "Das Caf\u00e9 serviert kein Bier mehr, daf\u00fcr gibt es frische S\u00e4fte.",
		"tgt": "The cafe no longer serves beer but now makes fresh juices."
	},
	{
		"src": "Nach neun Monaten sagte Rodriguez, dass er einen steten Strom an alten Stammkunden bemerkt habe.",
		"tgt": "Nine months in, Mr. Rodriguez said he had noticed a steady stream of old regulars."
	},
	{
		"src": "\"Viele alte Kunden wurden ebenfalls durch Preise aus Williamsburg verdr\u00e4ngt,\" sagte er.",
		"tgt": "\"A lot of former customers got priced out of Williamsburg too,\" he said."
	},
	{
		"src": "K\u00fcrzlich an einem Sonntag war Rebecca Oliveira ein solcher Kunde.",
		"tgt": "On a recent Sunday, Rebecca Oliveira was one such customer."
	},
	{
		"src": "Oliveira, 34, wohnte fr\u00fcher in Williamsburg und besuchte das Verb regelm\u00e4\u00dfig.",
		"tgt": "Ms. Oliveira, 34, used to live in Williamsburg and went to Verb frequently."
	},
	{
		"src": "Selbst nachdem sie nach Greenpoint gezogen war, w\u00fcrde sie den Weg auf sich nehmen.",
		"tgt": "Even after she moved to Greenpoint, she would still make the trek."
	},
	{
		"src": "Nachdem das Verb geschlossen hatte, gab sie eine Weile das Kaffeetrinken auf, sagte sie.",
		"tgt": "After Verb closed, she said, she gave up drinking coffee for a while."
	},
	{
		"src": "\"Mir wurde klar, dass es am Kaffee und an der Kultur im Verb lag, die mir gefiel,\" sagte sie.",
		"tgt": "\"I realized it was the coffee and the culture at Verb that I liked,\" she said."
	},
	{
		"src": "Jetzt trinkt sie wieder Kaffee, auch wenn sie an diesem Tag anstelle ihres \u00fcblichen Iced Coffees einen Blended Chai Tea bestellte, der ein weiterer neuer Zusatz ist.",
		"tgt": "Now she's back on coffee, although that day, instead of her usual iced coffee, she went with a blended chai drink, another new addition."
	},
	{
		"src": "Tom Rosenthal ist seit dem Beginn des Verb im Jahr 2003 ein weiterer langj\u00e4hriger und treuer Kunde.",
		"tgt": "Tom Rosenthal, another longtime customer, went faithfully to Verb starting in 2003."
	},
	{
		"src": "Er ging dort vor der Arbeit und bestellte unweigerlich immer Dasselbe.",
		"tgt": "He'd go before work and order the same thing without fail."
	},
	{
		"src": "\"Ich kam viertel nach sieben, jeden Tag, wie eine Schweizer Taschenuhr und sie bereiten meinen Everything-Bagel mit Butter zu,\" sagte er.",
		"tgt": "\"Quarter past seven, every day, like clockwork, I'd come in and they were making my everything bagel with butter,\" he said."
	},
	{
		"src": "Foto Rodriguez sagte, er wollte experimentieren und neue Zutaten in das Men\u00fc aufnehmen.",
		"tgt": "Photo Mr. Rodriguez said he wanted to experiment and introduced new ingredients to the menu."
	},
	{
		"src": "Heutzutage bekommt Rosenthal immer noch seine \u00fcbliche Bestellung, aber manchmal wechselt er sein Everything-Bagel mit Speck, Ei und K\u00e4se ab.",
		"tgt": "These days, Mr. Rosenthal still gets his regular order, but sometimes he'll switch things up with the bacon, egg and cheese on an everything bagel."
	},
	{
		"src": "Rodriguez sagte, dass er keinen Groll dar\u00fcber hegte, dass das Seifengesch\u00e4ft den alten Gesch\u00e4ftsraum eingenommen hat.",
		"tgt": "Mr. Rodriguez said he had no hard feelings about the soap shop taking over the old space."
	},
	{
		"src": "Tats\u00e4chlich boten die Eigent\u00fcmer des Soap Cherie an, eine spezielle Seife f\u00fcr Verb mit dem kaltgebr\u00fchten Kaffee des Caf\u00e9s als Zutat herzustellen.",
		"tgt": "In fact, the Soap Cherie owners offered to make special soap for Verb, using the cafe's cold-brewed coffee as an ingredient."
	},
	{
		"src": "\"Ich denke, wir werden noch auf ihr Angebot eingehen,\" sagte Rodriguez.",
		"tgt": "\"I think we still might take them up on it,\" Mr. Rodriguez said."
	},
	{
		"src": "Und die traditionellen, polnischen Einwohner Greenpoints haben das Caf\u00e9 ebenfalls akzeptiert.",
		"tgt": "And Greenpoint's traditional Polish residents have embraced the cafe as well."
	},
	{
		"src": "Ein neuer Kunde hat die Speisekarte ins Polnische \u00fcbersetzt und Rodriguez sagte, dass er vorhat, sie bald auszustellen, sodass sich seine neuen Nachbarn willkommen f\u00fchlen.",
		"tgt": "One of these new customers translated the menu into Polish, and Mr. Rodriguez said he planned to find a spot to display it soon to make his new neighbors feel welcome."
	},
	{
		"src": "Der Standort hat auch weitere Vorz\u00fcge.",
		"tgt": "The new location has other perks."
	},
	{
		"src": "Ein \u00f6rtliches Saftlokal m\u00f6chte den kaltgebr\u00fchten Kaffee ins Flaschen f\u00fcllen und verkaufen.",
		"tgt": "A local juice spot wants to bottle and sell the cold-brewed coffee."
	},
	{
		"src": "Es gibt eine Chance, dass das Caf\u00e9 auf ein benachbartes Geb\u00e4ude expandiert.",
		"tgt": "There is a chance the cafe will expand into an adjacent building."
	},
	{
		"src": "F\u00fcr viele Kunden reicht ein neues Verb aus, um ihre alten Favoriten zu bekommen.",
		"tgt": "For many customers, a new Verb to get their old favorites is enough."
	},
	{
		"src": "Joseph Witt war Stammkunde und sagte, dass er am Boden zerst\u00f6rt war, als das Caf\u00e9 schloss.",
		"tgt": "Joseph Whitt was a regular and said he was heartbroken when they closed."
	},
	{
		"src": "Als das neue Caf\u00e9 er\u00f6ffnete, sagte Whitt, dass sich das Betreten des Lokals und das Bestellen eine neuen Kaffees wie eine Heimkehr anf\u00fchlte.",
		"tgt": "When the new space opened, Mr. Whitt said, walking in and getting a coffee felt like a homecoming."
	},
	{
		"src": "\"Ich musste das riechen,\" sagte er.",
		"tgt": "\"I've needed to smell that,\" he said."
	},
	{
		"src": "Das deprimierende Essen der Wirtschaftskrise in \"einer reichlichen Mahlzeit\"",
		"tgt": "The Depressing Food of the Depression, in \"A Square Meal\""
	},
	{
		"src": "Im M\u00e4rz 1933, kurz nach seinem Aufstieg zum Pr\u00e4sidenten, nahm Franklin Delano Roosevelt sein Mittagessen im Oval Office ein.",
		"tgt": "In March 1933, shortly after ascending to the presidency, Franklin Delano Roosevelt sat down to lunch in the Oval Office."
	},
	{
		"src": "Als Feinschmecker hatte Pr\u00e4sident Roosevelt ein Faible f\u00fcr raffinierte Delikatessen der Fifth Avenue wie P\u00e2te de foie gras und Maryland Wasserschildkr\u00f6tensuppe.",
		"tgt": "A gourmand, President Roosevelt had a taste for fancy Fifth Avenue foods like p\u00e2t\u00e9 de foie gras and Maryland terrapin soup."
	},
	{
		"src": "Sein Men\u00fc an diesem Tag war etwas bescheidener: gef\u00fcllte Eier in Tomatensauce, Kartoffelp\u00fcree und als Dessert einen Pflaumenpudding.",
		"tgt": "His menu that day was more humble: deviled eggs in tomato sauce, mashed potatoes and, for dessert, prune pudding."
	},
	{
		"src": "\"Es war ein Akt kulinarischer Solidarit\u00e4t mit leidenden Leuten,\" sagte Jane Ziegelman.",
		"tgt": "\"It was an act of culinary solidarity with the people who were suffering,\" Jane Ziegelman said."
	},
	{
		"src": "Ihr Ehemann Andrew Coe f\u00fcgte hinzu,\"Es war auch eine Botschaft an die Amerikaner, wie sie essen sollten.\"",
		"tgt": "Her husband, Andrew Coe, added, \"It was also a message to Americans about how to eat.\""
	},
	{
		"src": "Das Ehepaar lebt in Brooklyn Heights und sind beide Lebensmittelhistoriker.",
		"tgt": "The couple, who live in Brooklyn Heights, are food historians."
	},
	{
		"src": "Coes letztes Buch \"Chop Suey\" handelte von der chinesischen K\u00fcche in den USA, w\u00e4hrend Ziegelman in ihrem Buch \"97 Orchard\" \u00fcber das Leben in einem Wohnhaus an der Lower East Side aus der Lebensmittelperspektive erz\u00e4hlt.",
		"tgt": "Mr. Coe's last book, \"Chop Suey,\" was about Chinese cuisine in America, while Ms. Ziegelman told the story of life in a Lower East Side tenement through food in her book \"97 Orchard.\""
	},
	{
		"src": "Ihr neueste Zusammenarbeit, \"Eine anst\u00e4ndige Mahlzeit\", die am Dienstag im Harper Verlag erscheinen wird, illustriert die Geschichte der amerikanischen K\u00fcche w\u00e4hrend der Gro\u00dfen Depression.",
		"tgt": "Their new, collaborative work, \"A Square Meal,\" which will be published Tuesday by Harper, is a history of American food in the Great Depression."
	},
	{
		"src": "Sie zeigten kulinarische Solidarit\u00e4t, als sie sich mit einem Reporter im Eisenberg's Sandwich Shop zum Abendessen treffen, einem kleinen, schn\u00f6rkellosem Imbiss im Flatiron District, das bereits seit dem B\u00f6rsencrash 1929 im Gesch\u00e4ft ist.",
		"tgt": "Showing some culinary solidarity of their own, they met a reporter for dinner at Eisenberg's Sandwich Shop, a tiny no-frills lunch counter in the Flatiron district that has been in business since the year of the crash, 1929."
	},
	{
		"src": "Ziegelman, 54, bestellte ein Frischk\u00e4sesandwich mit Olivenst\u00fcckchen, w\u00e4hrend Coe, 57, Truthahn mit Kartoffelp\u00fcree und Gem\u00fcsemischung a\u00df.",
		"tgt": "Ms. Ziegelman, 54, ordered a cream cheese and chopped olive sandwich, while Mr. Coe, 57, had the turkey, mashed potatoes and vegetable medley."
	},
	{
		"src": "Als der Reporter Hackbraten bestellte, fand dies das Paar f\u00fcr eine Diskussion \u00fcber das Essen in der \u00c4ra der Gro\u00dfen Depression passend.",
		"tgt": "When a reporter ordered meatloaf, the couple deemed it fitting for a discussion of Depression-era eating."
	},
	{
		"src": "\"Reichhaltige Lebensmittel waren sehr beliebt\", sagte Ziegelman.",
		"tgt": "\"Loaves were very popular,\" Ms. Ziegelman said."
	},
	{
		"src": "Es gab Erdnussbrot, Leberk\u00e4se und Bohnenbrot.",
		"tgt": "There was peanut loaf, liver loaf, bean loaf."
	},
	{
		"src": "Sie wurden aus einer Zutat und etwas Billigem zubereitet, das die Zutat streckt.",
		"tgt": "They were made from an ingredient and a cheap thing that stretches the ingredient out."
	},
	{
		"src": "Stellen Sie sich vor, so viele Erdn\u00fcsse zu essen, dass sie ihnen als Abendessen dienen.",
		"tgt": "Imagine eating enough peanuts to serve as your dinner."
	},
	{
		"src": "Coe grinste.",
		"tgt": "Mr. Coe grimaced."
	},
	{
		"src": "\"Es muss sich im Magen wie Blei gelegt haben,\" sagte er.",
		"tgt": "\"It must have sat in your stomach like lead,\" he said."
	},
	{
		"src": "In den Jahren vor der Gro\u00dfen Depression war der Tisch in einem amerikanischen Haushalt, vor allem in l\u00e4ndlichen Gegenden, ein All-You-Can-Eat-Buffet.",
		"tgt": "In the years before the Depression, the American table, especially in rural areas, was an all-you-can-eat buffet."
	},
	{
		"src": "Mannschaften von Frauen kochten f\u00fcr m\u00e4nnliche Feldarbeiter und es wurde frisch gebackene Pastete zum Fr\u00fchst\u00fcck, Mittagessen und Abendessen serviert.",
		"tgt": "Teams of women cooked for male farmworkers, and fresh-baked pie was served at breakfast, lunch and dinner."
	},
	{
		"src": "Es waren die Amerikaner, die w\u00e4hrend des ersten Weltkriegs Lebensmittel an hungernde Europ\u00e4er sandten. \"A Square Meal\" zeichnet die Wege auf, mit denen das Land damit umging, nicht mehr das Schlaraffenland zu sein.",
		"tgt": "It was Americans who had sent food to starving Europeans during World War I. \"A Square Meal\" chronicles the ways the nation coped with suddenly not being the land of plenty."
	},
	{
		"src": "\"Es war eine Zeit, in der Essen f\u00fcr die Amerikaner ein zentrales, angespanntes Thema wurde\", beg\u00fcndete Coe, warum er und seine Frau dar\u00fcber schreiben wollten.",
		"tgt": "\"This was a time when food became a central, fraught subject for the American people,\" Mr. Coe said, explaining why he and his wife wanted to write about it."
	},
	{
		"src": "Genauso angespannt war die neue Budgetdi\u00e4t: Geheimnisvolle Speisen wie Brote und Kasserollen wurden zu Grundnahrungsmittel, die Kasserolle als \"wundervolle Art, Essensreste wiederzuverwerten,\" merkte Ziegelman an, da K\u00f6che unappetitliche Zutaten unter einer kremigen Sauce verstecken konnten.",
		"tgt": "Equally fraught was the new budget diet: Mystery dishes like loaves and casseroles became staples, the casserole a \"wonderful way to repurpose leftovers,\" Ms. Ziegelman noted, because cooks could hide unappetizing ingredients under a creamy coating of sauce."
	},
	{
		"src": "Frisches Obst wurde durch billigeres Trockenobst ersetzt.",
		"tgt": "Fresh fruit was replaced with cheaper dried fruit."
	},
	{
		"src": "Fleisch, das jahrelang der Mittelpunkt der amerikanischen K\u00fcche war, wurde zu einem selten servierten Luxus.",
		"tgt": "Meat, for years the center of the American meal, became a sparingly apportioned luxury."
	},
	{
		"src": "Eigenartige Mischungen wurden ausprobiert, da eine kalorienreiche und n\u00e4hrhafte Befriedigung Vorrang vor Geschmack oder sogar gesunden K\u00fcchenverstand hatte.",
		"tgt": "Strange mashups were tried as caloric and nutritional fulfillment took precedent over taste or even common kitchen sense."
	},
	{
		"src": "W\u00e4hrend ihrer Recherche f\u00fcr das Buch, das auch Rezepte umfasst, bereitete Ziegelman ein Gericht aus dieser Epoche, gebackene Zwiebeln mit Erdnussbutter, zu.",
		"tgt": "In researching the book, which includes recipes, Ms. Ziegelman prepared a period dish of baked onion stuffed with peanut butter."
	},
	{
		"src": "\"Es war kein beliebter Zusatz am Mittagstsich,\" sagt Coe.",
		"tgt": "\"It was not a popular addition to the dinner table,\" Mr. Coe said."
	},
	{
		"src": "Ziegelmann f\u00fchrt weiter aus:\"Es war surreal.\"",
		"tgt": "Ms. Ziegelman amplified: \"It was surreal.\""
	},
	{
		"src": "Erdnussbutter und gebackene Zwiebeln passen nicht zueinander.",
		"tgt": "Peanut butter has nothing to say to a baked onion."
	},
	{
		"src": "Es war f\u00fcr viele der Hauswirtschaftsrezepte typisch.",
		"tgt": "It was characteristic of a lot of the home-ec recipes."
	},
	{
		"src": "Wie niemals zuvor oder seitdem, trieben Haushaltswirtschaftler - darunter Louise Stanley, Leiterin des Federal Bureau of Home Economics zwischen 1923 bis 1943 - die Essgewohnheiten des Landes derartig an.",
		"tgt": "As never before or since, home economists - among them Louise Stanley, chief of the federal Bureau of Home Economics from 1923 to 1943 - drove the country's eating habits."
	},
	{
		"src": "Indem sie Rezepte und Artikel in Zeitungen und Zeitschriften ver\u00f6ffentlichten, ermutigten sie Frauen dazu \"Haushaltspolitikerinnen\" zu werden und der Herausforderung, Pampe wie cremige Spaghetti mit Karotten in k\u00f6stliche Mahlzeiten zu verwandeln, gerecht zu werden.",
		"tgt": "Publishing recipes and articles in newspapers and magazines, they encouraged women to become \"budgeteers\" and rise to the challenge of transforming glop like creamed spaghetti with carrots into tasty dishes."
	},
	{
		"src": "\"A Square Meal\" ist ein Fest der historischen Leckerbissen.",
		"tgt": "\"A Square Meal\" is a feast of historical tidbits."
	},
	{
		"src": "Insbesondere schmackhaft sind die Berichte \u00fcber die Antwort der Regierung an die hungernden B\u00fcrger, wie Pr\u00e4sident Herbert Hoovers Lass-mich-Kuchen-Essen-Haltung.",
		"tgt": "Especially savory are the accounts of the government's response to its hungry citizenry, like President Herbert Hoover's let-me-eat-cake attitude."
	},
	{
		"src": "W\u00e4hrend er \u00f6ffentlich die einfache Iowa Bauernhausk\u00fcche seiner K\u00fcche lobte, speiste er wie der millionenschwere Mann von Welt, zu dem er geworden ist.",
		"tgt": "While he publicly praised the simple Iowa farmhouse cooking of his childhood, he dined like the millionaire sophisticate he had become."
	},
	{
		"src": "\"Er mochte kontinentale K\u00fcche wie Fisch mit Gurkensauce,\" sagte Coe.",
		"tgt": "\"He liked to eat Continental cuisine, like fish with cucumber sauce,\" Mr. Coe said."
	},
	{
		"src": "Er a\u00df in einem fast vergoldetem Speisezimmer und trug einen Smoking.",
		"tgt": "He ate in almost a gold-plated dining room, wearing a dinner jacket."
	},
	{
		"src": "Er war herrlich realit\u00e4tsfremd.",
		"tgt": "He was fabulously out of touch."
	},
	{
		"src": "Pr\u00e4sident Roosevelt h\u00e4tte vielleicht den selben Fehler begangen, wenn nicht seine Frau Eleanor ihn dazu aufgefordert h\u00e4tte, mit seinem Magen ein Exempel zu statuieren.",
		"tgt": "President Roosevelt may have committed the same error if his wife, Eleanor, had not encouraged him to set an example with his stomach."
	},
	{
		"src": "Wie im Buch beschrieben f\u00fchrte das Anheuern einer Haush\u00e4lterin mit keinem Interesse an Geschmacksrichtungen durch Frau Roosevelt dazu, dass das Wei\u00dfe Haus das langweiligste Essen in Washington hervorbrachte, sondern auch eines der am trostlosesten Zubereiteten.\"",
		"tgt": "As the book tells it, Mrs. Roosevelt's hiring of a housekeeper with no interest in flavor resulted in a White House that \"put out not only some of the dreariest food in Washington but also some of the most dismally prepared.\""
	},
	{
		"src": "Viele der Arten aus der \u00c4ra der Gro\u00dfen Depression, mit Essen umzugehen, wurde verworfen, sobald das Land wieder auf die Beine kam.",
		"tgt": "Many of the Depression-era food ways were abandoned as soon as the country got back on its feet."
	},
	{
		"src": "Das Verm\u00e4chtnis liegt auf unserem fortgef\u00fchrten Fokus auf Kalorien und Nahrung, sagte Ziegelman, sowie darauf, wie Wissenschaft auf Nahrungsmittel angewandt wurde.",
		"tgt": "The legacy is in our continued focus on calories and nutrition, Ms. Ziegelman said, and on the way science has been applied to cooking."
	},
	{
		"src": "Das Paar gab an beim Schreiben des Buches die Essgewohnheiten von Ziegelmans Schwiegermutter besser verstanden zu haben - zum Beispiel wie sie Lebensmittel nicht wegwerfen konnte.",
		"tgt": "The couple said that in writing the book, they gained greater understanding of the eating habits of Ms. Ziegelman's mother - how she couldn't throw food away, for instance."
	},
	{
		"src": "\"Sie hatte eine echte Angst vor der Verschwendung von Lebensmitteln,\" sagte Coe.",
		"tgt": "\"She had a real fear of food waste,\" Mr. Coe said."
	},
	{
		"src": "Ziegelman erinnerte sich: \"Sie machte Leute tats\u00e4chlich krank.\"",
		"tgt": "Ms. Ziegelman recalled: \"She actually got people sick.\""
	},
	{
		"src": "Da gab es den Windbeutelvorfall.",
		"tgt": "There was the cream-puff incident."
	},
	{
		"src": "Nachdem die Teller bei Eisenberg's abger\u00e4umt waren, zogen sie und Coe ein Dessert hervor, das sie zuhause zubereitet hatten: das Pflaumendessert, das Pr\u00e4sident Roosevelt zu Mittag a\u00df.",
		"tgt": "After the plates were cleared at Eisenberg's, she and Mr. Coe pulled out a dessert they had prepared at home: the prune dessert that President Roosevelt ate for lunch."
	},
	{
		"src": "\"Es wird Prune Whip genannt,\" sagte Ziegelman und f\u00fcgte hinzu, dass es ein \u00fcblicher Trick war, bescheidenen Rezepten einen schicken Namen zu verpassen.",
		"tgt": "\"It's called prune whip,\" Ms. Ziegelman said, adding that a common trick was to give modest recipes a snazzy name."
	},
	{
		"src": "Es gab keine geschlagene Sahne, nur Pflaumen, etwas Mehl, Zucker, Wasser und Zimt.",
		"tgt": "There was no whipped cream, just prunes, a little bit of flour, sugar, water and cinnamon."
	},
	{
		"src": "Jeder tauchte etwas widerwillig einen L\u00f6ffel in den z\u00e4hen, braunen Glibber ein.",
		"tgt": "Everyone reluctantly dipped a spoon into the viscous brown goo."
	},
	{
		"src": "Erstaunlicherweise schmeckte es nicht schlecht.",
		"tgt": "Surprisingly, it wasn't bad."
	},
	{
		"src": "Coe holte sich dreimal einen Nachschlag.",
		"tgt": "Mr. Coe went back for seconds, and thirds."
	},
	{
		"src": "Wie ein Can-Do-Budgetierer sagte er zu seiner Frau, \"Ein paar gehackte Waln\u00fcsse w\u00fcrden helfen.\"",
		"tgt": "Sounding like a can-do budgeter, he told his wife, \"Some chopped walnuts would help.\""
	},
	{
		"src": "Bei Bomben-Angriff get\u00f6tet: Er war der Held von Aleppo",
		"tgt": "Killed in a bomb attack: He was the hero of Aleppo"
	},
	{
		"src": "Er setzte sein eigenes Leben aufs Spiel um anderen zu helfen: Khaled Omar.",
		"tgt": "He put his own life at risk to help others: Khaled Omar."
	},
	{
		"src": "Er war der Held von Aleppo: Khaled Omar widmete sein Leben den Menschen in Syrien.",
		"tgt": "He was the hero of Aleppo: Khaled Omar dedicated his life to the Syrian people."
	},
	{
		"src": "Er riskierte alles, um Anderen das Leben zu retten.",
		"tgt": "He risked everything to save other people's lives."
	},
	{
		"src": "Jetzt ist der 30-J\u00e4hrige selbst bei einem Fassbomben-Angriff des Assad-Regimes gestorben.",
		"tgt": "Now the 30-year-old has been killed in a barrel bomb attack by the Assad regime."
	},
	{
		"src": "Omar war Mitglied der \"White Helmets\", eine Zivilschutzgruppe, die laut Bild-Zeitung bisher knapp 60.000 Menschen das Leben rettete.",
		"tgt": "Omar was a member of the \"White Helmets\", a civil protection group which, according to Bild newspaper, had saved the lives of 60,000 people."
	},
	{
		"src": "2900 Freiwillige setzen ihr eigenes Leben aufs Spiel, um Menschen aus zerbombten H\u00e4usern zu ziehen und um im Kriegsgebiet erste Hilfe zu leisten.",
		"tgt": "2,900 volunteers put their own lives at risk to pull people from bombed-out houses and perform first-aid in the war zone."
	},
	{
		"src": "Sie sind die Helden des Krieges in Syrien.",
		"tgt": "They are the heroes of the war in Syria."
	},
	{
		"src": "Omar war das Gesicht der Gruppe: Ein Video des Zivilsch\u00fctzers, das ihn bei einer 11-st\u00fcndigen Rettung eines S\u00e4uglings aus den Tr\u00fcmmern eines Hauses zeigt, ging 2014 um die Welt.",
		"tgt": "Omar was the face of the group: A video of the civil protection volunteer showing him during an 11-hour operation to rescue an infant from the ruins of a house went viral in 2014."
	},
	{
		"src": "Es machte den Syrer zur leuchtenden Symbolfigur im Grauen des Krieges.",
		"tgt": "It made the Syrian a glowing figurehead amidst the horror of the war."
	},
	{
		"src": "Als Helden hat er sich selbst jedoch nie gesehen, sagte laut Bild: \"F\u00fcr mich ist das der echte Jihad.\"",
		"tgt": "However, he never saw himself as a hero, saying, according to Bild: \"For me, this is the real jihad.\""
	},
	{
		"src": "\"Wenn ich dabei sterbe, Leben zu retten, denke ich, dass Gott in mir einen M\u00e4rtyrer sieht.\"",
		"tgt": "\"If I were to die saving lives, I would think that God saw me as a martyr.\""
	},
	{
		"src": "Kurz bevor Omar selbst einem Angriff zum Opfer fiel, hatte er in einem Video \u00fcber die letzten Bombenangriffe in Syrien gesprochen.",
		"tgt": "Shortly before Omar himself became a victim of an attack, he had spoken in a video about the recent bomb attacks on Syria."
	},
	{
		"src": "Die Helikopter haben vier Fassbomben \u00fcber dem Alzadia-Bezirk abgeworfen, eine war mit Chlorgas gef\u00fcllt.",
		"tgt": "Helicopters had released four barrel bombs over the Alzadia district, one of which was filled with chlorine gas."
	},
	{
		"src": "Eine Frau und zwei Kinder starben, sieben Menschen leiden an Atemnot.",
		"tgt": "One woman and two children were killed, and seven people have been left with breathing difficulties."
	},
	{
		"src": "\"Wir beseitigen jetzt die giftigen \u00dcberreste der Bombe, damit nicht Kinder damit spielen\", zitiert die Bild seine letzten Worte bevor er starb.",
		"tgt": "\"We are now clearing away the toxic remains of the bomb so that children don't play with it,\" quoted Bild as his last words before he died."
	},
	{
		"src": "Die t\u00f6dliche Bombe des Assad-Regimes hatte Terroristen treffen sollen.",
		"tgt": "The fatal bomb dropped by the Assad regime was supposed to have been aimed at terrorists."
	},
	{
		"src": "Gr\u00f6nlandhai: Das \u00e4lteste Wirbeltier ist fast 400 Jahre alt",
		"tgt": "The Greenland shark: The oldest vertebrate is almost 400 years old"
	},
	{
		"src": "Seltener Anblick.",
		"tgt": "It's a rare sight."
	},
	{
		"src": "Gr\u00f6nlandhaie kommen meist nur im Winter zur Oberfl\u00e4che.",
		"tgt": "Greenland sharks generally only come to the surface in winter."
	},
	{
		"src": "Dieser Hai durfte nach einer Untersuchung an Bord des Forschungsschiffs Sanna ins Meer zur\u00fcck.",
		"tgt": "After being examined on board the research ship \"Sanna\", this shark was returned to the sea."
	},
	{
		"src": "Er wurde 1624 geboren und schwimmt mit gut einem 1 km/h durch den Nordatlantik - bis heute.",
		"tgt": "It was born in 1624 and has swum through the North Atlantic at 1km/h right through to the present day."
	},
	{
		"src": "Gr\u00f6nlandhaie bekommen erst mit 150 Jahren Nachwuchs.",
		"tgt": "Greenland sharks only give birth to young at the age of 150."
	},
	{
		"src": "Gem\u00e4chlich schwimmt der Gr\u00f6nlandhai am Grund des Nordatlantiks entlang, in einer Stunde kommt er im Durchschnitt gerade 1.220 Meter weit.",
		"tgt": "Greenland sharks swim leisurely along the sea floor of the North Atlantic, covering an average of 1,220 metres in an hour."
	},
	{
		"src": "Nur wenn es drauf ankommt, beschleunigt das f\u00fcnf Meter lange Tier auf satte 2,6 km/h - und ist mit dieser H\u00f6chstgeschwindigkeit halb so schnell wie eine Robbe.",
		"tgt": "The five-metre-long animal can ramp this up to 2.6 km/h if necessary - but this maximum speed is half as fast as a seal."
	},
	{
		"src": "Dieser von Langsamkeit gepr\u00e4gte Lebensstil scheint aber ein Patentrezept f\u00fcr ein hohes Alter zu sein.",
		"tgt": "However, this slow pace of life seems to be the key to a long life."
	},
	{
		"src": "Julius Nielsen von der Universit\u00e4t von Kopenhagen und seine Kollegen berichten in der Fachzeitschrift \"Science\" jedenfalls von einem Gr\u00f6nlandhai, der 392 Jahre alt sein k\u00f6nnte.",
		"tgt": "Julius Nielsen from the University of Copenhagen and his colleagues wrote an article in \"Science\", the specialist journal, about a Greenland shark that could be 392 years old."
	},
	{
		"src": "\"Wahnsinn\", kommentiert Alexander Scheuerlein vom Max-Planck-Institut f\u00fcr demografische Forschung in Rostock diese Lebensspanne, die f\u00fcr Wirbeltiere einen Weltrekord bedeutet.",
		"tgt": "\"It's crazy,\" says Alexander Scheuerlein from the Max Planck Institute for Demographic Research in Rostock about this lifespan - which is a world record for a vertebrate."
	},
	{
		"src": "Zwar vermutete der Evolutionsbiologe schon lange, dass Gr\u00f6nlandhaie steinalt werden.",
		"tgt": "It is true that evolutionary biologists had long thought that Greenland sharks had been around for a very long time."
	},
	{
		"src": "Nur fehlten die Beweise.",
		"tgt": "They were simply lacking the proof."
	},
	{
		"src": "Gr\u00f6nlandhaie sind schwer zu beobachten, schlie\u00dflich leben sie vor allem im Eismeer vor den d\u00fcnn besiedelten K\u00fcsten von Kanada, Gr\u00f6nland, Norwegen und Spitzbergen.",
		"tgt": "It is hard to observe Greenland sharks, namely because they mainly live in the ocean off the sparsely populated coasts of Canada, Greenland, Norway and Svalbard."
	},
	{
		"src": "Weil sie Wassertemperaturen um die sechs Grad Celsius bevorzugen, tauchen sie an der Oberfl\u00e4che meist nur im Winter auf.",
		"tgt": "They generally only come to the surface in winter because they prefer water temperatures of around six degrees Celsius."
	},
	{
		"src": "\u00dcber den Lebensstil der Gr\u00f6nlandhaie wissen Forscher entsprechend wenig.",
		"tgt": "As a result, researchers know little about how Greenland sharks live."
	},
	{
		"src": "Ihr Zeitlupentempo ma\u00dfen sie, als sie vor Spitzbergen sechs Tiere mit einem Sender ausstatteten.",
		"tgt": "Their slow speed was measured by researchers off Svalbard, who fitted six animals with a tracker."
	},
	{
		"src": "Beute machen diese Haie trotzdem: Im Magen eines Tieres fanden Forscher die \u00dcberreste einer Robbe, ein anderes hatte den Kieferknochen eines jungen Eisb\u00e4ren geschluckt.",
		"tgt": "However, these sharks still manage to catch prey: In one animal's stomach, researchers found the remains of a seal; another shark had gobbled down the jawbone of a young polar bear."
	},
	{
		"src": "M\u00f6glicherweise jagen sie schlafende Tiere oder patrouillieren am Grund des Eismeeres und suchen Kadaver, die aus h\u00f6heren Wasserschichten nach unten torkeln.",
		"tgt": "It may be the case that they hunt down sleeping animals, or patrol on the ocean floor and look out for corpses that have sunk downwards from higher levels of water."
	},
	{
		"src": "Julius Nielsen und seine Kollegen untersuchten nun 28 Gr\u00f6nlandhaie, die Fischer zwischen 2010 und 2013 vor Gr\u00f6nland oder Spitzbergen als Beifang aus der Tiefe des Nordatlantiks holten.",
		"tgt": "Julius Nielsen and his colleagues have now examined 28 Greenland sharks caught in the depths of the North Atlantic by fishermen between 2010 and 2013 off the coast of Greenland or Svalbard."
	},
	{
		"src": "Der kleinste Hai war gerade 81 Zentimeter lang, w\u00e4hrend der gr\u00f6\u00dfte 502 Zentimeter ma\u00df.",
		"tgt": "The smallest shark was just 81 centimetres long, while the largest measured 502 centimetres."
	},
	{
		"src": "Um das Alter der Tiere zu ermitteln, analysierten sie mit der Kohlenstoff-14-Methode den Linsenkern der Haie.",
		"tgt": "They use carbon-14 dating on the shark's lens core to determine the shark's age."
	},
	{
		"src": "Dieses Zentrum der Augenlinse entsteht schon vor der Geburt der Haie, die darin enthaltenen Proteine werden sp\u00e4ter nicht mehr erneuert.",
		"tgt": "This core of the eye's lens comes into being even before the shark is born, and the proteins in it are not renewed subsequently."
	},
	{
		"src": "Die beiden kleinsten Haie hatten auffallend viel Kohlenstoff-14 im Linsenkern.",
		"tgt": "The two smallest sharks had remarkably high levels of carbon-14 in their lens cores."
	},
	{
		"src": "Ihre Geburt sollte daher nach den fr\u00fchen 1960er Jahren liegen, als Atomwaffenversuche gr\u00f6\u00dfere Mengen dieses radioaktiven Kohlenstoffs in die Atmosph\u00e4re schleuderten.",
		"tgt": "Consequently, they were likely born after the early 1960s, when nuclear weapons experiments released large amounts of this radioactive carbon into the atmosphere."
	},
	{
		"src": "In dem mit 220 Zentimetern L\u00e4nge drittkleinsten Tier enthielt der Linsenkern dagegen einen geringen \u00dcberschuss an Kohlenstoff-14 aus den Atomwaffenversuchen, es d\u00fcrfte bei seiner Untersuchung im Jahr 2012 also seinen 50. Geburtstag gefeiert haben.",
		"tgt": "By contrast, the lens cores of third-smallest animal, at 220 centimetres long, contained less of a surplus of carbon-14 from nuclear weapons experiments - so when it was examined in 2012, it must have already had its 50th birthday."
	},
	{
		"src": "Alle gr\u00f6\u00dferen Gr\u00f6nlandhaie hatten in ihrem Linsenkern dagegen normale Kohlenstoff-14-Mengen, das durch kosmische Strahlung in der Atmosph\u00e4re entsteht.",
		"tgt": "By contrast, all the larger Greenland sharks had normal levels of carbon-14 in their lens cores, which comes from cosmic radiation in the atmosphere."
	},
	{
		"src": "Tats\u00e4chlich zeigte die Kohlenstoff-14-Uhr f\u00fcr einen 493 Zentimeter langen Gr\u00f6nlandhai ein Alter von 335 Jahren, w\u00e4hrend der Rekord-Hai mit 502 Zentimetern sogar 392 Jahre alt sein d\u00fcrfte.",
		"tgt": "In fact, the carbon-14 monitor gave a 493-centimetre-long Greenland shark an age of 335, while the record-holding shark, at 502 centimetres, was apparently 392 years old."
	},
	{
		"src": "Dass Gr\u00f6nlandhai-Weibchen erst dann Nachwuchs bekommen, wenn sie l\u00e4nger als vier Meter sind, war bekannt.",
		"tgt": "It was already known that female Greenland sharks first had offspring when they were more than four metres long."
	},
	{
		"src": "Nun konnten die Forscher der L\u00e4nge ein Alter zuordnen.",
		"tgt": "Now researchers have been able to map this length onto an age."
	},
	{
		"src": "Da eines der Tiere mit 392 Zentimetern wohl an der Schwelle zur Geschlechtsreife stand und sein Alter mit 156 Jahren bestimmt wurde, lassen sich Gr\u00f6nlandhaie mit der Vermehrung offensichtlich mindestens eineinhalb Jahrhunderte Zeit.",
		"tgt": "As one of the animals, 392 centimetres long, was likely on the threshold of sexual maturity, and had an age of 156, it seems that Greenland sharks take at least 150 years to be able to reproduce."
	},
	{
		"src": "Auch das d\u00fcrfte f\u00fcr Wirbeltiere derzeit Weltrekord sein.",
		"tgt": "This is also a world record for vertebrates."
	},
	{
		"src": "Dass solche Methusaleme vor allem in eisigen Gew\u00e4ssern leben, ist kein Zufall.",
		"tgt": "It is not by chance that such Methuselahs predominantly live in icy waters."
	},
	{
		"src": "Auch der bisherige Rekordhalter, ein 211 Jahre alter Gr\u00f6nlandwal, in dessen Speck am Nacken eine 120 Jahre alte Harpunenspitze steckte, wurde vor Alaska gefangen.",
		"tgt": "The previous record holder, a 211-year-old Greenland whale, in whose neck a 120-year-old harpoon tip was lodged, was caught off Alaska."
	},
	{
		"src": "Durch die niedrigen Temperaturen l\u00e4uft h\u00e4ufig auch der Organismus der dort lebenden Tiere auf Sparflamme.",
		"tgt": "As a result of low temperatures, the systems of the animals living there often run on as little energy as possible."
	},
	{
		"src": "Sie reifen also sp\u00e4ter - und altern langsamer.",
		"tgt": "This means they mature later - and age slower."
	},
	{
		"src": "Um sich im kalten Wasser warm zu halten, werden die Tiere zudem oft besonders gro\u00df.",
		"tgt": "The animals often become particularly large so they stay warm in cold waters."
	},
	{
		"src": "Denn das Volumen w\u00e4chst viel schneller als seine Oberfl\u00e4che, durch die das Tier W\u00e4rme einb\u00fc\u00dft.",
		"tgt": "This is because their volume increases much quicker than their surface area, through which the animal radiates heat."
	},
	{
		"src": "Der W\u00e4rmeverlust von einem Gramm Maus ist daher viel gr\u00f6\u00dfer als bei einem Gramm Elefant.",
		"tgt": "This means that the heat lost per gram of a mouse is much bigger than that lost per gram of an elephant."
	},
	{
		"src": "Ein weiterer Vorteil: Sie haben weniger Feinde.",
		"tgt": "Another advantage is that they have fewer enemies."
	},
	{
		"src": "\"Ein kleineres Tier lebt also gef\u00e4hrlicher und sollte sich darauf konzentrieren, m\u00f6glichst fr\u00fch m\u00f6glichst viele Nachkommen zu haben\", erkl\u00e4rt der Evolutionsbiologe Scheuerlein.",
		"tgt": "\"This means that a smaller animal has a more dangerous life, and has to focus on having as many offspring as quickly as possible,\" explains Scheuerlein, an evolutionary biologist."
	},
	{
		"src": "Ein sehr gro\u00dfes Tier sollte dagegen seine Ressourcen eher in ein langes Leben investieren.",
		"tgt": "By contrast, a very large animal can invest its resources in having a longer life."
	},
	{
		"src": "Baugrund im Doppelpack",
		"tgt": "Construction sites coming as a twinpack"
	},
	{
		"src": "Mit Themen rund ums Bauen hat sich der Gemeinderat in der j\u00fcngsten Sitzung schwerpunktm\u00e4\u00dfig befasst.",
		"tgt": "The commune's council focused on construction-related topics in its most recent session."
	},
	{
		"src": "Mit Erleichterung nahm das Gremium die Mitteilung von B\u00fcrgermeister Robert Putz auf, dass \"endlich die Vermarktung der j\u00fcngst ausgewiesenen Wohnbaufl\u00e4chen beginnen kann\".",
		"tgt": "The committee was pleased to hear mayor Robert Putz' announcement that \"we can finally begin to market the residential construction sites that have recently been marked out\"."
	},
	{
		"src": "Nachdem die Grundst\u00fccks-, Parzellierungs- und Erschlie\u00dfungsfragen gekl\u00e4rt und die Antr\u00e4ge auf Vermessung gestellt werden konnten, steht dem Verkauf der Grundst\u00fccke in den Wohnbaugebieten \"Stra\u00dflweg\" und \"Sch\u00f6nau-West\" (Bereich Binderstra\u00dfe - Ausbauabschnitt 1) an Interessenten nichts mehr im Wege.",
		"tgt": "After plot, parcelling and accessibility questions had been answered, and applications for measurements had been made, there was nothing standing in the way of the sale of the plots in the residential areas of \"Stra\u00dflweg\" and \"Sch\u00f6nau-West\" (near Binderstra\u00dfe - development section 1) to interested parties."
	},
	{
		"src": "Der Gemeinderat ist \u00fcberzeugt, dass die Baufl\u00e4chen in der l\u00e4ndlich gepr\u00e4gten und ruhigen Wohngemeinde Sch\u00f6nau junge Familien und r\u00fcstige Senioren gleicherma\u00dfen ansprechen.",
		"tgt": "The communal council is convinced that the construction sites in the rural, peaceful residential commune of Sch\u00f6nau will attract young families and older people alike."
	},
	{
		"src": "Wie es hie\u00df, k\u00f6nnen sich Bauwillige ab sofort im Rathaus melden, \u00fcber die Vergabe der Parzellen wird der Gemeinderat voraussichtlich in seiner September-Sitzung beraten.",
		"tgt": "As said, people prepared to build on these sites should apply in the town hall from now, and the communal council will probably discuss giving out the plots in its September meeting."
	},
	{
		"src": "Um auch Anfragen zur Ansiedelung weiterer Gewerbebetriebe, verbunden mit der Schaffung von Arbeitspl\u00e4tzen, nachkommen zu k\u00f6nnen, beschloss der Gemeinderat, den erst im Fr\u00fchjahr dieses Jahres neu erstellten Fl\u00e4chennutzungsplan in Teilbereichen abzu\u00e4ndern.",
		"tgt": "So that it would be able to answer questions on the movement of additional businesses, in connection with the creation of jobs, the communal council decided to amend the space usage plan first re-drawn in spring of this year."
	},
	{
		"src": "So wird im Bereich Unterzeitlarn das dort schon ausgewiesene Gewerbegebiet um zwei Parzellen Richtung Staatsstra\u00dfe 2112 ausgeweitet.",
		"tgt": "Consequently, the business area already marked out in Unterzeitlarn will be expanded to include a further two plots near state road 2112."
	},
	{
		"src": "Frankfurt profitiert vom Brexit",
		"tgt": "Frankfurt will benefit from Brexit"
	},
	{
		"src": "Die Stadt am Main hat demnach im Wettbewerb mit Paris, Dublin und Luxemburg die besten Chancen, aus London verlagerte Arbeitspl\u00e4tze und Firmen anzuziehen.",
		"tgt": "The city on the river Main will soon have the best chance against the competition of Paris, Dublin and Luxembourg to draw jobs and companies away from London."
	},
	{
		"src": "\"Es ist sehr wahrscheinlich, dass Frankfurt am meisten vom Brexit-Votum profitiert\", sagt Michael Voigtl\u00e4nder, Leiter des Kompetenzfelds Finanzm\u00e4rkte und Immobilienm\u00e4rkte des IW.",
		"tgt": "\"It is highly likely that Frankfurt will benefit the most from the Brexit vote,\" said Michael Voigtl\u00e4nder, Head of IW's Financial Markets and Real Estate specialist area."
	},
	{
		"src": "Nach dem Brexit-Referendum ist es ungewiss, ob Geldh\u00e4user weiter von London aus Finanzgesch\u00e4fte in der gesamten EU betreiben d\u00fcrfen.",
		"tgt": "After the Brexit referendum it is unclear whether financial institutions will still be allowed to run European financial business from London."
	},
	{
		"src": "F\u00fcr den sogenannten EU-Pass reicht ihnen bisher die Zulassung in Gro\u00dfbritannien.",
		"tgt": "Registration in the UK is all that has been required to date for the \"EU passport\"."
	},
	{
		"src": "Das nutzen gerade gro\u00dfe US-Banken.",
		"tgt": "This is generally used by large US banks."
	},
	{
		"src": "Mehrere Banken haben schon angek\u00fcndigt, Jobs zu verlagern.",
		"tgt": "Several banks have already announced that they will relocate jobs."
	},
	{
		"src": "Die Lobbyvereinigung \"Frankfurt Main Finance\" rechnet mit 10000 neuen Arbeitspl\u00e4tzen am Main binnen f\u00fcnf Jahren.",
		"tgt": "The \"Frankfurt Main Finance\" lobbying group expects to see 10,000 new jobs on the river Main within five years."
	},
	{
		"src": "F\u00fcr Frankfurt, so das IW, spreche der Sitz der Europ\u00e4ischen Zentralbank (EZB), die Verantwortung f\u00fcr die Geldpolitik und Aufsicht \u00fcber die gr\u00f6\u00dften Banken der Eurozone vereint, sowie weiterer wichtiger Beh\u00f6rden wie der europ\u00e4ischen Versicherungsaufsicht EIOPA und des Risikorats ESRB.",
		"tgt": "According to the IW, the European Central Bank (ECB)'s headquarters, responsibility for monetary policy and supervision over the largest banks in the eurozone, all come together to represent a real plus for Frankfurt, along with further important authorities, such as EIOPA, Europe's insurance regulator, and ESRB, the risk board."
	},
	{
		"src": "In Paris habe zwar die Organisation f\u00fcr wirtschaftliche Zusammenarbeit und Entwicklung (OECD) ihren Hauptsitz, doch diese sei f\u00fcr die Finanzbranche weniger bedeutsam als die EZB.",
		"tgt": "While Paris has the headquarters of the Organisation for Economic Cooperation and Development (OECD), this is less important for the financial sector than the ECB."
	},
	{
		"src": "\"Die N\u00e4he zur Notenbank ist wichtig f\u00fcr Banken, da sie so direkt mit der Aufsicht kommunizieren k\u00f6nnen\", sagt IW-Professor Voigtl\u00e4nder.",
		"tgt": "\"The proximity to the central bank is important for banks - they can communicate directly with the authorities,\" says IW's Professor Voigtl\u00e4nder."
	},
	{
		"src": "Luxemburg beheimate zwar eine gro\u00dfe Fondsbranche, schneide aber ebenso wie Dublin bei der Infrastruktur schlechter ab.",
		"tgt": "While Luxembourg is home to a large funds industry, like Dublin, its infrastructure lets it down."
	},
	{
		"src": "Frankfurt sei dank des gro\u00dfen Flughafens deutlich leichter zu erreichen.",
		"tgt": "Thanks to its large airport, Frankfurt is considerably easier to get to."
	},
	{
		"src": "Ferner punkte die Stadt mit leicht verf\u00fcgbaren Gewerbeimmobilien.",
		"tgt": "In addition, the city's easily available business properties are a win."
	},
	{
		"src": "\"In Paris ist es gar nicht so einfach, freie hochwertige B\u00fcros zu finden\", sagt Voigtl\u00e4nder.",
		"tgt": "\"In Paris it's not all that easy to find vacant high-quality offices,\" said Voigtl\u00e4nder."
	},
	{
		"src": "An der Seine seien zudem die Mieten f\u00fcr erstklassige Gewerbeimmobilien um 50 Prozent h\u00f6her als am Main.",
		"tgt": "Rents for top-class business properties are 50% higher on the banks of the Seine than on the banks of the Main."
	},
	{
		"src": "Au\u00dferdem biete Frankfurt eine h\u00f6here Lebensqualit\u00e4t als die Konkurrenz dank guter medizinischer Versorgung und Infrastruktur sowie weniger Kriminalit\u00e4t.",
		"tgt": "In addition, Frankfurt can offer better quality of life than its competitors, thanks to its good medical systems and infrastructure, and low crime levels."
	},
	{
		"src": "In einem Ranking der Unternehmensberatung Mercer stehe die Stadt auf Platz sieben, Luxemburg auf Platz 19, Dublin auf Platz 33 und Paris an 37. Stelle.",
		"tgt": "In a table compiled by management consultants Mercer, the city was ranked 7th, Luxembourg 19th, Dublin 33rd and Paris 37 th."
	},
	{
		"src": "Auch wenn Lebensqualit\u00e4t eine Frage der Vorlieben sei: \"Mit seiner bereits starken Position als Finanzstandort f\u00fcr den europ\u00e4ischen Binnenmarkt k\u00f6nnte Frankfurt weitere Banken und Investoren anziehen\", folgert das IW.",
		"tgt": "And even if quality of life is a matter of preference: \"Thanks to its already strong position as a financial hub for the European domestic market, Frankfurt could be able to attract additional banks and investors,\" IW concluded."
	},
	{
		"src": "London werde aber trotz Brexit-Votum wichtigstes Finanzzentrum in Europa bleiben, meinen die Wirtschaftsforscher.",
		"tgt": "Despite the Brexit vote, London will remain Europe's financial capital, according to the economic researchers."
	},
	{
		"src": "Daf\u00fcr sprechen auch die Kr\u00e4fteverh\u00e4ltnisse: In London arbeiteten gem\u00e4\u00df Zahlen der Landesbank Helaba Ende 2015 rund 144000 Menschen in der Bankenbranche, in Frankfurt waren es 62500.",
		"tgt": "This is also to do with strength ratios: According to figures from regional bank Helaba, around 144,000 people worked in banking in London in 2015 - compared to 62,500 in Frankfurt."
	},
	{
		"src": "Gilead erh\u00e4lt Rechtskosten aus dem Hepatitis C Patentstreit mit Merck",
		"tgt": "Gilead to get attorney fees in hepatitis C patent fight with Merck"
	},
	{
		"src": "Ein US-Amtsrichter entschied, dass Gilead Sciences Inc Anspruch auf die R\u00fcckerstattung der Rechtskosten hat, die ihr aus dem Hepatits C Rechtsstreit mit dem Pharmaunternehmen Merck & Co Inc entstanden sind.",
		"tgt": "Gilead Sciences Inc is entitled to receive the attorney fees it incurred related to hepatitis C patent litigation with drugmaker Merck & Co Inc, a U.S. district judge has ruled."
	},
	{
		"src": "Im Juni wurde Gilead von einer Schadensersatzzahlung in H\u00f6he von $ 200 Millionen f\u00fcr die Verletzung zweier Patente von Merck befreit, die im Zusammenhang mit den Blockbuster-Medikamenten Sovaldi und Harvoni von Gilead standen, nachdem ein US-Richter ein Muster von Fehlverhalten seitens Mercks, einschlie\u00dflich des Meineides und anderer unethischer Handlungen, aufdeckte.",
		"tgt": "In June, Gilead was freed from paying up $200 million in damages for infringing two Merck patents related to Gilead's blockbuster drugs Sovaldi and Harvoni, after a U.S. judge found a pattern of misconduct by Merck including lying under oath and other unethical practices."
	},
	{
		"src": "Bei Erhebung der Klage am Donnerstag sagte US-Amtsrichterin Beth Labson Freeman, dass Gilead Anspruch auf Erlass der Kosten hat, die w\u00e4hrend der Verteidigung des Falles entstanden sind.",
		"tgt": "In a filing on Thursday, U.S. District Judge Beth Labson Freeman said that Gilead was entitled to relief from the fees it incurred while defending the case."
	},
	{
		"src": "Merck versucht mit Gilead gleichzuziehen, das den Markt einer neuen Generation von Hepatitis C Medikamenten beherrscht, die \u00fcber 90 Prozent der Patienten mit der Lebererkrankung heilen kann.",
		"tgt": "Merck is trying to catch up to Gilead, which dominates the market on a new generation of hepatitis C drugs that can cure well over 90 percent of patients with the liver disease."
	},
	{
		"src": "Der Fall geht auf das Jahr 2013 zur\u00fcck, als Gilead und Merck sich gegenseitig verklagten und Eigentum auf Laborarbeiten in Anspruch nahmen, denen Sofosbuvir zugrundelag, der aktive Inhaltsstoff in den Medikamenten von Gilead.",
		"tgt": "The case dates back to 2013 when Gilead and Merck sued each other, claiming ownership of laboratory work underlying sofosbuvir, the active ingredient in Gilead's drugs."
	},
	{
		"src": "Von den USA unterst\u00fctzte Truppen sagen, dass sie wieder vollst\u00e4ndige Kontrolle \u00fcber Manbij vom Islamischen Staat zur\u00fcckerobert haben",
		"tgt": "U.S. backed forces say they have seized full control of Manbij from Islamic State"
	},
	{
		"src": "Von den USA unterst\u00fctzte Truppen haben die vollst\u00e4ndige Kontrolle \u00fcber die n\u00f6rdliche Stadt Manbij nahe der t\u00fcrkischen Grenze zur\u00fcckerobert, nachdem die letzten IS-K\u00e4mpfer in der Stadt diese verlassen haben, sagte ein Sprecher der Gruppe am Freitag.",
		"tgt": "U.S.-backed forces have seized full control of northern city of Manbij near the Turkish border after the last remaining Islamic State fighters inside the city left, a spokesman for the group said on Friday."
	},
	{
		"src": "Die Demokratischen Kr\u00e4fte Syriens (DKS) durchk\u00e4mmen nach dem Auszug der noch verbliebenen Gruppe von K\u00e4mpfern, die sich innerhalb der Stadt vergraben haben, derzeit die Stadt.",
		"tgt": "Syria Democratic Forces (SDF) were now sweeping the city after the departure of a remaining group of militants who had been holed up in the city."
	},
	{
		"src": "Sie haben \u00fcber 2.000 Zivilpersonen befreit, die von den K\u00e4mpfern als Geiseln gehalten wurden, teilte Sharfan Darwish des mit dem DKS verb\u00fcndeten Manbij Milit\u00e4rrats Reuters mit.",
		"tgt": "They had freed over 2,000 civilian hostages who had been held by the militants, Sharfan Darwish of the SDF allied Manbij Military Council told Reuters."
	},
	{
		"src": "\"Die Stadt ist jetzt unter vollkommener Kontrolle, aber wir f\u00fchren gerade Aufr\u00e4umarbeiten durch,\" erz\u00e4hlte er Reuters.",
		"tgt": "\"The city is now fully under our control but we are undertaking sweeping operations,\" he told Reuters."
	},
	{
		"src": "Clintons verdienen 10,75 Millionen im Jahr 2015 und zahlen 34,2% Bundessteuern",
		"tgt": "Clintons earned $10.75 million in 2015, paid 34.2 percent federal tax rate"
	},
	{
		"src": "Hillary Clinton hat am Freitag ihre Steuererkl\u00e4rung f\u00fcr 2015 ver\u00f6ffentlicht, diese ergab f\u00fcr die Pr\u00e4sidentschaftskandidatin der Demokraten und ihren Ehemann ein Einkommen von USD 10,75 Millionen und eine effektiven Bundessteuersatz von 34,2%.",
		"tgt": "Hillary Clinton on Friday released her 2015 tax returns, which showed the Democratic presidential nominee and her husband had $10.75 million in income that year and paid an effective federal tax rate of 34.2 percent."
	},
	{
		"src": "Im Jahr 2015 spendeten die Clintons USD 1 Million f\u00fcr wohlt\u00e4tige Zwecke, haupts\u00e4chlich an die Clinton Foundation; der ehemalige Pr\u00e4sident Bill Clinton erwirtschaftete fast USD 5,3 Millionen in Redehonoraren; die ehemalige Au\u00dfenministerin gab ein Einkommen von USD 3 Millionen vom Verlag Simon & Schuster f\u00fcr ihr Buch \u00fcber ihre Amtszeit im Au\u00dfenministerium an.",
		"tgt": "In 2015, the Clintons made $1 million in charitable contributions, mostly to the Clinton Foundation; former President Bill Clinton brought in nearly $5.3 million in speaking fees; and the former secretary of state reported income of $3 million from publisher Simon & Schuster for her book on her tenure at the State Department."
	},
	{
		"src": "Clintons Kandidat f\u00fcr die Vizepr\u00e4sidentschaft, Senator Tim Kaine aus Virginia, ver\u00f6ffentliche zusammen mit seiner Frau Anne Holton seine Steuererkl\u00e4rungen der letzten zehn Jahre.",
		"tgt": "Clinton's running mate, U.S. Senator Tim Kaine of Virginia, along with his wife, Anne Holton, released 10 years of tax returns."
	},
	{
		"src": "Sie zahlten einen effektiven Bundessteuersatz von 20,3% im Jahr 2015.",
		"tgt": "They paid a federal effective tax rate of 20.3 percent in 2015."
	},
	{
		"src": "\"Hillary Clinton und Tim Kaine setzen weiterhin Standards in Bezug auf finanzielle Transparenz,\" gab Clintons Kampagnenhelferin Jennifer Palmieri in einer Stellungnahme bekannt.",
		"tgt": "\"Hillary Clinton and Tim Kaine continue to set the standard for financial transparency,\" Clinton campaign aide Jennifer Palmieri said in a statement."
	},
	{
		"src": "In einem krassen Gegensatz dazu versteckt sich Donald Trump hinter falschen Ausreden und R\u00fcckziehern in Bezug auf seine bisherigen Versprechungen seine Steuererkl\u00e4rungen zu ver\u00f6ffentlichen.",
		"tgt": "In stark contrast, Donald Trump is hiding behind fake excuses and backtracking on his previous promises to release his tax returns."
	},
	{
		"src": "Es ist \u00fcblich f\u00fcr US Pr\u00e4sidentschaftskandidaten ihre Steuererkl\u00e4rungen zu ver\u00f6ffentlichen, obwohl sie von Gesetzes wegen nicht dazu verpflichtet sind.",
		"tgt": "It is customary for U.S. presidential candidates to make their tax returns public, although they are not required by law to do so."
	},
	{
		"src": "Trump, ein New Yorker Gesch\u00e4ftsmann, und seine Anw\u00e4lte haben als Grund f\u00fcr seine Verweigerung eine Steuerpr\u00fcfung durch die Steuerbeh\u00f6rden angegeben.",
		"tgt": "Trump, a New York businessman, and his lawyers have cited an audit by the Internal Revenue Service as a reason for his refusal to release his returns."
	},
	{
		"src": "\"Sie sind am Zug\", schrieb Clintons Wahlkampfhelferin Ian Sams auf Twitter, in Bezug auf die Ver\u00f6ffentlichung der Pr\u00e4sidentschaftskandidatin der Demokraten.",
		"tgt": "\"Your move,\" Clinton campaign aide Ian Sams said on Twitter, linking to the Democratic nominee's returns."
	},
	{
		"src": "Am Donnerstag sagte Michael Cohen, Trumps Sonderberater, zu CNN, dass er Trump nicht erlauben w\u00fcrden, etwas zu ver\u00f6ffentlichen bevor die Steuerpr\u00fcfungen nicht abgeschlossen sind.",
		"tgt": "On Thursday, Trump's special counsel, Michael Cohen, told CNN he would not allow Trump to release them until the audits are complete."
	},
	{
		"src": "Trumps Kritiker, unter anderem auch der republikanische Pr\u00e4sidentschaftskandidat des Jahres 2012 Mitt Romney, haben bereits verlautbaren lassen, dass seine Weigerung Fragen in Bezug auf Verm\u00f6gen, seine Spenden f\u00fcr wohlt\u00e4tige Organisationen, sein Gesch\u00e4ftsgebaren und verschiedene andere Verbindungen aufwirft, insbesondere mit Russland.",
		"tgt": "Trump's critics, including 2012 Republican presidential candidate Mitt Romney and other fellow Republicans, have said his refusal raises questions about his net worth, his charitable contributions, his business dealings and various other ties, including with Russia."
	},
	{
		"src": "Clinton hat sich bereits auf das Thema gest\u00fcrzt und am Freitag ein Video im Internet ver\u00f6ffentlicht, in dem hochranginge Republikaner Trump auffordern seine Steuererkl\u00e4rung zu ver\u00f6ffentlichen.",
		"tgt": "Clinton has pounced on the issue, releasing an online video on Friday highlighting high-profile Republicans urging Trump to release his taxes."
	},
	{
		"src": "Am Donnerstag sprach sie das Thema auch w\u00e4hrend einer Rede zur Wirtschaft in Michigan an.",
		"tgt": "On Thursday, she raised the issue during an economic speech in Michigan."
	},
	{
		"src": "\"Er weigert sich das zu tun, was jeder andere Pr\u00e4sidentschaftskandidat in den letzten Jahrzehnten getan hat und seine Steuererkl\u00e4rungen zu ver\u00f6ffentlichen.\" sagte sie zu der Menge.",
		"tgt": "\"He refuses to do what every other presidential candidate in decades has done and release his tax returns,\" she told the crowd."
	},
	{
		"src": "Politico hat gemeldet, dass Trump w\u00e4hrend der 1990er f\u00fcr zwei Jahre keine oder nur sehr wenig Steuern gezahlt hat, und ein Wirtschaftsjournalist der New York Times zitierte am Freitag eine Reihe von Steueranw\u00e4ltenn und Steuerberatern, die angaben, dass das immer noch der Fall sein k\u00f6nnte.",
		"tgt": "Politico has reported that Trump paid zero to very little taxes for two years in the 1990s, and a New York Times business columnist on Friday quoted a number of tax lawyers and accountants saying that could still be the case."
	},
	{
		"src": "Bundessteuern sind im Wahlkampf zu einem Thema geworden.",
		"tgt": "Federal tax rates have become an issue in the presidential election."
	},
	{
		"src": "Clinton unterst\u00fctzt ein Regelung, die nach dem Milliard\u00e4r und Investor Warren Buffett benannt ist, die sicherstellen w\u00fcrde, dass Personen die mehr als USD 1 Million verdienen einen Steuersatz von mindestens 30% zahlen.",
		"tgt": "Clinton has endorsed a rule named after billionaire investor Warren Buffett that would ensure those making more than $1 million a year pay a tax rate of at least 30 percent."
	},
	{
		"src": "Pr\u00e4sident Obama unterst\u00fctzt den Vorschlag ebenfalls.",
		"tgt": "President Barack Obama also backs the proposal."
	},
	{
		"src": "W\u00e4hrend einer Wahlkampfveranstaltung f\u00fcr Hillary Clinton in der vergangenen Woche in Omaha, Nebraska forderte Buffett, dessen Berkshire Hathaway Industriekonglomerat hier seinen Sitz hat, Trump zu einem Treffen auf um deren Steuererkl\u00e4rungen auszutauschen.",
		"tgt": "At a Clinton rally last week in Omaha, Nebraska, Buffett, whose Berkshire Hathaway conglomerate is based there, challenged Trump to meet and exchange tax returns."
	},
	{
		"src": "Buffett sagte, er sei ebenso einer Steuerpr\u00fcfung der IRS unterzogen worden und Trump habe \"Angst\" vor den W\u00e4hlern und nicht vor den Steuerbeh\u00f6rden.",
		"tgt": "Buffet said that he too was under IRS audit and Trump is \"afraid\" not of the tax-collection agency but of voters."
	},
	{
		"src": "Clintons Kampagne hat Steuererkl\u00e4rung zur\u00fcckgehend bis zum Jahr 2007 ver\u00f6ffentlicht.",
		"tgt": "Clinton's campaign has released tax returns going back to 2007."
	},
	{
		"src": "Die Clintons, die jetzt in Chappaqua, New York, leben, zahlten im Durchschnitt einen effektiven Bundessteuersatz von ca. 32% zwischen den Jahren 2007 bis 2014 und einen effektiven kombinierten Steuersatz von ca. 40,5%.",
		"tgt": "The Clintons, who now live in Chappaqua, New York, paid an average effective federal tax rate of about 32 percent from 2007 to 2014 and an effective combined tax rate of approximately 40.5 percent."
	},
	{
		"src": "Die Steuererkl\u00e4rung der Clintons von 2015 zeigte, dass diese nur USD 100 ihres Einkommens als Lohn bezogen, anders als der Gro\u00dfteil aller Amerikaner.",
		"tgt": "The Clintons' 2015 return showed that, unlike most Americans, just $100 of their income came from wages."
	},
	{
		"src": "Ihre haupts\u00e4chliche Geldanlage war ein kosteng\u00fcnstiger Indexfonds, aus welchem die Clintons Dividenden und Ertr\u00e4ge von USD 109.000 versteuerten.",
		"tgt": "Their main investment was a low-cost index mutual fund, and the Clintons reported dividend and interest income of $109,000."
	},
	{
		"src": "Mit Beitr\u00e4gen von Kevin Drawbaugh; bearbeitet von Jonathan Otis",
		"tgt": "Additional reporting by Kevin Drawbaugh; Editing by Jonathan Oatis"
	},
	{
		"src": "Kondome mit Chilipuder, Feuerwerksk\u00f6rper f\u00f6rdern Tanzanias Elefantenschutz",
		"tgt": "Chilli-powder condoms, firecrackers boost Tanzania elephant protection"
	},
	{
		"src": "Natursch\u00fctzer in Tansania verwenden eine unorthodoxe Art, um Elefanten davon abzuhalten, in von Menschen bewohnte Siedlungen zu gehen - sie werfen Kondome auf sie, die mit Chilipuder gef\u00fcllt sind.",
		"tgt": "Conservationists in Tanzania are using an unorthodox way of keeping elephants from wandering into human settlements - by throwing condoms filled with chilli powder at them."
	},
	{
		"src": "Die Methode hat sich als effektiv erwiesen und die Honeyguide Foundation, die bereits vor Jahren die Idee dazu hatte, hat zusammen mit dem US-Naturschutz ihre F\u00f6rderung intensiviert, indem sie Freiwillige in D\u00f6rfern im Norden Tansanias trainiert, eine gewaltlose Vierstufenmethode zum Schutz ihrer H\u00e4user und Ernte zu verwenden ohne dabei Tiere zu verletzen.",
		"tgt": "The method has proved effective and Honeyguide Foundation, which hit upon the idea several years ago, with U.S.-based Nature Conservancy has stepped up its promotion, training volunteers in villages in north Tanzania to use a non-violent four-step way of protecting their homes and crops without hurting the animals."
	},
	{
		"src": "Zuvor haben viele Speere verwendet, um sich zu verteidigen.",
		"tgt": "Previously many used spears to defend themselves."
	},
	{
		"src": "Freitag ist Weltelefantentag, der dem Tierschutz gewidmet ist.",
		"tgt": "Friday is World Elephant Day, which is dedicated to the protection of the animals."
	},
	{
		"src": "\"Seitdem wir das ... Toolkit entwickelt haben, konnten wir innerhalb dieser Gemeinden eine \u00c4nderung ihrer Einstellung beobachten, wobei sie viel zuversichtlicher sind, dass sie die Elefanten von ihren Feldern abhalten k\u00f6nnen, ohne den Elefanten dabei zu schaden,\" \u00e4u\u00dferte sich der Gesch\u00e4ftsf\u00fchrer von Honeyguide Damian Bell in einer Mitteilung.",
		"tgt": "\"Since we developed the ... toolkit, we have seen an attitude change within these communities whereby they are much more confident that they can keep elephants out of their fields without harming the elephants,\" Honeyguide executive director Damian Bell said in a statement."
	},
	{
		"src": "Die ersten beiden Schritte umfassen das Beleuchten des Elefanten mit einer Fackel und das Blasen in ein Horn.",
		"tgt": "The first two steps involve shining a torch at the trespassing elephant and sounding a horn."
	},
	{
		"src": "Wenn er nicht abgeschreckt ist, wird eine sogenannten \"Chiliwolke\" geworfen.",
		"tgt": "If it is not deterred, a so-called \"chilli cloud\" is thrown."
	},
	{
		"src": "Chilipuder gemixt mit Erde wird zusammen mit einem Feuerwerksk\u00f6rper in ein Kondom zusammengepackt, dessen Ende bis auf die Z\u00fcndschnur zugedreht wird.",
		"tgt": "Chilli powder mixed with soil is packed with a firecracker into a condom, its end is twisted shut with just the fuse exposed."
	},
	{
		"src": "Wenn es angez\u00fcndet wird, platzt das Kondom mit einem Knall auf und spr\u00fcht feinen Staub an Chilipuder in die Luft.",
		"tgt": "When lit, the condom bursts open with a bang, spraying a fine dust of chilli powder into the air."
	},
	{
		"src": "Ein Hauch recht in der Regel bereits aus, um den Elefanten zu verjagen.",
		"tgt": "One whiff is usually enough to send an elephant the other way."
	},
	{
		"src": "Eine letzte M\u00f6glichkeit stellt ein Werfer dar, der ein Goldregenfeuerwerk in die Luft schie\u00dft und dabei eine laute, helle Explosion verursacht.",
		"tgt": "A last resort is a launcher that shoots a Roman candle firework into the air, producing a loud, bright explosion."
	},
	{
		"src": "Stadtrat beschlie\u00dft einstimmig: Kein Kioskneubau am St. Goarer Rheinufer",
		"tgt": "Municipal council reaches unanimous decision: No new kiosk to be built on the St. Goarer bank of the Rhine"
	},
	{
		"src": "Normalerweise nehmen die St. Goarer Investitionsvorhaben von Gewerbetreibenden mit Kusshand an - gilt doch gerade der Einzelhandel in der Kernstadt als deutlich ausbauf\u00e4hig.",
		"tgt": "Normally the people of St. Goarer are happy to accept investment from businesses - but retail in the core of the city is clearly capable of developing itself."
	},
	{
		"src": "Dem Antrag auf den Neubau eines Verkaufskiosks am Rheinufer in unmittelbarer N\u00e4he des im Bau befindlichen Rheinbalkons lehnte der Stadtrat jetzt allerdings einm\u00fctig ab.",
		"tgt": "The municipal has now unanimously rejected the application to build a new retail kiosk on the bank of the river Rhine close to the Rhine balcony currently under construction."
	},
	{
		"src": "\"Grunds\u00e4tzlich begr\u00fc\u00dfen wir neue Gewerbetreibende, aber an diesem Standort in exponierter Lage am Rheinufer passt dieser Kiosk nicht hin\", erkl\u00e4rte Michael Hubrath f\u00fcr die CDU-Fraktion.",
		"tgt": "\"We are generally happy to welcome new businesses, but this kiosk does not fit in this exposed position on the bank of the Rhine,\" explained Michael Hubrath on behalf of the CDU faction."
	},
	{
		"src": "J\u00fcdischer Regisseur zerschl\u00e4gt Berliner Hotel, weil israelische Vorwahl nach \"arabischer\" Aufforderung entfernt wurde - RT News",
		"tgt": "Jewish filmmaker slams Berlin hotel for removing Israel dial code after Arab \"request\" - RT News"
	},
	{
		"src": "Ein franz\u00f6sischer Regisseur mit j\u00fcdischen Wurzeln entfesselte einen Medienaufruhr, nachdem er verraten hatte, dass das Kempinski Bristol Hotel in Berlin keine israelische Vorwahl aufgelistet hat, da es arabische G\u00e4ste laut einem Mitarbeiter \"angefordert h\u00e4tten\".",
		"tgt": "A French filmmaker of Jewish origin unleashed a media furor after he revealed that the Kempinski Bristol hotel in Berlin does not list Israel's dial code, with employee citing \"requests\" from Arabic customers."
	},
	{
		"src": "Claude Lanzmann, Autor der Holocaustdokumentation \"Shoah\" lie\u00df seinen \u00c4rger im Kempinski Bristol Hotel in Berlin aus, indem er einen offenen Brief an die deutsche Zeitung FAZ schrieb.",
		"tgt": "Claude Lanzmann, an author of Holocaust documentary \"Shoah,\" vented his frustration at the Kempinski Bristol Hotel in Berlin, writing an open letter in the German outlet FAZ."
	},
	{
		"src": "W\u00e4hrend seines letzten Aufenthalts versuchte Lanzmann Israel auf der L\u00e4ndervorwahlliste des Hotels zu finden.",
		"tgt": "During his recent stay, Lanzmann tried to find Israel in the list of dial codes provided by the hotel."
	},
	{
		"src": "Das Land war allerdings nicht zwischen den L\u00e4ndern aufgelistet, die direkt aus dem Hotelzimmer angerufen werden k\u00f6nnen.",
		"tgt": "The country however was not mentioned among the states one can call directly from the room."
	},
	{
		"src": "Wie ist es im Jahr 2016 in Berlin, der Hauptstadt des neuen Deutschlands, m\u00f6glich, dass Israel eliminiert und gel\u00f6scht wurde?",
		"tgt": "How is it possible, in 2016 in Berlin, the capital of the new Germany, that Israel was eliminated and eradicated?"
	},
	{
		"src": "schrieb Lanzmann.",
		"tgt": "Lanzmann wrote."
	},
	{
		"src": "Stattdessen bietet das Kempinksi Bristol eine M\u00f6glichkeit, Israel \u00fcber ein eigenes Call Center anzuw\u00e4hlen.",
		"tgt": "Instead, Kempinski Bristol offers an opportunity to dial Israel via an own call center."
	},
	{
		"src": "Nach einer Erkl\u00e4rung suchend wandte sich der Regisseur an die Hotelrezeption.",
		"tgt": "Seeking explanation, the filmmaker addressed the issue at the hotel's reception."
	},
	{
		"src": "Die Antwort, die er dort erhielt, \"schockte ihn\", wie Lanzmann schrieb.",
		"tgt": "The answer he got there, Lanzmann wrote \"shocked him.\""
	},
	{
		"src": "Der Hotelangestellte sagte, dass die Ma\u00dfnahme eine \"absichtliche Entscheidung des Managements der Kempinski Hotels sei.\"",
		"tgt": "The hotel's clerk said that the measure was \"a deliberate decision by the management of Kempinski-Hotels.\""
	},
	{
		"src": "Der Grund, der dahinter stand, l\u00f6ste im Regisseur noch mehr Wut aus.",
		"tgt": "The reason behind the move triggered even more outrage by the filmmaker."
	},
	{
		"src": "\"Der Gro\u00dfteil unserer G\u00e4ste sind Araber und sie haben verlangt, dass die Vorwahl gel\u00f6scht wird,\" wurde der Angestellte von Lanzmann zitiert.",
		"tgt": "\"The majority of our guests are Arabs and they demanded Israel's code to be deleted,\" the employee was quoted as saying by Lanzmann."
	},
	{
		"src": "Der israelische Botschafter in Deutschland Yakov Hadas-Handelsman nannte dies eine \"gro\u00dfe Schande\", berichtet die S\u00fcddeutsche Zeitung.",
		"tgt": "Israeli ambassador to Germany Yakov Hadas-Handelsman called the case a \"great shame,\" Suddeutsche Zeitung reports."
	},
	{
		"src": "Wir waren von diesem Ereignis entsetzt und best\u00fcrzt.",
		"tgt": "We were appalled and shocked by the incident."
	},
	{
		"src": "Das ist wirklich sehr besch\u00e4mend.",
		"tgt": "It is in itself a great shame."
	},
	{
		"src": "Die Tatsache, dass sich dies in Deutschland in genau dieser Hotelkette zugetragen hat, ist sogar eine noch gr\u00f6\u00dfere Schande.",
		"tgt": "The fact that it has occurred in Germany and at that very hotel chain, is an even greater disgrace."
	},
	{
		"src": "Das bedarf keiner Erkl\u00e4rung.",
		"tgt": "That needs no explanation."
	},
	{
		"src": "Wir erwarten, dass das Hotel \"die richtigen Schlussfolgerungen zieht,\" sagte der Amtstr\u00e4ger.",
		"tgt": "We expect that the hotel draws the right conclusions,\" the official said."
	},
	{
		"src": "Der Vorfall l\u00f6ste eine ziemlich gro\u00dfe Resonanz im Internet aus, bei dem die Leute das Ganze einen Skandal nannten.",
		"tgt": "The incident triggered quite a response online, with people calling it a scandal."
	},
	{
		"src": "Manche unterstellten dem Kempinski Hotel, dass es den angeblichen Aufforderungen arabischer G\u00e4ste \"nachgegeben h\u00e4tte\".",
		"tgt": "Some alleged that the Kempinski hotel simply \"caved in\" to the alleged demands of Arabic customers."
	},
	{
		"src": "\"Sch\u00e4mt Euch,\" hie\u00df es in einem anderen Beitrag, in dem darauf hingewiesen wurde, dass das Hotel, das sich am noblen Kurf\u00fcrstendamm befindet, in der N\u00e4he einer Synagoge steht.",
		"tgt": "\"Shame on you,\" another post stated, pointing out that the hotel, located in the noble Kurfurstendamm street stands near a synagogue."
	},
	{
		"src": "Das Hotel wies schnell alle Anschuldigungen von sich und nannte den Vorfall ein \"Versehen\" und \"entschuldigte sich\" bei Lanzmann, berichtet Der Spiegel.",
		"tgt": "The hotel itself was quick to brush off any accusations, calling what happened an \"oversight\" and \"apologizing\" to Lanzmann, Der Spiegel reports."
	},
	{
		"src": "\"Es gab nie eine direkte Anweisung\", Israel nicht in die Schnellwahlliste aufzunehmen,\" zitierte die S\u00fcddeutsche Zeitung einen Sprecher des Kempinski Hotels.",
		"tgt": "\"There was never a direct order\" not to include Israel in the fast dial list,\" Suddeutsche Zeitung quoted a Kempinski representative as saying."
	},
	{
		"src": "Es f\u00fcgt hinzu, dass die L\u00e4ndervorwahl nun hinzugef\u00fcgt wurde.",
		"tgt": "It adds that the code was now added."
	},
	{
		"src": "Polizei setzt Tr\u00e4nengas & Gummigeschosse gegen protestierende brasilianische Studenten ein",
		"tgt": "Police use tear gas & rubber bullets against protesting Brazilian students"
	},
	{
		"src": "Studenten stie\u00dfen am Donnerstag in der brasilianischen Stadt Sao Paulo mit der Polizei zusammen, als sie sich versammelten, um gegen die Reformen der Regierung f\u00fcr das \u00f6ffentliche Bildungssystem zu demonstrieren.",
		"tgt": "Students clashed with police in the Brazilian city of Sao Paulo on Thursday as they gathered to demonstrate against government reforms to the public education system."
	},
	{
		"src": "Die Polizei setzte Tr\u00e4nengas und Gummigeschosse gegen die Demonstranten ein.",
		"tgt": "Police used tear gas and rubber bullets against the protesters."
	},
	{
		"src": "Die Schwierigkeiten fingen an, als Polizeibeamte versuchten die Studenten auseinanderzutreiben, was dazu f\u00fchrte, dass die Polizei Gummigeschosse und Tr\u00e4nengas einsetzte.",
		"tgt": "The trouble started when law enforcement officers tried to disperse the students, which led to the police using rubber bullets and tear gas."
	},
	{
		"src": "Mehrere hundert Studenten nahmen an den Demonstrationen teil, um ihre Best\u00fcrzung \u00fcber die Pl\u00e4ne auszudr\u00fccken.",
		"tgt": "Several hundred students took part in the demonstration to express their dismay at the plans."
	},
	{
		"src": "Gem\u00e4\u00df der Vorschl\u00e4ge des Gouverneurs des Bundesstaats Sao Paulo Geraldo Alckmin, werden etwas weniger als 100 \u00f6ffentliche Schulen geschlossen, w\u00e4hrend 300.000 Studenten umgesetzt werden, um Geld zu sparen.",
		"tgt": "Under proposals from the governor of the state of Sao Paulo Geraldo Alckmin, just under 100 public schools will be closed, while 300,000 students will be relocated in order to save money."
	},
	{
		"src": "Einige der Protestteilnehmer sah man Graffitits gegen den vorl\u00e4ufigen Pr\u00e4sidenten Michel Temer an W\u00e4nde spr\u00fchen.",
		"tgt": "Some of those taking part in the protest could be seen writing graffiti on the walls against the interim President Michel Temer."
	},
	{
		"src": "Die j\u00fcngsten Proteste ereigneten sich einige Tage nachdem Demonstranten in Massen auf die Stra\u00dfen gingen, um die suspendierte Pr\u00e4sidentin Dilma Rousseff zu unterst\u00fctzen, die durch ein Votum des Senats zu ihrer Abberufung aus dem Amt enthoben worden war.",
		"tgt": "This latest protest comes just days after protesters took to the streets en masse to support suspended President Dilma Rousseff as the country's senate voted for her impeachment."
	},
	{
		"src": "Handel zwischen Russland & Iran steigt pl\u00f6tzlich auf 71 % an - RT Business",
		"tgt": "Trade between Russia & Iran surges 71% - RT Business"
	},
	{
		"src": "Mit der Aufhebung der Sanktionen wuchs laut dem russischen Botschafter im Iran, Levan Dzhagaryan, der Handelsumsatz zwischen Moskau und Teheran im Jahresvergleich um 70,9 Prozent.",
		"tgt": "With the lifting of sanctions, trade turnover between Moscow and Tehran has grown 70.9 percent in year-on-year terms, according to Russia's ambassador to Iran, Levan Dzhagaryan."
	},
	{
		"src": "Seit die internationalen Sanktionen gegen den Iran aufgehoben wurden, wuchs das Interesse auf Seiten russischer Unternehmen an Gesch\u00e4ften im Land stark an, teilte der Botschafter mit.",
		"tgt": "Since international sanctions against Iran were lifted, there has been a surge in interest from Russian firms in doing business in the country, the ambassador said."
	},
	{
		"src": "Russische Unternehmen nehmen bestehende Verbindungen mit dem Iran auf, w\u00e4hrend neue Firmen bereit sind, sich Zugang zum Markt zu verschaffen.",
		"tgt": "Russian companies are resuming existing ties with Iran, while new firms are ready to get access to the market."
	},
	{
		"src": "Nat\u00fcrlich ist der weitere Handelsausbau eine der gr\u00f6\u00dften Priorit\u00e4ten der bilateralen Zusammenarbeit mit dem Iran,\" sagte Dzhagaryan.",
		"tgt": "Of course, the further expansion of trade is one of the main priorities of the bilateral cooperation with Iran,\" Dzhagaryan said."
	},
	{
		"src": "Er merkte an, dass der Handelsumsatz zwischen Russland und dem Iran in den ersten f\u00fcnf Monaten des Jahrs 2016 um 70,9 Prozent im Vergleich zu demselben Zeitraum im Jahre 2015 anstieg und $ 856 Millionen betrug.",
		"tgt": "He noted that in the first five months of 2016 the trade turnover between Russia and Iran increased by 70.9 percent compared to the same period of 2015 and amounted to $856 million."
	},
	{
		"src": "Insbesondere stiegen die russischen Importe in den Iran um 91,5 Prozent sprunghaft an und betrugen $ 697 Millionen.",
		"tgt": "In particular, Russian exports to Iran jumped by 91.5 percent and amounted to $697 million."
	},
	{
		"src": "Russische Importe aus dem Iran stiegen um 16 Prozent auf $ 158 Millionen an.",
		"tgt": "Russian imports from Iran increased by 16 percent to $158 million."
	},
	{
		"src": "Der Handelsaufschwung wurde durch Lieferungen von Maschinen, Landfahrzeugen und Waffen erreicht,\" sagte der Botschafter.",
		"tgt": "The boost in trade was achieved by supplies of machinery, ground vehicles and weapons,\" the ambassador said."
	},
	{
		"src": "Dzhagaryan geht f\u00fcr dieses Jahr von einer Rekordzahl von iranischen Touristen in Russland aus.",
		"tgt": "Dzhagaryan is also expecting a record number of Iranian tourists to visit Russia this year."
	},
	{
		"src": "Letztes Jahr gab die russische Auslandsvertretung rund 35.000 Visas, in erster Linie Reisevisas, an iranische B\u00fcrger aus.",
		"tgt": "Last year, the Russian diplomatic mission in Iran issued about 35,000 visas, mostly travel, to Iranian citizens."
	},
	{
		"src": "Des Weiteren erreichte der Iran die Top 20 der L\u00e4nder, was die Touristenanzahl in Russland betrifft.",
		"tgt": "In addition, for the first time Iran entered the top 20 countries by number of tourists visiting Russia."
	},
	{
		"src": "Man k\u00f6nnte sagen, dass die Rekordzahlen iranischer Touristen in Russland vom letzten Jahr, gebrochen werden, \" sagte er.",
		"tgt": "It's safe to say that last year's record number of Iranian tourists visiting Russia will be broken,\" he said."
	},
	{
		"src": "Gleichzeitig besuchen nur relativ wenige Russen den Iran, etwas, von dem der Botschafter hofft, dass es sich \u00e4ndern wird.",
		"tgt": "At the same time, relatively few Russians are visiting Iran, something the ambassador hopes will change."
	},
	{
		"src": "\"Ich pers\u00f6nlich kann den Besuch der St\u00e4dte Isfahan, Shiraz und Yazd empfehlen, die Monumente der alten persischen Zivilisation in einem guten Zustand erhalten haben, \" sagte er.",
		"tgt": "\"I can personally recommend to visit the cities of Isfahan, Shiraz and Yazd that have preserved monuments of ancient Persian civilization in good condition,\" he said."
	},
	{
		"src": "Zeugen gesucht: Getr\u00e4nkemarkt in Waldbr\u00f6l \u00fcberfallen",
		"tgt": "Witnesses wanted: drinks cash-and-carry in Waldbr\u00f6l raided"
	},
	{
		"src": "Ein Raub\u00fcberfall ist am Donnerstagabend auf den Getr\u00e4nkemarkt von Rewe XXL an der Waldbr\u00f6ler Gerberstra\u00dfe ver\u00fcbt worden.",
		"tgt": "A robbery took place on Thursday evening in the drinks cash-and-carry of Rewe XXL on Walbr\u00f6l's Gerberstra\u00dfe."
	},
	{
		"src": "Unter Vorhalt einer Schusswaffe forderten drei dunkel gekleidete Personen, die ihre Gesichter vermummt hatten, von dem Angestellten des Getr\u00e4nkemarktes die Herausgabe von Bargeld und fl\u00fcchteten anschlie\u00dfend zun\u00e4chst zu Fu\u00df und dann vermutlich mit einem silberfarbenen VW-Golf.",
		"tgt": "Three people dressed in dark clothing and with their faces covered brandished a gun and demanded that staff at the cash-and-carry hand over cash. They made a run for it on foot, and then probably got into a silver VW Golf."
	},
	{
		"src": "Wieviel Geld erbeutet wurde, teilt die Polizei nicht mit.",
		"tgt": "The police did not report how much money had been stolen."
	},
	{
		"src": "Die T\u00e4ter sollen zwischen 1,60 und 1,70 Meter gro\u00df gewesen sein, also relativ klein.",
		"tgt": "Between 1.6 and 1.7 m tall, the perpetrators were relatively short."
	},
	{
		"src": "Der Getr\u00e4nkemarkt ist unmittelbar vom Parkdeck des Rewe-Marktes aus zug\u00e4nglich und schlecht einsehbar.",
		"tgt": "The drinks cash-and-carry can be accessed directly from the Rewe supermarket's car park, and is tricky to observe."
	},
	{
		"src": "Die T\u00e4ter m\u00fcssen nach dem \u00dcberfall in Richtung Gerberstra\u00dfe, Friedrich-Engelbert-Weg gerannt und von dem gegen\u00fcber der Parkhauseinfahrt gelegenen Schotterparkplatz mit dem silberfarbenen Auto gefl\u00fcchtet sein, m\u00f6glicherweise in Richtung B 256 (Schladernring).",
		"tgt": "After the robbery, the perpetrators must have run towards Gerberstra\u00dfe along Friedrich-Engelbert-Weg, and then fled, possibly towards the B 256 (Schladern ring road) in the silver car from the Schotterparkplatz opposite the entrance to the multi-storey car park."
	},
	{
		"src": "Wer zur Tatzeit (gegen 19.45 Uhr) Beobachtungen gemacht hat, die im Zusammenhang mit dem Raub\u00fcberfall stehen, soll sich dringend bei der Polizei melden.",
		"tgt": "Anyone who saw anything around the time of the crime (around 7.45 p.m.) that is connected with the robbery should contact the police immediately."
	},
	{
		"src": "Nagold: Spiel und Spa\u00df bei Sommerfreizeit",
		"tgt": "Nagold: Fun and games at the summer fete"
	},
	{
		"src": "Acht sch\u00f6ne und frohe Tage verbrachten die Kinder und Jugendlichen der sozialp\u00e4dagogischen Tagesgruppe/sozialen Gruppenarbeit des Kinderschutzbundes Nagold mit ihren Betreuern auf ihrer Sommerfreizeit in Nussdorf, in der N\u00e4he von M\u00fchlacker.",
		"tgt": "Children and young people from the youth work day group/social group work project from the child protection league of Nagold spent eight gloriously happy days with their social workers during the summer camp in Nussdorf, near M\u00fchlacker."
	},
	{
		"src": "Im ruhig gelegenen Freizeitheim Hardtw\u00e4ldle war die lebensfreudige Gruppe w\u00e4hrend der ersten Schulferienwoche einquartiert.",
		"tgt": "The lively group spent the first week of the school holidays in the peacefully-located Hartw\u00e4ldle holiday camp."
	},
	{
		"src": "Mehrere Ganztagesausfl\u00fcge standen auf dem Programm.",
		"tgt": "There were several day trips on the agenda."
	},
	{
		"src": "Zum einen ging es nach Bretten mit dem Besuch des Streichelzoos.",
		"tgt": "One trip saw the group head to Bretten to visit the petting zoo."
	},
	{
		"src": "Zum anderen nach Maulbronn, wo es im weltber\u00fchmten Kloster eine spezielle Kinderf\u00fchrung gab.",
		"tgt": "Another saw them visit Maulbronn, where there was a special children's tour around the world-famous cloisters."
	},
	{
		"src": "Der dritte Ausflug f\u00fchrte nach Pforzheim.",
		"tgt": "The third trip took the group to Pforzheim."
	},
	{
		"src": "Im Keltenmuseum in Hochdorf erfuhr die Gruppe viel \u00fcber den Alltag und die Nahrung der Kelten.",
		"tgt": "The group learnt lots about how the Celts lived and what they ate in the Celtic Museum in Hochdorf."
	},
	{
		"src": "An den hei\u00dfen Tagen vergn\u00fcgte sich die Gruppe am Tiefensee in Maulbronn, welcher zum Springen, Schwimmen und Planschen einlud.",
		"tgt": "On warm dates, the group cooled off at the Tiefensee lake in Maulbronn: perfect for jumping into, swimming around in, and paddling."
	},
	{
		"src": "Kulinarisch wurden Kinder und Betreuer mit deren selbst zubereiteten Leibspeisen wie den Sauren Sp\u00e4tzle, dem Seebronner Pf\u00e4nnle, Iselshauser-Bloff, dem Englischen-Breakfast und T\u00fcbinger Bolognese verw\u00f6hnt.",
		"tgt": "Children and carers cooked their own favourite meals, such as mini German sp\u00e4tzle dumplings in a sour sauce, traditional Seebronner Pf\u00e4nnle and Iselshauser Bloff, English breakfast, and T\u00fcbingen-style bolognese."
	},
	{
		"src": "In Workshops wurde gebatikt, sch\u00f6ne Schmuckst\u00fccke aus Perlen und Steinen erschaffen oder aus Holz ein R\u00f6mische-M\u00fchle-Spiel hergestellt.",
		"tgt": "During workshops, children could practise baktik, make beautiful jewellery with pearls and stones, or create a Roman windmill game from wood."
	},
	{
		"src": "Weitere H\u00f6hepunkte der Freizeit waren das Angeln in einem nahegelegenen Teich, die Abende am Feuer und der abschlie\u00dfende \"Bunte Abend\".",
		"tgt": "Other highlights of the summer camp included fishing in a nearby pond, spending the evenings around a campfire, and the concluding \"Gala Night\"."
	},
	{
		"src": "Am Tag der Heimreise lachte die Sonne und die Kinder und Jugendlichen kehrten zufrieden heim.",
		"tgt": "When it came to go home, the sun was shining, and the children and young people headed home happy."
	},
	{
		"src": "Haigerloch: Pilgern zur Pforte der Barmherzigkeit",
		"tgt": "Haigerloch: Pilgrims at the gates of mercy"
	},
	{
		"src": "Die Ministranten aus der Seelsorgeeinheit Eyachtal-Haigerloch St. Anna waren unterwegs auf einer viert\u00e4gigen Pilgerwanderung von Villingen nach Freiburg.",
		"tgt": "The ministrants from the chaplaincy of Eyachtal-Haigerloch St. Anna went on a four-day pilgrimage from Villingen to Freiburg."
	},
	{
		"src": "Gemeinsam wurden vier Etappen bew\u00e4ltigt.",
		"tgt": "They covered four stages together."
	},
	{
		"src": "Um die Zeit bis zur n\u00e4chsten Romwallfahrt aller Ministranten in voraussichtlich zwei Jahren zu \u00fcberbr\u00fccken, hat sich die Oberministrantenrunde St. Anna zur Vorbereitung und Durchf\u00fchrung einer mehrt\u00e4gigen Pilgerwanderung entschlossen.",
		"tgt": "The committee of upper ministrants for St. Anna had decided to prepare for and go on a pilgrimage lasting several days to bridge the gap to the next pilgrimage to Rome for all ministrants, likely to take place in two years' time."
	},
	{
		"src": "Verschiedene Wallfahrtsziele wurde gepr\u00fcft und man entschied sich schlussendlich f\u00fcr die Bischofsstadt Freiburg, wo in diesem Jahr anl\u00e4sslich des Heiligen Jahres der Barmherzigkeit mit der hierzu ge\u00f6ffneten Pforte der Barmherzigkeit am Freiburger M\u00fcnster ein besonderes Pilgerziel geboten war.",
		"tgt": "Various pilgrimage sites were discussed, and a decision was finally made to go to the bishop's city of Freiburg, where, to mark the holy year of mercy, this year the gates of mercy opened for this at Freiburg cathedral are a particular pilgrimage site."
	},
	{
		"src": "16 Minis aus Bittelbronn, Gruol, Haigerloch und Heiligenzimmern machten sich auf den Weg.",
		"tgt": "16 children from Bittelbronn, Gruol, Haigerloch and Heiligenzimmern set off."
	},
	{
		"src": "Am Abend zuvor sandte Pfarrer Storost die Pilger in einer kleinen Feier in St. Anna aus, segnete die Pilgerkreuze und erteilte den Pilgersegen.",
		"tgt": "On the previous evening, Father Storost set the pilgrims off with a small celebration in St. Anna, blessed the pilgrims' cross and the pilgrims."
	},
	{
		"src": "Von Horb aus wurde per Bahn an den Startpunkt Villingen gefahren, wo auch ein M\u00fcnster Unserer Lieben Frau steht und so der Pilgerweg vom M\u00fcnster angetreten wurde.",
		"tgt": "They took the train from Horb to the starting point of Villingen, where the Cathedral of Our Lady is found. They started their pilgrimage from the cathedral."
	},
	{
		"src": "Die einzelnen Tagestouren wurden morgens und abends je von einem kurzen Impuls mit verschiedenen Gebeten, Liedern und Schrifttexten umrahmt.",
		"tgt": "The individual day trips were framed by brief moments every morning and evening with various prayers, songs and written texts."
	},
	{
		"src": "Aber auch unterwegs machten die Minis an Feldkreuzen, Kapellen oder Kirchen immer wieder Rast um gemeinsam ein Lied aus eigens zusammengestelltem Pilger-Liedheft zu singen.",
		"tgt": "Even when they were out and about, the children took breaks at wayside crosses, chapels or churches to sing a song from the pilgrims' songbook they had put together themselves."
	},
	{
		"src": "F\u00fcr die \u00dcbernachtungen standen jeweils Pfarrheime der \u00f6rtlichen Pfarreien zur Verf\u00fcgung.",
		"tgt": "The rectory of each parish they reached was available for them to stay in overnight."
	},
	{
		"src": "An den Etappenzielen sorgten Alexandra Burkhardt und Heidi Faller f\u00fcr ein schmackhaftes wie auch st\u00e4rkendes Abendessen und das Fr\u00fchst\u00fcck.",
		"tgt": "At each stage, Alexandra Burkhardt and Heidi Faller were responsible for creating a delicious, nourishing dinner and breakfast."
	},
	{
		"src": "Weiter ging es am zweiten Tag \u00fcber Furtwangen nach G\u00fctenbach.",
		"tgt": "The second day saw them head towards G\u00fctenbach, via Furtwangen."
	},
	{
		"src": "Tags darauf trat man die Etappe nach St. Peter an, welche die anstrengenste Wegstrecke war, mussten doch bei schw\u00fcler Hitze zun\u00e4chst rund 500 H\u00f6henmeter abgestiegen und danach wieder erklommen werden.",
		"tgt": "The next day, they set off on the section towards St. Peter, the most demanding section, seeing them climb around 500 metres in altitude in sweltering heat, and then descend again."
	},
	{
		"src": "Die verdiente Belohnung war abends ein gemeinsames Grillen am Badweiher.",
		"tgt": "They earned the reward of barbecueing together by the swimming pond."
	},
	{
		"src": "Nach dem Morgenimpuls am vierten Pilgertag in der imposanten Klosterkirche von St. Peter ging es auf die Schlussetappe nach Freiburg.",
		"tgt": "After the morning session on the fourth day of the pilgrimage in the impressive cloisters of St. Peter, they started off on the final stage to Freiburg."
	},
	{
		"src": "Sichtlich erleichtert und gl\u00fccklich trafen die Minis am sp\u00e4teren Nachmittag am Freiburger M\u00fcnster ein und durchschritten die Pforte der Barmherzigkeit.",
		"tgt": "The children gathered together in Freiburg Cathedral late in the afternoon, visibly relieved and happy, and passed through the gates of mercy."
	},
	{
		"src": "Mit einem kleinen Impuls wurde hier Gott gedankt.",
		"tgt": "A brief moment was taken to thank God."
	},
	{
		"src": "In der Abendmesse im M\u00fcnster wurden die am Pilgerziel angekommenen Minis von Kooperator Markus Obert begr\u00fc\u00dft.",
		"tgt": "The evening mass in the cathedral saw the children who had arrived at the pilgrimage site welcomed by Chaplain Markus Obert."
	},
	{
		"src": "Nach dem Gottesdienst konnten die Pilger die Sakristei und den Hochaltar besichtigen.",
		"tgt": "After the service, the pilgrims were able to visit the sacristry and the high altar."
	},
	{
		"src": "Am n\u00e4chsten Tag war noch Zeit f\u00fcr die Breisgaumetropole.",
		"tgt": "The next day, there was time to look around the city, located in the region of Breisgau."
	},
	{
		"src": "Nachmittags ging es per Bahn zur\u00fcck nach Horb.",
		"tgt": "In the afternoon they took the train back to Horb."
	},
	{
		"src": "Am Schluss waren sich alle Teilnehmer einig, dass die Tage von Spiritualit\u00e4t und einem starken Gemeinschaftserlebnis gepr\u00e4gt waren.",
		"tgt": "At the end, all the participants agreed that the trip was characterised by spirituality and a strong sense of camaraderie."
	},
	{
		"src": "Schotte Callum Skinner st\u00fcrmt nach Hause, als Brite Gold f\u00fcr Radsport erringt",
		"tgt": "Scot Callum Skinner storms home as Brits grab cycling gold"
	},
	{
		"src": "Schottlands Callum Skinner raste letzten Abend im M\u00e4nnerteam-Sprint im Velodrom in Rio zum Ruhm, als das britische Team den Titel von London 2012 verteidigte.",
		"tgt": "Scotland's Callum Skinner raced to glory in the men's team sprint at the Rio velodrome last night as the Team GB trio defended the title from London 2012."
	},
	{
		"src": "Der 23-J\u00e4hrige aus Glasgow nahm die Ankerrolle ein, die sein Landsmann Sir Chris Hoy sich zu Eigen gemacht hatte. Der Jungspund machte die Legende stolz, als er nach Hause st\u00fcrmte, um einen Sieg von den Favoriten Neuseeland einzuheimsen.",
		"tgt": "The Glaswegian 23-year-old was in the anchor role that his fellow Scotsman Sir Chris Hoy made his own and the youngster did the legend proud as he stormed home to snatch victory from the favoured New Zealand outfit."
	},
	{
		"src": "England beanspruchte vor vier Jahren einen schockierenden Sieg, w\u00e4hrend Hoy das f\u00fcnfte von sechs Olympiagoldmedaillen holte.",
		"tgt": "Britain claimed a shock victory four years ago to win as Hoy claimed the fifth of his six Olympic golds."
	},
	{
		"src": "Sie wiederholten den Trick, nachdem sie im M\u00e4rz bei den Bahn-Weltmeisterschaften in London trotz des R\u00fccktritts Hoys nur einen bescheidenen sechsten Platz holten.",
		"tgt": "And they repeated the trick after finishing a lowly sixth at March's Track World Championships in London, despite Hoy having since retired."
	},
	{
		"src": "Das Problem zwischen Peking und London war der Ersatz des Anfahrers Jamie Staff.",
		"tgt": "The issue between Beijing and London was replacing specialist starter Jamie Staff."
	},
	{
		"src": "Sie taten dies rechtzeitig als Hindes auftauchte.",
		"tgt": "They did so just in time as Hindes emerged."
	},
	{
		"src": "Hoys Ruhestand erzeugte eine L\u00fccke, die Kian Emadi und Matt Crampton versuchten zu schlie\u00dfen.",
		"tgt": "Hoy's retirement also created a void which Kian Emadi and Matt Crampton tried to fill."
	},
	{
		"src": "Skinner war der Mann, bei dem sie blieben, als sie Potenzial in dem Schotten sahen, das sich jetzt entfaltet hat.",
		"tgt": "Skinner was the man Britain's coaches stuck with, seeing potential in the Scot which has now been realised."
	},
	{
		"src": "Hindes, Kenny - die vor vier Jahren mit Hoy siegten - und Skinner setzten in den Qualifikationsrunden einen Olympiarekord, aber in den Standardrunden siegten die Neuseel\u00e4nder in der ersten Runde.",
		"tgt": "Hindes, Kenny - champions with Hoy four years ago - and Skinner set an Olympic record in qualifying, but the standard was overtaken by New Zealand in the first round."
	},
	{
		"src": "Und das britische Trio gewann das Duell mit Gold.",
		"tgt": "And the British trio won the duel for gold."
	},
	{
		"src": "Hindes lag nach seiner Runde knapp zur\u00fcck, aber Kenny brachte das Team nach vorne und Skinner hielt es.",
		"tgt": "Hindes was narrowly behind after his lap, but Kenny pushed the team in front and Skinner held on."
	},
	{
		"src": "Ein Strategiewechsel machte einen gro\u00dfen Teil der Transformation aus, bei dem Hindes in einem h\u00f6heren Gang fuhr, um ihn zu verlangsamen und es Kenny und vor allem Skinner zu erm\u00f6glichen, das Tempo zu halten.",
		"tgt": "A change of strategy was a big part of the transformation, with Hindes riding a bigger gear to slow him down and allow Kenny and, in particular, Skinner to keep pace."
	},
	{
		"src": "Hoy sah von seiner Position als BBC-Experte aus zu und fiel Skinner, Kenny und Hindes auf, als diese auf das Podest stiegen.",
		"tgt": "Hoy watched on from his position as a BBC pundit and caught the eye of Skinner, Kenny and Hindes when they stepped on to the podium."
	},
	{
		"src": "Der 23-j\u00e4hrige Skinner aus Glasgow sagte: \"Es ist ein schmeichelnder Vergleich.\"",
		"tgt": "The 23-year-old Skinner, from Glasgow, said: \"It's a flattering comparison.\""
	},
	{
		"src": "Ich bin nur hier, um mein Bestes zu tun und mir einen Namen zu machen.",
		"tgt": "I'm just out there to do my best and make a name for myself."
	},
	{
		"src": "Wir haben in der Endrunde einen Olympiarekord aufgestellt und die Weltmeister besiegt.",
		"tgt": "We set an Olympic record in the final and beat the world champions."
	},
	{
		"src": "Es war einfach unglaublich.",
		"tgt": "It was just incredible."
	},
	{
		"src": "Es gibt keine bessere Art dies zu gewinnen.",
		"tgt": "There's no better way to win it."
	},
	{
		"src": "Nach dem Triumph 2012 an der Seite Kennys und Hoys gab Hindes zu, dass er nach einem schwachen Start absichtlich auf die Bahn fiel.",
		"tgt": "After triumphing at London 2012 alongside Kenny and Hoy, Hindes admitted to deliberately falling to the track following a poor start."
	},
	{
		"src": "Er zog diese Aussage sp\u00e4ter zur\u00fcck und es kam kein Einspruch von Englands Rivalen.",
		"tgt": "He later retracted the comment and there was no method of appeal from Britain's rivals."
	},
	{
		"src": "Bei so einem \u00fcberragendem Sieg gab es dieses Mal kein solches Problem.",
		"tgt": "There was no such issue this time around in a supreme victory."
	},
	{
		"src": "Hindes sagte: \"Es f\u00fchlt sich mit den ganzen GB Flaggen auf der Trib\u00fcne wie London an.\"",
		"tgt": "Hindes said: \"It felt like London, with all the GB flags in the stand.\""
	},
	{
		"src": "Wir sind in den letzten drei Monaten als Team zusammengekommen.",
		"tgt": "We all as a team came together in the last three months."
	},
	{
		"src": "Wir sind bei so vielen Welttiteln so schlecht weggekommen, dass es unglaublich war, wieder bei der Olympiade zu gewinnen.",
		"tgt": "We've been losing out on so many world titles, so to win the Olympics again is just amazing."
	},
	{
		"src": "Das ist ein Ereignis, eine Goldmedaille f\u00fcr die Nation, die sieben von 10 Titeln sowohl in Peking als auch in London gewonnen wurden.",
		"tgt": "That is one event, one gold medal for the nation which won seven out of 10 track titles in both Beijing and London."
	},
	{
		"src": "Wenn das ein Barometer unseres Fortschritts in den letzten f\u00fcnf Monaten ist, dass erwarten uns erfolgreiche f\u00fcnf Tage im Velodrom.",
		"tgt": "If that is a barometer of the progress made in the last five months, then a successful five days in the velodrome awaits."
	},
	{
		"src": "Mit der Form Kennys ist es im Bereich des M\u00f6glichen, dass er Hoys Sieg von drei olympischen Goldmedaillen in einem Wettbewerb wiederholt.",
		"tgt": "With the form Kenny demonstrated, it is not beyond the realms of possibility to imagine him repeating Hoy's feat of winning three Olympic golds in one Games."
	},
	{
		"src": "Das w\u00fcrde f\u00fcr Kenny - der genau 12 Jahre j\u00fcnger als Hoy ist, der ebenfalls am 23. M\u00e4rz geboren wurde (ein anscheinend heiliges Datum f\u00fcr den britischen Sport; an dem Tag wurden auch Steve Redgrave, Mo Farah und Roger Bannister geboren) - eine Ausbeute von sechs Goldmedaillen und einer Silbermedaille bedeuten.",
		"tgt": "That would see Kenny - who is exactly 12 years younger than Hoy, who is also born on 23 March (that seemingly sacred date in British sport which is also the birthday of Steve Redgrave, Mo Farah and Roger Bannister) - take his tally to six gold medals and one silver."
	},
	{
		"src": "Das k\u00e4me der von Hoy gleich.",
		"tgt": "That would be the same as Hoy's."
	},
	{
		"src": "Kenny nimmt als n\u00e4chstes im Sprint teil, der heute beginnt und \u00fcber drei Tage gehen wird.",
		"tgt": "Kenny next competes in the sprint, which begins on today and plays out over three days."
	},
	{
		"src": "Der 28-j\u00e4hrige aus Bolton sagte: \"Ich genie\u00dfe dies nur f\u00fcr den Moment.\"",
		"tgt": "The 28-year-old from Bolton said: \"I'm just enjoying this one for now."
	},
	{
		"src": "Das Team-Ereignis ist immer am besten.",
		"tgt": "The team event is always the best."
	},
	{
		"src": "Man kann es mit seinen Kollegen gewinnen.",
		"tgt": "You get to win it with your mates."
	},
	{
		"src": "Es f\u00fchlt sich etwas einsam an, alleine zu gewinnen.",
		"tgt": "It's a bit lonely winning on your own to be honest."
	},
	{
		"src": "Hindes sagte: \"Wenn er zwei weitere Goldmedaillen gewinnt, sollte er zum Ritter geschlagen werden.\"",
		"tgt": "Hindes said: \"If he wins another two gold medals, he should get a knighthood.\""
	},
	{
		"src": "Es war der einzige Medaillenwettbewerb des Tages, aber es gab weitere gute Nachrichten f\u00fcr England.",
		"tgt": "It was the day's only medal event, but there was further good news for Britain."
	},
	{
		"src": "Sir Bradly Wiggins, Ed Clancy, Steven Burke und Owain Doull qualifizierten sich mit der schnellsten Leistung im Vierer-Vier-Kilometerrennen.",
		"tgt": "Sir Bradley Wiggins, Ed Clancy, Steven Burke and Owain Doull qualified fastest in the four-man, four-kilometres team pursuit."
	},
	{
		"src": "Sie kamen in 3:51,942 am Ziel an.",
		"tgt": "They finished in 3:51.943."
	},
	{
		"src": "Der Weltrekord, der 2012 in London Gold gewann, lag bei 3:51,659.",
		"tgt": "The world record, set in winning gold at London 2012, is 3:51.659."
	},
	{
		"src": "Die erste und finale Runde (22.42) finden heute am zweiten Tag des Wettbewers statt, bei dem Wiggins mit Sicherheit im Fokus stehen wird.",
		"tgt": "The first round and final (10.42pm) take place on today's second day of action, where Wiggins is sure to be the focus."
	},
	{
		"src": "Er hatte sich gestern mit Beauftragten vor der Qualifikation gestritten, als ihn Funktion\u00e4re zu sich riefen, um seine K\u00f6rpergr\u00f6\u00dfe zu messen.",
		"tgt": "He had a dispute with commissaires yesterday ahead of the qualification ride, when officials summoned him to measure his height."
	},
	{
		"src": "Im entsprechendem Frauenwettbewerb, der morgen fortgesetzt und beendet wird, avancierten Laura Trott, Joanna Rowsell Shand, Elinor Barker und Katie Archibald of Milngavie in Weltrekordszeit in 4:13,260.",
		"tgt": "In the corresponding women's event, which resumes and concludes tomorrow, Laura Trott, Joanna Rowsell Shand, Elinor Barker and Katie Archibald of Milngavie advanced in a world record time, clocking 4:13.260."
	},
	{
		"src": "Das GB Team verl\u00e4sst sich auf sein starkes Bahnradteam, um die mittlere Periode der Olympischen Spiele zu dominieren und eine Schar an Medaillen zu holen.",
		"tgt": "Team GB have come to rely on its mighty track cycling squad to take ownership of the middle period of an Olympic Games and deliver a host of medals."
	},
	{
		"src": "Nach einer wahrlich au\u00dfergew\u00f6hnlichen Darstellung von absoluter Dominanz in Peking und London wurden die Erwartungen f\u00fcr Rio heruntergefahren.",
		"tgt": "After truly exceptional showings of utter dominance at Beijing and London, expectations have been played down in the lead-up to Rio."
	},
	{
		"src": "Es spielten sich Dramas im Hintergrund ab, so der R\u00fccktritt des technischen Leiters Shane Sutton im April inmitten von Sexismus- und Mobbingvorw\u00fcrfen sowie der Ruhestand von Gr\u00f6\u00dfen wie Hoy und Victoria Pendleton.",
		"tgt": "There have been dramas in the background, not least the resignation of technical director Shane Sutton in April amid sexism and bullying allegations, and the retirements of giant figures like Hoy and Victoria Pendleton."
	},
	{
		"src": "Wenn man sich jedoch den ersten Abend des Wettbewerbs im Velodrom ansieht, sieht es ganz danach aus, als k\u00f6nnte der nun legend\u00e4re Ruf GBs, der zum perfekten Moment seinen H\u00f6hepunkt erreicht hat, wieder wiederholt werden.",
		"tgt": "However, on the evidence of the first night's racing in the velodrome, it looks like GB's now legendary reputation for peaking at the perfect time could be about to be repeated once again."
	},
	{
		"src": "Zukunft der Schmelzerei von Portland aufgrund von Aufhebung des Energievertrages fraglich",
		"tgt": "Portland smelter's future in doubt with axing of power contract"
	},
	{
		"src": "Die Zukunft der Aluminiumschmelze von Portland in Victoria - sowie hunderter Arbeitspl\u00e4tze von Arbeitern - stehen auf dem Spiel, da der Anlagenbetreiber den Energieliefervertrag k\u00fcndigen und damit s\u00e4mtliche Liefervertr\u00e4ge aufheben wird, wie das liefernde Energieunternehmen mitteilte.",
		"tgt": "The future of the Portland aluminium smelter in Victoria - and the jobs of hundreds of workers - is in doubt with the power company which supplies the plant disclosing one of the plant's owners is to terminate a supply contract, with all supply contracts expected to be axed."
	},
	{
		"src": "Dieser Schritt folgte der Entscheidung der Regierung in Victoria Anfang dieses Jahres, keine weiteren Subventionen zum Betrieb der Anlage zu vergeben.",
		"tgt": "The move follows the decision of the Victoria government earlier this year to not extend subsidies provided to keep the plant in operation."
	},
	{
		"src": "Eine f\u00fcr 20 Jahre festgelegte Subvention l\u00e4uft im November aus.",
		"tgt": "A 20-year fixed subsidy expires in November."
	},
	{
		"src": "Bis zu 2000 Arbeitspl\u00e4tze in der Anlage von Alcoa in Portland stehen auf dem Spiel.",
		"tgt": "Up to 2000 jobs may be at risk at Alcoa's Portland plant."
	},
	{
		"src": "Nicht weniger als 2000 Arbeitspl\u00e4tze -direkte sowie indirekte - k\u00f6nnten bei einer Schlie\u00dfung gef\u00e4hrdet sein.",
		"tgt": "As many as 2000 jobs - direct and indirect - could be at risk with any closure."
	},
	{
		"src": "Dar\u00fcber hinaus k\u00f6nnte es zu Dominoeffekten kommen, da die Schmelzerei rund 10 Prozent der gesamten Stromerzeugung Victorias verbraucht.",
		"tgt": "And there could be additional knock-on effects since the smelter consumes around 10 per cent of Victoria's entire electricity output."
	},
	{
		"src": "2014 schloss Alcoa die Point Henry Schmelzerei, was letztes Jahr zu einer Schlie\u00dfung des Anglesea Kraftwerks f\u00fchrte.",
		"tgt": "In 2014, Alcoa closed the Point Henry smelter which led to the closure last year of the Anglesea power plant."
	},
	{
		"src": "Die Schmelzerei von Alcoa in Portland verliert Geld und riskiert eine Schlie\u00dfung.",
		"tgt": "Alcoa's Portland smelter is losing money and risks closure."
	},
	{
		"src": "Dieser Schritt folgt den jahrelangen Spekulationen hinsichtlich der Zukunft der Anlage, urspr\u00fcnglich als Folge des starken Australischen Dollars und zuletzt aufgrund des Strompreises f\u00fcr die Anlage.",
		"tgt": "The moves follows speculation about the future of the plant for several years now, initially in the wake of the strong Australian dollar and more recently due to the price for the output from the plant."
	},
	{
		"src": "AGL, das die gro\u00dfe Aluminiumschmelzerei mit seinem Loy Yang A Kraftwerk in Latrobe Valley beliefert, teilte mit, dass es davon ausgeht, dass drei weitere Besitzer ihre Vertr\u00e4ge k\u00fcndigen werden.",
		"tgt": "AGL, which supplies the big aluminium smelter with electricity from its Loy Yang A power plant in the Latrobe Valley, said it expects the other three owners will also move to terminate their agreements."
	},
	{
		"src": "Die Anlage befindet sich im mehrheitlichen Besitz einer Joint Venture von Alcoa und Alumina, wovon das chinesische Unternehmen CITIC und die japanische Marubeni Corp kleinere Anteile halten.",
		"tgt": "The plant is majority owned by a joint venture of Alcoa and Alumina, with China's CITIC and Japan's Marubeni Corp holding smaller shares."
	},
	{
		"src": "\"AGL geht davon aus, dass die Anlage in Portland weiterhin betrieben wird, was eine weitere physische Nachfrage nach Strom durch die Schmelzerei bedeutet,\" teilte das Unternehmen mit.",
		"tgt": "\"AGL expects the Portland facility to continue to operate, meaning physical demand for electricity from the smelter will continue,\" it said."
	},
	{
		"src": "AGL sagte weiterhin aus, dass die Vertr\u00e4ge sogenannte \"Sicherungsgesch\u00e4fte\" seien, die ab November 2016 in Kraft h\u00e4tten treten sollen.",
		"tgt": "AGL said the contracts are so-called 'hedging contracts' which were due to take effect from November 2016."
	},
	{
		"src": "Die Vertr\u00e4ge haben eine 12-monatige K\u00fcndigungsfrist, sodass sie 2017 enden werden.",
		"tgt": "The contracts have a 12-month termination period so they will actually finish in 2017."
	},
	{
		"src": "\"Von daher geht AGL davon aus, dass die Vertr\u00e4ge im Gesch\u00e4ftsjahr 17 zu den Einnahmen beitragen werden,\" sagte der Stromlieferant.",
		"tgt": "\"As such, AGL continues to expect the contracts to contribute to earnings in fiscal year 17,\" the power company said."
	},
	{
		"src": "S\u00e4mtliche potenzielle Auswirkungen auf die Einnahmen auf AGL ab dem GJ 18 sind derzeit durch die Prognosen der starken Terminm\u00e4rkte f\u00fcr Gro\u00dfhandelsstrompreise beschr\u00e4nkt.",
		"tgt": "Any potential earnings impact on AGL from FY18 onwards is currently limited by the strong futures market outlook for wholesale electricity prices."
	},
	{
		"src": "AGL teilte mit, dass es den Wert der Vertr\u00e4ge bereits in seinem Jahresabschlus in H\u00f6he von $ 187 Million in \"Erwartung einer K\u00fcndigung\" abgeschrieben habe.",
		"tgt": "AGL said it had already written down the value of the contracts in its accounts by $187 million in \"anticipation of a termination event.\""
	},
	{
		"src": "Alcoa sagte, dass die Entscheidung, die Vertr\u00e4ge auszubuchen, die\"F\u00e4higkeit Alcoas... die Schmelzerei zu betreiben oder die Stromversorgung an die Schmelzerei zu gew\u00e4hrleisten\" nicht beeintr\u00e4chtige.",
		"tgt": "Alcoa said the decision to close out the contracts \"does not affect Alcoa's ... ability to operate the smelter or secure electricity supply to the smelter.\""
	},
	{
		"src": "Das US-Unternehmen sagte, dass es 2010 einen 20-Jahres-Vertrag mit Loy Yang abgeschlossen habe, der von November dieses Jahr an h\u00e4tte in Kraft treten sollen, auch wenn es noch eine Erkl\u00e4rung schuldig ist, warum es vom Vertrag zur\u00fcckgetreten ist.",
		"tgt": "The US company said it entered into a 20-year contract with Loy Yang in 2010 , which was due to commence from November this year, although it has yet to explain why it has pulled out of the contract."
	},
	{
		"src": "Analytiker warnen aufgrund der schlechten wirtschaftlichen Verh\u00e4ltnisse der Branche vor der m\u00f6glichen Schlie\u00dfung der Portland Schmelzerei in Victoria und der Tomago Anlage in der N\u00e4he von Newcastle.",
		"tgt": "Analysts have been wary of the possible closure of both of the Portland smelter in Victoria and also the Tomago plant near Newcastle due to the poor economics of the industry."
	},
	{
		"src": "In Bezugnahme auf die Aussagen der Analytiker Anfang der Woche sagte der Head of Operations Stephen Mikkelsen, dass Portland j\u00e4hrlich rund 600 Megawatt und Tomago rund 900 Megawatt an Strom verbrauchen.",
		"tgt": "Addressing analysts earlier in the week, AGL's head of operations, Stephen Mikkelsen said Portland uses around 600 megawatts of power annually and Tomago around 900 megawatts."
	},
	{
		"src": "Sollten beide Anlagen vom Markt verschwinden, w\u00fcrde das eine erhebliche Verringerung der Nachfrage auf dem [Strommarkt] bedeuten.",
		"tgt": "If both of those plants go from the market that's a significant reduction in demand in the [electricity] market."
	},
	{
		"src": "Und f\u00fcr uns als Stromerzeuger w\u00e4re das nicht gut,\" sagte er.",
		"tgt": "And as a generator that wouldn't be good for us,\" he said."
	},
	{
		"src": "Mehr als nur ein Kardashian Reality-TV-Star, Kendall ist auf dem Cover der Septemberausgabe der Vogue",
		"tgt": "Not just a Kardashian reality TV star, Kendall's on the cover of September's Vogue"
	},
	{
		"src": "Kendall Jenner, 20, Model und vierte Tochter der Managerin und Mutter des Kardashian-Jenner Clans Kris ist auf dem Cover der begehrten Septemberausgabe der US Vogue.",
		"tgt": "Kendall Jenner, 20, model and fourth daughter of mother-manager Kris's Kardashian-Jenner clan, is on the cover of US Vogue's coveted September issue."
	},
	{
		"src": "Kendall, die Markenbotschafterin von Estee Lauder ist und auf den Fashion Weeks in Mailand, Paris und New York lief, verk\u00fcndete am Donnerstag die Neuigkeiten auf ihrem Instagram-Konto.",
		"tgt": "Kendall, who is an Estee Lauder brand ambassador and has walked in Milan, Paris and New York fashion weeks, announced the news on her Instagram account on Thursday."
	},
	{
		"src": "\"In einem Raum voller Leute, die ich liebe, brachte mich der Anblick dieses Covers zum Weinen,\" schrieb Kendall.",
		"tgt": "\"In a room with a bunch of people I love, looking at this cover made me cry,\" Kendall wrote."
	},
	{
		"src": "Der Enth\u00fcllung des Covers folgte ein bizarres (oder einfach Keeping Up with the Kardashians \u00e4hnliches?), geskriptetes Reality-Video, das die gesamte Kardashian-Jenner Familie zeigt (mit Ausnahme der Problemf\u00e4lle Rob und Caitlyn sowie in Anwesenheit des allseits beliebtesten Showbiz-Onkels und Produzenten von Keeping Up Ryan Seacrest), wie sie das Cover ihrer Schwester vergessen und das mit einer klassischen Wendung endet: sie haben alle eine \u00dcberraschungsparty geplant.",
		"tgt": "The cover revelation was followed by a bizarre (or simply Keeping Up with the Kardashians-esque?), scripted reality video that featured the entire Kardashian-Jenner family (bar troublemakers Rob and Caitlyn, and joined by everyone's favourite showbiz uncle, Keeping Up producer Ryan Seacrest) forgetting about their sister's cover, only to end with the classic twist: they were all planning a surprise party."
	},
	{
		"src": "Das stellt die klischeebehaftete Handlung nahezu jeder Geburtstagsepisode einer Kindersendung dar (Seacrest brachte den Satz, \"Du dachtest, dass wir Dich vergessen h\u00e4tten?,\" mit der Ehrlichkeit eines Zeichentrickkaninchens auf einem Sendeplatz um 8 Uhr morgens), aber Kris musste ihre anderen M\u00e4dchen irgendwie an dieser Publicity teilnehmen lassen.",
		"tgt": "It's the cliche plot line of nearly every \"birthday\" episode of a children's television show (Seacrest delivers the line, \"You thought we forgot about you?,\" with the sincerity of a cartoon rabbit in an 8am timeslot), but Kris had to get her other girls in on this publicity somehow."
	},
	{
		"src": "Mit Hinblick auf die Septemberausgabe der Vogue hat mit Sicherheit eine neue \u00c4ra der Kardashians begonnen.",
		"tgt": "Because, with a spot on Vogue's September issue, we have surely entered a new era of Kardashian."
	},
	{
		"src": "Kendalls gro\u00dfe Schwester Kim mag sie, was das Vogue-Cover angeht, geschlagen haben (sie und ihr Mann Kanye West waren darauf im April 2014 zu sehen), doch das Cover der Septemberausgabe der Zeitschrift ist eine Liga f\u00fcr sich.",
		"tgt": "Kendall's big sister Kim may have beaten her to the cover of Vogue (she shared it with husband Kanye West in April 2014), but the magazine's September cover is a league unto itself."
	},
	{
		"src": "Die Septemberausgabe ist f\u00fcr Vogue die am meist verkaufteste Ausgabe des Jahres.",
		"tgt": "The September Issue is Vogue's highest selling edition of the year."
	},
	{
		"src": "Mit einem Umfang, der eher einem Bildband als einer Modezeitschrift \u00e4hnelt, zieht die Ausgabe eine gro\u00dfe Anzahl an Werbetreibenden an (Laut Fashionista waren von den 832 Seiten des W\u00e4lzers 615 Seiten Werbung).",
		"tgt": "With a thickness more closely resembling a coffee table book than a fashion magazine, the issue attracts a huge number of advertisers (Fashionista counted 615 of last year's 832-page tome as advertising content)."
	},
	{
		"src": "Die Enth\u00fcllung seines Coverstars wird so sehns\u00fcchtig erwartet, dass in den letzten zwei Jahren Bilder der Zeitschrift noch vor der offiziellen Bekanntgabe durchsickerten.",
		"tgt": "The revelation of its cover star is so hotly anticipated that, in the past two years, pictures of the magazine have been leaked before the official announcement."
	},
	{
		"src": "Frauen, die bereits auf dem Cover waren, umfassen Naomi Campbell, Linda Evangelista und Kate Moss.",
		"tgt": "Previous women to feature on the cover include Naomi Campbell, Linda Evangelista and Kate Moss."
	},
	{
		"src": "In den letzten Jahren waren eindeutig mehr \"Ber\u00fchmtheiten, die modeln\" als \"Models, die Ber\u00fchmtheiten sind\" auf dem Cover.",
		"tgt": "In recent years, the cover has certainly featured more \"celebrities who model\" than \"models who are celebrities.\""
	},
	{
		"src": "Oscar-Preistr\u00e4gerin und Dior-Markenbotschafterin Jennifer Lawrence war 2013 auf dem Cover, ein Jahr nachdem Lady Gaga die Ehre hatte.",
		"tgt": "Oscar winner and Dior ambassador Jennifer Lawrence was featured in 2013, the year after Lady Gaga had the honour."
	},
	{
		"src": "Aber selbst bei der geringen Chance, dass Frau Jenner - die von der Zeitschrift als das \"Durchbruchmodel\" ihrer Generation beschrieben wird - unter die fr\u00fchere Kategorie f\u00e4llt, befindet sie sich in guter Gesellschaft.",
		"tgt": "But, even on the off-chance that Ms Jenner - who is described by the magazine as the \"breakout model\" of her generation - falls into the former category, she is in pretty good company."
	},
	{
		"src": "Diese Ber\u00fchmtheiten sind nicht mit ber\u00fchmten Personen verwandt oder Reality Stars oder Jugendliche von heute, die wissen, wie man ein gutes Snapchat-Video dreht (auch wenn davon alles auf Jenner zutrifft).",
		"tgt": "These celebrities are not relatives of famous people, or reality stars, or kids these days who know how to make a good Snapchat video (although Jenner is all of these things)."
	},
	{
		"src": "Sie sind wirklich talentierte Frauen, die sich in der Unterhaltungsbranche auszeichnen.",
		"tgt": "They are legitimately talented women, excelling in the entertainment industry."
	},
	{
		"src": "Beyonce, die auf dem letzten Cover erschien, hatte mit der Ver\u00f6ffentlichung von Lemonade eines der erfolgreichsten Jahre ihrer Karriere.",
		"tgt": "Beyonce, who appeared on last year's cover, has had one of the strongest years of her career with the release of Lemonade."
	},
	{
		"src": "Nat\u00fcrlich gef\u00e4llt Jenners Erfolg nicht jedem.",
		"tgt": "Of course, not everyone is pleased about Jenner's success."
	},
	{
		"src": "Mit ihrer Reality-TV-Geschichte war Jenners Stellung in der Modewelt immer etwas angespannt.",
		"tgt": "With her reality television history, Jenner's position within the fashion world was always going to be fraught."
	},
	{
		"src": "Im Juni kritisierte das einstige Victoria's Secret-Modell Stephanie Seymour Jenner und ihre Kollegin Gigi Hadid und nannte sie \"die Mistst\u00fccke des Augenblicks.\"",
		"tgt": "In June, original Victoria's Secret model Stephanie Seymour criticised Jenner and her colleague Gigi Hadid, calling them the \"bitches of the moment.\""
	},
	{
		"src": "Diese Gef\u00fchle kochten wieder hoch, als die Nachricht mit dem Erscheinen Jenners auf dem Vogue Cover herauskam.",
		"tgt": "This sentiment has boiled up again with the news of Jenner's Vogue cover appearance."
	},
	{
		"src": "Aber auf dem Missmut herumzureiten scheint am Punkt vorbeizugehen.",
		"tgt": "But dwelling on the discontent seems beside the point."
	},
	{
		"src": "Kendall Jenner ist auf dem Cover der Septemberausgabe der Vogue.",
		"tgt": "Kendall Jenner is on the cover of the September Issue of Vogue."
	},
	{
		"src": "Sie ist im wahrsten Sinne des Wortes ein Supermodel.",
		"tgt": "She is a supermodel, in the purest sense of the word."
	},
	{
		"src": "Sie l\u00e4uft f\u00fcr Marc Jacobs.",
		"tgt": "She's walking for Marc Jacobs."
	},
	{
		"src": "Sie macht Werbung f\u00fcr Ihre Grundierung von Estee Lauder.",
		"tgt": "She's selling you Estee Lauder foundation."
	},
	{
		"src": "Sie und all ihre Schwestern verkaufen Ihnen Bilder von sich auf ihren jeweiligen Paywall-Apps.",
		"tgt": "She, and all of her sisters, are selling you pictures of themselves on their respective paywalled apps."
	},
	{
		"src": "Sie verkauft von ihr gemachte Bilder von Cindy Crawfords Tochter an die Zeitschrift LOVE.",
		"tgt": "She's selling pictures of Cindy Crawford's daughter she photographed to LOVE magazine."
	},
	{
		"src": "Und in ihrer Freizeit ist sie im Reality TV zu sehen. Vermutlich nur, um ihre Schwester Kourtney und deren Kinder zu sehen.",
		"tgt": "And, in her downtime, possibly just as a way still to see sister Kourtney and her kids, she's on reality television."
	},
	{
		"src": "Gemeinderechtszentren weisen j\u00e4hrlich 160.000 Leute ab",
		"tgt": "Community legal centres turn away 160,000 people a year"
	},
	{
		"src": "Mehr als 160.000 der Hilfsbed\u00fcrfigsten des Landes werden j\u00e4hrlich von den Gemeinderechtszentren abgewiesen, w\u00e4hrend sich die Branche auf die Auswirkungen weiterer Mittelk\u00fcrzungen auf bereits \u00fcberlastete Transaktionen gefasst macht.",
		"tgt": "More than 160,000 of the nation's most vulnerable are turned away from community legal centres every year, with the sector bracing itself for the impact further funding cuts will have on already-stretched operations."
	},
	{
		"src": "In Queensland werden bereits drei von f\u00fcnf Personen - meistens \u00e4ltere Personen, Immigranten, hilfsbed\u00fcrftige Arbeiter, Opfer von Gewalttaten und diejenigen, die \u00fcber keine Mittel f\u00fcr ungerechte Delogierungen und \u00e4hnliches verf\u00fcgen - bei ihrem Ansuchen auf kostenlose Rechtsberatung und Rechtsbeistand abgewiesen.",
		"tgt": "In Queensland, three out of five people - mostly the elderly, immigrants, vulnerable workers, victims of violence and those without resources to fight unfair evictions and the like - are already turned away while seeking free legal advice and representation."
	},
	{
		"src": "Juristische Dienstleistungen der Gemeinde, die bereits \u00fcberm\u00e4\u00dfig ausgelastet sind, machen sich f\u00fcr weitere K\u00fcrzungen bereit.",
		"tgt": "Community legal services, already stretched beyond limits, are bracing for further cuts."
	},
	{
		"src": "Ab Juni n\u00e4chsten Jahres ist vorgesehen, dass diese Rechtszentren weitere 30 Prozent ihrer Bundesmittel verlieren werden.",
		"tgt": "From June next year, those legal centres are slated to lose another 30 per cent of their federal funding."
	},
	{
		"src": "Der Direktor der Gemeindrechtszentren von Queesland James Farrell sagte, dass die letzte Erhebung der Nationalen Vereinigung von Gemeinderechtszentren ergab, dass bereits tausende von Leuten jedes Jahr abgewiesen werden.",
		"tgt": "Director of Community Legal Centres Queensland James Farrell said the latest National Association of Community Legal Centres Census Report found thousands of people were already being turned away each year."
	},
	{
		"src": "Farrell sagte, dass die Situation ohne eine Aufhebung des Beschlusses der Bundesregierung nur noch schlimmer werden w\u00fcrde.",
		"tgt": "Mr Farrell said without a reversal of the federal government decision, the situation was only going to get worse."
	},
	{
		"src": "\"Queenslands Gemeinderechtszentren sind chronisch unterfinanziert, was bedeutet, dass tausende von Leuten von wichtigen Diensten, die Sie ben\u00f6tigen, abgewiesen werden,\" sagte er.",
		"tgt": "\"Queensland's community legal centres are chronically underfunded, meaning thousands of people are turned away from the vital services they need,\" he said."
	},
	{
		"src": "Leute, die gewaltt\u00e4tige Beziehungen verlassen, Leute mit un\u00fcberschaubaren und erdr\u00fcckenden Schulden, Familien, die durch Trennungen gehen, Arbeiter, die ungerechterweise entlassen wurden - all diese Leute haben Probleme rechtlicher Art und diese Erhebung zeigt, dass sie nicht die Hilfe erhalten k\u00f6nnen, die sie ben\u00f6tigen.",
		"tgt": "People leaving violent relationships, people with unmanageable and crippling debts, families going through separation, workers who are unfairly sacked - all of these people have problems with legal dimensions, and this report shows that they're not able to get the help they need."
	},
	{
		"src": "Die Bundesregierung wird ab Juni 2017 die Mittel um 30 Prozent k\u00fcrzen, was bedeutet, dass tausende von hilsbed\u00fcrftigeren Leuten aus Queensland gezwungen sein werden, mit ihren rechtlichen Problemen ohne jegliche Hilfe zurechtzukommen.",
		"tgt": "The federal government will cut funding by 30 per cent from June 2017, which means thousands more vulnerable Queenslanders will be forced to navigate complex legal problems without help."
	},
	{
		"src": "Wir fordern den Generalbundesanwalt und Bundesjustizminister sowie Senatoren von Queensland George Brandis dazu auf, diese Mittelk\u00fcrzungen umgehend aufzuheben, sodass die Leute die Hilfe, die sie ben\u00f6tigen, bei rechtlichen Problemen erhalten k\u00f6nnen.",
		"tgt": "We call on the Attorney-General, and Queensland Senator George Brandis to immediately reverse these funding cuts, so people can get the help they need when they're faced with a legal problem."
	},
	{
		"src": "Letztes Jahr erf\u00fcllte die Landesregierung ihre Zusage, Mittel f\u00fcr Rechtshilfen auf den nationalen Durchschnitt anzuheben.",
		"tgt": "Last year, the state government delivered on its commitment to bring legal aid funding up to the national average."
	},
	{
		"src": "Es ist jetzt an der Zeit, sich die Bed\u00fcrfnisse der Gemeinderechtszentren und ihrer Kundengemeinden anzusehen sowie, dass die Regierung Palaszczuk in diese wichtige Arbeit investiert.",
		"tgt": "It's now time to look at the needs of community legal centres and their client communities, and for the Palaszczuk government to invest in this important work."
	},
	{
		"src": "Donald Trump Wahlkampagne angeklagt nachdem Mitarbeiter angeblich Waffe zog",
		"tgt": "Donald Trump campaign sued after staffer allegedly pulled a gun"
	},
	{
		"src": "New York: Donald Trumps Kampagne ist wegen angeblicher Unt\u00e4tigkeit angeklagt worden, nachdem ihr mitgeteilt wurde, dass ihr Kampagnenleiter f\u00fcr North Carolina im Februar eine Schusswaffe auf einen Mitarbeiter gerichtet habe, w\u00e4hrend sie im Februar in einem Jeep unterwegs waren.",
		"tgt": "New York: Donald Trump's campaign was sued for allegedly doing nothing after being told that the director of its North Carolina operations pulled a gun on a staffer as they drove in a Jeep in February."
	},
	{
		"src": "Der Vorfall wird in einer Anklageschrift beschrieben, der am Mittwoch im Landesgericht von Charlotte durch Vincent Bordini eingereicht wurde, einen ehemaligen Softwareprogrammierer f\u00fcr die Kampagne in diesem Bundesstaat.",
		"tgt": "The incident was described in a lawsuit filed on Wednesday in state court in Charlotte by Vincent Bordini, a former software trainer for the state campaign."
	},
	{
		"src": "Bordini gab an, monatelang gewartet zu haben, dass die Angelegenheit intern geregelt werden w\u00fcrde, bevor er realisierte, dass \" das nicht geschehen w\u00fcrde.\"",
		"tgt": "Bordini said he waited for months for the situation to be handled internally before realising \"this was not going to happen.\""
	},
	{
		"src": "Der Kampagnenleiter, Earl Philip, \" zog eine Pistole, legte seinen rechten Zeigefinger auf den Abzug, und rammte den Lauf in Vincents Kniekehle,\" gab Bordini in seiner Anklage an.",
		"tgt": "The director, Earl Phillip, \"produced a pistol, put his right index finger on the trigger, and drove the barrel into Vincent's knee cap,\" Bordini said in the complaint."
	},
	{
		"src": "Nachdem er sich bei der \u00f6rtlichen und regionalen Kampagnenleitung beschwert hatte, stellte Bordini fest, dass bereits mindestens vier weitere Personen dieselbe Erfahrung mit Phillip gemacht hatten, gab er in der Anklageschrift an.",
		"tgt": "After complaining to local and regional campaign leadership, Bordini learned that at least four other people had experience the same thing with Phillip, according to the filing."
	},
	{
		"src": "\"Waffen m\u00fcssen nicht abgefeuert werden, um Schaden anzurichten,\" gab Bordini an.",
		"tgt": "\"Guns don't have to fire to inflict damage,\" Bordini said in the complaint."
	},
	{
		"src": "Die Anklage kommt nur zwei Tage nachdem der republikanische Pr\u00e4sidentschaftskandidat einen Aufruhr ausl\u00f6ste, als er einer Menschenmenge in North Carolina sagte, dass die \"Second Amendment Leute\" - Schusswaffenbesitzer und Waffenfreunde - Ma\u00dfnahmen ergreifen sollten, falls seine Rivalin Hillary Clinton gew\u00e4hlt werden und Richter ernennen sollte.",
		"tgt": "The suit comes just two days after the Republican presidential nominee caused a furore when telling a crowd in North Carolina that the \"Second Amendment people\" -- understood to be gun owners and gun enthusiasts -- could take action if his rival Hillary Clinton were elected and gets her pick of judges."
	},
	{
		"src": "Trumps Kampagne stellte klar, dass die Medien seine Worte aus dem Kontext gerissen h\u00e4tten und dass er nicht zur Gewalt anstacheln w\u00fcrde.",
		"tgt": "Trump's campaign said the media had taken his words out of context and that he wasn't advocating violence."
	},
	{
		"src": "Bordinis Beschwerde verlangt Schadensersatz von der Kampagne f\u00fcr die Verletzung der Sorgfaltspflicht und von Philip wegen K\u00f6rperverletzung und bleibender seelischer Sch\u00e4den.",
		"tgt": "Bordini's complaint seeks compensation from the campaign for negligent supervision, and from Phillip for assault, battery and infliction of emotional distress."
	},
	{
		"src": "Trumps Pressesprecherin Hope Hicks war f\u00fcr eine Stellungnahme nicht zu erreichen.",
		"tgt": "Trump spokeswoman Hope Hicks didn't immediately return a message seeking comment."
	},
	{
		"src": "Versuche, Philip zu kontaktieren schlugen ebenso fehl.",
		"tgt": "Attempts to reach Phillip were unsuccessful."
	},
	{
		"src": "WCCB, ein lokaler Nachrichtensender in Charlotte, meldet, dass Phillip nicht l\u00e4nger Mitarbeiter der Kampagne ist.",
		"tgt": "WCCB, a local news affiliate in Charlotte, reported Phillip recently left the campaign."
	},
	{
		"src": "Auf Anrufe bei seinem Beratungsunternehmen, Innovative Consulting Services, wurde nicht reagiert.",
		"tgt": "A call left at his consulting firm, Innovative Consulting Services, wasn't immediately returned."
	},
	{
		"src": "Der republikanische Pr\u00e4sidentschaftskandidat Donald Trump hat bisher eine kontroverse Kampagne gef\u00fchrt.",
		"tgt": "Republican presidential candidate Donald Trump has run a controversial campaign."
	},
	{
		"src": "Das Verfahren lautet Bordini v. Donald J. Trump For President Inc., 16-CS-14300, Oberstes Gericht, County of Mecklenburg (Charlotte).",
		"tgt": "The case is Bordini v. Donald J. Trump For President Inc., 16-CS-14300, General Court of Justice, Superior Court Division County of Mecklenburg (Charlotte)."
	},
	{
		"src": "Berlin/Schwerin: Umfrage vor L\u00e4nder-Wahlen: SPD und CDU verlieren",
		"tgt": "Berlin/Schwerin: Poll ahead of regional elections: SPD and CDU lose out"
	},
	{
		"src": "Bei den anstehenden Wahlen in den Bundesl\u00e4ndern Mecklenburg-Vorpommern (4. September) und Berlin (18. September) zeichnen sich erhebliche Verluste f\u00fcr die Regierungsparteien SPD und CDU ab.",
		"tgt": "Ahead of the elections in the federal states of Mecklenburg-Vorpommern (4 September) and Berlin (18 September), considerable losses are looming for the governing parties of the SPD and the CDU."
	},
	{
		"src": "Dies ergaben repr\u00e4sentative Umfragen des Meinungsforschungsinstituts INSA f\u00fcr die \"Bild\"-Zeitung (Freitag).",
		"tgt": "These are the findings of a representative poll carried out by INSA, a polling institute, on behalf of \"Bild\" newspaper."
	},
	{
		"src": "W\u00e4hrend die rot-schwarze Regierungskoalition im Norden knapp weiter regieren k\u00f6nnte, ist dies nach den Umfragewerten in Berlin nicht m\u00f6glich.",
		"tgt": "While the red-black ruling coalition in the north might just be able to continue in office, this will not be possible in Berlin, according to the poll."
	},
	{
		"src": "In beiden Bundesl\u00e4ndern w\u00e4re die SPD aber die st\u00e4rkste Partei und h\u00e4tte damit gute Chancen, weiterhin den Regierungschef zu stellen.",
		"tgt": "However, the SPD was the strongest party in both states, with good chances of putting forward the head of the government."
	},
	{
		"src": "In Mecklenburg-Vorpommern st\u00fcrzte die SPD von 35,6 Prozent vor f\u00fcnf Jahren auf 24 Prozent ab.",
		"tgt": "In Mecklenburg-Vorpommern, the SPD plummeted from 35.6 percent to 24 percent in five years."
	},
	{
		"src": "Die Partei l\u00e4ge damit laut Umfrage nur noch knapp vor der CDU, die wieder auf 23 Prozent kommen k\u00f6nnte.",
		"tgt": "According to the poll, this puts the party only slightly above the CDU, who had 23 percent."
	},
	{
		"src": "Der dritte Platz ist zwischen der Linken und der AfD umstritten.",
		"tgt": "The Left and the AfD will fight over third place."
	},
	{
		"src": "Die Linke k\u00e4me auf 19 Prozent (zuvor 18,4 Prozent), die AfD w\u00e4re mit 19 Prozent erstmals im Landtag vertreten.",
		"tgt": "The Left had 19 percent (previously 18.4 percent), and, with 19 percent, the AfD could be in the regional parliament for the first time."
	},
	{
		"src": "Die Gr\u00fcnen z\u00f6gen trotz leichter Verluste mit 6 Prozent (zuvor 8,7 Prozent) wieder in den Schweriner Landtag ein.",
		"tgt": "Despite small losses (from 8.7 percent to 6 percent), the Greens will return to Schwerin's regional parliament."
	},
	{
		"src": "NPD und FDP w\u00e4ren mit jeweils 3 Prozent nicht im Landtag vertreten.",
		"tgt": "The NPD and the FPD, with 3 percent each, will not be represented in the regional parliament."
	},
	{
		"src": "Bei der Berliner Abgeordnetenhauswahl k\u00e4me die SPD der Umfrage zufolge nur noch auf 23 Prozent (Wahl 2011: 28,3 Prozent).",
		"tgt": "According to the poll, the SPD would only receive 23 percent in Berlin's elections to the House of Representatives (2011 elections: 28.3 percent)."
	},
	{
		"src": "Die CDU erreichte nur noch 18 Prozent nach 23,4 Prozent.",
		"tgt": "The CDU would only take 18 percent, after having taken 23.4 percent."
	},
	{
		"src": "Sie l\u00e4ge damit noch hinter den Gr\u00fcnen mit 19 Prozent (2011: 17,6 Prozent), aber vor den Linken mit 15 Prozent (vorher 11,7 Prozent).",
		"tgt": "This would put them behind the Greens with 19 percent (2011: 17.6 percent), but ahead of the Left, with 15 percent (previously 11.7 percent)."
	},
	{
		"src": "Die AfD w\u00e4re mit 14 Prozent erstmals im Abgeordnetenhaus vertreten.",
		"tgt": "The AfD would be represented in the House for the first time, with 14 percent."
	},
	{
		"src": "Mit 5 Prozent k\u00f6nnte die FDP auf eine R\u00fcckkehr hoffen, die Piraten w\u00fcrden dagegen im Gegensatz zu 2011 den Einzug verpassen.",
		"tgt": "With 5 percent, the FPD could hope to return, but the Pirates, by contrast, would miss out - unlike in 2011."
	},
	{
		"src": "Nokia 9000 Communicator: Das erste Smartphone",
		"tgt": "Nokia 9000 Communicator: The first smartphone"
	},
	{
		"src": "E-Mail und Internet in Zeitlupe: Vor 20 Jahren kam der Nokia Communicator auf den Markt.",
		"tgt": "Email and the Internet in slow motion: The Nokia Communicator was brought to market 20 years ago."
	},
	{
		"src": "Die Nachfolger dominieren heute die Welt - sein Hersteller erlebte ein Desaster.",
		"tgt": "Its successors have now conquered the world - but its manufacturer is in the midst of a disaster."
	},
	{
		"src": "Das Ger\u00e4t wog fast ein halbes Kilogramm und war mehr als viermal so schwer wie ein iPhone 5.",
		"tgt": "The device weighed almost half a kilogram, and was more than four times as heavy as an iPhone 5."
	},
	{
		"src": "Es war dicker und gr\u00f6\u00dfer, es lag deshalb auch nicht gut in der Hand.",
		"tgt": "It was thicker and larger, and harder to hold."
	},
	{
		"src": "Im Gegenteil, es war ziemlich klobig.",
		"tgt": "Indeed, it was quite bulky."
	},
	{
		"src": "Der eingebaute Speicher betrug anfangs acht Megabyte, das w\u00fcrde heute f\u00fcr ungef\u00e4hr zwei Selfies mit hoher Aufl\u00f6sung reichen.",
		"tgt": "The in-built storage originally held eight megabytes - enough today for around two high-resolution selfies."
	},
	{
		"src": "Ein iPhone wird mittlerweile mit mindestens 16 Gigabyte ausgeliefert.",
		"tgt": "Now, an iPhone holds at least 16 gigabytes."
	},
	{
		"src": "Der \"Nokia 9000 Communicator\" kam vor genau 20 Jahren, am 15. August 1996, in die Gesch\u00e4fte - und es war das erste Smartphone.",
		"tgt": "The \"Nokia 9000 Communicator\" was released for sale exactly 20 years ago, on 15 August 1996 - and it was the first smartphone."
	},
	{
		"src": "F\u00fcr ein paar Euro k\u00f6nnen Liebhaber die Ger\u00e4te noch im Internet kaufen, doch sie stammen irgendwie aus der Steinzeit des Internetzeitalters.",
		"tgt": "The device is still available online for fans to buy for a couple of euros, even though it comes from the stone age of the Internet."
	},
	{
		"src": "Vor 20 Jahren jedoch war der Communicator eine Sensation.",
		"tgt": "However, 20 years ago, the Communicator sparked a sensation."
	},
	{
		"src": "Der finnische Mobiltelefon-Hersteller hatte das Produkt ein paar Monate zuvor auf der Computermesse Cebit in Hannover als \"B\u00fcro im Westentaschenformat\" angek\u00fcndigt.",
		"tgt": "The Finnish mobile phone manufacturer had presented the product a couple of months previously at the Cebit computer trade fair in Hanover, billing it as \"the office you can fit in your pocket\"."
	},
	{
		"src": "In der Tat, das neue Mobiltelefon konnte f\u00fcr damalige Standards eine Menge: SMS und E-Mails konnten gesendet und empfangen werden, auch per Fax war der Communicator zu erreichen.",
		"tgt": "The new mobile phone could really do a lot by standards back then: it could send and receive SMS messages and emails, and could even be contacted by fax."
	},
	{
		"src": "Sogar der Zugriff auf Webseiten war per HTML-Browser m\u00f6glich, wenn auch qu\u00e4lend langsam.",
		"tgt": "You could even access websites via a HTML browser, even though it was painfully slow."
	},
	{
		"src": "Ein Taschenrechner war verf\u00fcgbar, ein digitales Adressbuch und ein elektronischer Kalender.",
		"tgt": "There was a calculator, a digital address book and an electronic calendar."
	},
	{
		"src": "Es gab eine kleine Antenne, und das Handy konnte \u00e4hnlich wie ein Laptop aufgeklappt werden.",
		"tgt": "There was a small antenna, and the phone could be folded open like a laptop."
	},
	{
		"src": "Dann fanden sich eine kleine Tastatur und ein Schwarz-Wei\u00df-Bildschirm.",
		"tgt": "This revealed a small keyboard and a black and white screen."
	},
	{
		"src": "Ziemlich stolz war der Preis: 2700 D-Mark, also etwa 1400 Euro.",
		"tgt": "The price was fairly high: 2700 deutschmarks, around 1400 euros."
	},
	{
		"src": "Der durchschnittliche Verkaufspreis eines Smartphones in Deutschland lag 2015 bei 392 Euro.",
		"tgt": "In 2015, the average sale price of a smartphone in Germany was 392 euros."
	},
	{
		"src": "Niemand konnte im August 1996 ahnen, dass der Communicator der Beginn der Smartphone-\u00c4ra werden w\u00fcrde.",
		"tgt": "In August 1996, nobody had any idea that the Communicator heralded the start of the smartphone era."
	},
	{
		"src": "Seitdem ist alles anders.",
		"tgt": "Today, everything has changed."
	},
	{
		"src": "Die klugen Telefone sind eine Erfolgsgeschichte, wenn auch nicht f\u00fcr Nokia.",
		"tgt": "Smartphones are a success story - even if the same cannot be said for Nokia."
	},
	{
		"src": "Die Handy-Sparte der Finnen erlebte ein beispielloses Desaster, wurde schlie\u00dflich an Microsoft verkauft und abgewickelt.",
		"tgt": "The mobile phone branch of the Finnish company experienced an unprecedented disaster, and was eventually sold to Microsoft and wound up."
	},
	{
		"src": "Den Markt beherrschen heute Anbieter, die alle viel sp\u00e4ter kamen als Nokia.",
		"tgt": "Today the market is dominated by providers who came to the game much later than Nokia."
	},
	{
		"src": "Immer und \u00fcberall online sein, das ist heute f\u00fcr sehr viele Menschen Alltag.",
		"tgt": "For many people today, being online all day, no matter where you are, is simply a fact of life."
	},
	{
		"src": "2015 gab es weltweit nahezu zwei Milliarden Smartphone-Nutzer.",
		"tgt": "In 2015, there were around two billion smartphone users around the world."
	},
	{
		"src": "Verkauft wurden etwa 1,4 Milliarden Ger\u00e4te, auf Samsung und Apple entfallen davon alleine 555 Millionen St\u00fcck.",
		"tgt": "Around 1.4 billion devices were sold, and Samsung and Apple alone make up 555 million of them."
	},
	{
		"src": "Der weltweite Umsatz mit den Ger\u00e4ten liegt bei rund 400 Milliarden Euro.",
		"tgt": "Global sales of the devices amount to around 400 billion euros."
	},
	{
		"src": "Dazu kommen die gut laufenden Gesch\u00e4fte der zahllosen App-Anbieter und der Telekommunikationskonzerne.",
		"tgt": "This is in addition to the flourishing businesses of innumerable app providers and telecommunications firms."
	},
	{
		"src": "Rund um das Smartphone ist inzwischen eine ganze Industrie entstanden.",
		"tgt": "An entire industry has now sprung up around smartphones."
	},
	{
		"src": "Der entscheidende Durchbruch zum Massenmarkt kam erst Anfang 2007, damals k\u00fcndigte Apple-Chef Steve Jobs auf der Mac-World die Einf\u00fchrung des iPhones an.",
		"tgt": "The decisive moment when the mass market was broken into was only at the start of 2007, when the Apple CEO at the time, Steve Jobs, announced the introduction of the iPhone at Mac World."
	},
	{
		"src": "Er versprach drei Ger\u00e4te in einem: ein Musikspieler, ein Telefon und einen Internet-Kommunikator, alles per Touch-Bildschirm leicht zu bedienen.",
		"tgt": "He promised three devices in one: a music player, a telephone and an internet communicator - and everything could be accessed easily via touchscreen."
	},
	{
		"src": "Der Siegeszug von Apple begann, noch heute ist das iPhone das wichtigste Produkt des Konzerns.",
		"tgt": "Apple's triumphant march began, and the iPhone is still the company's most important product today."
	},
	{
		"src": "Nokia, Motorola und Blackberry, die den Markt beherrschten, hatten das Nachsehen.",
		"tgt": "Nokia, Motorola and Blackberry, who used to dominate the market, lost out."
	},
	{
		"src": "Sie verschwanden schlie\u00dflich, Blackberry hat zu k\u00e4mpfen.",
		"tgt": "They eventually disappeared, and Blackberry had to fight for its existence."
	},
	{
		"src": "Das Sagen haben nun Apple und asiatische Anbieter wie Samsung.",
		"tgt": "Apple, and Asian providers such as Samsung, now hold sway."
	},
	{
		"src": "Das Smartphone ist 20 Jahre nach seiner Erfindung eine Selbstverst\u00e4ndlichkeit.",
		"tgt": "20 years after their invention, smartphones are a fact of life."
	},
	{
		"src": "Im Schnitt schaut heute jeder Deutsche inzwischen 88 Mal am Tag auf sein Handy.",
		"tgt": "Nowadays, every German looks at their phone an average of 88 times a day."
	},
	{
		"src": "\"Wir m\u00fcssen alle lernen, das Smartphone auch mal wegzulegen\", sagte gerade Janina Kugel, im Siemens-Vorstand f\u00fcr Personal zust\u00e4ndig.",
		"tgt": "\"We all need to learn to put our phones down from time to time,\" said Janina Kugel, Siemens HR Director."
	},
	{
		"src": "Permanente Erreichbarkeit gilt mittlerweile als Fluch und Segen zugleich.",
		"tgt": "Being permanently contactable has become a blessing and a curse."
	},
	{
		"src": "England muss den olympischen Geist lenken und Heathrow erweitern",
		"tgt": "Britain must channel the Olympic spirit and expand Heathrow"
	},
	{
		"src": "Heathrow wird nicht nur in unseren \u00f6rtlichen Kommunen und in ganz London, sondern im ganzen Land Erneuerung und Wohlstand bringen.",
		"tgt": "Heathrow will also deliver regeneration and prosperity not just in our local communities and across London, but across the country."
	},
	{
		"src": "F\u00fcr mich stellte das die gr\u00f6\u00dfte Attraktion Heathrows dar, genauso wie damals in 2012 in London, als wir einen gro\u00dfen Aufwand betrieben, um sicherzustellen, dass all unsere Nationen und Regionen von den Spielen profitierten.",
		"tgt": "For me, this was the great attraction of Heathrow, just as it was with London 2012, where we made enormous efforts to ensure that all our nations and regions benefited from the Games."
	},
	{
		"src": "Die Olympiade brachte gro\u00dfe Vorteile f\u00fcr Stratford und das East End.",
		"tgt": "The Olympics achieved huge benefits for Stratford and the East End."
	},
	{
		"src": "Und das werden wieder erreichen, indem wir f\u00fcr Ortsans\u00e4ssige und Firmen in der N\u00e4he von Heathrow neue M\u00f6glichkeiten schaffen.",
		"tgt": "And, we will do so again by creating opportunities for local people and firms close to Heathrow."
	},
	{
		"src": "F\u00fcr unsere \u00f6rtlichen Gemeinden werden wir alleine bereits 10.000 neue Lehrstellen, 40.000 neue Arbeitspl\u00e4tze schaffen und der Jugendarbeitslosigkeit in der Flughafenumgebung ein Ende bereiten.",
		"tgt": "For our local communities alone we'll create 10,000 new apprenticeships, 40,000 new jobs and bring an end to youth unemployment around the airport."
	},
	{
		"src": "So wie sie uns in London 2012 voraus waren, wird es solche geben, die denken werden, dass die Herausforderung der Erweiterung Heathrows zu gro\u00df ist.",
		"tgt": "Just as there were ahead of London 2012, there will be those that think the challenge of Heathrow expansion is too great."
	},
	{
		"src": "Mir wurde gesagt, dass England nie f\u00fcr die Spiele bereit sein wird und, dass wir uns auf der Weltb\u00fchne blamieren werden.",
		"tgt": "I was told that Britain would be never be ready for the Games and that we would be embarrassed on the world stage."
	},
	{
		"src": "Die Zweifler hatten 2012 Unrecht und sie werden auch bei Heathrow falsch liegen.",
		"tgt": "The doubters were wrong on 2012 and they will be proved wrong on Heathrow."
	},
	{
		"src": "Es gibt immer Hindernisse zum \u00dcberwinden, aber Heathrow beantwortet jede ihm gestellte Frage.",
		"tgt": "There are always obstacles to be overcome, but Heathrow is answering every question asked of it."
	},
	{
		"src": "Wie die Olympischen Spiele ist Heathrow f\u00fcr viele und nicht f\u00fcr einzelne ein Infrastrukturprojekt.",
		"tgt": "Like the Olympics, Heathrow is an infrastructure project for the many, not just the few."
	},
	{
		"src": "Erweiterung ist eine M\u00f6glichkeit, um bis zu 180.000 neue Arbeitspl\u00e4tze, \u00a3211 Mrd. an witschaftlichem Wachstum zu schaffen und ein Verm\u00e4chtnis von F\u00e4higkeiten und Besch\u00e4ftigung sowohl um den Flughafen als auch in ganz GB zu hinterlassen.",
		"tgt": "Expansion is an opportunity to create up to 180,000 new jobs, \u00a3211bn in economic growth, leaving a legacy of skills and employment both around the airport and across the UK."
	},
	{
		"src": "Wir haben ein tolles Team in Heathrow, das ein \u00a311 Mrd. teures Infrastrukturinvestitionsprogramm in Zeit und Budget umgesetzt hat, vom T5 - das f\u00fcnf Jahre in Folge zum weltbesten Flughafenterminal gew\u00e4hlt wurde, bis zum T2, das inmitten der zwei frequentiertesten Laufstege der Welt gebaut wurde.",
		"tgt": "We have a great team at Heathrow who have implemented an \u00a311bn programme of infrastructure investment on time and on budget, from T5 - voted the world's best airport terminal five years in a row, to T2, built in the middle of the world's busiest two runways."
	},
	{
		"src": "Jetzt stehen sie bereit einen dritten Laufsteg zu liefern, was durch \u00a316 Milliarden an privaten Investitionen unterst\u00fctzt wird.",
		"tgt": "Now they stand ready to deliver a third runway, backed by \u00a316 billion of private investment."
	},
	{
		"src": "Die Londoner Spiele von 2012 waren ein gro\u00dfer Erfolg f\u00fcr GB und ich bin zuversichtlich, dass die Erweiterung von Heathrow ebenfalls einer sein wird.",
		"tgt": "The London 2012 Games were a great success for the UK and I am confident that Heathrow expansion will be too."
	},
	{
		"src": "Es ist Zeit, dass wir diesen olympischen Geist lenken und Heathrow erweitern sowie dabei unseren k\u00fcnftigen Handel sichern und ein Verm\u00e4chtnis von Fertigkeiten und Besch\u00e4ftigung erschaffen, auf das England stolz sein kann.",
		"tgt": "It is time for us to channel that Olympic spirit and expand Heathrow, securing our trading future and creating a legacy of skills and employment that Britain can be proud of."
	},
	{
		"src": "Lord Paul Deighton ist Vorsitzender des Heathrow Boards und ehemaliger Commercial Secretary to the Treasury",
		"tgt": "Lord Paul Deighton is chairman of the Heathrow Board and former Commercial Secretary to the Treasury"
	},
	{
		"src": "Adblock Plus, Facebook im \"Katz-und Mausspiel\" bez\u00fcglich Anzeigenblockierung",
		"tgt": "Adblock Plus, Facebook in \"cat-and-mouse game\" over ad blocking"
	},
	{
		"src": "F\u00fcr Unternehmen, die mit Onlinewerbung Geld verdienen kommen laut einem der Softwarehersteller Versuche, Anzeigenblockierung zu umgehen, einem \"Katz- und Mausspiel\" gleich.",
		"tgt": "For companies that make money from online advertising, attempts to circumvent ad-blocking software amount to a \"cat-and-mouse game,\" according to one of the companies that makes that software."
	},
	{
		"src": "Am Donnerstag, nur zwei Tage nachdem Facebook ank\u00fcndigte, dass es Anzeigeblockierungen auf seiner Desktopseite blockieren w\u00fcrde, ver\u00f6ffentlichte Adblock Plus einen Blogpost, in dem es mitteilte, dass Anwender ihre Filter im Programm aktualisieren k\u00f6nnten, um erneut Werbung im sozialen Netzwerk zu blockieren.",
		"tgt": "On Thursday, just two days after Facebook announced it would be blocking ad blockers on its desktop site, Adblock Plus published a blog post saying that users could update their filters in its program to block ads on the social network once again."
	},
	{
		"src": "Am Dienstag teilte Facebook mit, dass seine Desktopseite die Codierung bez\u00fcglich seiner Werbeanzeigen \u00e4ndern w\u00fcrde, um es Anzeigeblockierungen die Erkennung dar\u00fcber, welcher Teil der Seite Werbung ist, zu erschweren zu erkennen.",
		"tgt": "On Tuesday, Facebook said that its desktop website would change the coding around its ads in order to make it more difficult for ad blockers to detect which parts of a page are ads."
	},
	{
		"src": "Aber Adblock verk\u00fcndete, dass es einen neuen Weg gefunden hat, die neuen Codes zu umgehen.",
		"tgt": "But Adblock now says it has gotten around the new codes."
	},
	{
		"src": "In einem Blogpost schrieb der Sprecher von Adblock Ben Williams, dass \"diese Art Hin-und-Her-Kampf zwischen der anzeigeblockierenden Open Source Community und den Umgehern bereits seit der Erfindung von Anzeigeblockierern im Gange ist,\" und, dass es m\u00f6glich ist, dass Facebook bald mit einer neuen L\u00f6sung kommt.",
		"tgt": "In a blog post, Adblock spokesperson Ben Williams wrote that \"this sort of back-and-forth battle between the open source ad-blocking community and circumventers has been going on since ad blocking was invented,\" and that it is possible Facebook would come up with its own fix soon."
	},
	{
		"src": "Die Tatsache, dass sich das weltgr\u00f6\u00dfte Unternehmen f\u00fcr soziale Medien in den Kampf eingelassen hat, ist ein starkes Indiz daf\u00fcr, wie besorgniserregend Anzeigeblockierer f\u00fcr die Branche geworden sind.",
		"tgt": "The fact that the world's largest social media company has entered the fight is a strong indication of just how big a concern ad blockers have become for the industry."
	},
	{
		"src": "Weltweit verwenden laut einer Studie vom letzten Jahr von Pagefair und Adobe rund 200 Millionen Leute Anzeigeblockierer; fast viermal so viel 2013.",
		"tgt": "Globally, roughly 200 million people use ad blockers, according to a study last year from Pagefair and Adobe; nearly quadruple the number who used such software in 2013."
	},
	{
		"src": "Mit 1,03 Milliarden t\u00e4glich aktiven Anwendern, die auf Facebook \u00fcber ihre mobilen Endger\u00e4te zugreifen, macht Handywerbung 84 Prozent der Werbeeinnahmen Facebooks aus.",
		"tgt": "With 1.03 billion daily active users accessing Facebook via mobile devices, mobile advertising now accounts for 84 per cent of Facebook's advertising revenue."
	},
	{
		"src": "Das Unternehmen hat es auf Anzeigenblockierer auf Desktop PCs abgesehen, da mobile Anzeigenblockierer keine Wirkung auf Facebooks mobiler App f\u00fcr das soziale Netzwerk und Instagram haben, teilte ein Sprecher mit.",
		"tgt": "The company is going after ad blockers on desktop however, because mobile ad blockers are not effective in Facebook's mobile apps for the social network and Instagram, a spokesperson said."
	},
	{
		"src": "Werbung auf Desktop PCs macht einen gen\u00fcgend gro\u00dfen Anteil der Einnahmen aus, sodass Facebook die Investition eines solchen Schrittes als lohnenswert erscheint.",
		"tgt": "Desktop ads still account for enough revenue that Facebook judged such a move to be worth the investment."
	},
	{
		"src": "Am Dienstag teilte Facebook mit, dass es sein \"Anzeigenpr\u00e4ferenzentool\" aktualisieren w\u00fcrde, um den Leuten mehr Kontrolle \u00fcber auf sie abgezielte Werbung zu haben.",
		"tgt": "Also on Tuesday, Facebook said it would be updating its \"ad preferences\" tool to give people more control over how ads are targeted to them."
	},
	{
		"src": "Am Donnerstag behauptete Facebook, dass Adblocks neue Filter besorgniserregend w\u00e4ren, weil sie auch Inhalte auf der Seite blockieren w\u00fcrden, die keine Werbung sind.",
		"tgt": "On Thursday Facebook claimed that Adblock's new filters were concerning because they would also block some non-advertising content on the site."
	},
	{
		"src": "\"F\u00fcr die Nutzer stellt das keine positive Erfahrung dar, daher planen wir, das Problem anzusprechen,\" teilte ein Sprecher von Facebook in einer E-Mail-Mitteilung mit.",
		"tgt": "\"This isn't a good experience for people and we plan to address the issue,\" a Facebook spokesperson said in an e-mailed statement."
	},
	{
		"src": "Anzeigenblockierer sind ein stumpfes Mittel, weshalb wir uns stattdessen auf Entwicklertools wie Ad Preferences konzentriert haben, um mehr Kontrolle in die H\u00e4nde der Leute zu legen.",
		"tgt": "Ad blockers are a blunt instrument, which is why we've instead focused on building tools like Ad Preferences to put control in people's hands."
	},
	{
		"src": "Frau bei vermutlichem Selbstmord auf Schweizer Autobahn \u00fcberfahren",
		"tgt": "Woman run over on Swiss motorway in apparent suicide"
	},
	{
		"src": "Das Opfer lag mitten in der Nacht auf der Autobahn.",
		"tgt": "The victim was lying on the motorway in the middle of the night."
	},
	{
		"src": "Die Polizei ruft Zeugen auf, nachdem eine Frau in den fr\u00fchen Morgenstunden am Donnerstag bei einem vermutlichen Selbstmord von mehreren Fahrzeugen auf einer Autobahn \u00fcberfahren wurde.",
		"tgt": "Police are appealing for witnesses after a woman was run over by several vehicles on a motorway in the early hours of Thursday in an apparent act of suicide."
	},
	{
		"src": "Der Vorfall ereignete sich auf der A1 in der N\u00e4he von Morges im Kanton Waadt kurz nach Mitternacht.",
		"tgt": "The incident happened on the A1 near Morges in the canton of Vaud just after midnight on Thursday."
	},
	{
		"src": "Eine Frau legte sich im Dunklen \"in einem Akt der Verzweiflung\" auf die Stra\u00dfe und wurden von mehreren Autos getroffen, sagte die Polizei in Waadt aus.",
		"tgt": "A woman lay down in the dark on the road \"in a desperate act\" and was hit by several vehicles, Vaud police said in a statement."
	},
	{
		"src": "Es ist offensichtlich, dass sich eine Schweizerin im Alter von 49 Jahren, die von mehreren Fahrzeugen, einschlie\u00dflich eines Lastwagens, \u00fcberfahren wurde, selbst t\u00f6ten wollte.",
		"tgt": "Clearly looking to kill herself, the victim, a Swiss woman aged 49, was hit by several vehicles including a lorry."
	},
	{
		"src": "Sie verstarb noch vor Ort.",
		"tgt": "She died at the scene."
	},
	{
		"src": "Mehrere Fahrer wurden bereits vernommen, doch einige sind noch immer nicht identifiziert worden, sagte die Polizei, die diese sowie jeden Zeugen des Vorfalls dazu auffordert, sich zu melden.",
		"tgt": "Several of the drivers involved have already been interviewed but some are still unidentified, said police, who are calling for them and anyone else who witnessed the incident to come forward."
	},
	{
		"src": "Es wurde ein Ermittlungsverfahren er\u00f6ffnet, was ein \"logischer\" Schritt in einer solchen Situation ist, teilte Gilles Hofstetter dem Le Tribune de Geneve mit.",
		"tgt": "A criminal investigation has been opened, a \"logical\" step in a situation like this, lawyer Gilles Hofstetter told Le Tribune de Geneve."
	},
	{
		"src": "Es bleibt jedoch abzuwarten, ob einer der Fahrer angezeigt werden wird.",
		"tgt": "However it remains to be seen if any of the drivers involved will face charges."
	},
	{
		"src": "War ein Zusammensto\u00df vermeidbar?",
		"tgt": "Was it possible to avoid impact?"
	},
	{
		"src": "Das ist etwas, was der Staatsanwalt entscheiden muss,\" sagte Hofstetter.",
		"tgt": "That's what the prosecutor must determine,\" said Hofstetter."
	},
	{
		"src": "Zwei \u00e4hnliche F\u00e4lle in den letzten f\u00fcnf Jahren zeigen, dass die Fahrer nicht zur Verantwortung gezogen werden.",
		"tgt": "Two other similar cases in the past five years suggest that drivers will not be held responsible."
	},
	{
		"src": "In jedem der beiden F\u00e4lle - bei denen eine Person im Dunklen auf der Autobahn lief - wurde entschieden, dass die Autofahrer nicht davon ausgehen m\u00fcssen, dass eine Fu\u00dfg\u00e4nger mitten in der Nacht auf der Autobahn l\u00e4uft, wie es in der Zeitung hie\u00df.",
		"tgt": "In each case - both of which involved a person walking on the motorway in the dark - it was judged that motorists cannot expect to come across a pedestrian on the motorway in the middle of the night, said the paper."
	},
	{
		"src": "Letztes Jahr wurde eine Polizistin der fahrl\u00e4ssigen T\u00f6tung freigesprochen, nachdem sie einen Mann \u00fcberfahren und get\u00f6tet hatte, der im August 2014 eines Nacht auf der A1 in der N\u00e4he von Payerne lag.",
		"tgt": "Last year a police officer was acquitted of causing death by negligence after she hit and killed a man who was lying on the A1 near Paynerne one night in August 2014."
	},
	{
		"src": "Das 22-j\u00e4hrige Opfer hatte getrunken und ist auf der Stra\u00dfe bewusstlos geworden, vernahm das Gericht.",
		"tgt": "The 22-year-old victim had been drinking and had passed out on the road, the court heard."
	},
	{
		"src": "Das Gericht stellte fest, dass die Polizistin -- die auf einen Notruf geantwortet hatte -- auf eine gerechtfertigte Art und Weise fuhr und, dass die Anwesenheit eines Mannes auf der Stra\u00dfe eine \"vollkommen au\u00dfergew\u00f6hnliche und unvorhersehbare Situation\" war, sagte der Richter.",
		"tgt": "The court found that the policewoman -- who was responding to an emergency call -- was driving in a manner that was justified and that the presence of a man on the road was a \"completely exceptional and unpredictable situation,\" the judge said."
	},
	{
		"src": "Jeder, der weitere Informationen zu dem Vorfall am Donnerstag in der N\u00e4he von Morges hat, sollte sich bei der Polizei unter der Nummer 021 644 83 46 oder 021 644 44 44 melden.",
		"tgt": "Anyone with information about Thursday's incident near Morges should call police on 021 644 83 46 or 021 644 44 44."
	},
	{
		"src": "NASA Klimamodell: Venus war einst bewohnbar",
		"tgt": "NASA climate model: Venus was once habitable"
	},
	{
		"src": "Die Venus war laut den Projektionen eines neuen NASA Klimamodells wahrscheinlich einst bewohnbar.",
		"tgt": "Venus was likely once habitable, according to the projections of a new NASA climate model."
	},
	{
		"src": "Wissenschaftler am Goddard Institute for Space Studies der NASA entwickelten ein Modell, um die Vergangenheit der Venus anhand von Tools und Algorithmen zu entdecken, die denen von Klimaforschern \u00e4hneln.",
		"tgt": "Scientists at NASA's Goddard Institute for Space Studies developed a model to explore Venus' past using tools and algorithms similar to those employed by climate scientists."
	},
	{
		"src": "Das Modell wurde entworfen, um zu bestimmen, ob die Venus mit ihrer hei\u00dfen, wasserlosen Oberfl\u00e4che und CO2-dichten Atmosph\u00e4re einst erd\u00e4hnliche Bedingungen aufgewiesen haben k\u00f6nnte.",
		"tgt": "The model was designed to determine whether or not Venus, with its hot, water-less surface and CO2-chocked atmosphere, might have once hosted Earth-like conditions."
	},
	{
		"src": "Wissenschaftler haben zuvor darauf hingedeutet, dass die langsame Umdrehung der Venus durch ihre dichte Atmosph\u00e4re erkl\u00e4rt werden k\u00f6nnte.",
		"tgt": "Scientists have previously suggested that Venus' slow rotation rate is explained by its thick atmosphere."
	},
	{
		"src": "Aber die neueste Simulation deutet darauf hin, dass die Venus eine d\u00fcnne, erd\u00e4hnliche Atmosph\u00e4re gehabt haben k\u00f6nnte und sich dennoch langsam weiterdrehte.",
		"tgt": "But the latest simulation suggests Venus could have boasted a thin, Earth-like atmosphere and still spun slowly."
	},
	{
		"src": "Das Modell beleuchtete auch die Topographie der fr\u00fchen Venus.",
		"tgt": "The model also looked at the topography of early Venus."
	},
	{
		"src": "Der Planet wies vermutlich mehr trockene Gegenden als de Erde auf, aber hatte einst genug Wasser und geographische Variabilit\u00e4t, um Leben zu beherbergen und vor schneller Verdunstung sch\u00fctzte.",
		"tgt": "The planet likely featured more dry regions than Earth, but once had enough water and geographical variability to host life and guard against rapid evaporation."
	},
	{
		"src": "Die fr\u00fche Venus profitierte auch von einer Sonne, die 30 Prozent matter war.",
		"tgt": "Early Venus also benefited from a sun that was 30 percent dimmer."
	},
	{
		"src": "\"In der GISS-Modellsimulation exponiert die langsame Umdrehung der Venus ihre Tagesseite der Sonne fast zwei Monate lang,\" erkl\u00e4rte GISS Wissenschaftler Anthony Del Genio in einer Pressemitteilung.",
		"tgt": "\"In the GISS model's simulation, Venus' slow spin exposes its dayside to the sun for almost two months at a time,\" GISS scientist Anthony Del Genio explained in a news release."
	},
	{
		"src": "Dies erw\u00e4rmt die Oberfl\u00e4che und produziert Regen, das eine dicke Schicht Wolken erschafft, was wie ein Regenschirm wirkt, um die Oberfl\u00e4che von einem Gro\u00dfteil der Sonnenw\u00e4rme abzuschirmen.",
		"tgt": "This warms the surface and produces rain that creates a thick layer of clouds, which acts like an umbrella to shield the surface from much of the solar heating."
	},
	{
		"src": "Das Ergebnis sind Durchschnittstemperaturen, die einige Grad k\u00fchler als die der Erde heute sind.",
		"tgt": "The result is mean climate temperatures that are actually a few degrees cooler than Earth's today."
	},
	{
		"src": "Das Modell brachte eine Geschichte der Venus hervor, die der Evolution \u00e4hnelt, die zuvor von Planetenforschern vermutet wurde.",
		"tgt": "The model produced a story of Venus similar to the evolution previously hypothesized by planetary scientists."
	},
	{
		"src": "Obwohl sie einst vermutlich bewohnbar war, war die Venus -- im Laufe mehrer Milliarden Jahre --zuviel Hitze und ultraviolettem Licht ausgesetzt.",
		"tgt": "Though likely once habitable, Venus was -- over the course of several billion years -- exposed to too much heat and ultraviolet light."
	},
	{
		"src": "Ihre Ozeane verdunsteten und ihr Wasserdampf wurde vom ultraviolettem Licht weggebrannt.",
		"tgt": "Its oceans evaporated and its water vapor was burned away by ultraviolet light."
	},
	{
		"src": "Als ihr Hydrogen entwich blieb nur noch eine dicke Atmosph\u00e4re an Kohlenstoffdioxid mit einer t\u00f6dlichen Treibhauswirkung zur\u00fcck -- die Venus, die wie wir sie heute kennen.",
		"tgt": "As its hydrogen escaped, all that was left was a thick atmosphere of carbon dioxide with a deathly greenhouse gas effect -- thus, the Venus we know today."
	},
	{
		"src": "Die Forscher teilten die Ergebnisse ihres neuen Venus Klimamodells im Geophysical Research Letters.",
		"tgt": "Researchers shared the results of their new Venus climate model in the journal Geophysical Research Letters."
	},
	{
		"src": "Patrick Roy tritt als Trainer der Avalanche zur\u00fcck",
		"tgt": "Patrick Roy resigns as Avalanche coach"
	},
	{
		"src": "Patrick Roy trat am Donnerstag als Trainer und Vice President Of Hockey Operations der Colorado Avalanche zur\u00fcck und f\u00fchrte ein zu geringes Mitbestimmungsrecht beim Entscheidungsprozess des Teams an.",
		"tgt": "Patrick Roy resigned as coach and vice president of the hockey operations of the Colorado Avalanche on Thursday, citing a lack of a voice within the team's decision-making process."
	},
	{
		"src": "Alternativ-Pr\u00e4sident/General Manager der Colorados Joe Sakic best\u00e4tigte diese Entscheidung und merkte an, dass der Verein unverz\u00fcglich nach einem neuen Trainer suchen wird.",
		"tgt": "Colorado executive vice president/general manager Joe Sakic confirmed the move and noted that the club will begin a search for a new coach immediately."
	},
	{
		"src": "\"In den letzten drei Jahren habe ich meine Pflichten als Cheftrainer und Vice President Of Hockey Operations der Colorado Avalanche mit Energie, Leidenschaft und Bestimmtheit erf\u00fcllt,\" \u00e4u\u00dferte sich der 50-j\u00e4hrige Roy in einer Stellungnahme.",
		"tgt": "\"For the past three years, I have carried out my duties as head coach and vice president of hockey operations for the Colorado Avalanche with energy, passion and determination,\" the 50-year-old Roy said in the statement."
	},
	{
		"src": "Ich habe im Laufe des Sommers lange und viel dar\u00fcber nachgedacht, wie ich dieses Team verbessern k\u00f6nnte, um ihm mehr Tiefe zu verleihen, dies es ben\u00f6tigt und es auf ein h\u00f6heres Niveau zu bringen.",
		"tgt": "I have thought long and hard over the course of the summer about how I might improve this team to give it the depth it needs and bring it to a higher level."
	},
	{
		"src": "Um dies zu erreichen, muss die Vision des Trainers und Vice President Of Hockey Operations perfekt auf die der Organisation abgestimmt sein.",
		"tgt": "To achieve this, the vision of the coach and VP-hockey operations needs to be perfectly aligned with that of the organization."
	},
	{
		"src": "Er muss auch ein Mitbestimmungsrecht bei Entscheidungen haben, die die Leistung des Teams beeinflussen.",
		"tgt": "He must also have a say in the decisions that impact the team's performance."
	},
	{
		"src": "Diese Bedingungen werden momentan nicht erf\u00fcllt.",
		"tgt": "These conditions are not currently met."
	},
	{
		"src": "Sakic, der Roy am 23. Mai 2013 angeheuert hatte, bedankte sich bei ihm f\u00fcr dessen Beitr\u00e4ge f\u00fcr das Team.",
		"tgt": "Sakic, who hired Roy on May 23, 2013, thanked Roy for his contributions to the team."
	},
	{
		"src": "\"Patrick hat mich heute \u00fcber diese Entscheidung informiert,\" sagte Sakic.",
		"tgt": "\"Patrick informed me of his decision today,\" Sakic said."
	},
	{
		"src": "Wir sch\u00e4tzen alle, was er f\u00fcr unsere Organisation getan hat und w\u00fcnschen ihm f\u00fcr die Zukunft nur das Beste.",
		"tgt": "We appreciate all he has done for our organization and wish him the best of luck in the future."
	},
	{
		"src": "Roy wurde w\u00e4hrend seiner Deb\u00fctsaison bei den Avalanches 2013-14 als Gewinner des Jack Adams Awards als der beste Trainer der Liga ausgezeichnet.",
		"tgt": "Roy was named the Jack Adams Award winner as the league's best coach during his rookie season with the Avalanche in 2013-14."
	},
	{
		"src": "Er f\u00fchrte den Verein auf 112 Punkte und auf den ersten Platz in der Central Vision, aber Colorado wurde in der ersten Runde der Playoffs von Minnesota geschlagen und verpasste in jedem der beiden letzten Jahre die Nachsaison.",
		"tgt": "He guided the club to 112 points and a first-place finish in the Central Division, but Colorado was upset by Minnesota in the first round of the playoffs and has missed the postseason in each of the last two years."
	},
	{
		"src": "Die Avalanches verzeichneten in der Saison 2015-16 eine 39-39-4 Marke und fielen hinter den Wild f\u00fcr eine zweite Wildcard Spot in der Western Conference um f\u00fcnf Punkte zur\u00fcck.",
		"tgt": "The Avalanche posted a 39-39-4 mark in 2015-16 and fell five points shy of the Wild for the second wild-card spot in the Western Conference."
	},
	{
		"src": "Als Hall of Fame Torwart gewann Roy vier Stanley Cups -- zwei St\u00fccke mit den Montreal Canadiens und den Avalanche.",
		"tgt": "A Hall of Fame goaltender, Roy won four Stanley Cups -- two apiece with the Montreal Canadiens and the Avalanche."
	},
	{
		"src": "Nordesee\u00f6larbeiter nehmen wieder Gespr\u00e4che auf, setzen Streik aus",
		"tgt": "North Sea oil workers resume talks, suspend strike"
	},
	{
		"src": "Die Arbeitsk\u00e4mpfe bez\u00fcglich der Entlohnung f\u00fcr Nordsee\u00f6larbeiter werden ausgesetzt, w\u00e4hrend sich alle Streitparteien f\u00fcr eine neue Gespr\u00e4chsrunde an den Tisch setzen, sagten Verhandlungsf\u00fchrer.",
		"tgt": "Labor strikes over pay for North Sea oil workers are suspended while all parties to the dispute sit down for a new round of talks, lead negotiators said."
	},
	{
		"src": "Streiks gegen den \u00d6lfelddienstleister Wood Group wurden sporadisch auf Plattformen in der Nordsee durchgef\u00fchrt, die durch Royal Dutch Shell betrieben werden.",
		"tgt": "Strikes against oilfield services company Wood Group have been staged sporadically on platforms in the North Sea operated by Royal Dutch Shell."
	},
	{
		"src": "\"Wood Group sowie die Unite und RMT Gewerkschaften k\u00f6nnen best\u00e4tigen, dass wir uns geeinigt haben, den Abwicklungsprozess des derzeitigen Streites neu zu beginnen,\" hei\u00dft es in einer gemeinsamen Aussage.",
		"tgt": "\"Wood Group and the Unite and RMT unions can confirm we have agreed to restart the process for resolution of the current dispute,\" a joint statement read."
	},
	{
		"src": "Wir werden einige ganzt\u00e4gige Sitzungen in den n\u00e4chsten Wochen abhalten, die Anfang n\u00e4chsten Jahres anfangen werden, um die Probleme neu anzugehen.",
		"tgt": "We will hold a number of full-day meetings over the next few weeks, starting early next week, to take a fresh look at the issues."
	},
	{
		"src": "Die Gewerkschaften sagten, dass ihr letzter Streik, der der erste in \u00fcber 25 Jahren ist, ein Protest gegen m\u00f6gliche Lohnk\u00fcrzungen von bis zu 30 Prozent sei.",
		"tgt": "The labor unions said their recent action, which they said is the first in more than 25 years, was in protest of potential pay cuts of up to 30 percent."
	},
	{
		"src": "Wood Group hat dieses Jahr die Raten an seine Kontraktoren in der Nordsee um rund 9 Prozent aufgrund von negativem Marktdruck gek\u00fcrzt.",
		"tgt": "Wood Group this year cut rates paid to its North Sea contractors by about 9 percent because of negative market pressures."
	},
	{
		"src": "Die Ratenk\u00fcrzung des Unternehmens folgt einem 10-prozentigem R\u00fcckgang f\u00fcr Onshore-Auftragnehmer im Jahr 2014.",
		"tgt": "The company's rate reduction follows a 10 percent decrease for onshore contractors in 2014."
	},
	{
		"src": "Das Unternehmen sagte, dass zus\u00e4tzliche K\u00fcrzungen dem Unternehmen den ben\u00f6tigten Raum gibt, um durch den Marktabschwung zu kommen.",
		"tgt": "The company said additional cuts would give the company the room needed to move through the market downturn."
	},
	{
		"src": "Shell hat f\u00fcr seinen Teil tausenden von Leuten entlassen und Pl\u00e4ne angek\u00fcndigt, seine \u00d6l- und Gasgesch\u00e4ftst\u00e4tigkeiten in bis zu 10 L\u00e4ndern aufzugeben, da es seine Gesch\u00e4ftst\u00e4tigkeiten als Folge seines Megazusammenschlusses mit dem britischen Energieunternehmen BG Group rationalisiert.",
		"tgt": "Shell, for its part, has trimmed thousands of people from its payroll and announced plans to leave oil and gas operations in up to 10 countries as it streamlines its operations in the wake of its mega-merger with British energy company BG Group."
	},
	{
		"src": "Energieunternehmen befinden sich aufgrund der niedrigeren Roh\u00f6lpreise unter Druck, eine wirtschaftliche Situation, die sich durch die Entscheidung der Briten im Juni, die Europ\u00e4ische Union zu verlassen, verst\u00e4rkt hatte.",
		"tgt": "Energy companies are under pressure from lower crude oil prices, an economic situation compounded by the British decision in June to leave the European Union."
	},
	{
		"src": "Das schottische Parlamentsmitglied Dave Anderson traf sich Anfang dieser Woche mit Arbeiterf\u00fchrern, um eines der gr\u00f6\u00dften Arbeitsstreitigkeiten zu diskutieren, die seit einer Generation in der Nordsee stattfanden.",
		"tgt": "Scottish Member of Parliament Dave Anderson met with labor leaders earlier this week to discuss one of the biggest labor disputes to strike the North Sea in a generation."
	},
	{
		"src": "Die Nordsee ist f\u00fcr die regionale Wirtschaft wichtig, sagte er.",
		"tgt": "The North Sea, he said, is vital for the regional economy."
	},
	{
		"src": "\"In der Nordsee und im ganzen Land ben\u00f6tigen wir eine Wirtschaft, die f\u00fcr viele und nicht nur f\u00fcr wenige funktioniert,\" sagte er in einer Aussage.",
		"tgt": "\"In the North Sea and right across the country, we need an economy that works for the many and not just the few,\" he said in a statement."
	},
	{
		"src": "2016 werden weniger als $ 1,4 Milliarden an Ausgaben f\u00fcr neue Projekte in der Nordsee im Vergleich zu durchschnittlich rund $ 7 Milliarden in den letzten f\u00fcnf Jahren erwartet.",
		"tgt": "Less than $1.4 billion in spending on new projects in the North Sea is expected in 2016, compared with an average of around $7 billion in the past five years."
	},
	{
		"src": "Kepler misst Rotationsrate von Sternen im Sternenhaufen der Plejaden",
		"tgt": "Kepler measures spin rates of stars in Pleiades cluster"
	},
	{
		"src": "Die neueste Mission mit dem Kepler Weltraumteleskop hat Astronomen dabei geholfen, den vollst\u00e4ndigsten Katalog an Rotationsraten unter den Sternen des Sternenhaufens der Plejaden zu sammeln.",
		"tgt": "The latest mission by the Kepler space telescope has helped astronomers collect the most complete catalog of spin rates among the stars of the Pleiades cluster."
	},
	{
		"src": "Die neuen Daten helfen den Astronomen zu verstehen, warum sich Sterne im Sternenhaufen zu unterschiedlichen Raten rotieren sowie in welchem Zusammenhang die Rotationszeitr\u00e4ume mit der Planetenentstehung stehen.",
		"tgt": "The new data is helping astronomers understand why stars in the cluster spin at varying rates, as well as how rotation periods relate to planet formation."
	},
	{
		"src": "\"Wir hoffen, dass wir durch das Vergleichen unserer Ergebnisse mit anderen Sternenhaufen, mehr \u00fcber die Beziehung zwischen der Masse eines Sterns, seinem Alter und sogar der Geschichte seines Sonnensystems erfahren,\" sagte Luisa Rebull, eine Forscherin am Caltech's Infrared Processing and Analysis Center in Pasadena, in einer Pressemitteilung.",
		"tgt": "\"We hope that by comparing our results to other star clusters, we will learn more about the relationship between a star's mass, its age, and even the history of its solar system,\" Luisa Rebull, a research scientist at Caltech's Infrared Processing and Analysis Center in Pasadena, said in a news release."
	},
	{
		"src": "Der Sternenhaufen der Plejaden liegt 445 Lichtjahre von der Erde entfernt.",
		"tgt": "The Pleiades cluster is situated 445 light-years from Earth."
	},
	{
		"src": "Viele Sterne in diesem Sternenhaufen, die vor rund 125 Millionen Jahren entstanden, erreichen jetzt das Erwachsenenalter.",
		"tgt": "Many of the stars in the cluster are just now reaching adulthood, having been born roughly 125 million years ago."
	},
	{
		"src": "Sie drehen sich jetzt am schnellsten.",
		"tgt": "They're spinning as fast as they ever will."
	},
	{
		"src": "Zu Spitzenrotationsraten sto\u00dfen diese reifenden Sterne gro\u00dfe Mengen an Sternwinden aus.",
		"tgt": "At their peak spin rates, these maturing stars eject large amounts of stellar wind."
	},
	{
		"src": "Da diese Winde durch die Magnetfelder der Sterne reisen, haben sie einen bremsenden Effekt auf die Sterne.",
		"tgt": "As these winds travel across the stars' magnetic fields, they enact a braking effect on the stars."
	},
	{
		"src": "Wenn ein Stern altert, beginnt seine Rotationsrate sich zu verlangsamen.",
		"tgt": "As a star ages, its spin rate begins to slow down."
	},
	{
		"src": "Kepler misst die Rotationsrate eines jeden Sterns, indem er die Zeit zwischen dem Erscheinen eines erkennbaren Sternenflecks -- wie Sonnenflecken -- erkennt.",
		"tgt": "Kepler measures each star's spin rate by tracking the time between the appearance of recognizable starspots -- like sunspots."
	},
	{
		"src": "Der neueste Katalog von Rotationsraten weist darauf hin, dass sich massivere Sterne langsamer drehen als weniger massive Sterne.",
		"tgt": "The latest catalog of spin rates suggests more massive stars spin more slowly than less massive stars."
	},
	{
		"src": "Rebull vergleicht die Sterne mit T\u00e4nzern, wobei gr\u00f6\u00dfere Sterne langsamer Pirouetten drehen als kleinere.",
		"tgt": "Rebull likens the stars to dancers, larger ones pirouetting more slowly than smaller ones."
	},
	{
		"src": "\"Im \"Ballet\" der Plejaden sehen wir, dass langsame Rotoren dazu tendieren, massiver zu sein, wohingegen schnellere Rotoren dazu tendieren, sehr helle Sterne zu sein,\" sagte Rebull.",
		"tgt": "\"In the 'ballet' of the Pleiades, we see that slow rotators tend to be more massive, whereas the fastest rotators tend to be very light stars,\" said Rebull."
	},
	{
		"src": "Da der Sternenhaufen der Plejaden so nah ist, dient es als ideales kosmisches Labor, um stellare Qualit\u00e4ten wie Rotationsraten zu vergleichen.",
		"tgt": "Because the Pleiades cluster is so close, it serves as an ideal cosmic laboratory to compare stellar qualities with spin rates."
	},
	{
		"src": "\"Der Sternenhaufen der Plejaden bietet einen Anker f\u00fcr theoretische Modelle der stellaren Rotation in beide Richtungen, j\u00fcngere und \u00e4ltere,\" sagte Rebull.",
		"tgt": "\"The Pleiades star cluster provides an anchor for theoretical models of stellar rotation going both directions, younger and older,\" said Rebull."
	},
	{
		"src": "Es liegt noch viel vor uns wor\u00fcber wir gerne mehr erfahren wollen, wie das Wie, Wann und Warum Sterne ihre Rotationsraten verlangsamen und sozusagen ihre \"Tanzschuhe\" aufh\u00e4ngen.",
		"tgt": "We still have a lot we want to learn about how, when and why stars slow their spin rates and hang up their 'dance shoes,' so to speak."
	},
	{
		"src": "Rebull und ihre Kollegen haben in drei Zeitungsberichten ausf\u00fchrlich \u00fcber ihre neueste Analyse der Rotationsraten der Plejaden berichtet, die bald im Astronomical Journal erscheinen werden.",
		"tgt": "Rebull and her colleagues detailed their latest analysis of Pleiades spin rates in three new papers, soon to be published in the Astronomical Journal."
	},
	{
		"src": "Ein umstrittener Baseball-Star tritt ab",
		"tgt": "A controversial baseball star steps down"
	},
	{
		"src": "Die Tr\u00e4nen liefen bei Alex Rodriguez schneller als der US-Baseball-Star in besten Tagen von Base zu Base.",
		"tgt": "Alex Rodriguez' tears ran quicker than the US baseball star had run from base to base, in better days."
	},
	{
		"src": "Nach seiner emotionalen R\u00fccktritts-Bekanntgabe wird der 41 Jahre alte Profi am 12. August gegen die Tampa Bay Rays ein letztes Mal das Trikot seiner New York Yankees tragen.",
		"tgt": "After his emotional announcement of retirement, the 41-year-old pro will wear his New York Yankees jersey for the last time on 12 August, against the Tampa Bay Rays."
	},
	{
		"src": "\"Ich liebe dieses Spiel und dieses Team.\"",
		"tgt": "\"I love this game and this team.\""
	},
	{
		"src": "\"Ich sage 'Goodbye' zu beidem\", erkl\u00e4rte der 14-malige All-Star-Game-Teilnehmer der Major League Baseball (MLB).",
		"tgt": "\"I'm saying goodbye to both of them,\" the 14-time All Star Major League Baseball (MLB) player explained."
	},
	{
		"src": "Dreimal wurde Rodriguez zum wertvollsten Spieler der Liga gew\u00e4hlt, 2009 gewann er mit den Yankees die World Series.",
		"tgt": "Rodriguez was voted the most valuable player in the league three times, and in 2009 he won the World Series with the Yankees."
	},
	{
		"src": "Seine Unterschrift unter einem Zehnjahresvertrag bescherte ihm seit 2007 j\u00e4hrlich 27 Millionen US-Dollar.",
		"tgt": "He signed a ten-year contract, which has brought him 27 million US dollars every year since 2007."
	},
	{
		"src": "Bis zum Ende des Kontrakts am 31. Dezember 2017 fungiert er k\u00fcnftig als Berater und Jugendcoach - bei vollem Gehalt.",
		"tgt": "Until the end of the contract on 31 December 2017, he will work as a consultant and a youth coach - on full pay."
	},
	{
		"src": "Als Spieler zahlte es Rodriguez lange Zeit mit Leistung zur\u00fcck.",
		"tgt": "Rodriguez paid this back in terms of playing performance long ago."
	},
	{
		"src": "Mit 696 Homeruns, 3114 Hits und 2021 Punkten f\u00fcr seine Teams (\"Runs\") f\u00fcr die Seattle Mariners (1994 bis 2000), den Texas Rangers (2001 bis 2004) und seit 2005 den Yankees schaffte er einige Meilensteine.",
		"tgt": "With 696 home runs, 3114 hits and 2021 points for his team (\"runs\"), for the Seattle Mariners (1994 to 2000), the Texas Rangers (2001 to 2004) and since 2005, the Yankees, he has reached rather a few milestones."
	},
	{
		"src": "Mit den Hall-of-Fame-Mitgliedern Hank Aaron und Willie Mays weisen nur zwei weitere Baseball-Spieler in den wichtigsten Statistiken \u00e4hnliche Werte auf.",
		"tgt": "Along with Hall of Fame members Hank Aaron and Willie Mays, there are only two other baseball players who can boast similar key statistics."
	},
	{
		"src": "Doch in die Ruhmeshalle des Baseballs d\u00fcrfte der 41-J\u00e4hrige dennoch nicht aufgenommen werden.",
		"tgt": "However, the 41-year-old cannot be welcomed into the baseball Hall of Fame."
	},
	{
		"src": "Denn so erfolgreich Rodriguez - Spitzname \"A-Rod\" - auf dem Feld war, so umstritten ist sein Auftreten au\u00dferhalb des Platzes.",
		"tgt": "Because no matter how successful Rodriguez - nicknamed \"A-Rod\" - was on the pitch, his behaviour off the pitch was just as controversial."
	},
	{
		"src": "Bereits 2009 gab der Superstar bei \"ESPN\" zu, zwischen 2001 und 2003 verbotene Steroide zu sich genommen zu haben.",
		"tgt": "As far back as 2009 the superstar told ESPN that he had taken banned steroids between 2001 and 2003."
	},
	{
		"src": "Im August 2013 wurde er aufgrund einer Verwicklung im sogenannten Biogenesis-Skandal bis Ende 2014 f\u00fcr 211 Partien gesperrt.",
		"tgt": "In August 2013 he was banned for 211 games until the end of 2014 for his involvement in the \"biogenesis scandal\"."
	},
	{
		"src": "Rodriguez gilt als Hauptverd\u00e4chtiger, jahrelang \u00fcber eine Anti-Aging-Klinik in S\u00fcd-Florida leistungsf\u00f6rdernde Mittel erhalten zu haben.",
		"tgt": "Rodriguez was the main suspect accused of having received performance enhancing drugs via an anti-ageing clinic in Florida over a period of years."
	},
	{
		"src": "Nach einem Rechtsstreit wurde die Sperre noch auf 162 Begegnungen reduziert.",
		"tgt": "After a legal battle, the ban was reduced to 162 matches."
	},
	{
		"src": "\"Die Liga k\u00f6nnte mir f\u00fcr das Jahr 2014 sogar einen Gefallen getan haben, denn ich habe 20 Jahre ohne Pause durchgespielt\", sagte Rodriguez damals s\u00fcffisant.",
		"tgt": "\"The league might even have done me a favour in 2014 - I'd played for 20 years without a break,\" Rodriguez said, summing things up."
	},
	{
		"src": "Auch seine Abschieds-Tage verlaufen nicht ger\u00e4uschlos.",
		"tgt": "Even his final days didn't go off without a bang."
	},
	{
		"src": "W\u00e4hrend viele Baseball-Legenden in ihren letzten Spielen noch einmal die gro\u00dfe B\u00fchne erhalten, musste Rodriguez h\u00e4ufig auf der Bank sitzen.",
		"tgt": "While many baseball legends take to the great stage over their last few games, Rodriguez had to sit on the sidelines."
	},
	{
		"src": "\"Mein Job beinhaltet keine Abschieds-Tour.\"",
		"tgt": "\"My job isn't about a retirement tour.\""
	},
	{
		"src": "\"Mein Job beinhaltet den Versuch, jedes Spiel zu gewinnen\", \u00e4tzte Yankees-Coach Joe Girardi.",
		"tgt": "\"My job is about trying to win every game,\" stated Yankees coach Joe Girardi."
	},
	{
		"src": "Immerhin bekam Rodriguez, der mit der Schauspielerin Cameron Diaz verheiratet war und dem Verh\u00e4ltnisse mit Popstar Madonna und der Schauspielerin Kate Hudson nachgesagt werden, Sympathie-Bekundungen der Fans vom Yankee-Erzrivalen Boston Red Sox.",
		"tgt": "Nevertheless, Rodriguez, who was married to actress Cameron Diaz and who has been rumoured to have been linked to pop star Madonna and actress Kate Hudson, had the support of the fans of Yankees' arch rivals, Boston Red Sox."
	},
	{
		"src": "\"We want A-Rod\", sangen die Anh\u00e4nger bei der 4:9-Niederlage gegen das Rodriguez-Team.",
		"tgt": "\"We want A-Rod,\" the fans sang as they were defeated 4:9 by Rodriguez' team."
	},
	{
		"src": "Olympia 2016: Chen Xinyi, Silwia Danekowa und Adrian Zielinski sind erste Dopingf\u00e4lle",
		"tgt": "2016 Olympics: Chen Xinyi, Silwia Danekowa and Adrian Zielinski are the first doping cases"
	},
	{
		"src": "Erwischt: Wegen eines positiven Dopingprobe darf Gewichtheber Adrian Zielinski aus Polen in Rio nicht starten.",
		"tgt": "Busted: After a sample tested positive for doping, weightlifter Adrian Zielinksi from Poland is not allowed to compete in Rio."
	},
	{
		"src": "Rio de Janeiro - Die Olympischen Spiele 2016 werden von den ersten offiziellen Dopingf\u00e4llen \u00fcberschattet.",
		"tgt": "Rio de Janeiro - the 2016 Olympic Games have been overshadowed by the first official cases of doping."
	},
	{
		"src": "Eine erwischte Athletin h\u00e4tte fast eine Medaille gewonnen.",
		"tgt": "One now-banned athlete had almost won a medal."
	},
	{
		"src": "Vor dem siebten Wettkampftag sind die ersten offiziellen Dopingf\u00e4lle die Olympischen Spiele in Rio de Janeiro bekannt geworden.",
		"tgt": "The first official doping cases of the Rio Olympic Games were announced ahead of the seventh day of the competition."
	},
	{
		"src": "Die chinesische Schwimmerin Chen Xinyi, 3000-Meter-Hindernisl\u00e4uferin Silwia Danekowa aus Bulgarien und der polnische Gewichtheber Adrian Zielinski wurden in Brasilien positiv getestet und ausgeschlossen - unmittelbar vor dem Beginn der ohnehin kritisch be\u00e4ugten Leichtathletik-Wettbewerbe kommen diese Nachrichten zur Unzeit.",
		"tgt": "Chinese swimmer Chen Xinyi, 3000-meter hurdler Silwia Danekowa from Bulgaria and Polish weightlifter Adrian Zielinski tested positive in Brazil, and have been excluded. Just before the start of the athletics competition, which has not escaped criticism, this news comes at a bad time."
	},
	{
		"src": "Bei Chen war schon am vergangenen Sonntag das Diuretikum Hydrochlorothiazid nachgewiesen worden, das als maskierendes Mittel f\u00fcr Dopingsubstanzen benutzt wird.",
		"tgt": "The Sunday before, Chen had revealed the presence of the diuretic hydrochlorothiazide, which is used to mask drugs."
	},
	{
		"src": "Der Internationale Sportgerichtshof CAS best\u00e4tigte am Freitagnachmittag Ortszeit ihren Ausschluss von den Olympischen Spielen.",
		"tgt": "The international sport tribunal CAS confirmed on Friday afternoon local time that she had been banned from the Olympic Games."
	},
	{
		"src": "Am Sonntag hatte die 18-J\u00e4hrige den vierten Platz im Finale \u00fcber 100 m Schmetterling belegt, nur um 0,09 Sekunden verpasste sie dabei die Bronzemedaille.",
		"tgt": "On Sunday, the 18-year-old had taken fourth place in the 100m Butterfly final - missing out on a bronze medal by just 0.09 seconds."
	},
	{
		"src": "Am Freitag h\u00e4tte Chen an den Vorl\u00e4ufen \u00fcber 50 m Freistil teilnehmen sollen.",
		"tgt": "Chen was supposed to have taken part in the 50m Freestyle heats on Friday."
	},
	{
		"src": "Chen hat beim Internationalen Olympischen Komitee (IOC) die \u00d6ffnung der B-Probe und eine Anh\u00f6rung beantragt.",
		"tgt": "Chen applied to the International Olympic Committee (IOC) for a hearing and to have her B sample opened."
	},
	{
		"src": "Der nationale Verband nehme die Angelegenheit \"sehr ernst und verlangt von Chen volle Kooperation bei den Untersuchungen\", zitierte Xinhua aus einer Mitteilung: \"Wir werden mit dem Internationalen Sportgerichtshof CAS zusammenarbeiten und werden das Urteil akzeptieren\".",
		"tgt": "The national association is taking the instance \"very seriously, and asks that Chen cooperate fully with the investigations,\" quoted Xinhua from a press release: \"We will collaborate with the international sports tribunal CAS and will accept their decision\"."
	},
	{
		"src": "Erstmals in der Geschichte ist nicht mehr das IOC, sondern der CAS f\u00fcr die Sanktionierung der Sportler mit positiven F\u00e4llen zust\u00e4ndig.",
		"tgt": "For the first time in history, the CAS, not the IOC, is responsible for sanctioning sportspeople who test positive."
	},
	{
		"src": "Ebenfalls in der Nacht von Rio sickerte die Nachricht \u00fcber die positive Probe bei Danekowa durch, die 33-J\u00e4hrige ging damit selbst in die Offensive.",
		"tgt": "Also overnight in Rio, the news about Danekowa's positive test leaked out, and the 33-year-old went on the offensive herself."
	},
	{
		"src": "\"Ich hatte drei Tests, alle negativ, und mein vierter Test war positiv\", dies sei \"ein unglaublicher Schock\", sagte sie dem bulgarischen TV-Sender BNT.",
		"tgt": "\"I had three tests, all of which were negative, and my fourth test was positive,\" which was \"an unbelievable shock,\" she said to Bulgarian TV channel BNT."
	},
	{
		"src": "Sie sei unschuldig, \"die einzige Erkl\u00e4rung k\u00f6nnten Nahrungserg\u00e4nzungsmittel sein\", erkl\u00e4rte die Leichtathletin.",
		"tgt": "She said she was innocent and that \"the only explanation could be food supplements,\" the athlete explained."
	},
	{
		"src": "Dem Bericht zufolge soll es sich bei der verbotenen Substanz um das Blutdopingmittel EPO handeln.",
		"tgt": "According to the report, the banned substance involved was the blood doping chemical EPO."
	},
	{
		"src": "Danekowa wurde vorl\u00e4ufig suspendiert, laut BNT soll auch die B-Probe schon positiv ausgefallen sein.",
		"tgt": "Danekowa was suspended as a precaution, and according to BNT, a B sample also tested postive."
	},
	{
		"src": "Bulgariens Ministerpr\u00e4sident Bojko Borissow meldete sich umgehend mit Kritik an der Athletin zu Wort.",
		"tgt": "Bulgaria's Prime Minister Bojko Borissow spoke up immediately to criticise the athlete."
	},
	{
		"src": "\"Ich verstehe nicht, warum die Sportler nicht die richtigen Schl\u00fcsse ziehen\", sagte er: \"Wir Bulgaren stehen unter Beobachtung, so viele sind schon ausgeschlossen worden\".",
		"tgt": "\"I do not understand why sportspeople do not draw the right conclusions,\" he said: \"We Bulgarians are under observation, so many have already been banned\"."
	},
	{
		"src": "So d\u00fcrfen etwa s\u00e4mtliche Gewichtheber aus der chronisch dopingbelasteten Nation nicht in Rio teilnehmen.",
		"tgt": "Almost all the weightlifters from the nation, which has been plagued by doping, were not allowed to participate in Rio."
	},
	{
		"src": "Am Freitag wurde auch der Fall \"Adrian Zielinski\" bekannt, der London-Olympiasieger in der Klasse bis 85 kg wurde wie sein Bruder Tomasz drei Tage zuvor positiv auf das anabole Steroid Nandrolon getestet.",
		"tgt": "On Friday the case of \"Adrian Zielinski\" was announced: the winner at the London Olympics in the weight category of up to 85 kg had tested positive for the anabolic steroid Nandrolone three days earlier, just like his brother."
	},
	{
		"src": "Beide bestreiten die Einnahme, beide d\u00fcrfen allerdings nicht in der Klasse bis 94 kg starten.",
		"tgt": "Both deny taking it, but neither was allowed to compete in the weight category of up to 94 kg."
	},
	{
		"src": "Vor dem Start der Leichtathleten ist besonders der Fall Danekowa ein weiterer schwerer Schlag f\u00fcr die Reputation der gesamten Sportart.",
		"tgt": "Ahead of the athletes' start, the case of Danekowa is another heavy blow for the reputation of the entire sport."
	},
	{
		"src": "Der Weltverband IAAF hatte der kompletten russischen Mannschaft bis auf eine Ausnahme wegen systematischen Dopings den Start untersagt, auch die L\u00e4ufernation Kenia produziert in Rio zahlreiche schlechte Nachrichten.",
		"tgt": "The World Federation IAAF had banned the entire Russian team, with one exception, for systematic doping, and running nation Kenya also created a mass of bad news in Rio."
	},
	{
		"src": "Im Schwimmsport hatten zudem die fr\u00fcheren Vergehen in China f\u00fcr heftige Auseinandersetzungen auch zwischen den Athleten gesorgt.",
		"tgt": "In swimming, China's earlier offence had caused heated disputes between the athletes themselves."
	},
	{
		"src": "So griff der Franzose Camille Lacourt den chinesischen Olympiasieger Sun Yang harsch an.",
		"tgt": "Camille Lacourt, from France, spoke out harshly against Chinese Olympic winner Sun Yang."
	},
	{
		"src": "\"Sun Yang pinkelt lila.\"",
		"tgt": "\"Sun Yang's pee is purple.\""
	},
	{
		"src": "\"Wenn ich das Podium \u00fcber 200 m Freistil sehe, will ich mich \u00fcbergeben\", sagte Lacourt im franz\u00f6sischen Radio.",
		"tgt": "\"When I look at the podium for the 200m Freestyle, I want to throw up,\" Lacourt said on French radio."
	},
	{
		"src": "Sun stand zudem im Mittelpunkt einer Auseinandersetzung mit dem Australier Mack Horton.",
		"tgt": "In addition, Sun was at the middle of an argument with Mack Horton, from Australia."
	},
	{
		"src": "\"Ich habe keine Zeit und keinen Respekt f\u00fcr Doping-Betr\u00fcger\", sagte dieser.",
		"tgt": "\"I have no time and no respect for drug cheats,\" he said."
	},
	{
		"src": "Sun war 2014 bei den chinesischen Meisterschaften positiv auf das Stimulans Trimetazidin getestet worden, musste aber nur eine dreimonatige Sperre absitzen.",
		"tgt": "Sun tested positive for the stimulant trimetazidine at the Chinese championships in 2014, but only had to sit out for a three-month ban."
	},
	{
		"src": "Datenklau: So perfide erpressen Hacker ihr L\u00f6segeld",
		"tgt": "Data theft: This is how perfidiously hackers extort ransom money"
	},
	{
		"src": "Programmierer von Erpressungs-Malware greifen aktuell gezielt Unternehmen an - und sind dabei erfolgreich.",
		"tgt": "Programmers of extortion malware are currently targeting companies - with success."
	},
	{
		"src": "Laut einer aktuellen Umfrage der Malware-Abwehr-Spezialisten Malwarebytes unter 540 Unternehmen in Nordamerika, Gro\u00dfbritannien und Deutschland wurden 40 Prozent der befragten Firmen in den vergangenen zw\u00f6lf Monaten mindestens einmal, teilweise mehrfach Opfer einer Attacke mit Erpresser-Software.",
		"tgt": "According to a recent survey of 540 companies in North America, the UK and Germany by Malwarebytes, the malware defence specialists, 40 percent of the companies surveyed had fallen victim to one, two, or several attacks involving extortion software in the past twelve months."
	},
	{
		"src": "In Deutschland waren knapp 20 Prozent der Firmen bereits einmal Ziel einer Ransomware-Erpressung.",
		"tgt": "In Germany, around 20 percent of the companies had already been targeted by a ransomware attack."
	},
	{
		"src": "40 Prozent der Opfer zahlten bereitwillig die von den T\u00e4tern geforderten L\u00f6segelder, um die angegriffenen Systeme und Daten wieder nutzen zu k\u00f6nnen.",
		"tgt": "40 percent of the victims willingly paid up the ransom demanded by the perpetrators so that they were able to use their systems and data that had been affected by the attack."
	},
	{
		"src": "Die T\u00e4ter spezialisieren ihre Erpresser-Software laut der Beobachtungen von Malwarebytes zusehends auf Attacken in Firmennetzwerke.",
		"tgt": "According to Malwarebytes' observations, it is noticeable that perpetrators are tailoring their extortion software to attacks on corporate networks."
	},
	{
		"src": "Sind sie dort erfolgreich, f\u00e4llt das potenziell zu erpressende L\u00f6segeld deutlich h\u00f6her aus als bei Privatnutzern.",
		"tgt": "If they are successful in that domain, the ransom money they can demand is significantly higher than it would be for private users."
	},
	{
		"src": "\"Wir beobachten aktuell eine erschreckend schnelle Evolution der Schadsoftware\", erkl\u00e4rt Malwarebytes-Chef Marcin Kleczynski im Gespr\u00e4ch mit der \"Welt\".",
		"tgt": "\"We are currently seeing harmful software develop terrifyingly quickly,\" explains Malwarebytes' CEO, Marcin Kleczynski, in an interview with \"Die Welt\" newspaper."
	},
	{
		"src": "2008 waren die meisten Malwareprogramme noch darauf ausgelegt, Werbung zu verschicken.",
		"tgt": "In 2008, most malware programmes were still focused on sending out adverts."
	},
	{
		"src": "Dann entdeckten die T\u00e4ter Erpressungs-Software f\u00fcr sich.",
		"tgt": "Then perpetrators discovered extortion software."
	},
	{
		"src": "Erst waren Privatnutzer das Ziel, doch der Wechsel hin zu Firmenattacken erfolgte in den vergangenen Monaten erschreckend schnell.",
		"tgt": "Private users were initially the target, but the shift to corporate attacks took place terrifyingly quickly over the past few months."
	},
	{
		"src": "Ransomware arbeitet nach einem einfachen Muster: Einmal auf dem Computer eines Opfers aktiv, sucht sie gezielt nach unl\u00e4ngst ver\u00e4nderten Dateien wie etwa Word-, Excel- oder Datenbank-Dateien sowie nach Archiven von Bildern und Videos.",
		"tgt": "Ransomware follows a simple pattern: Once activated on a user's computer, it seeks out files that have not been edited for a long time, like Word, Excel or database files, as well as image and video archives."
	},
	{
		"src": "Diese Dateien verschl\u00fcsselt die Ransomware und l\u00f6scht die Originale nachhaltig.",
		"tgt": "The ransomware encrypts these files, and deletes the originals for good."
	},
	{
		"src": "Anschlie\u00dfend pr\u00e4sentiert die Software die Forderungen der Erpresser.",
		"tgt": "Finally, the software presents the extortioner's demands."
	},
	{
		"src": "Um den Endschl\u00fcsselungs-Code zu den Dateien zu bekommen, m\u00fcssen die Opfer Geld - meist in Form der Cryptow\u00e4hrung Bitcoin - \u00fcberweisen.",
		"tgt": "The victim has to transfer money - generally in the form of \"Bitcoins\", a cryptocurrency - to get the decryption code needed for the files."
	},
	{
		"src": "Doch wo bei Privatnutzern die pers\u00f6nliche Foto-Datenbank auf dem Spiel steht, geht es bei Firmen um sensible Kundendaten oder Projekt-Datenbanken, ohne die die Produktion stillsteht.",
		"tgt": "But while it's a personal photo database that's at play for private users, it's sensitive customer data or project databases needed for the continuation of projects that are the focus for companies."
	},
	{
		"src": "Dementsprechend h\u00f6her f\u00e4llt der Schaden aus, wenn eine Ransomware zuschl\u00e4gt.",
		"tgt": "As a result, the damage from a ransomware hit is greater."
	},
	{
		"src": "22 Prozent der betroffenen deutschen Firmen meldeten Umsatzverluste durch Ransomware, 13 Prozent mussten sogar die Gesch\u00e4ftst\u00e4tigkeit komplett unterbrechen, bei einem Fall waren Menschen in Lebensgefahr.",
		"tgt": "22 percent of German companies affected reported that they had suffered a fall in turnover due to ransomware, 13 percent had to cease trading entirely, and in one instance, people's lives were put at risk."
	},
	{
		"src": "In Deutschland waren bereits mehrfach Krankenh\u00e4user Opfer von Attacken, deren Patienten durch den Verlust von Krankenakten akut bedroht sein k\u00f6nnen.",
		"tgt": "In Germany, several hospitals have already fallen victim to attacks, and their patients were placed under serious threat as a result of the loss of medical records."
	},
	{
		"src": "\"Wir sagen den Opfern immer: Zahlt nicht, ihr f\u00f6rdert damit nur das Problem\", erkl\u00e4rt Kleczynski.",
		"tgt": "\"We always tell victims not to pay up: that simply exacerbates the problem,\" explains Kleczynski."
	},
	{
		"src": "Doch 80 bis 90 Prozent der Firmen, die zahlen, bekommen ihre Daten wieder.",
		"tgt": "But 80 to 90 percent of companies who pay up get their files back."
	},
	{
		"src": "F\u00fcr Manager ist es schwierig, angesichts von Stillstand im Betrieb die Forderung der T\u00e4ter abzulehnen.",
		"tgt": "Faced with operations coming to a standstill, it is hard for managers to say no to the perpetrators' demands."
	},
	{
		"src": "Die Hacker wiederum wissen das und versuchen alles, um eine gute Reputation aufzubauen.",
		"tgt": "Then again, the hackers know that, and do all they can to build up a good reputation."
	},
	{
		"src": "In einer aktuellen Studie haben die Sicherheitsforscher von F-Secure die Nutzeroberfl\u00e4chen und den Kontakt mit den Erpressern untersucht und kommen zu dem Ergebnis: Die T\u00e4ter versuchen tats\u00e4chlich, eine Art Kundenservice aufzubauen, um mehr Geld einzunehmen.",
		"tgt": "A recent study saw security researchers from F-Secure examine user interfaces and contact with extortioners. They came to the conclusion that perpetrators really do try to construct a kind of customer service system so that they can get more money."
	},
	{
		"src": "Sie erkl\u00e4ren ihren Opfern per Chat, wie sie per Bitcoin zahlen k\u00f6nnen, richten frei zug\u00e4ngliche Support-Websites ein oder entschl\u00fcsseln umsonst Beispiel-Dateien.",
		"tgt": "They explain to their victims via chat how to pay using Bitcoin, set up freely-accessible support websites, or decrypt sample files for free."
	},
	{
		"src": "Und werden Privatleute nach Zahlungen von wenigen Hundert Euro erl\u00f6st, m\u00fcssen Unternehmen teils hart verhandeln und f\u00fcnfstellige Summen zahlen, um ihre Daten unverschl\u00fcsselt zur\u00fcckzubekommen.",
		"tgt": "And while private individuals are targeted for sums of a few hundred euros, companies sometimes have to bargain hard and pay out five-figure sums to get their files back decrypted."
	},
	{
		"src": "Angesichts der potenziell hohen und relativ risikolosen Gewinne aus der Ransomware-Erpressung werden die Hacker immer professioneller und teilen sich die Arbeit, erkl\u00e4rt Sicherheitsexperte Chester Wisniewski vom Antivirus-Anbieter Sophos: \"Eine einzelne Person kann eine Ransomware circa innerhalb einer Woche schreiben.\"",
		"tgt": "Faced with the potentially high and relatively risk-free profits from ransomware extortion, hackers are becoming more and more professional, splitting up their work, explains security expert Chester Wisniewski from antivirus provider Sophos: \"An individual can write a ransomware program within about a week.\""
	},
	{
		"src": "Wahrscheinlicher ist es jedoch, dass es sich um drei oder vier Personen handelt.",
		"tgt": "However, it is more likely that three or four people will be involved."
	},
	{
		"src": "Die Programmierer verkaufen ihre Schadsoftware dann in Form eines Software-Baukastens an die eigentlichen Erpresser.",
		"tgt": "The programmers then sell their malware to the actual extortioners in the form of a set of software building blocks."
	},
	{
		"src": "Die bisherigen Malware-Kits entstanden, indem die Malware selbst, Beratung und zus\u00e4tzliche Tools f\u00fcr einen einmaligen, festen Preis zwischen 1000 und 10.000 Dollar gekauft wurden.",
		"tgt": "Malware kits to date, including the malware itself, advice and additional tools, have been sold for a one-off fixed fee of between 1000 and 10,000 dollars."
	},
	{
		"src": "\"Im Lieferumfang enthalten ist ein Anpassungstool, sodass kleinere Konfigurationen, Aussehen und Branding ver\u00e4ndert werden k\u00f6nnen\", sagt Wisniewski.",
		"tgt": "\"The kits include an adapter tool so that smaller configurations can be constructed, and the appearance and branding can be changed,\" says Wisniewski."
	},
	{
		"src": "Die Erpresser suchen sich dann weitere Hacker, um die frisch eingekaufte Software unter den Opfern zu verbreiten.",
		"tgt": "The extortioners then look out additional hackers to distribute the freshly prepared software between victims."
	},
	{
		"src": "Wir leben in einer Dienstleistungswirtschaft.",
		"tgt": "We live in a service economy."
	},
	{
		"src": "Man loggt sich also in eines der Foren im Untergrund, kauft das Set von einem Kriminellen und beauftragt einen weiteren damit, die Software auf m\u00f6glichst vielen PCs zu installieren.",
		"tgt": "So you just log into an underground forum, buy the set from a criminal, and task someone else with installing the software on as many PCs as possible."
	},
	{
		"src": "Die Bezahlung erfolgt pro infiziertem Rechner.",
		"tgt": "There's a payment made for every computer infected."
	},
	{
		"src": "\"\u00dcblicherweise beauftragen die Kriminellen dann Spammer mit der Verbreitung\", erkl\u00e4rt Wisniewski.",
		"tgt": "\"Normally, criminals then task spammers with distribution,\" explains Wisniewski."
	},
	{
		"src": "Das Risiko von Ransomware ist mittlerweile bei vielen Unternehmen bekannt, die ihre Daten besser sichern.",
		"tgt": "Now, many companies are aware of the risks of ransomware, and they are protecting their data better."
	},
	{
		"src": "\u00dcber 50 Prozent der Firmen-IT-Verantwortlichen in der Malwarebytes-Umfrage vertrauen darauf, Ransomware mittels Datei-Back-ups und Scannersoftware abwehren zu k\u00f6nnen.",
		"tgt": "More than 50 percent of companies' IT specialists in Maywarebytes' survey relied on using file back-ups and scanner software to beat ransomware."
	},
	{
		"src": "Dementsprechend verfolgen die T\u00e4ter bereits neue Strategien.",
		"tgt": "As a result, perpetrators are already trying out new strategies."
	},
	{
		"src": "\"Wenn die Verschl\u00fcsselung von Daten allein keine ausreichende Bedrohung f\u00fcr erfolgreiche Erpessung mehr ist, drohen die T\u00e4ter stattdessen mit der Ver\u00f6ffentlichung von sensiblen Daten wie etwa Kundenlisten oder Preiskalkulationen\", erkl\u00e4rt Malwarebytes-Chef Marcin Kleczynski.",
		"tgt": "\"If simply encrypting files isn't enough of a threat to make an extortion request be granted, the perpetrators threaten to publish sensitive files instead, such as customer lists, or price calculations,\" explains Malwarebytes' CEO, Marcin Kleczynski."
	},
	{
		"src": "Damit ist das Schadenspotential je nach Art der Daten noch um ein vielfaches h\u00f6her als zuvor.",
		"tgt": "This means that the risk potential is much higher than before, depending on the type of file."
	},
	{
		"src": "Auch k\u00f6nnten die T\u00e4ter k\u00fcnftig v\u00f6llig neue Ziele im Internet der Dinge aufs Korn nehmen.",
		"tgt": "In the future, perpetrators will be able to focus themselves on brand-new targets within the internet of things."
	},
	{
		"src": "Auf der Hackerkonferenz Defcon demonstrierten Sicherheitsforscher, wie sie ein mit dem Internet verbundenes Thermostat unter ihre Kontrolle bekommen konnten.",
		"tgt": "At the Defcon hacker conference, security researchers demonstrated how they could take control of a thermostat connected to the internet."
	},
	{
		"src": "Mitten im Winter k\u00f6nnte die Freischaltung einer derart blockierten Heizung so manchem Opfer durchaus ein L\u00f6segeld wert sein.",
		"tgt": "In the midst of winter, many victims would pay a ransom to have their blocked heating turned back on."
	},
	{
		"src": "Wenn die T\u00e4ter dann anstatt der Heizung in Zukunft eine ganze Fertigungsstra\u00dfe in einer Fabrik blockieren, k\u00f6nnte Ransomware auch in der Industrie 4.0 ein Thema werden.",
		"tgt": "In the future, if hackers switch off an entire production line in a factory instead of someone's heating, ransomware could also be a issue in Industry 4.0."
	},
	{
		"src": "Einer f\u00fcr alle F\u00e4lle",
		"tgt": "Something for every situation"
	},
	{
		"src": "HONDA HR-V ist flexibel und alltagstauglich",
		"tgt": "HONDA HR-V is practical and perfect for everyday use"
	},
	{
		"src": "In den kleinen HR-V will Honda alles packen: ein wenig SUV, ein wenig Coup\u00e9 und auch noch die Vielseitigkeit eines Minivans.",
		"tgt": "Honda wants to cram everything into the small HR-V: a bit of an SUV, a bit of a coup\u00e9, bundled up with the versatility of a minivan."
	},
	{
		"src": "Klingt ziemlich \u00fcberladen, doch der HR-V, der auf der gleichen neuen Plattform wie der neue Jazz konstruiert wurde, erweist sich im Alltag tats\u00e4chlich als ausgesprochen flexibel.",
		"tgt": "It seems a bit too much, but the HR-V, built on the same new platform as the new Jazz, does indeed prove itself to be exceptionally flexible in daily use."
	},
	{
		"src": "Obwohl der nur 1,60 m hohe HR-V eher klein wirkt, haben die Passagiere sowohl in der ersten Reihe als auch im Fond viel Platz, es wirkt an keiner Stelle eng.",
		"tgt": "Although the HR-V, at just 1.60m tall, seems small, passengers in the front and the back have got plenty of room, it's not a squeeze at all."
	},
	{
		"src": "Die Materialien des Innenraums sind gut verarbeitet und wirken angenehm, nur die Cockpit-Oberseite f\u00e4llt da etwas ab.",
		"tgt": "The materials used in the interior are well crafted, and have a pleasant appearance - just the surface of the dashboard lets the side down."
	},
	{
		"src": "Vielseitiger als vergleichbare Fahrzeuge ist der HR-V beim Stauraum.",
		"tgt": "The HR-V is more versatile than comparable vehicles in terms of its loading space."
	},
	{
		"src": "Es steht nicht nur ein Kofferraum von 453 l bei hochgestellten und 1026 l bei umgeklappten R\u00fcckenlehnen zur Verf\u00fcgung, sondern es gibt die \"Magic Seats\".",
		"tgt": "There isn't just a boot of 453 l with the seats up, and 1026 l with the seats down; there are the \"magic seats\" too."
	},
	{
		"src": "Das ist weniger magisch, als es klingt: Die Sitzfl\u00e4chen der R\u00fcckbank lassen sich wie Kinosessel hochklappen und bieten dadurch Stauraum, der vom Boden bis zur Decken 1,24 m hoch ist.",
		"tgt": "This is rather less magical than it sounds: the seats in the back can be flipped up like cinema seats to reveal additional loading space, measuring 1.24 m from floor to ceiling."
	},
	{
		"src": "Der Kofferraum l\u00e4sst sich gut beladen, allerdings ist die Ladeh\u00f6he mit 650 mm etwas h\u00f6her als beim vergleichbaren Peugeot 2008.",
		"tgt": "The boot is easy to load, but the load height of 650 mm is a bit higher than it is in the Peugeot 2008, which is a comparable model."
	},
	{
		"src": "Der getestete 1,6-l-Diesel mit 88 kW/120 PS beschleunigt den HR-V dank des Drehmoments von bis zu 300 Nm in weiten Drehzahlbereichen sehr kraftvoll.",
		"tgt": "The 1.6 l diesel engine we tested, with 88 kW/120 horsepower accelerates the HR-V powerfully, thanks to the torque of up to 300 Nm across a wide range of speeds."
	},
	{
		"src": "Er d\u00fcrfte seine Arbeit allerdings etwas leiser verrichten.",
		"tgt": "However, it could certainly do its work a bit more quietly."
	},
	{
		"src": "Erfreulich ist der Alltagsverbrauch von 4,7 l/100 km.",
		"tgt": "Everyday consumption of 4.7 l/100 km was pleasing."
	},
	{
		"src": "Es gibt noch eine weitere Motorisierung: einen 1,5-l-Benziner mit 96 kW/130 PS.",
		"tgt": "There is an additional motor: a 1.5 l petrol engine with 96 kW/130 horsepower."
	},
	{
		"src": "Ein Allradantrieb wird nicht angeboten.",
		"tgt": "All-wheel drive is not available."
	},
	{
		"src": "Das Fahrverhalten ist ausgewogen, ein guter Kompromiss zwischen Dynamik und Komfort.",
		"tgt": "Its handling is balanced, a good compromise between speed and comfort."
	},
	{
		"src": "Die Lenkung d\u00fcrfte aber etwas direkter sein.",
		"tgt": "The steering could be a bit more direct, however."
	},
	{
		"src": "Die Ausstattung l\u00e4sst in der getesteten Top-Variante \"Executive\" keine W\u00fcnsche offen.",
		"tgt": "In the top-flight \"Executive\" version, which we tested, the fittings leave nothing to be desired."
	},
	{
		"src": "Zu den Sicherheitssystemen geh\u00f6rt der City-Notbremsassistent (arbeitet bis Tempo 32), das Kollisionswarnsystem und der Spurhalteassistent.",
		"tgt": "The safety systems include city emergency braking assistant (functions up to a speed of 32), collision warning system, and the lane departure warning system."
	},
	{
		"src": "Der Kollisionswarner irritiert manchmal, weil er beim Rangieren viele Hindernisse als \"herannahende Objekte\" bewertet.",
		"tgt": "The collision warning system is irritating occasionally: when parking, it sees lots of obstacles as \"approaching objects\"."
	},
	{
		"src": "Sehr zuverl\u00e4ssig arbeitet der Fernlichtassistent.",
		"tgt": "The high-beam assistant system is very reliable."
	},
	{
		"src": "Und der intelligente Temporegler reagiert auf die Verkehrszeichenerkennung und drosselt bei Bedarf die Geschwindigkeit.",
		"tgt": "And the intelligent speed regulator reacts to traffic signage, and reduces the vehicle's speed if necessary."
	},
	{
		"src": "Die volle Konnektivit\u00e4t gibt es aber nur f\u00fcr die Top-Ausstattung: 7-Zoll-Touchscreen, Navi, App-Integration und mehr.",
		"tgt": "However, full connectivity is only available for the top-of-the-range model: 7 inch touchscreen, satnav, app integration, and more."
	},
	{
		"src": "Zwei USB- und eine HDMI-Buchse liegen unter der Armlehne und sind deshalb etwas umst\u00e4ndlich zu erreichen.",
		"tgt": "There are two USB ports and a HDMI port under the armrest, which makes them rather tricky to access."
	},
	{
		"src": "Die rund 29000 Euro f\u00fcr den gut ausgestatteten Top-Diesel sind in Ordnung.",
		"tgt": "It costs around 29,000 euros for a top-of-the-range diesel model, which is fair."
	},
	{
		"src": "Wer nicht so viel investieren will, erh\u00e4lt den Benziner ab 20000 Euro, den Diesel ab 23000 Euro.",
		"tgt": "If you don't want to invest quite that much, the petrol model is available from 20,000 euros, and diesel from 23,000 euros."
	},
	{
		"src": "Die Motoren erf\u00fcllen die Euro-6-Abgasnorm.",
		"tgt": "The motors comply with euro 6 emissions standards."
	},
	{
		"src": "Mit dem HR-V bietet Honda ein vielseitiges und alltagstaugliches Auto.",
		"tgt": "With the HR-V, Honda is offering a diverse car that is perfect for everyday driving."
	},
	{
		"src": "Airline haftet nicht: Sturz auf Fluggastbr\u00fccke",
		"tgt": "Airline is not liable: Fall on passenger boarding bridge"
	},
	{
		"src": "Eine Airline haftet nicht f\u00fcr den Sturz eines Passagiers auf der Fluggastbr\u00fccke.",
		"tgt": "An airline will not be liable for a passenger's fall on a passenger boarding bridge."
	},
	{
		"src": "Denn eine Haftung sei nur bei Gefahren denkbar, die typisch f\u00fcr den Luftverkehr sind, argumentierte das Oberlandesgericht D\u00fcsseldorf (Az.: 18 U 124/14).",
		"tgt": "This is because liability only applies for risks typical for aviation travel, the Higher Regional Court of Dusseldorf argued (Az.: 18 U 124/14)."
	},
	{
		"src": "Der Kl\u00e4ger hatte sich bei dem Sturz eine Kniescheibe gebrochen.",
		"tgt": "The claimant had broken a kneecap in the fall."
	},
	{
		"src": "Der Unfall h\u00e4tte jedoch \u00fcberall passieren k\u00f6nnen - es handele sich um ein allgemeines Lebensrisiko, so das Gericht.",
		"tgt": "However, the accident could have happened anywhere - it was one of the ordinary risks of life, pronounced the court."
	},
	{
		"src": "Die Fluggesellschaft musste dem Mann keinen Schadenersatz zahlen.",
		"tgt": "The airline did not have to pay the man any compensation."
	},
	{
		"src": "Krankheitsfall: Wann bezahlt der Veranstalter",
		"tgt": "When do organisers pay if illness strikes?"
	},
	{
		"src": "Erkrankte Urlauber bekommen nach ihrer Reise nur dann Geld zur\u00fcck, wenn die Ursache der Krankheit zweifelsfrei im Hotel zu finden ist.",
		"tgt": "Travellers who fall ill will only get their money back when they return home if there is no doubt that their illness was caused by something within their hotel."
	},
	{
		"src": "Das ist aber nur dann der Fall, wenn mehr als zehn Prozent der G\u00e4ste erwiesenerma\u00dfen die gleichen Symptome zeigen.",
		"tgt": "However, this is only the case if more than ten percent of visitors can be proved to have suffered the same symptoms."
	},
	{
		"src": "In dem verhandelten Fall war eine Familie am zweiten Tag ihres T\u00fcrkeiurlaubs schwer an Durchfall und Erbrechen erkrankt.",
		"tgt": "In this case, a family were stricken with diarrhoea and vomiting on the second day of their holiday in Turkey."
	},
	{
		"src": "Sie verbrachte fast den gesamten Urlaub im Zimmer.",
		"tgt": "They spent almost all their holiday in their room."
	},
	{
		"src": "Ihre Erkrankung f\u00fchrten die Urlauber auf eine defekte Kl\u00e4ranlage zur\u00fcck, die angeblich das Meerwasser verschmutzt hatte.",
		"tgt": "The holidaymakers blamed a malfunctioning sewage treatment plant, which they believed to have polluted the seawater."
	},
	{
		"src": "Die Familie war der Ansicht, die Reise sei damit mangelhaft gewesen - und klagte gegen den Veranstalter.",
		"tgt": "The family took the opinion that the holiday was unsatisfactory - and took the organiser to court."
	},
	{
		"src": "Vor Gericht hatten die Kl\u00e4ger keinen Erfolg.",
		"tgt": "The claimants had no luck in court."
	},
	{
		"src": "Zwar war die Kl\u00e4ranlage in der Tat defekt.",
		"tgt": "It was true that the waste treatment plant was suffering from a fault."
	},
	{
		"src": "Doch der Veranstalter erfuhr erst kurz vor Abreise der Kl\u00e4ger davon.",
		"tgt": "But the organiser only found out about this just before the claimants departed."
	},
	{
		"src": "Er musste bis dahin davon ausgehen, dass das Meerwasser in Ordnung war.",
		"tgt": "Until that date, the organiser had to assume that the seawater was acceptable."
	},
	{
		"src": "Er habe seine Informationspflichten also nicht verletzt, so das Urteil.",
		"tgt": "According to the judgement, the organiser had not violated its information obligation."
	},
	{
		"src": "Zumal in den Proben des Wassers keine Verunreinigungen gefunden wurden.",
		"tgt": "In addition, no contamination was found in water samples."
	},
	{
		"src": "Die Erkrankung mehrerer Hotelg\u00e4ste - wom\u00f6glich durch Ansteckung untereinander - geh\u00f6re zum allgemeinen Lebensrisiko.",
		"tgt": "When several hotel guests fall ill - possibly by infecting each other - the court views this as a general life risk."
	},
	{
		"src": "Von 691 G\u00e4sten waren nur 38 erkrankt.",
		"tgt": "Only 38 of 691 guests fell ill."
	},
	{
		"src": "De Maizi\u00e8re sagte, nach den von Fl\u00fcchtlingen ver\u00fcbten Gewalttaten in W\u00fcrzburg und Ansbach im Juli h\u00e4tten viele Menschen Sorge vor weiteren Anschl\u00e4gen.",
		"tgt": "De Maizi\u00e8re said that many people were worried about further attacks following the violence perpetrated by refugees in W\u00fcrzburg and Ansbach in July."
	},
	{
		"src": "Der Staat m\u00fcsse besonnen und entschlossen zugleich auf Terrorgefahren reagieren.",
		"tgt": "He said that the state must react to the threat of terrorism with prudence and resolve."
	},
	{
		"src": "Sicher ist: Unser Land wird die Gewalt der T\u00e4ter nicht mit Hass und Spaltung beantworten.",
		"tgt": "One thing is for sure: Our country will not react to the perpetrators' violence with hatred and division."
	},
	{
		"src": "Diesen Triumph werden wir den Terroristen nicht g\u00f6nnen.",
		"tgt": "We will not give the terrorists this victory."
	},
	{
		"src": "Wenn Straft\u00e4ter schneller das Land verlassen m\u00fcssten, erh\u00f6he das aber die Sicherheit und st\u00e4rke auch die Zustimmung der Bev\u00f6lkerung f\u00fcr die Fl\u00fcchtlingspolitik.",
		"tgt": "If perpetrators have to leave the country quicker, that will boost security and increase the general public's approval of refugee politics."
	},
	{
		"src": "De Maizi\u00e8re will eine Umsetzung der Vorschl\u00e4ge bis zur Bundestagswahl 2017 erreichen.",
		"tgt": "De Maizi\u00e8re wants the proposals to be implemented before the federal elections in 2017."
	},
	{
		"src": "Er k\u00fcndigte auch eine weitere personelle Verst\u00e4rkung der Sicherheitskr\u00e4fte an, und zwar \"in mittlerer vierstelliger Gr\u00f6\u00dfenordnung \u00fcber mehrere Jahre\".",
		"tgt": "He also announced that security services would receive more staff, to the tune of \"a mid-four figure sum over several years\"."
	},
	{
		"src": "Sympathiewerbung f\u00fcr Terrorismus m\u00fcsse wieder unter Strafe stehen.",
		"tgt": "Advertising for terrorism must be punishable once again."
	},
	{
		"src": "Video\u00fcberwachung soll verbessert, das Waffenrecht so novelliert werden, dass vor allem der Kauf von Waffen im Internet erschwert wird.",
		"tgt": "Video surveillance is to be improved, and gun laws to be amended so that purchasing weapons online, in particular, is made more difficult."
	},
	{
		"src": "Die zuletzt viel diskutierte Schweigepflicht f\u00fcr \u00c4rzte soll nach de Maizi\u00e8res Worten gewahrt bleiben.",
		"tgt": "Doctors' confidentiality obligations, recently the subject of much discussion, are to remain, according to De Maizi\u00e8re."
	},
	{
		"src": "Allerdings will er im Dialog mit der \u00c4rzteschaft nach L\u00f6sungen suchen, wie die Gef\u00e4hrdung der B\u00fcrger verringert werden k\u00f6nne, sagte er mit Blick etwa auf psychische Auff\u00e4lligkeiten.",
		"tgt": "However, he wants to talk to doctors to find solutions to reduce the risk to the general public with regard to mental illness, he said."
	},
	{
		"src": "Um einer Radikalisierung von Fl\u00fcchtlingen entgegenzuwirken, h\u00e4lt der Minister eine bessere soziale Betreuung f\u00fcr notwendig.",
		"tgt": "The Minister felt that improved social care was important to counteract the radicalisation of refugees."
	},
	{
		"src": "Lehrkr\u00e4fte m\u00fcssten besser auf den Umgang mit traumatisierten Menschen vorbereitet werden.",
		"tgt": "Teachers must be better trained for dealing with traumatised individuals."
	},
	{
		"src": "Zur Verfolgung von Kriminellen in speziellen Bereichen des Internets (Darknet) plant de Maizi\u00e8re den Einsatz verdeckter Ermittler.",
		"tgt": "De Maizi\u00e8re is planning to employ undercover agents to hunt down criminals in particular areas of the Internet (the Dark Web)."
	},
	{
		"src": "SPD-Chef Gabriel sagte: \"Die SPD ist bereit, \u00fcber alles zu reden, was dazu beitr\u00e4gt, die Sicherheit weiter zu erh\u00f6hen\".",
		"tgt": "SPD Head Gabriel said that \"the SPD is prepared to discuss anything that will increase security further\"."
	},
	{
		"src": "Es sei wichtig, dass sich der Innenminister klar gegen Aktionismus ausgesprochen habe.",
		"tgt": "He said it was important that the Minister of the Interior had spoken out clearly against actionism."
	},
	{
		"src": "\"Das war eine Ohrfeige f\u00fcr die Scharfmacher in der CDU/CSU\", sagte Gabriel den Zeitungen der Funke Mediengruppe (Freitag).",
		"tgt": "\"That was a slap in the face for agitators in the CDU/CSU,\" said Gabriel on Friday to the newspapers of the Funke media group."
	},
	{
		"src": "De Maizi\u00e8re hatte Rufe aus der Union nach einem Burka-Verbot und der Abschaffung der doppelten Staatsangeh\u00f6rigkeit zuvor zur\u00fcckgewiesen.",
		"tgt": "De Maizi\u00e8re had previously turned down calls from the coalition for a burka ban and the abolition of dual nationality."
	},
	{
		"src": "Ein generelles Verbot der Vollverschleierung halte er f\u00fcr verfassungsrechtlich problematisch.",
		"tgt": "He views an overarching ban of full veils as problematic under the constitution."
	},
	{
		"src": "Man kann nicht alles verbieten, was man ablehnt, und ich lehne das Tragen der Burka ab.",
		"tgt": "You can't ban everything you're opposed to, and I'm opposed to the wearing of the burka."
	},
	{
		"src": "Reden k\u00f6nne man \u00fcber Regeln etwa im Stra\u00dfenverkehr oder f\u00fcr Zeugen vor Gericht.",
		"tgt": "We can talk about the law with regard to traffic, or for witnesses appearing in court."
	},
	{
		"src": "Gr\u00fcnen-Chefin Simone Peter warf dem Minister vor, er wolle mit immer neuen Anti-Terror-Paketen Tatkraft und Handlungsf\u00e4higkeit simulieren.",
		"tgt": "Head of the Greens, Simone Peter, accused the Minister of wanting to use new anti-terror packages to create an air of energy and ability to act."
	},
	{
		"src": "Linken-Parteichef Bernd Riexinger sagte: \"Flotte Spr\u00fcche und eine Versch\u00e4rfung des Aufenthaltsrechts bringen den Menschen in diesem Land nicht mehr Sicherheit\".",
		"tgt": "Head of the Left, Bernd Riexinger, said that \"smooth talking and tightening up residency laws are not going to make the people in this country any more safe\"."
	},
	{
		"src": "Besserer Verkehrsfluss auf dem Autobahnzubringer",
		"tgt": "Better flow of traffic on the motorway slip road"
	},
	{
		"src": "Es staut sich regelm\u00e4\u00dfig auf der Umgehungsstra\u00dfe - hier ein Bild vom November.",
		"tgt": "Traffic jams are a regular occurrence on the bypass - here's a photo from November."
	},
	{
		"src": "Doch das soll sich \u00e4ndern: Die Rechtsabbiegespur soll verl\u00e4ngert werden.",
		"tgt": "But that is about to change: the right-hand turning lane is to be extended."
	},
	{
		"src": "Das ist eine gute Nachricht f\u00fcr alle Auto\u00adfahrer, die im Berufsverkehr auf der Umgebungsstra\u00dfe jeden Abend im Stau stehen, wenn sie \u00fcber den Autobahn\u00adzubringer (A 43) fahren.",
		"tgt": "This is good news for all drivers stuck in rush-hour traffic on the bypass every evening as they drive onto the motorway slip road (A43)."
	},
	{
		"src": "Der Landesbetrieb Stra\u00dfenbau verl\u00e4ngert am kommenden Dienstag und Mittwoch (16./17. August) im Bereich zwischen der Hammer Stra\u00dfe und der Abfahrt Weseler Stra\u00dfe die Rechtsabbiegerspur um 700 Meter.",
		"tgt": "Next Tuesday and Wednesday (16/17 August), the State Roadworks Office will extendthe right-hand turning lane in the area between Hammer Stra\u00dfe and the exit from Weseler Stra\u00dfe by 700 metres."
	},
	{
		"src": "Autofahrer k\u00f6nnen dann direkt von der Hammer Stra\u00dfe rechts einf\u00e4deln.",
		"tgt": "This means that drivers will be able to feed in directly from Hammer Stra\u00dfe."
	},
	{
		"src": "Der gro\u00dfe Vorteil: Der Verkehr teilt sich fr\u00fchzeitiger auf, wodurch der Gesamt\u00adablauf auf dem vielbefahrenen Abschnitt der Bundesstra\u00dfe 51 verbessert wird.",
		"tgt": "The major advantage is that traffic will split earlier, improving overall circulation on the busy section of main road 51."
	},
	{
		"src": "Die Idee mit der verl\u00e4ngerten Ausfahrt hatte die CDU-Fraktion in der Bezirks\u00advertretung M\u00fcnster-West.",
		"tgt": "The CDU fraction in the M\u00fcnster (West) district administration came up with the idea to lengthen the exit."
	},
	{
		"src": "Die Fahrbahnverengung auf dem Zubringer nervt die Autofahrer vor allem zwischen 17 und 19 Uhr.",
		"tgt": "The traffic on the slip road is particularly bad for drivers between 5pm and 7pm."
	},
	{
		"src": "Werktags reicht der R\u00fcckstau bis zur Br\u00fccke \u00fcber den Albersloher Weg und manchmal auch dar\u00fcber hinaus.",
		"tgt": "On weekdays, the traffic jam stretches to the bridge over Albersloher Weg - and sometimes even goes over it."
	},
	{
		"src": "Grund ist das Nadel\u00f6hr auf der B 51 kurz vor der Abfahrt Weseler Stra\u00dfe.",
		"tgt": "This is caused by the bottleneck on the B51, just before the exit onto Weseler Stra\u00dfe."
	},
	{
		"src": "Ab hier wird der Verkehr nur einspurig \u00fcber die Autobahnbr\u00fccke gelenkt.",
		"tgt": "From here, there is only a single lane of traffic over the motorway bridge."
	},
	{
		"src": "Die zweite Spur musste vor gut eindreiviertel Jahren zur\u00fcckgebaut werden.",
		"tgt": "The second lane was removed a good eighteen months ago."
	},
	{
		"src": "Der Grund: Statische Berechnungen hatten ergeben, dass die Br\u00fccke nicht mehr die erforderliche Tragkraft besitzt, um vor allem den Schwerlastverkehr zweispurig aufzunehmen.",
		"tgt": "The reason for this was that structural analysis had shown that the bridge was no longer capable of supporting the weight caused by two lanes, particularly the weight of heavy goods vehicles."
	},
	{
		"src": "Wie lange dieser Engpass und der damit verbundene werkt\u00e4gliche Stau andauern wird, kann der zust\u00e4ndige Landesbetrieb nicht sagen.",
		"tgt": "The relevant authorities cannot say how long this bottleneck, and the associated rush-hour traffic, will last."
	},
	{
		"src": "Allerdings ist mit Jahren zu rechnen: Denn die Br\u00fccke hat eine offizielle Restnutzdauer bis zum Jahr 2034.",
		"tgt": "It's going to be a matter of years: officially, the bridge will remain in use until 2034."
	},
	{
		"src": "F\u00fcr die Verl\u00e4ngerung der Rechtsabbiegespur hat der Landesbetrieb bewusst die verkehrsschw\u00e4chere Zeit in den Schulferien ausgesucht, weil mit Behinderungen zu rechnen sei.",
		"tgt": "The district authorities deliberately chose the less busy period of the school holidays for the extension of the right-hand turning lane, because it will cause delays."
	},
	{
		"src": "Der Verkehr wird am Dienstag und am Mittwoch einspurig an der Baustelle vorbei gef\u00fchrt.",
		"tgt": "Traffic will be diverted past the construction site in a single lane on Tuesday and Wednesday."
	},
	{
		"src": "Interkulturelle Reise: Kulturangebote f\u00fcr Schulen",
		"tgt": "Intercultural journey: Cultural programme for schools"
	},
	{
		"src": "Die internationale Klasse der Waldschule besuchte das Theaterst\u00fcck \"Das unsichtbare Haus\".",
		"tgt": "The international class from the forest school has been to see \"The Invisible House\" at the theatre."
	},
	{
		"src": "Der Verein Nima's und das Junge Theater planen jetzt ein Musikprojekt.",
		"tgt": "The \"Nima's\" association and Young Theatre are now planning a musical project."
	},
	{
		"src": "Der Verein Nima's erm\u00f6glicht Jugendlichen mit Migration- und Fl\u00fcchtlingshintergrund, kulturelle Institutionen in M\u00fcnster zu besuchen.",
		"tgt": "The \"Nima's\" association enables young people from a migrant or refugee background to visit cultural institutions in M\u00fcnster."
	},
	{
		"src": "Die \"Klasse International\" der Waldschule Kinderhaus hat eine Vorstellung des preisgekr\u00f6nten St\u00fccks \"Das unsichtbare Haus\" des Jungen Theaters M\u00fcnster besucht.",
		"tgt": "The \"International Class\" at the Kinderhaus forest school saw a performance of the award-winning play \"The Invisible House\" at the Young Theatre in M\u00fcnster."
	},
	{
		"src": "Im Kontext der vom Verein Nima's initiierten \"Interkulturellen Reise\" besuchten 19 Sch\u00fcler zwischen elf und 15 Jahren die Inszenierung im Kleinen Haus.",
		"tgt": "Within the framework of the \"Intercultural Journey\" set up by Nima's, 19 pupils aged between 11 and 15 saw the play in the small house."
	},
	{
		"src": "Seit Anfang des Jahres bietet der Verein, der sich die kulturelle Integration von Jugendlichen mit Migration- und Fl\u00fcchtlingshintergrund zum Ziel gesetzt hat, Schulen mit Willkommensklassen die M\u00f6glichkeit, im Rahmen dieses Projekts kulturelle Institutionen in M\u00fcnster zu besuchen.",
		"tgt": "The association's objective is to encourage cultural integration of young people from migrant and refugee backgrounds, and since the start of the year, it has offered schools with welcome classes with the chance to attend cultural institutions in M\u00fcnster as part of this project."
	},
	{
		"src": "Die meisten Jugendlichen der Klasse seien zwischen September 2015 und M\u00e4rz 2016 unter anderem aus Afghanistan, Iran, Serbien und Syrien nach M\u00fcnster gekommen und spr\u00e4chen wenig Deutsch.",
		"tgt": "Most young people in the class arrived in M\u00fcnster between September 2015 and March 2016 from Afghanistan, Iran, Serbia and Syria, among others, and spoke little German."
	},
	{
		"src": "Dank der Choreographien, der szenischen Bilder und Videoanimationen sei es ihnen m\u00f6glich gewesen, dem Handlungsverlauf dennoch zu folgen, so die Pressemitteilung des Jungen Theaters M\u00fcnster.",
		"tgt": "Thanks to the choreography, scenic images and video animations they were able to follow the plot regardless, according to the press release from M\u00fcnster's Young Theatre."
	},
	{
		"src": "Der Verein Nima's, gegr\u00fcndet von Dr. Tannaz Westerberg aus Sprakel, und das Junge Theater werden in der kommenden Spielzeit im Rahmen eines Musiktheaterprojekts zusammenarbeiten.",
		"tgt": "Nima's, founded by Dr. Tannaz Westerberg from Sprakel, and the Young Theatre, will work on a musical theatre project together over the next season."
	},
	{
		"src": "Von Oktober bis Dezember sollen Jugendliche mit und ohne Flucht- und Migrationshintergrund zwischen 14 und 20 Jahren die M\u00f6glichkeit erhalten, professionell angeleitete Kurse in den Bereichen Gesang, Tanz, Schauspiel und Musik zu besuchen.",
		"tgt": "From October to December, young people aged between 14 and 20 with and without a migrant and refugee background will have the chance to attend professionally-led courses for singing, dancing, acting, and music."
	},
	{
		"src": "Angebote f\u00fcr Kinder und Familien im Bereich Theaterspiel und theatrale Sprachvermittlung sind in der Planung.",
		"tgt": "There are also plans for acting and theatrical language training for children and families."
	},
	{
		"src": "Das Projekt \"Interkulturellen Reise\" geht weiter.",
		"tgt": "The \"Intercultural Journey\" project continues."
	},
	{
		"src": "Angesichts der gestiegenen Fl\u00fcchtlingszahlen rechnet der Verein mit vielen Klassen, die sich beteiligen wollen.",
		"tgt": "As a result of the increase in the number of refugees, the association is expecting that many classes will want to take part."
	},
	{
		"src": "Regen statt Sternschnuppen: Hoffnung auf Wetterbesserung",
		"tgt": "Rain replaces shooting stars: There is hope that the weather will improve"
	},
	{
		"src": "Das Wetter hat den Sternschnuppen-Guckern im S\u00fcdwesten Deutschlands in der Nacht zum Freitag einen Strich durch die Rechnung gemacht - doch es gibt noch Hoffnung.",
		"tgt": "For people hoping to spot shooting stars in south-west Germany on Thursday night, the weather put paid to their plans - but all is not lost."
	},
	{
		"src": "Die Nacht sei wegen Wolken und Regen schlecht daf\u00fcr geeignet gewesen, das Himmelsspektakel zu beobachten, sagte der Vorsitzende der Sternwarte Welzheim, Hans-Ulrich Keller, am Freitagmorgen.",
		"tgt": "The President of the Observatory of Welzheim, Hans-Ulrich Keller, said on Friday morning that the clouds and rain overnight meant that conditions were not ideal for observing the celestial show."
	},
	{
		"src": "Unsere Hoffnung liegt auf der Nacht zum Samstag.",
		"tgt": "We are pinning our hopes on Friday night."
	},
	{
		"src": "Das Wetter soll gut sein, dann sehen wir bestimmt viele Sternschnuppen am Himmel.",
		"tgt": "The weather is supposed to be good, so we'll definitely see lots of shooting stars in the sky."
	},
	{
		"src": "Bei den Sternschuppen handelt es sich um Perseiden, die mit 216000 Kilometern pro Stunde zu den schnellsten Sternschnuppen geh\u00f6ren.",
		"tgt": "The shooting stars are the Perseids: some of the quickest shooting stars, travelling at 216000 kilometres an hour."
	},
	{
		"src": "Ihren Namen haben sie, weil sie scheinbar aus dem Sternbild Perseus kommen, das im Nordosten aufgeht.",
		"tgt": "Their name refers to the fact that they seem to come from the constellation of Perseus, which is visible in the north-east."
	},
	{
		"src": "Erholsame Nacht: Tipps gegen Schlafst\u00f6rungen",
		"tgt": "Silent night: Tips to fight sleep disorders"
	},
	{
		"src": "Abends w\u00e4lzt man sich ewig herum, nachts liegt man stundenlang wach, morgens ist schon weit vor dem Weckerklingeln nicht mehr an Schlaf zu denken.",
		"tgt": "In the evening your mind won't stop whirring, you lie awake for hours each night, and by the time morning comes, sleep is far from your mind even well before your alarm goes off."
	},
	{
		"src": "Das ist alles andere als erholsam.",
		"tgt": "This is anything but relaxing."
	},
	{
		"src": "Immerhin ist man mit solchen Problemen in guter Gesellschaft: Laut dem Robert Koch-Institut hat etwa ein Viertel der Erwachsenen Schlafst\u00f6rungen und mehr als zehn Prozent empfinden ihren Schlaf h\u00e4ufig oder dauerhaft als nicht erholsam.",
		"tgt": "If you suffer from these issues, you're in good company: According to the Robert Koch Institute, around a quarter of adults suffer from sleep disorders, and more than ten percent find that they often or always wake up not feeling refreshed."
	},
	{
		"src": "Wie \u00e4u\u00dfern sich Schlafprobleme oder Schlafst\u00f6rungen?",
		"tgt": "How do sleep problems or sleep disorders manifest themselves?"
	},
	{
		"src": "Es gibt mehrere Formen von Schlafst\u00f6rungen, und es k\u00f6nnen ihnen vielf\u00e4ltige Ursachen zugrunde liegen, betont Hans-G\u00fcnter Wee\u00df, Vorstandsmitglied der Deutschen Gesellschaft f\u00fcr Schlafforschung und Schlafmedizin.",
		"tgt": "There are various forms of sleep disorders, and they can have many causes, emphasises Hans-G\u00fcnter Wee\u00df, President of the German Association for Sleep Research and Sleep Medicine."
	},
	{
		"src": "Was man landl\u00e4ufig darunter versteht, ist aber die Insomnie, also eine Ein- und Durchschlafst\u00f6rung.",
		"tgt": "What people generally understand by sleep disorders is insomnia: a problem with falling asleep and sleeping through the night."
	},
	{
		"src": "Gerade das Durchschlafen empfinden viele Menschen als unbefriedigend oder unzureichend, sagt Jens Wagenknecht, Vorstandsmitglied im Deutschen Haus\u00e4rzteverband mit Praxis im nieders\u00e4chsischen Varel.",
		"tgt": "Many people feel that their sleep throughout the night is unsatisfactory or inadequate, says Jens Wagenknecht, Member of the Board of the German Association of General Practicioners, who practices in Varel in Lower Saxony."
	},
	{
		"src": "Was steckt hinter Schlafst\u00f6rungen?",
		"tgt": "What is behind sleep disorders?"
	},
	{
		"src": "Die Ursachen von Schlafst\u00f6rungen sind komplex.",
		"tgt": "The causes of sleep disorders are complex."
	},
	{
		"src": "Dahinter k\u00f6nnen organische, psychische oder verhaltensbedingte Faktoren, aber auch Medikamente stecken.",
		"tgt": "Biological, psychological or behavioural factors can be to blame, along with medication."
	},
	{
		"src": "Nicht selten ist die Schlafst\u00f6rung Ausdruck einer anderen Erkrankung.",
		"tgt": "A sleep disorder is often a reflection of another illness."
	},
	{
		"src": "\"Sehr fr\u00fches Aufwachen ist vor allem bei einer Depression h\u00e4ufig\", sagt Wee\u00df.",
		"tgt": "\"Waking up very early is common with depression, in particular,\" says Wee\u00df."
	},
	{
		"src": "Und es kann sein, dass verschiedene Faktoren einander bedingen.",
		"tgt": "And it can be the case that several factors have an impact on each other."
	},
	{
		"src": "Wer zum Beispiel einen Bandscheibenvorfall hat, kann schlecht liegen, wacht alle zwei bis drei Stunden auf und f\u00e4ngt wom\u00f6glich an, \u00fcber Alltagsprobleme und -sorgen zu gr\u00fcbeln, gibt Wee\u00df ein Beispiel.",
		"tgt": "If you have a slipped disk, for example, you might find it hard to lie down, wake up every couple of hours, and start to grumble about everyday problems and worries, suggests Wee\u00df as an example."
	},
	{
		"src": "Das f\u00fchrt zu Anspannung, und Schlaf ist nicht mehr m\u00f6glich.",
		"tgt": "That causes tension, and it is impossible to sleep."
	},
	{
		"src": "Ab wann sollte man mit Schlafst\u00f6rungen zum Arzt?",
		"tgt": "When should you see your doctor about sleep disorders?"
	},
	{
		"src": "Wer \u00fcber einen Zeitraum von einem Monat in mindestens drei N\u00e4chten pro Woche nicht gut schl\u00e4ft und am Tag beeintr\u00e4chtigt ist, sollte zum Arzt gehen, r\u00e4t Wee\u00df.",
		"tgt": "If, over the course of a month, you sleep poorly for at least three nights a week, and find that this impacts you during the day, you should see a doctor, advises Wee\u00df."
	},
	{
		"src": "Die Beeintr\u00e4chtigung kann ganz unterschiedlich aussehen: Man ist abgeschlagen, m\u00fcde, unausgeschlafen, hat Schwierigkeiten mit der Aufmerksamkeit und der Konzentration, ist leicht reizbar, hat Stimmungsschwankungen oder k\u00f6rperliche Beschwerden wie Magen- oder Kopfschmerzen.",
		"tgt": "They can impact in various different ways: You could be exhausted, tired, poorly rested, suffer from difficulties concentrating and staying alert, be irritable, have mood swings or physical complains such as stomach ache or headaches."
	},
	{
		"src": "Um die Schlafst\u00f6rung zu lindern, ist es wichtig, deren Ursachen herauszufinden.",
		"tgt": "To be able to treat a sleep disorder, it is important to work out what is causing it."
	},
	{
		"src": "Als Behandlungsoptionen kommen unter anderem Verhaltens\u00e4nderungen, eine kognitive Verhaltenstherapie oder auch Medikamente - klassische Schlaftabletten nur im Ausnahmefall und h\u00f6chstens f\u00fcr zwei Wochen - infrage.",
		"tgt": "Behaviour changes, cognitive behavioural therapy or medication - with traditional sleeping tablets only being used in exceptional circumstances and for a maximum of two weeks - are all options for treatment."
	},
	{
		"src": "Niedergelassene Schlafmediziner gibt es in Deutschland kaum, betont Prof. Ingo Fietze, Leiter des interdisziplin\u00e4ren Schlafmedizinischen Zentrums der Charit\u00e9 Universit\u00e4tsmedizin Berlin.",
		"tgt": "There are hardly any registered sleep doctors in Germany, emphasises Prof. Ingo Fietze, Head of the Interdisciplinary Centre for Sleep Medicine at the Charit\u00e9 University Medicine Centre in Berlin."
	},
	{
		"src": "Deshalb sollte man sich bei Schlafproblemen zun\u00e4chst an den Hausarzt wenden, r\u00e4t Wee\u00df.",
		"tgt": "As a result, you should first turn to your GP if you're suffering with a sleep disorder, recommends Wee\u00df."
	},
	{
		"src": "Der kann mit Untersuchungen abkl\u00e4ren, ob die Probleme eine k\u00f6rperliche Ursache haben.",
		"tgt": "Your doctor will examine you to see if the problems have a physical cause."
	},
	{
		"src": "Wer sollte ins Schlaflabor, und was passiert da?",
		"tgt": "Who should go to a sleep lab, and what happens there?"
	},
	{
		"src": "Zur Untersuchung im Schlaflabor raten Mediziner zum Beispiel bei Schnarchen mit Atemaussetzern, bei krankhafter Tagesm\u00fcdigkeit, bei Schlafwandlern oder wenn man die Ursache einer Durchschlafst\u00f6rung nicht findet, erkl\u00e4rt Fietze.",
		"tgt": "Doctors recommend an examination in a sleep lab for patients whose snoring disrupts their breathing, for people who feel abnormally sleepy during the day, for sleepwalkers, or if the cause of a sleep disorder cannot be pinpointed, explains Fietze."
	},
	{
		"src": "Auf die Untersuchung vorbereiten muss man sich eigentlich nicht.",
		"tgt": "You don't have to prepare for the examination at all."
	},
	{
		"src": "Man sollte den Tag normal verbringen.",
		"tgt": "You should spend the day normally."
	},
	{
		"src": "\"Nur bitte keinen Mittagsschlaf machen\", sagt Fietze.",
		"tgt": "\"Just - please don't take an afternoon nap,\" says Fietze."
	},
	{
		"src": "Nach dem Verkabeln geht man zu seiner normalen Zeit ins Bett.",
		"tgt": "After being cabled up, you head to bed at your normal time."
	},
	{
		"src": "Neben den Elektroden am K\u00f6rper tr\u00e4gt man eine Nasenbrille, einen Brustgurt und einen F\u00fchler am Finger.",
		"tgt": "In addition to the electrodes on the body, you wear a nasal cannula, a belt across your chest and a sensor on your finger."
	},
	{
		"src": "Zudem zeichnet eine Kamera an der Decke den Schlafenden auf.",
		"tgt": "In addition, a camera mounted on the ceiling records the sleeper."
	},
	{
		"src": "Wie k\u00f6nnen Betroffene die Probleme in den Griff kriegen?",
		"tgt": "How can those affected get a grip on the problems they are experiencing?"
	},
	{
		"src": "Es gibt ziemlich viele Stellschrauben, an denen man f\u00fcr einen besseren Schlaf ansetzen kann.",
		"tgt": "There are a fair few areas that can be adjusted to encourage a better night's sleep."
	},
	{
		"src": "Wee\u00df z\u00e4hlt auf: Regelm\u00e4\u00dfige Schlafens- und Aufstehzeiten, nicht zu lange im Bett liegen, am Tag nicht schlafen, nicht fernsehen zum Einschlafen, Alkohol meiden und nachts nicht auf die Uhr schauen - dann beginnt man n\u00e4mlich sofort zu rechnen, und das ist ganz und gar nicht f\u00f6rderlich.",
		"tgt": "Wee\u00df lists them: going to bed and getting up a regular times, not staying in bed too long, not sleeping during the day, not watching television to get to sleep, avoiding alcohol, and not looking at the clock during the night - because then you start working out times straight away, and that's not helpful at all."
	},
	{
		"src": "Was das Dschungelcamp mit fehlenden Medaillen im Schwimmen zu hat",
		"tgt": "What the jungle camp has got to do with missing swimming medals"
	},
	{
		"src": "Der ehemalige deutsche Schwimmer Markus Deibler hat sich per Facebook zum entt\u00e4uschenden Abschneiden des DSV-Teams bei Olympis ge\u00e4u\u00dfert.",
		"tgt": "Former German swimmer Markus Deibler has posted on Facebook about the disappointing performance of the DSV team at the Olympics."
	},
	{
		"src": "Im Dezember 2014 hatte er bei den Kurzbahnweltmeisterschaften in Doha erstmals Gold geholt und stellte dabei gleichzeitig seinen ersten Weltrekord auf.",
		"tgt": "In December 2014 he got his first gold medal at the Short Course Swimming Championships in Doha, while setting his first world record."
	},
	{
		"src": "Nun hat sich der ehemalige DSV-Athlet Markus Deibler via Facebook sch\u00fctzende vor seine in der Kritik stehenden Ex-Teamkollegen gestellt.",
		"tgt": "Now the former DSV athlete Markus Deibler has come forward on Facebook to defend his ex-teammates from criticism."
	},
	{
		"src": "\"In einem Land, in dem ein Olympiasieger 20.000\u20ac Pr\u00e4mie bekommt und ein Dschungelk\u00f6nig 150.000\u20ac sollte sich niemand \u00fcber fehlende Medaillen wundern\", schrieb der 26-J\u00e4hrige in der Nacht zu Freitag auf seiner Facebook-Seite.",
		"tgt": "\"In a country in which an Olympic champion is awarded 20,000 euros and the King of the Jungle gets 150,000 euros, nobody should wonder why medals aren't being won,\" the 26-year-old wrote on Thursday night on his Facebook page."
	},
	{
		"src": "Das F\u00f6rdersystem im Schwimmsport sei schlecht, die Dopingkontrollen hingegen sehr gut.",
		"tgt": "The remuneration system in swimming is poor, but doping tests, on the other hand, are very good, he says."
	},
	{
		"src": "Damit k\u00f6nnen wir nicht mit L\u00e4ndern konkurrieren, die sehr viel f\u00f6rdern und beim Thema Doping nicht so genau hinsehen oder es sogar betreiben.",
		"tgt": "This means that we cannot compete with countries who pay a lot and that don't pay as much attention to doping, or even encourage it."
	},
	{
		"src": "\"Ich sage nicht, dass hier die Kontrollen eingestellt werden sollen\", erkl\u00e4rte er weiter.",
		"tgt": "\"I'm not saying that we should stop our tests,\" he went on to explain."
	},
	{
		"src": "Wollte er ein Comeback starten, m\u00fcsste Deibler bereits neun Monate vor seinem ersten Start der Nationalen Anti-Doping-Agentur Deutschland (NADA) gemeldet sein.",
		"tgt": "If he wanted to make a comeback, Deibler would have to register with the National Anti-Doping Agency for Germany (NADA) nine months before he started."
	},
	{
		"src": "Genau so sollte man es auch mit L\u00e4ndern halten.",
		"tgt": "This is exactly how it should be with countries."
	},
	{
		"src": "\"Wer nicht eine gewisse Zeit vor WM/OS von unabh\u00e4ngigen Kontrolleuren der WADA/FINA kontrolliert werden kann, darf nicht teilnehmen\", fordert der Wahl-Hamburger, der mittlerweile eine Eisdiele betreibt.",
		"tgt": "\"If you don't submit to WADA/FINA checks a particular amount of time before the World Championships/Olympics, then you shouldn't be able to take part,\" the Hamburg resident stated, who now runs an ice-cream parlour."
	},
	{
		"src": "Flughafen: Bande von Gep\u00e4ckdieben festgenommen",
		"tgt": "Airport: A gang of luggage thieves are arrested"
	},
	{
		"src": "Professionelle Diebe am Flughafen D\u00fcsseldorf",
		"tgt": "Professional thieves at Dusseldorf airport"
	},
	{
		"src": "Zivilfahndern der D\u00fcsseldorfer Polizei gelang am Donnerstag die Festnahme von zwei Frauen und zwei M\u00e4nnern im Alter von 50 bis 61 Jahren.",
		"tgt": "Plain clothes officers from Dusseldorf's police force managed to arrest two women and two men, aged between 50 and 61, on Thursday."
	},
	{
		"src": "Die Tatverd\u00e4chtigen hatten als Bande mehrere Taschen- und Gep\u00e4ckdiebst\u00e4hle begangen.",
		"tgt": "The suspects had worked as a group to steal several bags and items of luggage."
	},
	{
		"src": "Gegen 21.30 Uhr erkannten zivile Beamte im Bereich des Flughafens D\u00fcsseldorf eine Bande wieder, die den Polizisten aus vergangenen Diebstahlsdelikten bekannt war.",
		"tgt": "Around 9.30 p.m. civil servants in Dusseldorf Airport recognised a gang known to the police from previous thefts."
	},
	{
		"src": "Die zwei Frauen und zwei M\u00e4nner hatten seit Mitte Juli dieses Jahres mehrere Delikte begangen und waren dabei gemeinschaftlich, arbeitsteilig und besonders professionell vorgegangen.",
		"tgt": "The two men and two women had committed multiple crimes since mid-July, and had committed the offences as a group, dividing up their work in a particularly professional way."
	},
	{
		"src": "Die Spezialisten des Kriminalkommissariats 34 k\u00f6nnen den Dieben, die eigens zur Begehung von Straftaten nach Deutschland eingereist waren, vier Taten nachweisen.",
		"tgt": "The specialists from the 34th police inspectorate were able to prove that the thieves, who had travelled to Germany to commit the crimes, had committed four crimes."
	},
	{
		"src": "Dabei hatten sie insgesamt \u00fcber 15.000 Euro erbeutet.",
		"tgt": "They had made more than 15,000 euros as a result."
	},
	{
		"src": "Altbauten, ein paar Lindenb\u00e4umchen, zwischendurch noch ein Rest Kopfsteinpflaster: Die Rigaer Stra\u00dfe in Berlin-Friedrichshain wirkt auf den ersten Blick nicht so, doch die Polizei z\u00e4hlt sie zu den \"Gef\u00e4hrlichen Orten\" der Stadt.",
		"tgt": "Old buildings, a couple of little linden trees, and a few cobblestones among them: at first glance, Berlin-Friedrichshain's Rigaer Stra\u00dfe doesn't look as if it's one of the streets that the police consider to be among the most dangerous in the city."
	},
	{
		"src": "Geht man die Stra\u00dfe von Osten nach Westen entlang, kommt man an Spielpl\u00e4tzen, einem frischgestrichenen Kindergarten und einem Bioladen vorbei.",
		"tgt": "If you walk along the street from east to west, you come across playgrounds, a freshly painted kindergarten and a health-food shop."
	},
	{
		"src": "An die Fassade eines grauen Hauses hat jemand \"h\u00e4sslich!\" gespr\u00fcht.",
		"tgt": "Someone has spraypainted \"horrid!\" on the facade of a house."
	},
	{
		"src": "Gegen\u00fcber von einem Lidl, der auch bald abgerissen werden soll, wird schon gebaut: Bis 2017 soll hier ein Haus mit hohen Fenstern und 133 neuen Mietwohnungen entstehen.",
		"tgt": "Opposite a Lidl, due to be pulled down soon, construction is already underway: by 2017, a building with large windows and 133 new apartments to rend is expected to be constructed."
	},
	{
		"src": "Artikel \u00fcber diesen \"trendigen Stadtteil\", wie die zust\u00e4ndige Immobilienfirma Friedrichshain nennt, werden in den letzten Wochen allerdings bevorzugt mit brennenden Autos bebildert.",
		"tgt": "Articles on this \"trendy district\", as the property company responsible has dubbed Friedrichshain, have been illustrated with pictures of burning cars over the past few weeks."
	},
	{
		"src": "Grund ist das Haus mit der Nummer 94: Einst war es besetzt, mittlerweile haben die Bewohner Mietvertr\u00e4ge, im Erdgeschoss sind jedoch noch R\u00e4ume besetzt und werden f\u00fcr Veranstaltungen genutzt.",
		"tgt": "The reason for this is house 94: At first, it was occupied by squatters, then the inhabitants had rental contracts, but some rooms on the ground floor are still occupied by squatters and used for events."
	},
	{
		"src": "Besonders der Berliner Innensenator Henkel hatte sich seit Anfang des Jahres mehrfach f\u00fcr ein hartes Vorgehen der Polizei gegen das Projekt ausgesprochen, die Gegend als \"No-Go-Zone\" f\u00fcr Polizisten und die 94 als Ausgangspunkt autonomer Gewalt bezeichnet.",
		"tgt": "Berlin's Senator of the Interior Henkel had called multiple times since the start of the year for the police to take a hard line against the project that has made the area a \"no-go zone\" for police and singled out 94 as the starting point for autonomous violence."
	},
	{
		"src": "Nachdem am 22. Juni die R\u00e4ume im Erdgeschoss, die Kadterschmiede, mit 300 Polizeibeamten ger\u00e4umt worden waren, patrouillierte die Polizei drei Wochen lang offiziellen Aussagen zufolge mit 30 bis 40 Beamten und drei Mannschaftswagen vor Ort, sperrte Teile der Stra\u00dfe und hielt Besucher davon ab, das Haus mit der Nummer 94 zu betreten.",
		"tgt": "After the rooms on the ground floor, the Kadterschmiede, were cleared on 22 June by 300 police officers, the police patrolled the area for three weeks, according to official statements, with 30 to 40 officers and three vans, closing parts of the street and preventing visitors from accessing house 94."
	},
	{
		"src": "W\u00e4hrenddessen renovierten Bauarbeiter im Auftrag der unbekannten Hausbesitzer die R\u00e4ume.",
		"tgt": "During this period, builders renovated the rooms on behalf of the unidentified owner of the house."
	},
	{
		"src": "Am 13. Juli entschied ein Berliner Verwaltungsgericht, dass die R\u00e4umung illegal gewesen war, und einen Tag sp\u00e4ter zogen Polizei und Bauarbeiter unter dem Jubel von Sympathisanten und Anwohnern ab.",
		"tgt": "On 13 July Berlin's Administrative Court ruled that the clearing was illegal, and, one day later, police and builders left the site, to the cheers of supporters and residents."
	},
	{
		"src": "An diesem Sommernachmittag wirkt die Stra\u00dfe friedlich: Eltern gehen mit Kindern spazieren, Leute sitzen auf dem B\u00fcrgersteig vor den H\u00e4usern in der Sonne, andere unterhalten sich vorm Sp\u00e4ti.",
		"tgt": "On this summer afternoon, the street seemed peaceful: parents were out walking with their children, people were sitting on their houses' steps in the sunshine, other people were chatting in front of the off-licence."
	},
	{
		"src": "In unmittelbarer N\u00e4he der Hausprojekte liegen eine Grundschule und Kinderg\u00e4rten.",
		"tgt": "Near the house project there is a primary school and a kindergarten."
	},
	{
		"src": "Linke Gewalt ist nicht die Hauptsorge vieler Anwohner: Kerstin Neugebauer, die seit 1999 im Kiez wohnt, und Jana*, die hier drei Kinder gro\u00dfzieht, sind vor allem von der Polizeipr\u00e4senz genervt.",
		"tgt": "Far-left violence is not what worries most residents the most: Kerstin Neugebauer, who has lived in the district since 1999, and Jana*, who has brought three children up here, are mainly irritated by the police presence."
	},
	{
		"src": "Mit den Bewohnern der Hausprojekte teilen sie die Sorge vor steigenden Mieten und Gentrifizierung.",
		"tgt": "They share the inhabitants of the housing project's fears of rising rents and gentrification."
	},
	{
		"src": "Es klingt nicht nach einem Kiez, der sich mehrheitlich Polizeischutz vor vandalierenden Linken herbeiw\u00fcnschte.",
		"tgt": "It doesn't sound like a district that wants more police protection against left-wing vandalism."
	},
	{
		"src": "Der Graben, den der Berliner Innensenator und die Polizei zwischen Hausbesetzern und ihren Nachbarn aufmachen, existiert so offenbar nicht.",
		"tgt": "The schisms that Berlin's Senator for the Interior and the police believe to have opened up between the squatters in the house and their neighbours do not exist."
	},
	{
		"src": "Friedrichshain im Osten Berlins war eigentlich ein traditionelles Arbeiterviertel, das auch heute im Vergleich zum Rest der Stadt ein niedriges Durchschnittseinkommen und hohes Armutsrisiko hat.",
		"tgt": "Friedrichshain, in the east of Berlin, was traditionally a working-class neighbourhood. Even today, it has a lower average income and a higher risk of poverty than the rest of the city."
	},
	{
		"src": "Auch Hausbesetzungen und die daraus geborenen Wohnprojekte geh\u00f6ren schon lange zum Kiez: 1990 wurden zahlreiche H\u00e4user in der ehemaligen DDR besetzt, darunter nahezu die gesamte Mainzer Stra\u00dfe ganz in der N\u00e4he der Rigaer.",
		"tgt": "Squatters in houses and the residential projects they spawn are nothing new in the district: in 1990 numerous houses in the then-GDR were full of squatters, including almost all of Mainzer Stra\u00dfer, near Rigauer."
	},
	{
		"src": "W\u00e4hrend die Mainzer unter gro\u00dfem Polizeiaufgebot in einer regelrechten Stra\u00dfenschlacht ger\u00e4umt worden war, wurden viele der Projekte in der Rigaer legalisiert und werden teils heute noch von den Leuten bewohnt, die sie vor 26 Jahren besetzt hatten.",
		"tgt": "While those on Mainzerstra\u00dfe were cleared out during a real street battle with a large police deployment, many of the projects in Rigauer were legalised, and are to a certain extent still inhabited by the people who first squatted there 26 years ago."
	},
	{
		"src": "Gleichzeitig ist der Stadtteil in den letzten Jahren zunehmend zum Magneten f\u00fcr Touristen und Wahlberliner aus aller Welt geworden: Mit ihnen teilen sich nun Anwohner aus DDR-Zeiten und ehemalige Hausbesetzer ihren Kiez.",
		"tgt": "At the same time, the district has become more and more of a magnet for tourists and Berlin residents who come from all over the world: residents from GDR times and former squatters are now sharing their district with them."
	},
	{
		"src": "Das macht sich auch bei den Mieten bemerkbar, die seit 2009 bei Neuvermietungen um fast 60 Prozent gestiegen sind.",
		"tgt": "This can be felt in the rents, which have climbed by almost 60 percent since 2009."
	},
	{
		"src": "Viele der Neubauten in der Rigaer werden als Symbole f\u00fcr diese Entwicklung angegriffen: Man erkennt sie an eingeworfenen Scheiben oder frisch gestrichenen Fassaden, die mit Farbbeuteln beworfen wurden.",
		"tgt": "Many of the new buildings in Rigauer are seen as symbols of this development: this is clear from their broken windows or freshly painted facades splattered by paint bombs."
	},
	{
		"src": "Keine andere Stra\u00dfe wurde dieses Jahr so oft zusammen mit den Worten \"linksautonome Gewalt\" erw\u00e4hnt.",
		"tgt": "No other street has been mentioned so often this year in connection with \"autonomous left-wing violence\"."
	},
	{
		"src": "Ein Grund daf\u00fcr, dass nicht alle Nachbarn das als Problem ansehen, k\u00f6nnte sein, dass sie von der Kriminalit\u00e4t nicht unbedingt betroffen sind: Straftaten wie K\u00f6rperverletzung richten sich Statistiken zufolge fast ausschlie\u00dflich gegen Polizisten.",
		"tgt": "One reason for not all neighbours seeing this as a problem could be that they are not directly affected by crime: according to statistics, almost all crimes such as bodily harm are directed against the police."
	},
	{
		"src": "Den gr\u00f6\u00dften Teil der Straftaten machen Sachbesch\u00e4digungen aus, die tendenziell eher die Neubauten und frisch renovierte H\u00e4user treffen.",
		"tgt": "The majority of crimes are damage to property, which tend to target new buildings and recently renovated properties."
	},
	{
		"src": "F\u00fcr Kerstin Neugebauer, die seit 17 Jahren in einem Mietshaus neben der umstrittenen 94 wohnt, kann von Unsicherheit keine Rede sein.",
		"tgt": "For Kerstin Neugebauer, who has been living in a block of flats next-door to controversial number 94 for 17 years, there can be no talk of uncertainty."
	},
	{
		"src": "Was Gewalttaten angeht, ist sie beschwichtigend: Die Leute in der 94 sind ihre Nachbarn, die seien das bestimmt nicht gewesen.",
		"tgt": "She is calm about acts of violence: the people at number 94 are her neighbours, they certainly had nothing to do with it."
	},
	{
		"src": "Auch die ber\u00fchmten brennenden Autos gebe es direkt in der Rigaer schon l\u00e4nger nicht mehr.",
		"tgt": "Even the notorious burning cars have not played a role in Rigaer for a long time."
	},
	{
		"src": "F\u00fcr die studierte Architektin ist ihre Stra\u00dfe kein krimineller Brennpunkt, im Gegenteil: \"Hier hilft man einander, lebt zusammen auf der Stra\u00dfe und bekommt mehr voneinander mit, als woanders\".",
		"tgt": "The trained architect does not see her street as a crime flashpoint - quite the opposite: \"Here we help each other, live together along the street, and talk to each other more than elsewhere\"."
	},
	{
		"src": "Neugebauer ist bewusst in die Rigaer Stra\u00dfe gezogen - und geblieben.",
		"tgt": "Neugebauer chose to move to Rigauer Stra\u00dfe - and she chose to stay there."
	},
	{
		"src": "Deswegen war es ihr auch so wichtig, dass die Anwohner ihre Stra\u00dfe zur\u00fcckbekommen: Von der Polizei, der Politik und den Medien, die im Juli alle pl\u00f6tzlich die Deutungshoheit \u00fcber den Stadtteil beanspruchten.",
		"tgt": "This is also why it was so important to her that residents got their street back: back from the police, politicians and the media who suddenly started claiming how important the district was in July."
	},
	{
		"src": "Doch in den Augen von Bewohnerinnen wie Neugebauer wird die Stra\u00dfe ihnen weiterhin weggenommen: Durch gesichtslose Neubauten in ehemaligen Baul\u00fccken, die die alten Bewohner verdr\u00e4ngen.",
		"tgt": "But in the eyes of residents like Neugebauer, the street is still being taken away: by impersonal new developments in old empty sites, which drive out old residents."
	},
	{
		"src": "\"Das sind ja letztendlich Eigentumswohnungen, die f\u00fcr viele hier nicht interessant sind - hier wohnen eher Leute, die nicht so gut betucht sind\", sagt sie.",
		"tgt": "\"They are freehold flats, and most people here aren't interested in that - people here generally aren't so well-off,\" she said."
	},
	{
		"src": "\"Gewalt und Zerst\u00f6rung kann ich absolut nicht guthei\u00dfen.\"",
		"tgt": "\"I absolutely cannot condone violence and destruction.\""
	},
	{
		"src": "Aber was soll man denn machen, wenn einem nie jemand zuh\u00f6rt?",
		"tgt": "But what should you do when nobody listens to you?"
	},
	{
		"src": "Da setzt auf allen Seiten Frustration ein, auch bei der Polizei und den Bewohnern.",
		"tgt": "Then everyone gets frustrated, including the police and residents."
	},
	{
		"src": "F\u00fcr Zugezogene, die sich \u00fcber Farbbomben \u00e4rgern, hat Kerstin Neugebauer wenig Verst\u00e4ndnis: Die Hausprojekte und die linke Szene geh\u00f6rten zum Kiez.",
		"tgt": "Kerstin Neugebauer has little sympathy for people who have moved in and are irritated by paint bombs: The housing project and the left-wing scene are part of the district."
	},
	{
		"src": "Wer herzieht, sollte sich dessen bewusst sein - genau wie jemand, der in ein Kneipenviertel zieht, sich dort schlecht \u00fcber L\u00e4rm beschweren kann.",
		"tgt": "If you move here, you should be aware of that - just like someone who moves into an area full of pubs should know they can't really complain about the noise."
	},
	{
		"src": "Alle nur mit Vornamen vorgestellten Personen haben darum gebeten, nicht mit ihrem richtigen Namen genannt zu werden",
		"tgt": "All people only described using their forenames have requested that their real names are not used"
	},
	{
		"src": "Urbach: Annika Deuschle ist neue Fl\u00fcchtlingsbeauftragte",
		"tgt": "Urbach: Annika Deutscle is the new Commissioner for Refugees"
	},
	{
		"src": "Annika Deuschle ist die Ansprechpartnerin in Sachen Integration und Organisatorin.",
		"tgt": "Annika Deutschle is the contact person for integration and organisation."
	},
	{
		"src": "Au\u00dferdem ist sie Sozialarbeiterin vor Ort.",
		"tgt": "She will also work on-site as a social worker."
	},
	{
		"src": "Seit Juli ist Annika Deuschle die Fl\u00fcchtlingsbeauftragte f\u00fcr Urbach.",
		"tgt": "Annika Deuschle has been the Commissioner for Refugees for Urbach since July."
	},
	{
		"src": "Die Sozialp\u00e4dagogin unterst\u00fctzt das Team der Verwaltung um Achim Grockenberger.",
		"tgt": "The social education worker will assist the management team run by Achim Grockenberger."
	},
	{
		"src": "Sie sieht sich als Ansprechpartnerin f\u00fcr alle Akteure: Fl\u00fcchtlinge, Arbeitskreis Fl\u00fcchtlingshilfe, Verwaltung, Beh\u00f6rden und wer sonst noch mitmischt.",
		"tgt": "She views herself as a point-of-contact for all involved: refugees, people from the working group for refugees, administrators, authorities, and anyone else."
	},
	{
		"src": "Regine Kunde vom Arbeitskreis deutet an, dass die Ehrenamtlichen mehr als dankbar sind, dass Deuschle nun da ist, die eierlegende Wollmilchsau, die vor allem ein Problem hat.",
		"tgt": "Regine Kunde from the working group said that the volunteers are more than grateful that Deuschle is now available to work as a jack-of-all-trades to help anyone experiencing difficulties."
	},
	{
		"src": "So hatten einige - weniger spottend als vielmehr auf die Vielzahl an erw\u00fcnschen Aufgabengebieten abzielend - gemeint, als die Verwaltung die Stelle ausschreiben wollte.",
		"tgt": "That's what some people said when management posted the advert for the job - meaning it less in a mocking way, and more with reference to the number of tasks that were to be performed."
	},
	{
		"src": "Gesucht wurde eine Verwaltungsfachkraft mit einem Talent f\u00fcr Sprachen und Menschen, verbunden mit einer langj\u00e4hrigen Erfahrung im Bereich der Sozialarbeit, eben eine eierlegende Wollmilchsau.",
		"tgt": "They were looking for a manager with people skills and communication skills, combined with years of experience in social work - a real jack-of-all-trades."
	},
	{
		"src": "Doch Verwaltungsarbeit sei nicht ihr zentraler Bereich, meint Annika Deuschle.",
		"tgt": "However, managerial work is not how she spends most of her time, Annika Deuschle says."
	},
	{
		"src": "Vor allem gehe es um Organisation, Arbeit mit den Menschen vor Ort und auch hinter den Kulissen sowie Netzwerkt\u00e4tigkeit.",
		"tgt": "It is primarily about organisation, working on-site with people, even in the background, and networking, she says."
	},
	{
		"src": "Die 31-J\u00e4hrige ist seit rund sechs Wochen dabei.",
		"tgt": "The 31-year-old has been in post for around six weeks."
	},
	{
		"src": "Sie hat eine 50-Prozent-Stelle auf drei Jahre befristet.",
		"tgt": "She has taken the 50% job for a fixed term of three years."
	},
	{
		"src": "\"Es war h\u00f6chste Zeit\", sagt Regine Kunde, dass Annika Deuschle ehren- und hauptamtliche Akteure unterst\u00fctzt.",
		"tgt": "It was high time,\" Regine Kunde said, that Annika Deuschle offered support to voluntary and full-time workers."
	},
	{
		"src": "Es gibt gro\u00dfe und kleine Probleme, organisatorische, menschliche und Verst\u00e4ndigungsprobleme.",
		"tgt": "There are major problems, minor problems, organisational problems, problems with people, comprehension problems."
	},
	{
		"src": "Bald stehen neue Container in der Wasenstra\u00dfe",
		"tgt": "New containers will soon be located in Wasenstra\u00dfe"
	},
	{
		"src": "Ein schwerwiegendes Problem ist es seit einiger Zeit, Wohnungen f\u00fcr die Anschlussfl\u00fcchtlinge zu finden, die anerkannt worden sind.",
		"tgt": "For a while, one major problem has been finding homes subsequently for refugees that have been given certified status."
	},
	{
		"src": "F\u00fcr die Anschlussunterbringung sind die Kommunen zust\u00e4ndig.",
		"tgt": "Communes themselves are responsible for subsequent accommodation."
	},
	{
		"src": "Sie m\u00fcssen die Fl\u00fcchtlinge in eigenen oder angemieteten Wohnr\u00e4umen unterbringen.",
		"tgt": "They have to house the refugees in their own properties or in rented properties."
	},
	{
		"src": "Die Kosten f\u00fcr den Bau, die Miete oder die Renovierung dieser Unterk\u00fcnfte m\u00fcssen die Kommunen selbst tragen.",
		"tgt": "Communes themselves have to bear the costs for constructing, renting or renovating this accommodation."
	},
	{
		"src": "Die Verantwortung wechselt vom Landratsamt auf Kommune und Jobcenter.",
		"tgt": "Responsibility switches from district administration to communes and job centres."
	},
	{
		"src": "Problem: Es gibt freie Objekte, doch nicht jeder Vermieter will seine Wohnung anbieten.",
		"tgt": "The problem: Properties are free, but not every landlord is prepared to let."
	},
	{
		"src": "Die Suche gestaltet sich seit einiger Zeit als sehr schwierig.",
		"tgt": "The search has been very difficult for a while."
	},
	{
		"src": "De facto findet die Verwaltung keine privaten Wohnungen.",
		"tgt": "De facto, the administration cannot find any private homes."
	},
	{
		"src": "Es funktioniere bisher nicht, dabei sei man auf Privatwohnungen angewiesen, so Deuschle.",
		"tgt": "According to Deuschle, being reliant on private homes has not worked."
	},
	{
		"src": "Daher m\u00fcssen gemeindliche Wohnungen ert\u00fcchtigt werden, wie es so sch\u00f6n hei\u00dft.",
		"tgt": "This is why the commune's homes need to be beefed up, as it is so neatly put."
	},
	{
		"src": "Also werden bald neue Container in der Wasenstra\u00dfe aufgestellt.",
		"tgt": "Consequently new containers will soon be located in Wasenstra\u00dfe."
	},
	{
		"src": "Doch nur mit Wohnungen ist es nicht getan.",
		"tgt": "But homes alone will not do the trick."
	},
	{
		"src": "Perspektive ist das Stichwort, sind sich Regine Kunde und Annika Deuschle einig.",
		"tgt": "Perspective is the key word, and Regine Kunde and Annika Deuschle agree on that score."
	},
	{
		"src": "Neben einer festen Bleibe sind es Praktikumspl\u00e4tze, Ausbildungsstellen, Schulpl\u00e4tze, Ein-Euro-Jobs und Aushilfst\u00e4tigkeiten f\u00fcr Fl\u00fcchtlinge und Migranten, die gefundnen oder eingerichtet werden m\u00fcssen.",
		"tgt": "In addition to a fixed abode, internships, apprenticeships, school places, \"one-euro\" traineeship jobs and temporary jobs need to be found or set up for refugees and migrants."
	},
	{
		"src": "\"Mehr Pl\u00e4tze w\u00e4ren gut\", berichtet Regine Kunde.",
		"tgt": "\"More jobs would be good,\" reports Regine Kunde."
	},
	{
		"src": "Viele arbeiten im Bauhof oder helfen Hausmeistern, erledigen gemeinn\u00fctzige Arbeit - und das motiviert und sehr ordentlich, wie Annika Deuschle berichtet.",
		"tgt": "Many people work in builder's yards or help caretakers, or do voluntary work - and that provides motivation in a very orderly way, as Annika Deuschle reports."
	},
	{
		"src": "Sie hofft, dass die Arbeit f\u00fcr das Gemeinwesen zu einer positiven Au\u00dfenwirkung f\u00fchrt.",
		"tgt": "She hopes that working for the community leads to a positive public perception."
	},
	{
		"src": "Das sei \"keine Besch\u00e4ftigungstherapie\".",
		"tgt": "This is not \"employment therapy\"."
	},
	{
		"src": "T\u00e4tigkeit meint aber nicht nur Arbeit.",
		"tgt": "Being active doesn't just mean working."
	},
	{
		"src": "Der Tag brauche eine feste Struktur, sagen Deuschle und Kunde.",
		"tgt": "The day needs a fixed structure, Deuschle and Kunde say."
	},
	{
		"src": "Die Menschen m\u00fcssten ein Zugeh\u00f6rigkeitsgef\u00fchl entwickeln.",
		"tgt": "People need to develop a sense of belonging."
	},
	{
		"src": "Also brauche es Angebote wie Sport, Kontakte mit Einheimischen und vor allem Sprachkurse.",
		"tgt": "Consequently there is a need to provide sports, contact to locals, and, above all, language courses."
	},
	{
		"src": "Professionelle Kurse sind rar.",
		"tgt": "Professional courses are rare."
	},
	{
		"src": "Also springen auch hier Verwaltung und Ehrenamtliche ein.",
		"tgt": "There is where the administration and volunteers can get involved."
	},
	{
		"src": "Es sei zentral, dass die Fl\u00fcchtlinge das Gef\u00fchl bekommen, sie seien in Deutschland erw\u00fcnscht und willkommen.",
		"tgt": "She says it is key that refugees feel as if they are wanted and welcome in Germany."
	},
	{
		"src": "Die lange Dauer der Verfahren sei ein Problem.",
		"tgt": "The length of time that processes take is a problem."
	},
	{
		"src": "Sie m\u00fcssen den Fl\u00fcchtlingen erkl\u00e4ren, dass es eben dauert und sie die Zeit sinnvoll \u00fcberbr\u00fccken k\u00f6nnen, beispielsweise mit Sprachkursen.",
		"tgt": "They have to explain to refugees that it will take that long, and that the time can be filled productively - for example, with language courses."
	},
	{
		"src": "Wer irgendwann das Gef\u00fchl entwickle, er k\u00f6nne in Urbach niemanden helfen, d\u00fcrfe nicht arbeiten und sei unn\u00fctz, der werde sich nie integrieren.",
		"tgt": "If someone feels that they can't help anyone in Urbach, that they aren't allowed to work, and that they are useless, they'll never integrate."
	},
	{
		"src": "Die deutliche Mehrheit sei motiviert.",
		"tgt": "The clear majority are motivated."
	},
	{
		"src": "Problemf\u00e4lle gibt es aber auch, sagt Kunde ehrlich, \"Leute, bei denen gar nichts geht\". Die Arbeit von Deuschle und Kunde sei daher immer auch, andere zu motivieren.",
		"tgt": "But there are also problem cases, Kunde says honestly, \"people for whom nothing works\". As a result, Deuschle and Kunde's work will always be to motivate others."
	},
	{
		"src": "Das alles sei schon eine \"Mammutaufgabe\".",
		"tgt": "All told, this is \"a mammoth task\"."
	},
	{
		"src": "Eine schwierige Frage: Haben die beiden nach den j\u00fcngsten Vorkommnissen Angst vor Radikalisierung, auch in einer kleinen Gemeinde wie Urbach?",
		"tgt": "A tricky question: After recent events, are the two women worried about radicalisation, even in a small commune like Urbach?"
	},
	{
		"src": "\"Nein\", sagt Regine Kunde ganz deutlich, \"was mancher naiv nennen mag\". Ein Restrisiko k\u00f6nne und wolle sie aber nicht ausschlie\u00dfen.",
		"tgt": "\"No,\" Regine Kunde said clearly, \"which some people might call naive\". She could not and did not want to ignore the chance of a residual risk remaining."
	},
	{
		"src": "Sensibilisiert seien die Helfer aber schon.",
		"tgt": "However, volunteers are already aware of this."
	},
	{
		"src": "Diese Vorf\u00e4lle seien auch Thema bei den Fl\u00fcchtlingen.",
		"tgt": "These issues are already discussed by the refugees."
	},
	{
		"src": "Die h\u00e4tten die Angst, dass die Attent\u00e4ter sie komplett in Verruf bringen.",
		"tgt": "They were afraid that the attackers would bring them into total disrepute."
	},
	{
		"src": "\"Sie wollen zeigen, dass sie damit nichts zu tun haben\", sagt Regine Kunde.",
		"tgt": "\"They want to show they have nothing to do with it,\" Regine Kunde said."
	},
	{
		"src": "Viele w\u00fcrden gerne in Urbach bleiben.",
		"tgt": "Many of them would like to stay in Urbach."
	},
	{
		"src": "Also m\u00fcssen Haupt- und Ehrenamtliche vor Ort und in der Region nach T\u00e4tigkeiten Ausschau halten.",
		"tgt": "So full-time and volunteer staff have to keep an eye open for jobs in the town and across the region."
	},
	{
		"src": "Dabei haben sie immer im Hintergrund, dass bald ein neuer Sto\u00df an Fl\u00fcchtlingen und Migranten nach Urbach kommen k\u00f6nnte.",
		"tgt": "But they always have in the back of their mind that a new group of refugees and migrants could soon be arriving in Urbach."
	},
	{
		"src": "Braucht Deutschland eine Obergrenze?",
		"tgt": "Does Germany need a cap?"
	},
	{
		"src": "Diese Frage klar zu beantworten, scheut sich die Politik.",
		"tgt": "Politicians shy away from answering this question."
	},
	{
		"src": "Eigentlich ist es unfair, sie Helfern vor Ort zu stellen.",
		"tgt": "It is unfair to show them volunteers on site."
	},
	{
		"src": "\"In Urbach sind wir noch nicht da angekommen, wo wir hinm\u00f6chten\", sagt Annika Deuschle.",
		"tgt": "\"In Urbach we've not got to where we wanted to be quite yet,\" said Annika Deuschle."
	},
	{
		"src": "Keine neuen Fl\u00fcchtlinge, das w\u00fcrde die Lage entspannen.",
		"tgt": "The situation would ease a bit if they did not receive any new refugees."
	},
	{
		"src": "Regine Kunde macht ebenfalls deutlich, dass die Urbacher auch schon damit ausgelastet sind, die bisherigen Menschen vern\u00fcnftig zu integrieren.",
		"tgt": "Regine Kunde also makes clear that the residents of Urbach have their hands full with integrating the refugees who have arrived to date."
	},
	{
		"src": "Das sind zurzeit rund 100 Personen, \u00fcberwiegend junge M\u00e4nner.",
		"tgt": "Currently they amount to around 100 people, predominantly young men."
	},
	{
		"src": "Doch wenn Menschen in Not sind, m\u00fcsse man ihnen helfen, sind sich beide Frauen einig.",
		"tgt": "But when people are in need, you've got to help them - and both women agree on that."
	},
	{
		"src": "Die politische Weltlage ist so kompliziert, da gibt es keine einfachen Antworten.",
		"tgt": "The political situation is so complicated that there are no easy answers to be found there."
	},
	{
		"src": "Schorndorf: Einbrecher mit Hubschrauber gesucht",
		"tgt": "Schorndorf: Search for intruders made by helicopter"
	},
	{
		"src": "Der Polizeihubschrauber flog etwa eine Stunde lang verschiedene Gebiete ab - erfolglos.",
		"tgt": "The police helicopter flew above various areas for about an hour - without success."
	},
	{
		"src": "Zwei unbekannte M\u00e4nner sind am Freitagmorgen gegen 8.50 Uhr gewaltsam in eine Wohnung in einem Mehrfamilienhaus im Lindenweg eingedrungen.",
		"tgt": "Two unknown men broke into an apartment in an apartment building in Lindenweg on Friday morning at around 8.50am."
	},
	{
		"src": "Der Bewohner \u00fcberraschte die beiden und schlug die Unholde in die Flucht.",
		"tgt": "The residents surprised the two men, who fled."
	},
	{
		"src": "Die beiden M\u00e4nner waren etwa 1,65 bis 1,70 Meter gro\u00df, wohl maskiert, trugen beide Bluejeans und schwarze Kapuzenpullis.",
		"tgt": "The two men were between 1.65m and 1.70m tall, probably wearing masks, both wearing blue jeans and black hooded tops."
	},
	{
		"src": "Sie fl\u00fcchteten Richtung Innenstadt.",
		"tgt": "They were heading towards the centre of town."
	},
	{
		"src": "Zur Fahndung setzte die Polizei mehrere Streifenbesatzungen sowie einen Polizeihubschrauber ein.",
		"tgt": "The police launched several strip patrols and a police helicopter to try and find them."
	},
	{
		"src": "Die Fahndung verlief ohne Erfolg.",
		"tgt": "Without success."
	},
	{
		"src": "Eventuell fielen die Unbekannten vor der Tat nahe der Wohnung beziehungsweise bei ihrer Flucht auf.",
		"tgt": "It may be the case that the unknown assailants were recognised near the apartment or during their escape."
	},
	{
		"src": "Baden-W\u00fcrttemberg: Polizei ermittelt nach Rocker-Angriff auf Imbiss",
		"tgt": "Baden-W\u00fcrttemberg: Police launch investigation after bikers attack a snack bar"
	},
	{
		"src": "Nach einer Attacke auf einen Ulmer Imbiss ermittelt die Polizei gegen sechs Verd\u00e4chtige aus dem Rockermilieu wegen schweren Landfriedensbruchs.",
		"tgt": "After an attack on a snack stand in Ulm, police have launched investigations against six suspects who associate with the biker community for a serious breach of the peace."
	},
	{
		"src": "Bei Wohnungsdurchsuchungen seien Beweismittel und Rauschgift sichergestellt worden, teilte die Polizei am Freitag mit.",
		"tgt": "House searches had revealed evidence and drugs, the police revealed on Friday."
	},
	{
		"src": "Rund 20 maskierte M\u00e4nner einer rocker\u00e4hnlichen Gruppierung hatten laut Polizei im Juli Flaschen und Steine gegen die Schaufensterscheibe eines Imbisses geworfen.",
		"tgt": "According to the police, around 20 masked men from a biker-esque clan had thrown bottles and stones against the window of the snack bar."
	},
	{
		"src": "Danach sollen sie zwei G\u00e4ste angegriffen und einen leicht verletzt haben.",
		"tgt": "Afterwards, two customers were attacked, one of whom was slightly injured."
	},
	{
		"src": "Danach flohen sie.",
		"tgt": "Then they fled."
	},
	{
		"src": "Am Imbiss und am angrenzenden Geb\u00e4ude entstand ein Schaden von 10000 Euro.",
		"tgt": "Damage amounting to 10,000 euros was caused to the snack bar and the neighbouring building."
	},
	{
		"src": "Den Ermittlern zufolge geht es um einen Streit im Ulmer Rockermilieu zwischen einer kurdischen und einer t\u00fcrkischen Gang.",
		"tgt": "Investigators believe it was a dispute among Ulm's biker gangs, between a Kurdish gang and a Turkish gang."
	},
	{
		"src": "Th\u00fcringen: Zeiss Meditec der Umsatz-Milliarde n\u00e4her gekommen",
		"tgt": "Th\u00fcringen: Zeiss Meditec comes closer to reaching a billion in turnover"
	},
	{
		"src": "Eine hohe Nachfrage nach Medizintechnik in Asien hat den Umsatz von Carl Zeiss Meditec angekurbelt.",
		"tgt": "Strong demand for medical technology in Asia has boosted Carl Zeiss Meditec's turnover."
	},
	{
		"src": "In den ersten neun Monaten des im Oktober begonnenen Gesch\u00e4ftsjahres stieg der Konzernumsatz um 6,7 Prozent auf 798,6 Millionen Euro, wie das b\u00f6rsennotierte Unternehmen am Freitag in Jena mitteilte.",
		"tgt": "Over the first nine months of the business year that started in October, the company's turnover grew by 6.7 percent to 789.6 million euros, as the listed company reported on Friday in Jena."
	},
	{
		"src": "Das Asiengesch\u00e4ft wuchs \u00fcberproportional um 17,1 Prozent.",
		"tgt": "Its business in Asia grew disproportionately, by 17.1 percent."
	},
	{
		"src": "Der Gewinn vor Zinsen und Steuern erh\u00f6hte sich laut Zwischenbilanz von 89,5 Millionen Euro auf 110,5 Millionen Euro.",
		"tgt": "Profits before interest and taxes increased from 89.5 million euros to 110.5 million euros, according to the interim report."
	},
	{
		"src": "Der Jenaer Medizintechnik-Konzern will in diesem Gesch\u00e4ftsjahr die Umsatzmarke von einer Milliarde Euro \u00fcbertreffen, bekr\u00e4ftigte der Vorstand.",
		"tgt": "The Jena-based medical technology company wants to cross a turnover threshold of one billion euros this year, said its Board of Directors."
	},
	{
		"src": "Zeiss Meditec stellt Ger\u00e4te und Ausr\u00fcstungen f\u00fcr Arztpraxen und Kliniken her.",
		"tgt": "Zeiss Meditec produces devices and equipment for doctors' practices and clinics."
	},
	{
		"src": "Das Unternehmen, das zum Optik- und Elektronikkonzern Carl Zeiss (Oberkochen) geh\u00f6rt, besch\u00e4ftigt knapp 3000 Mitarbeiter.",
		"tgt": "The company is owned by the Carl Zeiss optics and electronics firm (Oberkochen), and employs just under 3000 people."
	}
]